const C: Record<string, string[]> = {"Mishneh Torah, Agents and Partners 2":["אֵין הָעַכּוּ\"ם נַעֲשֶׂה שָׁלִיחַ לְדָבָר מִן הַדְּבָרִים שֶׁבָּעוֹלָם. וְכֵן אֵין יִשְׂרָאֵל נַעֲשֶׂה שָׁלִיחַ לְעַכּוּ\"ם לְדָבָר מִן הַדְּבָרִים. שֶׁנֶּאֱמַר (במדבר יח כח) \"כֵּן תָּרִימוּ גַם אַתֶּם\" מָה אַתֶּם בְּנֵי בְּרִית אַף שְׁלוּחֲכֶם בְּנֵי בְּרִית. וְהוּא הַדִּין לְכָל הַתּוֹרָה כֻּלָּהּ. וּמַה מְשַׁלַּחֲכֶם בֶּן בְּרִית אַף בְּכָל הַתּוֹרָה כֻּלָּהּ הַמְשַׁלֵּחַ בֶּן בְּרִית:","עוֹשֶׂה אָדָם שָׁלִיחַ אִישׁ אוֹ אִשָּׁה וַאֲפִלּוּ אֵשֶׁת אִישׁ וַאֲפִלּוּ עֶבֶד וְשִׁפְחָה הוֹאִיל וְהֵן בְּנֵי דַּעַת וְיֶשְׁנָן בְּמִקְצָת מִצְוֹת נַעֲשִׂין שְׁלוּחִין לְמַשָּׂא וּמַתָּן. אֲבָל מִי שֶׁאֵינָן בְּנֵי דַּעַת וְהֵן חֵרֵשׁ שׁוֹטֶה וְקָטָן אֵינָן נַעֲשִׂין שְׁלוּחִין וְלֹא עוֹשִׂין שָׁלִיחַ. אֶחָד הַקָּטָן וְאֶחָד הַקְּטַנָּה. לְפִיכָךְ הַשּׁוֹלֵחַ בְּנוֹ קָטָן אֵצֶל הַחֶנְוָנִי וּמָדַד לוֹ בְּאִיסָר שֶׁמֶן וְנָתַן לוֹ אֶת הָאִיסָר וְאִבֵּד אֶת הַשֶּׁמֶן וְאֶת הָאִיסָר הַחֶנְוָנִי חַיָּב לְשַׁלֵּם שֶׁלֹּא שְׁלָחוֹ אֶלָּא לְהוֹדִיעוֹ וְלֹא הָיָה לוֹ לְשַׁלֵּחַ אֶלָּא עִם בֶּן דַּעַת. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְאִם פֵּרֵשׁ וְאָמַר שְׁלַח לִי עִם הַקָּטָן הֲרֵי זֶה פָּטוּר:","הָאוֹמֵר לַחֲבֵרוֹ מָנֶה שֶׁיֵּשׁ לִי בְּיָדְךָ בֵּין מִלְוֶה בֵּין פִּקָּדוֹן שְׁלָחֵהוּ לִי בְּיַד פְּלוֹנִי אֲפִלּוּ הָיָה קָטָן אִם רָצָה לְשַׁלְּחוֹ בְּיָדוֹ נִפְטָר וְאֵינוֹ חַיָּב בְּאַחֲרָיוּתוֹ. וְכֵן שְׁנַיִם שֶׁהִתְנוּ בֵּינֵיהֶם שֶׁכָּל מִי שֶׁיִּרְצֶה לִשְׁלֹחַ לַחֲבֵרוֹ מְשַׁלֵּחַ בְּיַד מִי שֶׁיִּרְצֶה הַמְשַׁלֵּחַ הֲרֵי זֶה מְשַׁלֵּחַ בְּיַד מִי שֶׁיֵּרָאֶה לוֹ שֶׁהוּא רָאוּי לְהוֹלִיךְ דָּבָר זֶה. וְאִם נִגְנַב אוֹ אָבַד בַּדֶּרֶךְ אוֹ שֶׁכָּפַר בּוֹ הַשָּׁלִיחַ הֲרֵי הַמְשַׁלֵּחַ פָּטוּר. שֶׁכָּל תְּנַאי שֶׁבַּמָּמוֹן קַיָּם:","הַשָּׁלִיחַ שֶׁקָּנָה אוֹ שֶׁמָּכַר וְהוֹדִיעַ שֶׁהוּא שָׁלִיחַ בְּדָבָר זֶה לִפְלוֹנִי אַף עַל פִּי שֶׁמָּשַׁךְ אוֹ שֶׁהִמְשִׁיךְ וְנִמְצָא שֶׁעָבַר עַל דַּעַת הַמְשַׁלֵּחַ בָּטֵל הַמִּקָּח וּמַחֲזִיר. וְאִם לֹא הוֹדִיעַ שֶׁהוּא שָׁלִיחַ נִקְנָה הַמִּקָּח וְיִהְיֶה הַדִּין בֵּינוֹ וּבֵין זֶה שֶׁשְּׁלָחוֹ:","רְאוּבֵן שֶׁקָּנָה שָׂדֶה מִשִּׁמְעוֹן וְאָמַר לוֹ לְלֵוִי קָנִיתִי אוֹתָהּ וְכָתַב שְׁטַר מֶכֶר בְּשֵׁם לֵוִי וְחָזַר רְאוּבֵן וְאָמַר לְשִׁמְעוֹן לְעַצְמִי קְנִיתִיהָ חֲזֹר וּכְתֹב שְׁטַר מֶכֶר בִּשְׁמִי. אֵין כּוֹפִין אֶת הַמּוֹכֵר לִכְתֹּב לוֹ שְׁטָר אַחֵר בְּשֵׁם רְאוּבֵן. וְאִם הִתְנָה עִמּוֹ בַּתְּחִלָּה וְאָמַר לוֹ לְעַצְמִי אֶקְנֶה וְזֶה שֶׁאֶכְתֹּב שְׁטָר בְּשֵׁם לֵוִי כְּדֵי שֶׁלֹּא יֵדְעוּ בִּי שֶׁאֲנִי הוּא הַקּוֹנֶה הֲרֵי זֶה כּוֹפֵהוּ לַחְזֹר וְלִכְתֹּב שְׁטָר אַחֵר בִּשְׁמוֹ:","הַסַּרְסוּר שָׁלִיחַ הוּא אֶלָּא שֶׁהוּא נוֹטֵל שְׂכַר שְׁלִיחוּתוֹ לְפִיכָךְ אִם שִׁנָּה דַּעַת הַבְּעָלִים מְשַׁלֵּם מַה שֶּׁהִפְסִיד. כֵּיצַד. רְאוּבֵן שֶׁנָּתַן חֵפֶץ לְשִׁמְעוֹן הַסַּרְסוּר וְאָמַר לוֹ מְכֹר לִי זֶה וְאַל תִּמְכֹּר בְּפָחוֹת מִמֵּאָה וְהָלַךְ וּמְכָרוֹ בַּחֲמִשִּׁים מְשַׁלֵּם הַחֲמִשִּׁים מִבֵּיתוֹ. מָכַר בְּמָאתַיִם הַכּל לִרְאוּבֵן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. רְאוּבֵן אוֹמֵר בְּמֵאָה אָמַרְתִּי לְךָ וְהַסַּרְסוּר אוֹמֵר בַּחֲמִשִּׁים אָמַרְתָּ לִי וְכֵן בַּחֲמִשִּׁים מָכַרְתִּי נִשְׁבָּע הַסַּרְסוּר שְׁבוּעַת הַתּוֹרָה שֶׁהֲרֵי הוֹדָה בְּמִקְצָת. וְאִם כְּבָר נָתַן לוֹ הַחֲמִשִּׁים נִשְׁבָּע שְׁבוּעַת הֶסֵּת שֶׁעָשָׂה שְׁלִיחוּתוֹ וְזוֹכֶה הַלּוֹקֵחַ. וְאִם יָדַע הַלּוֹקֵחַ שֶׁחֵפֶץ זֶה שֶׁל רְאוּבֵן הוּא וְזֶה הַמּוֹכֵר לוֹ סַרְסוּר הוּא יַחְזִיר הַחֵפֶץ לַבְּעָלִים וְיַחֲרִים עַל מִי שֶׁנָּתַן לוֹ רְשׁוּת לִמְכֹּר בַּחֲמִשִּׁים אוֹ שֶׁרָצָה בַּחֲמִשִּׁים וְחָזַר בּוֹ אַחַר שֶׁקָּנִיתִי:","כָּל סַרְסוּר שֶׁהוֹדִיעַ לַלּוֹקֵחַ שֶׁחֵפֶץ זֶה אוֹ קַרְקַע זֶה שֶׁל רְאוּבֵן וְאַחַר שֶׁקָּנָה הַלּוֹקֵחַ אָמַר רְאוּבֵן אֵינִי רוֹצֶה לִמְכֹּר בְּדָמִים אֵלּוּ מַחְזִיר הַלּוֹקֵחַ שֶׁהֲרֵי לֹא פָּסַק לוֹ דָּמִים וְאָמַר לוֹ מָכוּר לְךָ בְּכָךְ וְכָךְ. [כָּל] סַרְסוּר שֶׁאָבַד הַחֵפֶץ מִיָּדוֹ אוֹ נִגְנַב אוֹ נִשְׁבַּר חַיָּב לְשַׁלֵּם מִפְּנֵי שֶׁהוּא נוֹשֵׂא שָׂכָר:","הַלּוֹקֵחַ כֵּלִים מִבֵּית הָאֻמָּן לְשַׁגְּרָן לְבֵית חָמִיו וְאָמַר לוֹ אִם מְקַבְּלִין אוֹתָן מִמֶּנִּי אֲנִי אֶתֵּן לְךָ אֶת דְּמֵיהֶם וְאִם לָאו אֶתֵּן שָׂכָר מוּעָט וְנֶאֶנְסוּ בַּהֲלִיכָה הֲרֵי זֶה חַיָּב לְשַׁלֵּם. וְאִם נֶאֶנְסוּ בַּחֲזָרָה פָּטוּר. נְטָלָן עַל מְנָת לְמָכְרָן לַאֲחֵרִים וְאָמַר לוֹ אִם יִמָּכְרוּ בְּמָקוֹם פְּלוֹנִי אוֹ עַד זְמַן פְּלוֹנִי אֶתֵּן לְךָ דָּמִים כָּךְ וְכָךְ וְאִם לֹא יִמָּכְרוּ אַחְזִירֵם לְךָ וְנֶאֶנְסוּ בֵּין בַּהֲלִיכָה בֵּין בַּחֲזָרָה חַיָּב לְשַׁלֵּם:","כָּל שָׁלִיחַ שֶׁטָּעַן שֶׁאֵרְעוֹ אֹנֶס פְּלוֹנִי וְהִפְסִיד כָּךְ וְכָךְ הֲרֵי זֶה נִשְׁבָּע שְׁבוּעַת הַשּׁוֹמְרִין עַל טַעֲנָתוֹ וְיִפָּטֵר. וְאִם הָיָה הָאֹנֶס בְּמָקוֹם שֶׁאֶפְשָׁר לְהָבִיא עָלָיו עֵדִים אוֹ דָּבָר שֶׁהוּא גָּלוּי וְיָדוּעַ שֶׁהֲרֵי יִמְצָא עֵדִים הֲרֵי זֶה צָרִיךְ לְהָבִיא רְאָיָה עַל טַעֲנָתוֹ וְאִם לֹא הֵבִיא עֵדִים אֵינוֹ נֶאֱמָן וּמְשַׁלֵּם. מַעֲשֶׂה בְּאֶחָד שֶׁאָמַר לִשְׁלוּחוֹ קְנֵה לִי אַרְבַּע מֵאוֹת גַרְבֵּי יַיִן מִמָּעוֹת שֶׁהָיוּ לִי בְּיָדוֹ וְקָנָה לוֹ וְנִמְצְאוּ חֹמֶץ אָמְרוּ חֲכָמִים מִנְיָן גָּדוֹל כָּזֶה שֶׁהֶחְמִיץ קוֹל יֵשׁ לוֹ הוֹאִיל וְאֶפְשָׁר לְהָבִיא רְאָיָה יָבִיא רְאָיָה שֶׁלֹּא הָיָה הַיַּיִן חֹמֶץ בְּשָׁעָה שֶׁלָּקַח וְיִפָּטֵר וְאִם לֹא יָבִיא רְאָיָה יְשַׁלֵּם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה מִדְּבָרִים שֶׁהָרְאָיָה מְצוּיָה בָּהֶן אֲבָל דָּבָר הַנֶּעֱלָם שֶׁאֵין רְאָיָתוֹ מְצוּיָה יִשָּׁבַע עָלָיו. וְכֵן הַדִּין בְּכָל טַעֲנָה שֶׁיִּטְעֹן הַשֻּׁתָּף וְכַיּוֹצֵא בּוֹ. וְכֵן הַדִּין בְּטַעֲנַת הַשּׁוֹמְרִין אִם הָרְאָיָה יְכוֹלָה לִהְיוֹת אוֹ יָבִיא רְאָיָה עַל טַעֲנָתוֹ אוֹ יְשַׁלֵּם כְּמוֹ שֶׁיִּתְבָּאֵר:"],"Mishneh Torah, Appraisals and Devoted Property 5":["הַמַּקְדִישׁ שְׂדֵה אֲחֻזָּתוֹ מִצְוָה עָלָיו לִפְדּוֹתָהּ הוּא שֶׁהָאָדוֹן קוֹדֵם. וְאִם לֹא רָצָה אֵין כּוֹפִין אוֹתוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁמִּצְוַת יוֹבֵל נוֹהֶגֶת שֶׁאִם יַגִּיעַ יוֹבֵל וְלֹא יִגְאָלֶנָּה תֵּצֵא לַכֹּהֲנִים כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל בִּזְמַן שֶׁבָּטְלוּ הַיּוֹבְלוֹת שֶׁהֲרֵי אֵינָהּ יוֹצֵאת לַכֹּהֲנִים אֶלָּא סוֹפָהּ לְהִפָּדוֹת לְעוֹלָם כּוֹפִין אֶת הָאָדוֹן לִפְתֹּחַ בָּהּ תְּחִלָּה וְהִיא נִפְדֵית בְּשָׁוְיָהּ כִּשְׁאָר הַהֶקְדֵּשׁוֹת. אִם נִמְצָא מִי שֶׁמּוֹסִיף עָלָיו וְגוֹאֵל אוֹתָהּ יִגְאַל וְאִם לָאו אוֹמְרִין לוֹ הִגִּיעָתְךָ וְיִתֵּן מַה שֶּׁאָמַר וְאֵינוֹ פּוֹתֵחַ בְּפָחוֹת מֵאַרְבַּע פְּרוּטוֹת כְּדֵי שֶׁיְּהֵא הַחֹמֶשׁ שֶׁמּוֹסִיף פְּרוּטָה:","רָצָה הָאָדוֹן לִמְכֹּר שָׂדוֹת אֲחֵרוֹת מִשְּׂדוֹתָיו אוֹ לִלְווֹת כְּדֵי לִפְדּוֹת שָׂדֶה זוֹ שֶׁהִקְדִּישׁ הָרְשׁוּת בְּיָדוֹ. בֵּין בִּזְמַן שֶׁהַיּוֹבֵל נוֹהֵג בֵּין בִּזְמַן שֶׁאֵין הַיּוֹבֵל נוֹהֵג. וְהוּא קוֹדֵם לְכָל אָדָם. וְכֵן אִם רָצָה לִגְאל חֶצְיָהּ גּוֹאֵל. מַה שֶּׁאֵין כֵּן בְּמוֹכֵר לְהֶדְיוֹט. זֶה חֹמֶר בְּהֶדְיוֹט מִבְּהֶקְדֵּשׁ:","הַמַּקְדִּישׁ אֶת בֵּיתוֹ אוֹ אֶת בְּהֵמָה טְמֵאָה שֶׁלּוֹ אוֹ שְׁאָר מִטַּלְטְלָיו הֲרֵי אֵלּוּ נֶעֱרָכִין בְּשָׁוְיֵיהֶן בֵּין טוֹב וּבֵין רַע. וְאִם פָּדָה אוֹתָן הַמַּקְדִּישׁ אוֹ אִשְׁתּוֹ אוֹ יוֹרְשׁוֹ מוֹסִיף חֹמֶשׁ. וְכוֹפִין אֶת הַבְּעָלִים לִפְתֹּחַ רִאשׁוֹן וְהַדָּמִים לְבֶדֶק הַבַּיִת. בֵּין שֶׁהָיָה הַבַּיִת מִבָּתֵּי עָרֵי חוֹמָה בֵּין שֶׁהָיָה מִבָּתֵּי הַחֲצֵרִים הֲרֵי זֶה נִגְאָל לְעוֹלָם:","גְּאָלוֹ אַחֵר מִיַּד הַהֶקְדֵּשׁ אִם הָיָה בֵּית עָרֵי חוֹמָה וְקָם בְּיַד הַגּוֹאֵל שְׁנֵים עָשָׂר חֹדֶשׁ נֶחְלָט. וְאִם הָיָה בֵּית הַחֲצֵרִים וְהִגִּיעַ הַיּוֹבֵל וְהוּא בְּיַד הַגּוֹאֵל חוֹזֵר לִבְעָלָיו בַּיּוֹבֵל:","הַמַּקְדִּישׁ בְּהֵמָה טְהוֹרָה תְּמִימָה לְבֶדֶק הַבַּיִת אַף עַל פִּי שֶׁעָבַר עַל עֲשֵׂה מַה שֶּׁעָשָׂה עָשׂוּי וְחָלָה קְדֻשָּׁה עָלֶיהָ וְנִפְדֵית כְּשֶׁהִיא תְּמִימָה. וּמַעֲרִיךְ אוֹתָהּ הַכֹּהֵן בְּדָמֶיהָ. וְהַדָּמִים יִפְּלוּ לְבֶדֶק הַבַּיִת. וְאֵין הַפּוֹדֶה אוֹתָהּ פּוֹדֶה אֶלָּא עַל מְנָת לְהַקְרִיבָהּ לַמִּזְבֵּחַ לְמַה שֶּׁהִיא רְאוּיָה. שֶׁכָּל דָּבָר הָרָאוּי לַמִּזְבֵּחַ אֵינוֹ יוֹצֵא מִידֵי מִזְבֵּחַ לְעוֹלָם:","וּמִנַּיִן שֶׁאָסוּר לְהַקְדִּישׁ תְּמִימִין לְבֶדֶק הַבַּיִת שֶׁנֶּאֱמַר (ויקרא כב כג) \"וְשׁוֹר וָשֶׂה שָׂרוּעַ וְקָלוּט נְדָבָה תַּעֲשֶׂה אֹתוֹ\". מִפִּי הַשְּׁמוּעָה לָמְדוּ נְדָבָה לְבֶדֶק הַבַּיִת. וְכֵן הַדְּבָרִים מַרְאִין שֶׁאֵינָהּ אֶלָּא קְדֻשַּׁת דָּמִים. שֶׁאֵין מַקְרִיבִין בַּעַל מוּם לַמִּזְבֵּחַ שֶׁנֶּאֱמַר אֹתוֹ (ויקרא כב כג) \"אוֹתוֹ\" אַתָּה עוֹשֶׂה נְדָבָה לְבֶדֶק הַבַּיִת וְאֵין אַתָּה עוֹשֶׂה תְּמִימִים נְדָבָה לְבֶדֶק הַבַּיִת. וְלָאו הַבָּא מִכְּלַל עֲשֵׂה כַּעֲשֵׂה הוּא:","הַמַּקְדִּישׁ אֶת בְּהֶמְתּוֹ סְתָם אוֹ שֶׁהִקְדִּישׁ אֶת נְכָסָיו סְתָם רוֹאִין כָּל בְּהֵמָה תְּמִימָה הָרְאוּיָה לְהַקְרִיב עַל גַּבֵּי הַמִּזְבֵּחַ זְכָרִים יִמָּכְרוּ לְצָרְכֵי עוֹלוֹת וְיַקְרִיבוּ אוֹתָן עוֹלוֹת. וְהַנְּקֵבוֹת יִמָּכְרוּ לְצָרְכֵי שְׁלָמִים וְיַקְרִיבוּ אוֹתָן שְׁלָמִים. וְהַדָּמִים יִפְּלוּ לְבֶדֶק הַבַּיִת שֶׁסְּתָם הֶקְדֵּשׁוֹת לְבֶדֶק הַבַּיִת. וְעַל זֶה נֶאֱמַר (ויקרא כז ט) \"וְאִם בְּהֵמָה אֲשֶׁר יַקְרִיבוּ מִמֶּנָּה קָרְבָּן לַה' כּל אֲשֶׁר יִתֵּן מִמֶּנּוּ לַה' יִהְיֶה קֹּדֶשׁ\" כְּלוֹמַר כָּל הָרָאוּי לְקָרְבָּן עַל גַּבֵּי הַמִּזְבֵּחַ יִקָּרֵב:","הִקְדִּישׁ נְכָסָיו סְתָם וְהָיוּ בָּהֶן יֵינוֹת וּשְׁמָנִים וּסְלָתוֹת וְעוֹפוֹת הָרְאוּיִין לִקָּרֵב עַל גַּבֵּי הַמִּזְבֵּחַ יִמָּכְרוּ לְצָרְכֵי אוֹתוֹ הַמִּין וְיַקְרִיבוּ אוֹתָן וְהַדָּמִים יִלָּקַח בָּהֶן זְכָרִים וְיַקְרִיבוּ עוֹלוֹת:","וּמִפְּנֵי מָה יַקְרִיבוּ דְּמֵי אֵלּוּ עוֹלוֹת וּדְמֵי הַבְּהֵמָה הַתְּמִימָה יִפְּלוּ לְבֶדֶק הַבַּיִת. לְפִי שֶׁהַבְּהֵמָה הַקְּדוֹשָׁה לַמִּזְבֵּחַ אִם נָפַל בָּהּ מוּם יֵשׁ לָהּ פִּדְיוֹן כְּמוֹ שֶׁיִּתְבָּאֵר וְהַסּלֶת וְהַיַּיִן וְהַשֶּׁמֶן וְהָעוֹפוֹת שֶׁנִּפְסְלוּ אֵין לָהֶן פִּדְיוֹן שֶׁנֶּאֱמַר (ויקרא כז יא) \"וְהֶעֱמִיד אֶת הַבְּהֵמָה\" וְגוֹ' כָּל שֶׁיֶּשְׁנוֹ בִּכְלַל הַעֲמָדָה וְהַעֲרָכָה יֵשׁ לָהּ פִּדְיוֹן וְכָל שֶׁאֵינוֹ בִּכְלַל הַעֲמָדָה וְהַעֲרָכָה אֵין לָהּ פִּדְיוֹן:","הִקְדִּישׁ נְכָסָיו סְתָם וְהָיְתָה בָּהֶן הַקְּטֹרֶת שֶׁנּוֹתְנִין לְאָמָּנִין בִּשְׂכָרָן עַד שֶׁיַּחְזְרוּ וְיִקְחוּ אוֹתָהּ כְּמוֹ שֶׁבֵּאַרְנוּ בִּשְׁקָלִים. הֲרֵי זוֹ תִּנָּתֵן לְאָמָּנִין בִּשְׂכָרָן כְּמוֹ שֶׁעוֹשִׂין בְּמוֹתַר הַקְּטֹרֶת. וְכֵן עוֹשִׂין אִם יֵשׁ בִּנְכָסָיו אֶחָד מִסַּמָּנֵי הַקְּטֹרֶת:","הַמַּקְדִּישׁ בְּהֵמָה תְּמִימָה לַמִּזְבֵּחַ וְנָפַל בָּהּ מוּם וְנִפְסְלָה הֲרֵי זוֹ נֶעֱרֶכֶת וְנִפְדֵית. וְעַל זֶה נֶאֱמַר (ויקרא כז יא) \"וְאִם כָּל בְּהֵמָה טְמֵאָה אֲשֶׁר לֹא יַקְרִיבוּ מִמֶּנָּה קָרְבָּן לַה' וְהֶעֱמִיד אֶת הַבְּהֵמָה\" וְגוֹ'. וְיָבִיא בְּדָמֶיהָ קָרְבָּן אַחֵר כְּמוֹתָהּ:","כָּל הַמַּקְדִּישׁ בְּהֵמָה בְּחַיֶּיהָ בֵּין טְהוֹרָה בֵּין טְמֵאָה בֵּין קָדְשֵׁי הַבַּיִת בֵּין קָדְשֵׁי מִזְבֵּחַ שֶׁנָּפַל בָּהֶן מוּם אוֹ תְּמִימָה הָרְאוּיָה לִקָּרֵב כְּמוֹ שֶׁיִּתְבָּאֵר הֲרֵי זוֹ צְרִיכָה הַעֲמָדָה בְּבֵית דִּין שֶׁנֶּאֱמַר (ויקרא כז יא) \"וְהֶעֱמִיד אֶת הַבְּהֵמָה\". לְפִיכָךְ אִם מֵתָה הַבְּהֵמָה קֹדֶם שֶׁתֵּעָרֵךְ וְתִפָּדֶה אֵין פּוֹדִין אוֹתָהּ אַחַר שֶׁמֵּתָה אֶלָּא תִּקָּבֵר. אֲבָל אִם הִקְדִּישׁ שְׁחוּטָה אוֹ נְבֵלָה לְבֶדֶק הַבַּיִת הֲרֵי זוֹ תִּפָּדֶה כִּשְׁאָר מִטַּלְטְלִין:","שָׁחַט בָּהּ שְׁנַיִם אוֹ רֹב שְׁנַיִם וַעֲדַיִן הִיא מְפַרְכֶּסֶת הֲרֵי הִיא כְּחַיָּה לְכָל דְּבָרֶיהָ וְנֶעֱרֶכֶת וַהֲרֵי הִיא בִּכְלַל וְהֶעֱמִיד וְהֶעֱרִיךְ עַד שֶׁתָּמוּת:","הַמַּקְדִּישׁ בְּהֵמָה תְּמִימָה לְדָמֶיהָ הֲרֵי זוֹ נִתְקַדֵּשׁ גּוּפָהּ. כֵּיצַד. הָאוֹמֵר דְּמֵי בְּהֵמָה זוֹ הֶקְדֵּשׁ לַמִּזְבֵּחַ הִיא עַצְמָהּ תִּקָּרֵב. הִקְדִּישׁ אֶחָד מֵאֵיבָרֶיהָ לְדָמָיו וְאָמַר דְּמֵי רַגְלָהּ שֶׁל פָּרָה זוֹ הֶקְדֵּשׁ לַמִּזְבֵּחַ הֲרֵי זוֹ סָפֵק אִם פָּשְׁטָה קְדֻשָּׁה בְּכֻלָּהּ אוֹ לֹא פָּשְׁטָה. וּלְפִיכָךְ תִּקָּרֵב וְלֹא תִּפָּדֶה:","וכֵּיצַד עוֹשִׂין. מוֹכְרִין אוֹתָהּ כֻּלָּהּ לְמִי שֶׁיַּקְרִיב אוֹתָהּ. וְדָמֶיהָ חֻלִּין חוּץ מִדְּמֵי אוֹתוֹ אֵיבָר. וְאִם הָיָה אֵיבָר שֶׁהַנְּשָׁמָה תְּלוּיָה בּוֹ פָּשְׁטָה קְדֻשָּׁה בְּכֻלָּהּ:","הָיְתָה בְּהֵמָה בַּעֲלַת מוּם שֶׁאֵינָהּ רְאוּיָה לִקָּרֵב וְהִקְדִּישׁ אֵיבָר מֵאֵיבָרֶיהָ לְדָמָיו בֵּין שֶׁהַנְּשָׁמָה תְּלוּיָה בּוֹ בֵּין שֶׁהַנְּשָׁמָה אֵין תְּלוּיָה בּוֹ לֹא נִתְקַדֵּשׁ אֶלָּא דְּמֵי אוֹתוֹ אֵיבָר בִּלְבַד. כֵּיצַד. כְּגוֹן שֶׁאָמַר דְּמֵי רֶגֶל פָּרָה זוֹ אוֹ דְּמֵי לִבָּהּ הֶקְדֵּשׁ לַמִּזְבֵּחַ. הוּא וְהֶקְדֵּשׁ שֻׁתָּפִין בָּהּ:","וְכֵן הָאוֹמֵר רֹאשׁ עֶבֶד זֶה אוֹ לֵב חֲמוֹר זֶה הֶקְדֵּשׁ לַמִּזְבֵּחַ אוֹ שֶׁאָמַר רֹאשִׁי הֶקְדֵּשׁ לַמִּזְבֵּחַ אֵינוֹ חַיָּב אֶלָּא בִּדְמֵי רֹאשׁוֹ וְרוֹאִין כַּמָּה יִשְׁוֶה אוֹתוֹ אֵיבָר אִלּוּ הָיָה נִמְכָּר וְיָבִיא בְּדָמָיו קָרְבָּן:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּקָדְשֵׁי מִזְבֵּחַ. אֲבָל בְּקָדְשֵׁי בֶּדֶק הַבַּיִת הָאוֹמֵר דְּמֵי רֹאשׁ חֲמוֹר זֶה אוֹ כְּבֵדוֹ הֶקְדֵּשׁ אוֹ דְּמֵי רֹאשׁ עֶבֶד זֶה אוֹ כְּבֵדוֹ הֶקְדֵּשׁ הוֹאִיל וְהוּא דָּבָר שֶׁהַנְּשָׁמָה תְּלוּיָה בּוֹ הֲרֵי זֶה חַיָּב בִּדְמֵי כֻּלּוֹ. שֶׁכָּל הֶקְדֵּשׁ בֶּדֶק הַבַּיִת קְדֻשַּׁת דָּמִים הוּא:","הָאוֹמֵר עֶרְכִּי עָלַי לַמִּזְבֵּחַ מֵבִיא בְּעֶרְכּוֹ קָרְבָּן. וְאִם אֵין יָדוֹ מַשֶּׂגֶת לְעֵרֶךְ שָׁלֵם הֲרֵי זֶה דְּבַר סָפֵק אִם נִדּוֹן בְּהֶשֵּׂג יָד הוֹאִיל וְהוֹצִיאוֹ בִּלְשׁוֹן עֵרֶךְ. אוֹ אֵינוֹ נִדּוֹן בְּהֶשֵּׂג יָד הוֹאִיל וְלַמִּזְבֵּחַ נָדַר. וְכֵן הַמַּקְדִּישׁ שְׂדֵה אֲחֻזָּתוֹ לַמִּזְבֵּחַ הֲרֵי זוֹ נִפְדֵית וְהַדָּמִים יָבִיאוּ בָּהֶן עוֹלוֹת לַמִּזְבֵּחַ. וְיֵשׁ בַּדָּבָר סָפֵק אִם פּוֹדִין אוֹתָהּ בָּעֵרֶךְ הַקָּצוּב בָּהּ אוֹ פּוֹדִין אוֹתָהּ בְּשָׁוְיָן הוֹאִיל וְלַמִּזְבֵּחַ הִקְדִּישׁ וְדָנִין בְּכָל אֵלּוּ וְכַיּוֹצֵא בָּהֶן לְהַחְמִיר:"],"Mishneh Torah, Blessings 7":["מִנְהָגוֹת רַבּוֹת נָהֲגוּ חַכְמֵי יִשְׂרָאֵל בַּסְּעֻדָּה וְכֻלָּן דֶּרֶךְ אֶרֶץ. וְאֵלּוּ הֵן. כְּשֶׁנִּכְנָסִין לַסְּעֻדָּה הַגָּדוֹל שֶׁבְּכֻלָּן נוֹטֵל אֶת יָדָיו תְּחִלָּה. וְאַחַר כָּךְ נִכְנָסִין וְיוֹשְׁבִין מְסֻבִּין. וְגָדוֹל מֵסֵב בָּרֹאשׁ וְשֵׁנִי לוֹ לְמַטָּה הֵימֶנּוּ. הָיוּ שְׁלֹשָׁה מִטּוֹת גָּדוֹל מֵסֵב בָּרֹאשׁ וְשֵׁנִי לוֹ לְמַעְלָה הֵימֶנּוּ וּשְׁלִישִׁי לוֹ לְמַטָּה הֵימֶנּוּ:","בַּעַל הַבַּיִת מְבָרֵךְ הַמּוֹצִיא וּמַשְׁלִים הַבְּרָכָה וְאַחַר כָּךְ בּוֹצֵעַ. וְהָאוֹרֵחַ מְבָרֵךְ בִּרְכַּת הַמָּזוֹן כְּדֵי שֶׁיְּבָרֵךְ לְבַעַל הַבַּיִת. וְאִם הָיוּ כֻּלָּן בַּעֲלֵי הַבַּיִת הַגָּדוֹל שֶׁבָּהֶן בּוֹצֵעַ וְהוּא מְבָרֵךְ בִּרְכַּת הַמָּזוֹן:","אֵין הַבּוֹצֵעַ רַשַּׁאי לִבְצֹעַ עַד שֶׁיָּבִיאוּ מֶלַח אוֹ לִפְתָּן לִפְנֵי כָּל אֶחָד וְאֶחָד אֶלָּא אִם כֵּן נִתְכַּוְּנוּ לֶאֱכל פַּת חֲרֵבָה. וְאֵינוֹ בּוֹצֵעַ לֹא פְּרוּסָה קְטַנָּה מִפְּנֵי שֶׁהוּא נִרְאֶה כְּצַר עַיִן וְלֹא פְּרוּסָה גְּדוֹלָה יוֹתֵר מִכְּבֵיצָה מִפְּנֵי שֶׁנִּרְאֶה כִּרְעַבְתָּן. וּבְשַׁבָּת יֵשׁ לוֹ לִבְצֹעַ פְּרוּסָה גְּדוֹלָה. וְאֵינוֹ בּוֹצֵעַ אֶלָּא מִמָּקוֹם שֶׁנִּתְבַּשֵּׁל יָפֶה יָפֶה:","מִצְוָה מִן הַמֻּבְחָר לִבְצֹעַ כִּכָּר שְׁלֵמָה. אִם הָיְתָה שָׁם שְׁלֵמָה שֶׁל שְּׂעוֹרִים וּפְרוּסָה שֶׁל חִטִּים מַנִּיחַ שְׁלֵמָה בְּתוֹךְ פְּרוּסָה וּבוֹצֵעַ מִשְּׁתֵּיהֶן כְּדֵי שֶׁיִּבְצַע מֵחִטִּים וּמִשְּׁלֵמָה. בְּשַׁבָּתוֹת וּבְיָמִים טוֹבִים חַיָּב לִבְצֹעַ עַל שְׁתֵּי כִּכָּרוֹת נוֹטֵל שְׁתֵּיהֶן בְּיָדוֹ וּבוֹצֵעַ אַחַת מֵהֶן:","הַבּוֹצֵעַ נוֹתֵן פְּרוּסָה לִפְנֵי כָּל אֶחָד וְאֶחָד. וְהָאַחֵר נוֹטֵל בְּיָדוֹ. וְאֵין הַבּוֹצֵעַ נוֹתֵן בְּיַד הָאוֹכֵל אֶלָּא אִם כֵּן הָיָה אָבֵל. וְהַבּוֹצֵעַ הוּא פּוֹשֵׁט יָדָיו תְּחִלָּה וְאוֹכֵל. וְאֵין הַמְּסֻבִּין רַשָּׁאִין לִטְעֹם עַד שֶׁיִּטְעֹם הַמְבָרֵךְ. וְאֵין הַבּוֹצֵעַ רַשַּׁאי לִטְעֹם עַד שֶׁיִּכְלֶה אָמֵן מִפִּי רֹב הַמְּסֻבִּין. וְאִם רָצָה הַבּוֹצֵעַ לַחֲלֹק כָּבוֹד לְרַבּוֹ אוֹ לְמִי שֶׁהוּא גָּדוֹל מִמֶּנּוּ בְּחָכְמָה וְיַנִּיחֶנּוּ לִפְשֹׁט יָדוֹ קֹדֶם לוֹ הָרְשׁוּת בְּיָדוֹ:","שְׁנַיִם מַמְתִּינִין זֶה לָזֶה בִּקְעָרָה. שְׁלֹשָׁה אֵין מַמְתִּינִין. גָּמְרוּ מֵהֶן שְׁנַיִם הַשְּׁלִישִׁי מַפְסִיק עִמָּהֶן. גָּמַר אֶחָד מֵהֶן הַשְּׁנַיִם אֵין מַפְסִיקִין לוֹ אֶלָּא אוֹכְלִין וְהוֹלְכִין עַד שֶׁגּוֹמְרִין. אֵין מְשִׂיחִין בִּסְעֻדָּה כְּדֵי שֶׁלֹּא יָבוֹא לִידֵי סַכָּנָה. וּמִפְּנֵי זֶה אִם בָּא לָהֶם יַיִן בְּתוֹךְ הַמָּזוֹן כָּל אֶחָד וְאֶחָד מְבָרֵךְ לְעַצְמוֹ. שֶׁאִם בֵּרֵךְ אֶחָד וְעוֹנֶה הָעוֹנֶה אָמֵן בִּשְׁעַת הַבְּלִיעָה יָבוֹא לִידֵי סַכָּנָה. וְאֵין מִסְתַּכְּלִין בִּפְנֵי הָאוֹכֵל וְלֹא לִמְנָתוֹ שֶׁלֹּא לְבַיְּשׁוֹ:","הַשַּׁמָּשׁ שֶׁעוֹמֵד לִפְנֵי הַמְּסֻבִּין אֵינוֹ אוֹכֵל עִמָּהֶן. וְדֶרֶךְ רַחֲמָנוּת הוּא לִתֵּן לְתוֹךְ פִּיו מִכָּל תַּבְשִׁיל וְתַבְשִׁיל כְּדֵי לְיַשֵּׁב דַּעְתּוֹ. וְאִם נָתְנוּ לוֹ יַיִן מְבָרֵךְ עַל כָּל כּוֹס וְכוֹס שֶׁנּוֹתְנִין לוֹ. מִפְּנֵי שֶׁאֵין שְׁתִיָּתוֹ תְּלוּיָה בִּרְצוֹנוֹ אֶלָּא בִּרְצוֹנָם:","יָצָא אֶחָד מִן הַמְּסֻבִּין לְהַשְׁתִּין מַיִם נוֹטֵל יָדוֹ אַחַת וְנִכְנָס. דִּבֵּר עִם חֲבֵרוֹ וְהִפְלִיג נוֹטֵל שְׁתֵּי יָדָיו וְנִכְנָס. אִם הָיוּ מְסֻבִּין לִשְׁתִיָּה נִכְנָס וְיוֹשֵׁב בִּמְקוֹמוֹ וְנוֹטֵל יָדָיו וְאַחַר כָּךְ מַחֲזִיר פָּנָיו לָאוֹרְחִין. וְלָמָּה נוֹטֵל בִּמְקוֹמוֹ שֶׁמָּא יֹאמְרוּ לֹא נָטַל יָדָיו מִפְּנֵי שֶׁאֵין שָׁם אֲכִילָה:","אֵין מַנִּיחִין בָּשָׂר חַי עַל הַפַּת. וְאֵין מַעֲבִירִין כּוֹס מָלֵא עַל הַפַּת. וְאֵין סוֹמְכִין אֶת הַקְּעָרָה בְּפַת. וְאֵין זוֹרְקִין אֶת הַפַּת. וְלֹא אֶת הַחֲתִיכוֹת וְלֹא אֶת הָאֳכָלִין שֶׁאֵין לָהֶן קְלִפִּין כְּגוֹן תּוּתִים וַעֲנָבִים וּתְאֵנִים מִפְּנֵי שֶׁהֵן נִמְאָסִין. וּמֻתָּר לִמְשֹׁךְ אֶת הַיַּיִן בְּצִנּוֹרוֹת בְּבָתֵּי חֲתָנִים וְזוֹרְקִין לִפְנֵיהֶם קְלָיוֹת וֶאֱגוֹזִים בִּימוֹת הַחַמָּה אֲבָל לֹא בִּימוֹת הַגְּשָׁמִים מִפְּנֵי שֶׁנִּמְאָסִין. וְאֵין נוֹטְלִין יְדֵיהֶן בְּיַיִן בֵּין חַי בֵּין מָזוּג. וְכֵן אֵין מַפְסִידִין שְׁאָר אֳכָלִין וּמַשְׁקִין דֶּרֶךְ בִּזּוּי וּבְעִיטָה:","אָסוּר לְאוֹרְחִים לִטּל כְּלוּם מִמַּה שֶּׁלִּפְנֵיהֶם וְלִתֵּן בְּיַד בְּנוֹ אוֹ בִּתּוֹ שֶׁל בַּעַל הַבַּיִת שֶׁמָּא יִתְבַּיֵּשׁ בַּעַל הַסְּעֻדָּה שֶׁהֲרֵי אֵין לוֹ אֶלָּא מַה שֶּׁהֵבִיא לִפְנֵיהֶם וְנִמְצְאוּ הַקְּטַנִּים נוֹטְלִים אוֹתָם וְהוֹלְכִים. לֹא יִשְׁלַח אָדָם לַחֲבֵרוֹ חָבִית יַיִן וְשֶׁמֶן צָף עַל פִּיהָ שֶׁמָּא יִשְׁלַח לוֹ אָדָם חָבִית שֶׁכֻּלָּהּ יַיִן וִידַמֶּה שֶׁהוּא שֶׁמֶן וְשֶׁמֶן הוּא שֶׁעַל פָּנֶיהָ בִּלְבַד וִיזַמֵּן אוֹרְחִים וְיִתְבַּיֵּשׁ. וְכֵן כָּל כַּיּוֹצֵא בִּדְבָרִים אֵלּוּ הַמְּבִיאִים לִידֵי בּוּשָׁה לְבַעַל הַסְּעֻדָּה אֲסוּרִין:","גָּמְרוּ מִלֶּאֱכל מְסַלְּקִין אֶת הַשֻּׁלְחָן וּמְכַבְּדִין אֶת הַמָּקוֹם שֶׁאָכְלוּ בּוֹ וְאַחַר כָּךְ נוֹטְלִין אֶת יְדֵיהֶם. שֶׁמָּא יְשַׁיְּרוּ שָׁם פֵּרוּרִין שֶׁיֵּשׁ בָּהֶן כְּזַיִת שֶׁאָסוּר לְהַלֵּךְ בָּהֶן וְלִרְחֹץ עֲלֵיהֶן. אֲבָל פֵּרוּרִין שֶׁאֵין בָּהֶן כְּזַיִת מֻתָּר לְאַבְּדָן בַּיָּד:","הֵבִיאוּ לָהֶם מַיִם לִנְטִילָה כָּל שֶׁמְּבָרֵךְ בִּרְכַּת הַמָּזוֹן הוּא נוֹטֵל יָדָיו תְּחִלָּה. כְּדֵי שֶׁלֹּא יֵשֵׁב הַגָּדוֹל וְיָדָיו מְזֹהָמוֹת עַד שֶׁיִּטּל אַחֵר. וּשְׁאָר הַסּוֹעֲדִין נוֹטְלִין יָדָן בַּסּוֹף זֶה אַחַר זֶה. וְאֵין מְכַבְּדִין בְּדָבָר זֶה שֶׁאֵין מְכַבְּדִין בְּיָדַיִם מְזֹהָמוֹת וְלֹא בִּגְשָׁרִים וְלֹא בִּדְרָכִים אֶלָּא בְּפֶתַח הָרָאוּי לִמְזוּזָה וּבִשְׁעַת כְּנִיסָה:","גָּמְרוּ לִטּל יְדֵיהֶן וְנִגְּבוּ יְדֵיהֶן וּבֵרְכוּ בִּרְכַּת הַמָּזוֹן וְהֵבִיאוּ אֶת הַמֻּגְמָר. מִי שֶׁבֵּרֵךְ בִּרְכַּת הַמָּזוֹן הוּא מְבָרֵךְ עַל הַמֻּגְמָר וְכֻלָּן עוֹנִין אָמֵן:","אִם הָיָה שָׁם יַיִן מְבִיאִין כּוֹס מַחֲזִיק רְבִיעִית אוֹ יָתֵר עַל רְבִיעִית. וּמְבִיאִין בְּשָׂמִים וְאוֹחֵז אֶת הַיַּיִן בִּימִינוֹ וְאֶת הַבְּשָׂמִים בִּשְׂמֹאלוֹ וּמְבָרֵךְ בִּרְכַּת הַמָּזוֹן. וְאַחַר כָּךְ מְבָרֵךְ עַל הַיַּיִן. וְאַחַר כָּךְ מְבָרֵךְ עַל הַבְּשָׂמִים. אִם הָיוּ הַבְּשָׂמִים שֶׁמֶן עָרֵב וְכַיּוֹצֵא בּוֹ טָחוֹ בְּרֹאשׁ הַשַּׁמָּשׁ. וְאִם הָיָה הַשַּׁמָּשׁ תַּלְמִיד חָכָם טָחוֹ בַּכֹּתֶל כְּדֵי שֶׁלֹּא יֵצֵא מְבֻשָּׂם לַשּׁוּק:","אַף עַל פִּי שֶׁאֵין בִּרְכַּת הַמָּזוֹן צְרִיכָה יַיִן. אִם בֵּרֵךְ עַל הַיַּיִן כַּמִּנְהָג שֶׁאָמַרְנוּ צָרִיךְ שֶׁיָּדִיחַ כּוֹס שֶׁל בְּרָכָה מִבִּפְנִים וְלִשְׁטֹף אוֹתוֹ מִבַּחוּץ. וִימַלְּאֶנּוּ יַיִן חַי. וְכֵיוָן שֶׁהִגִּיעַ לְבִרְכַּת הָאָרֶץ נוֹתֵן לְתוֹכוֹ מְעַט מַיִם כְּדֵי שֶׁיְּהֵא עָרֵב לִשְׁתִיָּה. וְאֵין מְשִׂיחִין עַל כּוֹס שֶׁל בִּרְכַּת הַמָּזוֹן אֶלָּא הַכֹּל שׁוֹתְקִים עַד שֶׁתִּכְלֶה בִּרְכַּת הַמָּזוֹן וּבִרְכַּת הַיַּיִן וְיִשְׁתּוּ:"],"Mishneh Torah, Circumcision 2":["הַכּל כְּשֵׁרִין לָמוּל. וַאֲפִלּוּ עָרֵל וְעֶבֶד וְאִשָּׁה וְקָטָן מָלִין בְּמָקוֹם שֶׁאֵין שָׁם אִישׁ. אֲבָל עַכּוּ״ם לֹא יָמוּל כְּלָל. וְאִם מָל אֵינוֹ צָרִיךְ לַחֲזֹר וְלָמוּל שְׁנִיָּה. וּבַכּל מָלִין וַאֲפִלּוּ בְּצוּר וּבִזְכוּכִית וּבְכָל דָּבָר שֶׁכּוֹרֵת. וְלֹא יָמוּל בִּקְרוּמִית שֶׁל קָנֶה מִפְּנֵי הַסַּכָּנָה. וּמִצְוָה מִן הַמֻּבְחָר לָמוּל בְּבַרְזֶל בֵּין בְּסַכִּין בֵּין בְּמִסְפָּרַיִם. וְנָהֲגוּ כָּל יִשְׂרָאֵל בְּסַכִּין:","כֵּיצַד מוֹהֲלִין. חוֹתְכִין אֶת כָּל הָעוֹר הַמְחַפֶּה אֶת הָעֲטָרָה עַד שֶׁתִּתְגַּלֶּה כָּל הָעֲטָרָה. וְאַחַר כָּךְ פּוֹרְעִין אֶת הַקְּרוּם הָרַךְ שֶׁלְּמַטָּה מִן הָעוֹר בְּצִפֹּרֶן וּמַחֲזִירוֹ לְכָאן וּלְכָאן עַד שֶׁיֵּרָאֶה בְּשַׂר הָעֲטָרָה. וְאַחַר כָּךְ מוֹצֵץ אֶת הַמִּילָה עַד שֶׁיֵּצֵא הַדָּם מִמְּקוֹמוֹת רְחוֹקִים כְּדֵי שֶׁלֹּא יָבוֹא לִידֵי סַכָּנָה. וְכָל מִי שֶׁאֵינוֹ מוֹצֵץ מַעֲבִירִין אוֹתוֹ. וְאַחַר שֶׁמּוֹצֵץ נוֹתֵן עָלֶיהָ אִסְפְּלָנִית אוֹ רְטִיָּה וְכַיּוֹצֵא בָּהֶן:","יֵשׁ צִיצִין מְעַכְּבִין אֶת הַמִּילָה וְיֵשׁ צִיצִין שֶׁאֵין מְעַכְּבִין אֶת הַמִּילָה. כֵּיצַד. אִם נִשְׁאַר מֵעוֹר הָעָרְלָה עוֹר הַחוֹפֶה רֹב גָּבְהָהּ שֶׁל עֲטָרָה הֲרֵי זֶה עָרֵל כְּמוֹת שֶׁהָיָה. וְזֶה הָעוֹר הוּא צִיץ הַמְעַכֵּב. וְאִם לֹא נִשְׁאַר מִמֶּנּוּ אֶלָּא מְעַט שֶׁאֵינוֹ חוֹפֶה רֹב גָּבְהָהּ שֶׁל עֲטָרָה זֶהוּ צִיץ שֶׁאֵינוֹ מְעַכֵּב:","הַמָּל כָּל זְמַן שֶׁעוֹסֵק בַּמִּילָה חוֹזֵר בֵּין עַל הַצִּיצִין שֶׁמְּעַכְּבִין בֵּין עַל צִיצִין שֶׁאֵין מְעַכְּבִין. פֵּרַשׁ, עַל צִיצִין הַמְעַכְּבִין חוֹזֵר, עַל צִיצִין שֶׁאֵינָן מְעַכְּבִין אֵינוֹ חוֹזֵר. מָל וְלֹא פָּרַע אֶת הַמִּילָה כְּאִלּוּ לֹא מָל:","קָטָן שֶׁבְּשָׂרוֹ רַךְ וּמְדֻלְדָּל בְּיוֹתֵר אוֹ שֶׁהָיָה בַּעַל בָּשָׂר עַד שֶׁיֵּרָאֶה כְּאִלּוּ אֵינוֹ מָהוּל רוֹאִין אוֹתוֹ בְּעֵת שֶׁיִּתְקַשֶּׁה. אִם נִרְאֶה שֶׁהוּא מָהוּל אֵינוֹ צָרִיךְ כְּלוּם. וְצָרִיךְ לְתַקֵּן אֶת הַבָּשָׂר מִכָּאן וּמִכָּאן מִפְּנֵי מַרְאִית הָעַיִן. וְאִם בְּעֵת שֶׁיִּתְקַשֶּׁה לֹא נִרְאֶה מָהוּל חוֹזְרִין וְקוֹצְצִין אֶת הַבָּשָׂר הַמְדֻלְדָּל מִכָּאן וּמִכָּאן עַד שֶׁתֵּרָאֶה הָעֲטָרָה גְּלוּיָה בְּעֵת קִשּׁוּי. וְדָבָר זֶה מִדִּבְרֵי סוֹפְרִים. אֲבָל מִן הַתּוֹרָה אַף עַל פִּי שֶׁהוּא נִרְאֶה כְּעָרֵל הוֹאִיל וּמָל אֵינוֹ צָרִיךְ לָמוּל פַּעַם שְׁנִיָּה:","עוֹשִׂין כָּל צָרְכֵי מִילָה בְּשַׁבָּת. מָלִין וּפוֹרְעִין וּמוֹצְצִין. וְחוֹזֵר עַל צִיצִין הַמְעַכְּבִין אַף עַל פִּי שֶׁפֵּרַשׁ וְעַל צִיצִין שֶׁאֵין מְעַכְּבִין כָּל זְמַן שֶׁלֹּא פֵּרַשׁ. וְנוֹתֵן עָלֶיהָ אִסְפְּלָנִית. אֲבָל מַכְשִׁירֵי מִילָה אֵינָן דּוֹחִין אֶת הַשַּׁבָּת. כֵּיצַד. הֲרֵי שֶׁלֹּא מָצְאוּ סַכִּין אֵין עוֹשִׂין סַכִּין בְּשַׁבָּת וְלֹא מְבִיאִין אוֹתוֹ מִמָּקוֹם לְמָקוֹם. וַאֲפִלּוּ מָבוֹי שֶׁאֵינוֹ מְעֹרָב אֵין מְבִיאִין אוֹתוֹ מֵחָצֵר לְחָצֵר. וְאֵין עֵרוּב מִדִּבְרֵיהֶם נִדְחֶה מִפְּנֵי הֲבָאַת הַסַּכִּין הוֹאִיל וְאֶפְשָׁר לַהֲבִיאוֹ מֵעֶרֶב שַׁבָּת:","וְכֵן אֵין שׁוֹחֲקִין לָהּ סַמְמָנִין וְאֵין מְחִמִּין לָהּ חַמִּין. וְאֵין עוֹשִׂין לָהּ אִסְפְּלָנִית. וְאֵין טוֹרְפִין יַיִן וְשֶׁמֶן. וְאִם לֹא שָׁחַק כַּמּוֹן מֵעֶרֶב שַׁבָּת לוֹעֵס בְּשִׁנָּיו וְנוֹתֵן. וְאִם לֹא טָרַף יַיִן וְשֶׁמֶן נוֹתֵן זֶה לְעַצְמוֹ וְזֶה לְעַצְמוֹ. זֶה הַכְּלָל, כָּל שֶׁאֶפְשָׁר לַעֲשׂוֹתוֹ מֵעֶרֶב שַׁבָּת אֵינוֹ דּוֹחֶה אֶת הַשַּׁבָּת. אֲבָל אִם שָׁכַח וְלֹא הֵכִינוּ הַמַּכְשִׁירִין תִּדָּחֶה הַמִּילָה לִתְשִׁיעִי:","מָלוּ אֶת הַקָּטָן בְּשַׁבָּת וְאַחַר כָּךְ נִשְׁפְּכוּ הַחַמִּין אוֹ נִתְפַּזְּרוּ הַסַּמְמָנִין עוֹשִׂין לוֹ הַכּל בְּשַׁבָּת מִפְּנֵי שֶׁסַּכָּנָה הִיא לוֹ. מָקוֹם שֶׁדַּרְכָּן לְהַרְחִיץ אֶת הַקָּטָן מַרְחִיצִין אוֹתוֹ בְּשַׁבָּת בְּיוֹם הַמִּילָה בֵּין לִפְנֵי הַמִּילָה בֵּין לְאַחַר הַמִּילָה, אוֹ בַּשְּׁלִישִׁי שֶׁל מִילָה שֶׁחָל לִהְיוֹת בְּשַׁבָּת. בֵּין רְחִיצַת כָּל גּוּפוֹ. בֵּין רְחִיצַת מִילָה. בֵּין בְּחַמִּין שֶׁהוּחַמּוּ מֵעֶרֶב שַׁבָּת בֵּין בְּחַמִּין שֶׁהוּחַמּוּ בְּשַׁבָּת. מִפְּנֵי שֶׁסַּכָּנָה הִיא לוֹ:","שָׁכְחוּ וְלֹא הֵבִיאוּ סַכִּין מֵעֶרֶב שַׁבָּת אוֹמֵר לְעַכּוּ״ם לְהָבִיא סַכִּין בְּשַׁבָּת. וּבִלְבַד שֶׁלֹּא יָבִיא אוֹתוֹ דֶּרֶךְ רְשׁוּת הָרַבִּים. כְּלָלוֹ שֶׁל דָּבָר כָּל דָּבָר שֶׁעֲשִׂיָּתוֹ בְּשַׁבָּת אֲסוּרָה עָלֵינוּ מִשּׁוּם שְׁבוּת מֻתָּר לָנוּ לוֹמַר לְעַכּוּ״ם לַעֲשׂוֹת אוֹתָן כְּדֵי לַעֲשׂוֹת מִצְוָה בִּזְמַנָּהּ. וְדָבָר שֶׁעֲשִׂיָּתוֹ אֲסוּרָה עָלֵינוּ מִשּׁוּם מְלָאכָה אָסוּר לָנוּ לוֹמַר לְעַכּוּ״ם לַעֲשׂוֹתוֹ בְּשַׁבָּת:","מַכְשִׁירֵי מִילָה אֲפִלּוּ בִּזְמַנָּהּ אֵינָן דּוֹחִין אֶת יוֹם טוֹב הוֹאִיל וְאֶפְשָׁר לַעֲשׂוֹתָן מֵעֶרֶב יוֹם טוֹב. וְקַל וָחֹמֶר הַדְּבָרִים, אִם לֹא דָּחוּ מַכְשִׁירֵי מִילָה שְׁבוּת שֶׁהוּא מִדִּבְרֵיהֶם הֵיאַךְ יִדְחוּ לֹא תַּעֲשֶׂה שֶׁבַּתּוֹרָה. אֲבָל שׁוֹחֲקִין לָהּ סַמָּנִין בְּיוֹם טוֹב הוֹאִיל וְרָאוּי לִקְדֵרָה. וְטוֹרְפִין לָהּ יַיִן וְשֶׁמֶן:"],"Mishneh Torah, Creditor and Debtor 19":["כְּשֶׁיּוֹרְדִין בֵּית דִּין לְנִכְסֵי הַלּוֶֹה לִגְבּוֹת מֵהֶן לֹא יִגְבּוּ לְבַעַל חוֹב אֶלָּא מִן הַבֵּינוֹנִית שֶׁבְּקַרְקְעוֹתָיו. וְדִין תּוֹרָה שֶׁיִּגְבֶּה בַּעַל חוֹב מִן הַזִּבּוּרִית שֶׁנֶּאֱמַר (דברים כד יא) \"בַּחוּץ תַּעֲמֹד וְהָאִישׁ אֲשֶׁר אַתָּה נשֶׁה בוֹ יוֹצִיא\" וְגוֹ' מַה דַּרְכּוֹ שֶׁל אָדָם לְהוֹצִיא פָּחוּת שֶׁבְּכֵלָיו. אֲבָל תִּקְּנוּ חֲכָמִים בְּבֵינוֹנִיּת כְּדֵי שֶׁלֹּא תִּנְעל דֶּלֶת בִּפְנֵי לוֹוִין. בַּמֶּה דְּבָרִים אֲמוּרִים בְּבָא לִפָּרַע מִן הַלּוֶֹה עַצְמוֹ. אֲבָל הַבָּא לִפָּרַע מִן הַיּוֹרְשִׁין בֵּין קְטַנִּים בֵּין גְּדוֹלִים לֹא יִפָּרַע אֶלָּא מִן הַזִּבּוּרִית:","אֵין נִפְרָעִים מִנְּכָסִים מְשֻׁעְבָּדִין בְּמָקוֹם שֶׁיֵּשׁ נְכָסִים בְּנֵי חוֹרִין וַאֲפִלּוּ הָיוּ בְּנֵי חוֹרִין זִבּוּרִית וְהַמְשֻׁעְבָּדִים בֵּינוֹנִית אוֹ עִידִית בֵּין שֶׁמְּכָרָם בֵּין שֶׁנְּתָנָם. נִשְׁתַּדְּפוּ בְּנֵי חוֹרִין הֲרֵי זֶה טוֹרֵף מִן הַמְשֻׁעְבָּדִין שֶׁכֵּיוָן שֶׁנִּשְׁחֲתוּ כְּאִלּוּ אֵינָם:","רְאוּבֵן שֶׁמָּכַר כָּל שְׂדוֹתָיו לְשִׁמְעוֹן וְחָזַר שִׁמְעוֹן וּמָכַר שָׂדֶה אַחַת מֵהֶן לְלֵוִי וּבָא בַּעַל חוֹב שֶׁל רְאוּבֵן לִטְרֹף רָצָה מִזֶּה גּוֹבֶה רָצָה מִזֶּה גּוֹבֶה. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁלָּקַח לֵוִי בֵּינוֹנִית. אֲבָל אִם לָקַח עִידִית אוֹ זִבּוּרִית אֵינוֹ טוֹרֵף מִלֵּוִי שֶׁהֲרֵי זֶה אוֹמֵר לוֹ מִפְּנֵי זֶה טָרַחְתִּי וְלָקַחְתִּי שָׂדֶה שֶׁאֵין דִּינְךָ לִגְבּוֹת מִמֶּנּוּ. וְכֵן אִם לָקַח לֵוִי בֵּינוֹנִית וְהִנִּיחַ אֵצֶל שִׁמְעוֹן בֵּינוֹנִית כְּמוֹ הַבֵּינוֹנִית שֶׁלָּקַח אֵינוֹ טוֹרֵף מִלֵּוִי שֶׁהֲרֵי זֶה אוֹמֵר לוֹ הִנַּחְתִּי לְךָ מָקוֹם לִגְבּוֹת מִמֶּנּוּ:","כְּבָר בֵּאַרְנוּ שֶׁהַנִּזָּקִין שָׁמִין לָהֶן בְּעִידִית וּבַעַל חוֹב בְּבֵינוֹנִית וּכְתֻבַּת אִשָּׁה בְּזִבּוּרִית. הָיוּ לוֹ עִידִית וְזִבּוּרִית נִזָּקִין בְּעִידִית בַּעַל חוֹב [וּכְתֻבַּת אִשָּׁה] בְּזִבּוּרִית. הָיוּ לוֹ עִידִית וּבֵינוֹנִית נִזָּקִין בְּעִידִית וּבַעַל חוֹב וּכְתֻבַּת אִשָּׁה בְּבֵינוֹנִית. הָיוּ לוֹ זִבּוּרִית וּבֵינוֹנִית בִּלְבַד נִזָּקִין וּבַעַל חוֹב בְּבֵינוֹנִית וּכְתֻבַּת אִשָּׁה בְּזִבּוּרִית:","מְכָרָן לִשְׁלֹשָׁה בְּנֵי אָדָם בְּבַת אַחַת הֲרֵי כֻּלָּן נִכְנְסוּ תַּחַת הַבְּעָלִים וְהַנִּזָּקִין טוֹרְפִין מִן הָעִידִית וּבַעַל חוֹב טוֹרֵף מִן הַבֵּינוֹנִית וּכְתֻבַּת אִשָּׁה טוֹרֶפֶת מִן הַזִּבּוּרִית. מְכָרָן לָזֶה אַחַר זֶה כֻּלָּן טוֹרְפִין מִן הָאַחֲרוֹן. לֹא הִסְפִּיק טוֹרְפִין מִשֶּׁלְּפָנָיו. לֹא הִסְפִּיק טוֹרְפִין מִשֶּׁלִּפְנֵי פָנָיו. אֲפִלּוּ הָיָה הָאַחֲרוֹן הוּא שֶׁלָּקַח הַזִּבּוּרִית שֶׁהֲרֵי הַלּוֹקֵחַ הַקּוֹדֵם אוֹמֵר לַטּוֹרֵף הִנַּחְתִּי לְךָ מָקוֹם לִגְבּוֹת מִמֶּנּוּ:","מְכָרָן לְאֶחָד זוֹ אַחַר זוֹ הֲרֵי הַלּוֹקֵחַ נִכְנָס תַּחַת הַבְּעָלִים. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁלָּקַח עִידִית בָּאַחֲרוֹנָה אֲבָל לָקַח זִבּוּרִית בָּאַחֲרוֹנָה כֻּלָּן גּוֹבִין מִן הַזִּבּוּרִית שֶׁהֲרֵי אוֹמֵר לַטּוֹרֵף כְּשֶׁיָּבוֹא לִגְבּוֹת מִן הַשָּׂדֶה שֶׁלָּקַח תְּחִלָּה הֲרֵי הִנַּחְתִּי לְךָ מָקוֹם לִגְבּוֹת מִמֶּנּוּ. וְלָמָּה אֵינוֹ אוֹמֵר לוֹ הַטּוֹרֵף כָּךְ אִם לָקַח עִידִית בָּאַחֲרוֹנָה וְתִגְבֶּה הָאִשָּׁה וּבַעַל חוֹב מִן הָעִידִית שֶׁלָּקַח בָּאַחֲרוֹנָה. שֶׁזּוֹ תַּקָּנָה הִיא לַלּוֹקֵחַ וַהֲרֵי אוֹמֵר לוֹקֵחַ לָהֶן אִי אֶפְשִׁי בְּתַקָּנָה זוֹ אֶלָּא כָּל אֶחָד מִכֶּם יִגְבֶּה מִן הָרָאוּי לוֹ:","מְכָרָן לְאֶחָד זוֹ אַחַר זוֹ וּמָכַר לוֹ עִידִית בָּאַחֲרוֹנָה וְחָזַר הַלּוֹקֵחַ וּמָכַר זִבּוּרִית וּבֵינוֹנִית וְשִׁיֵּר עִידִית לְפָנָיו כֻּלָּן גּוֹבִין מִן הָעִידִית שֶׁהֲרֵי אֵין לוֹ בְּמָה יִדְחֶה אוֹתָם. מָכַר עִידִית וְהִנִּיחַ בֵּינוֹנִית וְזִבּוּרִית הַנִּזָּקִין טוֹרְפִין מִן הָעִידִית שֶׁבְּיַד לוֹקֵחַ הַשֵּׁנִי וּבַעַל חוֹב וּכְתֻבַּת אִשָּׁה גּוֹבִין מִבֵּינוֹנִית וְזִבּוּרִית שֶׁשִּׁיֵּר לְפָנָיו:","מִי שֶׁלָּוָה מֵאֶחָד וְאַחַר כָּךְ מָכַר הַלּוֶֹה נְכָסָיו לִשְׁנַיִם וְכָתַב בַּעַל חוֹב לְלוֹקֵחַ שֵׁנִי דִּין וּדְבָרִים אֵין לִי עִמְּךָ וְקָנוּ מִיָּדוֹ אֵינוֹ יָכוֹל לִטְרֹף מִלּוֹקֵחַ רִאשׁוֹן שֶׁהֲרֵי אוֹמֵר לוֹ הִנַּחְתִּי לְךָ מָקוֹם לִגְבּוֹת מִמֶּנּוּ אֵצֶל בַּעַל חוֹבְךָ מִן הַנְּכָסִים שֶׁקָּנָה לוֹקֵחַ שֵׁנִי אַחֲרַי וְאַתָּה הִפְסַדְתָּ עַל עַצְמְךָ שֶׁהֲרֵי סִלַּקְתָּ עַצְמְךָ מֵהֶן. וְהוּא הַדִּין לְאִשָּׁה בִּכְתֻבָּתָהּ אִם כָּתְבָה לַשֵּׁנִי. אִבְּדָה כְּתֻבָּתָהּ וְאֵינָהּ יְכוֹלָה לִטְרֹף. אֲבָל אִם כָּתְבוּ לָרִאשׁוֹן טוֹרְפִין מִן הַשֵּׁנִי. מָכַר הַלּוֶֹה שָׂדֶה לַלּוֹקֵחַ וּמְכָרָהּ לוֹקֵחַ רִאשׁוֹן לְלוֹקֵחַ שֵׁנִי וְכָתַב הַמַּלְוֶה לְלוֹקֵחַ רִאשׁוֹן דִּין וּדְבָרִים אֵין לִי עִמְּךָ וְקָנוּ מִיָּדוֹ הֲרֵי בַּעַל חוֹב טוֹרֵף מִלּוֹקֵחַ שֵׁנִי אוֹתָהּ הַשָּׂדֶה וְלוֹקֵחַ רִאשׁוֹן טוֹרֵף אוֹתָהּ מִבַּעַל חוֹב שֶׁהֲרֵי כָּתַב לוֹ וְלוֹקֵחַ שֵׁנִי טוֹרֵף אוֹתָהּ מִלּוֹקֵחַ רִאשׁוֹן שֶׁהֲרֵי הוּא מְכָרָהּ לוֹ וּבַעַל חוֹב חוֹזֵר וְטוֹרֵף מִשֵּׁנִי וְחוֹזְרִין חֲלִילָה עַד שֶׁיַּעֲשׂוּ פְּשָׁרָה בֵּינֵיהֶן. וְכֵן הָאִשָּׁה בִּכְתֻבָּתָהּ:"],"Mishneh Torah, Creditor and Debtor 5":["הָעַכּוּ\"ם וְגֵר תּוֹשָׁב לוִֹין מֵהֶן וּמַלְוִין אוֹתָן בְּרִבִּית שֶׁנֶּאֱמַר (דברים כג כ) \"לֹא תַשִּׁיךְ לְאָחִיךָ\" לְאָחִיךְ אָסוּר וְלִשְׁאָר הָעוֹלָם מֻתָּר. וּמִצְוַת עֲשֵׂה לְהַשִּׁיךְ לְעַכּוּ\"ם שֶׁנֶּאֱמַר (דברים כג כא) \"לַנָּכְרִי תַשִּׁיךְ\" מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁזּוֹ מִצְוַת עֲשֵׂה וְזֶהוּ דִּין תּוֹרָה:","אָסְרוּ חֲכָמִים שֶׁיִּהְיֶה יִשְׂרָאֵל מַלְוֶה אֶת הָעַכּוּ\"ם בְּרִבִּית קְצוּצָה אֶלָּא בִּכְדֵי חַיָּיו. גָּזְרוּ שֶׁמָּא יִלְמֹד מִמַּעֲשָׂיו בְּרֹב יְשִׁיבָתוֹ עִמּוֹ. לְפִיכָךְ מֻתָּר לִלְווֹת מִן הָעַכּוּ\"ם בְּרִבִּית שֶׁהֲרֵי הוּא בּוֹרֵחַ מִלְּפָנָיו וְאֵינוֹ רָגִיל אֶצְלוֹ. וְתַלְמִיד חָכָם שֶׁאֵינוֹ רָגִיל בּוֹ לִלְמֹד מִמַּעֲשָׂיו מֻתָּר לְהַלְווֹת לָעַכּוּ\"ם בְּרִבִּית אֲפִלּוּ לְהַרְוִיחַ. וְכָל אֲבַק רִבִּית עִם הָעַכּוּ\"ם מֻתֶּרֶת לַכּל:","יִשְׂרָאֵל שֶׁלָּוָה מָעוֹת מִן הָעַכּוּ\"ם בְּרִבִּית וּבִקֵּשׁ לְהַחְזִירָם לוֹ. מְצָאוֹ יִשְׂרָאֵל אַחֵר וְאָמַר לוֹ תְּנֵם לִי וַאֲנִי מַעֲלֶה לְךָ כְּדֶרֶךְ שֶׁאַתָּה מַעֲלֶה לָעַכּוּ\"ם. הֲרֵי זוֹ רִבִּית קְצוּצָה אֲפִלּוּ הֶעֱמִידוֹ אֵצֶל הָעַכּוּ\"ם עַד שֶׁיִּטּל הָעַכּוּ\"ם מְעוֹתָיו וְיַחְזֹר וְיִתְּנֵם בְּיַד יִשְׂרָאֵל הָאַחֵר:","עַכּוּ\"ם שֶׁלָּוָה מָעוֹת מִיִּשְׂרָאֵל בְּרִבִּית וּבִקֵּשׁ לְהַחְזִירָם לוֹ. מְצָאוֹ יִשְׂרָאֵל אַחֵר וְאָמַר לוֹ תְּנֵם לִי וַאֲנִי מַעֲלֶה לְךָ כְּדֶרֶךְ שֶׁאַתָּה מַעֲלֶה לְיִשְׂרָאֵל הֲרֵי זֶה מֻתָּר. וְאִם הֶעֱמִידוֹ אֵצֶל יִשְׂרָאֵל אַף עַל פִּי שֶׁנָּתַן הָעַכּוּ\"ם הַמָּעוֹת בְּיָדוֹ הוֹאִיל וּמִדַּעַת יִשְׂרָאֵל נָתַן הֲרֵי זוֹ רִבִּית קְצוּצָה:","אָסוּר לְיִשְׂרָאֵל לִתְלוֹת מְעוֹתָיו בְּיַד עַכּוּ\"ם כְּדֵי לְהַלְווֹתָן בְּרִבִּית לְיִשְׂרָאֵל. וְעַכּוּ\"ם שֶׁהִלְוָה אֶת יִשְׂרָאֵל בְּרִבִּית אָסוּר לְיִשְׂרָאֵל אַחֵר לִהְיוֹת לוֹ עָרֵב שֶׁכֵּיוָן שֶׁבְּדִינֵיהֶם שֶׁתּוֹבֵעַ הֶעָרֵב תְּחִלָּה נִמְצָא הֶעָרֵב תּוֹבֵעַ אֶת יִשְׂרָאֵל בְּרִבִּית שֶׁהֶעָרֵב חַיָּב בָּהּ לָעַכּוּ\"ם. לְפִיכָךְ אִם קִבֵּל עָלָיו הָעַכּוּ\"ם שֶׁלֹּא יִתְבַּע אֶת הֶעָרֵב תְּחִלָּה הֲרֵי זֶה מֻתָּר:","יִשְׂרָאֵל שֶׁלָּוָה מָעוֹת מִן הָעַכּוּ\"ם בְּרִבִּית וּזְקָפָן עָלָיו בְּמִלְוֶה וְנִתְגַּיֵּר אִם עַד שֶׁלֹּא נִתְגַּיֵּר זְקָפָן עָלָיו בְּמִלְוֶה גּוֹבֶה אֶת הַקֶּרֶן וְהָרִבִּית וְאִם מִשֶּׁנִּתְגַּיֵּר זְקָפָן עָלָיו בְּמִלְוֶה גּוֹבֶה אֶת הַקֶּרֶן וְלֹא אֶת הָרִבִּית. אֲבָל עַכּוּ\"ם שֶׁלָּוָה מִיִּשְׂרָאֵל בְּרִבִּית וְזָקַף עָלָיו אֶת הָרִבִּית בְּמִלְוֶה אַף עַל פִּי שֶׁזְּקָפָן עָלָיו אַחֵר שֶׁנִּתְגַּיֵּר גּוֹבֶה אֶת הַקֶּרֶן וְאֶת הָרִבִּית שֶׁלֹּא יֹאמְרוּ בִּשְׁבִיל מְעוֹתָיו נִתְגַּיֵּר זֶה. וְגוֹבֶה הַיִּשְׂרָאֵל מִמֶּנּוּ אַחַר שֶׁנִּתְגַּיֵּר כָּל מְעוֹת הָרִבִּית שֶׁנִּתְחַיֵּב בָּהֶן כְּשֶׁהָיָה עַכּוּ\"ם:","מִצְוָה לְהַקְדִּים הַלְוָאַת יִשְׂרָאֵל בְּחִנָּם לְהַלְוָאַת עַכּוּ\"ם בְּרִבִּית:","אָסוּר לְאָדָם שֶׁיִּתֵּן מְעוֹתָיו קָרוֹב לְשָׂכָר וְרָחוֹק לְהֶפְסֵד שֶׁזֶּה אֲבַק רִבִּית הוּא וְהָעוֹשֶׂה כֵן נִקְרָא רָשָׁע. וְאִם נָתַן חוֹלְקִין בַּשָּׂכָר וּבַהֶפְסֵד כְּדִין הָעֵסֶק. וְהַנּוֹתֵן מְעוֹתָיו קָרוֹב לְהֶפְסֵד וְרָחוֹק לְשָׂכָר הֲרֵי זֶה נִקְרָא חָסִיד:","אֵין מוֹשִׁיבִין חֶנְוָנִי לְמַחֲצִית שָׂכָר וְלֹא יִתֵּן מָעוֹת לִקַּח בָּהֶן פֵּרוֹת לְמַחֲצִית שָׂכָר וְלֹא בֵּיצִים לְהוֹשִׁיב תַּחַת הַתַּרְנְגוֹלִין שֶׁלּוֹ לְמַחֲצִית שָׂכָר וְאֵין שָׁמִין עֲגָלִים וּסְיָחִין לְפַטְּמָן לְמַחֲצִית שָׂכָר אֶלָּא אִם כֵּן נָתַן לוֹ שְׂכַר עֲמָלוֹ וּמְזוֹנוֹ. אוֹ יִהְיֶה רֶוַח הַמִּתְעַסֵּק יוֹתֵר עַל הֶפְסֵדוֹ כְּמוֹ שֶׁבֵּאַרְנוּ בְּעִנְיַן הַשֻּׁתָּפוּת:","הַמִּשְׁתַּתֵּף עִם חֲבֵרוֹ בְּמָעוֹת אוֹ בְּקַרְקַע אוֹ הַנּוֹתֵן לוֹ עֵסֶק לֹא יְצָרֵף הַשָּׂכָר עִם הַקֶּרֶן שֶׁמָּא לֹא יִהְיֶה שָׁם שָׂכָר וְנִמְצְאוּ בָּאִין לִידֵי רִבִּית. וְכֵן לֹא יִתֵּן לוֹ מָעוֹת בְּתוֹרַת עֵסֶק אוֹ שֻׁתָּפוּת וְיִכְתֹּב אוֹתָן מִלְוֶה שֶׁמָּא יָמוּת וְנִמְצָא הַשְּׁטָר בְּיַד הַיּוֹרֵשׁ וְגוֹבֶה בּוֹ אֶת הָרִבִּית:","אָסוּר לְהַקְדִּים הָרִבִּית אוֹ לְאַחֵר אוֹתוֹ. כֵּיצַד. נָתַן עֵינָיו לִלְווֹת מִמֶּנּוּ וְהָיָה מְשַׁלֵּחַ לוֹ סִבְלוֹנוֹת בִּשְׁבִיל שֶׁיַּלְוֵהוּ זוֹ הִיא רִבִּית מֻקְדֶּמֶת. לָוָה מִמֶּנּוּ וְהֶחְזִיר לוֹ מְעוֹתָיו וְהָיָה מְשַׁלֵּחַ לוֹ סִבְלוֹנוֹת בִּשְׁבִיל מְעוֹתָיו שֶׁהָיוּ בְּטֵלִין אֶצְלוֹ זוֹ הִיא רִבִּית מְאֻחֶרֶת. וְאִם עָבַר וְעוֹשֶׂה כֵן הֲרֵי זֶה אֲבַק רִבִּית:","מִי שֶׁלָּוָה מֵחֲבֵרוֹ וְלֹא הָיָה רָגִיל מִקֹּדֶם לְהַקְדִּים לוֹ שָׁלוֹם אָסוּר לְהַקְדִּים לוֹ שָׁלוֹם. וְאֵין צָרִיךְ לוֹמַר שֶׁיְּקַלְּסוֹ בִּדְבָרִים אוֹ יַשְׁכִּים לְפִתְחוֹ שֶׁנֶּאֱמַר (דברים כג כ) \"נֶשֶׁךְ כָּל דָּבָר\" אֲפִלּוּ דְּבָרִים אֲסוּרִים. וְכֵן אָסוּר לוֹ לְלַמֵּד אֶת הַמַּלְוֶה מִקְרָא אוֹ גְּמָרָא כָּל זְמַן שֶׁמְּעוֹתָיו בְּיָדוֹ אִם לֹא הָיָה רָגִיל בָּזֶה מִקֹּדֶם שֶׁנֶּאֱמַר נֶשֶׁךְ כָּל דָּבָר:","הַמַּלְוֶה אֶת חֲבֵרוֹ לֹא יֹאמַר לוֹ דַּע אִם בָּא אִישׁ פְּלוֹנִי מִמָּקוֹם פְּלוֹנִי (כְּלוֹמַר) שֶׁתְּכַבְּדוֹ וְתַאֲכִילוֹ וְתַשְׁקֵהוּ כָּרָאוּי. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","יֵשׁ דְּבָרִים שֶׁהֵן כְּמוֹ רִבִּית וּמֻתָּרִין כֵּיצַד. לוֹקֵחַ אָדָם שִׁטְרוֹתָיו שֶׁל חֲבֵרוֹ בְּפָחוֹת וְאֵינוֹ חוֹשֵׁשׁ. וּמֻתָּר לְאָדָם לִתֵּן לַחֲבֵרוֹ דִּינָר כְּדֵי שֶׁיַּלְוֶה לִפְלוֹנִי מֵאָה דִּינָרִין שֶׁלֹּא אָסְרָה תּוֹרָה אֶלָּא רִבִּית הַבָּאָה מִן הַלּוֶֹה לַמַּלְוֶה. וְכֵן אוֹמֵר אָדָם לַחֲבֵרוֹ הֵא לְךָ דִּינָר זֶה וֶאֱמֹר לִפְלוֹנִי שֶׁיַּלְוֵנִי. שֶׁלֹּא נָתַן אֶלָּא שְׂכַר אֲמִירָה:","יֵשׁ דְּבָרִים שֶׁהֵן מֻתָּרִין וְאָסוּר לַעֲשׂוֹתָן מִפְּנֵי הַעֲרָמַת רִבִּית. כֵּיצַד. אָמַר לוֹ הַלְוֵנִי מָנֶה אָמַר לוֹ מָנֶה אֵין לִי חִטִּים יֵשׁ לִי בְּמָנֶה וְנָתַן לוֹ חִטִּים בְּמָנֶה וְחָזַר וּלְקָחָן מִמֶּנּוּ בְּתִשְׁעִים הֲרֵי זֶה מֻתָּר. אֲבָל אֲסָרוּהוּ מִפְּנֵי הַעֲרָמַת רִבִּית שֶׁהֲרֵי נָתַן לוֹ תִּשְׁעִים וְלוֹקֵחַ מָנֶה. וְאִם עָבַר וְעָשָׂה כָּזֶה הֲרֵי הוּא מוֹצִיא מִמֶּנּוּ מֵאָה בְּדִין שֶׁאֲפִלּוּ אֲבַק רִבִּית אֵין כָּאן. וְכֵן מִי שֶׁהָיְתָה שָׂדֶה מְמֻשְׁכֶּנֶת בְּיָדוֹ לֹא יַחְזֹר וְיַשְׂכִּיר אוֹתָהּ לְבַעַל הַשָּׂדֶה מִפְּנֵי הַעֲרָמַת רִבִּית שֶׁהֲרֵי זֶה עוֹמֵד בְּשָׂדֵהוּ כְּשֶׁהָיָה וְנוֹתֵן לָזֶה שָׂכָר בְּכָל חֹדֶשׁ בִּשְׁבִיל מְעוֹתָיו שֶׁהִלְוָהוּ:","אָסוּר לְהַשְׂכִּיר הַדִּינָרִין שֶׁאֵין זֶה דּוֹמֶה לְמַשְׂכִּיר אֶת הַכְּלִי שֶׁהַכְּלִי חוֹזֵר בְּעַצְמוֹ וְזֶה מוֹצִיא אֵלּוּ וּמֵבִיא דִּינָרִין אֲחֵרוֹת וְנִמְצָא זֶה אֲבַק רִבִּית:","מֶלֶךְ שֶׁהָיוּ דִּינָיו שֶׁכָּל מִי שֶׁיִּתֵּן הַמַּס הַקָּצוּב עַל כָּל אִישׁ וְאִישׁ עַל יְדֵי זֶה שֶׁלֹּא נָתַן יִשְׁתַּעְבֵּד בּוֹ וְנָתַן עַל יָדוֹ דִּינָר אַף עַל פִּי שֶׁמְּשַׁעְבֵּד בּוֹ יֶתֶר מִדִּינָר הֲרֵי זֶה מֻתָּר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Daily Offerings and Additional Offerings 7":["בְרָאשֵׁי חֳדָשִׁים מַקְרִיבִין מוּסַף רֹאשׁ חֹדֶשׁ אַחַר תָּמִיד שֶׁל שַׁחַר. וְכַמָּה הוּא מוּסַף רֹאשׁ חֹדֶשׁ. פָּרִים שְׁנַיִם וְאַיִל אֶחָד וְשִׁבְעָה כְּבָשִׂים הַכּל עוֹלוֹת. וּשְׂעִיר עִזִּים חַטָּאת:","מַעֲשֵׂה כָּל הָעוֹלוֹת אֶחָד הוּא כְּמַעֲשֵׂה הַתָּמִיד. וּמַעֲשֵׂה הַחַטָּאוֹת שֶׁל רָאשֵׁי חֳדָשִׁים וְשֶׁל מוֹעֲדוֹת כְּמַעֲשֵׂה הַחַטָּאת הַנֶּאֱכֶלֶת שֶׁבֵּאַרְנוּ:","בְּפֶסַח מַקְרִיבִין קָרְבַּן מוּסָף בְּכָל יוֹם. מִיּוֹם הָרִאשׁוֹן עַד יוֹם הַשְּׁבִיעִי כְּמוּסַף רָאשֵׁי חֳדָשִׁים. פָּרִים שְׁנַיִם וְאַיִל אֶחָד וְשִׁבְעָה כְּבָשִׂים הַכּל עוֹלוֹת וּשְׂעִיר חַטָּאת הַנֶּאֱכֶלֶת. בְּיוֹם שֵׁנִי שֶׁל פֶּסַח שֶׁהוּא יוֹם שִׁשָּׁה עָשָׂר בְּנִיסָן מַקְרִיבִין יֶתֶר עַל מוּסָף שֶׁל כָּל יוֹם כֶּבֶשׂ לְעוֹלָה עִם עֹמֶר הַתְּנוּפָה. וְהִיא מִנְחָה שֶׁל צִבּוּר כְּמוֹ שֶׁבֵּאַרְנוּ:","וּזְמַנּוֹ קָבוּעַ וּלְפִיכָךְ דּוֹחֶה אֶת הַשַּׁבָּת וְאֶת הַטֻּמְאָה:","אֵין מְבִיאִין מִנְחָה זוֹ אֶלָּא מֵאֶרֶץ יִשְׂרָאֵל שֶׁנֶּאֱמַר (ויקרא כג י) \"וַהֲבֵאתֶם אֶת עֹמֶר רֵאשִׁית קְצִירְכֶם אֶל הַכֹּהֵן\". מִצְוָתוֹ לָבוֹא מִן הַקָּרוֹב. לֹא בָּא מִן הַקָּרוֹב מְבִיאִין אוֹתָהּ מִכָּל מָקוֹם מֵאֶרֶץ יִשְׂרָאֵל:","מִצְוָתוֹ לְהִקָּצֵר בַּלַּיְלָה בְּלֵיל שִׁשָּׁה עָשָׂר. בֵּין בְּחל בֵּין בְּשַׁבָּת:","וְכָל הַלַּיְלָה כָּשֵׁר לִקְצִירַת הָעֹמֶר. וְאִם קְצָרוּהוּ בַּיּוֹם כָּשֵׁר:","מִצְוָתוֹ לָבוֹא מִן הַקָּמָה. לֹא מָצְאוּ יָבִיאוּ מִן הָעֳמָרִים:","מִצְוָתוֹ לָבוֹא מִן הַלַּח. לֹא מָצְאוּ יָבִיאוּ מִן הַיָּבֵשׁ:","דַּרְכָּן הָיָה לְהָבִיא מִשָּׂדוֹת שֶׁבַּדָּרוֹם. הָיָה נָר חֲצִי הַשָּׂדֶה וְזוֹרֵעַ חֶצְיָהּ בְּשָׁנָה זוֹ וּבְשָׁנָה אַחֶרֶת נָר חֲצִי הַשָּׂדֶה שֶׁזָּרַע וְזוֹרֵעַ הַחֵצִי שֶׁנָּר וּמֵבִיא מִמֶּנּוּ:","עֹמֶר זֶה מִן הַשְּׂעוֹרִים הָיָה בָּא. וְדָבָר זֶה הֲלָכָה מִמּשֶׁה רַבֵּנוּ. וְכֵיצַד הָיָה נַעֲשֶׂה. מֵעֶרֶב יוֹם טוֹב יוֹצְאִין שְׁלוּחֵי בֵּית דִּין וְעוֹשִׂין אוֹתוֹ כְּרִיכוֹת בִּמְחֻבָּר לַקַּרְקַע כְּדֵי שֶׁיִּהְיֶה נֹחַ לִקְצֹר. כָּל הָעֲיָרוֹת הַסְּמוּכוֹת לְשָׁם מִתְכַּנְּסוֹת כְּדֵי שֶׁיִּהְיֶה נִקְצַר בְּעֵסֶק גָּדוֹל. וְקוֹצְרִין שָׁלֹשׁ סְאִין שְׂעוֹרִין בִּשְׁלֹשָׁה אֲנָשִׁים. וּבְשָׁלֹשׁ קֻפּוֹת. וּבִשְׁלֹשָׁה מַגָּלוֹת. כֵּיוָן שֶׁחָשְׁכָה אוֹמֵר לָהֶם הַקּוֹצֵר לְכָל הָעוֹמְדִים שָׁם. בָּא הַשֶּׁמֶשׁ אוֹמְרִין לוֹ הִין. בָּא הַשֶּׁמֶשׁ אוֹמְרִים לוֹ הִין. בָּא הַשֶּׁמֶשׁ אוֹמְרִין לוֹ הִין. מַגָּל זֶה אוֹמְרִין לוֹ הִין. מַגָּל זֶה אוֹמְרִין לוֹ הִין. מַגָּל זֶה אוֹמְרִין לוֹ הִין. קֻפָּה זוֹ אוֹמְרִין לוֹ הִין. קֻפָּה זוֹ אוֹמְרִין לוֹ הִין. קֻפָּה זוֹ אוֹמְרִין לוֹ הִין. וְאִם הָיָה שַׁבָּת אוֹמֵר לָהֶן שַׁבָּת הַיּוֹם אוֹמְרִים לוֹ הִין. שַׁבָּת הַיּוֹם אוֹמְרִין לוֹ הִין. שַׁבָּת הַיּוֹם אוֹמְרִין לוֹ הִין. וְאַחַר כָּךְ אוֹמֵר לָהֶן אֶקְצֹר וְהֵן אוֹמְרִין לוֹ קְצֹר. אֶקְצֹר וְהֵם אוֹמְרִים לוֹ קְצֹר. אֶקְצֹר וְהֵם אוֹמְרִים לוֹ קְצֹר. שָׁלֹשׁ פְּעָמִים עַל כָּל דָּבָר וְדָבָר. וְכָל כָּךְ לָמָּה מִפְּנֵי אֵלּוּ הַטּוֹעִים שֶׁיָּצְאוּ מִכְּלַל יִשְׂרָאֵל בְּבַיִת שֵׁנִי. שֶׁהֵן אוֹמְרִין שֶׁזֶּה שֶׁנֶּאֱמַר בַּתּוֹרָה (ויקרא כג יא) (ויקרא כג טו טז) \"מִמָּחֳרַת הַשַּׁבָּת\" הוּא שַׁבָּת בְּרֵאשִׁית. וּמִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁאֵינָהּ שַׁבָּת אֶלָּא יוֹם טוֹב וְכֵן רָאוּ תָּמִיד הַנְּבִיאִים וְהַסַּנְהֶדְרִין בְּכָל דּוֹר וְדוֹר שֶׁהָיוּ מְנִיפִין אֶת הָעֹמֶר בְּשִׁשָּׁה עָשָׂר בְּנִיסָן בֵּין בְּחל בֵּין בְּשַׁבָּת. וַהֲרֵי נֶאֱמַר בַּתּוֹרָה (ויקרא כג יד) \"וְלֶחֶם וְקָלִי וְכַרְמֶל לֹא תֹאכְלוּ עַד עֶצֶם הַיּוֹם הַזֶּה\". וְנֶאֱמַר (יהושע ה יא) \"וַיֹּאכְלוּ מֵעֲבוּר הָאָרֶץ מִמָּחֳרַת הַפֶּסַח מַצּוֹת וְקָלוּי\". וְאִם תֹּאמַר שֶׁאוֹתוֹ הַפֶּסַח בְּשַׁבָּת אֵרַע כְּמוֹ שֶׁדִּמּוּ הַטִּפְּשִׁים. הֵיאַךְ תָּלָה הַכָּתוּב הֶתֵּר אֲכִילָתָם לֶחָדָשׁ בְּדָבָר שֶׁאֵינוֹ הָעִקָּר וְלֹא הַסִּבָּה אֶלָּא נִקְרָה נִקְרֶה. אֶלָּא מֵאַחַר שֶׁתָּלָה הַדָּבָר בְּמָחֳרַת הַפֶּסַח הַדָּבָר בָּרוּר שֶׁמָּחֳרַת הַפֶּסַח הִיא הָעִלָּה הַמַּתֶּרֶת אֶת הֶחָדָשׁ וְאֵין מַשְׁגִּיחִין עַל אֵי זֶה יוֹם הוּא מִימֵי הַשָּׁבוּעַ:","קְצָרוּהוּ וּנְתָנוּהוּ בְּקֻפּוֹת וֶהֱבִיאוּהוּ לָעֲזָרָה וַחֲבָטוּהוּ. וְזוֹרִין וּבוֹרְרִין. וְלוֹקְחִין אֶת הַשְּׂעוֹרִין וּמְהַבְהֲבִין אוֹתוֹ בָּאוּר. בְּאַבּוּב מְנֻקָּב. כְּדֵי שֶׁיִּהְיֶה הָאֵשׁ שׁוֹלֵט בְּכֻלָּן שֶׁנֶּאֱמַר (ויקרא ב יד) \"אָבִיב קָלוּי בָּאֵשׁ גֶּרֶשׂ כַּרְמֶל\". מִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁאֵינוֹ מְדַבֵּר אֶלָּא בְּמִנְחַת הָעֹמֶר בִּלְבַד. וְאַחַר שֶׁקּוֹלִין אוֹתוֹ שׁוֹטְחִין אוֹתוֹ בָּעֲזָרָה וְהָרוּחַ מְנַשֶּׁבֶת בּוֹ. וְנוֹתְנִין אוֹתוֹ לְרֵחַיִם שֶׁל גָּרוֹסוֹת וְטוֹחֲנִין אֶת הַשָּׁלֹשׁ סְאִין וּמוֹצִיאִין מִן הַכּל עִשָּׂרוֹן שֶׁהוּא מְנֻפֶּה בִּשְׁלֹשׁ עֶשְׂרֵה נָפָה. וְהַשְּׁאָר נִפְדֶּה וְנֶאֱכָל לְכָל אָדָם. וְחַיָּב בְּחַלָּה וּפָטוּר מִן הַמַּעַשְׂרוֹת כְּמוֹ שֶׁבֵּאַרְנוּ. וְלוֹקְחִין זֶה הָעִשָּׂרוֹן שֶׁל סלֶת הַשְּׂעוֹרִים וּבוֹלְלִין אוֹתוֹ בְּלוֹג שֶׁמֶן בְּשִׁשָּׁה עָשָׂר בְּנִיסָן וְנוֹתְנִין עָלָיו קֹמֶץ לְבוֹנָה כִּשְׁאָר הַמְּנָחוֹת. וּמְנִיפוֹ בַּמִּזְרָח מוֹלִיךְ וּמֵבִיא מַעֲלֶה וּמוֹרִיד וּמַגִּישׁוֹ כְּנֶגֶד חֻדָּהּ שֶׁל קֶרֶן מַעֲרָבִית דְּרוֹמִית כִּשְׁאָר הַמְּנָחוֹת. וְקוֹמֵץ וּמַקְטִיר. וְהַשְּׁאָר נֶאֱכָל לַכֹּהֲנִים כִּשְׁיָרֵי כָּל הַמְּנָחוֹת. ואֵימָתַי קוֹמְצִין אוֹתוֹ. לְאַחַר שֶׁמַּקְרִיבִין מוּסַף הַיּוֹם וְכֶבֶשׂ הָעוֹלָה קֹדֶם תָּמִיד שֶׁל בֵּין הָעַרְבַּיִם:","אָסוּר לִקְצֹר בְּאֶרֶץ יִשְׂרָאֵל מִין מֵחֲמֵשֶׁת מִינֵי תְּבוּאָה קֹדֶם לִקְצִירַת הָעֹמֶר שֶׁנֶּאֱמַר (ויקרא כג י) \"רֵאשִׁית קְצִירְכֶם\" שֶׁיִּהְיֶה תְּחִלָּה לְכָל הַנִּקְצָרִים. בַּמֶּה דְּבָרִים אֲמוּרִים בְּקָצִיר שֶׁרָאוּי לְהָבִיא מִמֶּנּוּ עֹמֶר. אֲבָל בֵּית הַשְּׁלָחִין שֶׁבָּעֲמָקִים הוֹאִיל וְאֵינוֹ רָאוּי לְהָבִיא מִמֶּנּוּ קוֹצְרִין אוֹתוֹ מִלִּפְנֵי הָעֹמֶר. אֲבָל לֹא יִגְדּשׁ:","תְּבוּאָה שֶׁהִשְׁרִישָׁה קֹדֶם הָעֹמֶר הָעֹמֶר מַתִּירָהּ. וְאִם לָאו אָסוּר לְקָצְרָהּ כְּדֶרֶךְ שֶׁאָסוּר לְאָכְלָהּ עַד שֶׁיָּבוֹא הָעֹמֶר הַבָּא:","תְּבוּאָה שֶׁלֹּא הֵבִיאָה שְׁלִישׁ מֻתָּר לִקְצֹר מִמֶּנָּה לְהַאֲכִיל לִבְהֵמָה. וְקוֹצְרִין מִפְּנֵי הַנְּטִיעוֹת שֶׁלֹּא יִפָּסְדוּ. וְקוֹצְרִין לְפַנּוֹת מָקוֹם לְבֵית הָאָבֵל אוֹ לְבֵית הַמִּדְרָשׁ. שֶׁנֶּאֱמַר (ויקרא כג י) \"קְצִירְכֶם\" וְלֹא קְצִיר מִצְוָה:","וְאַף עַל פִּי שֶׁמֻּתָּר לִקְצֹר לֹא יַעֲשֶׂה אוֹתָן כְּרִיכוֹת כְּדֶרֶךְ הַקּוֹצְרִין. אֶלָּא יַנִּיחֵם צְבָתִים צְבָתִים:","כְּבָר בֵּאַרְנוּ שֶׁאֵין מְבִיאִין מְנָחוֹת וְלֹא מִנְחַת נְסָכִים וְלֹא בִּכּוּרִים מִן הֶחָדָשׁ קֹדֶם הֲבָאַת הָעֹמֶר. וְאִם הֵבִיא פָּסוּל. וְלֹא יָבִיא קֹדֶם לַהֲבָאַת שְׁתֵּי הַלֶּחֶם. וְאִם הֵבִיא כָּשֵׁר:","וְכָל הַמַּקְרִיב מִנְחָה מִן הֶחָדָשׁ תְּחִלָּה מְבָרֵךְ שֶׁהֶחֱיָינוּ:","תְּבוּאָה שֶׁזְּרָעָהּ אַחַר שֶׁקָּרַב הָעֹמֶר וּקְצָרָהּ אַחַר שֶׁקָּרַב הָעֹמֶר שֶׁל שָׁנָה הַבָּאָה הֲרֵי זוֹ סָפֵק אִם מְבִיאִין מִמֶּנָּה מְנָחוֹת לְכַתְּחִלָּה טֶרֶם הֲבָאַת שְׁתֵּי הַלֶּחֶם הוֹאִיל וּתְבוּאָה זוֹ עָבַר עָלֶיהָ הֲבָאַת שְׁתֵּי הַלֶּחֶם וּקְצִירַת הָעֹמֶר. אוֹ אֵין מְבִיאִין עַד שֶׁיָּבִיאוּ שְׁתֵּי הַלֶּחֶם אַחַר הֲבָאַת הָעֹמֶר שֶׁל שָׁנָה אַחֶרֶת:","וְכֵן תְּבוּאָה שֶׁהָיְתָה בַּקַּרְקַע וְחָנְטוּ עָלֶיהָ אוֹ הֵנֵצּוּ עָלִים שֶׁלָּהּ כְּשֶׁהֵבִיאוּ שְׁתֵּי הַלֶּחֶם הֲרֵי זֶה סָפֵק אִם הֲנָצַת הֶעָלִין אוֹ חֲנָטָתָן כְּמוֹ הֻשְׁרְשָׁה וְהֻתְּרָה לְהָבִיא מִמֶּנָּה מְנָחוֹת אוֹ אֵינָהּ חֲשׁוּבָה הַשְׁרָשָׁה. לְפִיכָךְ לֹא יָבִיא וְאִם הֵבִיא הֻרְצָה:","וְהַקּוֹצֵר קֹדֶם קְצִירַת הָעֹמֶר אֵינוֹ לוֹקֶה וְהַקָּצִיר כָּשֵׁר:","מִצְוַת עֲשֵׂה לִסְפֹּר שֶׁבַע שַׁבָּתוֹת תְּמִימוֹת מִיּוֹם הֲבָאַת הָעֹמֶר שֶׁנֶּאֱמַר (ויקרא כג טו) \"וּסְפַרְתֶּם לָכֶם מִמָּחֳרַת הַשַּׁבָּת\" \"שֶׁבַע שַׁבָּתוֹת\". וּמִצְוָה לִמְנוֹת הַיָּמִים עִם הַשָּׁבוּעוֹת שֶׁנֶּאֱמַר (ויקרא כג טז) \"תִּסְפְּרוּ חֲמִשִּׁים יוֹם\". וּמִתְּחִלַּת הַיּוֹם מוֹנִין לְפִיכָךְ מוֹנֶה בַּלַּיְלָה מִלֵּיל שִׁשָּׁה עָשָׂר בְּנִיסָן:","שָׁכַח וְלֹא מָנָה בַּלַּיְלָה מוֹנֶה בַּיּוֹם וְאֵין מוֹנִין אֶלָּא מְעֻמָּד. וְאִם מָנָה מְיֻשָּׁב יָצָא:","מִצְוָה זוֹ עַל כָּל אִישׁ מִיִּשְׂרָאֵל וּבְכָל מָקוֹם וּבְכָל זְמַן. וְנָשִׁים וַעֲבָדִים פְּטוּרִין מִמֶּנָּה:","וְצָרִיךְ לְבָרֵךְ בְּכָל לַיְלָה בָּרוּךְ אַתָּה ה' אֱלֹקֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ עַל סְפִירַת הָעֹמֶר קֹדֶם שֶׁיִּסְפֹּר. מָנָה וְלֹא בֵּרֵךְ יָצָא וְאֵינוֹ חוֹזֵר וּמְבָרֵךְ:"],"Mishneh Torah, Damages to Property 5":["בְּהֵמָה שֶׁהָיְתָה רוֹעָה וּפָרְשָׁה וְנִכְנְסָה בַּשָּׂדוֹת וּבַכְּרָמִים אַף עַל פִּי שֶׁעֲדַיִן לֹא הִזִּיקָה מַתְרִין בִּבְעָלֶיהָ שָׁלֹשׁ פְּעָמִים. אִם לֹא שָׁמַר בְּהֶמְתּוֹ וְלֹא מְנָעָהּ מִלִּרְעוֹת יֵשׁ רְשׁוּת לְבַעַל הַשָּׂדֶה לְשָׁחֳטָהּ שְׁחִיטָה כְּשֵׁרָה וְאוֹמֵר לִבְעָלֶיהָ בּוֹאוּ וּמִכְרוּ בָּשָׂר שֶׁלָּכֶם. מִפְּנֵי שֶׁאָסוּר לָאָדָם לְהַזִּיק וּלְשַׁלֵּם מַה שֶּׁהִזִּיק אֲפִלּוּ לִגְרֹם הַנֵּזֶק אָסוּר:","לְפִיכָךְ אָסְרוּ חֲכָמִים לְגַדֵּל בְּהֵמָה דַּקָּה וְחַיָּה דַּקָּה בְּאֶרֶץ יִשְׂרָאֵל בִּמְקוֹם הַשָּׂדוֹת וְהַכְּרָמִים אֶלָּא בַּיְעָרִים וּבַמִּדְבָּרוֹת שֶׁבְּאֶרֶץ יִשְׂרָאֵל. וּמְגַדְּלִין בְּסוּרְיָא בְּכָל מָקוֹם:","עֲשָׂרָה תְּנָאִים הִתְנָה יְהוֹשֻׁעַ וּבֵית דִּינוֹ בְּשָׁעָה שֶׁחִלֵּק אֶת הָאָרֶץ וְאֵלּוּ הֵן. א) הִתְנָה שֶׁמַּרְעִין בְּהֵמָה דַּקָּה בִּיעָרִים שֶׁאִילָנֵיהֶן גַּסִּין. אֲבָל אֵין מַרְעִין שָׁם בְּהֵמָה גַּסָּה. וּבְיַעַר שֶׁאִילָנָיו דַּקִּים אֵין מַרְעִין בּוֹ לֹא גַּסָּה וְלֹא דַּקָּה אֶלָּא מִדַּעַת בְּעָלָיו. ב) וְכֵן הִתְנָה שֶׁיִּהְיֶה כָּל אָדָם מֻתָּר לְלַקֵּט עֵצִים מִשְּׂדֵה חֲבֵרוֹ. וְהוּא שֶׁיִּהְיוּ עֵצִים פְּחוּתִים וּקְרוֹבִים לִהְיוֹת קוֹצִים כְּגוֹן הִיזְמֵי וְהִיגֵי. וְהוּא שֶׁיִּהְיוּ לַחִים וּמְחֻבָּרִין וּבִלְבַד שֶׁלֹּא יְשָׁרֵשׁ. אֲבָל שְׁאָר עֵצִים אָסוּר. ג) וְכֵן הִתְנָה שֶׁיִּהְיֶה כָּל אָדָם מֻתָּר לְלַקֵּט עֲשָׂבִים הָעוֹלִין מֵאֲלֵיהֶן בְּכָל מָקוֹם חוּץ מִשְּׂדֵה תִּלְתָּן שֶׁזְּרָעָהּ לִבְהֵמָה. ד) וְכֵן הִתְנָה שֶׁיִּהְיֶה אָדָם קוֹטֵם נְטִיעָה בְּכָל מָקוֹם חוּץ מִגְּרוֹפִיּוֹת שֶׁל זַיִת וְאֵינוֹ קוֹטֵם מִן הָאִילָנוֹת אֶלָּא בְּזַיִת כְּבֵיצָה וּבְקָנִים וּבִגְפָנִים מִן הַפְּקָק וּלְמַעְלָה וּבִשְׁאָר הָאִילָן מִתּוֹכוֹ שֶׁל אִילָן לֹא מֵחֻדּוֹ. וּכְשֶׁהִתִּיר לִקְטֹם לֹא הִתִּיר אֶלָּא מֵחָדָשׁ שֶׁאֵינוֹ עוֹשֶׂה פֵּרוֹת אֲבָל לֹא מִיָּשָׁן שֶׁעוֹשֶׂה פֵּרוֹת. וְאֵינוֹ קוֹטֵם אֶלָּא מִמָּקוֹם שֶׁאֵינוֹ רוֹאֶה פְּנֵי חַמָּה. ה) וְכֵן הִתְנָה שֶׁהַמַּעְיָן הַיּוֹצֵא בַּתְּחִלָּה בְּנֵי אוֹתָהּ הָעִיר שֶׁיָּצָא בִּגְבוּלָם מִסְתַּפְּקִין מִמֶּנּוּ אַף עַל פִּי שֶׁאֵין עִקָּרוֹ בְּחֶלְקָם. וְאֵין לַאֲחֵרִים לְהִסְתַּפֵּק עִמָּהֶם מִמֶּנּוּ. ו) וְכֵן הִתְנָה שֶׁיִּהְיֶה כָּל אָדָם מֻתָּר לָצוּד דָּגִים מִיָּם טְבֶרְיָה וְהוּא שֶׁיָּצוּד בְּחַכָּה בִּלְבַד. אֲבָל לֹא יִפְרשֹׁ קֶלַע וְיַעֲמִיד סְפִינָה שָׁם אֶלָּא בְּנֵי הַשֵּׁבֶט שֶׁהִגִּיעַ אוֹתוֹ הַיָּם בְּחֶלְקָם. ז) וְכֵן הִתְנָה שֶׁכָּל אָדָם שֶׁצָּרִיךְ לִנְקָבָיו מִסְתַּלֵּק מִן הַדֶּרֶךְ וְנִכְנַס אֲחוֹרֵי הַגָּדֵר שֶׁפָּגַע בּוֹ וְנִפְנֶה שָׁם וַאֲפִלּוּ בְּשָׂדֶה מְלֵאָה כַּרְכֹּם וְנוֹטֵל מִשָּׁם צְרוֹר וּמְקַנֵּחַ. ח) וְכֵן הִתְנָה שֶׁכָּל הַתּוֹעֶה בֵּין הַכְּרָמִים וְכַיּוֹצֵא בָּהֶן מְפַסֵּג וְעוֹלֶה מְפַסֵּג וְיוֹרֵד עַד שֶׁיֵּצֵא לְדַרְכּוֹ. ט) וְכֵן הִתְנָה שֶׁבִּזְמַן שֶׁיִּרְבֶּה הַטִּיט בְּדַרְכֵי הָרַבִּים אוֹ נְקִיעֵי מַיִם יֵשׁ לְעוֹבְרֵי דְּרָכִים לְהִסְתַּלֵּק לְצִדְדֵי הַדְּרָכִים וּמְהַלְּכִין שָׁם אַף עַל פִּי שֶׁהֵן מְהַלְּכִין בְּדֶרֶךְ שֶׁיֵּשׁ לָהּ בְּעָלִים. י) וְכֵן הִתְנָה שֶׁמֵּת מִצְוָה קוֹנֶה מְקוֹמוֹ וְנִקְבָּר בַּמָּקוֹם שֶׁיִּמָּצֵא בּוֹ. שֶׁלֹּא יִהְיֶה מֻטָּל עַל הַמֵּצַר וְלֹא בְּתוֹךְ תְּחוּם הַמְּדִינָה. אֲבָל אִם נִמְצָא עַל הַמֵּצַר אוֹ שֶׁהָיָה בְּתוֹךְ הַתְּחוּם מְבִיאוֹ לְבֵית הַקְּבָרוֹת:","שְׁלֹמֹה תִּקֵּן שֶׁיִּהְיוּ עוֹבְרֵי דְּרָכִים מֻתָּרִין בִּימוֹת הַחַמָּה לְהַלֵּךְ בַּשְּׁבִילִין שֶׁבַּשָּׂדוֹת שֶׁיֵּשׁ לָהֶן בְּעָלִים עַד שֶׁתֵּרֵד רְבִיעָה שְׁנִיָּה:","וְתַקָּנוֹת אֵלּוּ כֻּלָּן נוֹהֲגוֹת בְּכָל מָקוֹם אֲפִלּוּ בְּחוּצָה לָאָרֶץ:","וּמִשֶּׁיָּרַד הַטַּל בְּבָבֶל אָסוּר לְהַלֵּךְ בִּשְׁבִילִין שֶׁיֵּשׁ לָהֶן בְּעָלִים:","אַף עַל פִּי שֶׁאֵין מְגַדְּלִין בְּהֵמָה דַּקָּה בְּאֶרֶץ יִשְׂרָאֵל מֻתָּר לַשְׁהוֹתָהּ קֹדֶם לָרֶגֶל שְׁלֹשִׁים יוֹם וְקֹדֶם לְמִשְׁתֵּה בְּנוֹ שְׁלֹשִׁים יוֹם. וְהַטַּבָּח לוֹקֵחַ וְשׁוֹחֵט לוֹקֵחַ וּמַשְׁהֶה עַד שֶׁיִּשְׁחֹט מְעַט מְעַט. וּבִלְבַד שֶׁלֹּא תֵּצֵא וְתִרְעֶה בָּעֵדֶר. אֶלָּא כָּל הַמַּשְׁהֶה מַשְׁהֶה בְּתוֹךְ בֵּיתוֹ כְּדֵי שֶׁלֹּא תַּזִּיק:","וּכְבָר עָשׂוּ בָּבֶל כְּאֶרֶץ יִשְׂרָאֵל לֶאֱסֹר בָּהּ גִּדּוּל בְּהֵמָה דַּקָּה וְחַיָּה דַּקָּה מִפְּנֵי שֶׁהָיוּ רֹב הַשָּׂדוֹת וְהַכְּרָמִים שָׁם בְּאוֹתָן הַיָּמִים שֶׁל יִשְׂרָאֵל:","וְכֵן אָסְרוּ חֲכָמִים לְגַדֵּל חֲזִירִים בְּכָל מָקוֹם. וְלֹא אֶת הַכֶּלֶב אֶלָּא אִם כֵּן הָיָה קָשׁוּר בְּשַׁלְשֶׁלֶת. אֲבָל מְגַדֵּל הוּא כְּלָבִים בָּעִיר הַסְּמוּכָה לַסְּפָר. בַּיּוֹם קוֹשְׁרוֹ וּבַלַּיְלָה מַתִּירוֹ. וְאָמְרוּ חֲכָמִים אָרוּר מְגַדֵּל כְּלָבִים וַחֲזִירִים מִפְּנֵי שֶׁהֶזֵּקָן מְרֻבֶּה וּמָצוּי:","רוֹעֶה שֶׁעָשָׂה תְּשׁוּבָה אֵין מְחַיְּבִין אוֹתוֹ לִמְכֹּר מִיָּד אֶלָּא מוֹכֵר עַל יָד עַל יָד. וְכֵן מִי שֶׁנָּפְלוּ לוֹ כְּלָבִים וַחֲזִירִים בִּירֻשָּׁה אֵין מְחַיְּבִין אוֹתוֹ לִמְכֹּר מִיָּד אֶלָּא מוֹכֵר מְעַט מְעַט:"],"Mishneh Torah, Defilement by Leprosy 16":["בַּיִת הַמְנֻגָּע אָב מֵאֲבוֹת הַטֻּמְאוֹת כָּל הַנּוֹגֵעַ בּוֹ נִטְמָא. וְכֵן אֲבָנִים שֶׁחוֹלְצִין מִמֶּנּוּ אַחַר הֶסְגֵּר אוֹ אֲבָנִים וְעֵצִים וְעָפָר שֶׁל בַּיִת כְּשֶׁנּוֹתְצִין אוֹתוֹ כֻּלָּן אֲבוֹת טֻמְאוֹת. וְכָל כְּזַיִת מֵהֶם מְטַמֵּא אָדָם וְכֵלִים בְּמַגָּע וּבְמַשָּׂא וּבְבִיאָה. כֵּיצַד. אִם נִכְנַס כְּזַיִת מֵהֶן לְבַיִת טָהוֹר נִטְמָא כָּל אֲשֶׁר בַּבַּיִת מֵאָדָם וְכֵלִים שֶׁכֻּלָּן מְטַמְּאִין בְּבִיאָה כְּאָדָם מְצֹרָע וְכֻלָּן אֲסוּרִין בַּהֲנָאָה. וְאִם שְׂרָפָן וְעָשָׂה מֵהֶן סִיד הֲרֵי זֶה אָסוּר בַּהֲנָאָה שֶׁנֶּאֱמַר (ויקרא יד מד) \"צָרַעַת מַמְאֶרֶת\" תֵּן בּוֹ מְאֵרָה וְאַל תֵּהָנֶה בּוֹ. וְכֻלָּן מְשַׁלְּחִין אוֹתָן חוּץ לָעִיר אַף עַל פִּי שֶׁאֵינָהּ מֻקֶּפֶת חוֹמָה:","בַּיִת מֻסְגָּר אֵינוֹ מְטַמֵּא אֶלָּא מִתּוֹכוֹ שֶׁנֶּאֱמַר (ויקרא יד מו) \"וְהַבָּא אֶל הַבַּיִת כָּל יְמֵי הִסְגִּיר אֹתוֹ יִטְמָא עַד הָעָרֶב\". אֲבָל הַמֻּחְלָט מְטַמֵּא מִתּוֹכוֹ וּמֵאֲחוֹרָיו שֶׁהַנּוֹגֵעַ בּוֹ מֵאֲחוֹרָיו טָמֵא שֶׁנֶּאֱמַר (ויקרא יד מד) \"צָרַעַת מַמְאֶרֶת\" (ויקרא יד מד) \"בַּבַּיִת טָמֵא הוּא\" וְכִי טָהוֹר הָיָה אֶלָּא לְהוֹסִיף לוֹ טֻמְאָה עַל טֻמְאָתוֹ שֶׁיִּהְיֶה כֻּלּוֹ טָמֵא וִיטַמֵּא מֵאֲחוֹרָיו. וְכֵן אֲבָנִים שֶׁיֵּשׁ בָּהֶן הַנֶּגַע בְּמֻסְגָּר מְטַמְּאִין מֵאֲחוֹרֵיהֶן:","אֶחָד הַמֻּסְגָּר וְהַמֻּחְלָט מְטַמֵּא בְּבִיאָה. כֵּיצַד. בַּיִת שֶׁהָיָה מֵסֵךְ עַל גַּבֵּי בַּיִת מְנֻגָּע בֵּין מֻחְלָט בֵּין מֻסְגָּר אוֹ אִילָן שֶׁהוּא מֵסֵךְ עָלָיו הָעוֹמֵד תַּחַת הָאִילָן אוֹ הַנִּכְנָס לַבַּיִת הַחִיצוֹן טָמֵא. שֶׁהֲרֵי הוּא וְהַבַּיִת הַטָּמֵא תַּחַת אֹהֶל אֶחָד. וְכֵן אֶבֶן מְנֻגַּעַת הַנִּכְנֶסֶת לְאֹהֶל וְהֻנְחָה שָׁם נִטְמָא כָּל אֲשֶׁר בָּאֹהֶל. הָיְתָה מֻנַּחַת תַּחַת הָאִילָן וְהַטָּהוֹר עוֹבֵר נִטְמָא. הָיָה הַטָּהוֹר עוֹמֵד תַּחַת הָאִילָן וְעָבַר אָדָם בְּאֶבֶן מְנֻגַּעַת לֹא טִמְּאָהוּ. וְאִם הִנִּיחָהּ שָׁם טִמְּאָהוּ שֶׁמּוֹשָׁב הַמְנֻגָּע כָּמוֹהוּ בֵּין אָדָם בֵּין כֵּלִים בֵּין אֲבָנִים וְעֵצָיו וַעֲפָרוֹ:","הַמַּאֲהִיל בְּיָדוֹ עַל אֶבֶן מְנֻגַּעַת אוֹ שֶׁהֶאֱהִילָה עָלָיו טָהוֹר עַד שֶׁיִּגַּע:","טָהוֹר שֶׁנִּכְנַס לְבַיִת מְנֻגָּע דֶּרֶךְ אֲחוֹרָיו אֲפִלּוּ נִכְנַס כֻּלּוֹ חוּץ מֵחָטְמוֹ טָהוֹר שֶׁנֶּאֱמַר (ויקרא יד מו) \"וְהַבָּא אֶל הַבַּיִת\" דֶּרֶךְ בִּיאָה טִמְּאָה תּוֹרָה:","טָהוֹר שֶׁהִכְנִיס רֹאשׁוֹ וְרֻבּוֹ לְבַיִת טָמֵא נִטְמָא. וְכֵן טַלִּית טְהוֹרָה שֶׁהִכְנִיס מִמֶּנָּה שָׁלֹשׁ עַל שָׁלֹשׁ לְבַיִת טָמֵא נִטְמֵאת. וְכֵן כְּלִי חֶרֶס שֶׁהִכְנִיס אֲוִירוֹ לְבַיִת טָמֵא נִטְמָא. אֲבָל שְׁאָר כֵּלִים עַד שֶׁיַּכְנִיס רֹב הַכֵּלִים, מִשֶּׁיַּכְנִיס רֻבּוֹ נִטְמָא מִיָּד. בַּמֶּה דְּבָרִים אֲמוּרִים בְּכֵלִים שֶׁנִּכְנְסוּ חֲלוּצִין. אֲבָל אָדָם מִיִּשְׂרָאֵל שֶׁנִּכְנַס לְבַיִת מְנֻגָּע וְהוּא לָבוּשׁ בִּבְגָדָיו וְסַנְדָּלָיו בְּרַגְלָיו וְטַבְּעוֹתָיו בְּיָדָיו הֲרֵי הָאָדָם טָמֵא מִיָּד. וּבְגָדָיו טְהוֹרִים עַד שֶׁיַּשְׁהֶה שָׁם כְּדֵי שֶׁיָּסֵב אָדָם וְיֹאכַל כְּשָׁלֹשׁ בֵּיצִים פַּת חִטִּים בְּלִפְתָּן שֶׁנֶּאֱמַר (ויקרא יד מז) \"וְהַשֹּׁכֵב בַּבַּיִת יְכַבֵּס אֶת בְּגָדָיו וְהָאֹכֵל בַּבַּיִת יְכַבֵּס אֶת בְּגָדָיו\". וְכִי תַּעֲלֶה עַל דַּעְתְּךָ שֶׁאֵין בְּגָדָיו מִתְטַמְּאִין עַד שֶׁיֹּאכַל שָׁם. אֶלָּא לִתֵּן שִׁעוּר לַשּׁוֹכֵב כְּאוֹכֵל. וְאַחַד הַשּׁוֹכֵב אוֹ הַיּוֹשֵׁב אוֹ הָעוֹמֵד אִם שָׁהָה כְּדֵי לֶאֱכל שִׁעוּר אֲכִילָה הָאֲמוּרָה נִטְמְאוּ בְּגָדָיו:","מִי שֶׁנִּכְנַס לְבַיִת מְנֻגָּע וְכֵלָיו עַל כְּתֵפָיו וְסַנְדָּלוֹ וְטַבַּעְתּוֹ בְּכַפָּיו הוּא וְהֵן טְמֵאִין מִיָּד שֶׁאֵינוֹ מַצִּיל מִלְּטַמֵּא מִיָּד אֶלָּא כֵּלִים שֶׁהוּא לָבוּשׁ בָּהֶן. וְכֵן הָעַכּוּ\"ם וְהַבְּהֵמָה שֶׁהָיוּ לְבוּשִׁין בְּכֵלִים וְנִכְנְסוּ לַבַּיִת הַמְנֻגָּע נִטְמְאוּ הַכֵּלִים מִיָּד. אֲבָל הָעַכּוּ\"ם אֵינוֹ מְקַבֵּל טֻמְאָה כִּבְהֵמָה:","מִי שֶׁהָיָה עוֹמֵד בְּבַיִת מְנֻגָּע וּפָשַׁט יָדָיו חוּץ לַבַּיִת וְטַבְּעוֹתָיו בְּיָדָיו אִם שָׁהָה כְּדֵי אֲכִילַת הַשִּׁעוּר נִטְמְאוּ הַטַּבָּעוֹת אַף עַל פִּי שֶׁהֵם בַּחוּץ. וְכֵן הָעוֹמֵד בַּחוּץ וּפָשַׁט יָדוֹ לְבַיִת מְנֻגָּע נִטְמְאוּ יָדָיו בִּלְבַד מִיָּד. וְאִם נִשְׁתַּהוּ שָׁם כְּדֵי אֲכִילַת הַשִּׁעוּר נִטְמְאוּ טַבְּעוֹתָיו וְאִם לָאו טְהוֹרוֹת:","כָּל הַמַּצִּיל בְּצָמִיד פָּתִיל בְּאֹהֶל הַמֵּת מַצִּיל מְכֻסֶּה בְּבַיִת מְנֻגָּע. וְכָל הַמַּצִּיל מְכֻסֶּה בְּאֹהֶל הַמֵּת אֲפִלּוּ הָיָה מְגֻלֶּה בְּבַיִת הַמְנֻגָּע הֲרֵי זֶה טָהוֹר. כֵּיצַד. כְּלֵי חֶרֶס אוֹ כְּלֵי אֲבָנִים וּכְלֵי אֲדָמָה וְכַיּוֹצֵא בָּהֶן שֶׁהָיוּ אֳכָלִין וּמַשְׁקִין וְכֵלִים בְּתוֹכָן וְהָיוּ מְכֻסִּין בְּבַיִת הַמְנֻגָּע אַף עַל פִּי שֶׁאֵינָן מֻקָּפִין צָמִיד פָּתִיל הֵן וְכָל מַה שֶּׁבְּתוֹכָן טָהוֹר. הַבּוֹר וְהַדּוּת שֶׁבְּבַיִת הַמְנֻגָּע אַף עַל פִּי שֶׁהֵן מְגֻלִּין כֵּלִים שֶׁבְּתוֹכָן טְהוֹרִין:","הַצָּרַעַת הוּא שֵׁם הָאָמוּר בְּשֻׁתָּפוּת כּוֹלֵל עִנְיָנִים הַרְבֵּה שֶׁאֵין דּוֹמִין זֶה לָזֶה. שֶׁהֲרֵי לֹבֶן עוֹר הָאָדָם קָרוּי צָרַעַת. וּנְפִילַת קְצָת שְׂעַר הָרֹאשׁ אוֹ הַזָּקָן קָרוּי צָרַעַת. וְשִׁנּוּי עֵין הַבְּגָדִים אוֹ הַבָּתִּים קָרוּי צָרַעַת. וְזֶה הַשִּׁנּוּי הָאָמוּר בַּבְּגָדִים וּבַבָּתִּים שֶׁקְּרָאַתּוּ תּוֹרָה צָרַעַת בְּשֻׁתָּפוּת הַשֵּׁם אֵינוֹ מִמִּנְהָגוֹ שֶׁל עוֹלָם אֶלָּא אוֹת וּפֶלֶא הָיָה בְּיִשְׂרָאֵל כְּדֵי לְהַזְהִירָן מִלָּשׁוֹן הָרַע. שֶׁהַמְסַפֵּר בְּלָשׁוֹן הָרַע מִשְׁתַּנּוֹת קִירוֹת בֵּיתוֹ. אִם חָזַר בּוֹ יִטְהַר הַבַּיִת. אִם עָמַד בְּרִשְׁעוֹ עַד שֶׁהֻתַּץ הַבַּיִת מִשְׁתַּנִּין כְּלֵי הָעוֹר שֶּׁבְּבֵיתוֹ שֶׁהוּא יוֹשֵׁב וְשׁוֹכֵב עֲלֵיהֶן. אִם חָזַר בּוֹ יִטְהֲרוּ. וְאִם עָמַד בְּרִשְׁעוֹ עַד שֶׁיִּשָּׂרְפוּ מִשְׁתַּנִּין הַבְּגָדִים שֶׁעָלָיו. אִם חָזַר בּוֹ יִטְהֲרוּ וְאִם עָמַד בְּרִשְׁעוֹ עַד שֶׁיִּשָּׂרְפוּ מִשְׁתַּנֶּה עוֹרוֹ וְיִצְטָרֵעַ וְיִהְיֶה מֻבְדָּל וּמְפֻרְסָם לְבַדּוֹ עַד שֶׁלֹּא יִתְעַסֵּק בְּשִׂיחַת הָרְשָׁעִים שֶׁהוּא הַלֵּיצָנוּת וְלָשׁוֹן הָרַע. וְעַל עִנְיָן זֶה מַזְהִיר בַּתּוֹרָה וְאוֹמֵר (דברים כד ח) \"הִשָּׁמֶר בְּנֶגַע הַצָּרַעַת\" (דברים כד ט) \"זָכוֹר אֵת אֲשֶׁר עָשָׂה ה' אֱלֹהֶיךָ לְמִרְיָם בַּדֶּרֶךְ\". הֲרֵי הוּא אוֹמֵר הִתְבּוֹנְנוּ מָה אֵרַע לְמִרְיָם הַנְּבִיאָה שֶׁדִּבְּרָה בְּאָחִיהָ שֶׁהָיְתָה גְּדוֹלָה מִמֶּנּוּ בְּשָׁנִים וְגִּדְלַתּוּ עַל בִּרְכֶּיהָ וְסִכְּנָה בְּעַצְמָהּ לְהַצִּילוֹ מִן הַיָּם וְהִיא לֹא דִּבְּרָה בִּגְנוּתוֹ אֶלָּא טָעֲתָה שֶׁהִשְׁוַתּוּ לִשְׁאָר נְבִיאִים וְהוּא לֹא הִקְפִּיד עַל כָּל הַדְּבָרִים הָאֵלּוּ שֶׁנֶּאֱמַר (במדבר יב ג) \"וְהָאִישׁ משֶׁה עָנָו מְאֹד\" וְאַף עַל פִּי כֵן מִיָּד נֶעֶנְשָׁה בְּצָרַעַת. קַל וָחֹמֶר לִבְנֵי אָדָם הָרְשָׁעִים הַטִּפְּשִׁים שֶׁמַּרְבִּים לְדַבֵּר גְּדוֹלוֹת וְנִפְלָאוֹת. לְפִיכָךְ רָאוּי לְמִי שֶׁרוֹצֶה לְכַוֵּן אָרְחוֹתָיו לְהִתְרַחֵק מִישִׁיבָתָן וּמִלְּדַבֵּר עִמָּהֶן כְּדֵי שֶׁלֹּא יִתָּפֵס אָדָם בְּרֶשֶׁת רְשָׁעִים וְסִכְלוּתָם. וְזֶה דֶּרֶךְ יְשִׁיבַת הַלֵּצִים הָרְשָׁעִים בַּתְּחִלָּה מַרְבִּין בְּדִבְרֵי הֲבַאי כָּעִנְיָן שֶׁנֶּאֱמַר (קהלת ה ב) \"וְקוֹל כְּסִיל בְּרֹב דְּבָרִים\". וּמִתּוֹךְ כָּךְ בָּאִין לְסַפֵּר בִּגְנוּת הַצַּדִּיקִים כָּעִנְיָן שֶׁנֶּאֱמַר (תהילים לא יט) \"תֵּאָלַמְנָה שִׂפְתֵי שָׁקֶר הַדֹּבְרוֹת עַל צַדִּיק עָתָק\". וּמִתּוֹךְ כָּךְ יִהְיֶה לָהֶן הֶרְגֵּל לְדַבֵּר בַּנְּבִיאִים וְלָתֵת דֹּפִי בְּדִבְרֵיהֶם כָּעִנְיָן שֶׁנֶּאֱמַר (דברי הימים ב לו טז) \"וַיִּהְיוּ מַלְעִבִים בְּמַלְאֲכֵי הָאֱלֹהִים וּבוֹזִים דְּבָרָיו וּמִתַּעְתְּעִים בִּנְבִאָיו\". וּמִתּוֹךְ כָּךְ בָּאִין לְדַבֵּר בֵּאלֹהִים וְכוֹפְרִין בָּעִקָּר כָּעִנְיָן שֶׁנֶּאֱמַר (מלכים ב יז ט) \"וַיְחַפְּאוּ בְנֵי יִשְׂרָאֵל דְּבָרִים אֲשֶׁר לֹא כֵן עַל ה' אֱלֹהֵיהֶם\". וַהֲרֵי הוּא אוֹמֵר (תהילים עג ט) \"שַׁתּוּ בַשָּׁמַיִם פִּיהֶם וּלְשׁוֹנָם תִּהֲלַךְ בָּאָרֶץ\" מִי גָּרַם לָהֶם לָשִׁית בַּשָּׁמַיִם פִּיהֶם לְשׁוֹנָם שֶׁהָלְכָה תְּחִלָּה בָּאָרֶץ. זוֹ הִיא שִׂיחַת הָרְשָׁעִים שֶׁגּוֹרֶמֶת לָהֶן יְשִׁיבַת קְרָנוֹת וִישִׁיבַת כְּנֵסִיּוֹת שֶׁל עַמֵּי הָאָרֶץ וִישִׁיבַת בָּתֵּי מִשְׁתָּאוֹת עִם שׁוֹתֵי שֵׁכָר. אֲבָל שִׂיחַת כְּשֵׁרֵי יִשְׂרָאֵל אֵינָהּ אֶלָּא בְּדִבְרֵי תּוֹרָה וְחָכְמָה. לְפִיכָךְ הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹזֵר עַל יָדָן וּמְזַכֶּה אוֹתָן בָּהּ. שֶׁנֶּאֱמַר (מלאכי ג טז) \"אָז נִדְבְּרוּ יִרְאֵי ה' אִישׁ אֶל רֵעֵהוּ וַיַּקְשֵׁב ה' וַיִּשְׁמָע וַיִּכָּתֵב סֵפֶר זִכָּרוֹן לְפָנָיו לְיִרְאֵי ה' וּלְחשְׁבֵי שְׁמוֹ\": סְלִיקוּ לְהוּ הִלְכוֹת טֻמְאַת צָרַעַת"],"Mishneh Torah, Defilement by a Corpse 12":["טֶפַח עַל טֶפַח מְרֻבָּע עַל רוּם טֶפַח מֵבִיא אֶת הַטֻּמְאָה וְחוֹצֵץ בִּפְנֵי הַטֻּמְאָה דִּין תּוֹרָה. שֶׁאֵין קָרוּי אֹהֶל אֶלָּא טֶפַח עַל טֶפַח בְּרוּם טֶפַח אוֹ יֶתֶר עַל זֶה. כֵּיצַד. כְּזַיִת מִן הַמֵּת מֻנָּח לַאֲוִיר וּבְצִדּוֹ כֵּלִים כְּגוֹן מְחָטִין וְצִנּוֹרוֹת וְכַיּוֹצֵא בָּהֶן וְאֵינָן נוֹגְעִים בְּטֻמְאָה. אִם הֶאֱהִיל עֲלֵיהֶן אֹהֶל שֶׁיֵּשׁ בּוֹ טֶפַח עַל טֶפַח וְהָיָה גָּבוֹהַּ מֵעַל הָאָרֶץ טֶפַח הֲרֵי זֶה מֵבִיא אֶת הַטֻּמְאָה לַכֵּלִים וּטְמֵאִין. הָיוּ כֵּלִים אֲחֵרִים עַל גַּבֵּי אֹהֶל זֶה שֶׁיֵּשׁ בּוֹ טֶפַח עַל טֶפַח הֲרֵי הֵן טְהוֹרִין. מִפְּנֵי שֶׁהָאֹהֶל חוֹצֵץ בֵּינָם וּבֵין הַטֻּמְאָה. הִנֵּה לָמַדְתָּ שֶׁכְּשֵׁם שֶׁהָאֹהֶל מְטַמֵּא כָּל שֶׁתַּחְתָּיו מַצִּיל כָּל שֶׁחוּצָה לוֹ וְחוֹצֵץ בֵּין הַטֻּמְאָה וּבֵין כֵּלִים שֶׁעַל גַּבָּיו. וְכֵן אִם הָיְתָה הַטֻּמְאָה עַל גַּבָּיו וְכֵלִים תַּחְתָּיו הַכֵּלִים טְהוֹרִין. שֶׁהָאֹהֶל חוֹצֵץ בִּפְנֵי הַטֻּמְאָה. הָיָה הָאֹהֶל פָּחוֹת מֵרוּם טֶפַח אוֹ פָּחוֹת מִטֶּפַח עַל טֶפַח. אַף עַל פִּי שֶׁהוּא גָּבוֹהַּ כַּמָּה טְפָחִים הַכֵּלִים שֶׁבְּצַד הַטֻּמְאָה טְהוֹרִים וְכֵלִים שֶׁלְּמַעְלָה מֵאֹהֶל זֶה כָּל שֶׁכְּנֶגֶד הַטֻּמְאָה טָמֵא מִפְּנֵי שֶׁהֶאֱהִילוּ עַל הַטֻּמְאָה וְאֵין שָׁם אֹהֶל לָחֹץ בִּפְנֵי הַטֻּמְאָה. וְכֵן אִם הָיְתָה טֻמְאָה עַל גַּבֵּי אֹהֶל זֶה וְכֵלִים תַּחְתָּיו כָּל שֶׁכְּנֶגֶד הַטֻּמְאָה טָמֵא שֶׁהֲרֵי הֶאֱהִילָה עֲלֵיהֶן וְאֵין שָׁם אֹהֶל שֶׁיָּחֹץ בִּפְנֵי הַטֻּמְאָה שֶׁכָּל פָּחוֹת מֵרוּם טֶפַח כִּנְגִיעָה הוּא חָשׁוּב. וְטֻמְאָה שֶׁתַּחְתָּיו טֻמְאָה רְצוּצָה הִיא כְּמוֹ שֶׁבֵּאַרְנוּ. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁלֹּא הָיָה הָאֹהֶל אָדָם אוֹ כֵּלִים. אֲבָל אָדָם אוֹ כֵּלִים שֶׁנַּעֲשׂוּ אֹהֶל עַל הַטֻּמְאָה בֵּין שֶׁהָיוּ הֵן עַצְמָן אֹהֶל בֵּין שֶׁהָיוּ עַמּוּדֵי הָאֹהֶל אֲפִלּוּ הָיוּ כֵּלִים שֶׁאֵין מְקַבְּלִין טֻמְאָה כָּל עִקָּר הֲרֵי אֵלּוּ מְבִיאִין אֶת הַטֻּמְאָה וְאֵינָן חוֹצְצִין בִּפְנֵי הַטֻּמְאָה. כֵּיצַד. לוּחַ שֶׁהָיָה מֻנָּח עַל גַּבֵּי אַרְבָּעָה בְּנֵי אָדָם אוֹ עַל גַּבֵּי אַרְבָּעָה כֵּלִים אֲפִלּוּ כְּלֵי אֲבָנִים וְכַיּוֹצֵא בָּהֶן מִכֵּלִים שֶׁאֵין לְמִינָן טֻמְאָה. וְאֵין צָרִיךְ לוֹמַר אִם הָיָה מֻנָּח עַל אַרְבָּעָה שִׁפּוּדִין אוֹ אַרְבָּעָה קָנִים שֶׁגְּבוֹהִין טֶפַח. וְהָיְתָה טֻמְאָה וְכֵלִים תַּחְתָּיו הַכֵּלִים טְמֵאִים. וְאִם הָיוּ כֵּלִים עַל גַּבָּיו אֲפִלּוּ שֶׁלֹּא כְּנֶגֶד הַטֻּמְאָה טְמֵאִים. וְאִם הָיְתָה טֻמְאָה עַל גַּבֵּי לוּחַ וְכֵלִים תַּחְתָּיו כָּל כֵּלִים שֶׁתַּחַת הַלּוּחַ טְמֵאִין. אֲבָל אִם הַלּוּחַ הָיָה מֻנָּח עַל גַּבֵּי אַרְבַּע אֲבָנִים אוֹ עַל גַּבֵּי בְּהֵמָה וְחַיָּה. וְהָיְתָה טֻמְאָה תַּחְתָּיו הֲרֵי הַכֵּלִים שֶׁעַל גַּבָּיו טְהוֹרִין:","הָיְתָה טֻמְאָה עַל גַּבָּיו הֲרֵי כָּל הַכֵּלִים שֶׁתַּחְתָּיו טְהוֹרִין מִפְּנֵי שֶׁהָאֹהֶל חוֹצֵץ בִּפְנֵי הַטֻּמְאָה. וּכְלֵי גְּלָלִים וּכְלֵי אֲבָנִים וּכְלֵי אֲדָמָה הַבָּאִים בְּמִדָּה הֲרֵי הֵם כְּאֹהָלִים וְאֵינָם כְּכֵלִים וּלְפִיכָךְ חוֹצְצִים בִּפְנֵי הַטֻּמְאָה:","נֶסֶר שֶׁהוּא נָתוּן עַל פִּי תַּנּוּר חָדָשׁ וְעוֹדֵף מִכָּל צְדָדָיו בְּפוֹתֵחַ טֶפַח. הָיְתָה טֻמְאָה תַּחַת הַנֶּסֶר כֵּלִים שֶׁעַל גַּבָּיו טְהוֹרִין. טֻמְאָה עַל גַּבָּיו כֵּלִים שֶׁתַּחְתָּיו טְהוֹרִים מִפְּנֵי שֶׁתַּנּוּר חָדָשׁ אֵינוֹ כְּכֵלִים לְעִנְיָן זֶה. וְאִם הָיָה יָשָׁן הַכּל טָמֵא:","נֶסֶר שֶׁהוּא נָתוּן עַל פִּי שְׁנֵי תַּנּוּרִים אֲפִלּוּ יְשָׁנִים וְעוֹדֵף מִחוּצָה לְתַנּוּר זֶה וּמִחוּצָה לְתַנּוּר זֶה וְהָיְתָה טֻמְאָה תַּחְתָּיו בֵּין שְׁנֵי הַתַּנּוּרִים בֵּינֵיהֶן בִּלְבַד טָמֵא. אֲבָל כֵּלִים שֶׁתַּחַת שְׁתֵּי הַקְּצָווֹת שֶׁחוּצָה לַתַּנּוּרִים טְהוֹרִים שֶׁהֲרֵי הֵן כִּשְׁנֵי אֹהָלִים זֶה בְּצַד זֶה. וְכֵן נֶסֶר שֶׁהוּא נָתוּן עַל פִּי תַּנּוּר אֲפִלּוּ יָשָׁן וְיוֹצֵא מִזֶּה טֶפַח וּמִזֶּה טֶפַח אֲבָל לֹא מִן הַצְּדָדִין וְטֻמְאָה בְּצַד זֶה כֵּלִים שֶׁבַּצַּד הַשֵּׁנִי טְהוֹרִין:","אָדָם שֶׁנָּשָׂא כְּלִי כְּגוֹן מִרְדַּעַת וְכַיּוֹצֵא בּוֹ וְהֶאֱהִיל צַד הַכְּלִי הָאֶחָד עַל הַטֻּמְאָה אִם הָיָה בְּהֶקֵּפוֹ טֶפַח אַף עַל פִּי שֶׁאֵין בְּרָחְבּוֹ אֶלָּא רֹחַב אֶצְבַּע וּשְׁלִישׁ הֲרֵי זֶה מְטַמֵּא אֶת הַנּוֹשֵׂא וּמֵבִיא לוֹ טֻמְאָה מִדִּבְרֵיהֶם שֶׁגָּזְרוּ עַל שֶׁיֵּשׁ בְּהֶקֵּפוֹ טֶפַח מִשּׁוּם שֶׁיֵּשׁ בְּרָחְבּוֹ טֶפַח. אֲבָל אֵינוֹ מֵבִיא אֶת הַטֻּמְאָה לַכֵּלִים שֶׁתַּחְתָּיו וְלִשְׁאָר אָדָם שֶׁיַּאֲהִיל עֲלֵיהֶן וְעַל הַטֻּמְאָה עַד שֶׁיִּהְיֶה בּוֹ רֹחַב טֶפַח:","אֲרוֹנוֹת שֶׁל עֵץ שֶׁמַּנִּיחִין בָּהֶן אֶת הַמֵּת אֵינָן כְּקֶבֶר (אֲבָל) אִם יֵשׁ בֵּין כִּסּוּי הָאָרוֹן וְהַמֵּת גֹּבַהּ טֶפַח חוֹצֵץ וְהָעוֹמֵד עַל גַּבֵּי הָאָרוֹן טָהוֹר מִן הַתּוֹרָה. וְאַף עַל פִּי שֶׁרֹב אֲרוֹנוֹת יֵשׁ בָּהֶן חֲלַל טֶפַח הוֹאִיל וְיֵשׁ שֶׁאֵין שָׁם חֲלַל טֶפַח גָּזְרוּ עַל כָּל הָאֲרוֹנוֹת שֶׁאֵינָן חוֹצְצִין וְשֶׁיִּהְיֶה הַמְהַלֵּךְ עַל גַּבֵּי הָאָרוֹן כְּנוֹגֵעַ בַּמֵּת אוֹ בַּקֶּבֶר:","קוֹרָה שֶׁהִיא נְתוּנָה מִכֹּתֶל לְכֹתֶל וְהַטֻּמְאָה תַּחְתֶּיהָ אִם יֵשׁ בָּהּ פּוֹתֵחַ טֶפַח מְבִיאָה אֶת הַטֻּמְאָה תַּחַת כֻּלָּהּ וְכָל הַכֵּלִים אוֹ אָדָם שֶׁתַּחְתֶּיהָ טְמֵאִים אַף עַל פִּי שֶׁאֵין כֻּלָּהּ שָׁוָה וּקְצָתוֹ פְּחוּתָה מִטֶּפַח מִפְּנֵי שֶׁקְּצָתָהּ מִקְצָת אֹהֶל הוּא. וְאִם אֵין בָּהּ פּוֹתֵחַ טֶפַח טֻמְאָה בּוֹקַעַת וְעוֹלָה בּוֹקַעַת וְיוֹרֶדֶת כְּמוֹ שֶׁבֵּאַרְנוּ. כַּמָּה יִהְיֶה בְּהֶקֵּפָהּ וְיִהְיֶה בָּהּ פּוֹתֵחַ טֶפַח. בִּזְמַן שֶׁהִיא עֲגֻלָּה שְׁלֹשָׁה טְפָחִים וּבִזְמַן שֶׁהִיא מְרֻבַּעַת אַרְבָּעָה טְפָחִים:","סְאָה שֶׁהִיא מֻטָּה עַל צִדָּה בָּאֲוִיר אֵינָהּ מְבִיאָה אֶת הַטֻּמְאָה תַּחַת כֻּלָּהּ עַד שֶׁיִּהְיֶה בְּהֶקֵּפָהּ אַרְבָּעָה טְפָחִים וּמֶחֱצָה בְּקֵרוּב. כְּדֵי שֶׁיִּהְיֶה גֹּבַהּ הַצַּד הָעֶלְיוֹן טֶפַח וּמֶחֱצָה וְיִהְיֶה הַטֶּפַח עַל טֶפַח מִמֶּנָּה גָּבְהוֹ מֵעַל הָאָרֶץ טֶפַח. לְפִיכָךְ אִם הָיְתָה גְּבוֹהָה מֵעַל הָאָרֶץ חֲצִי טֶפַח וְהָיָה בְּהֶקֵּפָהּ שְׁלֹשָׁה מְבִיאָה אֶת הַטֻּמְאָה. וְכֵן עַמּוּד עָגל שֶׁהוּא מֻטָּל לָאֲוִיר וּמֻנָּח עַל הָאָרֶץ אֵינוֹ מֵבִיא טֻמְאָה תַּחַת דָּפְנוֹ עַד שֶׁיִּהְיֶה בּוֹ הֶקֵּף כ\"ד טְפָחִים וְאִם אֵין בְּהֶקֵּפוֹ עֶשְׂרִים וְאַרְבָּעָה טְפָחִים טֻמְאָה בּוֹקַעַת וְעוֹלָה בּוֹקַעַת וְיוֹרֶדֶת. זֶה שֶׁהִצְרִיכוּ עֶשְׂרִים וְאַרְבָּעָה טְפָחִים עַל הָעִקָּרִין שֶׁסּוֹמְכִים עֲלֵיהֶן חֲכָמִים בְּחֶשְׁבּוֹן כָּל הַמִּשְׁפָּטִים. שֶׁכָּל שֶׁיֵּשׁ בְּהֶקֵּפוֹ שְׁלֹשָׁה יֵשׁ בּוֹ רֹחַב טֶפַח. וְכָל טֶפַח עַל טֶפַח בָּרִבּוּעַ יֵשׁ בַּאֲלַכְסוֹנוֹ טֶפַח וּשְׁנֵי חֳמָשִׁין. לְפִיכָךְ אִם הָיָה בְּהֶקֵּף הָעַמּוּד עֶשְׂרִים וְאַרְבָּעָה טְפָחִים נִמְצָא תַּחַת כָּל דָּפְנוֹ טֶפַח עַל רוּם טֶפַח מְרֻבָּע וְיֶתֶר מְעַט. שֶׁחֶשְׁבּוֹנוֹת אֵלּוּ בְּקֵרוּב הֵן:"],"Mishneh Torah, Defilement by a Corpse 23":["כָּל הַכֵּלִים הַמַּצִּילִים בְּצָמִיד פָּתִיל מַצִּילִין עַל כָּל מַה שֶּׁבְּתוֹכָן בֵּין אֳכָלִין בֵּין מַשְׁקִין בֵּין בְּגָדִים וּכְלֵי שֶׁטֶף. זֶהוּ דִּין תּוֹרָה. אֲבָל מִדִּבְרֵי סוֹפְרִים שֶׁכְּלִי חֶרֶס הַמֻּקָּף צָמִיד פָּתִיל אֵינוֹ מַצִּיל אֶלָּא עַל הָאֳכָלִין וְעַל הַמַּשְׁקִין וְעַל כְּלֵי חֶרֶס אֲחֵרִים שֶׁיִּהְיוּ בְּתוֹכוֹ. אֲבָל אִם הָיוּ בְּתוֹךְ כְּלִי חֶרֶס הַמֻּקָּף כְּלֵי שֶׁטֶף אוֹ בְּגָדִים הֲרֵי אֵלּוּ טְמֵאִים. וּמִפְּנֵי מָה אָמְרוּ שֶׁלֹּא יַצִּיל עַל הַכּל כִּשְׁאָר כֵּלִים הַמַּצִּילִין. מִפְּנֵי שֶׁשְּׁאָר הַכֵּלִים הַמַּצִּילִין אֵין מְקַבְּלִין טֻמְאָה וּכְלֵי חֶרֶס מְקַבְּלִין טֻמְאָה וּכְלִי טָמֵא אֵינוֹ חוֹצֵץ. וְכָל כְּלֵי עַם הָאָרֶץ בְּחֶזְקַת טֻמְאָה כְּמוֹ שֶׁיִּתְבָּאֵר. וְלָמָּה לֹא אָמְרוּ כְּלִי חֶרֶס שֶׁל עַם הָאָרֶץ לֹא יַצִּיל עַל הַכּל וְשֶׁל חָבֵר יַצִּיל עַל הַכּל שֶׁהֲרֵי הוּא טָהֹר. מִפְּנֵי שֶׁאֵין עַם הָאָרֶץ טָמֵא בְּעֵינֵי עַצְמוֹ, שֶׁאוֹמֵר הוֹאִיל וּכְלִי חֶרֶס מַצִּיל עַל הַכּל אֶחָד אֲנִי וְאֶחָד הֶחָבֵר, וּלְפִיכָךְ חָשׁוּ וְגָזְרוּ שֶׁלֹּא יַצִּיל עַל הַכּל. וְלָמָּה אָמְרוּ מַצִּיל עַל הָאֳכָלִין וְעַל הַמַּשְׁקִין וְעַל כְּלֵי חֶרֶס. מִפְּנֵי שֶׁאֵלּוּ הַשְּׁלֹשָׁה טְמֵאִים הֵן עַל גַּבֵּי עַם הָאָרֶץ בֵּין קֹדֶם שֶׁיִּהְיוּ בְּאֹהֶל הַמֵּת בֵּין אַחַר שֶׁיִּהְיוּ שָׁם תַּחַת צָמִיד פָּתִיל. וּלְעוֹלָם לֹא יִשְׁאַל הֶחָבֵר מֵעַם הָאָרֶץ לֹא אֳכָלִין וְלֹא מַשְׁקִין וְלֹא כְּלֵי חֶרֶס אֶלָּא עַל דַּעַת שֶׁהֵן טְמֵאִין שֶׁהֲרֵי אֵין לָהֶן טָהֳרָה לְעוֹלָם וְלֹא יָבוֹא בָּהֶן לִידֵי תַּקָּלָה. אֲבָל כְּלֵי שֶׁטֶף שׁוֹאֵל אוֹתָם הֶחָבֵר מֵעַם הָאָרֶץ וּמַטְבִּילָן מִפְּנֵי מַגַּע עַם הָאָרֶץ וּמַעֲרִיב שִׁמְשׁוֹ וּמִשְׁתַּמֵּשׁ בָּהֶן בְּטָהֳרוֹת לְפִיכָךְ חָשׁוּ חֲכָמִים שֶׁמָּא יִשְׁאַל מִמֶּנּוּ כְּלִי שֶׁטֶף שֶׁכְּבָר הָיָה תַּחַת צָמִיד פָּתִיל בִּכְלִי חֶרֶס שֶׁלּוֹ. שֶׁהֲרֵי עַם הָאָרֶץ הַזֶּה מְדַמֶּה שֶׁנִּצַּל וַהֲרֵי הוּא טָמֵא טֻמְאַת שִׁבְעָה וְיַטְבִּיל הֶחָבֵר וְיַעֲרִיב שִׁמְשׁוֹ וְיִשְׁתַּמֵּשׁ בּוֹ בְּטָהֳרוֹת וְיָבוֹא לִידֵי תַּקָּלָה. וּמִפְּנֵי זֶה גָּזְרוּ שֶׁלֹּא יַצִּיל כְּלִי חֶרֶס עַל כְּלִי שֶׁטֶף שֶׁבְּתוֹכוֹ:","אָדָם שֶׁהָיָה נָתוּן בְּתוֹךְ הֶחָבִית וּמֻקֶּפֶת צָמִיד פָּתִיל טָהוֹר. וַאֲפִלּוּ עֲשָׂאָהּ גּוֹלֵל לְקֶבֶר. וְיֵרָאֶה לִי שֶׁזֶּה שֶׁלֹּא גָּזְרוּ עַל כְּלִי חֶרֶס שֶׁלֹּא יַצִּיל עַל הָאָדָם. מִפְּנֵי שֶׁהוּא דָּבָר שֶׁאֵינוֹ מָצוּי וְכָל דָּבָר שֶׁאֵינוֹ מָצוּי לֹא גָּזְרוּ בּוֹ:","כְּלֵי חֶרֶס שֶׁמִּשְׁתַּמְּשִׁין בָּהֶן בְּאֵפֶר הַפָּרָה אוֹ בְּקָדָשִׁים עַמֵּי הָאָרֶץ נֶאֱמָנִים עַל טָהֳרָתָם. מִפְּנֵי שֶׁהֵן נִזְהָרִים בָּהֶן הַרְבֵּה וּלְפִיכָךְ יַצִּילוּ עַל הַכּל בְּצָמִיד פָּתִיל אַף עַל פִּי שֶׁהֵן שֶׁל חֶרֶס:","אֲרֻבָּה שֶׁבֵּין בַּיִת לַעֲלִיָּה וְטֻמְאָה בַּבַּיִת וּקְדֵרָה נְתוּנָה עַל פִּי הָאֲרֻבָּה וּנְקוּבָה בְּכוֹנֵס מַשְׁקֶה. הַקְּדֵרָה טְמֵאָה וְהָעֲלִיָּה טְהוֹרָה. הָיְתָה שְׁלֵמָה כָּל שֶׁבָּעֲלִיָּה מֵאֳכָלִין וּמַשְׁקִין וּכְלֵי חֶרֶס טָהוֹר. אֲבָל אָדָם וּכְלֵי שֶׁטֶף שֶׁבָּעֲלִיָּה טְמֵאִים שֶׁאֵין כְּלִי חֶרֶס חוֹצֵץ אֶלָּא עַל הָאֳכָלִים וְעַל הַמַּשְׁקִין וּכְלֵי חֶרֶס. וְכָל שֶׁבָּעֲלִיָּה טָהוֹר כְּאִלּוּ הוּא תַּחַת צָמִיד פָּתִיל בִּכְלִי חֶרֶס. וְטִמְאוּ הָאָדָם שֶׁבָּעֲלִיָּה זוֹ מִפְּנֵי שֶׁהוּא דָּבָר הַמָּצוּי. לְפִיכָךְ אִם הָיָה בָּעֲלִיָּה זוֹ כְּלִי מַתָּכוֹת וְכַיּוֹצֵא בּוֹ מָלֵא מַשְׁקִין הַכְּלִי טָמֵא טֻמְאַת שִׁבְעָה וְהַמַּשְׁקִין טְהוֹרִין. הָיְתָה בָּהּ אִשָּׁה לָשָׁה בַּעֲרֵבָה שֶׁל עֵץ הָאִשָּׁה וְהָעֲרֵבָה טְמֵאִין טֻמְאַת שִׁבְעָה וְהַבָּצֵק טָהוֹר כָּל זְמַן שֶׁעוֹסֶקֶת בּוֹ. פֵּרְשָׁה וְחָזְרָה וְנָגְעָה בּוֹ טִמְּאַתּוֹ. וְכֵן אִם פִּנָּה הַבָּצֵק אוֹ הַמַּשְׁקִין לִכְלִי אַחֵר מִכְּלֵי שֶׁטֶף שֶׁבָּעֲלִיָּה נִטְמְאוּ בְּמַגַּע הַכְּלִי הָאַחֵר. הָיָה עַל פִּי אֲרֻבָּה זוֹ שְׁאָר כֵּלִים הַמַּצִּילִים בְּצָמִיד פָּתִיל שֶׁאֵין מְקַבְּלִין טֻמְאָה כְּמוֹ שֶׁבֵּאַרְנוּ וּלְפִיכָךְ אֵין מַגַּע עַם הָאָרֶץ מְטַמֵּא אוֹ שֶׁהָיָה כְּלִי חֶרֶס הַטָּהוֹר לְפָרָה אֲדֻמָּה אוֹ לְקֹדֶשׁ שֶׁהַכּל נֶאֱמָנִין עַל טָהֳרָתָן. הֲרֵי זֶה מַצִּיל עַל כָּל מַה שֶּׁבָּעֲלִיָּה. הָיָה אֹהֶל נָטוּי בָּעֲלִיָּה וּמִקְצָתוֹ מְרֻדָּד עַל הָאֲרֻבָּה שֶׁבֵּין בַּיִת לַעֲלִיָּה הֲרֵי זֶה מַצִּיל וְאַף עַל פִּי שֶׁאֵין גַּגּוֹ עַל הָאֲרֻבָּה שֶׁהָאֹהֶל מַצִּיל בְּכִסּוּי כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Defilement of Foods 11":["הַבּוֹצֵר עֲנָבִים לִמְכֹּר בַּשּׁוּק אוֹ לְיַבְּשָׁן לֹא הֻכְשְׁרוּ לְטֻמְאָה עַד שֶׁיִּפְּלוּ עֲלֵיהֶן מַשְׁקִין לִרְצוֹנוֹ כִּשְׁאָר הָאֳכָלִין. אֲבָל הַבּוֹצֵר לִדְרֹךְ הֻכְשַׁר לְטֻמְאָה וְאַף עַל פִּי שֶׁלֹּא נָפְלוּ מַשְׁקִין עַל הַבָּצִיר כְּלָל וְאִם נָגְעָה בּוֹ טֻמְאָה נִטְמָא. וְדָבָר זֶה גְּזֵרָה מִדִּבְרֵי סוֹפְרִים. וּמִפְּנֵי מָה גָּזְרוּ עַל הַבּוֹצֵר לַגַּת שֶׁהוּא מֻכְשָׁר שֶׁפְּעָמִים שֶׁאָדָם נִכְנַס לְכַרְמוֹ לֵידַע אִם הִגִּיעַ לְהִבָּצֵר וְסוֹחֵט אֶשְׁכּוֹל שֶׁל עֲנָבִים לִבְדֹּק בּוֹ וּמְזַלְּפוֹ עַל גַּבֵּי הָעֲנָבִים הַבְּצוּרוֹת שֶׁהֲרֵי הַכּל לִדְרִיכָה עוֹמֵד. וְעוֹד מִפְּנֵי שֶׁאֵינוֹ מַקְפִּיד עָלָיו הֲרֵי הוּא מִתְמַעֵךְ וְיֵצְאוּ מֵימָיו וַהֲרֵי הוּא מַקְפִּיד עֲלֵיהֶן שֶׁלֹּא יָזוּבוּ בַּקַּרְקַע וְנִמְצָא מֻכְשָׁר בָּהֶן. לְפִיכָךְ גָּזְרוּ שֶׁהַבּוֹצֵר לְגַת הֻכְשַׁר:","הַבּוֹצֵר עֲנָבִים שֶׁאִם לֹא מָצָא לָהֶם שׁוּק מַחֲזִירָן לַגַּת לֹא הֻכְשְׁרוּ עַד שֶׁיָּבוֹאוּ לִרְשׁוּת הַגַּת. וְכֵן הַזֵּיתִים שֶׁבָּאוּ לִרְשׁוּת הַבַּד הֻכְשְׁרוּ כְּמוֹ שֶׁיִּתְבָּאֵר:","הַבּוֹצֵר עֲנָבִים וּנְתָנָם בְּעָבִיט אוֹ שֶׁשְּׁטָחָן עַל גַּבֵּי הֶעָלִין הֻכְשְׁרוּ בְּמַשְׁקִין הַיּוֹצְאִין מֵהֶן שֶׁהֲרֵי דַּעְתּוֹ עַל הַמַּשְׁקִין וּלְפִיכָךְ שָׁטַח עַל הֶעָלִין אוֹ נָתַן לְתוֹךְ הֶעָבִיט שֶׁהוּא כְּמוֹ בּוֹר לְפִיכָךְ אִם נָטַל מֵהֶן טָמֵא אוֹ מִי שֶׁיָּדָיו טְמֵאוֹת טִמְּאָן. בָּצַר וְנָתַן לַסַּלִּים אוֹ בְּמַשְׁטִיחַ שֶׁל אֲדָמָה לֹא הֻכְשְׁרוּ שֶׁהֲרֵי אֵינוֹ מַקְפִּיד עַל הַמַּשְׁקֶה הַיּוֹצֵא מֵהֶן לְפִיכָךְ נוֹטֵל הַטָּמֵא מֵהֶן וְאוֹכֵל וְאַף עַל פִּי שֶׁהֵן מְבֻקָּעוֹת וּמְנַטְּפות לַגַּת הֲרֵי הַגַּת טְהוֹרָה שֶׁהֲרֵי לֹא הֻכְשְׁרוּ וַהֲרֵי נִבְצְרוּ לַאֲכִילָה. וְכֵן הַנּוֹטֵל מִן הַסַּלִּים וּמִן הַמַּשְׁטִיחַ שֶׁל אֲדָמָה וְאָכַל וְהוֹתִיר כִּסְאָה וּכְסָאתַיִם וּזְרָקָן לַגַּת. וְאַף עַל פִּי שֶׁהַיַּיִן מְנַתֵּז עַל הָעֲנָבִים לֹא הֻכְשְׁרוּ:","עֲנָבִים שֶׁהָיוּ בְּסַלִּים אוֹ בְּמַשְׁטִיחַ שֶׁל אֲדָמָה וְלָקַח מֵהֶן לְדָרְכָן הֻכְשְׁרוּ לְפִיכָךְ צָרִיךְ לִקַּח מֵהֶן בְּיָדַיִם טְהוֹרוֹת כְּדֵי שֶׁלֹּא יִקַּח מֵהֶן הַטָּמֵא וִיטַמְּאֵן:","כֶּרֶם שֶׁהוּא עוֹמֵד בְּבֵית הַפְּרָס הַבּוֹצֵר אוֹתוֹ לַגַּת אֵינוֹ מֻכְשָׁר כָּל זְמַן שֶׁהוּא בְּבֵית הַפְּרָס הוֹאִיל וְטֻמְאַת בֵּית הַפְּרָס מִדִּבְרֵיהֶם וְהַבּוֹצֵר לַגַּת הֻכְשַׁר מִדִּבְרֵיהֶם הֵקֵלּוּ בִּגְזֵרָה זוֹ וְלֹא גָּזְרוּ עָלָיו שֶׁיִּהְיֶה מֻכְשָׁר עַד שֶׁיֵּצֵא מִבֵּית הַפְּרָס. לְפִיכָךְ הָרוֹצֶה לִבְצֹר בְּבֵית הַפְּרָס לַגַּת בְּטָהֳרָה מְטַהֵר אֶת הַבּוֹצְרִים וְאֶת הַכֵּלִים וּמַזֶּה עֲלֵיהֶם שְׁלִישִׁי וּשְׁבִיעִי וּמַעֲרִיב שִׁמְשָׁן כְּדֵי לְהַכִּיר שֶׁאֵין מְקִלִּין בְּטֻמְאַת בֵּית הַפְּרָס אֶלָּא מִפְּנֵי שֶׁהוּא סָפֵק וְאַחַר כָּךְ נִכְנָסִין וּבוֹצְרִין וּמוֹצִיאִין חוּץ לְבֵית הַפְּרָס וַאֲחֵרִים טְהוֹרִים מְקַבְּלִין מֵהֶן וּמוֹלִיכִין לַגַּת וְאִם נָגְעוּ אֵלּוּ בְּאֵלּוּ טְמֵאִין מְטַמְּאִין אֶת הָעֲנָבִים שֶׁהָאֲנָשִׁים שֶׁבְּבֵית הַפְּרָס טְמֵאִין וּמְטַמְּאִין לְאוֹתָן שֶׁבַּחוּץ וְעוֹשִׂין אוֹתוֹ רִאשׁוֹן וְהֵן מְטַמְּאִין אֶת הָעֲנָבִים שֶׁהֲרֵי הֻכְשְׁרוּ מִשֶּׁיָּצְאוּ חוּץ לְבֵית הַפְּרָס:","הַמּוֹסֵק אֶת זֵיתָיו לְכָבְשָׁן אוֹ לְמָכְרָן בַּשּׁוּק לֹא הֻכְשְׁרוּ עַד שֶׁיִּפְּלוּ עֲלֵיהֶן מַשְׁקִין בְּרָצוֹן כִּשְׁאָר הָאֳכָלִין. וְכֵן הַמּוֹסֵק זֵיתָיו לִדְרֹךְ בְּבֵית הַבַּד לֹא הֻכְשְׁרוּ עַד שֶׁתִּגָּמֵר מְלַאכְתָּן. וּמִפְּנֵי מָה יֻכְשְׁרוּ הַזֵּיתִים שֶׁנִּגְמְרָה מְלַאכְתָּן שֶׁחֶזְקָתָן שֶׁהֻכְשְׁרוּ בְּמֹהַל שֶׁלָּהֶן שֶׁהֲרֵי רוֹצֶה בְּקִיּוּמוֹ כְּדֵי שֶׁיִּהְיוּ נוֹחִין לִדְרֹךְ. אֲבָל קֹדֶם שֶׁתִּגָּמֵר מְלַאכְתָּן אֵין הַמֹּהַל הַיּוֹצֵא מֵהֶן מַכְשִׁיר מִפְּנֵי שֶׁאֵינוֹ רוֹצֶה בְּקִיּוּמוֹ. לְפִיכָךְ זֵיתִים שֶׁלֹּא נִגְמְרָה מְלַאכְתָּן שֶׁנָּפְלוּ עֲלֵיהֶן מַשְׁקִין טְמֵאִין אֵין טָמֵא אֶלָּא מְקוֹם מַגָּעָם כְּכָל הָאֳכָלִים שֶׁלֹּא הֻכְשְׁרוּ. נָפְלוּ עֲלֵיהֶן מַשְׁקִין טְמֵאִין אַחַר שֶׁנִּגְמְרָה מְלַאכְתָּן נִטְמְאוּ כֻּלָּן שֶׁהַמַּשְׁקִין הַטְּמֵאִין מְטַמְּאִים אֶת הַמֹּהַל שֶׁבָּהֶן וְהַמֹּהַל מְטַמֵּא אֶת כֻּלָּן. שֶׁהַמֹּהַל שֶׁיָּצָא מֵהֶן אַחַר גְּמַר מְלַאכְתָּן חָשׁוּב מַשְׁקֶה וּמִתְטַמֵּא וּמַכְשִׁיר:","חָבִית שֶׁל זֵיתִים מְגֻלְגָּלִים צָרִיךְ לִנְקֹב הֶחָבִית כְּדֵי שֶׁיֵּצֵא הַמֹּהַל. וְאִם לֹא נִקֵּב הֲרֵי אֵלּוּ מֻכְשָׁרִין. נִקְּבָהּ וּסְתָמוּהָ שְׁמָרִים וְהִנָּם בְּלוּלִים בַּמֹּהַל אֵינָם מַכְשִׁירִין מִפְּנֵי שֶׁאֵינָן בִּרְצוֹנוֹ שֶׁהֲרֵי נִקְּבָהּ:","זֵיתִים שֶׁמְּסָקָן לִדְרִיכָה מֵאֵימָתַי גְּמַר מְלַאכְתָּן מִשֶּׁתִּגָּמֵר מְסִיקָתָן וְיִהְיוּ מֻנָּחִים וּמוּכָנִים לִדְרִיכָה. אַף עַל פִּי שֶׁלֹּא נָפְלוּ עֲלֵיהֶן מַשְׁקִין וְלֹא יָצְאוּ מֵהֶן מַשְׁקִין הוֹאִיל וְנִגְמְרָה מְלַאכְתָּן הֻכְשְׁרוּ. אֲבָל קֹדֶם שֶׁנִּגְמְרָה מְלַאכְתָּן אַף עַל פִּי שֶׁנִּתְמַעֲכוּ וְהִזִּיעוּ וְנִתְחַבְּרוּ בְּמַשְׁקֵיהֶן אֵינָן מֻכְשָׁרִין. גָּמַר מִלִּמְסֹק זֵיתָיו אֲבָל עָתִיד לִקַּח זֵיתִים אֲחֵרִים לְהוֹסִיף עֲלֵיהֶם אֲפִלּוּ אֵינוֹ עָתִיד לְהוֹסִיף אֶלָּא אוֹ קַב אוֹ קַבַּיִם לֹא הֻכְשְׁרוּ. וְאִם הֶעֱרִים הֲרֵי אֵלּוּ מֻכְשָׁרִין. גָּמַר מִלִּקַּח אֲבָל עָתִיד לִלְווֹת וּלְהוֹסִיף וְאֵרְעוֹ אֹנֶס אוֹ נִתְעַסֵּק בְּמִשְׁתֶּה וְלֹא הוֹסִיף עֲדַיִן לֹא נִגְמְרָה מְלַאכְתָּן וְאֵינָן מְקַבְּלִין טֻמְאָה. וַאֲפִלּוּ זָבִים וְזָבוֹת מְהַלְּכִין עֲלֵיהֶם טְהוֹרִים:","הָעוֹטֵן זֵיתָיו בִּשְׁנֵי בַּדִּים כֵּיוָן שֶׁגָּמַר אַחַת מֵהֶן הֻכְשְׁרוּ לְקַבֵּל טֻמְאָה:","הַמַּסִּיק זֵיתָיו בַּגָּלִיל הָעֶלְיוֹן וְעָתִיד לְהוֹרִידָם לַגָּלִיל הַתַּחְתּוֹן אֵין מְקַבְּלִין טֻמְאָה עַד שֶׁיּוֹרִידֵם לְשָׁם. וְהוּא שֶׁחִשֵּׁב עֲלֵיהֶן קֹדֶם שֶׁיִּמְסֹק אֲבָל אַחַר שֶׁיִּמְסֹק אֵין הַמַּחְשָׁבָה מוֹעֶלֶת אֶלָּא הֻכְשְׁרוּ. גָּמַר אֶת זֵיתָיו וְעָתִיד לְמָכְרָן לֹא הֻכְשְׁרוּ. עָתִיד לְחַפּוֹתָן בְּעָלִין הֻכְשְׁרוּ וּמְקַבְּלִין טֻמְאָה:","הַלּוֹקֵחַ מַעֲטָן זֵיתִים מִן הָעַכּוּ\"ם אִם יֵשׁ מַסִּיק עַל פְּנֵי הָאֲדָמָה יֵעָשׂוּ בְּטֻמְאָה שֶׁזֶּה בְּחֶזְקַת שֶׁגָּמַר. וְנֶאֱמָן עַם הָאָרֶץ לוֹמַר מַעֲטָן זֶה לֹא גְּמַרְתִּיו:","הָרוֹצֶה לִטּל מִזֵּיתִים שֶׁלֹּא נִגְמְרָה מְלַאכְתָּן וְלִדְרֹךְ הֲרֵי זֶה נוֹטֵל מֵהֶן בְּטֻמְאָה וּמוֹלִיךְ לְבֵית הַבַּד בְּטֻמְאָה וּמְכַסֶּה הַשְּׁאָר בְּטֻמְאָה וְאֵינוֹ חוֹשֵׁשׁ שֶׁהֲרֵי לֹא הֻכְשְׁרוּ כְּדֵי שֶׁיְּקַבְּלוּ טֻמְאָה:","הַמַּנִּיחַ אֶת זֵיתָיו בְּכוֹתֵשׁ כְּדֵי שֶׁיַּמְתִּינוּ וְיִהְיוּ נוֹחִים לְהִכָּתֵשׁ הֲרֵי אֵלּוּ מֻכְשָׁרִין. הִנִּיחָן שֶׁיַּמְתִּינוּ וְשֶׁיִּמְלָחֵם אַחַר שֶׁיַּמְתִּינוּ אֵינָן מֻכְשָׁרִין שֶׁהֲרֵי דַּעְתּוֹ עֲלֵיהֶן לְכָבְשָׁן:","הַפּוֹצֵעַ זֵיתִים שֶׁל תְּרוּמָה בְּיָדַיִם טְמֵאוֹת פְּסָלָן שֶׁפְּצִיעָתָן הִיא גְּמַר מְלַאכְתָּן. פְּצָעָן לְסָפְגָן בְּמֶלַח לֹא הֻכְשְׁרוּ. וְכֵן אִם פְּצָעָן לֵידַע אִם יֵשׁ בָּהֶן שֶׁמֶן וְהִגִּיעוּ לְהִמָּסֵק לֹא הֻכְשְׁרוּ:","הַמַּנִּיחַ זֵיתִים בַּגַּת לְגַרְגְּרָן וּלְיַבְּשָׁן אֲפִלּוּ הֵם רוּם אַמָּה אֵינָן מֻכְשָׁרִין. נְתָנָן בַּבַּיִת שֶׁיִּלְקוּ אַף עַל פִּי שֶׁעָתִיד לְהַעֲלוֹתָן לַגַּג אוֹ שֶׁנְּתָנָן בַּגַּג שֶׁיִּלְקוּ אַף עַל פִּי שֶׁעָתִיד לְפָתְחָם וְיַפְרִיס אוֹתָן הֲרֵי אֵלּוּ מֻכְשָׁרִים. נְתָנָן בַּבַּיִת עַד שֶׁיִּשְׁמֹר אֶת גַּגּוֹ אוֹ עַד שֶׁיּוֹלִיכֵם לְמָקוֹם אַחֵר אֵינָן מֻכְשָׁרִים שֶׁעֲדַיִן לֹא נִגְמְרָה מְלַאכְתָּן:","הָעוֹטֵן זֵיתָיו בִּרְשׁוּת עַם הָאָרֶץ וְנָעַל וְחָתַם אֵינוֹ חוֹשֵׁשׁ שֶׁמָּא יֵשׁ לוֹ מַפְתֵּחַ אַחֵר וְחוֹתָם אַחֵר. אַף עַל פִּי שֶׁמָּצָא חוֹתָם מְקֻלְקָל וּמַפְתֵּחַ פָּתוּחַ הֲרֵי אֵלּוּ טְהוֹרִין. וְחוֹתָם שֶׁאָמְרוּ אֲפִלּוּ צְרוֹר אוֹ קֵיסָם. הָיוּ שָׁם חוֹרִין וּסְדָקִין אֵינוֹ חוֹשֵׁשׁ שֶׁמָּא מַכְנִיס קָנֶה וּמְסִיטָן. הָיוּ שָׁם חַלּוֹנוֹת שֶׁל אַרְבָּעָה טְפָחִים נִדּוֹנוֹת כִּפְתָחִין:","הַדּוֹרֵךְ בְּטֻמְאָה וְרָצָה לְטַהֵר כְּלֵי בֵּית הַבַּד וְהָעַקָּל מִן הַמַּשְׁקִין הַטְּמֵאִין שֶׁנִּבְלְעוּ בָּהֶן כֵּיצַד יַעֲשֶׂה. כְּלִי שֶׁל עֵץ וְשֶׁל אֲבָנִים מֵדִיחַ. וְשֶׁל נְסָרִים וְכַיּוֹצֵא בָּהֶן מְנַגְּבָן. וְשֶׁל גֶּמִי מְיַשְּׁנָן כָּל שְׁנֵים עָשָׂר חֹדֶשׁ אוֹ חוֹלְטָן בְּחַמִּין אוֹ בְּמֵי זֵיתִים אוֹ מַנִּיחָן תַּחַת צִנּוֹר שֶׁמֵּימָיו מְקַלְּחִין אוֹ לְתוֹךְ מַעְיָן שֶׁמֵּימָיו רוֹדְפִין שְׁתֵּים עֶשְׂרֵה שָׁעוֹת. וְאַחַר כָּךְ מַטְבִּיל אֶת הַכֵּלִים שֶׁצְּרִיכִין טְבִילָה וּמִשְׁתַּמֵּשׁ בָּהֶן בְּטָהֳרָה:"],"Mishneh Torah, Defilement of Foods 8":["חַלוֹת אוֹ כִּכָּרִים שֶׁכְּנָסָן וְהָיוּ נוֹשְׁכוֹת זוֹ בְּזוֹ וְדַעְתּוֹ לְהַפְרִישָׁן אוֹ שֶׁאָפָה חַלָּה עַל גַּבֵּי חַלָּה בַּתַּנּוּר וַעֲדַיִן לֹא קָרְמוּ פָּנֶיהָ וְנָגַע טְבוּל יוֹם בְּאַחַת מֵהֶן לֹא פָּסַל אֶלָּא הַחַלָּה שֶׁנָּגַע בָּהּ. וְכֵן הַמַּיִם שֶׁהִרְתִּיחוּ וְנַעֲשׂוּ כְּקוּבָּה. וְהַגְּרִיסִין שֶׁהִרְתִּיחוּ רְתִיחָה רִאשׁוֹנָה. וְיַיִן חָדָשׁ וְאֹרֶז שֶׁהִרְתִּיחוּ. וְנָגַע טְבוּל יוֹם בָּרְתִיחָה אֵינוֹ חִבּוּר וְלֹא פָּסַל אֶלָּא הָרְתִיחָה בִּלְבַד. וּבִשְׁאָר כָּל הַטֻּמְאוֹת בֵּין קַלּוֹת בֵּין חֲמוּרוֹת הַכּל חִבּוּר. אֲבָל חַלּוֹת שֶׁהָיוּ נוֹשְׁכוֹת זוֹ בְּזוֹ וְאֵין דַּעְתּוֹ לְהַפְרִישׁ. אוֹ שֶׁאָפָה חַלָּה עַל גַּבֵּי חַלָּה וְנָשְׁכוּ וְקָרְמוּ בַּתַּנּוּר. וּרְתִיחַת הַמַּיִם שֶׁאֵינָהּ מְחֻלְחֶלֶת כְּקוּבָּה. וּרְתִיחַת הַגְּרִיסִין שְׁנִיָּה. וּרְתִיחַת יַיִן יָשָׁן. וּרְתִיחַת הַשֶּׁמֶן בֵּין יָשָׁן בֵּין חָדָשׁ. וּרְתִיחַת עֲדָשִׁים. הֲרֵי אֵלּוּ חִבּוּר בִּטְבוּל יוֹם וְאֵין צָרִיךְ לוֹמַר בְּכָל הַטֻּמְאוֹת:","בָּצֵק שֶׁיָּצָא בִּשְׁעַת אֲפִיָּה וְנִמְצָא בְּאֶמְצַע הַכִּכָּר כְּמוֹ מַסְמֵר יוֹצֵא. וְכֵן קְצָת הַבָּצֵק שֶׁנִּמְשַׁךְ וְנֶחְרַךְ בְּעֵת אֲפִיָּה וְהוּא הַנִּקְרָא חַרְחוּר. אִם הָיוּ פְּחוּתִים מִכְּאֶצְבַּע וְנָגַע טְבוּל יוֹם בָּהֶן פָּסַל כָּל הַכִּכָּר. וְכֵן אִם נָגַע בְּגַרְגֵר מֶלַח קָטָן שֶׁבַּכִּכָּר נִפְסַל כָּל הַכִּכָּר. וְאֵין צָרִיךְ לוֹמַר בְּכָל הַטֻּמְאוֹת. אֲבָל צְרוֹר שֶׁבַּכִּכָּר אוֹ תּוּרְמוּס וְגַרְגֵּר מֶלַח גָּדוֹל וְחַרְחוּר יֶתֶר מִכְּאֶצְבַּע שֶׁנָּגַע בָּהֶן אֲפִלּוּ אַב הַטֻּמְאָה הַכִּכָּר טָהוֹר וְאֵין צָרִיךְ לוֹמַר בִּטְבוּל יוֹם:","רָקִיק שֶׁנֶּחְרַךְ חֶצְיָהּ וְחֶצְיָהּ קַיָּם הֲרֵי זוֹ אֵינוֹ חִבּוּר. נֶחְרַךְ הָאֶמְצַע וְהַצְּדָדִין קַיָּמִין אֵינָן חִבּוּר זֶה לָזֶה אֲפִלּוּ בְּאַב הַטֻּמְאָה וְאֵין צָרִיךְ לוֹמַר בִּטְבוּל יוֹם. בְּשַׂר קֹדֶשׁ שֶׁקָּרַם עָלָיו הַמָּרָק וְנָגַע טְבוּל יוֹם בַּקִיפָה הַחֲתִיכוֹת מֻתָּרוֹת. נָגַע בַּחֲתִיכָה הַחֲתִיכָה וְכָל הָעוֹלִין עִמָּהּ חִבּוּר. וְכֵן בְּתַבְשִׁיל קִטְנִיּוֹת שֶׁקָּרַם עַל גַּבֵּי פְּרוּסוֹת. שֶׁמֶן שֶׁצָּף עַל גַּבֵּי יַיִן וְנָגַע טְבוּל יוֹם בַּשֶּׁמֶן לֹא פָּסַל אֶלָּא הַשֶּׁמֶן:","יָרָק תְּרוּמָה וּבֵיצָה טְרוּפָה נְתוּנָה עַל גַּבָּיו וְנָגַע טְבוּל יוֹם בַּבֵּיצָה לֹא פָּסַל אֶלָּא קֶלַח שֶׁכְּנֶגְדוֹ. וְאִם הָיְתָה כְּמִין כּוֹבַע אֵינוֹ חִבּוּר:","חוּט שֶׁל בֵּיצָה שֶׁקָּרַם עַל דָּפְנָהּ שֶׁל אִלְפָּס וְנָגַע בּוֹ טְבוּל יוֹם. מִן הַשָּׂפָה וּלְפָנִים חִבּוּר מִן הַשָּׂפָה וְלַחוּץ אֵינוֹ חִבּוּר. וְכֵן בְּקִטְנִיּוֹת שֶׁקָּרְמוּ עַל שְׂפַת הַקְּדֵרָה:","חָבִית שֶׁנִּקְּבָה בֵּין מִשּׁוּלֶיהָ בֵּין מִצִּדֶּיהָ וְסָתַם טְבוּל יוֹם הַנֶּקֶב בְּיָדָיו נִפְסְלָה כֻּלָּהּ:","הַמְעָרֶה מִכְּלִי לִכְלִי וְנָגַע טְבוּל יוֹם בַּקִּלּוּחַ מְשַׁעֲרִין זֶה שֶׁנָּגַע בּוֹ בְּאֶחָד וּמֵאָה. שֶׁתְּרוּמָה טְמֵאָה שֶׁנִּתְעָרְבָה בְּאֶחָד וּמֵאָה בָּטְלָה בְּמִעוּטָהּ כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת תְּרוּמוֹת:","טְבוּל יוֹם שֶׁהָיָה תּוֹרֵם אֶת הַבּוֹר וְנָפְלָה מִמֶּנּוּ חָבִית שֶׁל תְּרוּמָה וְשָׁקְעָה בְּבוֹר שֶׁל יַיִן וְנָגַע בַּיַּיִן שֶׁבַּבּוֹר. מִן הַשָּׂפָה וְלַחוּץ אֵינוֹ חִבּוּר מִן הַשָּׂפָה וּלְפָנִים חִבּוּר. וְאִם הָיָה הַבּוֹר פִּיטַס אֲפִלּוּ הָיָה כְּלִי גָּדוֹל שֶׁמַּחְזִיק מֵאָה כּוֹר כֻּלּוֹ חִבּוּר וְאִם נָגַע בְּמִקְצָת הַיַּיִן פָּסַל הַתְּרוּמָה שֶּׁבֶּחָבִית שֶׁבְּקַרְקַע הַכְּלִי:","הַסּלֶת שֶׁל מְנָחוֹת וְהַלְּבוֹנָה וְהַקְּטֹרֶת וְהַגֶּחָלִים שֶׁנָּגַע טְבוּל יוֹם בְּמִקְצָתָן פָּסַל אֶת כֻּלָּן. בַּמֶּה דְּבָרִים אֲמוּרִים בְּגֶחָלִים שֶׁחוֹתֶה בְּמַחְתָּה בְּיוֹם הַכִּפּוּרִים. שֶׁהַמַּחְתָּה שֶׁחוֹתֶה בָּהּ נִכְנָס לַהֵיכָל. אֲבָל גֶּחָלִים שֶׁחוֹתֶה בְּכָל יוֹם כְּשֶׁהוּא מְעָרֶה בְּמַחְתָּה שֶׁל כֶּסֶף לְשֶׁל זָהָב אִם נִתְפַּזְּרוּ מִן הַגֶּחָלִים אֵין בָּהֶן קְדֻשָּׁה אֶלָּא מְכַבְּדָן לָאַמָּה:","מִקְפָּה שֶׁל חֻלִּין אוֹ רָקִיק שֶׁל חֻלִּין וְשֶׁמֶן שֶׁל תְּרוּמָה צָף עַל גַּבֵּיהֶן וְנָגַע טְבוּל יוֹם בַּשֶּׁמֶן לֹא פָּסַל אֶלָּא הַשֶּׁמֶן בִּלְבַד. וְאִם חִבֵּץ כָּל מָקוֹם שֶׁהָלַךְ בּוֹ הַשֶּׁמֶן פָּסַל:","יָרָק שֶׁל חֻלִּין שֶׁבִּשְּׁלוֹ בְּשֶׁמֶן שֶׁל תְּרוּמָה וְנָגַע בּוֹ טְבוּל יוֹם לֹא פָּסַל אֶלָּא מְקוֹם מַגָּעוֹ:","הַמִּקְפָּה שֶׁל תְּרוּמָה וְהַשּׁוּם וְהַשֶּׁמֶן שֶׁל חֻלִּין שֶׁנָּגַע טְבוּל יוֹם בְּמִקְצָתָן פָּסַל אֶת כֻּלָּן:","הַמִּקְפָּה שֶׁל חֻלִּין וְהַשֶּׁמֶן שֶׁל תְּרוּמָה שֶׁנָּגַע טְבוּל יוֹם בְּמִקְצָתָן לֹא פָּסַל אֶלָּא מְקוֹם מַגָּעוֹ. אִם הָיָה הַשּׁוּם מְרֻבֶּה הוֹלְכִין אַחַר הָרֹב. אֵימָתַי בִּזְמַן שֶׁהוּא גּוּשׁ בִּקְעָרָה אֲבָל אִם הָיָה מְפֻזָּר בִּמְדוֹכָה וְנָגַע בְּמִקְצָתוֹ לֹא פָּסַל אֶלָּא מְקוֹם מַגָּעוֹ מִפְּנֵי שֶׁהוּא רוֹצֶה בְּפִזּוּרוֹ. וּשְׁאָר כָּל הַנִּדּוֹכִין שֶׁדַּרְכָּן לְדוּכָן בְּמַשְׁקִין כְּגוֹן הַשּׁוּם בְּשֶׁמֶן אִם דָּכָן שֶׁלֹּא בְּמַשְׁקִין וְקִבְּצָן אַף עַל פִּי שֶׁהֵן גּוּשׁ בִּקְעָרָה וְנָגַע בָּהֶן לֹא פָּסַל אֶלָּא מְקוֹם מַגָּעוֹ. שֶׁהֲרֵי הֵם כְּעִגּוּל שֶׁל דְּבֵלָה שֶׁאִם נִטְמָא מִקְצָתוֹ לֹא נִטְמָא כֻּלּוֹ:","עִסָּה שֶׁקָּרָא שֵׁם חַלָּתָהּ בִּצְפוֹנָהּ אוֹ בִּדְרוֹמָהּ. וְכֵן הַקִּשּׁוּת שֶׁקָּרָא שֵׁם תְּרוּמָה בִּצְפוֹנָהּ אוֹ בִּדְרוֹמָהּ הֲרֵי זֶה חִבּוּר. וְאִם נָגַע טְבוּל יוֹם בְּמִקְצָת הָעִסָּה נִפְסְלָה הַחַלָּה. נִטְּלָה חַלָּתָהּ מִתּוֹכָהּ וְחָזְרָה לְתוֹכָהּ אֵינוֹ חִבּוּר:","עִסָּה שֶׁנִּדְמְעָה אוֹ שֶׁנִּתְחַמְּצָה בִּשְׂאוֹר שֶׁל תְּרוּמָה אֵינָהּ נִפְסֶלֶת בִּטְבוּל יוֹם:","עִסָּה שֶׁהֻכְשְׁרָה בְּמַשְׁקִין וְנִלּוֹשָׁה בְּמֵי פֵּרוֹת וְנָגַע בָּהּ טְבוּל יוֹם לֹא פָּסַל אֶלָּא מְקוֹם מַגָּעוֹ בִּלְבַד:","מַעֲשֵׂר רִאשׁוֹן שֶׁהֻכְשַׁר וְנָגַע בּוֹ טְבוּל יוֹם אוֹ יָדַיִם מְסֹאָבוֹת מַפְרִישִׁין מִמֶּנּוּ תְּרוּמַת מַעֲשֵׂר בְּטָהֳרָה. מִפְּנֵי שֶׁמַּעֲשֵׂר רִאשׁוֹן כְּחֻלִּין וּטְבוּל יוֹם וְיָדַיִם מְסֹאָבוֹת אֵינָם פּוֹסְלִין אֶת הַחֻלִּין שֶׁהַשְּׁלִישִׁי בְּחֻלִּין טָהוֹר כְּמוֹ שֶׁבֵּאַרְנוּ. וְכֵן הָאִשָּׁה שֶׁהִיא טְבוּלַת יוֹם לָשָׁה אֶת הָעִסָּה וְקוֹצָה לָהּ חַלָּה וּמַפְרִישָׁתָהּ וּמַנִּיחָתָהּ בְּכֵלִים וְנוֹתַנְתּוֹ עִם שְׁאָר הָעִסָּה כְּאַחַת. וּמַקֶּפֶת עַל הַכּל כְּדֵי לִתְרֹם מִן הַמֻּקָּף וְאַחַר כָּךְ קוֹרְאָה לָהּ שֵׁם וְאוֹמֶרֶת הֲרֵי זוֹ חַלָּה. וּמִשֶּׁתִּקְרָא לָהּ שֵׁם לֹא תִּגַּע בָּהּ שֶׁלֹּא תִּפְסְלֶנָּהּ. וְכָךְ הִיא עוֹשָׂה אִם לָשָׁה בַּעֲרֵבָה שֶׁהִיא טְבוּלַת יוֹם:","לָגִין שֶׁהוּא טְבוּל יוֹם שֶׁמִּלְּאָהוּ מֵחָבִית מַעֲשֵׂר שֶׁלֹּא נִטְּלָה תְּרוּמָתוֹ וְאָמַר הֲרֵי זוֹ תְּרוּמַת מַעֲשֵׂר עַל מַה שֶּׁבֶּחָבִית אַחַר שֶׁתֶּחֱשַׁךְ הֲרֵי זוֹ תְּרוּמָה טְהוֹרָה. לְפִי שֶׁאֵינָהּ נַעֲשֵׂית תְּרוּמַת מַעֲשֵׂר עַד שֶׁתֶּחֱשַׁךְ כְּפִי תְּנָאוֹ וְאַחַר שֶׁתֶּחֱשַׁךְ יַעֲרִיב שִׁמְשׁוֹ שֶׁל לָגִין וְיִטְהַר. נִשְׁבְּרָה הֶחָבִית קֹדֶם שֶׁתֶּחֱשַׁךְ הַלָּגִין בְּטִבְלוֹ. נִשְׁבַּר הַלָּגִין הֶחָבִית בְּטִבְלָהּ:","טְבוּל יוֹם מִטֻּמְאַת מֵת וּמִבְּעִילַת נִדָּה עוֹשֶׂה בְּבֵית הַבַּד. וְכֵן שְׁאָר הַטְּמֵאִים שֶׁטָּבְלוּ עוֹשִׂין בְּטָהֳרוֹת. חוּץ מִזָּב וְזָבָה בַּשְּׁבִיעִי שֶׁלָּהֶן שֶׁאַף עַל פִּי שֶׁטָּבְלוּ לֹא יַעֲשׂוּ בְּבֵית הַבַּד וְלֹא יִתְעַסְּקוּ בְּטָהֳרוֹת שֶׁמָּא יִרְאוּ וְנִמְצְאוּ טְמֵאִים לְמַפְרֵעַ שֶׁהֲרֵי סוֹתְרִין הַכּל כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Divorce 1":["אֵין הָאִשָּׁה מִתְגָּרֶשֶׁת אֶלָּא בִּכְתָב שֶׁיַּגִּיעַ לָהּ וּכְתָב זֶה הוּא הַנִּקְרָא גֵּט. וַעֲשָׂרָה דְּבָרִים הֵן עִקַּר הַגֵּרוּשִׁין מִן הַתּוֹרָה וְאֵלּוּ הֵן. א) שֶׁלֹּא יְגָרֵשׁ הָאִישׁ אֶלָּא בִּרְצוֹנוֹ. ב) וְשֶׁיְּגָרֵשׁ בִּכְתָב וְלֹא בְּדָבָר אַחֵר. ג) וְשֶׁיִּהְיֶה עִנְיַן הַכְּתָב שֶׁגֵּרְשָׁהּ וֶהֱסִירָהּ מִקִּנְיָנוֹ. ד) וְשֶׁיִּהְיֶה עִנְיָנוֹ דָּבָר הַכּוֹרֵת בֵּינוֹ לְבֵינָהּ. ה) וְשֶׁיִּהְיֶה נִכְתָּב לִשְׁמָהּ. ו) וְשֶׁלֹּא יִהְיֶה מְחֻסַּר מַעֲשֶׂה אַחַר כְּתִיבָתוֹ אֶלָּא נְתִינָתוֹ לָהּ [בִּלְבַד]. ז) וְשֶׁיִּתְּנֵהוּ לָהּ. ח) וְשֶׁיִּתְּנֵהוּ לָהּ בִּפְנֵי עֵדִים. ט) וְשֶׁיִּתְּנֵהוּ לָהּ בְּתוֹרַת גֵּרוּשִׁין. י) וְשֶׁיִּהְיֶה הַבַּעַל אוֹ שְׁלוּחוֹ הוּא שֶׁנּוֹתְנוֹ לָהּ. וּשְׁאָר הַדְּבָרִים שֶׁבַּגֵּט כְּגוֹן הַזְּמַן וַחֲתִימַת הָעֵדִים וְכַיּוֹצֵא בָּהֶן הַכּל מִדִּבְרֵי סוֹפְרִים:","וּמִנַּיִן שֶׁעֲשָׂרָה דְּבָרִים אֵלּוּ מִן הַתּוֹרָה. שֶׁנֶּאֱמַר (דברים כד א) \"וְהָיָה אִם לֹא תִמְצָא חֵן בְּעֵינָיו וְכָתַב לָהּ סֵפֶר כְּרִיתֻת וְנָתַן בְּיָדָהּ וְשִׁלְּחָהּ מִבֵּיתוֹ\". אִם לֹא תִמְצָא חֵן בְּעֵינָיו. מְלַמֵּד שֶׁאֵינוֹ מְגָרֵשׁ אֶלָּא בִּרְצוֹנוֹ. וְאִם נִתְגָּרְשָׁה שֶׁלֹּא בִּרְצוֹנוֹ אֵינָהּ מְגֹרֶשֶׁת. אֲבָל הָאִשָּׁה מִתְגָּרֶשֶׁת בִּרְצוֹנָהּ וְשֶׁלֹּא בִּרְצוֹנָהּ:","(דברים כד א) \"וְכָתַב\". מְלַמֵּד שֶׁאֵינָהּ מִתְגָּרֶשֶׁת אֶלָּא בִּכְתָב. (דברים כד א) \"לָהּ\". לִשְׁמָהּ. (דברים כד א) \"סֵפֶר כְּרִיתֻת\". דָּבָר הַכּוֹרֵת בֵּינוֹ לְבֵינָהּ שֶׁלֹּא יִשָּׁאֵר לוֹ עָלֶיהָ רְשׁוּת. וְאִם עֲדַיִן לֹא נִכְרַת בֵּינוֹ לְבֵינָהּ אֵינָהּ מְגֹרֶשֶׁת כְּמוֹ שֶׁיִּתְבָּאֵר. (דברים כד א) \"וְנָתַן בְּיָדָהּ\". מְלַמֵּד שֶׁאֵינָהּ מִתְגָּרֶשֶׁת עַד שֶׁיִּנָּתֵן הַגֵּט בְּיָדָהּ אוֹ בְּיַד שְׁלוּחָה שֶׁהוּא כְּיָדָהּ אוֹ לַחֲצֵרָהּ שֶׁהַכּל כְּיָדָהּ כְּמוֹ שֶׁיִּתְבָּאֵר. (דברים כד א) \"וְשִׁלְּחָהּ\". שֶׁיִּהְיֶה עִנְיַן הַגֵּט שֶׁהוּא הַמְשַׁלֵּחַ אוֹתָהּ. לֹא שֶׁיִּשְׁלַח עַצְמוֹ מִמֶּנָּה:","כֵּיצַד. כָּתַב לָהּ הֲרֵי אַתְּ מְשֻׁלַּחַת הֲרֵי אַתְּ מְגֹרֶשֶׁת הֲרֵי אַתְּ לְעַצְמֵךְ הֲרֵי אַתְּ מֻתֶּרֶת לְכָל אָדָם וְכַיּוֹצֵא בְּזֶה הָעִנְיָן הֲרֵי זוֹ מְגֹרֶשֶׁת. וְגוּפוֹ שֶׁל גֵּט הֲרֵי אַתְּ מֻתֶּרֶת לְכָל אָדָם. אֲבָל אִם כָּתַב לָהּ אֵינִי בַּעְלֵךְ אֵינִי אֲרוּסֵךְ אֵינִי אִישֵׁךְ אֵין זֶה גֵּט שֶׁנֶּאֱמַר (דברים כד א) \"וְשִׁלְּחָהּ\" וְלֹא שֶׁיִּשְׁלַח אֶת עַצְמוֹ. וְכֵן הַכּוֹתֵב לְאִשְׁתּוֹ הֲרֵי אַתְּ בַּת חוֹרִין אֵינוֹ גֵּט:","זֶה שֶׁנֶּאֱמַר בַּתּוֹרָה (דברים כד א) \"וְשִׁלְּחָהּ מִבֵּיתוֹ\" אֵין עִנְיָנוֹ שֶׁלֹּא יִגָּמְרוּ גֵּרוּשֶׁיהָ עַד שֶׁתֵּצֵא מִבֵּיתוֹ אֶלָּא כְּשֶׁמַּגִּיעַ גֵּט לְיָדָהּ גָּמְרוּ גֵּרוּשֶׁיהָ וְאַף עַל פִּי שֶׁעֲדַיִן הִיא בְּבֵיתוֹ כְּמוֹ שֶׁיִּתְבָּאֵר. שֶׁלֹּא נֶאֱמַר וְשִׁלְּחָהּ אֶלָּא שֶׁאִם גֵּרֵשׁ וְלֹא הוֹצִיאָהּ מִבֵּיתוֹ הֲרֵי זֶה כְּמִי שֶׁגֵּרֵשׁ וְהֶחֱזִיר גְּרוּשָׁתוֹ. לְפִיכָךְ צְרִיכָה מִמֶּנּוּ גֵּט כְּמוֹ שֶׁיִּתְבָּאֵר:","וּמִנַּיִן שֶׁלֹּא יִהְיֶה מְחֻסַּר מַעֲשֶׂה אַחַר כְּתִיבָתוֹ שֶׁנֶּאֱמַר (דברים כד א) \"וְכָתַב\" (דברים כד א) \"וְנָתַן\" מִי שֶׁאֵינוֹ מְחֻסָּר אֶלָּא כְּתִיבָה וּנְתִינָה הוּא הַגֵּט הַכָּשֵׁר. יָצָא דָּבָר שֶׁמְּחֻסַּר קְצִיצָה אַחַר הַכְּתִיבָה. לְפִיכָךְ אִם כָּתַב גֵּט עַל קֶרֶן הַפָּרָה נוֹתֵן לָהּ הַפָּרָה. וְאִם חָתַךְ הַקֶּרֶן אַחַר שֶׁכְּתָבוֹ וּנְתָנוֹ לָהּ אֵינוֹ גֵּט. וְכֵן אִם כָּתַב בִּמְחֻבָּר אַף עַל פִּי שֶׁחָתְמוּ בּוֹ הָעֵדִים אַחַר שֶׁתְּלָשׁוֹ וּנְתָנוֹ לָהּ אֵינוֹ גֵּט:","אֵין כּוֹתְבִין בִּמְחֻבָּר אֲפִלּוּ טֹפֶס הַגֵּט. כָּתַב הַטֹּפֶס בִּמְחֻבָּר וּתְלָשׁוֹ וְאַחַר כָּךְ כָּתַב שֵׁם הָאִישׁ וְשֵׁם הָאִשָּׁה וְהַזְּמַן וַהֲרֵי אַתְּ מֻתֶּרֶת לְכָל אָדָם וַחֲתָמוֹ וּנְתָנוֹ לָהּ כָּשֵׁר:","כָּתַב כָּל הַגֵּט עַל הֶעָלֶה הַזָּרוּעַ בְּעָצִיץ נָקוּב אַף עַל פִּי שֶׁנָּתַן לָהּ הֶעָצִיץ כֻּלּוֹ הַגֵּט פָּסוּל גְּזֵרָה שֶׁמָּא יִקְטֹם. אֲבָל כּוֹתֵב הוּא עַל חַרְסוֹ שֶׁל עָצִיץ וְנוֹתֵן לָהּ:","וּמִנַּיִן שֶׁאֵינוֹ נוֹתְנוֹ לָהּ אֶלָּא בְּתוֹרַת גֵּרוּשִׁין שֶׁנֶּאֱמַר (דברים כד א) \"סֵפֶר כְּרִיתֻת\" וְנָתַן בְּיָדָהּ שֶׁיִּתֵּן אוֹתוֹ בְּתוֹרַת סֵפֶר כְּרִיתֻת. אֲבָל אִם נְתָנוֹ לָהּ בְּתוֹרַת שֶׁהוּא שְׁטַר חוֹב אוֹ מְזוּזָה אוֹ שֶׁנְּתָנוֹ בְּיָדָהּ וְהִיא יְשֵׁנָה וְנֵעוֹרָה וַהֲרֵי הוּא בְּיָדָהּ אֵינוֹ גֵּט. וְאִם אָמַר לָהּ אַחַר כָּךְ הֲרֵי הוּא גִּטֵּךְ הֲרֵי זֶה גֵּט:","אָמַר לְעֵדִים רְאוּ גֵּט שֶׁאֲנִי נוֹתֵן לָהּ וְחָזַר וְאָמַר לָהּ כִּנְסִי שְׁטַר חוֹב זֶה הֲרֵי זֶה כָּשֵׁר. שֶׁהֲרֵי הוֹדִיעַ אֶת הָעֵדִים שֶׁנְּתָנוֹ בְּתוֹרַת גֵּרוּשִׁין. וְזֶה שֶׁאָמַר לָהּ שְׁטַר חוֹב מִפְּנֵי שֶׁנִּכְלַם מִמֶּנָּה:","הַמְגָרֵשׁ צָרִיךְ שֶׁיֹּאמַר לָהּ כְּשֶׁיִּתֵּן לָהּ הַגֵּט הֲרֵי זֶה גִּטֵּךְ אוֹ הוּא גִּטֵּךְ וְכַיּוֹצֵא בָּזֶה. וְאִם נָתַן בְּיָדָהּ וְלֹא אָמַר כְּלוּם הֲרֵי זֶה גֵּט פָּסוּל. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁלֹּא הָיָה מְדַבֵּר עִמָּהּ עַל עִסְקֵי גִּטָּהּ. אֲבָל אִם הָיָה מְדַבֵּר עַל עִסְקֵי גִּטָּהּ וְנָטַל הַגֵּט וְנָתַן בְּיָדָהּ וְלֹא אָמַר כְּלוּם הֲרֵי זֶה גֵּט כָּשֵׁר:","גֵּט שֶׁהָיָה מֻנָּח עַל הָאָרֶץ וְאָמַר לָהּ טְלִי גִּטֵּךְ מֵעַל גַּבֵּי קַרְקַע וּנְטָלַתּוּ אוֹ שֶׁהָיָה קָשׁוּר עַל יָדוֹ אוֹ עַל יְרֵכוֹ וּשְׁלָפַתּוּ מִמֶּנּוּ אַף עַל פִּי שֶׁאָמַר לָהּ אַחַר שֶׁבָּא לְיָדָהּ הֲרֵי זֶה גִּטֵּךְ אֵינוֹ גֵּט שֶׁנֶּאֱמַר (דברים כד א) \"וְנָתַן בְּיָדָהּ\" לֹא שֶׁתִּקַּח הִיא מֵעַצְמָהּ וַהֲרֵי לֹא נָתַן לָהּ לֹא הוּא וְלֹא שְׁלוּחוֹ. אֲבָל אִם הִרְכִּין לָהּ בְּגוּפוֹ אוֹ הִטָּה יָדוֹ עַד שֶׁשָּׁלְפָה הַגֵּט מֵעָלָיו וְאָמַר לָהּ הֲרֵי זֶה גִּטֵּךְ הֲרֵי זֶה גֵּט:","וּמִנַּיִן שֶׁיִּתְּנֶנּוּ לָהּ בִּפְנֵי עֵדִים. הֲרֵי הוּא אוֹמֵר (דברים יט טו) \"עַל פִּי שְׁנַיִם עֵדִים אוֹ שְׁלֹשָׁה עֵדִים יָקוּם דָּבָר\". וְאִי אֶפְשָׁר שֶׁתִּהְיֶה זוֹ הַיּוֹם עֶרְוָה וְהַבָּא עָלֶיהָ בְּמִיתַת בֵּית דִּין וּלְמָחָר תִּהְיֶה מֻתֶּרֶת בְּלֹא עֵדִים. לְפִיכָךְ אִם נָתַן לָהּ גֵּט בֵּינוֹ לְבֵינָהּ וַאֲפִלּוּ בְּעֵד אֶחָד אֵינוֹ גֵּט כְּלָל:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה הַגֵּט בִּכְתַב יַד סוֹפֵר. אֲבָל אִם כָּתַב הַבַּעַל הַגֵּט בִּכְתַב יָדוֹ וְחָתַם עָלָיו עֵד אֶחָד וּנְתָנוֹ לָהּ הֲרֵי זֶה גֵּט פָּסוּל [וּפוֹסֵל לִכְהֻנָּה]:","תַּקָּנַת חֲכָמִים הוּא שֶׁיִּהְיוּ הָעֵדִים חוֹתְמִין עַל הַגֵּט. שֶׁמָּא יִתֵּן לָהּ גֵּט בִּפְנֵי שְׁנַיִם וְיָמוּתוּ וְנִמְצָא הַגֵּט שֶׁבְּיָדָהּ כְּחֶרֶס מֵחַרְסֵי אֲדָמָה שֶׁהֲרֵי אֵין בּוֹ עֵדִים. לְפִיכָךְ תִּקְּנוּ שֶׁיָּעִידוּ מִתּוֹכוֹ. וְאַף עַל פִּי שֶׁהָעֵדִים בְּתוֹכוֹ נוֹתְנוֹ לָהּ בִּפְנֵי שְׁנַיִם בֵּין בִּפְנֵי אוֹתָן הָעֵדִים הַחֲתוּמִין עָלָיו בֵּין בִּפְנֵי שְׁנַיִם אֲחֵרִים. שֶׁעִקַּר הַגֵּרוּשִׁין בְּעֵדֵי מְסִירָה:","חָתְמוּ בּוֹ שְׁנַיִם וְעָבַר וּנְתָנוֹ לָהּ בֵּינוֹ לְבֵינָהּ אוֹ שֶׁנִּמְצְאוּ עֵדֵי מְסִירָה פְּסוּלִין הֲרֵי זֶה כָּשֵׁר הוֹאִיל וְעֵדִים שֶׁבּוֹ כְּשֵׁרִין וַהֲרֵי הַגֵּט יוֹצֵא מִתַּחַת יָדֶיהָ. וְיֵשׁ שֶׁהוֹרָה מִן הַגְּאוֹנִים שֶׁהוּא פָּסוּל:","הָיוּ עֵדָיו מִתּוֹכוֹ פְּסוּלִין אֲפִלּוּ אֶחָד פָּסוּל וְאֶחָד כָּשֵׁר וּנְתָנוֹ לָהּ בִּפְנֵי שְׁנֵי עֵדִים כְּשֵׁרִין הֲרֵי זֶה פָּסוּל שֶׁנִּמְצָא כִּמְזֻיָּף מִתּוֹכוֹ:","הִרְחִיק אֶת הָעֵדִים מִן הַכְּתָב מְלֹא שְׁנֵי שִׁיטִין פָּסוּל. וְכַמָּה יַרְחִיק אֶת הָעֵדִים מִן הַכְּתָב פָּחוֹת מִכְּדֵי שְׁנֵי שִׁיטִין כְּדֵי שֶׁיִּהְיוּ נִקְרָאִין עִמּוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה הַגֵּט יוֹצֵא מִתַּחַת יָדֶיהָ וְלֹא הָיוּ שָׁם עֵדֵי מְסִירָה. אֲבָל אִם מְסָרוֹ לָהּ בְּעֵדִים אַף עַל פִּי שֶׁהֵן מְרֻחָקִין הַרְבֵּה וְאֵין נִקְרָאִין עִמּוֹ וְאַף עַל פִּי שֶׁאֵין חָתוּם עָלָיו עֵד כְּלָל הֲרֵי זֶה כָּשֵׁר. שֶׁעִקַּר הַגֵּרוּשִׁין בְּעֵדֵי מְסִירָה:","הָעֵדִים שֶׁנּוֹתֵן אֶת הַגֵּט בִּפְנֵיהֶם צְרִיכִין לִקְרוֹתוֹ וְאַחַר כָּךְ יִתְּנֶנּוּ לָהּ. וְאִם נְתָנוֹ לָהּ בִּפְנֵיהֶם תְּחִלָּה חוֹזְרִין וְקוֹרְאִין אוֹתוֹ אַחַר שֶׁנְּתָנוֹ לָהּ. קְרָאוּהוּ וְהוּא בְּיַד הַבַּעַל אוֹ בְּיַד שְׁלוּחוֹ וְהֶחְזִירוּהוּ לוֹ. וְחָזַר הוּא וְהִכְנִיסוֹ לְתוֹךְ יָדוֹ וּנְתָנוֹ לָהּ חוֹזְרִין וְקוֹרְאִין אוֹתוֹ:","לֹא קְרָאוּהוּ אֶלָּא נָטְלָתוֹ וּזְרָקַתּוּ לַיָּם אוֹ לָאֵשׁ הֲרֵי זוֹ מְגֹרֶשֶׁת. הוֹאִיל וּקְרָאוּהוּ תְּחִלָּה אֵין חוֹשְׁשִׁים לוֹ שֶׁהֶחֱלִיפוֹ. וְלֹא עוֹד אֶלָּא אֲפִלּוּ אָמַר הַבַּעַל שְׁטָר אַחֵר הָיָה וְלֹא הָיָה הַגֵּט שֶׁקְּרָאתֶם אֵינוֹ נֶאֱמָן וַהֲרֵי הִיא מְגֹרֶשֶׁת:","הֲרֵי שֶׁלֹּא קָרְאוּ הַגֵּט בַּתְּחִלָּה וְנָתַן לָהּ הַגֵּט בִּפְנֵיהֶם וּזְרָקַתּוּ לָאוּר אוֹ לַיָּם אַף עַל פִּי שֶׁהַבַּעַל אוֹמֵר גֵּט כָּשֵׁר הָיָה הֲרֵי זוֹ סָפֵק מְגֹרֶשֶׁת:","זָרַק לָהּ הַגֵּט לַחֲצֵרָהּ לְבֵין הֶחָבִיּוֹת בִּפְנֵי עֵדִים וּבִקְּשׁוּ וּמָצְאוּ מְזוּזָה אוֹ שְׁטָר אַחֵר אֵין חוֹשְׁשִׁין לָהּ. שֶׁזֶּה שֶׁנִּמְצָא הוּא שֶׁזָּרַק. נִמְצְאוּ שָׁם שְׁתַּיִם שָׁלֹשׁ מְזוּזוֹת אוֹ שְׁטָרוֹת חוֹשְׁשִׁין שֶׁמָּא גֵּט שֶׁזָּרַק גְּרָרוּהוּ עַכְבָּרִים וַהֲרֵי זוֹ סָפֵק מְגֹרֶשֶׁת:","הָעֵדִים שֶׁחוֹתְמִין עַל הַגֵּט צְרִיכִים לִהְיוֹתָם יוֹדְעִים לִקְרוֹת וְלַחְתֹּם. וְאִם אֵינָם יוֹדְעִים לִקְרוֹת קוֹרְאִים בִּפְנֵיהֶם וְחוֹתְמִים. וְהוּא שֶׁיַּכִּירוּ לְשׁוֹן הַגֵּט. וְאִם אֵינָם יוֹדְעִים לַחְתֹּם רוֹשְׁמִין לָהֶם הַנְּיָר בְּרֹק וְכַיּוֹצֵא בּוֹ מִדָּבָר שֶׁאֵין רִשּׁוּמוֹ מִתְקַיֵּם וְהֵן כּוֹתְבִין עַל הָרשֶׁם. וְאֵין עוֹשִׂין כָּךְ בִּשְׁאָר שְׁטָרוֹת. קַל הוּא שֶׁהֵקֵלּוּ בְּגִטֵּי נָשִׁים כְּדֵי שֶׁלֹּא יִהְיוּ בְּנוֹת יִשְׂרָאֵל עֲגוּנוֹת הוֹאִיל וַחֲתִימַת הָעֵדִים בְּגֵט מִדִּבְרֵיהֶם כְּמוֹ שֶׁבֵּאַרְנוּ:","אַף עַל פִּי שֶׁחֲתִימַת הָעֵדִים בְּגֵט מִדִּבְרֵיהֶם הִתְקִינוּ שֶׁיִּהְיוּ הָעֵדִים מְפָרְשִׁין שְׁמוֹתֵיהֶן בַּגֵּט. וְכֵן הִתְקִינוּ בְּעֵדֵי הַגֵּט שֶׁאֵין חוֹתְמִין אֶלָּא זֶה בִּפְנֵי זֶה. וְאִם חָתְמוּ זֶה שֶׁלֹּא בִּפְנֵי זֶה הֲרֵי זֶה גֵּט פָּסוּל. וְכֵן הִתְקִינוּ חֲכָמִים שֶׁיִּכְתֹּב זְמַן בַּגֵּט וּמְקוֹם כְּתִיבָתוֹ כִּשְׁאָר הַשְּׁטָרוֹת. שֶׁמָּא תִּהְיֶה אִשְׁתּוֹ קְרוֹבָתוֹ וְתִזְנֶה כְּשֶׁהִיא תַּחְתָּיו וְיִכְתֹּב לָהּ גֵּט אַחַר הַזְּנוּת וְיִתֵּן לָהּ. וְאִם לֹא יִהְיֶה בּוֹ זְמַן יְכוֹלָה לוֹמַר קֹדֶם הַזְּנוּת נִתְגָּרַשְׁתִּי. וּלְפִיכָךְ תִּקְּנוּ זְמַן בְּגִטִּין:","גֵּט שֶׁיֵּשׁ עָלָיו עֵדִים וְאֵין בּוֹ זְמַן אוֹ שֶׁהָיָה מֻקְדָּם אוֹ מְאֻחָר אוֹ שֶׁנִּכְתַּב בַּיּוֹם וְנֶחְתַּם בַּלַּיְלָה שֶׁלְּאַחֲרָיו אַף עַל פִּי שֶׁעֲסוּקִין בְּאוֹתוֹ הָעִנְיָן. אוֹ כָּתַב אֶת הַגֵּט בִּירוּשָׁלַיִם וְטָעָה וְכָתַב בְּלוּד. כָּל אֵלּוּ פְּסוּלִין עַד שֶׁיַּחְתְּמוּ בּוֹ בִּזְמַן כְּתִיבָתוֹ וּבִמְקוֹם כְּתִיבָתוֹ:","חָתַךְ מִמֶּנּוּ הַזְּמַן וּנְתָנוֹ לָהּ אוֹ שֶׁלֹּא כָּתַב שֵׁם הַיּוֹם אֶלָּא בְּשַׁבָּת רִאשׁוֹנָה אוֹ שְׁנִיָּה מֵחֹדֶשׁ פְּלוֹנִי אוֹ בְּחֹדֶשׁ פְּלוֹנִי אוֹ בְּשָׁנָה פְּלוֹנִית וְלֹא הִזְכִּיר הַחֹדֶשׁ אֲפִלּוּ כָּתַב בְּשָׁבוּעַ פְּלוֹנִי כָּשֵׁר. וְכֵן אִם כָּתַב בּוֹ הַיּוֹם גֵּרַשְׁתִּיהָ כָּשֵׁר שֶׁמַּשְׁמָעוֹ הַיּוֹם הַזֶּה שֶׁיָּצָא בּוֹ הַגֵּט:","וְכֵן תִּקְּנוּ שֶׁיְּהוּ מוֹנִין בְּגִטִּין לְמַלְכוּת אוֹתוֹ הַזְּמַן מִשּׁוּם שְׁלוֹם מַלְכוּת. כָּתַב לְשֵׁם מַלְכוּת שֶׁאֵינָהּ מַלְכוּת אוֹתָהּ הַמְּדִינָה אוֹ לְבִנְיַן הַבַּיִת אוֹ לְחֻרְבַּן הַבַּיִת אִם דֶּרֶךְ אַנְשֵׁי אוֹתוֹ מָקוֹם לִמְנוֹת בּוֹ הֲרֵי זֶה כָּשֵׁר וְאִם אֵין דַּרְכָּן לִמְנוֹת בּוֹ הֲרֵי זֶה פָּסוּל. וּכְבָר נָהֲגוּ כָּל יִשְׂרָאֵל לִמְנוֹת בְּגִטִּין אוֹ לִיצִירָה אוֹ לַמַּלְכוּת אֲלֶכְּסַנְדְּרוֹס מַקְדוֹן שֶׁהוּא מִנְיַן שְׁטָרוֹת. וְאִם כָּתַב לְשֵׁם מַלְכוּת אוֹתוֹ זְמַן בִּמְדִינָה שֶׁיֵּשׁ בָּהּ רְשׁוּת אוֹתָהּ מַלְכוּת הֲרֵי זֶה כָּשֵׁר:","הָאוֹמֵר לִשְׁנַיִם כִּתְבוּ וְחִתְמוּ וּתְנוּ גֵּט לְאִשְׁתִּי וְנִתְאַחֵר הַדָּבָר יָמִים אוֹ שָׁנִים. אוֹ שֶׁנִּמְצָא הַגֵּט בָּטֵל וְהֻצְרְכוּ לִכְתֹּב לָהּ גֵּט אַחֵר כָּשֵׁר אַחַר כַּמָּה שָׁנִים כְּמוֹ שֶׁיִּתְבָּאֵר. הֲרֵי אֵלּוּ כּוֹתְבִין זְמַן הַכְּתִיבָה וּמְקוֹם הַכְּתִיבָה, לֹא הַזְּמַן שֶׁאָמַר לָהֶן הַבַּעַל בּוֹ כִּתְבוּ וְלֹא אוֹתוֹ הַמָּקוֹם. כֵּיצַד. הָיוּ בִּירוּשָׁלַיִם כְּשֶׁאָמַר לָהֶן וְהָיוּ עוֹמְדִין בְּתִשְׁרֵי וְנִתְאַחֲרוּ עַד נִיסָן וַהֲרֵי הֵן בְּלוּד כּוֹתְבִין זְמַן הַגֵּט מִנִּיסָן וּבְלוּד שֶׁשָּׁם נִכְתַּב הַגֵּט כִּשְׁאָר שְׁטָרוֹת:"],"Mishneh Torah, Divorce 9":["הַמְגָרֵשׁ אֶת אִשְׁתּוֹ לְאַחַר זְמַן קָבוּעַ הֲרֵי זוֹ מְגֹרֶשֶׁת כְּשֶׁיַּגִּיעַ הַזְּמַן שֶׁקָּבַע. וַהֲרֵי זֶה דּוֹמֶה לִתְנַאי וְאֵינוֹ תְּנַאי. דּוֹמֶה לִתְנַאי שֶׁהִיא מִתְגָּרֶשֶׁת כְּשֶׁיַּגִּיעַ הַזְּמַן שֶׁקָּבַע. וְאֵינוֹ תְּנַאי שֶׁהַמְגָרֵשׁ עַל תְּנַאי הֲרֵי גֵּרֵשׁ וְזֶה עֲדַיִן לֹא גֵּרֵשׁ עַד שֶׁיַּגִּיעַ אוֹתוֹ הַזְּמַן. לְפִיכָךְ הַמְגָרֵשׁ עַל תְּנַאי צָרִיךְ לִכְפֹּל תְּנָאוֹ וְזֶה אֵינוֹ צָרִיךְ לִכְפֹּל דְּבָרוֹ וְלֹא לִשְׁאָר מִשְׁפְּטֵי הַתְּנָאִין שֶׁבֵּאַרְנוּ:","כֵּיצַד. הָאוֹמֵר לְאִשְׁתּוֹ הֲרֵי זֶה גִּטֵּךְ וְלֹא תִּתְגָּרְשִׁי בּוֹ אֶלָּא לְאַחַר שְׁלֹשִׁים יוֹם אֵינָהּ מְגֹרֶשֶׁת אֶלָּא לְאַחַר שְׁלֹשִׁים יוֹם. וְאִם מֵת הַבַּעַל אוֹ אָבַד הַגֵּט אוֹ נִשְׂרַף בְּתוֹךְ שְׁלֹשִׁים אֵינָהּ מְגֹרֶשֶׁת:","הָלְכָה וְהִנִּיחָתוֹ בְּצִדֵּי רְשׁוּת הָרַבִּים וְנִגְנַב אוֹ אָבַד מִשָּׁם לְאַחַר שְׁלֹשִׁים יוֹם הֲרֵי זוֹ מְגֹרֶשֶׁת הוֹאִיל וְהָיָה הַגֵּט קַיָּם בַּיּוֹם שֶׁמִּתְגָּרֶשֶׁת בּוֹ וְיִחֲדָה אוֹתוֹ בְּמָקוֹם שֶׁאֵינוֹ רְשׁוּת הָרַבִּים. שֶׁצִּדֵּי רְשׁוּת הָרַבִּים אֵינָן כִּרְשׁוּת הָרַבִּים:","וְכֵן אִם תָּלָה הַגֵּרוּשִׁין בְּמַעֲשֶׂה דִּינוֹ כְּדִין מְגָרֵשׁ אַחַר זְמַן. כֵּיצַד. כְּגוֹן שֶׁאָמַר לְאִשָּׁה הֲרֵי זֶה גִּטֵּךְ וְלֹא תִּתְגָּרְשִׁי בּוֹ עַד שֶׁתִּתְּנִי לִי מָאתַיִם זוּז הֲרֵי זוֹ מִתְגָּרֶשֶׁת אַחַר שֶׁתִּתֵּן. וְאֵין צָרִיךְ לִכְפֹּל תְּנָאוֹ וְלֹא לִשְׁאָר מִשְׁפְּטֵי הַתְּנָאִין שֶׁבֵּאַרְנוּ. שֶׁהֲרֵי לֹא גֵּרֵשׁ עַל תְּנַאי אֶלָּא עֲדַיִן לֹא גֵּרֵשׁ זֶה אֶלָּא תָּלָה הַגֵּרוּשִׁין בַּעֲשִׂיַּת כָּךְ וְכָךְ וְאַחַר כָּךְ תִּתְגָּרֵשׁ:","וּמַה בֵּין הַמְגָרֵשׁ עַל תְּנַאי לְזֶה שֶׁקָּבַע זְמַן לְגֵרוּשִׁין אוֹ תְּלָאָן בְּמַעֲשֶׂה. שֶׁהַמְגָרֵשׁ עַל תְּנַאי יֵשׁ שָׁם גֵּרוּשִׁין וְאֵינָן גּוֹמְרִין עַד שֶׁיִּתְקַיֵּם הַתְּנַאי. לְפִיכָךְ כְּשֶׁיִּתְקַיֵּם הַתְּנַאי נִתְגָּרְשָׁה אִם הָיָה הַגֵּט קַיָּם אַף עַל פִּי שֶׁאֵינוֹ בִּרְשׁוּתָהּ וְאֵינָהּ צְרִיכָה לַחֲזֹר וְלִטְּלוֹ אוֹ לִהְיוֹתוֹ בִּרְשׁוּתָהּ אַחַר שֶׁנִּתְקַיֵּם הַתְּנַאי שֶׁהֲרֵי הִגִּיעַ לְיָדָהּ תְּחִלָּה בְּתוֹרַת גֵּרוּשִׁין. וְאִם נִשֵּׂאת קֹדֶם שֶׁיִּתְקַיֵּם הַתְּנַאי לֹא תֵּצֵא כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל הַתּוֹלֶה גֵּרוּשִׁין בִּזְמַן אוֹ בְּמַעֲשֶׂה לֹא הִגִּיעַ גֵּט לְיָדָהּ בְּתוֹרַת גֵּרוּשִׁין אֶלָּא בְּתוֹרַת פִּקָּדוֹן עַד הַזְמֵן שֶׁקָּבַע אוֹ עַד שֶׁתַּעֲשֶׂה הַמַּעֲשֶׂה. לְפִיכָךְ כְּשֶׁהִגִּיעַ הַזְּמַן צְרִיכָה לִהְיוֹת הַגֵּט בִּרְשׁוּתָהּ אוֹ תַּחֲזֹר וְתִטְּלֶנּוּ אוֹ שֶׁיִּהְיֶה בַּמָּקוֹם שֶׁיִּחֲדָה אוֹתוֹ בּוֹ אַף עַל פִּי שֶׁאֵינוֹ רְשׁוּתָהּ כְּמוֹ שֶׁבֵּאַרְנוּ וְאַחַר כָּךְ תִּתְגָּרֵשׁ בּוֹ. וְאִם נִשֵּׂאת קֹדֶם שֶׁיַּגִּיעַ הַזְּמַן שֶׁקָּבַע אוֹ קֹדֶם שֶׁתַּעֲשֶׂה הַמַּעֲשֶׂה שֶׁתָּלָה בּוֹ הַגֵּרוּשִׁין תֵּצֵא וְהַוָּלָד מַמְזֵר שֶׁעֲדַיִן הִיא אֵשֶׁת אִישׁ גְּמוּרָה וְאֵין כָּאן שֵׁם גֵּרוּשִׁין:","הַנּוֹתֵן גֵּט בְּיַד אִשְׁתּוֹ וְאָמַר לָהּ אִם לֹא תִּתְּנִי לִי מָאתַיִם זוּז אֵין זֶה גֵּט אוֹ אֵין אַתְּ מְגֹרֶשֶׁת הֲרֵי זֶה לֹא גֵּרֵשׁ כְּלָל וְאֵין כָּאן גֵּט לֹא עַל תְּנַאי וְלֹא תָּלוּי בְּמַעֲשֶׂה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הָרוֹצֶה לְגָרֵשׁ עַל תְּנַאי וְיִהְיֶה עִנְיַן תְּנָאוֹ שֶׁלֹּא תִּתְגָּרֵשׁ עַד זְמַן פְּלוֹנִי הֲרֵי זֶה מוֹצִיא עִנְיָן זֶה בִּלְשׁוֹן תְּנַאי וְיִתְלֶה הַתְּנַאי בְּבִיאָתוֹ בִּזְמַן קָבוּעַ אוֹ בַּהֲלִיכָתוֹ. כֵּיצַד. כְּגוֹן שֶׁיֹּאמַר לָהּ אִם לֹא בָּאתִי מִכָּאן וְעַד שְׁלֹשִׁים יוֹם הֲרֵי זֶה גֵּט וְאִם בָּאתִי בְּתוֹךְ שְׁלֹשִׁים יוֹם לֹא יִהְיֶה גֵּט וְנוֹתֵן הַגֵּט בְּיָדָהּ. אוֹ יֹאמַר לָהּ הֲרֵי זֶה גִּטֵּךְ עַל מְנָת שֶׁלֹּא אָבוֹא לִמְדִינָה זוֹ עַד שְׁלֹשִׁים יוֹם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הִתְנָה עָלֶיהָ שֶׁיִּהְיֶה גֵּט אִם לֹא בָּא עַד שְׁלֹשִׁים יוֹם לִמְדִינָה זוֹ וְהָיָה בָּא בַּדֶּרֶךְ בְּתוֹךְ שְׁלֹשִׁים יוֹם וְחָלָה אוֹ עִכְּבוֹ נָהָר וְלֹא בָּא עַד אַחַר שְׁלֹשִׁים יוֹם הֲרֵי זֶה גֵּט. אֲפִלּוּ עוֹמֵד וְצוֹוֵחַ הֲרֵי אֲנִי אָנוּס שֶׁאֵין אֹנֶס בְּגִטִּין. וְאַף עַל פִּי שֶׁגִּלָּה דַּעְתּוֹ שֶׁאֵין רְצוֹנוֹ לְגָרֵשׁ:","הִתְנָה עָלֶיהָ שֶׁתִּתְגָּרֵשׁ כְּשֶׁיַּעֲבֹר מִנֶּגֶד פָּנֶיהָ שְׁלֹשִׁים יוֹם וְהָיָה הוֹלֵךְ וּבָא הוֹלֵךְ וּבָא וְלֹא נִתְיַחֵד עִמָּהּ כְּשֶׁיֵּלֵךְ וְיִשְׁהֶה שְׁלֹשִׁים יוֹם תִּהְיֶה מְגֹרֶשֶׁת. וְאַף עַל פִּי שֶׁהָיָה הוֹלֵךְ וּבָא בְּתוֹךְ שְׁלֹשִׁים יוֹם הוֹאִיל וְלֹא נִתְיַחֵד עִמָּהּ הֲרֵי זֶה גֵּט כָּשֵׁר. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהִתְנָה וְאָמַר הֲרֵי הִיא נֶאֱמֶנֶת עָלַי לוֹמַר שֶׁלֹּא פִּיַּסְתִּיהָ. אֲבָל אִם לֹא הֶאֱמִינָהּ חוֹשְׁשִׁין שֶׁמָּא פִּיְּסָהּ כְּשֶׁהָיָה הוֹלֵךְ וּבָא וּמָחֲלָה לוֹ וְחָזַר וּבָטַל הַגֵּט כְּשֶׁפִּיְּסָהּ. וּמִפְּנֵי חֲשָׁשׁ זֶה יִהְיֶה הַגֵּט פָּסוּל אַחַר שְׁלֹשִׁים יוֹם. וְכֵן הָאוֹמֵר לְאִשָּׁה הֲרֵי זֶה גִּטֵּךְ לְאַחַר שְׁנֵים עָשָׂר חֹדֶשׁ וְהָיָה עִמָּהּ בַּמְּדִינָה חוֹשְׁשִׁין שֶׁמָּא פִּיְּסָהּ עַד שֶׁיֹּאמַר נֶאֱמֶנֶת עָלַי שֶׁלֹּא פִּיַּסְתִּי:","וְכֵן כָּל הַתְּנָאִין שֶׁהֵן תְּלוּיִין בִּרְצוֹנָהּ וְאִם רָצָת וּמָחֲלָה אוֹתָן לְבַעְלָהּ בָּטֵל הַגֵּט חוֹשְׁשִׁין לָהּ שֶׁמָּא פִּיֵּס עַד שֶׁיֹּאמַר נֶאֱמֶנֶת עָלַי. בַּמֶּה דְּבָרִים אֲמוּרִים בְּמִתְגָּרֶשֶׁת מִן הַנִּשּׂוּאִין שֶׁלִּבּוֹ גַּס בָּהּ אֲבָל בְּמִתְגָּרֶשֶׁת מִן הָאֵרוּסִין אֵין חוֹשְׁשִׁין לוֹ שֶׁמָּא פִּיֵּס:","הֲרֵי זֶה גִּטֵּךְ מֵעַכְשָׁו אִם לֹא בָּאתִי מִכָּאן וְעַד שְׁנֵים עָשָׂר חֹדֶשׁ אֵין חוֹשְׁשִׁין שֶׁמָּא בַּסֵּתֶר בָּא שֶׁאֵין דֶּרֶךְ בְּנֵי אָדָם לָבוֹא בְּצִנְעָה. וְאִם תָּם הַזְּמַן שֶׁקָּבַע וְלֹא בָּא הֲרֵי זוֹ מְגֹרֶשֶׁת. מֵת בְּתוֹךְ י״‎ב חדֶשׁ אַף עַל פִּי שֶׁאִי אֶפְשָׁר שֶׁיָּבוֹא וַהֲרֵי הִיא מְגֹרֶשֶׁת לֹא תִּנָּשֵׂא בִּמְקוֹם יָבָם עַד אַחַר שְׁנֵים עָשָׂר חֹדֶשׁ כְּשֶׁיִּתְקַיֵּם הַתְּנַאי:","בָּרִיא שֶׁהִתְנָה שֶׁיִּהְיֶה זֶה גֵּט אִם מַתִּי. אוֹ חוֹלֶה שֶׁהִתְנָה שֶׁיִּהְיֶה זֶה גֵּט אִם מַתִּי מֵחלִי זֶה לֹא אָמַר כְּלוּם. שֶׁמַּשְׁמָעוּת אִם מַתִּי לְאַחַר מִיתָה וּמַשְׁמָעוֹ מֵעַתָּה. לְפִיכָךְ אִם אָמַר אִם מַתִּי הֲרֵי זֶה כְּאוֹמֵר לְאַחַר מוֹתִי וְאֵין גֵּט לְאַחַר מִיתָה:","אָמַר לָהּ הֲרֵי זֶה גִּטֵּךְ מֵעַכְשָׁו אִם מַתִּי אוֹ מֵהַיּוֹם אִם מַתִּי הֲרֵי זֶה גֵּט וּכְשֶׁיָּמוּת תִּהְיֶה מְגֹרֶשֶׁת:","אָמַר לָהּ הֲרֵי זֶה גִּטֵּךְ מֵעַכְשָׁו אוֹ מֵהַיּוֹם לְאַחַר מִיתָתִי וּמֵת הֲרֵי זוֹ סָפֵק מְגֹרֶשֶׁת שֶׁמָּא אַחַר שֶׁאָמַר מֵעַכְשָׁו חָזַר בּוֹ מִלְּשׁוֹן מֵעַכְשָׁו וְסָמְכָה דַּעְתּוֹ עַל לְאַחַר מִיתָה וְאֵין גֵּט לְאַחַר מִיתָה:","הֲרֵי זֶה גִּטֵּךְ לִכְשֶׁתֵּצֵא חַמָּה מִנַּרְתֵּקָהּ וּמֵת בַּלַּיְלָה אֵינוֹ גֵּט. עַל מְנָת שֶׁתִּזְרַח חַמָּה וּמֵת בַּלַּיְלָה הֲרֵי זוֹ מְגֹרֶשֶׁת וּכְשֶׁתִּזְרַח חַמָּה יִתְקַיֵּם הַתְּנַאי. הִתְנָה עָלֶיהָ שֶׁאִם זָרְחָה חַמָּה יִהְיֶה גֵּט וְאִם לֹא זָרְחָה לֹא יִהְיֶה גֵּט וּמֵת בַּלַּיְלָה אֵינוֹ גֵּט שֶׁהֲרֵי לֹא נִתְקַיֵּם הַתְּנַאי עַד שֶׁמֵּת וְאֵין גֵּט לְאַחַר מִיתָה:","שְׁכִיב מֵרַע שֶׁכָּתַב גֵּט לְאִשְׁתּוֹ וְגֵרֵשׁ וְעָמַד אֵינוֹ יָכוֹל לַחֲזֹר בּוֹ שֶׁאֵין גִּטּוֹ כְּמַתְּנָתוֹ. שֶׁאִם תֹּאמַר יַחֲזֹר בּוֹ יֹאמְרוּ גִּטּוֹ לְאַחַר מִיתָה יְגָרֵשׁ כְּמוֹ מַתְּנָתוֹ שֶׁאֵינָהּ קוֹנָה אֶלָּא לְאַחַר מִיתָה:","הֲרֵי זֶה גִּטֵּךְ מֵהַיּוֹם אִם מַתִּי מֵחלִי זֶה וְנָפַל עָלָיו בַּיִת אוֹ נְשָׁכוֹ נָחָשׁ אוֹ טְרָפוֹ אֲרִי וְכַיּוֹצֵא בָּזֶה וּמֵת אֵינוֹ גֵּט:","אָמַר לָהּ אִם לֹא יַעֲמֹד מֵחלִי זֶה וְנָפַל עָלָיו בַּיִת אוֹ נְשָׁכוֹ נָחָשׁ אוֹ טְרָפוֹ אֲרִי הֲרֵי זוֹ סָפֵק מְגֹרֶשֶׁת. הֲרֵי זֶה גִּטֵּךְ מֵעַכְשָׁו אִם מַתִּי מֵחלִי זֶה וְעָמַד וְהָלַךְ בַּשּׁוּק וְחָלָה וּמֵת אוֹמְדִין אוֹתוֹ אִם מֵחֲמַת הַחלִי הָרִאשׁוֹן מֵת הֲרֵי זֶה גֵּט וְאִם לָאו אֵינוֹ גֵּט. וְאִם נִתַּק מֵחלִי לְחלִי וְלֹא עָמַד בַּשּׁוּק הֲרֵי זֶה גֵּט וְאֵינוֹ צָרִיךְ אֹמֶד:","וּבְכָל אֵלּוּ הַתְּנָאִין כָּל הַיָּמִים שֶׁמִּנְּתִינַת הַגֵּט עַד שֶׁיָּמוּת וְיִתְקַיֵּם הַתְּנַאי הֲרֵי הִיא מְגֹרֶשֶׁת לְכָל דָּבָר. וּבִלְבַד שֶׁלֹּא תִּתְיַחֵד עִמּוֹ כְּמוֹ שֶׁבֵּאַרְנוּ:","חוֹלֶה שֶׁרָצָה לְגָרֵשׁ אִשְׁתּוֹ עַל תְּנַאי כְּשֶׁיָּמוּת כְּדֵי שֶׁלֹּא תִּפּל לִפְנֵי יָבָם וְאִם עָמַד לֹא תִּהְיֶה מְגֹרֶשֶׁת וְלֹא רָצָה לְגָרְשָׁהּ מֵעַכְשָׁו כְּדֵי שֶׁלֹּא תִּטָּרֵף דַּעְתּוֹ. כָּךְ הוּא כּוֹתֵב בַּגֵּט אַחַר שֶׁכּוֹתֵב הַתֹּרֶף אוֹ אוֹמֵר לָהּ כְּשֶׁנּוֹתֵן הַגֵּט. אִם לֹא מַתִּי לֹא יִהְיֶה גֵּט וְאִם מַתִּי יִהְיֶה גֵּט וְאִם לֹא מַתִּי לֹא יִהְיֶה גֵּט. כְּדֵי שֶׁתִּהְיֶה תְּנַאי כָּפוּל וְהֵן קֹדֶם לְלָאו וְלֹא יִפְתַּח פִּיו תְּחִלָּה לְפֻרְעָנוּת. וְאִם מֵת תִּהְיֶה מְגֹרֶשֶׁת כְּשֶׁיָּמוּת. וְהוּא שֶׁיַּגִּיעַ הַגֵּט לְיָדָהּ קֹדֶם מִיתָה:","בַּעַל שֶׁאָמַר לְאֶחָד זְכֵה בְּגֵט זֶה לְאִשְׁתִּי כְּדֵי שֶׁלֹּא תִּפּל לִפְנֵי יָבָם וְנָתַן הַגֵּט לְיָדוֹ וּמֵת הַבַּעַל קֹדֶם שֶׁיַּגִּיעַ הַגֵּט לְיָדָהּ הֲרֵי זוֹ סָפֵק מְגֹרֶשֶׁת. שֶׁרֹב הַנָּשִׁים זְכוּת הוּא לָהֶן שֶׁלֹּא יִפְּלוּ לִפְנֵי יָבָם. וּלְפִיכָךְ תִּהְיֶה סְפֵק מְגֹרֶשֶׁת אַף עַל פִּי שֶׁלֹּא הִגִּיעַ גֵּט לְיָדָהּ הוֹאִיל וְזָכָה לָהּ בּוֹ אַחֵר:","אָמַר לָעֵדִים לְאַחַר שְׁנֵים עָשָׂר חֹדֶשׁ כִּתְבוּ גֵּט לְאִשְׁתִּי אוֹ שֶׁאָמַר לָהֶם כִּתְבוּ וּתְנוּ גֵּט לְאִשְׁתִּי לְאַחַר י״‎ב חֹדֶשׁ. הֲרֵי אֵלּוּ כּוֹתְבִין וְנוֹתְנִין לָהּ אַחַר הַזְּמַן שֶׁקָּבַע. וְאִם כְּתָבוּהוּ בְּתוֹךְ הַזְּמַן אַף עַל פִּי שֶׁנְּתָנוּהוּ לָהּ לְאַחַר זְמַן שֶׁאָמַר אֵינוֹ גֵּט. כְּתָבוּהוּ אַחַר זְמַן שֶׁאָמַר וּמֵת קֹדֶם שֶׁיִּנָּתֵן לָהּ אֵינוֹ גֵּט. וְאִם לֹא נוֹדַע אִם מִיתָה קָדְמָה לִנְתִינַת הַגֵּט אוֹ נְתִינַת הַגֵּט קָדְמָה לְמִיתָה הֲרֵי זוֹ סָפֵק מְגֹרֶשֶׁת:","אָמַר לָהֶן כִּתְבוּ וּתְנוּ לְאִשְׁתִּי גֵּט אַחַר הַשָּׁבוּעַ. אֵין כּוֹתְבִין אֶלָּא עַד שָׁנָה אַחַר הַשָּׁבוּעַ. אָמַר לָהֶן לְאַחַר שָׁנָה אֵין כּוֹתְבִין [אֶלָּא] עַד לְאַחַר חֹדֶשׁ מִשָּׁנָה שְׁנִיָּה. אָמַר לָהֶן לְאַחַר הַחֹדֶשׁ (אֵין) כּוֹתְבִין עַד לְאַחַר הַשַּׁבָּת מֵחֹדֶשׁ שֵׁנִי. אָמַר לְאַחַר שַׁבָּת (אֵין) כּוֹתְבִין לְאַחַר הַשַּׁבָּת עַד סוֹף יוֹם שְׁלִישִׁי. אָמַר לָהֶן כִּתְבוּ וּתְנוּ לָהּ קֹדֶם הַשַּׁבָּת כּוֹתְבִין מִיּוֹם רְבִיעִי וְעַד סוֹף יוֹם שִׁשִּׁי וְנוֹתְנִין לָהּ:","הֲרֵי שֶׁאֵחֲרוּ אַחַר הַזְּמַן שֶׁאָמַר וְאַחַר כָּךְ כָּתְבוּ וְנָתְנוּ לָהּ כְּגוֹן שֶׁאָמַר לָהֶן לְאַחַר הַחֹדֶשׁ וְכָתְבוּ וְנָתְנוּ לָהּ לְאַחַר שְׁתֵּי שַׁבָּתוֹת מֵחֹדֶשׁ שֵׁנִי הֲרֵי זֶה פָּסוּל:","נִתְיַחֵד עִמָּהּ אַחַר שֶׁאָמַר לָהֶן לִכְתֹּב וְלַחְתֹּם וְלִתֵּן לָהּ הֲרֵי אֵלּוּ לֹא יִכְתְּבוּ. וְקַל וָחֹמֶר הַדְּבָרִים אִם הַגֵּט שֶׁנָּתַן לָהּ לְיָדָהּ כְּשֶׁנִּתְיַחֵד עִמָּהּ נִפְסַל הַגֵּט שֶׁמָּא בָּעַל. קַל וָחֹמֶר לָזֶה שֶׁלֹּא נִכְתַּב. וְאִם כְּתָבוֹ וּנְתָנוֹ לָהּ אַחַר שֶׁנִּתְיַחֵד עִמָּהּ אֵינוֹ גֵּט:","אָמַר לַעֲשָׂרָה כִּתְבוּ גֵּט לְאִשְׁתִּי אֶחָד כּוֹתֵב עַל יְדֵי כֻּלָּם. כֻּלְּכֶם כִּתְבוּ כּוֹתֵב אֶחָד מֵהֶם בְּמַעֲמַד כֻּלָּם. הוֹלִיכוּ גֵּט זֶה לְאִשְׁתִּי מוֹלִיכוֹ אֶחָד מֵהֶן עַל יְדֵי כֻּלָּם. כֻּלְּכֶם הוֹלִיכוּ גֵּט זֶה לְאִשְׁתִּי מוֹלִיכוֹ אֶחָד מֵהֶן בְּמַעֲמַד כֻּלָּם:","אָמַר לַעֲשָׂרָה כִּתְבוּ גֵּט וְחִתְמוּ וּתְנוּ לְאִשְׁתִּי אֶחָד מֵהֶן כּוֹתֵב וּשְׁנַיִם מֵהֶן חוֹתְמִין וְאֶחָד מֵהֶן נוֹתְנוֹ לָהּ. וַאֲפִלּוּ הָיָה הַכּוֹתֵב אֶחָד מִשְּׁנֵי הָעֵדִים שֶׁחָתְמוּ בּוֹ וְהוּא הַשָּׁלִיחַ שֶׁנְּתָנוֹ לָהּ הֲרֵי זֶה כָּשֵׁר. אָמַר לָהֶן כֻּלְּכֶם חֲתֹמוּ כֻּלָּם חוֹתְמִין. וְאִם מְנָאָן בֵּין שֶׁמָּנָה כֻּלָּם בֵּין שֶׁמָּנָה מִקְצָתָן וְאָמַר לָהֶן חֲתֹמוּ הֲרֵי זֶה כְּאוֹמֵר לָהֶן כֻּלְּכֶם חֲתֹמוּ וּשְׁנַיִם שֶׁחוֹתְמִין בַּתְּחִלָּה הֵן מִשּׁוּם עֵדִים וְהַשְּׁאָר מִשּׁוּם תְּנַאי. לְפִיכָךְ אִם הָיוּ הַשְּׁאָר פְּסוּלִין אוֹ חָתְמוּ זֶה הַיּוֹם וְזֶה לְמָחָר אֲפִלּוּ לְיָמִים הַרְבֵּה הֲרֵי זֶה גֵּט כָּשֵׁר. מֵת אֶחָד מֵהֶן קֹדֶם חֲתִימָה הֲרֵי זֶה גֵּט בָּטֵל. הָיָה אֶחָד מִשְּׁנַיִם הָרִאשׁוֹנִים פָּסוּל הֲרֵי זֶה גֵּט פָּסוּל. שֶׁמָּא יֹאמְרוּ עֵד פָּסוּל כָּשֵׁר בְּעֵדוּת שְׁאָר שְׁטָרוֹת בְּעֵת שֶׁיִּהְיוּ הָעֵדִים רַבִּים וְלֹא הִכְשִׁירוּהוּ בְּגֵט שֶׁעֵדָיו רַבִּים אֶלָּא מִפְּנֵי שֶׁעֵדֵי מְסִירָה הֵן הָעִקָּר:","תִּקְּנוּ חֲכָמִים שֶׁהָאוֹמֵר לְרַבִּים לִכְתֹּב גֵּט אוֹ לַחְתֹּם אוֹ לְהוֹלִיךְ גֵּט לְאִשְׁתּוֹ. אִם לִכְתִיבָה אוֹמֵר לָהֶן כָּל אֶחָד מִכֶּם יִכְתֹּב גֵּט לְאִשְׁתִּי וְכֵן לְהוֹלָכָה כָּל אֶחָד מִכֶּם יוֹלִיךְ. וְאִם לַחֲתִימָה יֹאמַר לָהֶן כָּל שְׁנַיִם מִכֶּם יַחְתְּמוּ בְּגֵט זֶה וְיִתְּנוּ לְאִשְׁתִּי:","וְלָמָּה אָמְרוּ חֲכָמִים עֵדֵי הַגֵּט אֵין חוֹתְמִין אֶלָּא זֶה בִּפְנֵי זֶה גְּזֵרָה שֶׁמָּא יֹאמַר לְרַבִּים כֻּלְּכֶם חֲתֹמוּ. אִם תֹּאמַר חוֹתְמִין זֶה שֶׁלֹּא בִּפְנֵי זֶה שֶׁמָּא יָעִידוּ שְׁנַיִם וְתִטּל הַגֵּט בְּיָדָהּ וְתַחְשֹׁב שֶׁכְּבָר הֵעִידוּ בּוֹ וַעֲדַיִן לֹא נִתְקַיֵּם הַתְּנַאי:","אָמַר לִשְׁלֹשָׁה שְׁנַיִם מִכֶּם יִכְתְּבוּ גֵּט לְאִשְׁתִּי וְיַחְתְּמוּ וְיִתְּנוּ לָהּ וְהָיָה בָּהֶן אָב וּבְנוֹ בֵּין שֶׁחָתַם הַבֵּן עִם הָאֶחָד בֵּין שֶׁחָתַם הָאָב עִם הָאֶחָד הֲרֵי זֶה גֵּט כָּשֵׁר. שֶׁהָאָדָם עוֹשֶׂה הַבֵּן שָׁלִיחַ בִּמְקוֹם הָאָב:","אָמַר לִשְׁנַיִם כִּתְבוּ וְחִתְמוּ וּתְנוּ לִפְלוֹנִי שֶׁיּוֹלִיךְ לְאִשְׁתִּי. אוֹ תְּנוּ לְשָׁלִיחַ שֶׁיּוֹלִיךְ לָהּ. אֶחָד מֵהֶן כּוֹתֵב וּשְׁנֵיהֶם חוֹתְמִין וְנוֹתְנִין לַשָּׁלִיחַ. וְאִם הוֹלִיכוּ הֵן בְּעַצְמָן וְנָתְנוּ לָהּ אֵינוֹ גֵּט שֶׁלֹּא עָשָׂה אוֹתָן שְׁלוּחִין לְגֵרוּשִׁין. כֵּיצַד יַעֲשׂוּ. יִטְּלוּ אוֹתוֹ מִמֶּנָּה וְיִתְּנוּהוּ לַשָּׁלִיחַ וְחוֹזֵר וְנוֹתְנוֹ לָהּ בִּפְנֵיהֶן אוֹ בִּפְנֵי אֲחֵרִים. וְרַבּוֹתַי הוֹרוּ בְּגֵט זֶה דָּבָר שֶׁאֵינוֹ נִרְאֶה מִפְּנֵי שִׁבּוּשׁ שֶׁהָיָה בַּנֻּסְחָאוֹת שֶׁלָּהֶן:","אָמַר לְסוֹפֵר כְּתֹב לִי גֵּט לְאִשְׁתִּי. כְּתָבוֹ וּנְתָנוֹ לַבַּעַל בְּלֹא עֵדִים וּנְטָלוֹ הַבַּעַל וּנְתָנוֹ לְשָׁלִיחַ וְאָמַר לוֹ תֵּן גֵּט זֶה לְאִשְׁתִּי בִּפְנֵי עֵדִים וְהָלַךְ הַשָּׁלִיחַ וּנְתָנוֹ לָהּ בִּפְנֵי עֵדִים הֲרֵי זוֹ סְפֵק מְגֹרֶשֶׁת. שֶׁאֵין הַשָּׁלִיחַ נֶאֱמָן לְהַתִּיר הָעֶרְוָה אַף עַל פִּי שֶׁהוּא עֵד אֶחָד אֶלָּא מִפְּנֵי כְּתַב הָעֵדִים שֶׁחָתְמוּ עַל הַגֵּט שֶׁהֵן כְּמִי שֶׁנֶּחְקְרָה עֵדוּתָן בְּבֵית דִּין עַד שֶׁיִּהְיֶה שָׁם מְעַרְעֵר כְּמוֹ שֶׁבֵּאַרְנוּ שָׁם. וְאִם הָיוּ שָׁם שְׁנֵי עֵדִים שֶׁיָּעִידוּ שֶׁגֵּט זֶה הַבַּעַל נְתָנוֹ לַשָּׁלִיחַ לְגָרְשָׁהּ בּוֹ הֲרֵי זוֹ מְגֹרֶשֶׁת:","הָאוֹמֵר לְשָׁלִיחַ תֵּן גֵּט זֶה לְאִשְׁתִּי בְּמָקוֹם פְּלוֹנִי וּנְתָנוֹ לָהּ בְּמָקוֹם אַחֵר אֵינוֹ גֵּט. הֲרֵי הִיא בְּמָקוֹם פְּלוֹנִי וּנְתָנוֹ לָהּ בְּמָקוֹם אַחֵר כָּשֵׁר מִפְּנֵי שֶׁמַּרְאֶה מָקוֹם הוּא לוֹ. אָמַר אַל תִּתְּנֵהוּ לָהּ אֶלָּא בַּבַּיִת וּנְתָנוֹ לָהּ בָּעֲלִיָּה. אַל תִּתְּנֵהוּ לָהּ אֶלָּא בְּיָמִין וּנְתָנוֹ לָהּ בִּשְׂמֹאל. תְּנֵהוּ לָהּ בְּיוֹם פְּלוֹנִי וּנְתָנוֹ לָהּ בְּתוֹךְ הַזְּמַן אֵינוֹ גֵּט. אַל תִּתְּנֵהוּ לָהּ אֶלָּא בְּיוֹם פְּלוֹנִי וּנְתָנוֹ לָהּ מִלְּפָנָיו אוֹ מֵאַחֲרָיו אֵינוֹ גֵּט שֶׁהֲרֵי הִקְפִּיד עַל עַצְמוֹ שֶׁל יוֹם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","וְכֵן הָאִשָּׁה שֶׁאָמְרָה לִשְׁלוּחָהּ הִתְקַבֵּל לִי גִּטִּי בְּמָקוֹם פְּלוֹנִי וְקִבְּלוֹ לָהּ בְּמָקוֹם אַחֵר אֵינוֹ גֵּט. הָבֵא לִי גִּטִּי בְּמָקוֹם פְּלוֹנִי וֶהֱבִיאוֹ לָהּ בְּמָקוֹם אַחֵר כָּשֵׁר:","הָאוֹמֵר לִשְׁלוּחוֹ הוֹלֵךְ גֵּט זֶה לְאִשְׁתִּי בֵּין שֶׁאָמַר לוֹ הוֹלֵךְ בֵּין שֶׁאָמַר לוֹ אַתְּ הוֹלֵךְ וְחָלָה אוֹ נֶאֱנַס מְשַׁלְּחוֹ בְּיַד אַחֵר. וְאִם אָמַר לוֹ טֹל מִמֶּנָּה חֵפֶץ פְּלוֹנִי וְתֵן לָהּ גֵּט זֶה הֲרֵי זֶה לֹא יְשַׁלְּחֶנּוּ בְּיַד אַחֵר. וְאִם שִׁלְּחוֹ בְּיַד אַחֵר וְיָצָאת הָאִשָּׁה לִקְרַאת הַשָּׁלִיחַ וְנָתְנָה הַחֵפֶץ תְּחִלָּה וְאַחַר כָּךְ נָתַן לָהּ הַגֵּט הֲרֵי זוֹ מְגֹרֶשֶׁת:","נָתַן לָהּ הַגֵּט תְּחִלָּה וְאַחַר כָּךְ נָתְנָה הַחֵפֶץ אֲפִלּוּ מִיַּד שָׁלִיחַ רִאשׁוֹן אֵינוֹ גֵּט שֶׁהֲרֵי עָבַר עַל דִּבְרֵי הַבַּעַל בְּדָבָר שֶׁסְּתָם בְּנֵי אָדָם מַקְפִּידִין עָלָיו. שֶׁהֲרֵי הַבַּעַל אָמַר לוֹ טֹל הַחֵפֶץ תְּחִלָּה וְתֵן לָהּ הַגֵּט וְהוּא נָתַן וְאַחַר כָּךְ נָטַל:","אָמַר לוֹ תֵּן לָהּ הַגֵּט וְטל מִמֶּנָּה חֵפֶץ פְּלוֹנִי הֲרֵי זֶה לֹא יְשַׁלְּחֶנּוּ בְּיַד אַחֵר שֶׁאֵין רְצוֹנוֹ שֶׁיִּהְיֶה פִּקְדוֹנוֹ בְּיַד אַחֵר. וְאִם שִׁלְּחוֹ בְּיַד אַחֵר הֲרֵי זֶה גֵּט בֵּין שֶׁנָּתְנָה הַחֵפֶץ תְּחִלָּה בֵּין שֶׁלֹּא נָתְנָה אֶלָּא בַּסּוֹף:","נָתַן לְשָׁלִיחַ הַגֵּט וְאָמַר לוֹ לֹא תִּתְּנֵהוּ לָהּ אֶלָּא אַתָּה וּנְתָנוֹ לְאַחֵר וּנְתָנוֹ לָהּ אֵינוֹ גֵּט. וְכֵן אִם אָמַר לוֹ אַל תִּתְּנֵהוּ לָהּ אַתָּה תְּנֵהוּ לִפְלוֹנִי וְהוּא יִתְּנֵהוּ לָהּ וּנְתָנוֹ לָהּ הַשָּׁלִיחַ הָרִאשׁוֹן אֵינוֹ גֵּט. לְפִי שֶׁלֹּא עָשָׂהוּ שָׁלִיחַ לְגֵרוּשִׁין:","נָתַן לוֹ הַגֵּט וְאָמַר לוֹ הוֹלֵךְ גֵּט זֶה לְאִשְׁתִּי. אָמַר לוֹ הַשָּׁלִיחַ אֵינִי מַכִּירָהּ. אָמַר לוֹ הַבַּעַל תְּנֵהוּ לִפְלוֹנִי הוּא מַכִּירָהּ. הֲרֵי זֶה שָׁלִיחַ שֶׁלֹּא נִתָּן לְגֵרוּשִׁין וְאֵינוֹ נוֹתֵן הַגֵּט אֶלָּא לִפְלוֹנִי שֶׁאָמַר הַבַּעַל וְאוֹתוֹ הַפְּלוֹנִי הוּא שָׁלִיחַ לְגֵרוּשִׁין הוּא שֶׁמּוֹלִיכוֹ לָהּ אוֹ מְשַׁלְּחוֹ בְּיַד אַחֵר אִם חָלָה אוֹ נֶאֱנַס:","נָתַן הַגֵּט לְשָׁלִיחַ וְאָמַר לוֹ לֹא תִּתְּנֵהוּ לָהּ עַד שְׁלֹשִׁים יוֹם וְחָלָה אוֹ נֶאֱנַס בְּתוֹךְ הַשְּׁלֹשִׁים מְשַׁלְּחוֹ בְּיַד אַחֵר. שֶׁאַף עַל פִּי שֶׁאֵינוֹ עַכְשָׁו שָׁלִיחַ לְגֵרוּשִׁין הוֹאִיל וּלְאַחַר שְׁלֹשִׁים יוֹם יִהְיֶה שְׁלִיחַ גֵּרוּשִׁין עוֹשֶׂה שָׁלִיחַ אַחֵר בְּתוֹךְ שְׁלֹשִׁים יוֹם:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁלֹּא הָיָה בַּעְלָהּ עִמָּהּ בַּמְּדִינָה אוֹ שֶׁהָיְתָה מִתְגָּרֶשֶׁת מִן הָאֵרוּסִין. אֲבָל אִם מִתְגָּרֶשֶׁת מִן הַנִּשּׂוּאִין וּבַעְלָהּ עִמָּהּ בַּמְּדִינָה חוֹשְׁשִׁין לוֹ שֶׁמָּא פִּיֵּס. וְאֵינוֹ עוֹשֶׂה שָׁלִיחַ בְּתוֹךְ הַשְּׁלֹשִׁים אֶלָּא אִם כֵּן אָמַר נֶאֱמֶנֶת עָלַי שֶׁלֹּא פִּיַּסְתִּי. אֲבָל נוֹתֵן לָהּ הַגֵּט לְאַחַר שְׁלֹשִׁים וְחוֹשְׁשִׁין לָהּ כְּמוֹ שֶׁבֵּאַרְנוּ עַד שֶׁיֹּאמַר נֶאֱמֶנֶת עָלַי שֶׁלֹּא פִּיַּסְתִּי:"],"Mishneh Torah, Fasts 4":["בְכָל יוֹם וָיוֹם מִשֶּׁבַע תַּעֲנִיּוֹת הָאַחֲרוֹנוֹת שֶׁל מָטָר מִתְפַּלְּלִין עַל סֵדֶר זֶה. מוֹצִיאִין אֶת הַתֵּבָה לִרְחוֹבָהּ שֶׁל עִיר וְכָל הָעָם מִתְקַבְּצִים וּמִתְכַּסִּים בְּשַׂקִּים. וְנוֹתְנִין אֵפֶר מַקְלֶה עַל גַּבֵּי הַתֵּבָה וְעַל גַּבֵּי סֵפֶר תּוֹרָה כְּדֵי לְהַגְדִּיל אֶת הַבְּכִיָּה וּלְהַכְנִיעַ לִבָּם. וְאֶחָד מִן הָעָם נוֹטֵל מִן הָאֵפֶר וְנוֹתֵן בְּרֹאשׁ הַנָּשִׂיא וּבְרֹאשׁ אַב בֵּית דִּין בְּמָקוֹם הֲנָחַת תְּפִלִּין כְּדֵי שֶׁיִּכָּלְמוּ וְיָשׁוּבוּ. וְכָל אֶחָד וְאֶחָד נוֹטֵל וְנוֹתֵן בְּרֹאשׁוֹ:","וְאַחַר כָּךְ מַעֲמִידִין בֵּינֵיהֶן זָקֵן חָכָם וְהֵן יוֹשְׁבִין. לֹא הָיָה שָׁם זָקֵן חָכָם מַעֲמִידִין חָכָם. לֹא הָיָה שָׁם לֹא זָקֵן וְלֹא חָכָם מַעֲמִידִין אָדָם שֶׁל צוּרָה. וְאוֹמֵר לִפְנֵיהֶם דִּבְרֵי כִּבּוּשִׁין. אַחֵינוּ לֹא שַׂק וְלֹא תַּעֲנִית גּוֹרְמִין אֶלָּא תְּשׁוּבָה וּמַעֲשִׂים טוֹבִים. שֶׁכֵּן מָצִינוּ בְּנִינְוֵה שֶׁלֹּא נֶאֱמַר בְּאַנְשֵׁי נִינְוֵה וַיַּרְא הָאֱלֹהִים אֶת שַׂקָּם וְאֶת תַּעֲנִיתָם אֶלָּא (יונה ג י) \"וַיַּרְא הָאֱלֹהִים אֶת מַעֲשֵׂיהֶם\". וּבְקַבָּלָה הוּא אוֹמֵר (יואל ב יג) \"קִרְעוּ לְבַבְכֶם וְאַל בִּגְדֵיכֶם\". וּמוֹסִיף בְּעִנְיָנוֹת אֵלּוּ כְּפִי כֹּחוֹ עַד שֶׁיַּכְנִיעַ לִבָּם וְיָשׁוּבוּ תְּשׁוּבָה גְּמוּרָה:","וְאַחַר שֶׁגּוֹמֵר זֶה דִּבְרֵי כִּבּוּשִׁין עוֹמְדִין בִּתְפִלָּה וּמַעֲמִידִין שְׁלִיחַ צִבּוּר הָרָאוּי לְהִתְפַּלֵּל בְּתַעֲנִיּוֹת אֵלּוּ. וְאִם הָיָה אוֹתוֹ שֶׁאוֹמֵר דִּבְרֵי הַכִּבּוּשִׁין רָאוּי לְהִתְפַּלֵּל מִתְפַּלֵּל וְאִם לָאו מוֹרִידִין אַחֵר:","וְאֵי זֶה הוּא הָרָאוּי לְהִתְפַּלֵּל בְּתַעֲנִיּוֹת אֵלּוּ. אִישׁ שֶׁהוּא רָגִיל בִּתְפִלָּה. וְרָגִיל לִקְרוֹת בַּתּוֹרָה נְבִיאִים וּכְתוּבִים. וּמְטוּפָּל וְאֵין לוֹ. וְיֵשׁ לוֹ יְגִיעָה בַּשָּׂדֶה. וְלֹא יִהְיֶה בְּבָנָיו וּבִבְנֵי בֵּיתוֹ וְכָל קְרוֹבָיו הַנִּלְוִים עָלָיו בַּעַל עֲבֵרָה. אֶלָּא יִהְיֶה בֵּיתוֹ רֵיקָן מִן הָעֲבֵרוֹת. וְלֹא יָצָא עָלָיו שֵׁם רַע בְּיַלְדוּתוֹ. שְׁפַל בֶּרֶךְ. וּמְרֻצֶּה לָעָם. וְיֵשׁ לוֹ נְעִימָה וְקוֹלוֹ עָרֵב. וְאִם הָיָה זָקֵן עִם כָּל הַמִּדּוֹת הָאֵלּוּ הֲרֵי זֶה מְפֹאָר. וְאִם אֵינוֹ זָקֵן הוֹאִיל וְיֵשׁ בּוֹ כָּל הַמִּדּוֹת הָאֵלּוּ יִתְפַּלֵּל:","וּשְׁלִיחַ צִבּוּר מַתְחִיל וּמִתְפַּלֵּל עַד בִּרְכַּת גּוֹאֵל יִשְׂרָאֵל. וְאוֹמֵר זִכְרוֹנוֹת וְשׁוֹפָרוֹת מֵעֵין הַצָּרָה. וְאוֹמֵר (תהילים קכ א) \"אֶל ה' בַּצָּרָתָה לִּי קָרָאתִי וַיַּעֲנֵנִי\". (תהילים קכא א) \"אֶשָּׂא עֵינַי אֶל הֶהָרִים\" וְגוֹ'. (תהילים קל א) \"מִמַּעֲמַקִּים קְרָאתִיךָ ה'\". (תהילים קב א) \"תְּפִלָּה לְעָנִי כִי יַעֲטֹף\" וְגוֹ':","וְאוֹמֵר דִּבְרֵי תַּחֲנוּנִים כְּפִי כֹּחוֹ. וְאוֹמֵר רְאֵה נָא בְעָנְיֵנוּ וְרִיבָה רִיבֵנוּ וּמַהֵר לְגָאֳלֵנוּ. וּמִתְחַנֵּן וְאוֹמֵר בְּסוֹף תַּחֲנוּנָיו מִי שֶׁעָנָה אֶת אַבְרָהָם אָבִינוּ בְּהַר הַמּוֹרִיָּה הוּא יַעֲנֶה אֶתְכֶם וְיִשְׁמַע קוֹל צַעֲקַתְכֶם בַּיּוֹם הַזֶּה. בָּרוּךְ אַתָּה ה' גּוֹאֵל יִשְׂרָאֵל:","וּמַתְחִיל לְהוֹסִיף שֵׁשׁ בְּרָכוֹת שֶׁהוּא מוֹסִיף זוֹ אַחַר זוֹ. וּמִתְחַנֵּן בְּכָל אַחַת מֵהֶן בְּדִבְרֵי תַּחֲנוּנִים וּפְסוּקִים מִדִּבְרֵי קַבָּלָה וּמִכִּתְבֵי הַקֹּדֶשׁ כְּפִי שֶׁהוּא רָגִיל וְחוֹתֵם בְּכָל אַחַת מֵהֶן בַּחֲתִימוֹת אֵלּוּ:","בָּרִאשׁוֹנָה הוּא חוֹתֵם מִי שֶׁעָנָה אֶת משֶׁה וַאֲבוֹתֵינוּ עַל יַם סוּף הוּא יַעֲנֶה אֶתְכֶם וְיִשְׁמַע קוֹל צַעֲקַתְכֶם בַּיּוֹם הַזֶּה. בָּרוּךְ אַתָּה ה' זוֹכֵר הַנִּשְׁכָּחוֹת:","בַּשְּׁנִיָּה הוּא חוֹתֵם מִי שֶׁעָנָה אֶת יְהוֹשֻׁעַ בַּגִּלְגָּל הוּא יַעֲנֶה אֶתְכֶם וְיִשְׁמַע קוֹל צַעֲקַתְכֶם בַּיּוֹם הַזֶּה. בָּרוּךְ אַתָּה ה' שׁוֹמֵעַ תְּרוּעָה:","בַּשְּׁלִישִׁית הוּא חוֹתֵם מִי שֶׁעָנָה אֶת שְׁמוּאֵל בַּמִּצְפָּה הוּא יַעֲנֶה אֶתְכֶם וְיִשְׁמַע קוֹל צַעֲקַתְכֶם בַּיּוֹם הַזֶּה. בָּרוּךְ אַתָּה ה' שׁוֹמֵעַ צְעָקָה:","בָּרְבִיעִית הוּא חוֹתֵם מִי שֶׁעָנָה אֶת אֵלִיָּהוּ בְּהַר הַכַּרְמֶל הוּא יַעֲנֶה אֶתְכֶם וְיִשְׁמַע קוֹל צַעֲקַתְכֶם בַּיּוֹם הַזֶּה. בָּרוּךְ אַתָּה ה' שׁוֹמֵעַ תְּפִלָּה:","בַּחֲמִישִׁית הוּא חוֹתֵם מִי שֶׁעָנָה אֶת יוֹנָה בִּמְעֵי הַדָּגָה הוּא יַעֲנֶה אֶתְכֶם וְיִשְׁמַע קוֹל צַעֲקַתְכֶם בַּיּוֹם הַזֶּה. בָּרוּךְ אַתָּה ה' הָעוֹנֶה בְּעֵת צָרָה:","בַּשִּׁשִּׁית הוּא חוֹתֵם מִי שֶׁעָנָה אֶת דָּוִד וּשְׁלֹמֹה בְּנוֹ בִּירוּשָׁלַיִם הוּא יַעֲנֶה אֶתְכֶם וְיִשְׁמַע קוֹל צַעֲקַתְכֶם בַּיּוֹם הַזֶּה. בָּרוּךְ אַתָּה ה' הַמְרַחֵם עַל הָאָרֶץ. וְכָל הָעָם עוֹנִין אָמֵן אַחַר כָּל בְּרָכָה וּבְרָכָה כְּדֶרֶךְ שֶׁעוֹנִין אַחַר כָּל הַבְּרָכוֹת:","בַּשְּׁבִיעִית אוֹמֵר רְפָאֵנוּ ה' וְנֵרָפֵא וְכוּ'. וְגוֹמֵר הַתְּפִלָּה עַל הַסֵּדֶר וְתוֹקְעִין בַּחֲצוֹצְרוֹת. וְכַסֵּדֶר הַזֶּה עוֹשִׂין בְּכָל מָקוֹם:","כְּשֶׁהָיוּ מִתְפַּלְּלִין עַל הַסֵּדֶר הַזֶּה בִּירוּשָׁלַיִם הָיוּ מִתְכַּנְּסִין לְהַר הַבַּיִת כְּנֶגֶד שַׁעַר הַמִּזְרָח וּמִתְפַּלְּלִין כַּסֵּדֶר הַזֶּה. וּכְשֶׁמַּגִּיעַ שְׁלִיחַ צִבּוּר לוֹמַר מִי שֶׁעָנָה אֶת אַבְרָהָם אוֹמֵר בָּרוּךְ אַתָּה ה' אֱלֹהֵינוּ אֱלֹהַי יִשְׂרָאֵל מִן הָעוֹלָם וְעַד הָעוֹלָם בָּרוּךְ אַתָּה ה' גּוֹאֵל יִשְׂרָאֵל. וְהֵן עוֹנִין אַחֲרָיו בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. וְחַזָּן הַכְּנֶסֶת אוֹמֵר לַתּוֹקְעִים תִּקְעוּ בְּנֵי אַהֲרֹן תִּקְעוּ. וְחוֹזֵר הַמִּתְפַּלֵּל וְאוֹמֵר מִי שֶׁעָנָה אֶת אַבְרָהָם בְּהַר הַמּוֹרִיָּה הוּא יַעֲנֶה אֶתְכֶם וְיִשְׁמַע קוֹל צַעֲקַתְכֶם בַּיּוֹם הַזֶּה וְאַחַר כָּךְ תּוֹקְעִין הַכֹּהֲנִים וּמְרִיעִין וְתוֹקְעִין:","וְכֵן בַּבְּרָכָה הַשְּׁנִיָּה לָזוֹ שֶׁהִיא רִאשׁוֹנָה מִן הַשֵּׁשׁ שֶׁמּוֹסִיף חוֹתֵם בָּהּ בָּרוּךְ ה' אֱלֹהִים אֱלֹהֵי יִשְׂרָאֵל מִן הָעוֹלָם וְעַד הָעוֹלָם בָּרוּךְ אַתָּה ה' זוֹכֵר הַנִּשְׁכָּחוֹת. וְהֵן עוֹנִין בָּרוּךְ שֵׁם כְּבוֹד מַלְכוּתוֹ לְעוֹלָם וָעֶד. וְחַזַּן הַכְּנֶסֶת אוֹמֵר לָהֶן הָרִיעוּ בְּנֵי אַהֲרֹן הָרִיעוּ. וְחוֹזֵר שְׁלִיחַ צִבּוּר וְאוֹמֵר מִי שֶׁעָנָה אֶת משֶׁה וַאֲבוֹתֵינוּ עַל יַם סוּף הוּא יַעֲנֶה אֶתְכֶם וְיִשְׁמַע קוֹל צַעֲקַתְכֶם בַּיּוֹם הַזֶּה. וְאַחַר כָּךְ מְרִיעִין וְתוֹקְעִין וּמְרִיעִין:","וְכֵן עַל כָּל בְּרָכָה וּבְרָכָה בְּאַחַת אוֹמֵר תִּקְעוּ וּבְאַחַת אוֹמֵר הָרִיעוּ עַד שֶׁיִּגְמֹר כָּל שֶׁבַע הַבְּרָכוֹת. וְנִמְצְאוּ הַכֹּהֲנִים פַּעַם תּוֹקְעִין וּמְרִיעִין וְתוֹקְעִין. וּפַעַם מְרִיעִין וְתוֹקְעִין וּמְרִיעִין שֶׁבַע פְּעָמִים. וְאֵין עוֹשִׂים הַסֵּדֶר זֶה אֶלָּא בְּהַר הַבַּיִת בִּלְבַד. וּכְשֶׁהֵן תּוֹקְעִין וּמְרִיעִין שָׁם תּוֹקְעִין בַּחֲצוֹצְרוֹת וּבְשׁוֹפָר כְּאֶחָד כְּמוֹ שֶׁאָמַרְנוּ:","שֶׁבַע תַּעֲנִיּוֹת הָאֵלּוּ כָּל מָקוֹם שֶׁגּוֹזְרִין אוֹתָם שָׁם אַחַר שֶׁמִּתְפַּלְּלִין יוֹצְאִין כָּל הָעָם לְבֵית הַקְּבָרוֹת וּבוֹכִין וּמִתְחַנְּנִים שָׁם. כְּלוֹמַר הֲרֵי אַתֶּם מֵתִים כְּאֵלּוּ אִם לֹא תָּשׁוּבוּ מִדַּרְכֵיכֶם. וּבְכָל תַּעֲנִית מִתַּעֲנִיּוֹת הַצָּרוֹת שֶׁגּוֹזְרִין עַל הַצִּבּוּר מִתְפַּלְּלִין תְּפִלַּת נְעִילָה בְּכָל מָקוֹם:","יָרְדוּ לָהֶם גְּשָׁמִים עַד מָתַי יִהְיוּ יוֹרְדִין וְיִפְסְקוּ הַצִּבּוּר מִן הַתַּעֲנִית. מִשֶּׁיֵּרְדוּ בְּעֹמֶק הָאָרֶץ הַחֲרֵבָה טֶפַח. וּבַבֵּינוֹנִית טְפָחַיִם. וּבַעֲבוּדָה עַד שֶׁיֵּרְדוּ בְּעֹמֶק שְׁלֹשָׁה טְפָחִים:"],"Mishneh Torah, First Fruits and other Gifts to Priests Outside the Sanctuary 5":["מִצְוַת עֲשֵׂה לְהַפְרִישׁ תְּרוּמָה מִן הָעִסָּה לַכֹּהֵן שֶׁנֶּאֱמַר (במדבר טו כ) \"רֵאשִׁית עֲרִסֹתֵיכֶם חַלָּה תָּרִימוּ תְרוּמָה\". וְרֵאשִׁית זוֹ אֵין לָהּ שִׁעוּר מִן הַתּוֹרָה אֲפִלּוּ הִפְרִישׁ כִּשְׂעוֹרָה פָּטַר אֶת הָעִסָּה. וְהָעוֹשֶׂה כָּל עִסָּתוֹ חַלָּה לֹא עָשָׂה כְּלוּם עַד שֶׁיְּשַׁיֵּר מִקְצָתוֹ:","וּמִדִּבְרֵי סוֹפְרִים שֶׁמַּפְרִישִׁין אֶחָד מֵאַרְבָּעָה וְעֶשְׂרִים מִן הָעִסָּה כְּדֵי שֶׁיִּהְיֶה בָּהּ כְּדֵי מַתָּנָה לַכֹּהֵן שֶׁנֶּאֱמַר (דברים יח ד) \"תִּתֶּן לּוֹ \"תֵּן לוֹ דָּבָר הָרָאוּי לִתְּנוֹ מַתָּנָה. וְהַנַּחְתּוֹם הָעוֹשֶׂה לִמְכֹּר בַּשּׁוּק מַפְרִישׁ אֶחָד מִשְּׁמוֹנָה וְאַרְבָּעִים. לְפִי שֶׁעִסָּתוֹ מְרֻבָּה יֵשׁ בְּשִׁעוּר זֶה כְּדֵי מַתָּנָה:","הָעוֹשֶׂה עִסָּה לְמִשְׁתֵּה בְּנוֹ אַף עַל פִּי שֶׁהוּא מְרֻבֶּה מַפְרִישׁ אֶחָד מֵעֶשְׂרִים וְאַרְבָּעָה. שֶׁלֹּא לְחַלֵּק בְּעִסַּת בַּעַל הַבַּיִת. וְהַנַּחְתּוֹם שֶׁעָשָׂה עִסָּה קְטַנָּה אֶחָד מֵאַרְבָּעִים וּשְׁמוֹנֶה. שֶׁלֹּא לְחַלֵּק בְּעִסַּת הַנַּחְתּוֹם:","נִטְמֵאת הָעִסָּה בְּשׁוֹגֵג אוֹ בְּאֹנֶס מַפְרִישׁ אֶחָד מֵאַרְבָּעִים וּשְׁמוֹנָה. וְאִם טִמְּאָהּ בְּזָדוֹן מַפְרִישׁ אֶחָד מִכ\"ד כְּדֵי שֶׁלֹּא יִהְיֶה חוֹטֵא נִשְׂכָּר. וְחַלָּה טְמֵאָה [מֻתֶּרֶת] (לַכֹּהֵן) לְהַסָּקָה כִּתְרוּמָה טְמֵאָה:","אֵין חַיָּבִין בְּחַלָּה מִן הַתּוֹרָה אֶלָּא בְּאֶרֶץ יִשְׂרָאֵל בִּלְבַד שֶׁנֶּאֱמַר (במדבר טו יט) \"וְהָיָה בַּאֲכָלְכֶם מִלֶּחֶם הָאָרֶץ\" וְגוֹ'. וּבִזְמַן שֶׁכָּל יִשְׂרָאֵל שָׁם שֶׁנֶּאֱמַר (במדבר טו יח) \"בְּבֹאֲכֶם\" בִּיאַת כֻּלְּכֶם וְלֹא בִּיאַת מִקְצַתְכֶם. לְפִיכָךְ חַלָּה בַּזְּמַן הַזֶּה אֲפִלּוּ בִּימֵי עֶזְרָא בְּאֶרֶץ יִשְׂרָאֵל אֵינָהּ אֶלָּא מִדִּבְרֵיהֶם כְּמוֹ שֶׁבֵּאַרְנוּ בִּתְרוּמָה:","פֵּרוֹת חוּצָה לָאָרֶץ שֶׁנִּכְנְסוּ לָאָרֶץ חַיָּבִין בְּחַלָּה. וּפֵרוֹת הָאָרֶץ שֶׁיָּצְאוּ חוּצָה לָאָרֶץ פְּטוּרִין שֶׁנֶּאֱמַר (במדבר טו יח) \"אֲשֶׁר אֲנִי מֵבִיא אֶתְכֶם שָׁמָּה\" שָׁמָּה אַתֶּם חַיָּבִין בֵּין עַל פֵּרוֹת הָאָרֶץ בֵּין עַל פֵּרוֹת חוּצָה לָאָרֶץ:","מַפְרִישִׁין חַלָּה בְּחוּצָה לָאָרֶץ מִדִּבְרֵי סוֹפְרִים כְּדֵי שֶׁלֹּא תִּשְׁתַּכַּח תּוֹרַת חַלָּה מִיִּשְׂרָאֵל. וְאֵין מְבִיאִין חַלּוֹת חוּצָה לָאָרֶץ לָאָרֶץ כְּשֵׁם שֶׁאֵין מְבִיאִין תְּרוּמָה וּבִכּוּרִים מִשָּׁם. וְאִם הֵבִיא מַנִּיחָהּ עַד עֶרֶב הַפֶּסַח וְתִשָּׂרֵף כִּתְרוּמָה:","שְׁלֹשָׁה דִּינִין לְחַלָּה בְּשָׁלֹשׁ אֲרָצוֹת. כָּל הָאָרֶץ שֶׁהֶחֱזִיקוּ בָּהּ עוֹלֵי בָּבֶל עַד כְּזִיב מַפְרִישִׁין בָּהּ חַלָּה אַחַת כַּשִּׁעוּר וְהִיא נֶאֱכֶלֶת לַכֹּהֲנִים. וּשְׁאָר אֶרֶץ יִשְׂרָאֵל שֶׁהֶחֱזִיקוּ בָּהּ עוֹלֵי מִצְרַיִם וְלֹא עוֹלֵי בָּבֶל שֶׁהִיא מִכְּזִיב וְעַד אֲמָנָה מַפְרִישִׁין בָּהּ שְׁתֵּי חַלּוֹת הָאַחַת נִשְׂרֶפֶת וְהָאַחַת נֶאֱכֶלֶת. וּמִפְּנֵי מָה מַפְרִישִׁין בָּהּ שְׁתֵּי חַלּוֹת מִפְּנֵי שֶׁהַחַלָּה הָרִאשׁוֹנָה טְמֵאָה שֶׁהֲרֵי לֹא נִתְקַדְּשָׁה אוֹתָהּ הָאָרֶץ בִּימֵי עֶזְרָא. וּקְדֻשָּׁה רִאשׁוֹנָה בָּטְלָה מִשֶּׁגָּלוּ. וְהוֹאִיל וְהִיא אֶרֶץ יִשְׂרָאֵל מַפְרִישִׁין בָּהּ חַלָּה אֶחָד מֵאַרְבָּעִים וּשְׁמוֹנָה וְשׂוֹרְפִין אוֹתָהּ. וּמַפְרִישִׁין חַלָּה שְׁנִיָּה וְנוֹתְנִין אוֹתָהּ לַכֹּהֵן לְאָכְלָהּ. כְּדֵי שֶׁלֹּא יֹאמְרוּ תְּרוּמָה טְהוֹרָה נִשְׂרֶפֶת שֶׁהֲרֵי נִשְׂרְפָה הָרִאשׁוֹנָה אַף עַל פִּי שֶׁלֹּא נִטְמְאָה טֻמְאָה יְדוּעָה לַכּל. וְזוֹ שְׁנִיָּה אֵין לָהּ שִׁעוּר אֶלָּא כָּל שֶׁרוֹצֶה מַפְרִישׁ מִפְּנֵי שֶׁהִיא מִדִּבְרֵיהֶם. וְכָל הָאָרֶץ מֵאֲמָנָה וְלַחוּץ בֵּין בְּסוּרְיָא בֵּין בִּשְׁאָר הָאֲרָצוֹת מַפְרִישִׁין שְׁתֵּי חַלּוֹת. אַחַת לִשְׂרֵפָה כְּדֵי שֶׁלֹּא יֹאמְרוּ רָאִינוּ תְּרוּמָה טְמֵאָה נֶאֱכֶלֶת. וְאַחַת לַאֲכִילָה כְּדֵי שֶׁלֹּא תִּשְׁתַּכַּח תּוֹרַת חַלָּה מִיִּשְׂרָאֵל. וְהוֹאִיל וְזוֹ וְזוֹ מִדִּבְרֵיהֶם מוּטָב לְרַבּוֹת בַּנֶּאֱכֶלֶת לְפִיכָךְ שֶׁל שְׂרֵפָה אֵין לָהּ שִׁעוּר אֶלָּא כָּל שֶׁהוּא. וְשֶׁל אֲכִילָה אֶחָד מִמ\"ח. וּמֻתֶּרֶת לְזָבִים וּלְזָבוֹת וְאֵין צָרִיךְ לוֹמַר לִשְׁאָר טְמֵאִים:","בַּזְּמַן הַזֶּה שֶׁאֵין שָׁם עִסָּה טְהוֹרָה מִפְּנֵי טֻמְאַת הַמֵּת מַפְרִישִׁין חַלָּה אַחַת בְּכָל אֶרֶץ יִשְׂרָאֵל אֶחָד מִמ\"ח וְשׂוֹרְפִין אוֹתָהּ מִפְּנֵי שֶׁהִיא טְמֵאָה וְיֵשׁ לָהּ שֵׁם מִן הַתּוֹרָה. וּמִכְּזִיב עַד אֲמָנָה מַפְרִישִׁין שְׁנִיָּה לַכֹּהֵן לַאֲכִילָה וְאֵין לָהּ שִׁעוּר, כְּשֶׁהָיָה הַדָּבָר מִקֹּדֶם:","חַלַּת חוּצָה לָאָרֶץ אַף עַל פִּי שֶׁהִיא טְמֵאָה הוֹאִיל וְעִקַּר חִיּוּבָהּ מִדִּבְרֵיהֶם אֵינָהּ אֲסוּרָה בַּאֲכִילָה אֶלָּא עַל כֹּהֵן שֶׁטֻּמְאָה יוֹצְאָה עָלָיו מִגּוּפוֹ וְהֵם בַּעֲלֵי קְרָיִין וְזָבִים וְזָבוֹת וְנִדּוֹת וְיוֹלְדוֹת וּמְצֹרָעִין. אֲבָל שְׁאָר הַטְּמֵאִים בְּמַגַּע שְׁאָר הַטֻּמְאוֹת אֲפִלּוּ טְמֵאֵי מֵת מֻתָּרִים לְאָכְלָהּ. לְפִיכָךְ אִם הָיָה שָׁם כֹּהֵן קָטָן בְּחוּצָה לָאָרֶץ בֵּין בְּסוּרְיָא בֵּין בִּשְׁאָר אֲרָצוֹת וְרָצָה לְהַפְרִישׁ חַלָּה אַחַת מַפְרִישׁ אֶחָד מִמ\"ח. וְנֶאֱכֶלֶת לְקָטָן שֶׁעֲדַיִן לֹא רָאָה קֶרִי אוֹ לִקְטַנָּה שֶׁעֲדַיִן לֹא רָאֲתָה נִדָּה. וְאֵינוֹ צָרִיךְ לְהַפְרִישׁ שְׁנִיָּה:","וְכֵן אִם הָיָה שָׁם כֹּהֵן גָּדוֹל שֶׁטָּבַל מִשִּׁכְבַת זַרְעוֹ אוֹ מִזִּיבָתוֹ אַף עַל פִּי שֶׁלֹּא הֶעֱרִיב שִׁמְשׁוֹ וְאַף עַל פִּי שֶׁהוּא טְמֵא מֵת הֲרֵי זֶה מֻתָּר לֶאֱכל הַחַלָּה הָרִאשׁוֹנָה וְאֵינוֹ צָרִיךְ לְהַפְרִישׁ שְׁנִיָּה בְּחוּצָה לָאָרֶץ. כָּל הַמַּפְרִישׁ חַלָּה מְבָרֵךְ תְּחִלָּה אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לְהַפְרִישׁ חַלָּה בֵּין בָּאָרֶץ בֵּין בְּחוּצָה לָאָרֶץ. וּכְשֵׁם שֶׁמְּבָרֵךְ עַל הַטְּהוֹרָה כָּךְ מְבָרֵךְ עַל הַטְּמֵאָה. לְפִיכָךְ אֵין הָאִישׁ עֵרוֹם מַפְרִישׁ חַלָּה שֶׁאֵינוֹ יָכוֹל לְבָרֵךְ. אֲבָל הָאִשָּׁה הָעֲרוּמָה שֶׁיָּשְׁבָה וְכָל פָּנֶיהָ טוּחוֹת בַּקַּרְקַע מְבָרֶכֶת וּמַפְרֶשֶׁת חַלָּה:","הַנִּדָּה וְכַיּוֹצֵא בָּהּ מְבָרֶכֶת וּמַפְרֶשֶׁת חַלַּת חוּצָה לָאָרֶץ שֶׁאֵינָהּ מֻזְהֶרֶת עַל מַגָּעָהּ אֶלָּא עַל אֲכִילָתָהּ. וְאִם הָיָה שָׁם כֹּהֵן קָטָן אוֹ כֹּהֵן שֶׁטָּבַל שֶׁהִיא מֻתֶּרֶת לוֹ לַאֲכִילָה כְּמוֹ שֶׁבֵּאַרְנוּ הֲרֵי זֶה מֻתָּר לְאָכְלָהּ עִם הַזָּר עַל שֻׁלְחָן אֶחָד לְפִי שֶׁאֵינָהּ מְדַמַּעַת. וַאֲפִלּוּ נִתְעָרְבָה שָׁוֶה בְּשָׁוֶה. וְנוֹתְנִין אוֹתָהּ לְכֹהֵן עַם הָאָרֶץ מִפְּנֵי שֶׁהִיא טְמֵאָה בַּאֲוִיר אֶרֶץ הָעַמִּים [וְאֵין בָּהּ מִשּׁוּם כֹּהֵן הַמְּסַיֵּעַ בְּמַתְּנוֹתָיו שֶׁהוּא אָסוּר. וְאִם רָצָה לֶאֱכל תְּחִלָּה] וְאַחַר כָּךְ יַפְרִישׁ הַחַלָּה בְּחוּץ לָאָרֶץ מֻתָּר שֶׁאֵין עִקָּרָהּ אֶלָּא מִדִּבְרֵיהֶם:","הַחַלָּה נִקְרֵאת תְּרוּמָה לְפִיכָךְ אֵינָהּ נִטֶּלֶת אֶלָּא מִן הַמֻּקָּף כִּתְרוּמָה. וְאֵינָהּ נִטֶּלֶת מִן הַטָּהוֹר עַל הַטָּמֵא לְכַתְּחִלָּה:","וְכָל שֶׁאָמַרְנוּ בִּתְרוּמָה לֹא יִתְרֹם וְאִם תָּרַם אֵינָהּ תְּרוּמָה כָּךְ בְּחַלָּה. וְכָל שֶׁאָמַרְנוּ בִּתְרוּמָה לֹא יִתְרֹם מִזֶּה עַל זֶה כָּךְ בְּחַלָּה. וְכָל שֶׁאֵינוֹ אוֹכֵל תְּרוּמָה אֵינוֹ אוֹכֵל חַלָּה. וְכָל הָאוֹכֵל תְּרוּמָה אוֹכֵל חַלָּה:","הַסּוּמָא וְהַשִּׁכּוֹר מַפְרִישִׁין חַלָּה לְכַתְּחִלָּה שֶׁאֵין בְּעִסָּה רַע וְיָפֶה כְּדֵי שֶׁיְּכַוְּנוּ וְיַפְרִישׁוּ מִן הַיָּפֶה:"],"Mishneh Torah, Firstlings 8":["הַמַּכְנִּיס צֹאן לַדִּיר וְהִתְחִילוּ לָצֵאת אַחַת אַחַת וְהוּא מוֹנֶה כְּמוֹ שֶׁבֵּאַרְנוּ וְטָעָה בַּמִּנְיָן וְקָרָא לַשְּׁמִינִי אוֹ לְשֶׁלְּמַטָּה מִמֶּנּוּ עֲשִׂירִי אוֹ שֶׁקָּרָא לַשְּׁנֵים עָשָׂר אוֹ שֶׁלְּמַעְלָה מִמֶּנּוּ עֲשִׂירִי לֹא נִתְקַדְּשׁוּ. אֲבָל אִם קָרָא לַתְּשִׁיעִי אוֹ לָאַחַד עָשָׂר עֲשִׂירִי נִתְקַדְּשׁוּ. וְדָבָר זֶה הֲלָכָה מִפִּי הַקַּבָּלָה נִשְׁמַע שֶׁהַטָּעוּת מִתְקַדְּשׁוֹת לְמַעֲשֵׂר שֶׁלְּמַעְלָה מִמֶּנּוּ וְשֶׁלְּמַטָּה מִמֶּנּוּ אֲבָל לֹא שֶׁלִּפְנֵיהֶם וְשֶׁלְּאַחֲרֵיהֶם. אֲפִלּוּ קָרָא לַתְּשִׁיעִי עֲשִׂירִי וְלַעֲשִׂירִי תְּשִׁיעִי וְלָאַחַד עָשָׂר עֲשִׂירִי בֵּין בְּטָעוּת בֵּין בְּכַוָּנָה שְׁלָשְׁתָּן מֻקְדָּשִׁים:","וְהֵיאַךְ דִּינָם. הַתְּשִׁיעִי אֵינוֹ קָרֵב אֶלָּא נֶאֱכָל בְּמוּמוֹ. וְהָעֲשִׂירִי מַעֲשֵׂר. וְהָאַחַד עָשָׂר יִקָּרֵב שְׁלָמִים וְטָעוּן נְסָכִים כִּשְׁלָמִים וְאֵינוֹ עוֹשֶׂה תְּמוּרָה מִפְּנֵי שֶׁהוּא עַצְמוֹ כִּתְמוּרָה. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה הַמּוֹנֶה הוּא בַּעַל הַבְּהֵמוֹת אֲבָל הָעוֹשֶׂה שָׁלִיחַ לְעַשֵּׂר לוֹ וְטָעָה בֵּין בַּתְּשִׁיעִי בֵּין בָּאַחַד עָשָׂר אֵין מְקַדֵּשׁ אֶלָּא הָעֲשִׂירִי הַוַּדַּאי בִּלְבַד. שֶׁלֹּא עֲשָׂאָהוּ שָׁלִיחַ לִטְעוֹת וּלְהַפְסִיד אֶלָּא לְקַדֵּשׁ כָּרָאוּי:","זֶה שֶׁאָמַרְנוּ שֶׁאִם קָרָא לָאַחַד עָשָׂר עֲשִׂירִי נִתְקַדֵּשׁ כְּשֶׁקָּרָא לָעֲשִׂירִי תְּשִׁיעִי אֲבָל אִם קָרָא לָעֲשִׂירִי עֲשִׂירִי וְקָרָא אַחֲרָיו לָאַחַד עָשָׂר עֲשִׂירִי לֹא נִתְקַדֵּשׁ אַחַד עָשָׂר שֶׁהֲרֵי הָעֲשִׂירִי הַוַּדַּאי לֹא עָקַר שֵׁם עֲשִׂירִי מֵעָלָיו. וַאֲפִלּוּ יָצָא הָעֲשִׂירִי וְלֹא קְרָאָהוּ לֹא עֲשִׂירִי וְלֹא אַחַד עָשָׂר אֶלָּא שָׁתַק וְאַחַר כָּךְ יָצָא אַחַד עָשָׂר וּקְרָאָהוּ עֲשִׂירִי לֹא נִתְקַדֵּשׁ שֶׁהָעֲשִׂירִי מֵעַצְמוֹ נִתְקַדֵּשׁ. וְאַף עַל פִּי שֶׁלֹּא קְרָאָהוּ עֲשִׂירִי הוֹאִיל וְלֹא עָקַר שֵׁם עֲשִׂירִי מֵעָלָיו אֵין אַחַד עָשָׂר מְקֻדָּשׁ:","יָצְאוּ תְּשִׁיעִי וַעֲשִׂירִי כְּאֶחָד בֵּין שֶׁקָּרָא שְׁנֵיהֶם עֲשִׂירִי. בֵּין שֶׁקְּרָאָם תְּשִׁיעִי. שְׁנֵיהֶם מֻקְדָּשִׁין וְיֵאָכְלוּ בְּמוּמָן וְאֵינָן קְרֵבִין. וְכֵן אִם יָצָא עֲשִׂירִי וְאַחַד עָשָׂר כְּאֶחָד. אִם קְרָאָן עֲשִׂירִי הֲרֵי עֲשִׂירִי וְאַחַד עָשָׂר מְעֹרָבִים זֶה בָּזֶה וְהֵם כְּמוֹ מַעֲשֵׂר שֶׁנִּתְעָרֵב בִּשְׁלָמִים שֶׁיֵּאָכְלוּ בְּמוּמָן כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת פְּסוּלֵי הַמֻּקְדָּשִׁין. וְאִם קְרָאָן אַחַד עָשָׂר הֲרֵי הָעֲשִׂירִי וְהַחֻלִּין מְעֹרָבִין זֶה בָּזֶה וְיֵאָכְלוּ בְּמוּמָן:","הִתְחִיל לִמְנוֹת וְיָצְאוּ תְּחִלָּה שְׁנַיִם שֶׁהֵן רִאשׁוֹן וְשֵׁנִי הֲרֵי זֶה מוֹנֶה הַכּל זוּג זוּג וּמְקַדֵּשׁ זוּג עֲשִׂירִי. וְכֵן אִם מְנָאָן שְׁלֹשָׁה שְׁלֹשָׁה בְּכָל פַּעַם וּפַעַם אוֹ חֲמִשָּׁה חֲמִשָּׁה מְקַדֵּשׁ הַכַּת הָעֲשִׂירִית:","יָצְאוּ בַּתְּחִלָּה שְׁנַיִם וּמְנָאָן אֶחָד וְקָרָא הַשְּׁלִישִׁי שֶׁיָּצָא אַחֲרֵיהֶן שֵׁנִי וּמָנָה כְּדַרְכּוֹ אֶחָד אֶחָד הֲרֵי הַתְּשִׁיעִי וְהָעֲשִׂירִי מֻקְדָּשִׁין וְיֵאָכְלוּ בְּמוּמָן. הַתְּשִׁיעִי מִפְּנֵי שֶׁהוּא הָעֲשִׂירִי הַוַּדַּאי שֶׁהֲרֵי שְׁנַיִם יָצְאוּ בַּתְּחִלָּה. וְזֶה שֶׁקְּרָאוֹ עֲשִׂירִי הוּא אַחַד עָשָׂר וְהַקּוֹרֵא לְאַחַד עָשָׂר עֲשִׂירִי נִתְקַדֵּשׁ כְּמוֹ שֶׁבֵּאַרְנוּ:","מְנָאָן לְמַפְרֵעַ כְּגוֹן שֶׁיָּצָא רִאשׁוֹן וְאָמַר עֲשִׂירִי וְיָצָא שֵׁנִי וְאָמַר תְּשִׁיעִי עַד שֶׁיָּצָא הָעֲשִׂירִי וּמָנָה אַחַת הֲרֵי זֶה קָדַשׁ שֶׁהָעֲשִׂירִי מֵאֵלָיו נִתְקַדֵּשׁ:","קָרָא לַתְּשִׁיעִי עֲשִׂירִי וְנִשְׁאַר הָעֲשִׂירִי בַּדִּיר. הַתְּשִׁיעִי יֵאָכֵל בְּמוּמוֹ וְזֶה שֶׁנִּשְׁאַר בַּדִּיר מַעֲשֵׂר אַף עַל פִּי שֶׁלֹּא יָצָא וְלֹא בֵּרְרוֹ שֶׁהָעֲשִׂירִי מֵאֵלָיו נִתְקַדֵּשׁ. מֵת הָעֲשִׂירִי בַּדִּיר הַתְּשִׁיעִי יֵאָכֵל בְּמוּמוֹ וְכָל הַשְּׁמוֹנָה שֶׁיָּצְאוּ וְנִמְנוּ פְּטוּרִין וְאַף עַל פִּי שֶׁלֹּא נִתְקַדֵּשׁ עֲשִׂירִי שֶׁלָּהֶן לִקָּרֵב אֶלָּא מֵת קֹדֶם שֶׁיָּצָא. שֶׁהַמִּנְיָן הָרָאוּי פּוֹטֵר:","הִכְנִיס עֲשָׂרָה טְלָאִים לַדִּיר וְהָיָה מוֹנֶה וְהוֹלֵךְ. מֵת אֶחָד מִן הַמְּנוּיִין מוֹנֶה וּמַשְׁלִים כְּדַרְכּוֹ וּמְקַדֵּשׁ עֲשִׂירִי אַף עַל פִּי שֶׁאֵין שָׁם עַתָּה חַיִּים אֶלָּא תִּשְׁעָה:","מֵת אֶחָד מֵאֵלּוּ שֶׁבְּתוֹךְ הַדִּיר אֵלּוּ שֶׁנִּמְנוּ פְּטוּרִין מִפְּנֵי שֶׁהַמִּנְיָן הָרָאוּי לְמַעֲשֵׂר פּוֹטֵר אַף עַל פִּי שֶׁלֹּא הִפְרִישׁ עֲלֵיהֶן כְּמוֹ שֶׁבֵּאַרְנוּ. וְאֵלּוּ שֶׁבְּתוֹךְ הַדִּיר מַנִּיחָן לְגֹרֶן אַחֵר עַד שֶׁיִּצְטָרְפוּ לַאֲחֵרִים. וְכֵן מִי שֶׁהָיוּ לוֹ אַרְבָּעָה עָשָׂר טְלָאִים וְהִכְנִיסָן לַדִּיר וְיָצְאוּ אַרְבָּעָה וּמְנָאָן בְּפֶתַח זֶה וְיָצְאוּ שִׁשָּׁה וּמְנָאָן בְּפֶתַח אַחֵר וְנִשְׁאֲרוּ שָׁם אַרְבָּעָה בְּתוֹךְ הַדִּיר. אִם יָצְאוּ הָאַרְבָּעָה הַנִּשְׁאָרִים מִן הַפֶּתַח שֶׁיָּצְאוּ בּוֹ הַשִּׁשָּׁה נוֹטֵל מֵהֶן אֶחָד וְכֻלָּן פְּטוּרִין. שֶׁאוֹתָן הָאַרְבָּעָה שֶׁיָּצְאוּ תְּחִלָּה מִפֶּתַח רִאשׁוֹן מִנְיָן הָרָאוּי פְּטָרָן. וְאִם יָצְאוּ אֵלּוּ הָאַרְבָּעָה הַנִּשְׁאָרִים מִן הַפֶּתַח שֶׁיָּצְאוּ בּוֹ הָאַרְבָּעָה תְּחִלָּה. הֲרֵי אוֹתָם הָאַרְבָּעָה שֶׁיָּצְאוּ בַּתְּחִלָּה וְאוֹתָן הַשִּׁשָּׁה שֶׁיָּצְאוּ אַחֲרֵיהֶן בְּפֶתַח שֵׁנִי פְּטוּרִין שֶׁכָּל אֶחָד מֵהֶן נִמְנֶה מִנְיָן הָרָאוּי לְמַעֲשֵׂר שֶׁהֲרֵי נִשְׁאֲרוּ שָׁם בַּדִּיר אֲחֵרִים לְהַשְׁלִים הַמִּנְיָן וּלְעַשֵּׂר. אֲבָל אֵלּוּ הָאַרְבָּעָה שֶׁנִּשְׁאֲרוּ אַף עַל פִּי שֶׁיָּצְאוּ וְנִמְנוּ מִפֶּתַח הָרִאשׁוֹן אֵינוֹ מִנְיָן הָרָאוּי לְפִיכָךְ מִצְטָרְפִין לְגֹרֶן אַחֵר. יָצְאוּ אַרְבָּעָה מִפֶּתַח זֶה וְאַרְבָּעָה מִפֶּתַח שֵׁנִי וְנִשְׁאֲרוּ שָׁם שִׁשָּׁה. אִם יָצְאוּ הַשִּׁשָּׁה מֵאֶחָד מִשְּׁנֵי הַפְּתָחִים נוֹטֵל מֵהֶן אֶחָד מַעֲשֵׂר וְכֻלָּן פְּטוּרִין. וְאִם יָצְאוּ הַשִּׁשָּׁה בִּשְׁנֵי הַפְּתָחִים הֲרֵי הַשִּׁשָּׁה מִצְטָרְפִין לְגֹרֶן אַחֵר וְהַשְּׁמוֹנָה שֶׁיָּצְאוּ תְּחִלָּה מִכָּאן וּמִכָּאן פְּטוּרִין שֶׁכָּל אַרְבָּעָה מֵהֶן נִמְנוּ מִנְיָן הָרָאוּי לְהַשְׁלִים עָלָיו עֲשָׂרָה וּלְעַשֵּׂר שֶׁהֲרֵי שִׁשָּׁה הָיוּ שָׁם נִשְׁאָרִים בְּתוֹךְ הַדִּיר:","הָיוּ לוֹ תִּשְׁעָה עָשָׂר טְלָאִים בְּתוֹךְ הַדִּיר וְיָצְאוּ תִּשְׁעָה בְּפֶתַח זֶה וְתִשְׁעָה בְּפֶתַח שֵׁנִי נוֹטֵל הָאַחֲרוֹן לְשֵׁם מַעֲשֵׂר וְכֻלָּן פְּטוּרִין. שֶׁאוֹתָן הַתִּשְׁעָה נִמְנוּ מִנְיָן הָרָאוּי:","הָיָה מוֹנֶה וְהוֹצִיא הַטָּלֶה רֹאשׁוֹ וְרֻבּוֹ מִן הַדִּיר וְחָזַר הֲרֵי הוּא כְּמָנוּי לְכָל דָּבָר:","הָיָה מוֹנֶה וְהִפְסִיק הַמִּנְיָן מִפְּנֵי חֲבֵרוֹ שֶׁדִּבֵּר עִמּוֹ אוֹ שֶׁחָשְׁכָה לֵיל שַׁבָּת הֲרֵי זֶה חוֹזֵר וּמַשְׁלִים מִנְיָנוֹ אַחַר כָּךְ:","הָיָה מוֹנֶה הַיּוֹצְאִין אֶחָד אֶחָד וּמְקַדֵּשׁ עֲשִׂירִי וְקָפַץ אֶחָד מִן הַמְּנוּיִין לְתוֹךְ הַדִּיר לְתוֹךְ אֵלּוּ שֶׁעֲדַיִן לֹא נִמְנוּ וְלֹא נִתְעַשְּׂרוּ. נִפְטְרוּ הַכּל. שֶׁכָּל אֶחָד מֵהֶן סָפֵק אִם הוּא הַמָּנוּי שֶׁקָּפַץ אוֹ אַחֵר. וּכְבָר בֵּאַרְנוּ שֶׁכָּל הַמְּנוּיִין פְּטוּרִין:","קָפַץ אֶחָד מִן הָעֲשִׂירִיִּים לְתוֹךְ הַדִּיר. כֻּלָּן יִרְעוּ עַד שֶׁיִּפּל בָּהֶן מוּם וְיֵאָכְלוּ בְּמוּמָן:"],"Mishneh Torah, Forbidden Foods 4":["הָאוֹכֵל כְּזַיִת מִבְּשַׂר בְּהֵמָה שֶׁמֵּתָה אוֹ חַיָּה שֶׁמֵּתָה אוֹ עוֹף שֶׁמֵּת לוֹקֶה שֶׁנֶּאֱמַר (דברים יד כא) \"לֹא תֹאכְלוּ כָל נְבֵלָה\". וְכָל שֶׁלֹּא נִשְׁחֲטָה כָּרָאוּי הֲרֵי זוֹ מֵתָה. וּבְהִלְכוֹת הַשְּׁחִיטָה יִתְבָּאֵר הַשְּׁחִיטָה שֶׁהִיא כָּרָאוּי וְשֶׁאֵינָהּ כָּרָאוּי:","אֵין אָסוּר מִשּׁוּם נְבֵלָה אֶלָּא מִינִים טְהוֹרִים בִּלְבַד מִפְּנֵי שֶׁהֵן רְאוּיִין לִשְׁחִיטָה וְאִם נִשְׁחֲטוּ שְׁחִיטָה כְּשֵׁרָה יִהְיוּ מֻתָּרִין בַּאֲכִילָה. אֲבָל מִינִין טְמֵאִין שֶׁאֵין שְׁחִיטָה מוֹעֶלֶת בָּהֶן בֵּין שֶׁנִּשְׁחֲטָה כָּרָאוּי בֵּין שֶׁמֵּתָה כְּדַרְכָּהּ בֵּין שֶׁחָתַךְ בָּשָׂר מִן הַחַי מִמֶּנָּה וַאֲכָלוֹ אֵינוֹ לוֹקֶה מִשּׁוּם נְבֵלָה וּטְרֵפָה אֶלָּא מִשּׁוּם אוֹכֵל בְּשַׂר טְמֵאָה:","הָאוֹכֵל עוֹף טָהוֹר חַי כָּל שֶׁהוּא לוֹקֶה מִשּׁוּם אוֹכֵל נְבֵלָה וְאַף עַל פִּי שֶׁאֵין בּוֹ כְּזַיִת הוֹאִיל וַאֲכָלוֹ כֻּלּוֹ. וְאִם אֲכָלוֹ אַחַר שֶׁמֵּת עַד שֶׁיִּהְיֶה בּוֹ כְּזַיִת. וְאַף עַל פִּי שֶׁאֵין בְּכֻלּוֹ בָּשָׂר כְּזַיִת הוֹאִיל וְיֵשׁ בְּכֻלּוֹ כְּזַיִת חַיָּב עָלָיו מִשּׁוּם נְבֵלָה:","הָאוֹכֵל כְּזַיִת מִבְּשַׂר נֵפֶל בְּהֵמָה טְהוֹרָה לוֹקֶה מִשּׁוּם אוֹכֵל נְבֵלָה. וְאָסוּר לֶאֱכל מִן הַבְּהֵמָה שֶׁנּוֹלְדָה עַד לֵיל שְׁמִינִי שֶׁכָּל שֶׁלֹּא שָׁהָה שְׁמוֹנָה יָמִים בִּבְהֵמָה הֲרֵי זֶה כְּנֵפֶל. וְאֵין לוֹקִין עָלָיו. וְאִם נוֹדַע לוֹ שֶׁכָּלוּ לוֹ חֳדָשָׁיו בַּבֶּטֶן וְאַחַר כָּךְ נוֹלַד שֶׁהֵן תִּשְׁעָה חֳדָשִׁים לִבְהֵמָה גַּסָּה וַחֲמִשָּׁה לְדַקָּה הֲרֵי זֶה מֻתָּר בַּיּוֹם שֶׁנּוֹלַד:","הַשִּׁלְיָא שֶׁיָּצָאת עִם הַוָּלָד אֲסוּרָה בַּאֲכִילָה וְהָאוֹכְלָהּ פָּטוּר שֶׁאֵינָהּ בָּשָׂר:","הָאוֹכֵל כְּזַיִת מִבְּשַׂר בְּהֵמָה אוֹ חַיָּה אוֹ עוֹף טְהוֹרִים שֶׁנִּטְרְפוּ לוֹקֶה שֶׁנֶּאֱמַר (שמות כב ל) \"וּבָשָׂר בַּשָּׂדֶה טְרֵפָה לֹא תֹאכֵלוּ לַכֶּלֶב תַּשְׁלִכוּן אֹתוֹ\". טְרֵפָה הָאֲמוּרָה בַּתּוֹרָה זוֹ שֶׁטָּרְפָה אוֹתָהּ חַיַּת הַיַּעַר כְּגוֹן אֲרִי וְנָמֵר וְכַיּוֹצֵא בָּהֶן. וְכֵן עוֹף שֶׁטָּרַף אוֹתוֹ עוֹף הַדּוֹרֵס כְּגוֹן נֵץ וְכַיּוֹצֵא בּוֹ. וְאֵין אַתָּה יָכוֹל לוֹמַר שֶׁטָּרְפָה אוֹתָהּ וְהֵמִיתָה אוֹתָהּ שֶׁאִם מֵתָה הֲרֵי הִיא נְבֵלָה. וּמַה לִּי מֵתָה מֵחֲמַת עַצְמָהּ אוֹ הִכָּה בְּסַיִף וֶהֱמִיתָהּ אוֹ שְׁבָרָהּ אֲרִי וֶהֱמִיתָהּ. הָא אֵינוֹ מְדַבֵּר אֶלָּא בְּשֶׁנִּטְרְפָה וְלֹא מֵתָה:","וְאִם הַטְּרֵפָה שֶׁלֹּא מֵתָה אֲסוּרָה יָכוֹל אִם בָּא זְאֵב וְגָרַר הַגְּדִי בְּרַגְלוֹ אוֹ בִּזְנָבוֹ אוֹ בְּאָזְנוֹ וְרָדַף אָדָם וְהִצִּילוֹ מִפִּיו יִהְיֶה אָסוּר שֶׁהֲרֵי נִטְרַף תַּלְמוּד לוֹמַר (שמות כב ל) \"וּבָשָׂר בַּשָּׂדֶה טְרֵפָה\" וְגוֹ' (שמות כב ל) \"לַכֶּלֶב תַּשְׁלִיכוּן אֹתוֹ\". עַד שֶׁיַּעֲשֶׂה אוֹתָהּ בָּשָׂר הָרְאוּיָה לַכֶּלֶב. הָא לָמַדְתָּ שֶׁהַטְּרֵפָה הָאֲמוּרָה בַּתּוֹרָה הִיא שֶׁטָּרְפָה אוֹתוֹ חַיַּת הַיַּעַר וְשָׁבְרָה אוֹתָהּ וְנָטָה לָמוּת וַעֲדַיִן לֹא מֵתָה. אַף עַל פִּי שֶׁקָּדַם וּשְׁחָטָהּ קֹדֶם שֶׁתָּמוּת הֲרֵי זוֹ אֲסוּרָה מִשּׁוּם טְרֵפָה הוֹאִיל וְאִי אֶפְשָׁר שֶׁתִּחְיֶה מִמַּכָּה זוֹ הַבָּאָה עָלֶיהָ:","נִמְצֵאתָ לָמֵד שֶׁהַתּוֹרָה אָסְרָה הַמֵּתָה וְהִיא הַנְּבֵלָה. וְאָסְרָה הַנּוֹטָה לָמוּת מֵחֲמַת מַכּוֹתֶיהָ וְאַף עַל פִּי שֶׁעֲדַיִן לֹא מֵתָה וְהִיא הַטְּרֵפָה. וּכְשֵׁם שֶׁלֹּא תַּחֲלֹק בְּמִיתָה בֵּין מֵתָה מֵחֲמַת עַצְמָהּ בֵּין שֶׁנָּפְלָה וָמֵתָה בֵּין שֶׁחֲנָקָהּ עַד שֶׁמֵּתָה בֵּין שֶׁדְּרָסַתָּה חַיָּה וַהֲרָגַתָּה. כָּךְ לֹא תַּחֲלֹק בְּנוֹטָה לָמוּת בֵּין שֶׁטְּרָפַתָּה חַיָּה וּשְׁבָרַתָּה בֵּין שֶׁנָּפְלָה מִן הַגַּג וְנִשְׁתַּבְּרוּ רֹב צַלְעוֹתֶיהָ בֵּין שֶׁנָּפְלָה וְנִתְרַסְּקוּ אֵיבָרֶיהָ בֵּין שֶׁזָּרַק בָּהּ חֵץ וְנָקַב לִבָּהּ אוֹ רֵאָתָהּ בֵּין שֶׁבָּא לָהּ חלִי מֵחֲמַת עַצְמָהּ וְנָקַב לִבָּהּ אוֹ רֵאָתָהּ אוֹ שִׁבֵּר רֹב צַלְעוֹתֶיהָ וְכַיּוֹצֵא בָּהֶן. הוֹאִיל וְהִיא נוֹטָה לָמוּת מִכָּל מָקוֹם הֲרֵי זוֹ טְרֵפָה. בֵּין שֶׁהָיָה הַגּוֹרֵם בִּידֵי בָּשָׂר וָדָם בֵּין שֶׁהָיָה בִּידֵי שָׁמַיִם. אִם כֵּן לָמָּה נֶאֱמַר בַּתּוֹרָה (שמות כב ל) \"טְרֵפָה\". דִּבֵּר הַכָּתוּב בַּהוֹוֶה. שֶׁאִם לֹא תֹּאמַר כֵּן לֹא תֵּאָסֵר אֶלָּא אוֹתָהּ שֶׁנִּטְרְפָה בַּשָּׂדֶה אֲבָל אִם נִטְרְפָה בֶּחָצֵר לֹא תֵּאָסֵר. הָא לָמַדְתָּ שֶׁאֵין הַכָּתוּב מְדַבֵּר אֶלָּא בַּהוֹוֶה:","וְעִנְיַן הַכָּתוּב שֶׁהַנּוֹטָה לָמוּת מֵחֲמַת מַכּוֹתֶיהָ וְאִי אֶפְשָׁר לָהּ לִחְיוֹת מֵחֲמַת מַכָּה זוֹ אֲסוּרָה. מִכָּאן אָמְרוּ חֲכָמִים זֶה הַכְּלָל כָּל שֶׁאֵין כָּמוֹהָ חַיָּה טְרֵפָה. וּבְהִלְכוֹת שְׁחִיטָה יִתְבָּאֵר אֵי זֶה חלִי עוֹשֶׂה אוֹתָהּ טְרֵפָה וְאֵי זֶה חלִי אֵין עוֹשֶׂה אוֹתָהּ טְרֵפָה:","וְכֵן הַחוֹתֵךְ בָּשָׂר מִן הַחַי מִן הַטְּהוֹרִים הֲרֵי אוֹתוֹ הַבָּשָׂר טְרֵפָה וְהָאוֹכֵל מִמֶּנּוּ כְּזַיִת לוֹקֶה מִשּׁוּם אוֹכֵל טְרֵפָה. שֶׁהֲרֵי בָּשָׂר זֶה מִבְּהֵמָה שֶׁלֹּא נִשְׁחֲטָה וְלֹא מֵתָה. מַה לִּי טָרְפָה אוֹתָהּ חַיָּה מַה לִּי חֲתָכָהּ בְּסַכִּין מַה לִּי בְּכֻלָּהּ מַה לִּי בְּמִקְצָתָהּ. הֲרֵי הוּא אוֹמֵר (שמות כב ל) \"וּבָשָׂר בַּשָּׂדֶה טְרֵפָה לֹא תֹאכֵלוּ\" כֵּיוָן שֶׁנַּעֲשֵׂית הַבְּהֵמָה בָּשָׂר בַּשָּׂדֶה הֲרֵי הִיא טְרֵפָה:","בְּהֵמָה שֶׁהִיא חוֹלָה מֵחֲמַת שֶׁתָּשַׁשׁ כֹּחָהּ וְנָטְתָה לָמוּת הוֹאִיל וְלֹא אֵרְעָה מַכָּה בְּאֵיבָר מֵאֵיבָרֶיהָ הַמְּמִיתִים אוֹתָהּ הֲרֵי זוֹ מֻתֶּרֶת. שֶׁלֹּא אָסְרָה תּוֹרָה אֶלָּא כְּעֵין טְרֵפַת חַיַּת הַיַּעַר שֶׁהֲרֵי עָשָׂה בָּהּ מַכָּה הַמְּמִיתָה אוֹתָהּ:","אַף עַל פִּי שֶׁהִיא מֻתֶּרֶת גְּדוֹלֵי הַחֲכָמִים לֹא הָיוּ אוֹכְלִין מִבְּהֵמָה שֶׁמְּמַהֲרִין וְשׁוֹחֲטִין אוֹתָהּ כְּדֵי שֶׁלֹּא תָּמוּת וְאַף עַל פִּי שֶׁפִּרְכְּסָה בְּסוֹף שְׁחִיטָה. וְדָבָר זֶה אֵין בּוֹ אִסּוּר אֶלָּא כָּל הָרוֹצֶה לְהַחֲמִיר עַל עַצְמוֹ בְּדָבָר זֶה הֲרֵי זֶה מְשֻׁבָּח:","הַשּׁוֹחֵט בְּהֵמָה חַיָּה וְעוֹף וְלֹא יָצָא מֵהֶן דָּם הֲרֵי אֵלּוּ מֻתָּרִין וְאֵין אוֹמְרִין שֶׁמָּא מֵתִים הָיוּ. וְכֵן הַשּׁוֹחֵט אֶת הַבְּרִיאָה וְלֹא פִּרְכְּסָה הֲרֵי זוֹ מֻתֶּרֶת. אֲבָל הַמְסֻכֶּנֶת וְהִיא כָּל שֶׁמַּעֲמִידִין אוֹתָהּ וְאֵינָהּ עוֹמֶדֶת אַף עַל פִּי שֶׁהִיא אוֹכֶלֶת מַאֲכַל בְּרִיאוֹת אִם שְׁחָטָהּ וְלֹא פִּרְכְּסָה כְּלָל הֲרֵי זוֹ נְבֵלָה וְלוֹקִין עָלֶיהָ. וְאִם פִּרְכְּסָה הֲרֵי זוֹ מֻתֶּרֶת. וְצָרִיךְ שֶׁיִּהְיֶה הַפִּרְכּוּס בְּסוֹף הַשְּׁחִיטָה. אֲבָל בִּתְחִלָּתָהּ אֵינוֹ מוֹעִיל:","כֵּיצַד הוּא הַפִּרְכּוּס בִּבְהֵמָה דַּקָּה וּבְחַיָּה גַּסָּה וְדַקָּה. בֵּין שֶׁפָּשְׁטָה יָדָהּ וְהֶחֱזִירָה אוֹ שֶׁפָּשְׁטָה רַגְלָהּ אַף עַל פִּי שֶׁלֹּא הֶחֱזִירָה אוֹ שֶׁכְּפָפָה רַגְלָהּ בִּלְבַד הֲרֵי זֶה פִּרְכּוּס וּמֻתָּר. אֲבָל אִם פָּשְׁטָה יָדָהּ וְלֹא הֶחֱזִירָתָהּ הֲרֵי זוֹ אֲסוּרָה שֶׁאֵין זוֹ אֶלָּא הוֹצָאַת נֶפֶשׁ בִּלְבַד. וּבִבְהֵמָה גַּסָּה אֶחָד הַיָּד וְאֶחָד הָרֶגֶל בֵּין שֶׁפָּשְׁטָה וְלֹא כָּפְפָה בֵּין כָּפְפָה וְלֹא פָּשְׁטָה הֲרֵי זוֹ פִּרְכּוּס וּמֻתֶּרֶת. וְאִם לֹא פָּשְׁטָה לֹא יָד וְלֹא רֶגֶל וְלֹא כָּפְפָה כְּלָל הֲרֵי זוֹ נְבֵלָה. וּבְעוֹף אֲפִלּוּ לֹא רִפְרֵף אֶלָּא בְּעֵינוֹ וְלֹא כִּשְׁכֵּשׁ אֶלָּא בִּזְנָבוֹ הֲרֵי זֶה פִּרְכּוּס:","הַשּׁוֹחֵט אֶת הַמְסֻכֶּנֶת בַּלַּיְלָה וְלֹא יָדַע אִם פִּרְכְּסָה אוֹ לֹא פִּרְכְּסָה הֲרֵי זוֹ סְפֵק נְבֵלָה וַאֲסוּרָה:","כָּל אִסּוּרִין שֶׁבַּתּוֹרָה אֵין מִצְטָרְפִין זֶה עִם זֶה חוּץ מֵאִסּוּרֵי נָזִיר כְּמוֹ שֶׁיִּתְבָּאֵר שָׁם. לְפִיכָךְ הַלּוֹקֵחַ מְעַט חֵלֶב וּמְעַט דָּם וּמְעַט בְּשַׂר בְּהֵמָה טְמֵאָה וּמְעַט בְּשַׂר נְבֵלָה וּמְעַט בְּשַׂר דָּג טָמֵא וּמְעַט בְּשַׂר עוֹף טָמֵא וְכַיּוֹצֵא בָּאֵלּוּ מִשְּׁאָר הָאִסּוּרִין וְצֵרֵף מִן הַכּל כְּזַיִת וַאֲכָלוֹ אֵינוֹ לוֹקֶה וְדִינוֹ כְּדִין אוֹכֵל חֲצִי שִׁעוּר:","כָּל הַנְּבֵלוֹת מִצְטָרְפוֹת זוֹ עִם זוֹ. וּנְבֵלָה מִצְטָרֶפֶת עִם טְרֵפָה. וְכֵן כָּל בְּהֵמָה וְחַיָּה הַטְּמֵאִים מִצְטָרְפִין זֶה עִם זֶה. אֲבָל בְּשַׂר נְבֵלָה עִם בְּשַׂר בְּהֵמָה טְמֵאָה אֵין מִצְטָרְפִין. כֵּיצַד. הַלּוֹקֵחַ מִנִּבְלַת הַשּׁוֹר וְנִבְלַת הַצְּבִי וְנִבְלַת הַתַּרְנְגוֹל וְקִבֵּץ מִן הַכּל כְּזַיִת בָּשָׂר וַאֲכָלוֹ לוֹקֶה. וְכֵן אִם קִבֵּץ חֲצִי זַיִת מִנִּבְלַת בְּהֵמָה טְהוֹרָה וַחֲצִי זַיִת מִן הַטְּרֵפָה אוֹ חֲצִי זַיִת מִבְּשַׂר נְבֵלָה וַחֲצִי זַיִת מִבָּשָׂר מִן הַחַי מִן הַטְּהוֹרָה וַאֲכָלוֹ לוֹקֶה. וְכֵן בְּשַׂר הַגָּמָל וְהַחֲזִיר וְהָאַרְנֶבֶת שֶׁקִּבֵּץ מִכֻּלָּם כְּזַיִת וַאֲכָלוֹ לוֹקֶה. אֲבָל אִם צֵרֵף חֲצִי זַיִת מִנִּבְלַת הַשּׁוֹר וַחֲצִי זַיִת מִבְּשַׂר הַגָּמָל אֵינָן מִצְטָרְפִין. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְכֵן בְּהֵמָה טְמֵאָה וְעוֹף טָמֵא אוֹ דָּג טָמֵא אֵין בְּשַׂר שְׁנֵיהֶן מִצְטָרֵף. לְפִי שֶׁהֵן שְׁנֵי שֵׁמוֹת. שֶׁהֲרֵי כָּל אֶחָד מֵהֶן בְּלָאו בִּפְנֵי עַצְמוֹ כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל כָּל הָעוֹפוֹת הַטְּמֵאִין מִצְטָרְפִין כְּמוֹ שֶׁמִּצְטָרְפִין כָּל בְּהֵמָה וְחַיָּה הַטְּמֵאִין. זֶה הַכְּלָל כָּל שֶׁאִסּוּרָן בְּלָאו אֶחָד מִצְטָרְפִין. בִּשְׁנֵי לָאוִין אֵין מִצְטָרְפִין. חוּץ מִנְּבֵלָה וּטְרֵפָה הוֹאִיל וְהַטְּרֵפָה תְּחִלַּת נְבֵלָה הִיא:","הָאוֹכֵל מִנְּבֵלָה וּטְרֵפָה אוֹ מִבְּהֵמָה וְחַיָּה הַטְּמֵאִים מִן הָעוֹר וּמִן הָעֲצָמוֹת וּמִן הַגִּידִים וּמִן הַקַּרְנַיִם וּמִן הַטְּלָפַיִם וּמִן הַצִּפָּרְנַיִם שֶׁל עוֹף מִמְּקוֹמוֹת שֶׁמְּבַצְבֵּץ מִשָּׁם הַדָּם כְּשֶׁיֵּחָתְכוּ וּמִן הַשִּׁלְיָא שֶׁלָּהֶן אַף עַל פִּי שֶׁהוּא אָסוּר הֲרֵי זֶה פָּטוּר מִפְּנֵי שֶׁאֵלּוּ אֵינָן רְאוּיִין לַאֲכִילָה וְאֵין מִצְטָרְפִין עִם הַבָּשָׂר לִכְזַיִת:","קֵיבַת הַנְּבֵלָה וְקֵיבַת הַטְּמֵאָה מֻתֶּרֶת מִפְּנֵי שֶׁהִיא כִּשְׁאָר טִנֹּפֶת שֶׁבַּגּוּף. וּלְפִיכָךְ מֻתָּר לְהַעֲמִיד הַגְּבִינָה בְּקֵיבַת שְׁחִיטַת הָעַכּוּ\"ם וּבְקֵיבַת בְּהֵמָה וְחַיָּה טְמֵאָה. אֲבָל עוֹר הַקֵּבָה הֲרֵי הוּא כִּשְׁאָר הַמֵּעַיִם וְאָסוּר:","עוֹר הַבָּא כְּנֶגֶד פָּנָיו שֶׁל חֲמוֹר מֻתָּר בַּאֲכִילָה מִפְּנֵי שֶׁהוּא כְּמוֹ הַפֶּרֶשׁ וּמֵי רַגְלַיִם שֶׁהֵן מֻתָּרִין. יֵשׁ עוֹרוֹת שֶׁהֵן כְּבָשָׂר וְהָאוֹכֵל מֵהֶן כְּזַיִת כְּאוֹכֵל מִן הַבָּשָׂר. וְהוּא כְּשֶׁיֹּאכַל אוֹתָן כְּשֶׁהֵן רַכִּים:","וְאֵלּוּ שֶׁעוֹרוֹתֵיהֶן כִּבְשָׂרָן. עוֹר הָאָדָם וְעוֹר הַחֲזִיר שֶׁל יִשּׁוּב וְעוֹר חֲטוֹטֶרֶת שֶׁל גָּמָל שֶׁלֹּא טָעֲנוּ עָלָיו מַשָּׂא מֵעוֹלָם וְלֹא הִגִּיעַ לְמַשָּׂא שֶׁעֲדַיִן הִיא רַכָּה וְעוֹר בֵּית הַבּשֶׁת וְעוֹר שֶׁתַּחַת הָאַלְיָה וְעוֹר הַשָּׁלִיל וְעוֹר הָאֲנָקָה וְהַכֹּחַ וְהַלְּטָאָה וְהַחֹמֶט. כָּל אֵלּוּ הָעוֹרוֹת כְּשֶׁהֵן רַכּוֹת הֲרֵי הֵן כְּבָשָׂר לְכָל דָּבָר בֵּין לְאִסּוּר אֲכִילָה בֵּין לְטֻמְאָה:","נֶאֱמַר בְּשׁוֹר הַנִּסְקָל (שמות כא כח) \"וְלֹא יֵאָכֵל אֶת בְּשָׂרוֹ\". וְהֵיאַךְ הָיָה אֶפְשָׁר לְאָכְלוֹ אַחַר שֶׁנִּסְקַל וַהֲרֵי הוּא נְבֵלָה. אֶלָּא לֹא בָּא הַכָּתוּב אֶלָּא לְהוֹדִיעֲךָ שֶׁכֵּיוָן שֶׁנִּגְמַר דִּינוֹ לִסְקִילָה נֶאֱסַר וְנַעֲשָׂה כִּבְהֵמָה טְמֵאָה. וְאִם קָדַם וּשְׁחָטוֹ שְׁחִיטָה כְּשֵׁרָה הֲרֵי זֶה אָסוּר בַּהֲנָיָה. וְאִם אָכַל מִבְּשָׂרוֹ כְּזַיִת לוֹקֶה. וְכֵן כְּשֶׁיִּסָּקֵל לֹא יִמָּכֵר וְלֹא יִתְּנֶנּוּ לִכְלָבִים וְלֹא לְעַכּוּ\"ם לְכָךְ נֶאֱמַר לֹא יֵאָכֵל אֶת בְּשָׂרוֹ. וּפֶרֶשׁ שֶׁל שׁוֹר הַנִּסְקָל מֻתָּר בַּהֲנָאָה. נוֹדַע שֶׁהוּא פָּטוּר מִסְּקִילָה אַחַר שֶׁנִּגְמַר דִּינוֹ כְּגוֹן שֶׁהוּזְמוּ הָעֵדִים יֵצֵא וְיִרְעֶה בָּעֵדֶר. וְאִם נוֹדַע אַחַר שֶׁנִּסְקָל הֲרֵי זֶה מֻתָּר בַּהֲנָיָה:"],"Mishneh Torah, Forbidden Intercourse 15":["אֵי זֶהוּ (דברים כג ג) \"מַמְזֵר\" הָאָמוּר בַּתּוֹרָה. זֶה הַבָּא מֵעֶרְוָה מִן הָעֲרָיוֹת. חוּץ מִן הַנִּדָּה שֶׁהַבֵּן מִמֶּנָּה פָּגוּם וְאֵינוֹ מַמְזֵר. אֲבָל הַבָּא עַל שְׁאָר הָעֲרָיוֹת בֵּין בְּאֹנֶס בֵּין בְּרָצוֹן בֵּין בְּזָדוֹן בֵּין בִּשְׁגָגָה הַוָּלָד מַמְזֵר. וְאֶחָד זְכָרִים וְאֶחָד נְקֵבוֹת אֲסוּרִין לְעוֹלָם שֶׁנֶּאֱמַר (דברים כג ג) \"גַּם דּוֹר עֲשִׂירִי\" כְּלוֹמַר לְעוֹלָם:","אֶחָד מַמְזֵר שֶׁנָּשָׂא יִשְׂרְאֵלִית אוֹ יִשְׂרְאֵלִי שֶׁנָּשָׂא מַמְזֶרֶת כֵּיוָן שֶׁבָּעֲלוּ אַחַר הַקִּדּוּשִׁין לוֹקִין. קִדֵּשׁ וְלֹא בָּעַל אֵינוֹ לוֹקֶה. בָּעַל וְלֹא קִדֵּשׁ אֵינָן לוֹקִין מִשּׁוּם מַמְזֵרוּת שֶׁאֵין לְךָ בְּכָל חַיָּבֵי לָאוִין מִי שֶׁלּוֹקֶה עַל בְּעִילָה בְּלֹא קִדּוּשִׁין אֶלָּא כֹּהֵן גָּדוֹל בְּאַלְמָנָה כְּמוֹ שֶׁיִּתְבָּאֵר. הַמַּחֲזִיר גְּרוּשָׁתוֹ מִשֶּׁנִּשֵּׂאת הַוָּלָד כָּשֵׁר שֶׁהֲרֵי אֵינָהּ עֶרְוָה:","עַכּוּ\"ם וְעֶבֶד הַבָּא עַל בַּת יִשְׂרָאֵל הַוָּלָד כָּשֵׁר בֵּין פְּנוּיָה בֵּין בְּאֵשֶׁת אִישׁ בֵּין בְּאֹנֶס בֵּין בְּרָצוֹן. עַכּוּ\"ם וְעֶבֶד הַבָּאִים עַל הַמַּמְזֶרֶת הַוָּלָד מַמְזֵר. וּמַמְזֵר הַבָּא עַל הָעַכּוּ\"ם הַוָּלָד עַכּוּ\"ם. נִתְגַּיֵּר הֲרֵי הוּא כָּשֵׁר כִּשְׁאָר גֵּרִים. וְאִם בָּא עַל הַשִּׁפְחָה הַוָּלָד עֶבֶד. שִׁחְרְרוֹ הַוָּלָד כָּשֵׁר כִּשְׁאָר עֲבָדִים מְשֻׁחְרָרִין וּמֻתָּר בְּבַת יִשְׂרָאֵל:","זֶה הַכְּלָל בֵּן הַבָּא מִן הָעֶבֶד אוֹ מִן הָעַכּוּ\"ם אוֹ מִן הַשִּׁפְחָה אוֹ מִן בַּת עַכּוּ\"ם הֲרֵי הוּא כְּאִמּוֹ וְאֵין מַשְׁגִּיחִין עַל הָאָב. לְפִי דָּבָר זֶה הִתִּירוּ לְמַמְזֵר לִשָּׂא שִׁפְחָה כְּדֵי לְטַהֵר אֶת בָּנָיו שֶׁהֲרֵי הוּא מְשַׁחְרֵר אוֹתָם וְנִמְצְאוּ בְּנֵי חוֹרִין. וְלֹא גָּזְרוּ עַל הַשִּׁפְחָה לְמַמְזֵר מִפְּנֵי תַּקָּנַת הַבָּנִים:","מִי שֶׁחֶצְיוֹ עֶבֶד וְחֶצְיוֹ בֶּן חוֹרִין הַבָּא עַל אֵשֶׁת אִישׁ אוֹתוֹ הַבֵּן אֵין לוֹ תַּקָּנָה מִפְּנֵי שֶׁצַּד מַמְזֵרוּת וְצַד כַּשְׁרוּת מְעֹרָבִין בּוֹ. לְפִיכָךְ אָסוּר בְּשִׁפְחָה וְנִמְצְאוּ בָּנָיו כְּמוֹתוֹ לְעוֹלָם:","עַכּוּ\"ם הַבָּא עַל הַשִּׁפְחָה שֶׁטָּבְלָה הֲרֵי זֶה עֶבֶד וְעֶבֶד שֶׁטָּבַל שֶׁבָּא עַל עַכּוּ\"ם הַוָּלָד עַכּוּ\"ם הַלֵּךְ אַחַר הָאֵם אֲבָל עַכּוּ\"ם הַבָּא עַל שִׁפְחָה עַכּוּ\"ם אוֹ עֶבֶד עַכּוּ\"ם שֶׁבָּא עַל עַכּוּ\"ם בַּת חוֹרִין הַלֵּךְ אַחַר הַזָּכָר:","מַמְזֵר מֻתָּר לִשָּׂא גִּיֹּרֶת. וְכֵן הַמַּמְזֶרֶת מֻתֶּרֶת לְגֵר. וְהַבָּנִים מִשְּׁנֵיהֶם מַמְזֵרִים שֶׁהַוָּלָד הוֹלֵךְ אַחַר הַפָּגוּם שֶׁנֶּאֱמַר (דברים כג ג) \"בִּקְהַל ה'\" וּקְהַל גֵּרִים אֵינוֹ קָרוּי (דברים כג ג) \"קְהַל ה'\":","גִּיֹּרֶת שֶׁנִּשֵּׂאת לְגֵר וְהוֹלִידוּ בֵּן אַף עַל פִּי שֶׁהוֹרָתוֹ וְלֵדָתוֹ בִּקְדֻשָּׁה הֲרֵי זֶה מֻתָּר בְּמַמְזֶרֶת. וְכֵן בֶּן בֶּן בְּנוֹ עַד שֶׁיִּשְׁתַּקַּע שֵׁם גֵּרוּתוֹ מִמֶּנּוּ וְלֹא יִוָּדַע שֶׁהוּא גֵּר וְאַחַר כָּךְ יֵאָסֵר בְּמַמְזֶרֶת. וְאֶחָד הַגֵּרִים וְאֶחָד הָעֲבָדִים מְשֻׁחְרָרִין דִּין אֶחָד לְכֻלָּן:","גֵּר שֶׁנָּשָׂא בַּת יִשְׂרָאֵל אוֹ יִשְׂרָאֵל שֶׁנָּשָׂא גִּיֹּרֶת הַוָּלָד יִשְׂרָאֵל לְכָל דָּבָר וְאָסוּר בְּמַמְזֶרֶת:","שְׁלֹשָׁה מַמְזֵרִים הֵם. מַמְזֵר וַדַּאי וּמַמְזֵר סָפֵק וּמַמְזֵר מִדִּבְרֵי סוֹפְרִים. אֵי זֶהוּ מַמְזֵר וַדַּאי זֶה שֶׁבָּא מִן הָעֶרְוָה הַוַּדָּאִית כְּמוֹ שֶׁבֵּאַרְנוּ. וּמַמְזֵר סָפֵק זֶה שֶׁבָּא מִסְּפֵק עֶרְוָה כְּגוֹן הַבָּא עַל הָאִשָּׁה שֶׁנִּתְקַדְּשָׁה סְפֵק קִדּוּשִׁין אוֹ נִתְגָּרְשָׁה סְפֵק גֵּרוּשִׁין וְכַיּוֹצֵא בָּהֶן. מִדִּבְרֵי סוֹפְרִים. כְּגוֹן הָאִשָּׁה שֶׁשָּׁמְעָה שֶׁמֵּת בַּעְלָהּ וְנִשֵּׂאת וַהֲרֵי בַּעְלָהּ קַיָּם וּבָא בַּעְלָהּ הָרִאשׁוֹן עָלֶיהָ וְהִיא תַּחַת הַשֵּׁנִי הֲרֵי הַבֵּן מַמְזֵר מִדִּבְרֵי סוֹפְרִים:","פְּנוּיָה שֶׁנִּתְעַבְּרָה מִזְּנוּת אָמְרוּ לָהּ מַהוּ הָעֻבָּר הַזֶּה אוֹ הַיָּלוּד הַזֶּה אִם אָמְרָה בֵּן כָּשֵׁר הוּא וּלְיִשְׂרָאֵל נִבְעַלְתִּי הֲרֵי זוֹ נֶאֱמֶנֶת וְהַבֵּן כָּשֵׁר. וְאַף עַל פִּי שֶׁרֹב הָעִיר שֶׁזִּנְּתָה בָּהּ פְּסוּלִים:","וְאִם לֹא נִבְדְּקָה אִמּוֹ עַד שֶׁמֵּתָה אוֹ שֶׁהָיְתָה חֵרֶשֶׁת אוֹ אִלֶּמֶת אוֹ שׁוֹטָה אוֹ שֶׁאָמְרָה לִפְלוֹנִי הַמַּמְזֵר נִבְעַלְתִּי אוֹ לִפְלוֹנִי הַנָּתִין אֲפִלּוּ אוֹתוֹ פְּלוֹנִי מוֹדֶה שֶׁהוּא מִמֶּנּוּ הֲרֵי זֶה הַיָּלוּד סְפֵק מַמְזֵר. כְּשֵׁם שֶׁזִּנְּתָה עִם זֶה שֶׁהוֹדָה לָהּ כָּךְ זִנְּתָה עִם אַחֵר. וְזֶה הוּא הַנִּקְרָא שְׁתוּקִי שֶׁמַּכִּיר אֶת אִמּוֹ וְאֵינוֹ מַכִּיר אֶת אָבִיו וַדַּאי:","וְכֵן הַבֵּן הַנִּמְצָא בַּשּׁוּק וְהוּא הַנִּקְרָא אֲסוּפִי הֲרֵי הוּא סְפֵק מַמְזֵר שֶׁאֵין אָנוּ יוֹדְעִים מַה הוּא:","פְּנוּיָה שֶׁזִּנְּתָה וְאָמְרָה בֵּן זֶה בֶּן פְּלוֹנִי הוּא. אִם אוֹתוֹ פְּלוֹנִי כָּשֵׁר הֲרֵי הַבֵּן כָּשֵׁר וְאֵינָהּ נֶאֱמֶנֶת לִהְיוֹת זֶה בְּנוֹ שֶׁל פְּלוֹנִי. וְיֵרָאֶה לִי שֶׁחוֹשְׁשִׁין לִדְבָרֶיהָ וְיִהְיֶה הַבֵּן אָסוּר בִּקְרוֹבוֹת אוֹתוֹ פְּלוֹנִי מִסָּפֵק. וְאִם אוֹתוֹ פְּלוֹנִי מַמְזֵר אֵינָהּ נֶאֱמֶנֶת לִהְיוֹת הַבֵּן מַמְזֵר וַדַּאי עַל פִּיהָ כְּמוֹ שֶׁבֵּאַרְנוּ אֶלָּא יִהְיֶה סְפֵק מַמְזֵר:","אֲבָל הָאָב שֶׁהֻחְזַק שֶׁזֶּה בְּנוֹ וְאָמַר בְּנִי זֶה מַמְזֵר הוּא נֶאֱמָן. וְאִם יֵשׁ לַבֵּן בָּנִים אֵינוֹ נֶאֱמָן. שֶׁלֹּא הֶאֱמִינָה אוֹתוֹ תּוֹרָה אֶלָּא עַל בְּנוֹ שֶׁנֶּאֱמַר (דברים כא יז) \"כִּי אֶת הַבְּכֹר בֶּן הַשְּׂנוּאָה יַכִּיר\" יַכִּירֶנּוּ לַאֲחֵרִים:","וּכְשֵׁם שֶׁנֶּאֱמָן לוֹמַר בְּנִי זֶה בְּכוֹר כָּךְ נֶאֱמָן לוֹמַר בְּנִי זֶה מַמְזֵר אוֹ בֶּן גְּרוּשָׁה אוֹ בֶּן חֲלוּצָה. וְכֵן אִם הָיְתָה אִשְׁתּוֹ מְעֻבֶּרֶת נֶאֱמָן לוֹמַר עֻבָּר זֶה אֵינוֹ בְּנִי וּמַמְזֵר הוּא וְיִהְיֶה מַמְזֵר וַדַּאי. וְהָאוֹמֵר עַל עַצְמוֹ שֶׁהוּא מַמְזֵר נֶאֱמָן לֶאֱסֹר עַצְמוֹ בְּבַת יִשְׂרָאֵל. וְאָסוּר בְּמַמְזֶרֶת עַד שֶׁיִּוָּדַע וַדַּאי שֶׁהוּא מַמְזֵר. וּבְנוֹ כָּמוֹהוּ. וְאִם יֵשׁ לוֹ בְּנֵי בָּנִים אֵינוֹ נֶאֱמָן לִפְסל בְּנֵי בָּנָיו וְלֹא יִפְסל אֶלָּא עַצְמוֹ:","אֲרוּסָה שֶׁנִּתְעַבְּרָה וְהִיא בְּבֵית אָבִיהָ הֲרֵי הַוָּלָד בְּחֶזְקַת מַמְזֵר וְאָסוּר בְּבַת יִשְׂרָאֵל וְאָסוּר בְּמַמְזֶרֶת. וְאִם נִבְדְּקָה אִמּוֹ וְאָמְרָה מֵאֲרוּסִי נִתְעַבַּרְתִּי נֶאֱמֶנֶת וְהַוָּלָד כָּשֵׁר. וְאִם הִכְחִישָׁהּ הָאָרוּס וְאָמַר מֵעוֹלָם לֹא בָּאתִי עָלֶיהָ הֲרֵי הַוָּלָד מַמְזֵר שֶׁאֲפִלּוּ הָיָה בְּחֶזְקַת בְּנוֹ וְאָמַר בְּנִי זֶה מַמְזֵר נֶאֱמָן. וְהָאִשָּׁה אֵינָהּ בְּחֶזְקַת זוֹנָה אֶלָּא נֶאֱמֶנֶת לוֹמַר לָאָרוּס נִבְעַלְתִּי וְאֵינָהּ זוֹנָה. וְאִם נִשֵּׂאת לְכֹהֵן לֹא תֵּצֵא וּוְלָדָהּ מִמֶּנּוּ כָּשֵׁר:","הָיוּ הָעָם מְרַנְּנִים אַחֲרֶיהָ וְהִיא אֲרוּסָה עִם אֲרוּסָהּ וְעִם אֲנָשִׁים אֲחֵרִים אַף עַל פִּי שֶׁבָּא עָלֶיהָ אֲרוּסָהּ בְּבֵית חָמִיו הֲרֵי זֶה סְפֵק מַמְזֵר. כְּשֵׁם שֶׁהִפְקִירָה עַצְמָהּ לַאֲרוּסָהּ הִפְקִירָה לַאֲחֵרִים. וְאִם נִבְדְּקָה וְאָמְרָה עֻבָּר זֶה מֵאֲרוּסִי הֲרֵי זֶה כָּשֵׁר כְּמוֹ שֶׁבֵּאַרְנוּ:","אֵשֶׁת אִישׁ שֶׁהָיְתָה מְעֻבֶּרֶת וְאָמְרָה עֻבָּר זֶה אֵינוֹ מִבַּעֲלִי אֵינָהּ נֶאֱמֶנֶת לְפָסְלוֹ. וַהֲרֵי הַבֵּן בְּחֶזְקַת כַּשְׁרוּת. שֶׁלֹּא הֶאֱמִינָה תּוֹרָה אֶלָּא הָאָב. אָמַר הָאָב אֵינוֹ בְּנִי אוֹ שֶׁהָיָה בַּעְלָהּ בִּמְדִינַת הַיָּם הֲרֵי זֶה בְּחֶזְקַת מַמְזֵר. וְאִם אָמְרָה מֵעַכּוּ\"ם וְעֶבֶד נִתְעַבַּרְתִּי הֲרֵי הַוָּלָד כָּשֵׁר. שֶׁאֵין הַבַּעַל יָכוֹל לְהַכְחִישָׁהּ בִּדְבָרֶיהָ. וְאֵין הָעֻבָּר מִשְׁתַּהֶה בִּמְעֵי אִמּוֹ יֶתֶר עַל שְׁנֵים עָשָׂר חֹדֶשׁ:","אֵשֶׁת אִישׁ שֶׁיָּצָא עָלֶיהָ קוֹל שֶׁהָיְתָה זוֹנָה תַּחַת בַּעְלָהּ וְהַכּל מְרַנְּנִין אַחֲרֶיהָ אֵין חוֹשְׁשִׁין לְבָנֶיהָ שֶׁמָּא מַמְזֵרִים הֵם שֶׁרֹב בְּעִילוֹת אֵצֶל הַבַּעַל. וּמֻתָּר לִשָּׂא בִּתָּהּ לְכַתְּחִלָּה. אֲבָל הִיא עַצְמָהּ חוֹשְׁשִׁין לָהּ מִשּׁוּם זוֹנָה. וְאִם הָיְתָה פְּרוּצָה יוֹתֵר מִדַּאי אַף לְבָנֶיהָ חוֹשְׁשִׁין:","דִּין תּוֹרָה שֶׁסְּפֵק מַמְזֵר מֻתָּר לָבוֹא בַּקָּהָל שֶׁנֶּאֱמַר (דברים כג ג) \"לֹא יָבֹא מַמְזֵר בִּקְהַל ה'\" מַמְזֵר וַדַּאי אָסוּר לָבוֹא בַּקָּהָל וְלֹא סָפֵק. אֲבָל חֲכָמִים עָשׂוּ מַעֲלָה בְּיוּחֲסִין וְאָסְרוּ גַּם הַסְּפֵקוֹת לָבוֹא בַּקָּהָל. לְפִיכָךְ מַמְזֵר וַדַּאי מֻתָּר לִשָּׂא מַמְזֶרֶת וַדָּאִית אֲבָל מַמְזֵר סָפֵק אוֹ שְׁתוּקִי אוֹ אֲסוּפִי אָסוּר לִשָּׂא בַּת יִשְׂרָאֵל:","וְאָסוּר לִשָּׂא מַמְזֶרֶת וַאֲפִלּוּ מַמְזֶרֶת מִסָּפֵק אֲסוּרָה לוֹ שֶׁמָּא אֶחָד מֵהֶן אֵינוֹ מַמְזֵר וְהַשֵּׁנִי מַמְזֵר וַדַּאי. וּמַמְזֵר שֶׁל דִּבְרֵיהֶם מֻתָּר לִשָּׂא מַמְזֶרֶת שֶׁל דִּבְרֵיהֶם. וְכֵן שְׁאָר הַסְּפֵקוֹת אֲסוּרִין לִשָּׂא זֶה מִזֶּה:","כֵּיצַד. שְׁתוּקִים וַאֲסוּפִים וּסְפֵק מַמְזֵרִים אֲסוּרִים לָבוֹא זֶה עִם זֶה וְאִם נָשְׂאוּ לֹא יְקַיְּמוּ אֶלָּא יוֹצִיאוּ בְּגֵט וְהַוָּלָד סָפֵק כַּאֲבוֹתָיו. וְאֵין לִסְפֵקוֹת אֵלּוּ תַּקָּנָה אֶלָּא שֶׁיִּשְּׂאוּ מִן הַגֵּרִים וְהַוָּלָד הוֹלֵךְ אַחַר הַפָּגוּם:","כֵּיצַד. שְׁתוּקִי אוֹ אֲסוּפִי שֶׁנָּשָׂא גִּיֹּרֶת אוֹ מְשֻׁחְרֶרֶת אוֹ גֵּר וּמְשֻׁחְרָר שֶׁנָּשָׂא שְׁתוּקִית אוֹ אֲסוּפִית. הַוָּלָד שְׁתוּקִי אוֹ אֲסוּפִי:","הָאֲסוּפִי שֶׁנִּמְצָא בְּעִיר שֶׁיֵּשׁ בָּהּ עַכּוּ\"ם בֵּין שֶׁהָיָה רֹב עַכּוּ\"ם אוֹ רֹב יִשְׂרָאֵל הֲרֵי זֶה סְפֵק עַכּוּ\"ם לְעִנְיַן יוּחֲסִין. קִדֵּשׁ אִשָּׁה צְרִיכָה גֵּט מִסָּפֵק. מִי שֶׁהֲרָגוֹ לֹא הָיָה נֶהֱרַג עָלָיו:","הִטְבִּילוּהוּ בֵּית דִּין לְשֵׁם גֵּרוּת אוֹ שֶׁטָּבַל מִשֶּׁהִגְדִּיל הֲרֵי הוּא כִּשְׁאָר אֲסוּפִים הַנִּמְצָאִים בְּעָרֵי יִשְׂרָאֵל. הָיָה רֹב הָעִיר עַכּוּ\"ם מֻתָּר לְהַאֲכִילוֹ נְבֵלוֹת. הָיָה רֻבָּן יִשְׂרָאֵל מַחְזִירִין לוֹ אֲבֵדָתוֹ כְּיִשְׂרָאֵל. מֶחֱצָה עַל מֶחֱצָה מִצְוָה לְהַחֲיוֹתוֹ כְּיִשְׂרָאֵל. וּמְפַקְּחִין עָלָיו אֶת הַגַּל בְּשַׁבָּת וַהֲרֵי הוּא לְעִנְיַן נְזָקִין כְּכָל סְפֵק מָמוֹן הַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה:","יֵרָאֶה לִי שֶׁכָּל מְדִינָה שֶׁיֵּשׁ בָּהּ שִׁפְחָה אוֹ עַכּוּ\"ם הָרְאוּיָה לֵילֵד הוֹאִיל וְהָאֲסוּפִי הַנִּמְצָא שָׁם סְפֵק עַכּוּ\"ם אוֹ סְפֵק עֶבֶד כְּשֶׁיִּשָּׂא הַגִּיֹּרֶת כְּמוֹ שֶׁבֵּאַרְנוּ הֲרֵי זוֹ סְפֵק אֵשֶׁת אִישׁ וְהַבָּא עָלֶיהָ פָּטוּר שֶׁאֵין הוֹרְגִין עַל סָפֵק. וְכֵן יֵרָאֶה לִי שֶׁהַשְּׁתוּקִי שֶׁנָּשָׂא אִשָּׁה שֶׁאֶפְשָׁר שֶׁהִיא עֶרְוָה עָלָיו וַהֲרֵי הִיא סְפֵק אֵשֶׁת אִישׁ שֶׁאֵין קִדּוּשִׁין תּוֹפְסִין בַּעֲרָיוֹת:","וְאֵי זוֹ הִיא הָאִשָּׁה שֶׁאֶפְשָׁר שֶׁתִּהְיֶה עֶרְוָה עָלָיו. כָּל אִשָּׁה שֶׁהָיָה אָבִיהָ אוֹ אָחִיהָ קַיָּם כְּשֶׁנִּתְעַבְּרָה בּוֹ אִמּוֹ. וְכָל אִשָּׁה שֶׁנִּתְגָּרְשָׁה אוֹ נִתְאַלְמְנָה שֶׁמָּא אֵשֶׁת אָבִיו הִיא אוֹ אֵשֶׁת אֲחִי אָבִיו:","וּמִנַּיִן אֲנִי אוֹמֵר שֶׁאֵין הַשְּׁתוּקִי וְהָאֲסוּפִי אָסוּר בְּכָל אִשָּׁה שֶׁאֶפְשָׁר שֶׁתִּהְיֶה עֶרְוָה עָלָיו. שֶׁהֲרֵי הַכָּשֵׁר שֶׁנִּבְדְּקָה אִמּוֹ אֵינוֹ אָסוּר בְּכָל אִשָּׁה שֶׁאֶפְשָׁר שֶׁתִּהְיֶה עֶרְוָה עָלָיו. וַהֲרֵי נֶאֱמַר בַּתּוֹרָה (ויקרא יט כט) \"אַל תְּחַלֵּל אֶת בִּתְּךָ לְהַזְנוֹתָהּ\". וְאָמְרוּ חֲכָמִים שֶׁאִם יַעֲשֶׂה זֶה נִמְצָא אָב נוֹשֵׂא בִּתּוֹ וְאָח נוֹשֵׂא אֲחוֹתוֹ. וְאִלּוּ הָיָה הַדִּין שֶׁכָּל מִי שֶׁאֵינוֹ יוֹדֵעַ אָבִיו בְּוַדַּאי אָסוּר בְּכָל אִשָּׁה שֶׁאֶפְשָׁר שֶׁתִּהְיֶה עֶרְוָה עָלָיו. לֹא הָיִינוּ בָּאִים לַמִּדָּה הַזֹּאת לְעוֹלָם וְלֹא תִּהְיֶה הָאָרֶץ מְלֵאָה זִמָּה. הָא לָמַדְתָּ שֶׁאֵין אוֹסְרִין עֲרָיוֹת וּמַחֲזִיקִין אוֹתָן בִּשְׁאֵר בָּשָׂר בְּסָפֵק עַד שֶׁיִּוָּדַע בְּוַדַּאי שֶׁזּוֹ עֶרְוָה עָלָיו. שֶׁאִם אַתָּה אוֹמֵר כֵּן כָּל הַיְתוֹמִים שֶׁבָּעוֹלָם שֶׁלֹּא הִכִּירוּ אֲבוֹתֵיהֶם הָיוּ אֲסוּרִין לְהִנָּשֵׂא בְּכָל מָקוֹם שֶׁמָּא יִפְגְּעוּ בְּעֶרְוָה:","הַוָּלָד שֶׁהָיָה מֻשְׁלָךְ בַּדֶּרֶךְ וּבָא אֶחָד וְאָמַר בְּנִי הוּא וַאֲנִי הִשְׁלַכְתִּיו נֶאֱמָן. וְכֵן אִמּוֹ נֶאֱמֶנֶת. נֶאֱסַף מִן הַשּׁוּק וּבָאוּ אָבִיו וְאִמּוֹ אַחַר כֵּן וְאָמְרוּ בְּנֵנוּ הוּא אֵין נֶאֱמָנִין הוֹאִיל וְיָצָא עָלָיו שֵׁם אֲסוּפִי. וּבִשְׁנֵי רְעָבוֹן נֶאֱמָנִין שֶׁמִּפְּנֵי רָעָב הִשְׁלִיכוּהוּ וְהֵן רוֹצִין שֶׁיָּזוּנוּ אוֹתוֹ אֲחֵרִים וּלְפִיכָךְ שָׁתְקוּ עַד שֶׁנֶּאֱסַף:","נִמְצָא הַוָּלָד מָהוּל אוֹ שֶׁהֻחְתַּל אוֹ שֶׁהֻמְלַח אוֹ שֶׁהָיָה הַכֹּחַל בְּעֵינָיו אוֹ הַקְּמֵעִין בְּצַוָּארוֹ אוֹ שֶׁנִּמְצָא תַּחַת אִילָן מְסֻבָּךְ שֶׁאֵין חַיָּה נִכְנֶסֶת לוֹ וְהָיָה סָמוּךְ לָעִיר אוֹ שֶׁנִּמְצָא בְּבֵית הַכְּנֶסֶת הַסָּמוּךְ לִרְשׁוּת הָרַבִּים אוֹ בְּצִדֵּי רְשׁוּת הָרַבִּים אֵין כָּאן מִשּׁוּם אֲסוּפִי. מֵאַחֵר שֶׁהֵן מְשַׁמְּרִין אוֹתוֹ שֶׁלֹּא יָמוּת בְּחֶזְקַת כָּשֵׁר הוּא. אֲבָל אִם נִמְצָא מֻשְׁלָךְ בְּאֶמְצַע הַדֶּרֶךְ אוֹ רָחוֹק מִן הָעִיר אֲפִלּוּ תַּחַת אִילָן אוֹ בְּבֵית הַכְּנֶסֶת אוֹ שֶׁנִּמְצָא תָּלוּי בָּאִילָן מָקוֹם שֶׁחַיָּה מַגַּעַת לוֹ הֲרֵי זֶה אֲסוּפִי:","נֶאֱמֶנֶת חַיָּה לוֹמַר זֶה הַבֵּן כֹּהֵן הוּא אוֹ לֵוִי אוֹ נָתִין אוֹ מַמְזֵר מִפְּנֵי שֶׁלֹּא הֻחְזַק וְאֵין אָנוּ יוֹדְעִין יִחוּסָן. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהֻחְזְקָה בְּנֶאֱמָנוּת וְלֹא עִרְעֵר עָלֶיהָ אָדָם. אֲבָל אִם עִרְעֵר עָלֶיהָ אֲפִלּוּ אֶחָד וְאָמַר בְּשֶׁקֶר מְעִידָה אֵינָהּ נֶאֱמֶנֶת וַהֲרֵי הַבֵּן בְּחֶזְקַת כָּשֵׁר וְאֵין לוֹ יִחוּס:","דָּבָר בָּרוּר שֶׁהַשְּׁתוּקִי אָסוּר לִשָּׂא שְׁתוּקִית. וַאֲסוּפִי אָסוּר בַּאֲסוּפִית מִפְּנֵי שֶׁהֵן סְפֵקוֹת. אֲבָל מַמְזֵרִים וַדָּאִים וּנְתִינִים מֻתָּרִים לָבוֹא זֶה בָּזֶה וְהַוָּלָד מַמְזֵר. וּשְׁתוּקִי וַאֲסוּפִי מֻתָּרִין בִּנְתִינִים וּבִשְׁאָר הַגֵּרִים וְהַוָּלָד סָפֵק:"],"Mishneh Torah, Forbidden Intercourse 6":["דַם הַנִּדָּה וְדַם הַזָּבָה וְדַם הַקֹּשִׁי וְדַם יוֹלֶדֶת וְדַם טֹהַר שֶׁל יוֹלֶדֶת כֻּלּוֹ דָּם אֶחָד הוּא וּמִן הַמָּקוֹר הוּא בָּא. וּמַעֲיָן אֶחָד הוּא. וּבִזְמַנִּים בִּלְבַד הוּא שֶׁיִּשְׁתַּנֶּה דִּינוֹ וְתִהְיֶה רוֹאָה דָּם זוֹ טְהוֹרָה. וְזוֹ נִדָּה. וְזוֹ זָבָה:","כֵּיצַד. כְּשֶׁתִּרְאֶה הָאִשָּׁה דָּם תְּחִלָּה אוֹ כְּשֶׁתִּרְאֶה בִּשְׁעַת וֶסְתָּהּ וְהוּא הָעֵת שֶׁקָּבְעָה לְנִדָּתָהּ הֲרֵי זוֹ נִדָּה כָּל שִׁבְעַת הַיָּמִים. בֵּין רָאֲתָה כָּל שִׁבְעָה בֵּין שֶׁלֹּא רָאֲתָה אֶלָּא טִפָּה רִאשׁוֹנָה בִּלְבַד. רָאֲתָה דָּם בַּיּוֹם הַשְּׁמִינִי הֲרֵי זֶה דַּם זִיבָה מִפְּנֵי שֶׁהוּא בְּלֹא עֵת נִדָּתָהּ:","וְכֵן כָּל דָּם שֶׁתִּרְאֶה בְּתוֹךְ הַיָּמִים שֶׁבֵּין וֶסֶת נִדָּה לְוֶסֶת נִדָּה הֲרֵי הוּא דַּם זִיבָה. וַהֲלָכָה לְמשֶׁה מִסִּינַי שֶׁאֵין בֵּין זְמַן נִדָּה לִזְמַן נִדָּה אֶלָּא אַחַד עָשָׂר יוֹם בִּלְבַד:","כָּל שִׁבְעַת הַיָּמִים שֶׁנִּקְבְּעָה לָהּ וֶסֶת בִּתְחִלָּתָן הֵן הַנִּקְרָאִין יְמֵי נִדָּתָהּ. בֵּין רָאֲתָה בָּהֶן דָּם בֵּין לֹא רָאֲתָה בָּהֶן דָּם. וּמִפְּנֵי מָה נִקְרָאִין יְמֵי נִדָּה מִפְּנֵי שֶׁהֵן רְאוּיִין לְנִדָּה. וְכָל דָּם שֶׁתִּרְאֶה בָּהֶם דַּם נִדָּה יֵחָשֵׁב:","וְכָל אַחַד עָשָׂר יוֹם שֶׁאַחַר הַשִּׁבְעָה הֵן הַנִּקְרָאִין יְמֵי זִיבָתָהּ. בֵּין רָאֲתָה בָּהֶן דָּם בֵּין לֹא רָאֲתָה. וְלָמָּה נִקְרָאִין יְמֵי זִיבָה מִפְּנֵי שֶׁהֵן רְאוּיִין לְזִיבָה. וְכָל דָּם שֶׁתִּרְאֶה בָּהֶן דַּם זִיבָה יֵחָשֵׁב. וְהִזָּהֵר בִּשְׁנֵי שֵׁמוֹת אֵלּוּ שֶׁהֵן יְמֵי נִדָּתָהּ וִימֵי זִיבָתָהּ:","כָּל יְמֵי הָאִשָּׁה מִיּוֹם שֶׁיִּקָּבַע לָהּ וֶסֶת עַד שֶׁתָּמוּת אוֹ עַד שֶׁיֵּעָקֵר הַוֶּסֶת לְיוֹם אַחֵר תִּסְפֹּר לְעוֹלָם שִׁבְעָה מִתְּחִלַּת יוֹם הַוֶּסֶת וְאַחֲרֵיהֶן אַחַד עָשָׂר [וְאַחֲרֵיהֶן] שִׁבְעָה וְאַחֲרֵיהֶן אַחַד עָשָׂר. וְתִזָּהֵר בַּמִּנְיָן כְּדֵי שֶׁתֵּדַע בְּעֵת שֶׁתִּרְאֶה דָּם אִם בִּימֵי נִדָּה רָאֲתָה אוֹ בִּימֵי זִיבָה. שֶׁכָּל יָמֶיהָ שֶׁל אִשָּׁה כָּךְ הֵן שִׁבְעָה יְמֵי נִדָּה וְאַחַד עָשָׂר יְמֵי זִיבָה. אֶלָּא אִם כֵּן הִפְסִיקָה הַלֵּדָה כְּמוֹ שֶׁיִּתְבָּאֵר:","אִשָּׁה שֶׁרָאֲתָה דָּם בִּימֵי זִיבָתָהּ יוֹם אֶחָד בִּלְבַד אוֹ שְׁנֵי יָמִים זֶה אַחַר זֶה נִקְרֵאת זָבָה קְטַנָּה וְנִקְרֵאת שׁוֹמֶרֶת יוֹם כְּנֶגֶד יוֹם. וְאִם רָאֲתָה שְׁלֹשָׁה יָמִים זֶה אַחַר זֶה הֲרֵי זוֹ זָבָה גְּמוּרָה וְהִיא הַנִּקְרֵאת זָבָה גְּדוֹלָה וְנִקְרֵאת זָבָה סְתָם שֶׁנֶּאֱמַר (ויקרא טו כה) \"וְאִשָּׁה כִּי יָזוּב זוֹב דָּמָהּ יָמִים רַבִּים\" מִעוּט יָמִים שְׁנַיִם רַבִּים שְׁלֹשָׁה:","אֵין בֵּין זָבָה גְּדוֹלָה לְזָבָה קְטַנָּה אֶלָּא סְפִירַת שִׁבְעָה וַהֲבָאַת קָרְבָּן. שֶׁזָּבָה גְּדוֹלָה צְרִיכָה לִסְפֹּר שִׁבְעָה יָמִים נְקִיִּים וְזָבָה קְטַנָּה אֵינָהּ סוֹפֶרֶת אֶלָּא יוֹם אֶחָד בִּלְבַד. וְזָבָה גְּדוֹלָה מְבִיאָה קָרְבָּן כְּשֶׁתִּטְהַר [וְזָבָה קְטַנָּה אֵינָהּ מְבִיאָה קָרְבָּן כְּשֶׁתִּטְהַר]. אֲבָל לְעִנְיַן טֻמְאָה וְאִסּוּר בִּיאָה שְׁתֵּיהֶן שָׁווֹת:","כֵּיצַד. רָאֲתָה דָּם בִּימֵי זִיבָתָהּ. בֵּין שֶׁרָאֲתָה בִּתְחִלַּת הַלַּיְלָה בֵּין שֶׁרָאֲתָה בְּסוֹף הַיּוֹם. הֲרֵי אוֹתוֹ הַיּוֹם כֻּלּוֹ טָמֵא וּכְאִלּוּ לֹא פָּסַק הַדָּם מֵעֵת שֶׁרָאֲתָה עַד שֶׁשָּׁקְעָה הַחַמָּה וּמְשַׁמֶּרֶת כָּל הַלַּיְלָה. וְאִם לֹא רָאֲתָה כְּלוּם בַּלַּיְלָה מַשְׁכֶּמֶת לְמָחָר וְטוֹבֶלֶת אַחַר שֶׁתָּנֵץ הַחַמָּה וּמְשַׁמֶּרֶת כָּל הַיּוֹם. אִם לֹא רָאֲתָה כְּלוּם הֲרֵי זֶה יוֹם אֶחָד טָהוֹר כְּנֶגֶד הַיּוֹם הַטָּמֵא וַהֲרֵי הִיא מֻתֶּרֶת לְבַעְלָהּ לָעֶרֶב:","רָאֲתָה דָּם גַּם בַּיּוֹם הַשֵּׁנִי בֵּין בְּלֵילוֹ בֵּין בְּיוֹמוֹ אַחַר שֶׁטָּבְלָה הֲרֵי הַיּוֹם הַשֵּׁנִי טָמֵא וּמְשַׁמֶּרֶת כָּל לֵיל שְׁלִישִׁי. אִם לֹא רָאֲתָה מַשְׁכֶּמֶת לְמָחָר וְטוֹבֶלֶת אַחַר שֶׁתָּנֵץ הַחַמָּה וּמְשַׁמֶּרֶת כָּל הַיּוֹם. אִם לֹא רָאֲתָה כְּלוּם הֲרֵי זֶה יוֹם אֶחָד טָהוֹר כְּנֶגֶד שְׁנֵי יָמִים הַטְּמֵאִים וּמֻתֶּרֶת לְבַעְלָהּ לָעֶרֶב:","רָאֲתָה דָּם גַּם בַּשְּׁלִישִׁי בֵּין בְּיוֹמוֹ בֵּין בְּלֵילוֹ הֲרֵי זוֹ זָבָה גְּדוֹלָה וּצְרִיכָה לִסְפֹּר שִׁבְעָה יָמִים טְהוֹרִים בְּלֹא דָּם שֶׁנֶּאֱמַר (ויקרא טו כח) \"וְסָפְרָה לָּהּ שִׁבְעַת יָמִים\" וְגוֹ' וְטוֹבֶלֶת בַּיּוֹם הַשְּׁבִיעִי אַחַר הָנֵץ הַחַמָּה וַהֲרֵי הִיא מֻתֶּרֶת לְבַעְלָהּ לָעֶרֶב. וּבַיּוֹם הַשְּׁמִינִי מְבִיאָה קָרְבָּנָהּ שְׁנֵי תּוֹרִים אוֹ שְׁנֵי בְּנֵי יוֹנָה:","זָבָה קְטַנָּה שֶׁטָּבְלָה בַּלַּיְלָה שֶׁל יוֹם הַשִּׁמּוּר אוֹ זָבָה גְּדוֹלָה שֶׁטָּבְלָה בְּלֵיל שְׁבִיעִי כְּאִלּוּ לֹא טָבְלָה וַהֲרֵי הִיא כְּנִדָּה שֶׁטָּבְלָה בְּתוֹךְ שִׁבְעָה:","הַבָּא עַל זָבָה גְּדוֹלָה בְּיוֹם שְׁבִיעִי שֶׁל סְפִירָה אַחַר שֶׁטָּבְלָה אוֹ עַל זָבָה קְטַנָּה בְּיוֹם הַשִּׁמּוּר אַחַר שֶׁטָּבְלָה פָּטוּר מִן הַכָּרֵת. כֵּיוָן שֶׁטָּבְלָה בַּזְּמַן הָרָאוּי לִטְבִילָתָהּ טְהוֹרָה. וּלְאִשָּׁה זוֹ יִהְיֶה לָהּ תַּרְבּוּת רָעָה שֶׁהֲרֵי בְּעִילָתָהּ וּמַגָּעָהּ תְּלוּיִין:","כֵּיצַד הֵן תְּלוּיִין. אִם נִשְׁלַם הַיּוֹם אַחַר הַטְּבִילָה וְלֹא רָאֲתָה דָּם הֲרֵי כָּל שֶׁנָּגְעָה בּוֹ אַחַר טְבִילָתָהּ טָהוֹר וּבְעִילָתָהּ אַחַר הַטְּבִילָה אֵין חַיָּבִין עָלֶיהָ כְּלוּם. וְאִם רָאֲתָה דָּם בְּיוֹם זֶה אַחַר שֶׁטָּבְלָה נִמְצֵאת זָבָה לְמַפְרֵעַ וְכָל שֶׁנָּגְעָה בּוֹ לְמַפְרֵעַ טָמֵא. וְהִיא וּבוֹעֲלָהּ חַיָּבִין בְּקָרְבָּן. וּלְפִיכָךְ הִיא אֲסוּרָה לְבַעְלָהּ עַד לָעֶרֶב שֶׁלֹּא תָּבִיא עַצְמָהּ לִידֵי סָפֵק:","זָבָה שֶׁסָּפְרָה שֵׁשֶׁת יָמִים נְקִיִּים. וּבַשְּׁבִיעִי רָאֲתָה דָּם אֲפִלּוּ סָמוּךְ לִשְׁקִיעַת הַחַמָּה סוֹתֶרֶת הַכּל וְחוֹזֶרֶת לִמְנוֹת מֵאַחַר הַיּוֹם הַטָּמֵא שִׁבְעָה יָמִים נְקִיִּים:","פָּלְטָה שִׁכְבַת זֶרַע בְּתוֹךְ יְמֵי הַסְּפִירָה סוֹתֶרֶת יוֹם אֶחָד מִפְּנֵי שֶׁהוּא כְּזָב שֶׁרָאָה קֶרִי שֶׁסּוֹתֵר יוֹם אֶחָד. רָאֲתָה דָּם בַּעֲשִׂירִי מִימֵי זִיבָתָהּ וּבְאַחַד עָשָׂר וּבִשְׁתֵּים עָשָׂר אַף עַל פִּי שֶׁרָאֲתָה שְׁלֹשָׁה יָמִים זֶה אַחַר זֶה אֵינָהּ זָבָה גְּדוֹלָה. אֶלָּא יָצָאת מִזִּיבוּת קְטַנָּה לְנִדָּה שֶׁיּוֹם שְׁנֵים עָשָׂר מַתְחֶלֶת נִדָּתָהּ וְהָרוֹאָה בִּימֵי נִדָּתָהּ אֵינָהּ זָבָה כְּמוֹ שֶׁבֵּאַרְנוּ:","וּמַה הוּא זֶה שֶׁכָּתוּב בַּתּוֹרָה (ויקרא טו כה) \"אוֹ כִּי תָזוּב עַל נִדָּתָהּ\". שֶׁאִם רָאֲתָה שְׁלֹשָׁה יָמִים סָמוּךְ לְנִדָּתָהּ הֲרֵי זוֹ זָבָה. כְּגוֹן שֶׁרָאֲתָה בַּשְּׁמִינִי לְנִדָּתָהּ וּבַתְּשִׁיעִי וּבָעֲשִׂירִי שֶׁהֵן רִאשׁוֹן וְשֵׁנִי וּשְׁלִישִׁי מֵהָאַחַד עָשָׂר יוֹם שֶׁהֵן יְמֵי זִיבָתָהּ. רָאֲתָה דָּם בַּי\"א מִימֵי זִיבָתָהּ וְטָבְלָה לָעֶרֶב שֶׁהוּא לֵיל י\"ב וְשִׁמְּשָׁה מִטָּתָהּ אַף עַל פִּי שֶׁהִיא טְמֵאָה וּבוֹעֲלָהּ טָמֵא וְעוֹשִׂין מִשְׁכָּב וּמוֹשָׁב אֵינָם חַיָּבִים כָּרֵת מִפְּנֵי שֶׁאֵין יוֹם י\"ב מִצְטָרֵף לְיוֹם י\"א לַעֲשׂוֹת זָבָה. הוֹעִילָה לָהּ טְבִילַת לֵיל זֶה לְהַצִּילָהּ מִן הַקָּרְבָּן:","טָבְלָה בְּיוֹם י\"ב אַחַר שֶׁתָּנֵץ הַחַמָּה הֲרֵי זוֹ אֲסוּרָה לְבַעְלָהּ עַד לָעֶרֶב כְּדִין כָּל זָבָה קְטַנָּה. וְאִם עָבַר וּבְעָלָהּ שְׁנֵיהֶן פְּטוּרִין מִכְּלוּם. וַאֲפִלּוּ רָאֲתָה דָּם אַחַר שֶׁבָּא עָלֶיהָ בְּיוֹם י\"ב אֵין בְּכָךְ כְּלוּם שֶׁזֶּה דַּם נִדָּה הוּא וְאֵינוֹ מִצְטָרֵף לַיּוֹם שֶׁלְּפָנָיו:","רָאֲתָה דָּם בְּסוֹף שְׁבִיעִי לְנִדָּתָהּ בֵּין הַשְּׁמָשׁוֹת וְרָאֲתָה בַּתְּשִׁיעִי וּבַעֲשִׂירִי הֲרֵי זוֹ סְפֵק זָבָה. שֶׁמָּא רְאִיָּה רִאשׁוֹנָה בְּלֵיל שְׁמִינִי הָיְתָה וְנִמְצֵאת שֶׁרָאֲתָה שְׁלֹשָׁה יָמִים זֶה אַחַר זֶה מִתְּחִלַּת יְמֵי זִיבָתָהּ. וְכֵן אִם רָאֲתָה דָּם בַּתְּשִׁיעִי וּבַעֲשִׂירִי מִימֵי זִיבָתָהּ וְרָאֲתָה בְּסוֹף יוֹם אַחַד עָשָׂר בֵּין הַשְּׁמָשׁוֹת הֲרֵי זוֹ סְפֵק זָבָה. שֶׁמָּא רְאִיָּה אַחֲרוֹנָה בְּיוֹם אַחַד עָשָׂר הָיְתָה וַהֲרֵי רָאֲתָה שְׁלֹשָׁה יָמִים זֶה אַחַר זֶה בִּימֵי זִיבָתָהּ:","נִדָּה שֶׁבָּדְקָה עַצְמָהּ בְּתוֹךְ יְמֵי נִדָּתָהּ וּמָצְאָה שֶׁפָּסַק הַדָּם וַאֲפִלּוּ פָּסַק בְּשֵׁנִי לְנִדָּתָהּ וְשָׁגְגָה אוֹ הֵזִידָה וְלֹא בָּדְקָה עַד לְאַחַר נִדָּתָהּ יָמִים רַבִּים וּכְשֶׁבָּדְקָה מָצְאָה טֻמְאָה. אֵין אוֹמְרִים שֶׁמָּא כָּל אוֹתָן הַיָּמִים הָיְתָה טְמֵאָה וְתִהְיֶה זָבָה אֶלָּא כָּל אוֹתָן הַיָּמִים שֶׁלֹּא בָּדְקָה בְּחֶזְקַת טָהֳרָה. בָּדְקָה עַצְמָהּ וּמָצְאָה טְמֵאָה. אֲפִלּוּ בָּדְקָה בַּשְּׁבִיעִי לְנִדָּתָהּ וּבֵין הַשְּׁמָשׁוֹת לֹא בָּדְקָה עַצְמָהּ כְּדֵי לִפְרשׁ מִטֻּמְאַת נִדָּה אֶלָּא הִמְתִּינָה יָמִים וְאַחַר כָּךְ בָּדְקָה וּמָצָאת טְהוֹרָה הֲרֵי זוֹ סְפֵק זָבָה. וְאִם מָצְאָה טְמֵאָה הֲרֵי זוֹ זָבָה וַדָּאִית שֶׁכֵּיוָן שֶׁבַּתְּחִלָּה מָצְאָה טְמֵאָה וּלְבַסּוֹף טְמֵאָה הֲרֵי זוֹ בְּחֶזְקַת שֶׁלֹּא פָּסַק. וְיוֹם רִאשׁוֹן שֶׁל נִדָּה אַף עַל פִּי שֶׁמָּצְאָה בּוֹ טְהוֹרָה הֲרֵי זוֹ כְּמִי שֶׁמָּצְאָה טְמֵאָה. שֶׁיּוֹם רִאשׁוֹן כֻּלּוֹ הֻחְזַק הַמַּעֲיָן פָּתוּחַ:","זָבָה שֶׁבָּדְקָה עַצְמָהּ בָּרִאשׁוֹן מִימֵי הַסְּפִירָה וּמָצְאָה טָהוֹר וְלֹא בָּדְקָה עַד יוֹם שְׁבִיעִי וּמָצְאָה טָהוֹר הֲרֵי זוֹ בְּחֶזְקַת טָהֳרָה וּכְאִלּוּ בָּדְקָה כָּל שִׁבְעָה וּמָצְאָה טָהוֹר:","וְכֵן אִם בָּדְקָה בְּיוֹם רִאשׁוֹן מִימֵי הַסְּפִירָה וּמָצְאָה טָהוֹר וּבַיּוֹם הַשְּׁמִינִי וּמָצְאָה טָהוֹר הֲרֵי זוֹ בְּחֶזְקַת טָהֳרָה. בָּדְקָה בְּיוֹם שְׁלִישִׁי לְזִיבָתָהּ וּמָצְאָה שֶׁפָּסַק הַדָּם וְלֹא בָּדְקָה בְּיוֹם רִאשׁוֹן מִימֵי הַסְּפִירָה וּבַשְּׁבִיעִי בָּדְקָה וּמָצְאָה טָהוֹר הֲרֵי זוֹ בְּחֶזְקַת טָהֳרָה. וְהוּא הַדִּין לְזָב בְּכָל אֵלּוּ הַבְּדִיקוֹת שֶׁהוּא טָהוֹר וְעָלוּ לוֹ יְמֵי סְפִירָה:","כָּל אִשָּׁה שֶׁהִיא סְפֵק נִדָּה סְפֵק זָבָה צְרִיכָה לֵישֵׁב שִׁבְעַת יָמִים נְקִיִּים מִסָּפֵק וְטוֹבֶלֶת בְּלֵיל שְׁמִינִי וְאַחַר כָּךְ תִּהְיֶה מֻתֶּרֶת לְבַעְלָהּ. וּמְבִיאָה קָרְבַּן זָבָה וְאֵינוֹ נֶאֱכָל כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ:"],"Mishneh Torah, Foreign Worship and Customs of the Nations 6":["הָעוֹשֶׂה אוֹב אוֹ יִדְּעֹנִי בִּרְצוֹנוֹ בְּזָדוֹן חַיָּב כָּרֵת וְאִם הָיוּ שָׁם עֵדִים וְהַתְרָאָה נִסְקָל. הָיָה שׁוֹגֵג מֵבִיא חַטָּאת קְבוּעָה. כֵּיצַד הוּא מַעֲשֵׂה הָאוֹב. זֶה שֶׁהוּא עוֹמֵד וּמַקְטִיר קְטֹרֶת יְדוּעָה וְאוֹחֵז שַׁרְבִיט שֶׁל הֲדַס בְּיָדוֹ וּמְנִיפוֹ וְהוּא מְדַבֵּר בַּלָּאט בִּדְבָרִים יְדוּעִים אֶצְלָם עַד שֶׁיִּשְׁמַע הַשּׁוֹאֵל כְּאִלּוּ אֶחָד מְדַבֵּר עִמּוֹ וּמְשִׁיבוֹ עַל מַה שֶּׁהוּא שׁוֹאֵל בִּדְבָרִים מִתַּחַת הָאָרֶץ בְּקוֹל נָמוּךְ עַד מְאֹד וּכְאִלּוּ אֵינוֹ נִכָּר לָאֹזֶן אֶלָּא בְּמַחֲשָׁבָה מַרְגִּישׁ בּוֹ. וְכֵן הַלּוֹקֵחַ גֻּלְגּלֶת הַמֵּת וּמַקְטִיר לָהּ וּמְנַחֵשׁ בָּהּ עַד שֶׁיִּשָּׁמַע כְּאִלּוּ קוֹל יוֹצֵא מִתַּחַת שֶׁחְיוֹ שָׁפָל עַד מְאֹד וּמְשִׁיבוֹ. כָּל אֵלּוּ מַעֲשֵׂה אוֹב הֵן וְהָעוֹשֶׂה אֶחָד מֵהֶן נִסְקָל:","כֵּיצַד מַעֲשֵׂה הַיִּדְּעֹנִי. מֵנִיחַ עֶצֶם עוֹף שֶׁשְּׁמוֹ יָדוּעַ בְּפִיו וּמַקְטִיר וְעוֹשֶׂה מַעֲשִׂים אֲחֵרִים עַד שֶׁיִּפּל כְּנִכְפֶּה וִידַבֵּר בְּפִיו דְּבָרִים שֶׁעֲתִידִים לִהְיוֹת. וְכָל אֵלּוּ מִינֵי עֲבוֹדַת כּוֹכָבִים הֵן וְאַזְהָרָה שֶׁלָּהֶן מִנַּיִן שֶׁנֶּאֱמַר (ויקרא יט לא) \"אַל תִּפְנוּ אֶל הָאֹבֹת\" וְגוֹ':","הַנּוֹתֵן מִזַּרְעוֹ לַמּלֶךְ בִּרְצוֹנוֹ וּבְזָדוֹן חַיָּב כָּרֵת. בְּשׁוֹגֵג מֵבִיא חַטָּאת קְבוּעָה. וְאִם עָשָׂה בְּעֵדִים וְהַתְרָאָה נִסְקָל שֶׁנֶּאֱמַר (ויקרא כ ב) \"אֲשֶׁר יִתֵּן מִזַּרְעוֹ לַמּלֶךְ מוֹת יוּמָת\" וְגוֹ'. וְאַזְהָרָה שֶׁלּוֹ מִנַּיִן שֶׁנֶּאֱמַר (ויקרא יח כא) \"וּמִזַּרְעֲךָ לֹא תִתֵּן לְהַעֲבִיר לַמּלֶךְ\" וּלְהַלָּן הוּא אוֹמֵר (דברים יח י) \"לֹא יִמָּצֵא בְךָ מַעֲבִיר בְּנוֹ וּבִתּוֹ בָּאֵשׁ\". כֵּיצַד הָיוּ עוֹשִׂים. מַדְלִיק אֵשׁ גְּדוֹלָה וְלוֹקֵחַ מִקְצָת זַרְעוֹ וּמוֹסְרוֹ לְכֹהֲנֵיהֶם עוֹבְדֵי הָאֵשׁ. וְאוֹתָן הַכֹּהֲנִים נוֹתְנִין הַבֵּן לְאָבִיו אַחַר שֶׁנִּמְסַר בְּיָדָן לְהַעֲבִירוֹ בָּאֵשׁ בִּרְשׁוּתוֹ וַאֲבִי הַבֵּן הוּא שֶׁמַּעֲבִיר בְּנוֹ עַל הָאֵשׁ בִּרְשׁוּת הַכֹּהֲנִים וּמַעֲבִירוֹ בְּרַגְלָיו מִצַּד זֶה לְצַד אַחֵר בְּתוֹךְ הַשַּׁלְהֶבֶת. לֹא שֶׁהוּא שׂוֹרְפוֹ לַמּלֶךְ כְּדֶרֶךְ שֶׁשּׂוֹרְפִין בְּנֵיהֶם וּבְנוֹתֵיהֶם לַעֲבוֹדַת כּוֹכָבִים אַחֶרֶת אֶלָּא בְּהַעֲבָרָה בִּלְבַד הָיְתָה עֲבוֹדָה זוֹ שֶׁשְּׁמָהּ מלֶךְ. לְפִיכָךְ הָעוֹשֶׂה עֲבוֹדָה זוֹ לַעֲבוֹדַת כּוֹכָבִים אַחֶרֶת חוּץ מִמּלֶךְ פָּטוּר:","אֵינוֹ חַיָּב כָּרֵת אוֹ סְקִילָה עַד שֶׁיִּמְסֹר בְּנוֹ לַמּלֶךְ וְיַעֲבִירוֹ בְּרַגְלָיו בָּאֵשׁ דֶּרֶךְ הַעֲבָרָה. מָסַר וְלֹא הֶעֱבִיר הֶעֱבִיר וְלֹא מָסַר. אוֹ שֶׁמָּסַר וְהֶעֱבִיר שֶׁלֹּא בְּדֶרֶךְ הַעֲבָרָה פָּטוּר. וְאֵינוֹ חַיָּב עַד שֶׁיִּמְסֹר מִקְצָת זַרְעוֹ וְיָנִיחַ מִקְצָת שֶׁנֶּאֱמַר (ויקרא כ ג) \"כִּי מִזַּרְעוֹ נָתַן לַמּלֶךְ\" מִקְצָתוֹ וְלֹא כֻּלּוֹ:","אֶחָד זֶרַע כָּשֵׁר וְאֶחָד זֶרַע פָּסוּל אֶחָד בָּנָיו וּבְנוֹתָיו בְּנֵיהֶם וּבְנֵי בְּנֵיהֶם עַל כָּל יוֹצְאֵי יְרֵכוֹ הוּא חַיָּב מִפְּנֵי שֶׁהֵן זַרְעוֹ. אֲבָל אִם הֶעֱבִיר אֶחָיו אוֹ אַחְיוֹתָיו אוֹ אֲבוֹתָיו אוֹ שֶׁהֶעֱבִיר עַצְמוֹ פָּטוּר. הֶעֱבִיר אֶחָד מִזַּרְעוֹ וְהוּא יָשֵׁן אוֹ שֶׁהָיָה סוּמָא פָּטוּר:","מַצֵּבָה שֶׁאָסְרָה תּוֹרָה הִיא בִּנְיָן שֶׁהַכּל מִתְקַבְּצִין אֶצְלָהּ וַאֲפִלּוּ לַעֲבֹד אֶת ה' שֶׁכֵּן הָיָה דֶּרֶךְ עוֹבְדֵי כּוֹכָבִים. שֶׁנֶּאֱמַר (דברים טז כב) \"וְלֹא תָקִים לְךָ מַצֵּבָה\". וְכָל הַמֵּקִים מַצֵּבָה לוֹקֶה. וְכֵן אֶבֶן מַשְׂכִּית הָאֲמוּרָה בַּתּוֹרָה אַף עַל פִּי שֶׁהוּא מִשְׁתַּחֲוֶה עָלֶיהָ לַשֵּׁם לוֹקֶה שֶׁנֶּאֱמַר (ויקרא כו א) \"וְאֶבֶן מַשְׂכִּית לֹא תִתְּנוּ בְּאַרְצְכֶם לְהִשְׁתַּחֲוֹת עָלֶיהָ\" מִפְּנֵי שֶׁהָיָה דֶּרֶךְ עוֹבְדֵי כּוֹכָבִים לְהַנִּיחַ אֶבֶן לְפָנֶיהָ לְהִשְׁתַּחֲוֹת עָלֶיהָ. לְפִיכָךְ אֵין עוֹשִׂין כֵּן לַה'. וְאֵינוֹ לוֹקֶה עַד שֶׁיִּפְשֹׁט יָדָיו וְרַגְלָיו עַל הָאֶבֶן וְנִמְצָא כֻּלּוֹ מֻטָּל עָלֶיהָ שֶׁזּוֹ הִיא הִשְׁתַּחֲוָיָה הָאֲמוּרָה בַּתּוֹרָה:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁאָר (הָאֲרָצוֹת) אֲבָל בַּמִּקְדָּשׁ מֻתָּר לְהִשְׁתַּחֲווֹת עַל הָאֲבָנִים שֶׁנֶּאֱמַר (ויקרא כו א) \"בְּאַרְצְכֶם\", בְּאַרְצְכֶם אִי אַתֶּם מִשְׁתַּחֲוִים עַל הָאֲבָנִים אֲבָל אַתֶּם מִשְׁתַּחֲוִים עַל הָאֲבָנִים הַמְפֻצָּלוֹת בַּמִּקְדָּשׁ. וּמִפְּנֵי זֶה נָהֲגוּ כָּל יִשְׂרָאֵל לְהַצִּיעַ מַחְצְלָאוֹת בְּבָתֵּי כְּנֵסִיּוֹת הָרְצוּפוֹת בַּאֲבָנִים אוֹ מִינֵי קַשׁ וְתֶבֶן לְהַבְדִּיל בֵּין פְּנֵיהֶם וּבֵין הָאֲבָנִים. וְאִם לֹא מָצָא דָּבָר מַבְדִּיל בֵּינוֹ וּבֵין הָאֶבֶן הוֹלֵךְ לְמָקוֹם אַחֵר וּמִשְׁתַּחֲוֶה אוֹ שׁוֹחֶה עַל צִדּוֹ וּמַטֶּה כְּדֵי שֶׁלֹּא יַדְבִּיק פָּנָיו בָּאֶבֶן:","כָּל הַמִּשְׁתַּחֲוֶה לַה' עַל הָאֲבָנִים הַמְפֻצָּלוֹת בְּלֹא פִּשּׁוּט יָדַיִם וְרַגְלַיִם אֵינוֹ לוֹקֶה אֶלָּא מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. אֲבָל לַעֲבוֹדַת כּוֹכָבִים אֶחָד הִשְׁתַּחֲוָיָה בְּפִשּׁוּט יָדַיִם וְרַגְלַיִם אוֹ בְּלֹא פִּשּׁוּט יָדַיִם וְרַגְלַיִם מִשָּׁעָה שֶׁיִּכְבּשׁ פָּנָיו בַּקַּרְקַע נִסְקָל:","הַנּוֹטֵעַ אִילָן אֵצֶל הַמִּזְבֵּחַ אוֹ בְּכָל הָעֲזָרָה בֵּין אִילַן סְרָק בֵּין אִילַן מַאֲכָל אַף עַל פִּי שֶׁעֲשָׂאוֹ לְנוֹי לַמִּקְדָּשׁ וְיֹפִי לוֹ הֲרֵי זֶה לוֹקֶה שֶׁנֶּאֱמַר (דברים טז כא) \"לֹא תִטַּע לְךָ אֲשֵׁרָה כָּל עֵץ אֵצֶל מִזְבַּח ה' אֱלֹהֶיךָ\". מִפְּנֵי שֶׁהָיָה זֶה דֶּרֶךְ עוֹבְדֵי כּוֹכָבִים נוֹטְעִין אִילָנוֹת בְּצַד מִזְבֵּחַ שֶׁלָּהּ כְּדֵי שֶׁיִּתְקַבְּצוּ שָׁם הָעָם:","אָסוּר לַעֲשׂוֹת אַכְסַדְרָאוֹת שֶׁל עֵץ בַּמִּקְדָּשׁ כְּדֶרֶךְ שֶׁעוֹשִׂין בַּחֲצֵרוֹת, אַף עַל פִּי שֶׁהוּא בְּבִנְיָן וְאֵינוֹ עֵץ נָטוּעַ הַרְחָקָה יְתֵרָה הִיא שֶׁנֶּאֱמַר (דברים טז כא) \"כָּל עֵץ\". אֶלָּא כָּל הָאַכְסַדְרָאוֹת וְהַסְּבָכוֹת הַיּוֹצְאוֹת מִן הַכְּתָלִים שֶׁהָיוּ בַּמִּקְדָּשׁ שֶׁל אֶבֶן הָיוּ לֹא שֶׁל עֵץ:"],"Mishneh Torah, Foundations of the Torah 8":["משֶׁה רַבֵּנוּ לֹא הֶאֱמִינוּ בּוֹ יִשְׂרָאֵל מִפְּנֵי הָאוֹתוֹת שֶׁעָשָׂה. שֶׁהַמַּאֲמִין עַל פִּי הָאוֹתוֹת יֵשׁ בְּלִבּוֹ דֹּפִי שֶׁאֶפְשָׁר שֶׁיַּעֲשֶׂה הָאוֹת בְּלָט וְכִשּׁוּף. אֶלָּא כָּל הָאוֹתוֹת שֶׁעָשָׂה משֶׁה בַּמִּדְבָּר לְפִי הַצֹּרֶךְ עֲשָׂאָם. לֹא לְהָבִיא רְאָיָה עַל הַנְּבוּאָה. הָיָה צָרִיךְ לְהַשְׁקִיעַ אֶת הַמִּצְרִיִּים קָרַע אֶת הַיָּם וְהִצְלִילָן בְּתוֹכוֹ. צָרַכְנוּ לְמָזוֹן הוֹרִיד לָנוּ אֶת הַמָּן. צָמְאוּ בָּקַע לָהֶן אֶת הָאֶבֶן. כָּפְרוּ בּוֹ עֲדַת קֹרַח בָּלְעָה אוֹתָן הָאָרֶץ. וְכֵן שְׁאָר כָּל הָאוֹתוֹת. וּבַמֶּה הֶאֱמִינוּ בּוֹ. בְּמַעֲמַד הַר סִינַי שֶׁעֵינֵינוּ רָאוּ וְלֹא זָר וְאָזְנֵינוּ שָׁמְעוּ וְלֹא אַחֵר הָאֵשׁ וְהַקּוֹלוֹת וְהַלַּפִּידִים וְהוּא נִגַּשׁ אֶל הָעֲרָפֶל וְהַקּוֹל מִדַּבֵּר אֵלָיו וְאָנוּ שׁוֹמְעִים משֶׁה משֶׁה לֵךְ אֱמֹר לָהֶן כָּךְ וְכָךְ. וְכֵן הוּא אוֹמֵר (דברים ה ד) \"פָּנִים בְּפָנִים דִּבֶּר ה' עִמָּכֶם\". וְנֶאֱמַר (דברים ה ג) \"לֹא אֶת אֲבֹתֵינוּ כָּרַת ה' אֶת הַבְּרִית הַזֹּאת\". וּמִנַּיִן שֶׁמַּעֲמַד הַר סִינַי לְבַדּוֹ הִיא הָרְאָיָה לִנְבוּאָתוֹ שֶׁהִיא אֱמֶת שֶׁאֵין בּוֹ דֹּפִי שֶׁנֶּאֱמַר (שמות יט ט) \"הִנֵּה אָנֹכִי בָּא אֵלֶיךָ בְּעַב הֶעָנָן בַּעֲבוּר יִשְׁמַע הָעָם בְּדַבְּרִי עִמָּךְ וְגַם בְּךָ יַאֲמִינוּ לְעוֹלָם\". מִכְלַל שֶׁקֹּדֶם דָּבָר זֶה לֹא הֶאֱמִינוּ בּוֹ נֶאֱמָנוּת שֶׁהִיא עוֹמֶדֶת לְעוֹלָם אֶלָּא נֶאֱמָנוּת שֶׁיֵּשׁ אַחֲרֶיהָ הִרְהוּר וּמַחֲשָׁבָה:","נִמְצְאוּ אֵלּוּ שֶׁשׁוּלַּח לָהֶן הֵם הָעֵדִים עַל נְבוּאָתוֹ שֶׁהִיא אֱמֶת וְאֵינוֹ צָרִיךְ לַעֲשׂוֹת לָהֶן אוֹת אַחֵר. שֶׁהֵם וְהוּא עֵדִים בַּדָּבָר כִּשְׁנֵי עֵדִים שֶׁרָאוּ דָּבָר אֶחָד בְּיַחַד שֶׁכָּל אֶחָד מֵהֶן עֵד לַחֲבֵרוֹ שֶׁהוּא אוֹמֵר אֱמֶת וְאֵין אֶחָד מֵהֶן צָרִיךְ לְהָבִיא רְאָיָה לַחֲבֵרוֹ. כָּךְ משֶׁה רַבֵּנוּ כָּל יִשְׂרָאֵל עֵדִים לוֹ אַחַר מַעֲמַד הַר סִינַי וְאֵינוֹ צָרִיךְ לַעֲשׂוֹת לָהֶם אוֹת. וְזֶהוּ שֶׁאָמַר לוֹ לְהַקָּדוֹשׁ בָּרוּךְ הוּא בִּתְחִלַּת נְבוּאָתוֹ בְּעֵת שֶׁנָּתַן לוֹ הָאוֹתוֹת לַעֲשׂוֹתָן בְּמִצְרַיִם וְאָמַר לוֹ (שמות ג יח) \"וְשָׁמְעוּ לְקלֶךָ\". יָדַע משֶׁה רַבֵּנוּ שֶׁהַמַּאֲמִין עַל פִּי הָאוֹתוֹת יֵשׁ בִּלְבָבוֹ דֹּפִי וּמְהַרְהֵר וּמְחַשֵּׁב וְהָיָה נִשְׁמָט מִלֵּילֵךְ וְאָמַר (שמות ד א) \"וְהֵן לֹא יַאֲמִינוּ לִי\". עַד שֶׁהוֹדִיעוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁאֵלּוּ הָאוֹתוֹת אֵינָן אֶלָּא עַד שֶׁיֵּצְאוּ מִמִּצְרַיִם וְאַחַר שֶׁיֵּצְאוּ וְיַעַמְדוּ עַל הָהָר הַזֶּה יִסְתַּלֵּק הִרְהוּר שֶׁמְּהַרְהֲרִין אַחֲרֶיךָ שֶׁאֲנִי נוֹתֵן לְךָ כָּאן אוֹת שֶׁיֵּדְעוּ שֶׁאֲנִי שְׁלַחְתִּיךָ בֶּאֱמֶת מִתְּחִלָּה וְלֹא יִשָּׁאֵר בְּלִבָּם הִרְהוּר. וְהוּא שֶׁהַכָּתוּב אוֹמֵר (שמות ג יב) \"וְזֶה לְּךָ הָאוֹת כִּי אָנֹכִי שְׁלַחְתִּיךָ בְּהוֹצִיאֲךָ אֶת הָעָם מִמִּצְרַיִם תַּעַבְדוּן אֶת הָאֱלֹהִים עַל הָהָר הַזֶּה\". נִמְצֵאתָ אוֹמֵר שֶׁכָּל נָבִיא שֶׁיַּעֲמֹד אַחַר משֶׁה רַבֵּנוּ אֵין אָנוּ מַאֲמִינִים בּוֹ מִפְּנֵי הָאוֹת לְבַדּוֹ כְּדֵי שֶׁנֹּאמַר אִם יַעֲשֶׂה אוֹת נִשְׁמַע לוֹ לְכָל מַה שֶּׁיֹּאמַר. אֶלָּא מִפְּנֵי הַמִּצְוָה שֶׁצִּוָּה משֶׁה בַּתּוֹרָה וְאָמַר אִם נָתַן אוֹת (דברים יח טו) \"אֵלָיו תִּשְׁמָעוּן\". כְּמוֹ שֶׁצִּוָּנוּ לַחְתֹּךְ הַדָּבָר עַל פִּי שְׁנַיִם עֵדִים וְאַף עַל פִּי שֶׁאֵין אָנוּ יוֹדְעִין אִם הֵעִידוּ אֱמֶת אִם שֶׁקֶר. כָּךְ מִצְוָה לִשְׁמֹעַ מִזֶּה הַנָּבִיא אַף עַל פִּי שֶׁאֵין אָנוּ יוֹדְעִים אִם הָאוֹת אֱמֶת אוֹ בְּכִשּׁוּף וְלָט:","לְפִיכָךְ אִם עָמַד הַנָּבִיא וְעָשָׂה אוֹתוֹת וּמוֹפְתִים גְּדוֹלִים וּבִקֵּשׁ לְהַכְחִישׁ נְבוּאָתוֹ שֶׁל משֶׁה רַבֵּנוּ אֵין שׁוֹמְעִין לוֹ וְאָנוּ יוֹדְעִין בְּבֵאוּר שֶׁאוֹתָן הָאוֹתוֹת בְּלָט וְכִשּׁוּף הֵן. לְפִי שֶׁנְּבוּאַת משֶׁה רַבֵּנוּ אֵינָהּ עַל פִּי הָאוֹתוֹת כְּדֵי שֶׁנַּעֲרֹךְ אוֹתוֹת זֶה לְאוֹתוֹת זֶה. אֶלָּא בְּעֵינֵינוּ רְאִינוּהָ וּבְאָזְנֵינוּ שְׁמַעֲנוּהָ כְּמוֹ שֶׁשָּׁמַע הוּא. הָא לְמָה הַדָּבָר דּוֹמֶה לְעֵדִים שֶׁהֵעִידוּ לָאָדָם עַל דָּבָר שֶׁרָאָה בְּעֵינָיו שֶׁאֵינוֹ כְּמוֹ שֶׁרָאָה שֶׁאֵינוֹ שׁוֹמֵעַ לָהֶן אֶלָּא יוֹדֵעַ בְּוַדַּאי שֶׁהֵן עֵדֵי שֶׁקֶר. לְפִיכָךְ אָמְרָה תּוֹרָה שֶׁאִם בָּא הָאוֹת וְהַמּוֹפֵת (דברים יג ד) \"לֹא תִּשְׁמַע אֶל דִּבְרֵי הַנָּבִיא הַהוּא\". שֶׁהֲרֵי זֶה בָּא אֵלֶיךָ בְּאוֹת וּמוֹפֵת לְהַכְחִישׁ מַה שֶּׁרָאִיתָ בְּעֵינֶיךָ וְהוֹאִיל וְאֵין אָנוּ מַאֲמִינִים בְּמוֹפֵת אֶלָּא מִפְּנֵי הַמִּצְוֹת שֶׁצִּוָּנוּ משֶׁה הֵיאַךְ נְקַבֵּל מֵאוֹת זֶה שֶׁבָּא לְהַכְחִישׁ נְבוּאָתוֹ שֶׁל משֶׁה שֶׁרָאִינוּ וְשֶׁשָּׁמַעְנוּ:"],"Mishneh Torah, Gifts to the Poor 7":["מִצְוַת עֲשֵׂה לִתֵּן צְדָקָה לָעֲנִיִּים כְּפִי מַה שֶּׁרָאוּי לֶעָנִי. אִם הָיְתָה יַד הַנּוֹתֵן מַשֶּׂגֶת. שֶׁנֶּאֱמַר (דברים טו ח) \"פָתֹחַ תִּפְתַּח אֶת יָדְךָ לוֹ\" וְנֶאֱמַר (ויקרא כה לה) \"וְהֶחֱזַקְתָּ בּוֹ גֵּר וְתוֹשָׁב וָחַי עִמָּךְ\" וְנֶאֱמַר (ויקרא כה לו) \"וְחֵי אָחִיךָ עִמָּךְ\":","וְכָל הָרוֹאֶה עָנִי מְבַקֵּשׁ וְהֶעֱלִים עֵינָיו מִמֶּנּוּ וְלֹא נָתַן לוֹ צְדָקָה עָבַר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים טו ז) \"לֹא תְאַמֵּץ אֶת לְבָבְךָ וְלֹא תִקְפֹּץ אֶת יָדְךָ מֵאָחִיךָ הָאֶבְיוֹן\":","לְפִי מַה שֶּׁחָסֵר הֶעָנִי אַתָּה מְצֻוֶּה לִתֵּן לוֹ. אִם אֵין לוֹ כְּסוּת מְכַסִּים אוֹתוֹ. אִם אֵין לוֹ כְּלֵי בַּיִת קוֹנִין לוֹ. אִם אֵין לוֹ אִשָּׁה מַשִּׂיאִין אוֹתוֹ. וְאִם הָיְתָה אִשָּׁה מַשִּׂיאִין אוֹתָהּ לְאִישׁ. אֲפִלּוּ הָיָה דַּרְכּוֹ שֶׁל זֶה הֶעָנִי לִרְכֹּב עַל הַסּוּס וְעֶבֶד רָץ לְפָנָיו וְהֶעֱנִי וְיָרַד מִנְּכָסָיו קוֹנִין לוֹ סוּס לִרְכֹּב עָלָיו וְעֶבֶד לָרוּץ לְפָנָיו שֶׁנֶּאֱמַר (דברים טו ח) \"דֵּי מַחְסֹרוֹ אֲשֶׁר יֶחְסַר לוֹ\". וּמְצֻוֶּה אַתָּה לְהַשְׁלִים חֶסְרוֹנוֹ וְאֵין אַתָּה מְצֻוֶּה לְעַשְּׁרוֹ:","יָתוֹם שֶׁבָּא לְהַשִּׂיאוֹ אִשָּׁה. שׂוֹכְרִין לוֹ בַּיִת וּמַצִּיעִים לוֹ מִטָּה וְכָל כְּלֵי תַּשְׁמִישׁוֹ וְאַחַר כָּךְ מַשִּׂיאִין לוֹ אִשָּׁה:","בָּא הֶעָנִי וְשָׁאַל דֵּי מַחֲסוֹרוֹ וְאֵין יַד הַנּוֹתֵן מַשֶּׂגֶת נוֹתֵן לוֹ כְּפִי הַשָּׂגַת יָדוֹ וְכַמָּה עַד חֲמִישִׁית נְכָסָיו מִצְוָה מִן הַמֻּבְחָר. וְאֶחָד מֵעֲשָׂרָה בִּנְכָסָיו בֵּינוֹנִי. פָּחוֹת מִכָּאן עַיִן רָעָה. וּלְעוֹלָם לֹא יִמְנַע עַצְמוֹ מִשְּׁלִישִׁית הַשֶּׁקֶל בְּשָׁנָה. וְכָל הַנּוֹתֵן פָּחוֹת מִזֶּה לֹא קִיֵּם מִצְוָה. וַאֲפִלּוּ עָנִי הַמִּתְפַּרְנֵס מִן הַצְּדָקָה חַיָּב לִתֵּן צְדָקָה לְאַחֵר:","עָנִי שֶׁאֵין מַכִּירִין אוֹתוֹ וְאָמַר רָעֵב אֲנִי הַאֲכִילוּנִי אֵין בּוֹדְקִין אַחֲרָיו שֶׁמָּא רַמַּאי הוּא אֶלָּא מְפַרְנְסִין אוֹתוֹ מִיָּד. הָיָה עֵרוֹם וְאָמַר כַּסּוּנִי בּוֹדְקִין אַחֲרָיו שֶׁמָּא רַמַּאי הוּא. וְאִם הָיוּ מַכִּירִין אוֹתוֹ מְכַסִּין אוֹתוֹ לְפִי כְּבוֹדוֹ מִיָּד וְאֵין בּוֹדְקִין אַחֲרָיו:","מְפַרְנְסִין וּמְכַסִּין עֲנִיֵּי עַכּוּ\"ם עִם עֲנִיֵּי יִשְׂרָאֵל מִפְּנֵי דַּרְכֵי שָׁלוֹם. וְעָנִי הַמְחַזֵּר עַל הַפְּתָחִים אֵין נִזְקָקִין לוֹ לְמַתָּנָה מְרֻבָּה אֲבָל נוֹתְנִין לוֹ מַתָּנָה מֻעֶטֶת. וְאָסוּר לְהַחֲזִיר אֶת הֶעָנִי שֶׁשָּׁאַל רֵיקָם וַאֲפִלּוּ אַתָּה נוֹתֵן לוֹ גְּרוֹגֶרֶת אַחַת שֶׁנֶּאֱמַר (תהילים עד כא) \"אַל יָשֹׁב דַּךְ נִכְלָם\":","אֵין פּוֹחֲתִין לְעָנִי הָעוֹבֵר מִמָּקוֹם לְמָקוֹם מִכִּכָּר אֶחָד הַנִמְכָּר בְּפוּנְדְיוֹן כְּשֶׁהָיוּ הַחִטִּים אַרְבַּע סְאִין בְּסֶלַע וּכְבָר בֵּאַרְנוּ כָּל הַמִּדּוֹת. וְאִם לָן נוֹתְנִין לוֹ מַצָּע לִישֹׁן עָלָיו וְכֶסֶת לִתֵּן תַּחַת מְרַאשׁוֹתָיו. וְשֶׁמֶן וְקִטְנִית. וְאִם שָׁבַת נוֹתְנִין לוֹ מְזוֹן שָׁלֹשׁ סְעֻדּוֹת וְשֶׁמֶן וְקִטְנִית וְדָג וְיָרָק. וְאִם הָיוּ מַכִּירִין אוֹתוֹ נוֹתְנִין לוֹ לְפִי כְּבוֹדוֹ:","עָנִי שֶׁאֵינוֹ רוֹצֶה לִקַּח צְדָקָה מַעֲרִימִין עָלָיו וְנוֹתְנִין לוֹ לְשֵׁם מַתָּנָה אוֹ לְשֵׁם הַלְוָאָה. וְעָשִׁיר הַמַּרְעִיב אֶת עַצְמוֹ וְעֵינוֹ צָרָה בְּמָמוֹנוֹ שֶׁלֹּא יֹאכַל מִמֶּנּוּ וְלֹא יִשְׁתֶּה אֵין מַשְׁגִּיחִין בּוֹ:","מִי שֶׁאֵינוֹ רוֹצֶה לִתֵּן צְדָקָה אוֹ שֶׁיִּתֵּן מְעַט מִמַּה שֶּׁרָאוּי לוֹ. בֵּית דִּין כּוֹפִין אוֹתוֹ וּמַכִּין אוֹתוֹ מַכַּת מַרְדּוּת עַד שֶׁיִּתֵּן מַה שֶּׁאֲמָדוּהוּ לִתֵּן. וְיוֹרְדִין לִנְכָסָיו בְּפָנָיו וְלוֹקְחִין מִמֶּנּוּ מַה שֶּׁרָאוּי לוֹ לִתֵּן. וּמְמַשְׁכְּנִין עַל הַצְּדָקָה וַאֲפִלּוּ בְּעַרְבֵי שַׁבְּתוֹת:","אָדָם שׁוֹעַ שֶׁהוּא נוֹתֵן צְדָקָה יוֹתֵר מִן הָרָאוּי לוֹ. אוֹ שֶׁמֵּצֵר לְעַצְמוֹ וְנוֹתֵן לַגַּבָּאִים כְּדֵי שֶׁלֹּא יִתְבַּיֵּשׁ. אָסוּר לְתָבְעוֹ וְלִגְבּוֹת מִמֶּנּוּ צְדָקָה. וְגַבַּאי שֶׁמַּכְלִימוֹ וְשׁוֹאֵל מִמֶּנּוּ עָתִיד לְהִפָּרַע מִמֶּנּוּ שֶׁנֶּאֱמַר (ירמיה ל כ) \"וּפָקַדְתִּי עַל כָּל לֹחֲצָיו\":","אֵין פּוֹסְקִין צְדָקָה עַל יְתוֹמִים וַאֲפִלּוּ לְפִדְיוֹן שְׁבוּיִים וְאַף עַל פִּי שֶׁיֵּשׁ לָהֶם מָמוֹן הַרְבֵּה. וְאִם פָּסַק הַדַּיָּן עֲלֵיהֶם כְּדֵי לָשׂוּם לָהֶן שֵׁם מֻתָּר. גַּבָּאֵי צְדָקָה לוֹקְחִין מִן הַנָּשִׁים וּמִן הָעֲבָדִים וּמִן הַתִּינוֹקוֹת דָּבָר מֻעָט. אֲבָל לֹא דָּבָר מְרֻבֶּה. שֶׁחֶזְקַת הַמְרֻבֶּה גְּנֵבָה אוֹ גֵּזֶל מִשֶּׁל אֲחֵרִים. וְכַמָּה הוּא מֻעָט שֶׁלָּהֶן הַכּל לְפִי עשֶׁר הַבְּעָלִים וַעֲנִיּוּתָן:","עָנִי שֶׁהוּא קְרוֹבוֹ קֹדֶם לְכָל אָדָם. עֲנִיֵּי בֵּיתוֹ קוֹדְמִין לַעֲנִיֵּי עִירוֹ. עֲנִיֵּי עִירוֹ קוֹדְמִין לַעֲנִיֵּי עִיר אַחֶרֶת. שֶׁנֶּאֱמַר (דברים טו יא) \"לְאָחִיךָ לַעֲנִיֶּךָ וּלְאֶבְיֹנְךָ בְּאַרְצֶךָ\":","מִי שֶׁהָלַךְ בִּסְחוֹרָה וּפָסְקוּ עָלָיו אַנְשֵׁי הָעִיר שֶׁהָלַךְ שָׁם צְדָקָה הֲרֵי זֶה נוֹתֵן לַעֲנִיֵּי אוֹתָהּ הָעִיר. וְאִם הָיוּ רַבִּים וּפָסְקוּ עֲלֵיהֶן צְדָקָה נוֹתְנִין וּכְשֶׁבָּאִין מְבִיאִין אוֹתָהּ עִמָּהֶן וּמְפַרְנְסִין בָּהּ עֲנִיֵּי עִירָם. וְאִם יֵשׁ שָׁם חָבֵר עִיר יִתְּנוּהָ לְחָבֵר עִיר וְהוּא מְחַלְּקָהּ כְּמוֹ שֶׁיִּרְאֶה לוֹ:","הָאוֹמֵר תְּנוּ מָאתַיִם דִּינָר לְבֵית הַכְּנֶסֶת אוֹ תְּנוּ סֵפֶר תּוֹרָה לְבֵית הַכְּנֶסֶת יִתְּנוּ לְבֵית הַכְּנֶסֶת שֶׁהוּא רָגִיל בּוֹ. וְאִם הָיָה רָגִיל בִּשְׁנַיִם יִתְּנוּ לִשְׁנֵיהֶן. הָאוֹמֵר תְּנוּ מָאתַיִם דִּינָרִין לַעֲנִיִּים יִתְּנוּ לַעֲנִיֵּי אוֹתָהּ הָעִיר:"],"Mishneh Torah, Heave Offerings 4":["עוֹשֶׂה אָדָם שָׁלִיחַ לְהַפְרִישׁ לוֹ תְּרוּמוֹת וּמַעַשְׂרוֹת שֶׁנֶּאֱמַר (במדבר יח כח) \"כֵּן תָּרִימוּ גַם אַתֶּם\" לְרַבּוֹת שְׁלוּחֲכֶם. וְאֵין עוֹשִׂין שָׁלִיחַ עַכּוּ\"ם שֶׁנֶּאֱמַר גַם אַתֶּם מָה אַתֶּם בְּנֵי בְּרִית אַף שְׁלוּחֲכֶם בְּנֵי בְּרִית:","חֲמִשָּׁה לֹא יִתְרֹמוּ וְאִם תָּרְמוּ אֵין תְּרוּמָתָן תְּרוּמָה. הַחֵרֵשׁ. וְהַשּׁוֹטֶה. וְהַקָּטָן. וְהָעַכּוּ\"ם שֶׁתָּרַם אֶת שֶׁל יִשְׂרָאֵל וַאֲפִלּוּ בִּרְשׁוּתוֹ. וְהַתּוֹרֵם אֶת שֶׁאֵינוֹ שֶׁלּוֹ שֶׁלֹּא בִּרְשׁוּת הַבְּעָלִים. אֲבָל הַתּוֹרֵם מִשֶּׁלּוֹ עַל שֶׁל אֲחֵרִים הֲרֵי זוֹ תְּרוּמָה וְתִקֵּן פֵּרוֹתֵיהֶם. וְטוֹבַת הֲנָאָה שֶׁלּוֹ שֶׁנּוֹתְנָהּ לְכָל כֹּהֵן שֶׁיִּרְצֶה:","הַתּוֹרֵם שֶׁלֹּא בִּרְשׁוּת אוֹ שֶׁיָּרַד לְתוֹךְ שְׂדֵה חֲבֵרוֹ וְלִקֵּט פֵּרוֹת שֶׁלֹּא בִּרְשׁוּת כְּדֵי שֶׁיִּקָּחֵם וְתָרַם. אִם בָּא בַּעַל הַבַּיִת וְאָמַר לוֹ כַּלֵּךְ אֵצֶל יָפוֹת. אִם הָיוּ שָׁם יָפוֹת מִמַּה שֶּׁתָּרַם תְּרוּמָתוֹ תְּרוּמָה שֶׁהֲרֵי אֵינוֹ מַקְפִּיד. וְאִם לֹא הָיוּ שָׁם יָפוֹת אֵין תְּרוּמָתוֹ תְּרוּמָה שֶׁלֹּא אָמַר לוֹ אֶלָּא עַל דֶּרֶךְ מִחוּי. וְאִם בָּא בַּעַל הַבַּיִת וְלִקֵּט וְהוֹסִיף בֵּין יֵשׁ לוֹ יָפוֹת מֵהֶן בֵּין אֵין לוֹ תְּרוּמָתוֹ תְּרוּמָה:","חֲמִשָּׁה לֹא יִתְרֹמוּ וְאִם תָּרְמוּ תְּרוּמָתָן תְּרוּמָה. חֵרֵשׁ מְדַבֵּר וְאֵינוֹ שׁוֹמֵעַ מִפְּנֵי שֶׁאֵינוֹ שׁוֹמֵעַ הַבְּרָכָה. וְהָאִלֵּם שֶׁשּׁוֹמֵעַ וְאֵינוֹ מְדַבֵּר. וְהֶעָרוּם. מִפְּנֵי שֶׁאֵינָן יְכוֹלִין לְבָרֵךְ. וְהַשִּׁכּוֹר וְהַסּוּמָא מִפְּנֵי שֶׁאֵינָן יְכוֹלִין לְכַוֵּן וּלְהַפְרִישׁ אֶת הַיָּפֶה:","קָטָן שֶׁהִגִּיעַ לְעוֹנַת נְדָרִים אַף עַל פִּי שֶׁלֹּא הֵבִיא שְׁתֵּי שְׂעָרוֹת וְלֹא נַעֲשָׂה גָּדוֹל אִם תָּרַם תְּרוּמָתוֹ תְּרוּמָה. וַאֲפִלּוּ בִּתְרוּמָה שֶׁל תּוֹרָה הוֹאִיל וְנִדְרֵיהֶן וְהֶקְדֵּשָׁן קַיָּמִין מִן הַתּוֹרָה כְּמוֹ שֶׁבֵּאַרְנוּ בִּנְדָרִים:","הָאוֹמֵר לִשְׁלוּחוֹ צֵא וּתְרֹם לִי וְהָלַךְ לִתְרֹם וְאֵינוֹ יוֹדֵעַ אִם תָּרַם וְאִם לֹא תָּרַם וּבָא וּמָצָא כְּרִי תָּרוּם אֵין חֶזְקָתוֹ תָּרוּם. שֶׁאֵין אוֹמְרִין בְּאִסּוּרִין חֶזְקַת שָׁלִיחַ עוֹשֶׂה שְׁלִיחוּתוֹ לְהָקֵל אֶלָּא לְהַחֲמִיר וְחוֹשֵׁשׁ שֶׁמָּא אַחֵר תָּרַם שֶׁלֹּא בִּרְשׁוּת:","הָאוֹמֵר לִשְׁלוּחוֹ צֵא וּתְרֹם תּוֹרֵם כְּדַעְתּוֹ שֶׁל בַּעַל הַבַּיִת. אִם הָיָה יוֹדֵעַ בּוֹ שֶׁהוּא בַּעַל עַיִן רָעָה מַפְרִישׁ אֶחָד מִשִּׁשִּׁים. וְאִם הָיָה בַּעַל נֶפֶשׁ שְׂבֵעָה מַפְרִישׁ אֶחָד מֵאַרְבָּעִים. וְאִם אֵינוֹ יוֹדֵעַ דַּעְתּוֹ מַפְרִישׁ לוֹ בֵּינוֹנִית אֶחָד מֵחֲמִשִּׁים. נִתְכַּוֵּן לְבֵינוֹנִית וְעָלְתָה בְּיָדוֹ אֶחָד מֵאַרְבָּעִים אוֹ אֶחָד מִשִּׁשִּׁים תְּרוּמָתוֹ תְּרוּמָה. וְאִם נִתְכַּוֵּן לְהוֹסִיף עַל הַבֵּינוֹנִית וְתָרַם אֲפִלּוּ אֶחָד מִתִּשְׁעִים וְתִשְׁעָה אֵין תְּרוּמָתוֹ תְּרוּמָה:","פֵּרוֹת הַשֻּׁתָּפִין חַיָּבוֹת בִּתְרוּמָה וּמַעַשְׂרוֹת שֶׁנֶּאֱמַר (במדבר יח כח) \"מַעְשְׂרֹתֵיכֶם\" אֲפִלּוּ שֶׁל שְׁנַיִם. וְהַשֻּׁתָּפִין אֵינָן צְרִיכִין לִטּל רְשׁוּת זֶה מִזֶּה. אֶלָּא כָּל הַתּוֹרֵם מֵהֶן תְּרוּמָתוֹ תְּרוּמָה. תָּרַם אֶחָד מֵהֶן וּבָא הַשֵּׁנִי וְתָרַם תְּרוּמָה שְׁנִיָּה שֶׁהֲרֵי לֹא יָדַע שֶׁחֲבֵרוֹ תָּרַם. אִם הָיוּ מְמַחִין זֶה עַל זֶה תְּרוּמַת הַשֵּׁנִי אֵינָהּ תְּרוּמָה. וְאִם לֹא הָיוּ מְמַחִין וְתָרַם הָרִאשׁוֹן כַּשִּׁעוּר (אֵין תְּרוּמַת הַשֵּׁנִי תְּרוּמָה לֹא תָּרַם הָרִאשׁוֹן כַּשִּׁעוּר) תְּרוּמַת שְׁנֵיהֶן תְּרוּמָה:","הָאוֹמֵר לְשֻׁתָּפוֹ אוֹ לְבֶן בֵּיתוֹ אוֹ לְעַבְדּוֹ אוֹ לְשִׁפְחָתוֹ לִתְרֹם. וְהָלְכוּ לִתְרֹם וּבִטֵּל שְׁלִיחוּתוֹ קֹדֶם שֶׁיִּתְרֹמוּ. אִם לֹא שִׁנָּה הַשָּׁלִיחַ תְּרוּמָתוֹ תְּרוּמָה. וְאִם שִׁנָּה כְּגוֹן שֶׁאָמַר לוֹ תְּרֹם מִן הַצָּפוֹן וְתָרַם מִן הַדָּרוֹם הוֹאִיל וּבִטֵּל שְׁלִיחוּתוֹ מִקֹּדֶם אֵינָהּ תְּרוּמָה:","אָרִיס שֶׁתָּרַם וּבָא בַּעַל הַבַּיִת וְעִכֵּב אִם עַד שֶׁלֹּא תָּרַם עִכֵּב אֵין תְּרוּמָתוֹ תְּרוּמָה וְאִם מִשֶּׁתָּרַם עִכֵּב תְּרוּמָתוֹ תְּרוּמָה. וְהָאַפּוֹטְרוֹפְּסִין תּוֹרְמִין מִנִּכְסֵי יְתוֹמִים:","הַגַּנָּב וְהַגַּזְלָן וְהָאַנָּס תְּרוּמָתָן תְּרוּמָה. וְאִם הָיוּ הַבְּעָלִים רוֹדְפִין אַחֲרֵיהֶן אֵין תְּרוּמָתָן תְּרוּמָה:","הַבֵּן וְהַשָּׂכִיר וְהָעֶבֶד וְהָאִשָּׁה תּוֹרְמִין עַל מַה שֶּׁהֵן אוֹכְלִין. אֲבָל לֹא יִתְרְמוּ עַל הַכּל שֶׁאֵין אָדָם תּוֹרֵם דָּבָר שֶׁאֵינוֹ שֶׁלּוֹ. הַבֵּן כְּשֶׁאוֹכֵל עִם אָבִיו וְהָאִשָּׁה בְּעִסָּתָהּ תּוֹרְמִין מִפְּנֵי שֶׁהֵן בִּרְשׁוּת:","הַפּוֹעֲלִים אֵין לָהֶן רְשׁוּת לִתְרֹם שֶׁלֹּא מִדַּעַת בַּעַל הַבַּיִת. חוּץ מִן הַדּוֹרְכִין בְּגַת שֶׁאִם יִרְצוּ לְטַמֵּא אֶת הַיַּיִן הֲרֵי הֵן מְטַמְּאִים מִיָּד. וּלְפִי שֶׁמָּסַר לָהֶן וְהֶאֱמִינָן עַל כֵּן הֲרֵי הֵן כִּשְׁלוּחִין וְאִם תָּרְמוּ תְּרוּמָתָן תְּרוּמָה:","פּוֹעֵל שֶׁאָמַר לוֹ בַּעַל הַבַּיִת כְּנֹס לִי גָּרְנִי וּתְרֹם וְתָרַם וְאַחַר כָּךְ כָּנַס תְּרוּמָתוֹ תְּרוּמָה:","הָעַכּוּ\"ם שֶׁהִפְרִישׁ תְּרוּמָה מִשֶּׁלּוֹ דִּין תּוֹרָה שֶׁאֵינָהּ תְּרוּמָה לְפִי שֶׁאֵינָן חַיָּבִין. וּמִדִּבְרֵיהֶן גָּזְרוּ שֶׁתִּהְיֶה תְּרוּמָתוֹ תְּרוּמָה מִשּׁוּם בַּעֲלֵי כִּיסִין. שֶׁלֹּא יִהְיֶה זֶה הַמָּמוֹן שֶׁל יִשְׂרָאֵל וְיִתְלֶה אוֹתוֹ בְּעַכּוּ\"ם כְּדֵי לְפָטְרוֹ. וּבוֹדְקִין אֶת הָעַכּוּ\"ם שֶׁהִפְרִישׁ תְּרוּמָה אִם אָמַר בְּדַעַת יִשְׂרָאֵל הִפְרַשְׁתִּיהָ תִּנָּתֵן לְכֹהֵן. וְאִם לָאו טְעוּנָה גְּנִיזָה שֶׁמָּא בְּלִבּוֹ לַשָּׁמַיִם. בַּמֶּה דְּבָרִים אֲמוּרִים בְּאֶרֶץ יִשְׂרָאֵל. אֲבָל עַכּוּ\"ם שֶׁהִפְרִישׁ תְּרוּמָה בְּחוּצָה לָאָרֶץ לֹא גָּזְרוּ עֲלֵיהֶן וּמוֹדִיעִין אוֹתוֹ שֶׁאֵינוֹ צָרִיךְ וְאֵינָהּ תְּרוּמָה כְּלָל:","הַמִּתְכַּוֵּן לוֹמַר תְּרוּמָה וְאָמַר מַעֲשֵׂר. מַעֲשֵׂר וְאָמַר תְּרוּמָה. לֹא אָמַר כְּלוּם. עַד שֶׁיִּהְיֶה פִּיו וְלִבּוֹ שָׁוִין. הִפְרִישׁ תְּרוּמָה בְּמַחֲשַׁבְתּוֹ וְלֹא הוֹצִיא בִּשְׂפָתָיו כְּלוּם הֲרֵי זוֹ תְּרוּמָה שֶׁנֶּאֱמַר (במדבר יח כז) \"וְנֶחְשַׁב לָכֶם תְּרוּמַתְכֶם כַּדָּגָן מִן הַגֹּרֶן\" בְּמַחֲשָׁבָה בִּלְבַד תִּהְיֶה תְּרוּמָה:","הַמַּפְרִישׁ תְּרוּמָה עַל תְּנַאי אִם נִתְקַיֵּם הַתְּנַאי הֲרֵי הִיא תְּרוּמָה. וְאִם לָאו אֵינָהּ תְּרוּמָה. וְכֵן הַמַּפְרִישׁ תְּרוּמָה וּמַעַשְׂרוֹת וְנִחָם עֲלֵיהֶן הֲרֵי זֶה נִשְׁאַל לְחָכָם וּמַתִּיר לוֹ כְּדֶרֶךְ שֶׁמַּתִּירִין לוֹ שְׁאָר נְדָרִים. וְתַחֲזֹר חֻלִּין כְּמוֹ שֶׁהָיְתָה עַד שֶׁיַּפְרִישׁ פַּעַם שְׁנִיָּה אוֹתָהּ שֶׁהִפְרִישׁ תְּחִלָּה אוֹ פֵּרוֹת אֲחֵרוֹת:","הַתּוֹרֵם בּוֹר שֶׁל יַיִן וְאָמַר הֲרֵי זוֹ תְּרוּמָה עַל מְנָת שֶׁתַּעֲלֶה שָׁלֵם [צָרִיךְ שֶׁתַּעֲלֶה] שָׁלֵם מִן הַשֶּׁבֶר וּמִן הַשְּׁפִיכָה אֲבָל לֹא מִן הַטֻּמְאָה. וְאִם נִשְׁבְּרָה אֵינָהּ מְדַמַּעַת. הִנִּיחָהּ בְּמָקוֹם שֶׁאִם תִּשָּׁבֵר שָׁם אוֹ תִּתְגַּלְגֵּל לֹא תַּגִּיעַ לַבּוֹר הֲרֵי זוֹ מְדַמַּעַת שֶׁכְּבָר נִתְקַיֵּם הַתְּנַאי:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּתְרוּמָה גְּדוֹלָה. אֲבָל בִּתְרוּמַת מַעֲשֵׂר שֶׁמֻּתָּר לִתְרֹם שֶׁלֹּא מִן הַמֻּקָּף כֵּיוָן שֶׁעָלְתָה נִתְקַיֵּם תְּנָאוֹ וַהֲרֵי הִיא תְּרוּמַת מַעֲשֵׂר וְאַף עַל פִּי שֶׁנִּשְׁבְּרָה אוֹ שֶׁנִּשְׁפְּכָה וְאֵין צָרִיךְ לוֹמַר שֶׁנִּטְמֵאת:","הָאוֹמֵר שֶׁלְּמַעְלָה תְּרוּמָה וְשֶׁלְּמַטָּה חֻלִּין אוֹ שֶׁלְּמַעְלָה חֻלִּין וְשֶׁלְּמַטָּה תְּרוּמָה דְּבָרָיו קַיָּמִין שֶׁהַדָּבָר תָּלוּי בְּדַעַת הַתּוֹרֵם:","הַתּוֹרֵם אֶת הַגֹּרֶן צָרִיךְ שֶׁיְּכַוֵּן אֶת לִבּוֹ שֶׁתִּהְיֶה זוֹ תְּרוּמָה עַל הַכְּרִי וְעַל מַה שֶׁבַּקּוּטְעִין וְעַל מַה שֶּׁבַּצְּדָדִין וְעַל מַה שֶּׁבְּתוֹךְ הַתֶּבֶן. הַתּוֹרֵם אֶת הַיֶּקֶב צָרִיךְ שֶׁיְּכַוִּן אֶת לִבּוֹ לִתְרֹם עַל מַה שֶּׁבַּחַרְצַנִּין וְעַל מַה שֶּׁבַּזַּגִּין. הַתּוֹרֵם אֶת הַבּוֹר שֶׁל יַיִן צָרִיךְ שֶׁיְּכַוֵּן אֶת לִבּוֹ לִתְרֹם עַל מַה שֶּׁבַּגֶּפֶת. וְאִם לֹא נִתְכַּוֵּן אֶלָּא תָּרַם סְתָם נִפְטָר הַכּל. שֶׁתְּנַאי בֵּית דִּין הוּא שֶׁהַתְּרוּמָה עַל הַכּל. הַתּוֹרֵם כַּלְכָּלָה שֶׁל תְּאֵנִים וְנִמְצְאוּ תְּאֵנִים בְּצַד הַכַּלְכָּלָה הֲרֵי אֵלּוּ פְּטוּרִין מִפְּנֵי שֶׁבְּלִבּוֹ לִתְרֹם עַל הַכּל:"],"Mishneh Torah, Hiring 3":["שׁוֹמֵר שֶׁטָּעַן שֶׁנֶּאֱנַס אֹנֶס גָּדוֹל כְּגוֹן שְׁבוּרָה וּמֵתָה. אִם נֶאֱנַס בְּמָקוֹם שֶׁהָעֵדִים מְצוּיִין שָׁם מַצְרִיכִין אוֹתוֹ רְאָיָה עַל טַעֲנָתוֹ שֶׁנֶּאֱנַס וְיִפָּטֵר אַף מִשְּׁבוּעַת שׁוֹמְרִים וְאִם לֹא הֵבִיא רְאָיָה יְשַׁלֵּם שֶׁנֶּאֱמַר (שמות כב ט) \"אֵין רֹאֶה\" (שמות כב י) \"שְׁבֻעַת ה' תִּהְיֶה בֵּין שְׁנֵיהֶם\" הָא בְּמָקוֹם שֶׁאֶפְשָׁר לְהָבִיא רְאָיָה אֵין שָׁם שְׁבוּעָה אֶלָּא אוֹ יָבִיא רְאָיָה אוֹ יְשַׁלֵּם. אֲבָל אִם טָעַן שֶׁנֶּאֱנַס בְּמָקוֹם שֶׁאֵין הָעֵדִים מְצוּיִין שָׁם אֵין מַצְרִיכִין אוֹתוֹ רְאָיָה אֶלָּא יִשָּׁבַע שֶׁנֶּאֱנַס וְיִפָּטֵר. וְאִם הֵבִיא עֵדִים שֶׁלֹּא פָּשַׁע בָּהּ נִפְטָר אַף מִן הַשְּׁבוּעָה. מַעֲשֶׂה בְּאֶחָד שֶׁהֵבִיא חָבִית שֶׁל יַיִן בְּשָׂכָר וּשְׁבָרָהּ בַּשּׁוּק שֶׁל מְחוֹזָא וּבָאוּ לִפְנֵי חֲכָמִים וְאָמְרוּ שׁוּק זֶה שֶׁטָּעַנְתָּ שֶׁנִּשְׁבְּרָה בּוֹ חָבִית בְּנֵי אָדָם מְצוּיִין שָׁם אוֹ תָּבִיא רְאָיָה שֶׁלֹּא פָּשַׁעְתָּ אֶלָּא נִתְקַלְתָּ וְנָפַלְתָּ אוֹ תְּשַׁלֵּם דָּמֶיהָ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַמַּעֲבִיר חָבִית מִמָּקוֹם לְמָקוֹם בְּשָׂכָר וְנִשְׁבְּרָה דִּין תּוֹרָה הוּא שֶׁיְּשַׁלֵּם שֶׁאֵין זֶה אֹנֶס גָּדוֹל וַהֲרֵי הַשְּׁבִירָה כִּגְנֵבָה וַאֲבֵדָה שֶׁהוּא חַיָּב בָּהֶן. אֲבָל תִּקְּנוּ חֲכָמִים שֶׁיִּהְיֶה חַיָּב שְׁבוּעָה שֶׁלֹּא פָּשַׁע בָּהּ שֶׁאִם אַתָּה אוֹמֵר יְשַׁלֵּם אֵין לְךָ אָדָם שֶׁיַּעֲבִיר חָבִית לַחֲבֵרוֹ לְפִיכָךְ עָשׂוּ בּוֹ שְׁבִירַת הֶחָבִית כְּמִיתַת הַבְּהֵמָה וּשְׁבִירָתָהּ. וְעוֹד תִּקְּנוּ בְּדָבָר זֶה שֶׁאִם נָשְׂאוּ אוֹתָהּ שְׁנַיִם בְּמוֹט וְנִשְׁבְּרָה מְשַׁלְּמִין חֲצִי דָּמֶיהָ הוֹאִיל וּמַשּׂוֹי זֶה גָּדוֹל לְגַבֵּי אֶחָד וְקַל לְגַבֵּי שְׁנַיִם הֲרֵי הוּא כְּאֹנֶס וְאֵינוֹ אֹנֶס וּמְשַׁלְּמִין מֶחֱצָה אִם יֵשׁ עֵדִים שֶׁלֹּא פָּשְׁעוּ בָּהּ. נִשְׁבְּרָה בְּמָקוֹם שֶׁאֵין הָעֵדִים מְצוּיִין נִשְׁבָּעִין שֶׁלֹּא שְׁבָרוּהָ בִּפְשִׁיעָה וּמְשַׁלְּמִין חֲצִי דָּמֶיהָ. שֶׁהֲרֵי לֹא הָיָה לְכָל אֶחָד לְהַעֲבִיר אֶלָּא מַשּׂוֹי שֶׁיָּכוֹל לְהַעֲבִירוֹ בִּפְנֵי עַצְמוֹ. מִכָּאן אַתָּה לָמֵד שֶׁהָאֶחָד שֶׁהֶעֱבִיר חָבִית גְּדוֹלָה שֶׁאֵין דֶּרֶךְ כָּל הַסַּבָּלִים לְהַעֲבִירָהּ שֶׁהוּא פּוֹשֵׁעַ וְאִם נִשְׁבְּרָה בְּיָדוֹ מְשַׁלֵּם הַכּל:","הַסַּבָּל שֶׁשָּׁבַר חָבִית שֶׁל יַיִן לְחֶנְוָנִי וְנִתְחַיֵּב לְשַׁלֵּם וַהֲרֵי הִיא שָׁוָה בְּיוֹם הַשּׁוּק אַרְבָּעָה וּבִשְׁאָר הַיָּמִים שְׁלֹשָׁה אִם הֶחְזִירוֹ בְּיוֹם הַשּׁוּק חַיָּבִין לְהַחְזִיר חָבִית שֶׁל יַיִן אוֹ יְשַׁלְּמוּ לוֹ אַרְבָּעָה וְהוּא שֶׁלֹּא הָיָה לוֹ יַיִן לִמְכֹּר בְּיוֹם הַשּׁוּק אֲבָל אִם הָיָה לוֹ יַיִן מַחֲזִירִין לוֹ שְׁלֹשָׁה. הֶחְזִירוּ לוֹ בִּשְׁאָר הַיָּמִים מַחֲזִירִין לוֹ שְׁלֹשָׁה וּמְנַכִּין לוֹ בְּכָל זְמַן טֹרַח שֶׁהָיָה טוֹרֵחַ בִּמְכִירָתָהּ וּפְגַם הַנֶּקֶב שֶׁהָיָה נוֹקֵב הֶחָבִית וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","רוֹעֶה שֶׁבָּאוּ זְאֵבִים וְטָרְפוּ מִמֶּנּוּ אִם הָיָה זְאֵב אֶחָד אֵין זֶה אֹנֶס אֲפִלּוּ בִּשְׁעַת מִשְׁלַחַת זְאֵבִים. וְאִם הָיוּ שְׁנֵי זְאֵבִים הֲרֵי זֶה אֹנֶס. שְׁנֵי כְּלָבִים אֵינָן אֹנֶס אֲפִלּוּ בָּאוּ מִשְּׁתֵי רוּחוֹת. הָיוּ יֶתֶר עַל שְׁנַיִם הֲרֵי זֶה אֹנֶס. לִסְטִים מְזֻיָּן הֲרֵי הוּא אֹנֶס וַאֲפִלּוּ הָיָה הָרוֹעֶה מְזֻיָּן וּבָא לוֹ לִסְטִים אַחֵר מְזֻיָּן הֲרֵי זֶה אֹנֶס שֶׁאֵין הָרוֹעֶה מוֹסֵר נַפְשׁוֹ כְּלִסְטִים. הָאֲרִי וְהַדֹּב וְהַנָּמֵר וְהַבַּרְדְּלָס וְהַנָּחָשׁ הֲרֵי אֵלּוּ אֳנָסִין. אֵימָתַי בִּזְמַן שֶׁבָּאוּ מֵאֲלֵיהֶן. אֲבָל אִם הוֹלִיכָם לִמְקוֹם גְּדוּדֵי חַיּוֹת וְלִיסְטִים אֵין אֵלּוּ אֳנָסִין וְחַיָּב לְשַׁלֵּם:","רוֹעֶה שֶׁמָּצָא גַּנָּב וְהִתְחִיל לְהִתְגָּרוֹת בּוֹ וּלְהַרְאוֹתוֹ שֶׁאֵינוֹ חוֹשֵׁשׁ מִמֶּנּוּ וְאָמַר לוֹ הֲרֵי אָנוּ בְּמָקוֹם פְּלוֹנִי וְכָךְ וְכָךְ רוֹעִים אֲנַחְנוּ וְכָךְ וְכָךְ כְּלֵי מִלְחָמָה יֵשׁ לָנוּ וּבָא אוֹתוֹ הַלִּסְטִים וְנִצְּחוֹ וְלָקַח מֵהֶן הֲרֵי הָרוֹעֶה חַיָּב שֶׁאֶחָד הַמּוֹלִיךְ אֶת הַבְּהֵמָה לִמְקוֹם גְּדוּדֵי חַיּוֹת וְלִסְטִים אוֹ מֵבִיא אֶת הַלִּסְטִים בְּהִתְגָּרוּתוֹ לִמְקוֹם הַבְּהֵמָה:","רוֹעֶה שֶׁהָיָה לוֹ לְהַצִּיל הַטְּרֵפָה אוֹ הַשְּׁבוּיָה בְּרוֹעִים אֲחֵרִים וּבְמַקְלוֹת וְלֹא קָרָא רוֹעִים אֲחֵרִים וְלֹא הֵבִיא מַקְלוֹת לְהַצִּיל הֲרֵי זֶה חַיָּב אֶחָד שׁוֹמֵר חִנָּם וְאֶחָד שׁוֹמֵר שָׂכָר אֶלָּא שֶׁשּׁוֹמֵר חִנָּם קוֹרֵא רוֹעִים וּמֵבִיא מַקְלוֹת בְּחִנָּם וְאִם לֹא מָצָא פָּטוּר אֲבָל שׁוֹמֵר שָׂכָר חַיָּב לִשְׂכֹּר הָרוֹעִים וְהַמַּקְלוֹת עַד כְּדֵי דְּמֵי הַבְּהֵמָה כְּדֵי לְהַצִּיל וְחוֹזֵר וְלוֹקֵחַ שְׂכָרָן מִבַּעַל הַבַּיִת. וְאִם לֹא עָשָׂה כֵן וְהָיָה לוֹ לִשְׂכֹּר וְלֹא שָׂכַר הֲרֵי זֶה פּוֹשֵׁעַ וְחַיָּב:","רוֹעֶה שֶׁטָּעַן שֶׁהִצַּלְתִּי עַל יְדֵי רוֹעִים בְּשָׂכָר נִשְׁבָּע וְנוֹטֵל מַה שֶּׁטָּעַן שֶׁאֵינוֹ יָכוֹל לִטְעֹן אֶלָּא עַד כְּדֵי דְּמֵיהֶן וְיָכוֹל הָיָה לוֹמַר נִטְרְפָה וְיִשָּׁבַע בִּנְקִיטַת חֵפֶץ כְּדִין כָּל הַנִּשְׁבָּעִין וְנוֹטְלִין:","רוֹעֶה שֶׁהִנִּיחַ עֶדְרוֹ וּבָא לָעִיר בֵּין בְּעֵת שֶׁדֶּרֶךְ הָרוֹעִים לְהִכָּנֵס וּבֵין בְּעֵת שֶׁאֵין דֶּרֶךְ הָרוֹעִים לְהִכָּנֵס וּבָאוּ זְאֵבִים וּטְרָפוֹ אֲרִי וְדָרַס אֵין אוֹמְרִים אִלּוּ הָיָה שָׁם הָיָה מַצִּיל אֶלָּא אוֹמְדִין אוֹתוֹ אִם יָכוֹל לְהַצִּיל עַל יְדֵי רוֹעִים וּמַקְלוֹת חַיָּב וְאִם לָאו פָּטוּר וְאִם אֵין הַדָּבָר יָדוּעַ חַיָּב לְשַׁלֵּם:","מֵתָה הַבְּהֵמָה כְּדַרְכָּהּ הֲרֵי זֶה אֹנֶס וְהָרוֹעֶה פָּטוּר. סִגְפָהּ וּמֵתָה אֵינוֹ אֹנֶס. תְּקָפַתּוּ וְעָלְתָה לְרָאשֵׁי צוּקִין וּתְקָפַתּוּ וְנָפְלָה הֲרֵי זֶה אֹנֶס. הֶעֱלָהּ לְרָאשֵׁי צוּקִין אוֹ שֶׁעָלְתָה מֵאֵלֶיהָ וְהוּא יָכוֹל לְמָנְעָהּ וְלֹא מְנָעָהּ אַף עַל פִּי שֶׁתְּקָפַתּוּ וְנָפְלָה וּמֵתָה אוֹ נִשְׁבְּרָה חַיָּב שֶׁכָּל שֶׁתְּחִלָּתוֹ בִּפְשִׁיעָה וְסוֹפוֹ בְּאֹנֶס חַיָּב. וְכֵן רוֹעֶה שֶׁהֶעֱבִיר הַבְּהֵמוֹת עַל הַגֶּשֶׁר וְדָחֲפָה אַחַת מֵהֶן לַחֲבֵרְתָהּ וְנָפְלָה לְשִׁבּלֶת הַנָּהָר הֲרֵי זֶה חַיָּב שֶׁהָיָה לוֹ לְהַעֲבִירָן אַחַת אַחַת שֶׁאֵין הַשּׁוֹמֵר נוֹטֵל שָׂכָר אֶלָּא לִשְׁמֹר שְׁמִירָה מְעֵלָּה וְהוֹאִיל וּפָשַׁע בַּתְּחִלָּה וְהֶעֱבִירָן כְּאֶחָד אַף עַל פִּי שֶׁנֶּאֱנַס בַּסּוֹף בְּעֵת הַנְּפִילָה הֲרֵי הוּא חַיָּב:","פָּשַׁע בָּהּ וְיָצְאָה לַאֲגַם וּמֵתָה שָׁם כְּדַרְכָּהּ פָּטוּר שֶׁאֵין יְצִיאָתָהּ גָּרְמָה לָהּ שֶׁתָּבוֹא לִידֵי אֹנֶס זֶה הוֹאִיל וּכְדַרְכָּהּ מֵתָה מַה לִּי בְּבֵית שׁוֹמֵר מַה לִּי בָּאֲגַם. אֲבָל אִם גְּנָבָהּ גַּנָּב מֵהָאֲגַם וּמֵתָה כְּדַרְכָּהּ בְּבֵית הַגַּנָּב הֲרֵי הַשּׁוֹמֵר חַיָּב אַף עַל פִּי שֶׁהוּא שׁוֹמֵר חִנָּם שֶׁאֲפִלּוּ לֹא מֵתָה הֲרֵי הִיא אֲבֵדָה בְּיַד הַגַּנָּב וִיצִיאָתָהּ גָּרְמָה לָהּ לְהִגָּנֵב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Human Dispositions 6":["דֶרֶךְ בְּרִיָּתוֹ שֶׁל אָדָם לִהְיוֹת נִמְשָׁךְ בְּדֵעוֹתָיו וּבְמַעֲשָׂיו אַחַר רֵעָיו וַחֲבֵרָיו וְנוֹהֵג כְּמִנְהַג אַנְשֵׁי מְדִינָתוֹ. לְפִיכָךְ צָרִיךְ אָדָם לְהִתְחַבֵּר לַצַּדִּיקִים וִלֵישֵׁב אֵצֵל הַחֲכָמִים תָּמִיד כְּדֵי שֶׁיִּלְמַד מִמַּעֲשֵׂיהֶם. וִיִתִרַחֵק מִן הָרְשָׁעִים הַהוֹלְכִים בַּחשֶׁךְ כְּדֵי שֶׁלֹּא יִלְמֹד מִמַּעֲשֵׂיהֶם. הוּא שֶׁשְּׁלֹמֹה אוֹמֵר (משלי יג כ) \"הוֹלֵךְ אֶת חֲכָמִים יֶחְכָּם וְרֹעֶה כְסִילִים יֵרוֹעַ\". וְאוֹמֵר אַשְׁרֵי הָאִישׁ וְגוֹ'. וְכֵן אִם הָיָה בִּמְדִינָה שֶׁמִּנְהֲגוֹתֶיהָ רָעִים וְאֵין אֲנָשֶׁיהָ הוֹלְכִים בְּדֶרֶךְ יְשָׁרָה יֵלֵךְ לְמָקוֹם שֶׁאֲנָשֶׁיהָ צַדִּיקִים וְנוֹהֲגִים בְּדֶרֶךְ טוֹבִים. וְאִם הָיוּ כָּל הַמְּדִינוֹת שֶׁהוּא יוֹדְעָם וְשׁוֹמֵעַ שְׁמוּעָתָן נוֹהֲגִים בְּדֶרֶךְ לֹא טוֹבָה כְּמוֹ זְמַנֵּנוּ. אוֹ שֶׁאֵינוֹ יָכוֹל לָלֶכֶת לִמְדִינָה שֶׁמִּנְהֲגוֹתֶיהָ טוֹבִים מִפְּנֵי הַגְּיָסוֹת אוֹ מִפְּנֵי הַחֹלִי יֵשֵׁב לְבַדּוֹ יְחִידִי כָּעִנְיָן שֶׁנֶּאֱמַר (איכה ג כח) \"יֵשֵׁב בָּדָד וְיִדֹּם\". וְאִם הָיוּ רָעִים וְחַטָּאִים שֶׁאֵין מְנִיחִים אוֹתוֹ לֵישֵׁב בַּמְּדִינָה אֶלָּא אִם כֵּן נִתְעָרֵב עִמָּהֶן וְנוֹהֵג בְּמִנְהָגָם הָרַע יֵצֵא לַמְּעָרוֹת וְלַחֲוָחִים וְלַמִּדְבָּרוֹת. וְאַל יַנְהִיג עַצְמוֹ בְּדֶרֶךְ חַטָּאִים כָּעִנְיָן שֶׁנֶּאֱמַר (ירמיה ט א) \"מִי יִתְּנֵנִי בַמִּדְבָּר מְלוֹן אֹרְחִים\":","מִצְוַת עֲשֵׂה לְהִדָּבֵק בַּחֲכָמִים וְתַלְמִידֵיהֶם כְּדֵי לִלְמֹד מִמַּעֲשֵׂיהֶם כָּעִנְיָן שֶׁנֶּאֱמַר וּבוֹ תִדְבָּק. וְכִי אֶפְשָׁר לָאָדָם לְהִדָּבֵק בַּשְּׁכִינָה. אֶלָּא כָּךְ אָמְרוּ חֲכָמִים בְּפֵרוּשׁ מִצְוָה זוֹ, הִדָּבֵק בַּחֲכָמִים וְתַלְמִידֵיהֶם. לְפִיכָךְ צָרִיךְ אָדָם לְהִשְׁתַּדֵּל שֶׁיִּשָּׂא בַּת תַּלְמִיד חָכָם וְיַשִּׂיא בִּתּוֹ לְתַלְמִיד חָכָם וְלֶאֱכֹל וְלִשְׁתּוֹת עִם תַּלְמִידֵי חֲכָמִים וְלַעֲשׂוֹת פְּרַקְמַטְיָא לְתַלְמִיד חָכָם וּלְהִתְחַבֵּר לָהֶן בְּכָל מִינֵי חִבּוּר שֶׁנֶּאֱמַר וּלְדָבְקָה בּוֹ. וְכֵן צִוּוּ חֲכָמִים וְאָמְרוּ (משנה אבות א ד) \"וֶהֱוֵי מִתְאַבֵּק בַּעֲפַר רַגְלֵיהֶם וְשׁוֹתֶה בַּצָּמָא אֶת דִּבְרֵיהֶם\":","מִצְוָה עַל כָּל אָדָם לֶאֱהֹב אֶת כָּל אֶחָד וְאֶחָד מִיִּשְׂרָאֵל כְּגוּפוֹ שֶׁנֶּאֱמַר (ויקרא יט יח) \"וְאָהַבְתָּ לְרֵעֲךָ כָּמוֹךָ\". לְפִיכָךְ צָרִיךְ לְסַפֵּר בְּשִׁבְחוֹ וְלָחוּס עַל מָמוֹנוֹ כַּאֲשֶׁר הוּא חָס עַל מָמוֹן עַצְמוֹ וְרוֹצֶה בִּכְבוֹד עַצְמוֹ. וְהַמִּתְכַּבֵּד בִּקְלוֹן חֲבֵרוֹ אֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא:","אַהֲבַת הַגֵּר שֶׁבָּא וְנִכְנָס תַּחַת כַּנְפֵי הַשְּׁכִינָה שְׁתֵּי מִצְוֹת עֲשֵׂה. אַחַת מִפְּנֵי שֶׁהוּא בִּכְלַל רֵעִים וְאַחַת מִפְּנֵי שֶׁהוּא גֵּר וְהַתּוֹרָה אָמְרָה (דברים י יט) \"וַאֲהַבְתֶּם אֶת הַגֵּר\". צִוָּה עַל אַהֲבַת הַגֵּר כְּמוֹ שֶׁצִּוָּה עַל אַהֲבַת עַצְמוֹ שֶׁנֶּאֱמַר (דברים ו ה) \"וְאָהַבְתָּ אֵת ה' אֱלֹהֶיךָ\". הַקָּדוֹשׁ בָּרוּךְ הוּא עַצְמוֹ אוֹהֵב גֵּרִים שֶׁנֶּאֱמַר (דברים י יח) \"וְאֹהֵב גֵּר\":","כָּל הַשּׂוֹנֵא אֶחָד מִיִּשְׂרָאֵל בְּלִבּוֹ עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (ויקרא יט יז) \"לֹא תִשְׂנָא אֶת אָחִיךָ בִּלְבָבֶךָ\". וְאֵין לוֹקִין עַל לָאו זֶה לְפִי שֶׁאֵין בּוֹ מַעֲשֶׂה. וְלֹא הִזְהִירָה תּוֹרָה אֶלָּא עַל שִׂנְאָה שֶׁבַּלֵּב. אֲבָל הַמַּכֶּה אֶת חֲבֵרוֹ וְהַמְחָרְפוֹ אַף עַל פִּי שֶׁאֵינוֹ רַשַּׁאי אֵינוֹ עוֹבֵר מִשּׁוּם לֹא תִשְׂנָא:","כְּשֶׁיֶּחְטָא אִישׁ לְאִישׁ לֹא יִשְׂטְמֶנּוּ וְיִשְׁתֹּק כְּמוֹ שֶׁנֶּאֱמַר בָּרְשָׁעִים (שמואל ב יג כב) \"וְלֹא דִבֶּר אַבְשָׁלוֹם אֶת אַמְנוֹן מְאוּמָה לְמֵרָע וְעַד טוֹב כִּי שָׂנֵא אַבְשָׁלוֹם אֶת אַמְנוֹן\". אֶלָּא מִצְוָה עָלָיו לְהוֹדִיעוֹ וְלוֹמַר לוֹ לָמָּה עָשִׂיתָ לִי כָּךְ וְכָךְ וְלָמָּה חָטָאתָ לִי בְּדָבָר פְּלוֹנִי. שֶׁנֶּאֱמַר (ויקרא יט יז) \"הוֹכֵחַ תּוֹכִיחַ אֶת עֲמִיתֶךָ\". וְאִם חָזַר וּבִקֵּשׁ מִמֶּנּוּ לִמְחֹל לוֹ צָרִיךְ לִמְחֹל. וְלֹא יְהֵא הַמּוֹחֵל אַכְזָרִי שֶׁנֶּאֱמַר (בראשית כ יז) \"וַיִּתְפַּלֵּל אַבְרָהָם אֶל הָאֱלֹהִים\":","הָרוֹאֶה חֲבֵרוֹ שֶׁחָטָא אוֹ שֶׁהָלַךְ בְּדֶרֶךְ לֹא טוֹבָה מִצְוָה לְהַחֲזִירוֹ לַמּוּטָב וּלְהוֹדִיעוֹ שֶׁהוּא חוֹטֵא עַל עַצְמוֹ בְּמַעֲשָׂיו הָרָעִים שֶׁנֶּאֱמַר (ויקרא יט יז) \"הוֹכֵחַ תּוֹכִיחַ אֶת עֲמִיתֶךָ\". הַמּוֹכִיחַ אֶת חֲבֵרוֹ. בֵּין בִּדְבָרִים שֶׁבֵּינוֹ לְבֵינוֹ. בֵּין בִּדְבָרִים שֶׁבֵּינוֹ לְבֵין הַמָּקוֹם. צָרִיךְ לְהוֹכִיחוֹ בֵּינוֹ לְבֵין עַצְמוֹ. וִידַבֵּר לוֹ בְּנַחַת וּבְלָשׁוֹן רַכָּה וְיוֹדִיעוֹ שֶׁאֵינוֹ אוֹמֵר לוֹ אֶלָּא לְטוֹבָתוֹ לַהֲבִיאוֹ לְחַיֵּי הָעוֹלָם הַבָּא. אִם קִבֵּל מִמֶּנּוּ מוּטָב וְאִם לָאו יוֹכִיחֶנּוּ פַּעַם שְׁנִיָּה וּשְׁלִישִׁית. וְכֵן תָּמִיד חַיָּב אָדָם לְהוֹכִיחוֹ עַד שֶׁיַּכֵּהוּ הַחוֹטֵא וְיֹאמַר לוֹ אֵינִי שׁוֹמֵעַ. וְכָל שֶׁאֶפְשָׁר בְּיָדוֹ לִמְחוֹת וְאֵינוֹ מוֹחֶה הוּא נִתְפָּשׂ בַּעֲוֹן אֵלּוּ כֵּיוָן שֶׁאֶפְשָׁר לוֹ לִמְחוֹת בָּהֶם:","הַמּוֹכִיחַ אֶת חֲבֵרוֹ תְּחִלָּה לֹא יְדַבֵּר לוֹ קָשׁוֹת עַד שֶׁיַּכְלִימֶנּוּ שֶׁנֶּאֱמַר (ויקרא יט יז) \"וְלֹא תִשָּׂא עָלָיו חֵטְא\". כָּךְ אָמְרוּ חֲכָמִים יָכוֹל אַתָּה מוֹכִיחוֹ וּפָנָיו מִשְׁתַּנּוֹת תַּלְמוּד לוֹמַר וְלֹא תִשָּׂא עָלָיו חֵטְא. מִכָּאן שֶׁאָסוּר לָאָדָם לְהַכְלִים אֶת יִשְׂרָאֵל וְכָל שֶׁכֵּן בָּרַבִּים. אַף עַל פִּי שֶׁהַמַּכְלִים אֶת חֲבֵרוֹ אֵינוֹ לוֹקֶה עָלָיו עָוֹן גָּדוֹל הוּא. כָּךְ אָמְרוּ חֲכָמִים (גמרא סנהדרין קז א) \"הַמַּלְבִּין פְּנֵי חֲבֵרוֹ בָּרַבִּים אֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא\". לְפִיכָךְ צָרִיךְ אָדָם לְהִזָּהֵר שֶׁלֹּא לְבַיֵּשׁ חֲבֵרוֹ בָּרַבִּים בֵּין קָטָן בֵּין גָּדוֹל. וְלֹא יִקְרָא לוֹ בְּשֵׁם שֶׁהוּא בּוֹשׁ מִמֶּנּוּ. וְלֹא יְסַפֵּר לְפָנָיו דָּבָר שֶׁהוּא בּוֹשׁ מִמֶּנּוּ. בַּמֶּה דְּבָרִים אֲמוּרִים בִּדְבָרִים שֶׁבֵּין אָדָם לַחֲבֵרוֹ. אֲבָל בְּדִבְרֵי שָׁמַיִם אִם לֹא חָזַר בּוֹ בַּסֵּתֶר מַכְלִימִין אוֹתוֹ בָּרַבִּים וּמְפַרְסְמִים חֶטְאוֹ וּמְחָרְפִים אוֹתוֹ בְּפָנָיו וּמְבַזִּין וּמְקַלְּלִין אוֹתוֹ עַד שֶׁיַּחֲזֹר לַמּוּטָב כְּמוֹ שֶׁעָשׂוּ כָּל הַנְּבִיאִים בְּיִשְׂרָאֵל:","מִי שֶׁחָטָא עָלָיו חֲבֵרוֹ וְלֹא רָצָה לְהוֹכִיחוֹ וְלֹא לְדַבֵּר לוֹ כְּלוּם מִפְּנֵי שֶׁהָיָה הַחוֹטֵא הֶדְיוֹט בְּיוֹתֵר. אוֹ שֶׁהָיְתָה דַּעְתּוֹ מְשֻׁבֶּשֶׁת. וּמָחַל לוֹ בְּלִבּוֹ וְלֹא שְׂטָמוֹ וְלֹא הוֹכִיחוֹ הֲרֵי זוֹ מִדַּת חֲסִידוּת. לֹא הִקְפִּידָה תּוֹרָה אֶלָּא עַל הַמַּשְׂטֵמָה:","חַיָּב אָדָם לְהִזָּהֵר בִּיתוֹמִים וְאַלְמָנוֹת מִפְּנֵי שֶׁנַּפְשָׁן שְׁפָלָה לִמְאֹד וְרוּחָם נְמוּכָה אַף עַל פִּי שֶׁהֵן בַּעֲלֵי מָמוֹן. אֲפִלּוּ אַלְמָנָתוֹ שֶׁל מֶלֶךְ וִיתוֹמָיו מֻזְהָרִים אָנוּ עֲלֵיהֶן שֶׁנֶּאֱמַר (שמות כב כא) \"כָּל אַלְמָנָה וְיָתוֹם לֹא תְעַנּוּן\". וְהֵיאַךְ נוֹהֲגִין עִמָּהֶן. לֹא יְדַבֵּר אֲלֵיהֶם אֶלָּא רַכּוֹת. וְלֹא יִנְהֹג בָּהֶן אֶלָּא מִנְהַג כָּבוֹד. וְלֹא יַכְאִיב גּוּפָם בַּעֲבוֹדָה וְלִבָּם בִּדְבָרִים קָשִׁים. וְיָחוּס עַל מָמוֹנָם יוֹתֵר מִמָּמוֹן עַצְמוֹ. כָּל הַמַּקְנִיטָן אוֹ מַכְעִיסָן אוֹ הִכְאִיב לָהֶן אוֹ רָדָה בָּהֶן אוֹ אִבֵּד מָמוֹנָן הֲרֵי זֶה עוֹבֵר בְּלֹא תַּעֲשֶׂה וְכָל שֶׁכֵּן הַמַּכֶּה אוֹתָם אוֹ הַמְקַלְּלָן. וְלָאו זֶה אַף עַל פִּי שֶׁאֵין לוֹקִין עָלָיו הֲרֵי עָנְשׁוֹ מְפֹרָשׁ בַּתּוֹרָה (שמות כב כג) \"וְחָרָה אַפִּי וְהָרַגְתִּי אֶתְכֶם בֶּחָרֶב\". בְּרִית כָּרַת לָהֶן מִי שֶׁאָמַר וְהָיָה הָעוֹלָם שֶׁכָּל זְמַן שֶׁהֵם צוֹעֲקִים מֵחָמָס הֵם נַעֲנִים שֶׁנֶּאֱמַר (שמות כב כב) \"כִּי אִם צָעֹק יִצְעַק אֵלַי שָׁמֹעַ אֶשְׁמַע צַעֲקָתוֹ\". בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁעִנָּה אוֹתָן לְצֹרֶךְ עַצְמוֹ. אֲבָל עִנָּה אוֹתָם הָרַב כְּדֵי לְלַמְּדָן תּוֹרָה אוֹ אֻמָּנוּת אוֹ לְהוֹלִיכָן בְּדֶרֶךְ יְשָׁרָה הֲרֵי זֶה מֻתָּר. וְאַף עַל פִּי כֵן לֹא יִנְהֹג בָּהֶן מִנְהַג כָּל אָדָם אֶלָּא יַעֲשֶׂה לָהֶם הֶפְרֵשׁ וִינַהֲלֵם בְּנַחַת וּבְרַחֲמִים גְּדוֹלִים וְכָבוֹד שֶׁנֶּאֱמַר (משלי כב כג) \"כִּי ה' יָרִיב רִיבָם\". אֶחָד יָתוֹם מֵאָב וְאֶחָד יָתוֹם מֵאֵם. וְעַד אֵימָתַי נִקְרָאִים יְתוֹמִים לְעִנְיָן זֶה. עַד שֶׁלֹּא יִהְיוּ צְרִיכִין לְאָדָם גָּדוֹל לְהִסָּמֵךְ עָלָיו וּלְאָמְנָן וּלְהִטָּפֵל בָּהֶן אֶלָּא יִהְיֶה עוֹשֶׂה כָּל צָרְכֵי עַצְמוֹ לְעַצְמוֹ כִּשְׁאָר כָּל הַגְּדוֹלִים:"],"Mishneh Torah, Immersion Pools 9":["שֵׁשׁ מַעֲלוֹת בְּמִקְוָאוֹת זוֹ לְמַעְלָה מִזּוֹ. הָרִאשׁוֹן מֵי גְּבָאִים. וּמֵי בּוֹרוֹת שִׁיחִין וּמְעָרוֹת. וְכַיּוֹצֵא בָּהֶן מִמַּיִם הַמְכֻנָּסִין בַּקַּרְקַע אַף עַל פִּי שֶׁהֵן שְׁאוּבִין וְאַף עַל פִּי שֶׁאֵין בָּהֶן אַרְבָּעִים סְאָה הוֹאִיל וְאֵינָן מִתְטַמְּאִין אֶלָּא לְרָצוֹן כְּמוֹ שֶׁבֵּאַרְנוּ הֲרֵי הֵן בְּחֶזְקַת טְהוֹרִין וּכְשֵׁרִין לַעֲשׂוֹת מֵהֶן עִסָּה הַטְּבוּלָה לְחַלָּה וְלִטּל מֵהֶן לַיָּדַיִם וְהוּא שֶׁיִּטּל מֵהֶן בִּכְלִי כְּמוֹ שֶׁבֵּאַרְנוּ:","לְמַעְלָה מֵהֶן מֵי תַּמְצִית שֶׁלֹּא פָּסְקוּ אֶלָּא עֲדַיִן הַגְּשָׁמִים יוֹרְדִין וְהֶהָרִים בּוֹצְצִין וְהֵן נִמְשָׁכִין וְנִקְוִין וְאֵינָן שְׁאוּבִין אֲבָל אֵין בָּהֶן אַרְבָּעִים סְאָה הֲרֵי הֵן כְּשֵׁרִין לִתְרוּמָה וְלִטּל מֵהֶן לַיָּדַיִם וּמַטְבִּיל בָּהֶן אֶת הַמַּיִם שֶׁנִּטְמְאוּ. פָּסְקוּ הַגְּשָׁמִים וְלֹא פָּסְקוּ הֶהָרִים מִלְּהַזְחִיל עֲדַיִן הֵן מֵי תַּמְצִית. פָּסְקוּ הֶהָרִים וְאֵינָן בּוֹצְצִין הֲרֵי אֵלּוּ כְּמֵי גְּבָאִין:","הַחוֹפֵר בְּצַד הַיָּם וּבְצַד הַנָּהָר וּבִמְקוֹם הַבֵּצִין הֲרֵי הֵן כְּמֵי תַּמְצִית שֶׁלֹּא פָּסְקוּ:","הַחוֹפֵר בְּצַד הַמַּעְיָן כָּל זְמַן שֶׁהָיוּ בָּאִין מֵחֲמַת הַמַּעְיָן אַף עַל פִּי שֶׁפּוֹסְקִין וְחוֹזְרִין וּמוֹשְׁכִין הֲרֵי הֵן כְּמֵי מַעְיָן. פָּסְקוּ מִלִּהְיוֹת מוֹשְׁכִין הֲרֵי הֵן כְּמֵי גְּבָאִין:","לְמַעְלָה מֵהֶן מִקְוֶה שֶׁיֵּשׁ בּוֹ אַרְבָּעִים סְאָה מַיִם שֶׁאֵינָם שְׁאוּבִין שֶׁבּוֹ טוֹבֵל כָּל אָדָם טָמֵא חוּץ מִן הַזָּב הַזָּכָר וּבוֹ מַטְבִּילִין אֶת כָּל הַכֵּלִים הַטְּמֵאִים וְאֶת הַיָּדָיִם שֶׁמַּטְבִּילִין לְקֹדֶשׁ כְּמוֹ שֶׁבֵּאַרְנוּ:","לְמַעְלָה מִזֶּה הַמַּעְיָן שֶׁמֵּימָיו מוּעָטִין וְהִרְבּוּ עָלָיו מַיִם שְׁאוּבִין שָׁוֶה לְמִקְוֶה שֶׁאֵין מְטַהֲרִין בְּמַיִם הַנִּמְשָׁכִין מִמֶּנּוּ אֶלָּא בְּמַיִם הַנִּקְוִין וְעוֹמְדִין בְּאֶשְבּוֹרֶן וְשָׁוֶה לַמַּעְיָן שֶׁהוּא מְטַהֵר בְּכָל שֶׁהוּא שֶׁהַמַּעְיָן אֵין לְמֵימָיו שִׁעוּר אֲפִלּוּ כָּל שֶׁהֵן מְטַהֲרִין:","לְמַעְלָה מִזֶּה הַמַּעְיָן שֶׁלֹּא נִתְעָרֵב בּוֹ מַיִם שְׁאוּבִין אֲבָל מֵימָיו מֻכִּים כְּגוֹן שֶׁהָיוּ מֵימָיו מָרִים אוֹ מְלוּחִים שֶׁהֲרֵי הוּא מְטַהֵר בְּזוֹחֲלִים וְהֵן הַמַּיִם הַנִּגְרָרִים וְנִמְשָׁכִין מִן הַמַּעְיָן:","לְמַעְלָה מִזֶּה הַמַּעְיָן שֶׁמֵּימָיו מַיִם חַיִּים שֶׁבָּהֶן בִּלְבַד טוֹבְלִים בּוֹ הַזָּבִים הַזְּכָרִים וְלוֹקְחִין מֵהֶן לְטָהֳרַת הַמְצֹרָע וּלְקַדֵּשׁ מֵי חַטָּאת. מַה בֵּין מַעְיָן לְמִקְוֶה הַמִּקְוֶה אֵינוֹ מְטַהֵר אֶלָּא בְּאַרְבָּעִים סְאָה וְהַמַּעְיָן מְטַהֵר בְּכָל שֶׁהוּא. הַמִּקְוֶה אֵינוֹ מְטַהֵר אֶלָּא בְּאֶשְבּוֹרֶן וְהַמַּיִם הַנִּזְחָלִים מִמֶּנּוּ אֵינָן מְטַהֲרִין וְהַמַּעְיָן מְטַהֵר בְּזוֹחֲלִים. הַמִּקְוֶה לֹא תַּעֲלֶה בּוֹ טְבִילָה לְזָבִים וְהַמַּעְיָן אִם הָיוּ מֵימָיו מַיִם חַיִּים הַזָּב טוֹבֵל בָּהֶן:","מַעְיָן שֶׁמֵּימָיו יוֹצְאִין וְנִמְשָׁכִין לְתוֹךְ הַשֹּׁקֶת וְאַחַר כָּךְ יוֹצְאִין מִן הַשֹּׁקֶת וְנִזְחָלִין הֲרֵי כָּל הַמַּיִם שֶׁבַּשֹּׁקֶת וְשֶׁחוּץ לוֹ פְּסוּלִין. הָיוּ מִקְצָתָן נִמְשָׁכִין עַל שְׂפַת הַשֹּׁקֶת אֲפִלּוּ כָּל שֶׁהוּא הֲרֵי הַמַּיִם שֶׁחוּץ לַשֹּׁקֶת כְּשֵׁרִים שֶׁהַמַּעְיָן מְטַהֵר בְּכָל שֶׁהוּא. הָיוּ מֵימָיו נִמְשָׁכִין לְתוֹךְ בְּרֵכָה שֶׁהִיא מַיִם וְנִקְוִין שָׁם הֲרֵי אוֹתָהּ הַבְּרֵכָה כְּמִקְוֶה. הָיָה יוֹצֵא חוּץ לַבְּרֵכָה הֲרֵי זֶה פָּסוּל לְזָבִים וְלִמְצֹרָעִים וּלְקַדֵּשׁ מֵי חַטָּאת עַד שֶׁיֵּדַע שֶׁיָּצְאוּ כָּל מֵי הַמִּקְוֶה שֶׁהָיוּ בְּתוֹךְ הַבְּרֵכָה:","מַעְיָן שֶׁמֵּימָיו נִמְשָׁכִין עַל גַּבֵּי כֵּלִים שֶׁאֵין לָהֶן בֵּית קִבּוּל כְּגוֹן שֻׁלְחָן וְסַפְסָל וְכַיּוֹצֵא בָּהֶן הֲרֵי זֶה כְּמִקְוֶה וּבִלְבַד שֶׁלֹּא יַטְבִּיל עַל גַּבֵּי הַכֵּלִים:","מַעְיָן שֶׁהָיוּ אַמּוֹת קְטַנּוֹת נִמְשָׁכוֹת מִמֶּנּוּ וְרִבָּה עָלָיו מַיִם שְׁאוּבִין לְתוֹךְ הַמַּעְיָן עַד שֶׁגָּבְרוּ הַמַּיִם שֶׁבָּאַמּוֹת וְשָׁטְפוּ הֲרֵי הֵן כְּמַעְיָן לְכָל דָּבָר. הָיוּ מֵימֵי הַמַּעְיָן עוֹמְדִים וְאֵינָן נִמְשָׁכִין וְרִבָּה עָלָיו מַיִם עַד שֶׁמָּשְׁכוּ מִמֶּנּוּ אַמּוֹת הַמַּיִם הֲרֵי הַמַּיִם שֶׁמְּשׁוּכִין שָׁוִין לַמִּקְוֶה לְטַהֵר בָּאֶשְבּוֹרֶן בִּלְבַד וְשָׁוִין לַמַּעְיָן לְטַהֵר בְּכָל שֶׁהוּא:","כָּל הַיַּמִים מְטַהֲרִין בְּזוֹחֲלִין וּפְסוּלִין לְזָבִים וְלִמְצֹרָעִים וּלְקַדֵּשׁ בָּהֶן מֵי חַטָּאת:","הַמַּיִם הַזּוֹחֲלִין מִן הַמַּעְיָן הֲרֵי הֵם כְּמַעְיָן לְכָל דָּבָר. וְהַמְנַטְּפִין מִן הַמַּעְיָן אַף עַל פִּי שֶׁהֵן טוֹרְדִין הֲרֵי הֵם כְּמִקְוֶה וְאֵין מְטַהֲרִין אֶלָּא בְּאַרְבָּעִים סְאָה עוֹמְדִין. וּפְסוּלִין לְזָבִים וְלִמְצֹרָעִים וּלְקַדֵּשׁ בָּהֶן מֵי חַטָּאת. הָיוּ הַזּוֹחֲלִין מִן הַמַּעְיָן מִתְעָרְבִין עִם הַנּוֹטְפִין [מִמֶּנּוּ אִם רַבּוּ הַזּוֹחֲלִין עַל הַנּוֹטְפִין] הֲרֵי הַכּל כְּמַעְיָן לְכָל דָּבָר. וְאִם רַבּוּ הַנּוֹטְפִים עַל הַזּוֹחֲלִין וְכֵן אִם רַבּוּ מֵי גְּשָׁמִים עַל מֵי הַנָּהָר אֵינָן מְטַהֲרִין בְּזוֹחֲלִין אֶלָּא בְּאֶשְבּוֹרֶן. לְפִיכָךְ צָרִיךְ לְהַקִּיף מַפָּץ וְכַיּוֹצֵא בּוֹ בְּאוֹתוֹ הַנָּהָר הַמְעֹרָב עַד שֶׁיִּקָּווּ הַמַּיִם וְיִטְבּל בָּהֶן:","נוֹטְפִין שֶׁעֲשָׂאָן זוֹחֲלִין כְּגוֹן שֶׁסָּמַךְ לְמִקְוֶה הַמְנַטֵּף טַבְלָא שֶׁל חֶרֶס חֲלָקָה וַהֲרֵי הַמַּיִם נִזְחָלִין וְיוֹרְדִין עָלֶיהָ הֲרֵי הֵן כְּשֵׁרִין. וְכָל דָּבָר שֶׁמְּקַבֵּל טֻמְאָה וַאֲפִלּוּ מִדִּבְרֵי סוֹפְרִים אֵין מַזְחִילִין בּוֹ:","זוֹחֲלִין שֶׁקִּלְּחָן בַּעֲלֵי אֱגוֹז כְּשֵׁרִים כְּשֶׁהָיוּ שֶׁאֵין עֲלֵי הָאֱגוֹז הַלַּח שֶׁהוּא צוֹבֵעַ חָשׁוּב כְּכֵלִים:","מֵי גְּשָׁמִים הַבָּאִין מִן הַמִּדְרוֹן וְהִנָּם נִזְחָלִין וְיוֹרְדִין אַף עַל פִּי שֶׁהָיוּ מִתְּחִלָּתָן וְעַד סוֹפָן אַרְבָּעִים סְאָה אֵין מַטְבִּילִין בָּהֶן כְּשֶׁהֵן נִזְחָלִין עַד שֶׁיִּקָּווּ וְיָנוּחוּ בְּאֶשְבּוֹרֶן אַרְבָּעִים סְאָה. הֲרֵי שֶׁהִקִּיף כֵּלִים וְעָשָׂה מֵהֶן מְחִצּוֹת עַד שֶּׁנִּתְקַבֵּץ בֵּינֵיהֶן אַרְבָּעִים סְאָה מִמַּיִם הַנִּזְחָלִין מִן הַגְּשָׁמִים הֲרֵי זֶה טוֹבֵל בָּהֶן. וְכֵלִים שֶׁעָשָׂה מֵהֶן הַגָּדֵר לֹא עָלְתָה לָהֶן טְבִילָה:","גַּל שֶׁנִּתְלַשׁ מִן הַיָּם וְנָפַל עַל הָאָדָם אוֹ עַל הַכֵּלִים אִם יֵשׁ בּוֹ אַרְבָּעִים סְאָה הֲרֵי אֵלּוּ טְהוֹרִין לְחֻלִּין שֶׁאֵין הַטּוֹבֵל לְחֻלִּין צָרִיךְ כַּוָּנָה כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת שְׁאָר אָבוֹת הַטֻּמְאוֹת. וְאִם נִתְכַּוֵּן וְהָיָה יוֹשֵׁב וּמְצַפֶּה עַד שֶׁיִּפּל עָלָיו הַגַּל עָלְתָה לוֹ טְבִילָה לְדָבָר שֶׁנִּתְכַּוֵּן לוֹ:","אֵין מַטְבִּילִין בְּגַל כְּשֶׁהוּא בָּאֲוִיר קֹדֶם שֶׁיִּפּל עַל הָאָרֶץ וְאַף עַל פִּי שֶׁיֵּשׁ בּוֹ אַרְבָּעִים סְאָה. לְפִי שֶׁאֵין מַטְבִּילִין בְּזוֹחֲלִים קַל וָחֹמֶר בָּאֲוִיר. הָיוּ שְׁנֵי רָאשֵׁי הַגַּל נוֹגְעִין בָּאָרֶץ מַטְבִּילִין בּוֹ וְאֵין מַטְבִּילִין בַּכִּפָּה שֶׁלּוֹ מִפְּנֵי שֶׁהוּא אֲוִיר:"],"Mishneh Torah, Kings and Wars 1":["שָׁלֹשׁ מִצְוֹת נִצְטַוּוּ יִשְׂרָאֵל בִּשְׁעַת כְּנִיסָתָן לָאָרֶץ. לְמַנּוֹת לָהֶם מֶלֶךְ שֶׁנֶּאֱמַר (דברים יז טו) \"שׂוֹם תָּשִׂים עָלֶיךָ מֶלֶךְ\". וּלְהַכְרִית זַרְעוֹ שֶׁל עֲמָלֵק שֶׁנֶּאֱמַר (דברים כה יט) \"תִּמְחֶה אֶת זֵכֶר עֲמָלֵק\". וְלִבְנוֹת בֵּית הַבְּחִירָה שֶׁנֶּאֱמַר (דברים יב ה) \"לְשִׁכְנוֹ תִדְרְשׁוּ וּבָאתָ שָּׁמָּה\":","מִנּוּי מֶלֶךְ קוֹדֵם לְמִלְחֶמֶת עֲמָלֵק. שֶׁנֶּאֱמַר (שמואל א טו א) \"אֹתִי שָׁלַח ה' לִמְשָׁחֳךָ לְמֶלֶךְ\" (שמואל א טו ג) \"עַתָּה לֵךְ וְהִכִּיתָה אֶת עֲמָלֵק\". וְהַכְרָתַת זֶרַע עֲמָלֵק קוֹדֶמֶת לְבִנְיַן הַבַּיִת. שֶׁנֶּאֱמַר (שמואל ב ז א) \"וַיְהִי כִּי יָשַׁב הַמֶּלֶךְ בְּבֵיתוֹ וַה' הֵנִיחַ לוֹ מִסָּבִיב מִכָּל אֹיְבָיו\" (שמואל ב ז ב) \"וַיֹּאמֶר הַמֶּלֶךְ אֶל נָתָן הַנָּבִיא אָנֹכִי יוֹשֵׁב בְּבֵית אֲרָזִים\" וְגוֹ'. מֵאַחַר שֶׁהֲקָמַת מֶלֶךְ מִצְוָה לָמָּה לֹא רָצָה הַקָּדוֹשׁ בָּרוּךְ הוּא כְּשֶׁשָּׁאֲלוּ מֶלֶךְ מִשְּׁמוּאֵל. לְפִי שֶׁשָּׁאֲלוּ בְּתַרְעֹמֶת. וְלֹא שָׁאֲלוּ לְקַיֵּם הַמִּצְוָה אֶלָּא מִפְּנֵי שֶׁקָּצוּ בִּשְׁמוּאֵל הַנָּבִיא. שֶׁנֶּאֱמַר (שמואל א ח ז) \"כִּי לֹא אֹתְךָ מָאָסוּ כִּי אֹתִי מָאֲסוּ\" וְגוֹ':","אֵין מַעֲמִידִין מֶלֶךְ בַּתְּחִלָּה אֶלָּא עַל פִּי בֵּית דִּין שֶׁל שִׁבְעִים זְקֵנִים וְעַל פִּי נָבִיא. כִּיהוֹשֻׁעַ שֶׁמִּנָּהוּ משֶׁה רַבֵּנוּ וּבֵית דִּינוֹ. וּכְשָׁאוּל וְדָוִד שֶׁמִּנָּם שְׁמוּאֵל הָרָמָתִי וּבֵית דִּינוֹ:","אֵין מַעֲמִידִין מֶלֶךְ מִקְּהַל גֵּרִים אֲפִלּוּ אַחַר כַּמָּה דּוֹרוֹת עַד שֶׁתִּהְיֶה אִמּוֹ מִיִּשְׂרָאֵל. שֶׁנֶּאֱמַר (דברים יז טו) \"לֹא תוּכַל לָתֵת עָלֶיךָ אִישׁ נָכְרִי אֲשֶׁר לֹא אָחִיךָ הוּא\". וְלֹא לְמַלְכוּת בִּלְבַד אֶלָּא לְכָל שְׂרָרוֹת שֶׁבְּיִשְׂרָאֵל. לֹא שַׂר צָבָא וְלֹא שַׂר חֲמִשִּׁים אוֹ שַׂר עֲשָׂרָה. אֲפִלּוּ מְמֻנֶּה עַל אַמַּת הַמַּיִם שֶׁמְּחַלֵּק מִמֶּנָּה לַשָּׂדוֹת. וְאֵין צָרִיךְ לוֹמַר דַּיָּן אוֹ נָשִׂיא שֶׁלֹּא יְהֵא אֶלָּא מִיִּשְׂרָאֵל. שֶׁנֶּאֱמַר (דברים יז טו) \"מִקֶּרֶב אַחֶיךָ תָּשִׂים עָלֶיךָ מֶלֶךְ\" כָּל מְשִׂימוֹת שֶׁאַתָּה מֵשִׂים לֹא יְהוּ אֶלָּא מִקֶּרֶב אַחֶיךָ:","אֵין מַעֲמִידִין אִשָּׁה בְּמַלְכוּת שֶׁנֶּאֱמַר (דברים יז טו) \"עָלֶיךָ מֶלֶךְ\" וְלֹא מַלְכָּה. וְכֵן כָּל מְשִׂימוֹת שֶׁבְּיִשְׂרָאֵל אֵין מְמַנִּים בָּהֶם אֶלָּא אִישׁ:","וְאֵין מַעֲמִידִין מֶלֶךְ וְלֹא כֹּהֵן גָּדוֹל. לֹא קַצָּב. וְלֹא סַפָּר. וְלֹא בַּלָּן [א.] וְלֹא בֻּרְסִי. לֹא מִפְּנֵי שֶׁהֵן פְּסוּלִין אֶלָּא הוֹאִיל וְאֻמָּנוּתָן נִקְלָה הָעָם מְזַלְזְלִין בָּהֶן לְעוֹלָם. וּמִשֶּׁיַּעֲשֶׂה בִּמְלָאכָה מֵאֵלּוּ יוֹם אֶחָד נִפְסָל:","כְּשֶׁמַּעֲמִידִין הַמֶּלֶךְ מוֹשְׁחִין אוֹתוֹ בְּשֶׁמֶן הַמִּשְׁחָה. שֶׁנֶּאֱמַר (שמואל א י א) \"וַיִּקַּח שְׁמוּאֵל אֶת פַּךְ הַשֶּׁמֶן וַיִּצֹק עַל רֹאשׁוֹ וַיִּשָּׁקֵהוּ\". וּמֵאַחַר שֶׁמּוֹשְׁחִין הַמֶּלֶךְ הֲרֵי זֶה זוֹכֶה לוֹ וּלְבָנָיו עַד עוֹלָם. שֶׁהַמַּלְכוּת יְרֻשָּׁה שֶׁנֶּאֱמַר (דברים יז כ) \"לְמַעַן יַאֲרִיךְ יָמִים עַל מַמְלַכְתּוֹ הוּא וּבָנָיו בְּקֶרֶב יִשְׂרָאֵל\". הֵנִיחַ בֵּן קָטָן מְשַׁמְּרִין לוֹ הַמְּלוּכָה עַד שֶׁיַּגְדִּיל. כְּמוֹ שֶׁעָשָׂה יְהוֹיָדָע לְיוֹאָשׁ. וְכָל הַקּוֹדֵם בְּנַחֲלָה קֹדֶם לִירֻשַּׁת הַמְּלוּכָה. וְהַבֵּן הַגָּדוֹל קוֹדֵם לְקָטָן מִמֶּנּוּ. וְלֹא הַמַּלְכוּת בִּלְבַד אֶלָּא כָּל הַשְּׂרָרוֹת וְכָל הַמִּנּוּיִין שֶׁבְּיִשְׂרָאֵל יְרֻשָּׁה לִבְנוֹ וּלְבֶן בְּנוֹ עַד עוֹלָם. וְהוּא שֶׁיִּהְיֶה הַבֵּן מְמַלֵּא מְקוֹם אֲבוֹתָיו בְּחָכְמָה וּבְיִרְאָה. הָיָה מְמַלֵּא בְּיִרְאָה אַף עַל פִּי שֶׁאֵינוֹ מְמַלֵּא בְּחָכְמָה מַעֲמִידִין אוֹתוֹ בִּמְקוֹם אָבִיו וּמְלַמְּדִין אוֹתוֹ. וְכָל מִי שֶׁאֵין בּוֹ יִרְאַת שָׁמַיִם אַף עַל פִּי שֶׁחָכְמָתוֹ מְרֻבָּה אֵין מְמַנִּין אוֹתוֹ לְמִנּוּי מִן הַמִּנּוּיִין שֶׁבְּיִשְׂרָאֵל. כֵּיוָן שֶׁנִּמְשַׁח דָּוִד זָכָה בְּכֶתֶר מַלְכוּת. וַהֲרֵי הַמַּלְכוּת לוֹ וּלְבָנָיו הַזְּכָרִים עַד עוֹלָם. שֶׁנֶּאֱמַר (שמואל ב ז טז) \"כִּסְאֲךָ יִהְיֶה נָכוֹן עַד עוֹלָם\". וְלֹא זָכָה אֶלָּא לִכְשֵׁרִים שֶׁנֶּאֱמַר (תהילים קלב יב) \"אִם יִשְׁמְרוּ בָנֶיךָ בְּרִיתִי\". אַף עַל פִּי שֶׁלֹּא זָכָה אֶלָּא לִכְשֵׁרִים לֹא תִכָּרֵת הַמְּלוּכָה מִזֶּרַע דָּוִד לְעוֹלָם. הַקָּדוֹשׁ בָּרוּךְ הוּא הִבְטִיחוֹ בְּכָךְ שֶׁנֶּאֱמַר (תהילים פט לא) \"אִם יַעַזְבוּ בָנָיו תּוֹרָתִי וּבְמִשְׁפָּטַי לֹא יֵלֵכוּן\" (תהילים פט לג) \"וּפָקַדְתִּי בְשֵׁבֶט פִּשְׁעָם וּבִנְגָעִים עֲוֹנָם\" (תהילים פט לד) \"וְחַסְדִּי לֹא אָפִיר מֵעִמּוֹ\":","נָבִיא שֶׁהֶעֱמִיד מֶלֶךְ מִשְּׁאָר שִׁבְטֵי יִשְׂרָאֵל. וְהָיָה אוֹתוֹ הַמֶּלֶךְ הוֹלֵךְ בְּדֶרֶךְ הַתּוֹרָה וְהַמִּצְוָה וְנִלְחָם מִלְחֲמוֹת ה'. הֲרֵי זֶה מֶלֶךְ וְכָל מִצְוֹת הַמַּלְכוּת נוֹהֲגוֹת בּוֹ. אַף עַל פִּי שֶׁעִקַּר הַמַּלְכוּת לְדָוִד. וְיִהְיֶה מִבָּנָיו מֶלֶךְ. שֶׁהֲרֵי אֲחִיָּה הַשִּׁילוֹנִי הֶעֱמִיד יָרָבְעָם וְאָמַר לוֹ (מלכים א יא לח) \"וְהָיָה אִם שָׁמוֹעַ תִּשְׁמַע אֶת כָּל אֲשֶׁר אֲצַוֶּךָ וּבָנִיתִי לְךָ בַיִת נֶאֱמָן כַּאֲשֶׁר בָּנִיתִי לְדָוִד\" וְגוֹ'. וְאָמַר לוֹ אֲחִיָּה (מלכים א יא לו) \"וְלִבְנוֹ אֶתֵּן שֵׁבֶט אֶחָד לְמַעַן הֱיוֹת נִיר לְדָוִיד עַבְדִּי כָּל הַיָּמִים לְפָנַי בִּירוּשָׁלַםִ\":","מַלְכֵי בֵּית דָּוִד הֵם הָעוֹמְדִים לְעוֹלָם שֶׁנֶּאֱמַר (שמואל ב ז טז) \"כִּסְאֲךָ יִהְיֶה נָכוֹן עַד עוֹלָם\". אֲבָל אִם יַעֲמֹד מֶלֶךְ מִשְּׁאָר יִשְׂרָאֵל תִּפָּסֵק הַמַּלְכוּת מִבֵּיתוֹ. שֶׁהֲרֵי נֶאֱמַר לְיָרָבְעָם (מלכים א יא לט) \"אַךְ לֹא כָל הַיָּמִים\":","אֵין מוֹשְׁחִין מַלְכֵי יִשְׂרָאֵל בְּשֶׁמֶן הַמִּשְׁחָה אֶלָּא בְּשֶׁמֶן אֲפַרְסְמוֹן. וְאֵין מְמַנִּין אוֹתָן בִּירוּשָׁלַיִם לְעוֹלָם אֶלָּא מֶלֶךְ יִשְׂרָאֵל מִזֶּרַע דָּוִד. וְאֵין מוֹשְׁחִין אֶלָּא זֶרַע דָּוִד:","כְּשֶׁמּוֹשְׁחִין מַלְכֵי בֵּית דָּוִד אֵין מוֹשְׁחִין אוֹתָן אֶלָּא עַל הַמַּעְיָן:","וְאֵין מוֹשְׁחִין מֶלֶךְ בֶּן מֶלֶךְ. אֶלָּא אִם כֵּן הָיְתָה שָׁם מַחְלֹקֶת אוֹ מִלְחָמָה מוֹשְׁחִין אוֹתוֹ כְּדֵי לְסַלֵּק הַמַּחֲלֹקֶת. לְפִיכָךְ מָשְׁחוּ שְׁלֹמֹה מִפְּנֵי אֲדֹנִיָּה. וְיוֹאָשׁ מִפְּנֵי עֲתַלְיָה. וּמָשְׁחוּ יְהוֹאָחָז מִפְּנֵי יְהוֹיָקִים אָחִיו:"],"Mishneh Torah, Leavened and Unleavened Bread 1":["כָּל הָאוֹכֵל כְּזַיִת חָמֵץ בְּפֶסַח מִתְּחִלַּת לֵיל חֲמִשָּׁה עָשָׂר עַד סוֹף יוֹם אֶחָד וְעֶשְׂרִים בְּנִיסָן בְּמֵזִיד חַיָּב כָּרֵת שֶׁנֶּאֱמַר (שמות יב טו) \"כִּי כָּל אֹכֵל חָמֵץ וְנִכְרְתָה\". בְּשׁוֹגֵג חַיָּב קָרְבַּן חַטָּאת קְבוּעָה. אֶחָד הָאוֹכֵל וְאֶחָד הַמְמַחֶה וְשׁוֹתֶה:","הֶחָמֵץ בַּפֶּסַח אָסוּר בַּהֲנָיָה שֶׁנֶּאֱמַר (שמות יג ג) \"לֹא יֵאָכֵל חָמֵץ\" לֹא יְהֵא בּוֹ הֶתֵּר אֲכִילָה. וְהַמַּנִּיחַ חָמֵץ בִּרְשׁוּתוֹ בְּפֶסַח אַף עַל פִּי שֶׁלֹּא אֲכָלוֹ עוֹבֵר בִּשְׁנֵי לָאוִין שֶׁנֶּאֱמַר (שמות יג ז) (דברים טז ד) \"לֹא יֵרָאֶה לְךָ שְׂאֹר בְּכָל גְּבֻלֶךָ\" וְנֶאֱמַר (שמות יב יט) \"שְׂאֹר לֹא יִמָּצֵא בְּבָתֵּיכֶם\". וְאִסּוּר הֶחָמֵץ וְאִסּוּר הַשְּׂאוֹר שֶׁבּוֹ מַחְמִיצִין אֶחָד הוּא:","אֵינוֹ לוֹקֶה מִשּׁוּם לֹא יֵרָאֶה וְ(שמות יב יט) \"לֹא יִמָּצֵא\" אֶלָּא אִם כֵּן קָנָה חָמֵץ בְּפֶסַח אוֹ חִמְצוֹ כְּדֵי שֶׁיַּעֲשֶׂה בּוֹ מַעֲשֶׂה. אֲבָל אִם הָיָה לוֹ חָמֵץ קֹדֶם הַפֶּסַח וּבָא הַפֶּסַח וְלֹא בִּעֲרוֹ אֶלָּא הִנִּיחוֹ בִּרְשׁוּתוֹ אַף עַל פִּי שֶׁעָבַר עַל שְׁנֵי לָאוִין אֵינוֹ לוֹקֶה מִן הַתּוֹרָה מִפְּנֵי שֶׁלֹּא עָשָׂה בּוֹ מַעֲשֶׂה. וּמַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","חָמֵץ שֶׁעָבַר עָלָיו הַפֶּסַח אָסוּר בַּהֲנָיָה לְעוֹלָם. וְדָבָר זֶה קְנָס הוּא מִדִּבְרֵי סוֹפְרִים מִפְּנֵי שֶׁעָבַר עַל בַּל יֵרָאֶה וּבַל יִמָּצֵא אֲסָרוּהוּ. אֲפִלּוּ הִנִּיחוֹ בִּשְׁגָגָה אוֹ בְּאֹנֶס. כְּדֵי שֶׁלֹּא יַנִּיחַ אָדָם חָמֵץ בִּרְשׁוּתוֹ בְּפֶסַח כְּדֵי שֶׁיֵּהָנֶה בּוֹ אַחַר הַפֶּסַח:","חָמֵץ שֶׁנִּתְעָרֵב בְּדָבָר אַחֵר תּוֹךְ הַפֶּסַח בֵּין בְּמִינוֹ בֵּין שֶׁלֹּא בְּמִינוֹ הֲרֵי זֶה אוֹסֵר בְּכָל שֶׁהוּא. וְחָמֵץ שֶׁל יִשְׂרָאֵל שֶׁעָבַר עָלָיו הַפֶּסַח אַף עַל פִּי שֶׁהוּא אָסוּר בַּהֲנָיָה אִם נִתְעָרֵב בֵּין בְּמִינוֹ בֵּין שֶׁלֹּא בְּמִינוֹ הֲרֵי זֶה מֻתָּר לְאָכְלוֹ אַחַר הַפֶּסַח. שֶׁלֹּא קָנְסוּ וְאָסְרוּ אֶלָּא בֶּחָמֵץ עַצְמוֹ אֲבָל הַתַּעֲרֹבֶת מֻתָּר בַּאֲכִילָה לְאַחַר הַפֶּסַח:","אֵין חַיָּבִין כָּרֵת אֶלָּא עַל אֲכִילַת עַצְמוֹ שֶׁל חָמֵץ אֲבָל עֵרוּב חָמֵץ כְּגוֹן כּוּתָח הַבַּבְלִי וְשֵׁכָר הַמָּדִי וְכָל הַדּוֹמֶה לָהֶן מִדְּבָרִים שֶׁהֶחָמֵץ מְעֹרָב בָּהֶן אִם אֲכָלָן בְּפֶסַח לוֹקֶה וְאֵין בּוֹ כָּרֵת שֶׁנֶּאֱמַר (שמות יב כ) \"כָּל מַחְמֶצֶת לֹא תֹאכֵלוּ\". בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁאָכַל כְּזַיִת חָמֵץ בְּתוֹךְ הַתַּעֲרֹבֶת בִּכְדֵי אֲכִילַת שָׁלֹשׁ בֵּיצִים הוּא שֶׁלּוֹקֶה מִן הַתּוֹרָה. אֲבָל אִם אֵין בַּתַּעֲרֹבֶת כְּזַיִת בִּכְדֵי אֲכִילַת שָׁלֹשׁ בֵּיצִים אַף עַל פִּי שֶׁאָסוּר לוֹ לֶאֱכל אִם אָכַל אֵינוֹ לוֹקֶה אֶלָּא מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","הָאוֹכֵל מִן הֶחָמֵץ עַצְמוֹ בְּפֶסַח כָּל שֶׁהוּא הֲרֵי זֶה אָסוּר מִן הַתּוֹרָה שֶׁנֶּאֱמַר (שמות יג ג) \"לֹא יֵאָכֵל\". וְאַף עַל פִּי כֵן אֵינוֹ חַיָּב כָּרֵת אוֹ קָרְבָּן אֶלָּא עַל כַּשִּׁעוּר שֶׁהוּא כְּזַיִת. וְהָאוֹכֵל פָּחוֹת מִכְּזַיִת בְּמֵזִיד מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","אָסוּר לֶאֱכל חָמֵץ בְּיוֹם אַרְבָּעָה עָשָׂר מֵחֲצוֹת הַיּוֹם וּלְמַעְלָה שֶׁהוּא מִתְּחִלַּת שָׁעָה שְׁבִיעִית בַּיּוֹם. וְכָל הָאוֹכֵל בַּזְּמַן הַזֶּה לוֹקֶה מִן הַתּוֹרָה שֶׁנֶּאֱמַר (דברים טז ג) \"לֹא תֹאכַל עָלָיו חָמֵץ\". כְּלוֹמַר עַל קָרְבַּן הַפֶּסַח. כָּךְ לָמְדוּ מִפִּי הַשְּׁמוּעָה בְּפֵרוּשׁ דָּבָר זֶה לֹא תֹּאכַל חָמֵץ מִשָּׁעָה שֶׁרְאוּיָה לִשְׁחִיטַת הַפֶּסַח שֶׁהוּא (שמות יב ו) \"בֵּין הָעַרְבַּיִם\" וְהוּא חֲצִי הַיּוֹם:","וְאָסְרוּ חֲכָמִים לֶאֱכל חָמֵץ מִתְּחִלַּת שָׁעָה שִׁשִּׁית כְּדֵי שֶׁלֹּא יִגַּע בְּאִסּוּר תּוֹרָה. וּמִתְּחִלַּת שָׁעָה שִׁשִּׁית יִהְיֶה הֶחָמֵץ אָסוּר בַּאֲכִילָה וּבַהֲנָיָה כָּל שָׁעָה שִׁשִּׁית מִדִּבְרֵי סוֹפְרִים וּשְׁאָר הַיּוֹם מִשְּׁבִיעִית וּלְמַעְלָה מִן הַתּוֹרָה. שָׁעָה חֲמִישִׁית אֵין אוֹכְלִין בָּהּ חָמֵץ גְּזֵרָה מִשּׁוּם יוֹם הַמְעֻנָּן שֶׁמָּא יִטְעֶה בֵּין חֲמִישִׁית לְשִׁשִּׁית. וְאֵינוֹ אָסוּר בַּהֲנָיָה בְּשָׁעָה חֲמִישִׁית. לְפִיכָךְ תּוֹלִין בָּהּ תְּרוּמָה וְלֶחֶם תּוֹדָה וְכַיּוֹצֵא בָּהֶן מֵחָמֵץ שֶׁהוּא קֹדֶשׁ לֹא אוֹכְלִין וְלֹא שׂוֹרְפִין עַד שֶׁתַּגִּיעַ שָׁעָה שִׁשִּׁית וְשׂוֹרְפִין הַכּל:","הָא לָמַדְתָּ שֶׁמֻּתָּר לֶאֱכל חָמֵץ בְּיוֹם אַרְבָּעָה עָשָׂר עַד סוֹף שָׁעָה רְבִיעִית. וְאֵין אוֹכְלִין בְּשָׁעָה חֲמִישִׁית אֲבָל נֶהֱנִין בּוֹ. וְהָאוֹכֵל בְּשָׁעָה שִׁשִּׁית מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. וְהָאוֹכֵל מִתְּחִלַּת שָׁעָה שְׁבִיעִית לוֹקֶה:"],"Mishneh Torah, Levirate Marriage and Release 4":["כֵּיצַד מִצְוַת חֲלִיצָה. הַיְבָמָה הוֹלֶכֶת אַחַר הַיָּבָם בְּמָקוֹם שֶׁהוּא שָׁם וּבָאָה לַדַּיָּנִין. וְהֵן קוֹרְאִין לוֹ וְנוֹתְנִין לוֹ עֵצָה הַהוֹגֶנֶת לוֹ וְלָהּ. אִם עֵצָה טוֹבָה לְיַבֵּם יוֹעֲצִין אוֹתוֹ לְיַבֵּם. וְאִם עֵצָה טוֹבָה לַחֲלֹץ כְּגוֹן שֶׁהָיְתָה הִיא יַלְדָּה וְהוּא זָקֵן אוֹ הִיא זְקֵנָה וְהוּא יֶלֶד יוֹעֲצִין אוֹתוֹ לַחֲלֹץ:","וּצְרִיכִין הַדַּיָּנִין לִקְבֹּעַ מָקוֹם שֶׁיֵּשְׁבוּ בּוֹ וְאַחַר כָּךְ תַּחֲלֹץ שָׁם בִּפְנֵיהֶם שֶׁנֶּאֱמַר (דברים כה ז) ״וְעָלְתָה יְבִמְתּוֹ הַשַּׁעְרָה אֶל הַזְּקֵנִים״‎‎ וְגוֹ'. לֹא נוֹעֲדוּ וְלֹא קָבְעוּ מָקוֹם אֶלָּא נִקְרוּ נִקְרָה וְנִקְרֵאת הִיא וְהוּא לִפְנֵיהֶן וְחָלְצוּ חֲלִיצָתָהּ כְּשֵׁרָה:","וּמְלַמְּדִין אוֹתָהּ וְאֶת הַיָּבָם לִקְרוֹת עַד שֶׁהוּא וְהִיא יִהְיוּ רְגִילִין וְתִהְיֶה יְכוֹלָה לִקְרוֹת (דברים כה ז) ״לֹא אָבָה״‎‎ בִּנְשִׁימָה אַחַת וְאַחַר כָּךְ תֹּאמַר יַבְּמִי. כְּדֵי שֶׁלֹּא יִהְיֶה מַשְׁמַע דְּבָרֶיהָ אָבָה יַבְּמִי:","וּמֵאַחַר שֶׁתִּהְיֶה רְגִילָה לִקְרוֹת אַף עַל פִּי שֶׁלֹּא קָרְאָה בִּנְשִׁימָה אַחַת אֵין מַקְפִּידִין עַל זֶה. אֲבָל אִם אֵינָהּ יְכוֹלָה מַרְגִּילִין אוֹתָהּ עַד שֶׁתֵּדַע:","וְהַחֲלִיצָה בַּיּוֹם וְלֹא בַּלַּיְלָה. וּבִפְנֵי שְׁלֹשָׁה שֶׁיּוֹדְעִין לְהַקְרוֹת. וְאִם אֶחָד מִן הַשְּׁלֹשָׁה גֵּר פָּסוּל. וַאֲפִלּוּ הָיָה אָבִיו גֵּר וְאִמּוֹ יִשְׂרְאֵלִית לֹא תַּחֲלֹץ עַד שֶׁיִּהְיֶה אָבִיו וְאִמּוֹ מִיִּשְׂרָאֵל. וּמִצְוָתָהּ בַּחֲמִשָּׁה כְּדֵי לְפַרְסֵם הַדָּבָר. וְאוֹתָן הַשְּׁנַיִם אֲפִלּוּ הָיוּ עַמֵּי הָאָרֶץ:","כֵּיצַד חוֹלְצִין. מְבִיאִין לוֹ מִנְעָל שֶׁל עוֹר שֶׁיֵּשׁ לוֹ עָקֵב וְאֵינוֹ תָּפוּר בְּפִשְׁתָּן וְלוֹבְשׁוֹ בְּיָמִין וְקוֹשֵׁר רְצוּעוֹתָיו עַל רַגְלוֹ. וְעוֹמֵד הוּא וְהִיא בִּפְנֵי בֵּית דִּין וּמַקְרִין לַיְבָמָה בִּלְשׁוֹן הַקֹּדֶשׁ (דברים כה ז) ״מֵאֵן יְבָמִי״‎‎ וְגוֹ'. וְאַחַר כָּךְ מַקְרִין לַיָּבָם (דברים כה ח) ״לֹא חָפַצְתִּי לְקַחְתָּהּ״‎‎. וְנוֹעֵץ רַגְלוֹ בָּאָרֶץ וְהִיא יוֹשֶׁבֶת וּפוֹשֶׁטֶת יָדָהּ בִּפְנֵי בֵּית דִּין וּמַתֶּרֶת רְצוּעוֹת הַמִּנְעָל מֵעַל רַגְלוֹ וְחוֹלֶצֶת הַמִּנְעָל וּמַשְׁלֶכֶת אוֹתוֹ לָאָרֶץ וּמִשֶּׁיִּשָּׁמֵט רֹב הֶעָקֵב הֻתְּרָה הַיְבָמָה לְזָר:","וְאַחַר כָּךְ עוֹמֶדֶת וְיוֹרֶקֶת בָּאָרֶץ כְּנֶגֶד פָּנָיו רֹק הַנִּרְאֶה לַדַּיָּנִין. שֶׁמִּצְוַת חֲלִיצָה שֶׁיִּהְיוּ שְׁנֵיהֶן עוֹמְדִין בִּשְׁעַת קְרִיאָה וּבִשְׁעַת רְקִיקָה וּצְרִיכִין הַדַּיָּנִין לִרְאוֹת הָרֹק הַיּוֹצֵא מִפִּיהָ. וְאַחַר כָּךְ מַקְרִין לָהּ (דברים כה ט) ״כָּכָה יֵעָשֶׂה לָאִישׁ אֲשֶׁר לֹא יִבְנֶה אֶת בֵּית אָחִיו״‎‎ (דברים כה י) ״וְנִקְרָא שְׁמוֹ בְּיִשְׂרָאֵל בֵּית חֲלוּץ הַנָּעַל״‎‎:","הַכּל בִּלְשׁוֹן הַקֹּדֶשׁ שֶׁנֶּאֱמַר (דברים כה ט) ״כָּכָה״‎‎ בַּלָּשׁוֹן הַזֶּה. וְכָל הַיּוֹשְׁבִין שָׁם עוֹנִים אַחֲרֶיהָ (דברים כה י) ״חֲלוּץ הַנָּעַל״‎‎ שָׁלֹשׁ פְּעָמִים. וְצָרִיךְ שֶׁתִּתְכַּוֵּן הַיְבָמָה שֶׁתַּחֲלֹץ לוֹ וְיִתְכַּוֵּן הוּא שֶׁיַּחֲלֹץ לָהּ. וְיַעֲשׂוּ מַעֲשִׂים אֵלּוּ לִשְׁמָן. וְהַסּוּמָא אֵינוֹ חוֹלֵץ שֶׁנֶּאֱמַר (דברים כה ט) ״וְיָרְקָה בְּפָנָיו״‎‎ וְאֵין זֶה רוֹאֶה הָרֹק:","נִמְצָא סֵדֶר הַחֲלִיצָה כָּךְ הוּא. קוֹרְאָה הִיא תְּחִלָּה (דברים כה ז) ״מֵאֵן יְבָמִי לְהָקִים לְאָחִיו שֵׁם בְּיִשְׂרָאֵל לֹא אָבָה יַבְּמִי״‎‎. וְאַחַר כָּךְ הוּא אוֹמֵר (דברים כה ח) ״לֹא חָפַצְתִּי לְקַחְתָּהּ״‎‎. וְאַחַר כָּךְ תַּחֲלֹץ. וְאַחַר כָּךְ תָּרֹק. וְאַחַר כָּךְ תִּקְרָא (דברים כה ט) ״כָּכָה יֵעָשֶׂה לָאִישׁ אֲשֶׁר לֹא יִבְנֶה אֶת בֵּית אָחִיו״‎‎ (דברים כה י) ״וְנִקְרָא שְׁמוֹ בְּיִשְׂרָאֵל בֵּית חֲלוּץ הַנָּעַל״‎‎:","וְאֵין הַסֵּדֶר מְעַכֵּב אֶלָּא אִם לֹא קָרְאָה בַּתְּחִלָּה לֹא הִיא וְלֹא הוּא אוֹ שֶׁרָקְקָה וְאַחַר כָּךְ חָלְצָה אוֹ שֶׁקָּרְאָה וְאַחַר כָּךְ רָקְקָה חֲלִיצָתָהּ כְּשֵׁרָה:","וְלָמָּה לֹא תַּחֲזֹר וְתָרֹק עַל הַסֵּדֶר שֶׁמָּא יֹאמְרוּ רְקִיקָה לְבַדָּהּ אֵינָהּ כְּלוּם וְאֵינָהּ פּוֹסֶלֶת מִן הָאַחִין:","חָלְצָה בִּלְבַד וְלֹא קָרְאָה וְלֹא רָקְקָה חֲלִיצָתָהּ כְּשֵׁרָה. וְאֵין צָרִיךְ לוֹמַר שֶׁחָלְצָה וְקָרְאָה וְלֹא רָקְקָה אוֹ שֶׁחָלְצָה וְרָקְקָה וְלֹא קָרְאָה שֶׁחֲלִיצָתָהּ כְּשֵׁרָה:","בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיוּ יְכוֹלִין לְדַבֵּר שֶׁהֲרֵי הֵן רְאוּיִין לִקְרוֹת. אֲבָל אִלֶּמֶת אוֹ אִלֵּם אֵינָן חוֹלְצִין וְאִם חָלְצוּ חֲלִיצָתָן פְּסוּלָה. וְאֵינָן כְּחֵרֵשׁ וְחֵרֶשֶׁת שֶׁחָלְצוּ שֶׁלֹּא עָשׂוּ כְּלוּם. לְפִי שֶׁהַחֵרֵשׁ אוֹ הַחֵרֶשֶׁת אֵינָן בְּנֵי דַּעַת:","רָקְקָה בִּלְבַד שֶׁלֹּא חָלְצָה וְלֹא קָרְאָה. אוֹ שֶׁרָקְקָה וְקָרְאָה וְלֹא חָלְצָה הֲרֵי זוֹ כַּחֲלִיצָה פְּסוּלָה. קָרְאָה הִיא וְהוּא וְלֹא חָלְצָה וְלֹא רָקְקָה לֹא עָשָׂה כְּלוּם שֶׁנֶּאֱמַר (דברים כה ט) ״כָּכָה יֵעָשֶׂה לָאִישׁ״‎‎. שֶׁהַמַּעֲשֶׂה שֶׁהוּא הַחֲלִיצָה וְהָרְקִיקָה הוּא שֶׁמּוֹעִיל אֲבָל הַקְּרִיאָה אֵינָהּ מְעַכֶּבֶת וְאֵינָהּ מוֹעֶלֶת:","חָלְצָה וְרָקְקָה וְקָרְאָה וְהֵם יוֹשְׁבִין אוֹ מֻטִּין עַל צִדֵּיהֶן. אוֹ שֶׁהָיָה שְׂרוֹךְ הַנַּעַל קָשׁוּר עַל שׁוֹקוֹ מִן הָאַרְכֻּבָּה וּלְמַטָּה. אוֹ שֶׁחָלְצָה בִּפְנֵי שְׁלֹשָׁה עַמֵּי הָאָרֶץ שֶׁאֵינָן יוֹדְעִין לְהַקְרוֹת. וְכֵן הַסּוּמָא שֶׁחָלַץ. חֲלִיצָתוֹ כְּשֵׁרָה:","חָלְצָה בַּלַּיְלָה אוֹ שֶׁחָלְצָה בִּפְנֵי שְׁנַיִם אוֹ בִּפְנֵי שְׁלֹשָׁה וְנִמְצָא אֶחָד מֵהֶן קָרוֹב אוֹ פָּסוּל. אוֹ שֶׁהָיָה הַמִּנְעָל קָשׁוּר לְמַעְלָה מִן הָאַרְכֻּבָּה. אוֹ שֶׁהִתִּיר הוּא וְשָׁמְטָה הִיא אוֹ שֶׁהִתִּירָה הִיא וְשָׁמַט הוּא. אוֹ שֶׁנִּתְכַּוְּנָה הִיא וְלֹא נִתְכַּוֵּן הוּא. אוֹ שֶׁנִּתְכַּוֵּן הוּא וְלֹא נִתְכַּוְּנָה הִיא. וְכֵן קְטַנָּה שֶׁחָלְצָה לְגָדוֹל. חֲלִיצָתָן פְּסוּלָה. וְכֵן אִם חָלְצָה בִּפְנֵי יָחִיד וַאֲפִלּוּ בֵּינוֹ לְבֵינָהּ וּבַלַּיְלָה הֲרֵי זוֹ חֲלִיצָה פְּסוּלָה. אֲבָל חֵרֵשׁ שׁוֹטֶה וְקָטָן שֶׁחָלְצוּ וְכָל הַחוֹלֵץ לְמִי שֶׁהִיא פְּטוּרָה מִן הַחֲלִיצָה וּמִן הַיִּבּוּם אֵינָהּ חֲלִיצָה:","יָבָם שֶׁרַגְלוֹ הַיְמָנִית חֲתוּכָה אֵינוֹ חוֹלֵץ בִּשְׂמֹאל וְאִם חָלְצָה מֵעַל שְׂמֹאלוֹ חֲלִיצָתָהּ פְּסוּלָה. הָיְתָה רַגְלוֹ עֲקֻמָּה לְאָחוֹר אוֹ הֲפוּכָה עַל צִדָּהּ אוֹ שֶׁהָיָה מְהַלֵּךְ עַל רָאשֵׁי אֶצְבְּעוֹת רַגְלָיו הֲרֵי זֶה אֵינוֹ חוֹלֵץ שֶׁהַחוֹלֵץ צָרִיךְ לִנְעֹץ עֲקֵבוֹ בָּאָרֶץ וְזֶה אֵינוֹ יָכוֹל. וְאִם חָלְצָה לְמִי שֶׁרַגְלוֹ כָּךְ הֲרֵי חֲלִיצָתָהּ פְּסוּלָה:","וִיבָמָה שֶׁיָּדֶיהָ חֲתוּכוֹת חוֹלֶצֶת לְכַתְּחִלָּה וַאֲפִלּוּ בְּשִׁנֶּיהָ שֶׁלֹּא נֶאֱמַר וְחָלְצָה בְּיָדָהּ. חָלְצָה בְּמִנְעָל שֶׁל בֶּגֶד אֵינָהּ חֲלִיצָה. אֲבָל אִם חָלְצָה בְּמִנְעָל שֶׁאֵין לוֹ עָקֵב. אוֹ שֶׁהָיָה תָּפוּר בְּפִשְׁתָּן. אוֹ שֶׁהָיָה מִנְעָל שֶׁל שֵׂעָר אוֹ שֶׁל סִיב אוֹ שֶׁל שַׁעַם אוֹ שֶׁל עֵץ. אוֹ שֶׁהָיָה מִנְעָל גָּדוֹל שֶׁאֵינוֹ יָכוֹל לְהַלֵּךְ בּוֹ אוֹ קָטָן שֶׁאֵינוֹ חוֹפֶה אֶת רֹב רַגְלוֹ. אוֹ מִנְעָל פָּרוּם שֶׁאֵינוֹ חוֹפֶה רֹב הָרֶגֶל אוֹ נִפְחַת שֶׁאֵין מְקַבֵּל רֹב הָרֶגֶל. חֲלִיצָתָהּ פְּסוּלָה:","חָלְצָה בְּסַנְדָּל שֶׁל עֵץ וּמְחֻפֶּה עוֹר אוֹ הָיְתָה קַרְקָעִיתוֹ עוֹר וּלְחָיָיו שֶׁל שֵׂעָר. אוֹ שֶׁחָלְצָה סַנְדָּל שֶׁל שְׂמֹאל מֵעַל רַגְלוֹ הַיְמָנִית. אוֹ שֶׁלֹּא הָיָה הַמִּנְעָל שֶׁלּוֹ אוֹ (שֶׁלֹּא) הָיָה גָּדוֹל שֶׁיָּכוֹל לְהַלֵּךְ בּוֹ. אוֹ קָטָן שֶׁחוֹפֶה אֶת רֹב רַגְלוֹ אוֹ נִפְרַם שֶׁחוֹפֶה אֶת רֹב הָרֶגֶל אוֹ נִפְחַת שֶׁמְּקַבֵּל רֹב הָרֶגֶל. חֲלִיצָתוֹ כְּשֵׁרָה:","סַנְדָּל הַמֻּסְגָּר וְהַמֻּחְלָט וְשֶׁל עַכּוּ״‎ם שֶׁמַּנִּיחִין אוֹתוֹ בְּרַגְלֵי הַצּוּרָה לֹא תַּחֲלֹץ בּוֹ. וְאִם חָלְצָה חֲלִיצָתָהּ כְּשֵׁרָה. וְאַף עַל פִּי שֶׁהוּא אָסוּר בַּהֲנָאָה. אֲבָל סַנְדָּל שֶׁל תִּקְרֹבֶת עַכּוּ״‎ם וְשֶׁל עִיר הַנִּדַּחַת. אוֹ שֶׁנַּעֲשָׂה לְמֵת שֶׁיִּקָבֵר בּוֹ. אִם חָלְצָה בּוֹ חֲלִיצָתָהּ פְּסוּלָה שֶׁהֲרֵי אֵינוֹ עוֹמֵד לְהַלֵּךְ בּוֹ:","קָרְעָה הַמִּנְעָל מֵעַל רַגְלוֹ אוֹ שֶׁשְּׂרָפַתּוּ אוֹ שֶׁהָיָה לָבוּשׁ שְׁתֵּי מִנְעָלִין וְחָלְצָה הָעֶלְיוֹן אַף עַל פִּי שֶׁקָּרְעָה הַתַּחְתּוֹן עַד שֶׁנִּתְגַּלְּתָה רַגְלוֹ הֲרֵי זוֹ חֲלִיצָה פְּסוּלָה:","יְבָמָה שֶׁאָכְלָה שׁוּם אוֹ גַּרְגִּיר וְכַיּוֹצֵא בָּהֶן מִדְּבָרִים שֶׁמַּרְבִּין אֶת הָרֹק וְהָיָה הָרֹק זָב מִפִּיהָ אֵינוֹ כְּלוּם עַד שֶׁיִּהְיֶה הָרֹק מֵעַצְמוֹ:","רָקְקָה דָּם אוֹ שֶׁהָיָה שׁוֹתֵת מִפִּיהָ אֵינוֹ כְּלוּם. וְאִם מָצְצָה וְרָקְקָה כָּשֵׁר שֶׁאִי אֶפְשָׁר לְדָם שֶׁנִּמְצָץ בְּלֹא צִחְצוּחֵי רֹק. רָקְקָה וּקְלָטַתּוּ הָרוּחַ קֹדֶם שֶׁיַּגִּיעַ לִכְנֶגֶד פָּנָיו כְּגוֹן שֶׁהָיְתָה אֲרֻכָּה וְהוּא קָצָר אֵינוֹ כְּלוּם. וְאִם אַחַר שֶׁהִגִּיעַ לְנֶגֶד פָּנָיו אַף עַל פִּי שֶׁלֹּא הִגִּיעַ לָאָרֶץ כָּשֵׁר. וְכֵן אִם לֹא רָאוּ הַדַּיָּנִין הָרֹק כְּשֶׁיָּצָא מִפִּיהָ כָּשֵׁר:","חֲלִיצָה מֻטְעֵית פְּסוּלָה. כֵּיצַד. כְּגוֹן שֶׁאָמְרוּ לוֹ חֲלֹץ לָהּ וּבְכָךְ אַתָּה כּוֹנְסָהּ. אוֹ שֶׁאָמְרוּ לוֹ חֲלֹץ לָהּ שֶׁזּוֹ מִצְוָה הִיא וְאֵינָהּ מַפְסֶדֶת עָלֶיךָ כְּלוּם וְאִם תִּרְצֶה אַחַר כָּךְ לְיַבֵּם תְּיַבֵּם וְכַיּוֹצֵא בִּדְבָרִים אֵלּוּ פְּסוּלָה. אֲבָל אִם הִטְעוּהוּ וְאָמְרוּ לוֹ חֲלֹץ לָהּ עַל מְנָת שֶׁתִּתֵּן לְךָ מָאתַיִם זוּז אוֹ עַל תְּנַאי כָּךְ וְכָךְ אַף עַל פִּי שֶׁלֹּא נָתְנָה וְלֹא נִתְקַיֵּם הַתְּנַאי חֲלִיצָתָהּ כְּשֵׁרָה שֶׁהֲרֵי נִתְכַּוֵּן לַחֲלֹץ לָהּ:","הַמּוֹסֵר מוֹדָעָא עַל הַחֲלִיצָה חֲלִיצָתוֹ פְּסוּלָה. לְפִיכָךְ רָאוּי לַדַּיָּנִין לוֹמַר לוֹ לְבַטֵּל הַמּוֹדָעָא כְּדֶרֶךְ שֶׁעוֹשִׂין בְּגֵט. לְחָצוּהוּ יִשְׂרְאֵלִים וְהִכּוּהוּ עַד שֶׁחָלַץ אִם כַּדִּין עָשׂוּ חֲלִיצָתוֹ כְּשֵׁרָה. וְאִם שֶׁלֹּא כַּדִּין עָשׂוּ כְּגוֹן שֶׁהָיוּ הֶדְיוֹטוֹת אוֹ שֶׁטָּעוּ חֲלִיצָתוֹ פְּסוּלָה. וְאִם הָעַכּוּ״‎ם אֲנָסוּהוּ מֵעַצְמָן. אִם הָיָה הַדִּין נוֹתֵן שֶׁיַּחֲלֹץ חֲלִיצָתוֹ פְּסוּלָה. וְאִם שֶׁלֹּא כַּדִּין אֵינָהּ חֲלִיצָה:","כָּל מָקוֹם שֶׁאָמַרְנוּ אֵינָהּ חֲלִיצָה אוֹ לֹא עָשָׂה כְּלוּם אוֹ אֵינָהּ כְּלוּם הֲרֵי הִיא כְּאִלּוּ לֹא נֶחְלְצָה לוֹ וְלֹא נֶאֶסְרוּ עָלָיו קְרוֹבוֹתֶיהָ וְלֹא נִפְסְלָה מִן הַכְּהֻנָּה וּמֻתֶּרֶת לְהִתְיַבֵּם. וְכָל מָקוֹם שֶׁאָמַרְנוּ חֲלִיצָתָהּ פְּסוּלָה נֶאֶסְרוּ עָלָיו קְרוֹבוֹתֶיהָ וְנִפְסְלָה מִן הַכְּהֻנָּה וְנֶאֶסְרָה עַל הָאַחִין וְאֵינָהּ מִתְיַבֶּמֶת וְאֵינָהּ מֻתֶּרֶת לְהִנָּשֵׂא לְזָר עַד שֶׁתַּחֲלֹץ חֲלִיצָה כְּשֵׁרָה:","עָבְרָה וְנִשֵּׂאת הֲרֵי זֶה חוֹלֵץ לָהּ חֲלִיצָה כְּשֵׁרָה וְהִיא תַּחַת בַּעְלָהּ וְאֵין מוֹצִיאִין אוֹתָהּ מִיָּדוֹ:","יְבָמָה שֶׁגָּדְלָה בֵּין הָאַחִין הֲרֵי זוֹ מֻתֶּרֶת לְהִתְיַבֵּם וְאֵין חוֹשְׁשִׁין לָהּ שֶׁמָּא חָלְצָה לְאֶחָד מֵהֶן בֵּינוֹ לְבֵינָהּ וְנִפְסְלָה עֲלֵיהֶן. אֲבָל אִם רְאִינוּהָ שֶׁחָלְצָה נַעֲלוֹ שֶׁל אֶחָד מֵהֶן נִפְסְלָה שֶׁמָּא נִתְכַּוְּנָה לַחֲלִיצָה וּצְרִיכָה חֲלִיצָה כְּשֵׁרָה לְהַתִּירָהּ לְזָר:","גֵּט חֲלִיצָה שֶׁאָנוּ כּוֹתְבִין לָהּ אֵינוֹ אֶלָּא מַעֲשֵׂה בֵּית דִּין כְּדֵי שֶׁיִּהְיֶה בְּיָדָהּ רְאָיָה שֶׁנֶּחְלְצָה וְאֵין הַדַּיָּנִין חוֹלְצִין אֶלָּא אִם כֵּן מַכִּירִין. לְפִיכָךְ מִי שֶׁרָאָה זֹאת שֶׁנֶּחְלְצָה כּוֹתְבִין לָהּ גֵּט חֲלִיצָה אַף עַל פִּי שֶׁאֵינָן מַכִּירִין שֶׁזּוֹ הִיא בַּת פְּלוֹנִי וְאֵשֶׁת פְּלוֹנִי וְשֶׁזֶּה שֶׁחָלַץ לָהּ אָחִיו הוּא. שֶׁהֲרֵי הַדַּיָּנִין שֶׁחָלְצָה בִּפְנֵיהֶם הִכִּירוּ זֶה וְאַחַר כָּךְ חָלְצָה:","וזהו נוסח גט חליצה שנהגו בו העם: בְּיוֹם פְּלוֹנִי כָּךְ וְכָךְ לְיֶרַח פְּלוֹנִי שְׁנַת כָּךְ וְכָךְ לִבְרִיאַת עָלְמָא לְמִנְיָנָא דְּרָגִילְנָא לְמִימְנֵי בָּהּ בְּמָקוֹם פְּלוֹנִי אֲנַחְנָא דַּיָּנֵי דְּמִקְצָתְנָא חֲתִימִין לְתַתָּא בְּמוֹתַב תְּלָתָא כַּחֲדָא הֲוֵינָא יָתְבִין בְּבֵי דִּינָא וּסְלִיקָא לָקֳדָמָנָא פְּלוֹנִית בָּרַת פְּלוֹנִי אַרְמְלָתָא דִּפְלוֹנִי. וְקָרְבַת לָקֳדָמָנָא גְּבַר חַד דִּשְׁמֵיהּ פְּלוֹנִי בַּר פְּלוֹנִי. וְכֵן אָמְרָה לָנָא פְּלוֹנִית דָּא. פְּלוֹנִי בַּר פְּלוֹנִי דְּנָא אֲחוּהָ דִּפְלוֹנִי בַּעְלִי מֵאֲבוּהָּ הֲוָה דַּהֲוֵינָא נְסִיבָא לֵיהּ וְשָׁכִיב וְחַיֵּי לְרַבָּנָן וּלְכָל יִשְׂרָאֵל שָׁבַק. וּבַר וּבָרַת יָרִית וּמַחְסִין וּמוֹקִים שְׁמָא בְּיִשְׂרָאֵל לֹא שָׁבַק. וְהָדֵין פְּלוֹנִי אֲחוֹהִי חָזִי לְיִבּוּמִי יָתִי. כְּעַן רַבָּנָן אָמְרוּ לֵיהּ אִי צָבִי לְיִבּוּמִי יָתִי יְיַבֵּם וְאִי לֹא יִטְלַע לִי רַגְלֵיהּ דִּימִינָא קָדֳמֵיכוֹן וְאַשְׁרֵי סֵינֵיהּ מֵעַל רַגְלֵיהּ וְאֵרֹק בְּאַנְפּוֹהִי. וְאִשְׁתְּמוֹדַעְנוּהוּ לִפְלוֹנִי דְּנָא דַּאֲחוֹהִי דִּפְלוֹנִי מִיתְנָא מֵאֲבוּהִי הוּא וַאֲמַרְנָא לֵיהּ אִי צָבִית לְיִבּוּמֵי יָתָהּ יַבֵּם וְאִי לֹא אַטְלַע לָהּ קָדֳמָנָא רַגְלָךְ דִּימִינָא וְתִשְׁרֵי סֵינָךְ מֵעַל רַגְלָךְ וְתָרֹק בְּאַנְפָּךְ. וְעָנִי וְאָמַר לָנָא לֵית אֲנָא צָבִי לְיִבּוּמֵי יָתָהּ. מִיַּד אַקְרִינוּהָ לִפְלוֹנִית דָּא מֵאֵן יְבָמִי לְהָקִים לְאָחִיו שֵׁם בְּיִשְׂרָאֵל לֹא אָבָה יַבְּמִי. וְאַף לְהַאי פְּלוֹנִי אַקְרִינוּהוּ לֵיהּ לֹא חָפַצְתִּי לְקַחְתָּהּ. וְאַטְלַע לָהּ רַגְלֵיהּ דִּימִינָא וְשָׁרַת סֵינֵיהּ מֵעַל רַגְלֵיהּ וְרָקַת בְּאַנְפּוֹהִי רֹקָא דְּאִיתְחֲזִי לָנָא מִפּוּמָהּ עַל אַרְעָא. וְתוּב אַקְרִינוּהָ לִפְלוֹנִית דָּא כָּכָה יֵעָשֶׂה לָאִישׁ אֲשֶׁר לֹא יִבְנֶה אֶת בֵּית אָחִיו וְנִקְרָא שְׁמוֹ בְּיִשְׂרָאֵל בֵּית חֲלוּץ הַנָּעַל. וַאֲנַחְנָא דַּיָּנֵי וְכָל דְּהַוּוּ יָתְבִין קָדֳמָנָא עֲנֵינָן בַּתְרֵיהּ חֲלוּץ הַנָּעַל חֲלוּץ הַנָּעַל חֲלוּץ הַנָּעַל תְּלַת זִמְנִין. וּמִדְּאִיתְעֲבִיד עֻבְדָּא דָּא קָדֳמָנָא שָׁרִינוּהָ לִפְלוֹנִית דָּא לִמְהָךְ לְהִתְנַסְבָּא לְכָל מַאן דְּתִצְבֵּי וְאִינַשׁ לֹא יִמְחֶה בְּיֳדָהּ מִן יוֹמָא דְּנָן וּלְעָלַם. וּבָעִית מִנָּנָא פְּלוֹנִית דָּא גִּטָּא דַּחֲלִיצוּתָא דָּא וּכְתַבְנָא וַחֲתַמְנָא וִיהַבְנָא לָהּ לִזְכוּ כְּדַת משֶׁה וְיִשְׂרָאֵל. פְּלוֹנִי בַּר פְּלוֹנִי עֵד. פְּלוֹנִי בַּר פְּלוֹנִי עֵד:","וּמְעִידִין עָלָיו שְׁלֹשָׁה אוֹ שְׁנַיִם מִן הַשְּׁלֹשָׁה אוֹ שְׁנַיִם שֶׁרָאוּ הַחֲלִיצָה אַף עַל פִּי שֶׁאֵינָן הַדַּיָּנִין שֶׁחָלְצָה בִּפְנֵיהֶן כְּמוֹ שֶׁבֵּאַרְנוּ. וַאֲפִלּוּ אִשָּׁה אוֹ עֶבֶד אוֹ קָטָן שֶׁהוּא מַכִּיר וְנָבוֹן נֶאֱמָנִין לוֹמַר זֶה פְּלוֹנִי אָחִי פְּלוֹנִי וְזוֹ הִיא יְבִמְתּוֹ וְחוֹלְצִין עַל פִּיהֶן. מַה שֶּׁאֵין כֵּן בִּשְׁאָר עֵדֻיּוֹת שֶׁל תּוֹרָה בֵּין לְעֵדוּת מָמוֹן בֵּין לְעֵדוּת אִסּוּר. שֶׁזֶּה דָּבָר הֶעָשׂוּי לְהִגָּלוֹת הוּא אֶפְשָׁר לֵידַע אֲמִתַּת הַדָּבָר שֶׁלֹּא מִפִּיהֶן כָּעִנְיָן שֶׁבֵּאַרְנוּ בְּסוֹף הִלְכוֹת גֵּרוּשִׁין. וְאִם רָצָה הַיָּבָם לְיַבֵּם מְקַדֵּשׁ וּמְיַבֵּם וְכוֹתֵב לָהּ כְּתֻבָּה כְּמוֹ שֶׁהוֹדַעְנוּ:","וזהו נוסח כתובת יבמין שנהגו העם: בְּיוֹם פְּלוֹנִי כָּךְ וְכָךְ לְיֶרַח פְּלוֹנִי שְׁנַת כָּךְ וְכָךְ לְמִנְיַן פְּלוֹנִי לְמִנְיָנָא דְּרָגִילְנָא לְמִימְנֵי בְּמָקוֹם פְּלוֹנִי אֵיךְ פְּלוֹנִי בֶּן פְּלוֹנִי אָתָא לָקֳדָמָנָא וְכֵן אָמַר לָנָא. אָחִי דְּמִן אַבָּא שָׁכִיב וְחַיֵּי לְרַבָּנָן וּלְכָל יִשְׂרָאֵל שָׁבַק. וּבַר וּבָרַת יָרִית וּמַחְסִין וּמוֹקִים שְׁמָא בְּיִשְׂרָאֵל לֹא שָׁבַק. וְשָׁבַק הַהִיא אִתְּתָא דִּשְׁמָהּ פְּלוֹנִית בַּת פְּלוֹנִי וְחָזִי לִי מִן אוֹרַיְתָא לְיִבּוּמֵי יָתָהּ כְּדִכְתִיב בְּסֵפֶר אוֹרַיְתָא דְּמשֶׁה יְבָמָהּ יָבֹא עָלֶיהָ. וּצְבִיאַת פְּלוֹנִית דָּא וְאִתְיַבְּמַת לִפְלוֹנִי בַּר פְּלוֹנִי יְבָמָהּ לְאוֹקוּמֵי שְׁמָא בְּיִשְׂרָאֵל כְּדִכְתִיב וְהָיָה הַבְּכוֹר אֲשֶׁר תֵּלֵד יָקוּם עַל שֵׁם אָחִיו הַמֵּת וְגוֹ'. וְכָתַב לָהּ פְּלוֹנִי יְבָמָהּ לִפְלוֹנִית יְבִמְתֵּיהּ כֶּסֶף זוּזֵי מָאתָן דְּחָזוּ לָהּ דַּהֲווּ כְּתִיבִין בִּכְתֻבָּתָהּ דְּכָתַב לָהּ בַּעְלָהּ קַדְמָאָה וְאוֹסִיף לָהּ מִדִּילֵיהּ כָּךְ וְכָךְ וְדָא נְדוּנְיָא דְּהַנְעָלַת לֵיהּ וְכוּ' כִּשְׁאָר טָפְסֵי כְּתֻבּוֹת:","טופס הכתובה: בְּיוֹם פְּלוֹנִי כוּ'. אֵיךְ פְּלוֹנִי בֶּן פְּלוֹנִי אָמַר לִפְלוֹנִית בַּת פְּלוֹנִי בְּתֻלְתָּא כַּלָּתָא הֱוִי לִי לְאִנְתּוּ כְּדַת משֶׁה וְיִשְׂרָאֵל וַאֲנָא בְּמֵימַר דִּשְׁמַיָּא אֶפְלַח וְאוֹקִיר וַאֲסוֹבַר וְאֵיזוּן וַאֲפַרְנֵס וְאִכְסֵי יָתִיכִי כְּהִלְכוֹת גֻּבְרִין יְהוּדָאִין דְּמוֹקְרִין וּמְסוֹבְרִין וְזָנִין וּמְפַרְנְסִין וּמְכַסִּין יָת נְשֵׁיהוֹן בְּקֻשְׁטָא. וְיָהִיבְנָא לֵיכִי מֹהַר בְּתֻלֵּיכִי כֶּסֶף זוּזֵי מָאתָן דְּאִינוּן מִזּוּזֵי כַּסְפָּא כ״‎ה דְּחָזוּ לֵיכִי מִדְּאוֹרַיְתָא וּמְזוֹנַיְכִי וּכְסוּתַיְכִי וְסִפּוּקַיְכִי. וּמֵעַל עָלַיְכִי כְּאֹרַח כָּל אַרְעָא. וּצְבִיאַת פְּלוֹנִית דָּא וַהֲוַת לֵיהּ לְאִנְתּוּ לִפְלוֹנִי דְּנָא. וְרָצָה וְהוֹסִיף לָהּ תּוֹסֶפֶת עַל עִקַּר כְּתֻבָּתָהּ עַד מִשְׁלַם כָּךְ וְכָךְ וְדָא נְדוּנְיָא דְּהַנְעָלַת לֵיהּ כָּךְ וְכָךְ הַכּל נִתְקַבֵּל חָתָן זֶה וּבָא לְיָדוֹ וְנַעֲשֶׂה בִּרְשׁוּתוֹ וְזָקַף הַכּל עַל עַצְמוֹ כְּמִלְוֶה וּרְשׁוּ. וְכֵן אָמַר לָנָא פְּלוֹנִי חֲתָנָא דְּנָא אַחֲרָיוּת כְּתֻבְתָּא כּלָא עִקַּר כְּתֻבָּה וּנְדוּנְיָא וְתוֹסֶפֶת וּשְׁאָר תְּנָאֵי כְּתֻבָּה קַבָּלִית עָלַי וְעַל יַרְתַי בַּתְרָאִי וְעַל כָּל שְׁפַר אֲרַג נִכְסִין וְקִנְיָנִין דְּאִית לִי תְּחוֹת [כָּל] שְׁמַיָּא דְּקַנָּאִי וּדְעָתִיד אֲנָא לְמִיקְנָה מִמְּקַרְקְעֵי וּמִמִּטַּלְטְלֵי אַגַּב מְקַרְקְעֵי כֻּלְּהוֹן יֵהוֹן אַחְרָאִין וְעַרְבָאִין לִכְתֻבָּה דָּא כּלָא עִקָּר וּנְדוּנְיָא וְתוֹסֶפֶת לְאִתְפָּרְעָא מִנְּהוֹן בְּחַיַּי וּבָתַר מוֹתִי וַאֲפִלּוּ מִגְּלִימָא דְּעַל כַּתְפָאִי. וְקָנִינָן מִפְּלוֹנִי דָּא מִכָּל מַאי דִּכְתִיב וּמְפָרַשׁ לְעֵילָא קִנְיָן שָׁלֵם דְּלֹא כְּאַסְמַכְתָּא וּדְלָא כְּטֹפְסָא דִּשְׁטָרֵי אֶלָּא כְּחֹזֶק וּכְחֹמֶר כָּל שִׁטְרֵי כְּתֻבּוֹת הַנּוֹהֲגוֹת בְּיִשְׂרָאֵל וְכַהֹגֶן וּכְתִקּוּן רַבּוֹתֵינוּ זַ״‎ל וְחָתַמְנוּ עַל שְׁטַר כְּתֻבָּה זוֹ בַּזְּמַן הַנִּזְכָּר לְעֵיל וְהַכּל בָּרִיר וְשָׁרִיר וְקַיָּם:","וְאִם הָיְתָה כְּתֻבַּת אַלְמָנָה כּוֹתֵב פְּלוֹנִית אַלְמְנָתָא. וְאִם הָיְתָה כְּתֻבַּת גְּרוּשָׁה כּוֹתֵב פְּלוֹנִית הַגְּרוּשָׁה. וְכֵן אִם הָיְתָה שְׁבוּיָה כּוֹתֵב פְּלוֹנִית הַשְּׁבוּיָה כְּדֵי שֶׁלֹּא יִכָּשֵׁל בָּהּ כֹּהֵן. וְכוֹתֵב וְיָהִיבְנָא לֵיכִי מֹהַרַיְכִי כֶּסֶף זוּזֵי מֵאָה דְּאִינוּן מִזּוּזֵי כַּסְפָּא תְּרֵיסַר וּפַלְגָּא דְּחָזוּ לֵיכִי וְכוּ':","כְּשֶׁכּוֹתְבִין גֵּט יְבָמִין אוֹ כְּתֻבַּת יְבָמִין מְשַׂרְטֵט מְקוֹם הַפְּסוּקִים. שֶׁאָסוּר לִכְתֹּב שָׁלֹשׁ תֵּבוֹת בְּלֹא שִׂרְטוּט. וִיבָמָה שֶׁחָלְצָה מֻתֶּרֶת לְהִנָּשֵׂא בְּיוֹם חֲלִיצָתָהּ שֶׁהֲרֵי אֵינָהּ חוֹלֶצֶת עַד שֶׁתַּשְׁלִים תִּשְׁעִים יוֹם:"],"Mishneh Torah, Marriage 16":["הַנְּכָסִים שֶׁמַּכְנֶסֶת הָאִשָּׁה לְבַעְלָהּ בֵּין קרְקַע בֵּין מִטַּלְטְלִין בֵּין עֲבָדִים אַף עַל פִּי שֶׁהֵן נִכְתָּבִין בִּשְׁטַר הַכְּתֻבָּה אֵינָן נִקְרָאִין כְּתֻבָּה אֶלָּא נְדוּנְיָא שְׁמָם. וְאִם קִבֵּל הַבַּעַל אַחֲרָיוּת הַנְּדוּנְיָא עָלָיו וְנַעֲשֵׂית בִּרְשׁוּתוֹ אִם פָּחֲתָה פָּחֲתָה לוֹ וְאִם הוֹתִירָה הוֹתִירָה לוֹ הֲרֵי זוֹ נִקְרֵאת נִכְסֵי צֹאן בַּרְזֶל. וְאִם לֹא קִבֵּל אַחֲרָיוּת הַנְּדוּנְיָא עָלָיו אֶלָּא הֲרֵי הִיא בִּרְשׁוּת הָאִשָּׁה אִם פָּחֲתָה פָּחֲתָה לָהּ וְאִם הוֹתִירָה הוֹתִירָה לָהּ הֲרֵי זוֹ נִקְרֵאת נִכְסֵי מְלוֹג:","וְכֵן כָּל נְכָסִים שֶׁיֵּשׁ לָאִשָּׁה שֶׁלֹּא הִכְנִיסָה אוֹתָן לְבַעְלָהּ וְלֹא כָּתְבוּ אוֹתָן בַּכְּתֻבָּה אֶלָּא נִשְׁאֲרוּ לְעַצְמָהּ. אוֹ נָפְלוּ לָהּ בַּיְרֻשָּׁה אַחַר שֶׁנִּתְאָרְסָה אוֹ נִתְּנוּ לָהּ בְּמַתָּנָה. הַכּל נִקְרָאִין נִכְסֵי מְלוֹג שֶׁכֻּלָּן בִּרְשׁוּתָהּ הֵן. וְאֵין נִקְרָאִין כְּתֻבָּה אֶלָּא עִקַּר כְּתֻבָּה שֶׁהוּא מֵאָה אוֹ מָאתַיִם עִם הַתּוֹסֶפֶת בִּלְבַד:","כְּבָר הוֹדַעְנוּ שֶׁחֲכָמִים תִּקְּנוּ כְּתֻבָּה לָאִשָּׁה וְדִין הַתּוֹסֶפֶת כְּדִין הָעִקָּר. וְלֹא תִּקְּנוּ לִגְבּוֹתָהּ כָּל זְמַן שֶׁתִּרְצֶה אֶלָּא הֲרֵי הִיא כְּחוֹב שֶׁיֵּשׁ לוֹ זְמַן וְאֵין הַכְּתֻבָּה נִגְבֵּית אֶלָּא לְאַחַר מִיתַת הַבַּעַל אוֹ אִם גֵּרְשָׁהּ. וְכֵן הִתְקִינוּ שֶׁאִם הָיוּ לַבַּעַל שָׂדוֹת טוֹבוֹת וְרָעוֹת וּבֵינוֹנִיּוֹת וּבָאָה הָאִשָּׁה לִגְבּוֹת כְּתֻבָּתָהּ מִמֶּנּוּ שֶׁלֹּא תִּגְבֶּה אֶלָּא מִן הָרָעָה שֶׁבִּנְכָסָיו וְהִיא הַנִּקְרֵאת זִבּוּרִית:","וְכֵן הִתְקִינוּ שֶׁכְּשֶׁתָּבוֹא לִגְבּוֹת כְּתֻבָּתָהּ אַחַר מוֹתוֹ לֹא תִּגְבֶּה עַד שֶׁתִּשָּׁבַע בִּנְקִיטַת חֵפֶץ שֶׁלֹּא הִנִּיחַ אֶצְלָהּ כְּלוּם וְלֹא מָכְרָה לוֹ כְּתֻבָּתָהּ וְלֹא מָחֲלָה אוֹתָהּ. וְשָׁמִין לָהּ כָּל מַה שֶּׁעָלֶיהָ וּפוֹחֲתִין אוֹתוֹ מִכְּתֻבָּתָהּ. אֲבָל אִם גֵּרְשָׁהּ לִרְצוֹנוֹ גּוֹבָה בְּלֹא שְׁבוּעָה וְאֵין שָׁמִין כְּסוּת שֶׁעָלֶיהָ שֶׁהֲרֵי לְקָחָן לָהּ וְזָכְתָה בָּהֶן וְהוּא רוֹצֶה לְהוֹצִיאָהּ לֹא הִיא:","וְכֵן הִתְקִינוּ שֶׁלֹּא תִּגְבֶּה הָאַלְמָנָה כְּתֻבָּתָהּ אֶלָּא מִן הַקַּרְקַע. וְאֵינָהּ גּוֹבָה מִשֶּׁבַח שֶׁשָּׁבְחוּ נְכָסִים לְאַחַר מִיתַת הַבַּעַל. וְאֵין הַבָּנוֹת נִזּוֹנוֹת לְאַחַר מִיתַת אֲבִיהֶן מִשֶּׁבַח שֶׁשָּׁבְחוּ נְכָסִים לְאַחַר מִיתָתוֹ. וְאֵינָהּ טוֹרֶפֶת בִּכְתֻבָּתָהּ בְּשֶׁבַח שֶׁהִשְׁבִּיחַ הַלּוֹקֵחַ אַף עַל פִּי שֶׁבַּעַל חוֹב גּוֹבֶה אֶת הַשֶּׁבַח. וּדְבָרִים אֵלּוּ מִקֻּלֵּי כְּתֻבָּה הֵם:","וְכֵן מִקֻּלֵּי כְּתֻבָּה שֶׁתִּטּל הָאִשָּׁה בִּכְתֻבָּתָהּ מִן הַפָּחוּת שֶׁבַּמַּטְבְּעוֹת. כֵּיצַד. נָשָׂא אִשָּׁה בְּמָקוֹם אֶחָד וְגֵרְשָׁהּ בְּמָקוֹם אַחֵר. אִם הָיוּ מְעוֹת מְקוֹם הַנִּשּׂוּאִין טוֹבִים מִמְּעוֹת מְקוֹם הַגֵּרוּשִׁין נוֹתֵן לָהּ מִמְּעוֹת מְקוֹם הַגֵּרוּשִׁין. וְאִם הָיוּ מְעוֹת מְקוֹם הַגֵּרוּשִׁין טוֹבִים מִמְּעוֹת מְקוֹם הַנִּשּׂוּאִין נוֹתֵן לָהּ מִמְּעוֹת מְקוֹם הַנִּשּׂוּאִין. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁהָיָה בִּכְתֻבָּתָהּ מָעוֹת סְתָם. אֲבָל אִם פֵּרֵשׁ בָּהּ מַטְבֵּעַ יָדוּעַ בֵּין בַּעִקָּר בֵּין בַּתּוֹסֶפֶת הֲרֵי הִיא כְּדִין הַמַּלְוֶה אֶת חֲבֵרוֹ מַטְבֵּעַ יָדוּעַ שֶׁנּוֹתֵן לוֹ כַּמָּה שֶׁהִלְּוָהוּ כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת הַלְוָאָה:","תִּקְּנוּ הַגְּאוֹנִים בְּכָל הַיְשִׁיבוֹת שֶׁתִּהְיֶה הָאִשָּׁה גּוֹבָה כְּתֻבָּתָהּ אַחֲרֵי מוֹת בַּעְלָהּ אַף מִן הַמִּטַּלְטְלִין כְּדֶרֶךְ שֶׁהִתְקִינוּ לְבַעַל חוֹב לִגְבּוֹת מִן הַמִּטַּלְטְלִין. וּפָשְׁטָה תַּקָּנָה זוֹ בְּרֹב יִשְׂרָאֵל. וְכֵן שְׁאָר תְּנָאֵי כְּתֻבָּה כֻּלָּן כִּכְתֻבָּה הֵן וְיֶשְׁנָן בְּמִטַּלְטְלִין כְּבַקַּרְקַע. חוּץ מִכְּתֻבַּת בְּנִין דִּכְרִין שֶׁלֹּא מָצָאנוּ מִנְהַג יְרֻשָּׁתָן פָּשׁוּט בְּכָל הַיְשִׁיבוֹת. לְפִיכָךְ אֲנִי אוֹמֵר מַעֲמִידִין אוֹתָהּ עַל דִּין הַגְּמָרָא שֶׁאֵין יוֹרְשִׁין כְּתֻבַּת אִמָּן אֶלָּא מִן הַקַּרְקַע:","כְּבָר נָהֲגוּ בְּכָל הַמְּקוֹמוֹת שֶׁיָּדַעְנוּ וְשֶׁשָּׁמַעְנוּ שִׁמְעָן שֶׁיִּכְתְּבוּ בַּכְּתֻבָּה בֵּין מִמְּקַרְקְעֵי בֵּין מִמִּטַּלְטְלֵי. וְדָבָר זֶה תִּקּוּן גָּדוֹל הוּא וַאֲנָשִׁים גְּדוֹלִים וּנְבוֹנִים הִנְהִיגוּ דָּבָר זֶה שֶׁהֲרֵי זֶה תְּנַאי שֶׁבְּמָמוֹן וְנִמְצָא הָאַלְמָנָה גּוֹבָה מִן הַמִּטַּלְטְלִין בִּתְנַאי זֶה לֹא בְּתַקָּנַת אַחֲרוֹנִים:","הֲרֵי שֶׁלֹּא כָּתַב כָּךְ בִּשְׁטַר הַכְּתֻבָּה אֶלָּא נָשָׂא סְתָם. אִם הָיָה יוֹדֵעַ בְּתַקָּנָה זוֹ שֶׁל גְּאוֹנִים גּוֹבָה. וְאִם לָאו אוֹ שֶׁנִּסְתַּפֵּק לָנוּ הַדָּבָר מִתְיַשְּׁבִין בַּדָּבָר הַרְבֵּה שֶׁאֵין כֹּחַ בְּתַקָּנַת הַגְּאוֹנִים לָדוּן בָּהּ אַף עַל פִּי שֶׁלֹּא נִתְפָּרְשָׁה כְּדִין תְּנָאֵי כְּתֻבָּה שֶׁהֵם תַּקָּנַת הַסַּנְהֶדְרִין הַגְּדוֹלָה עַד שֶׁנּוֹצִיא בָּהּ מָמוֹן מִן הַיּוֹרְשִׁים:","וְעוֹד תִּקְּנוּ חֲכָמִים שֶׁיִּהְיוּ כָּל נִכְסֵי הַבַּעַל אַחְרָאִין וְעַרְבָאִין לִכְתֻבָּה אֲפִלּוּ כְּתֻבָּתָהּ מָנֶה וְיֵשׁ לוֹ קַרְקַע בְּאַלְפַּיִם זְהוּבִים הַכּל תַּחַת שִׁעְבּוּד הַכְּתֻבָּה. וְכָל שֶׁיִּמְכֹּר אַחַר הַנִּשּׂוּאִין מִנְּכָסָיו אַף עַל פִּי שֶׁמִּמְכָּרוֹ קַיָּם וְיֵשׁ לוֹ לִמְכֹּר כָּל נְכָסָיו אִם יִרְצֶה יֵשׁ לָהּ לִטְרֹף אוֹתָן בִּכְתֻבָּתָהּ כְּשֶׁיְּגָרְשֶׁנָּה אוֹ כְּשֶׁיָּמוּת אִם לֹא תִּמְצָא נְכָסִים בְּנֵי חוֹרִין. וּכְשֶׁתִּטְרֹף לֹא תִּטְרֹף אֶלָּא בִּשְׁבוּעָה בִּנְקִיטַת חֵפֶץ כְּדִין כָּל בַּעֲלֵי חוֹבוֹת. וְתַקָּנָה זוֹ כְּדֵי שֶׁלֹּא תִּהְיֶה כְּתֻבָּה קַלָּה בְּעֵינָיו:","כְּשֶׁמַּשְׁבִּיעִין בֵּית דִּין אוֹ הַיּוֹרְשִׁין אֶת הָאַלְמָנָה כְּשֶׁתָּבוֹא לִגְבּוֹת כְּתֻבָּתָהּ אֵין מַשְׁבִּיעִין אוֹתָהּ אֶלָּא חוּץ לְבֵית דִּין. מִפְּנֵי שֶׁבָּתֵּי דִּינִין הָיוּ נִמְנָעִין מִלְּהַשְׁבִּיעָהּ שֶׁחוֹשְׁשִׁין לָהּ שֶׁמָּא לֹא תְּדַקְדֵּק עַל עַצְמָהּ בִּשְׁבוּעָה. וְאִם רָצוּ הַיְתוֹמִים לְהַדִּירָהּ נוֹדֶרֶת לָהֶן כָּל מַה שֶּׁיִּרְצוּ וּמַדִּירִין אוֹתָהּ בְּבֵית דִּין וְאַחַר כָּךְ נוֹטֶלֶת כְּתֻבָּתָהּ:","מֵתָה הָאַלְמָנָה קֹדֶם שֶׁתִּשָּׁבַע אֵין יוֹרְשֶׁיהָ יוֹרְשִׁין מִכְּתֻבָּתָהּ כְּלוּם שֶׁאֵין לָהּ כְּתֻבָּה עַד שֶׁתִּשָּׁבַע. וְאִם נִשֵּׂאת קֹדֶם שֶׁתִּשָּׁבַע הֲרֵי זוֹ נִשְׁבַּעַת אַחַר הַנִּשּׂוּאִין וְנוֹטֶלֶת כָּל זְמַן שֶׁתִּרְצֶה. אֲבָל אֵינָהּ נוֹדֶרֶת וְנוֹטֶלֶת שֶׁמָּא יָפֵר לָהּ הַבַּעַל:","יִחֵד לָהּ קַרְקַע בִּכְתֻבָּתָהּ בֵּין שֶׁיִּחֵד בְּאַרְבַּעַת הַמְּצָרִים בֵּין בְּמֵצַר אֶחָד גּוֹבָה אֶת כְּתֻבָּתָהּ מִמֶּנָּה בְּלֹא שְׁבוּעָה. וְכֵן אִם כָּתַב לָהּ מִטַּלְטְלִין וְהֵן עַצְמָן קַיָּמִין נוֹטֶלֶת אוֹתָן בְּלֹא שְׁבוּעָה. וְכֵן אִם נִמְכְּרוּ וְנִלְקַח בָּהֶן מִטַּלְטְלִין אֲחֵרִים וְנוֹדַע שֶׁאֵלּוּ הַשְּׁנִיִּם מִדְּמֵי הַמִּטַּלְטְלִין הָרִאשׁוֹנִים נוֹטַלְתָּן בְּלֹא שְׁבוּעָה:","הַפּוֹגֶמֶת כְּתֻבָּתָהּ לֹא תִּפָּרַע אֶלָּא בִּשְׁבוּעָה. כֵּיצַד. הוֹצִיאָה שְׁטַר כְּתֻבָּה שֶׁיֵּשׁ בּוֹ אֶלֶף זוּז הַבַּעַל אוֹמֵר נִתְקַבַּלְתְּ הַכּל וְהִיא אוֹמֶרֶת לֹא נִתְקַבַּלְתִּי אֶלָּא כָּךְ וְכָךְ. וַאֲפִלּוּ יֵשׁ עָלֶיהָ עֵדִים בַּמִּקְצָת שֶׁנָּטְלָה וַאֲפִלּוּ דִּקְדְּקָה עַצְמָהּ בְּחֶשְׁבּוֹן מַה שֶּׁנָּטְלָה בַּחֲצִי פְּרוּטָה לֹא תִּטּל הַשְּׁאָר אֶלָּא בִּשְׁבוּעָה:","אָמַר הַבַּעַל נִתְקַבַּלְתְּ הַכּל וְהִיא אוֹמֶרֶת לֹא נִתְקַבַּלְתִּי כְּלוּם וְעַד אֶחָד מֵעִיד עָלֶיהָ שֶׁנִּתְקַבְּלָה הַכּל אוֹ מִקְצָת לֹא תִּפָּרַע כָּל הַכְּתֻבָּה אֶלָּא בִּשְׁבוּעָה:","הַנִּפְרַעַת שֶׁלֹּא בְּפָנָיו לֹא תִּפָּרַע אֶלָּא בִּשְׁבוּעָה. כֵּיצַד. הֲרֵי שֶׁגֵּרֵשׁ אֶת אִשְׁתּוֹ וְהָלַךְ לוֹ. בֵּית דִּין יוֹרְדִין לִנְכָסָיו אַחַר שֶׁתִּשָּׁבַע וּמַגְבִּין אוֹתָהּ כְּתֻבָּתָהּ. וְהוּא שֶׁיִּהְיֶה בְּמָקוֹם רָחוֹק שֶׁיֵּשׁ לָהֶן טֹרַח לְהוֹדִיעוֹ. אֲבָל אִם הָיָה בְּמָקוֹם קָרוֹב לְהוֹדִיעוֹ שׁוֹלְחִין לוֹ וּמוֹדִיעִין אוֹתוֹ. וְאִם לֹא יָבוֹא תִּשָּׁבַע וְתִטּל:","הַפּוֹחֶתֶת כְּתֻבָּתָהּ נִפְרַעַת שֶׁלֹּא בִּשְׁבוּעָה. כֵּיצַד. הוֹצִיאָה שְׁטַר כְּתֻבָּה בְּאֶלֶף זוּז הוּא אוֹמֵר נִתְקַבַּלְתְּ הַכּל וְהִיא אוֹמֶרֶת לֹא נִתְקַבַּלְתִּי כְּלוּם וְאֵין לִי אֶלָּא חָמֵשׁ מֵאוֹת זוּז וְזֶה שֶׁכָּתַב לִי אֶלֶף אֲמָנָה הָיְתָה בֵּינִי לְבֵינוֹ הֲרֵי זוֹ נִפְרַעַת שֶׁלֹּא בִּשְׁבוּעָה. אֲבָל אִם אָמְרָה אֵין בִּשְׁטַר כְּתֻבָּתִי אֶלָּא חֲמֵשׁ מֵאוֹת אֵינָהּ נִפְרַעַת בִּשְׁטָר זֶה שֶׁיֵּשׁ בּוֹ אֶלֶף זוּז כְּלוּם שֶׁהֲרֵי בִּטְּלָה אוֹתוֹ וּכְאִלּוּ הוֹדֵית שֶׁהוּא שֶׁקֶר. לְפִיכָךְ נִשְׁבַּע שְׁבוּעַת הֶסֵּת וְנִפְטָר:","כָּל מָקוֹם שֶׁאָמַרְנוּ לֹא תִּפָּרַע אֶלָּא בִּשְׁבוּעָה אוֹמְרִים לָהּ בֵּית דִּין הִשָּׁבְעִי וּטְלִי. וּמָקוֹם שֶׁאָמַרְנוּ תִּפָּרַע שֶׁלֹּא בִּשְׁבוּעָה אוֹמְרִים לַבַּעַל עֲמֹד וְתֵן לָהּ וְאֵין אַתָּה נֶאֱמָן בְּטַעֲנָה זוֹ עַד שֶׁתָּבִיא רְאָיָה לִדְבָרֶיךָ:","אָמַר הַבַּעַל מֵעַצְמוֹ תִּשָּׁבַע לִי עַל טַעֲנָתִי אוֹמְרִין לָהּ הִשָּׁבְעִי וּטְלִי וְתִשָּׁבַע בִּנְקִיטַת חֵפֶץ. הִתְנֵית עִמּוֹ שֶׁתִּגְבֶּה כְּתֻבָּתָהּ שֶׁלֹּא בִּשְׁבוּעָה אוֹ שֶׁתְּהֵא נֶאֱמֶנֶת בְּכָל מַה שֶּׁתִּטְעֹן גּוֹבָה מִמֶּנּוּ בְּלֹא שְׁבוּעָה כְּלָל. אֲבָל אִם בָּאָה לִגְבּוֹת מִיּוֹרְשָׁיו תִּשָּׁבַע וְאַחַר כָּךְ תִּטּל:","הִתְנֵית עִמּוֹ שֶׁתִּגְבֶּה כְּתֻבָּתָהּ מִיּוֹרְשָׁיו בְּלֹא שְׁבוּעָה אוֹ שֶׁתִּהְיֶה נֶאֱמֶנֶת בְּכָל מַה שֶּׁתִּטְעֹן עַל יוֹרְשָׁיו הֲרֵי זוֹ נוֹטֶלֶת מֵהֶן בְּלֹא שְׁבוּעָה. אֲבָל אִם בָּאָה לִטְרֹף מִנְּכָסִים מְשֻׁעְבָּדִים לֹא תִּטְרֹף אֶלָּא בִּשְׁבוּעָה. וְאַף עַל פִּי שֶׁהֶאֱמִינָהּ הַבַּעַל. שֶׁאֵין תְּנַאי הַבַּעַל מוֹעִיל אֶלָּא עָלָיו וְעַל יוֹרְשָׁיו אֲבָל לְהַפְסִיד מָמוֹן אֲחֵרִים אֵינוֹ מוֹעִיל:","אַלְמָנָה שֶׁהָיָה שְׁטַר כְּתֻבָּה יוֹצֵא מִתַּחַת יָדָהּ נִשְׁבַּעַת וְגוֹבָה כְּתֻבָּתָהּ לְעוֹלָם אֲפִלּוּ אַחַר מֵאָה שָׁנָה. בֵּין שֶׁהָיְתָה בְּבֵית בַּעְלָהּ בֵּין שֶׁהָיְתָה בְּבֵית אָבִיהָ. וְאִם אֵין שְׁטַר כְּתֻבָּה יוֹצֵא מִתַּחַת יָדָהּ אֵין לָהּ כְּלוּם וַאֲפִלּוּ עִקַּר כְּתֻבָּה וַאֲפִלּוּ תָּבְעָה בְּיוֹם מִיתַת בַּעְלָהּ. וְכֵן הַגְּרוּשָׁה אֲפִלּוּ עִקַּר כְּתֻבָּה אֵין לָהּ עַד שֶׁתּוֹצִיא שְׁטַר כְּתֻבָּה:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּמָקוֹם שֶׁדַּרְכָּן לִכְתֹּב כְּתֻבָּה. אֲבָל בְּמָקוֹם שֶׁאֵין דַּרְכָּן לִכְתֹּב כְּתֻבָּה אֶלָּא סוֹמְכִין עַל תְּנַאי בֵּית דִּין הֲרֵי זוֹ גּוֹבָה עִקַּר כְּתֻבָּה אַף עַל פִּי שֶׁאֵין בְּיָדָהּ שְׁטַר כְּתֻבָּה בֵּין נִתְגָּרְשָׁה בֵּין נִתְאַלְמְנָה בֵּין שֶׁהָיְתָה בְּבֵית בַּעְלָהּ בֵּין שֶׁהָיְתָה בְּבֵית אָבִיהָ. אֲבָל תּוֹסֶפֶת אֵין לָהּ בְּכָל מָקוֹם אֶלָּא בִּרְאָיָה בְּרוּרָה:","וְעַד כַּמָּה תִּגְבֶּה הָאַלְמָנָה הָעִקָּר בְּמָקוֹם שֶׁאֵין כּוֹתְבִין כְּתֻבָּה. אִם הָיְתָה בְּבֵית בַּעְלָהּ גּוֹבָה לְעוֹלָם. וְאִם הָיְתָה בְּבֵית אָבִיהָ עַד עֶשְׂרִים וְחָמֵשׁ שָׁנָה. וְאִם בָּאָה לִתְבֹּעַ אַחַר עֶשְׂרִים וְחָמֵשׁ שָׁנָה אֵין לָהּ כְּלוּם שֶׁאִלּוּ לֹא מָחֲלָה לֹא שָׁתְקָה כָּל זְמַן זֶה. וַהֲרֵי אֵינָהּ עִם הַיּוֹרְשִׁים כְּדֵי שֶׁתֹּאמַר נִכְלַמְתִּי מִלְּתָבְעָן וְהֵן עִמִּי בַּבַּיִת:","לְפִיכָךְ אִם הָיָה הַיּוֹרֵשׁ עַצְמוֹ מוֹלִיךְ מְזוֹנוֹתֶיהָ לְבֵית אָבִיהָ וּמְטַפֵּל בָּהּ יֵשׁ לָהּ לִתְבֹּעַ כְּתֻבָּתָהּ וַאֲפִלּוּ אַחַר כ\"ה שָׁנָה מִפְּנֵי שֶׁזּוֹ שֶׁשָּׁתְקָה וְלֹא תָּבְעָה מִפְּנֵי שֶׁהִיא בּוֹשָׁה מִן הַיּוֹרֵשׁ:","הִיא אוֹמֶרֶת בְּתוּלָה נִשֵּׂאתִי וְעִקַּר כְּתֻבָּתִי מָאתַיִם וְהַבַּעַל אוֹ יוֹרְשָׁיו אוֹמְרִים בְּעוּלָה נִשֵּׂאת וְאֵין לָהּ אֶלָּא מֵאָה. אִם יֵשׁ עֵדִים שֶׁרָאוּ שֶׁעָשׂוּ לָהּ הַמִּנְהָגוֹת שֶׁנָּהֲגוּ אַנְשֵׁי אוֹתָהּ הָעִיר לַעֲשׂוֹתָן לִבְתוּלָה כְּגוֹן מִינֵי שִׂמְחָה אוֹ כְּתָרִים אוֹ מַלְבּוּשׁ יָדוּעַ אוֹ שְׁאָר דְּבָרִים שֶׁאֵין עוֹשִׂין כָּךְ אֶלָּא לִבְתוּלָה הֲרֵי זוֹ נוֹטֶלֶת מָאתַיִם. וְאִם אֵין לָהּ עֵדִים בָּזֶה הֲרֵי זוֹ נוֹטֶלֶת מָנֶה. וְאִם הָיָה הַבַּעַל קַיָּם יֵשׁ לָהּ לְהַשְׁבִּיעוֹ שְׁבוּעַת הַתּוֹרָה שֶׁהֲרֵי הוֹדָה בְּמִקְצָת הַטַּעֲנָה. וְנֶאֱמָן הַקָּטָן לְהָעִיד בְּגָדְלוֹ וְלוֹמַר זָכוּר אֲנִי כְּשֶׁהָיִיתִי קָטָן שֶׁנַּעֲשָׂה לִפְלוֹנִית מִנְהַג הַבְּתוּלוֹת. וְכָל הַדְּבָרִים הָאֵלּוּ בְּמָקוֹם שֶׁאֵין כּוֹתְבִין כְּתֻבָּה כְּמוֹ שֶׁאָמַרְנוּ:","הָאִשָּׁה שֶׁאָמְרָה לְבַעְלָהּ גֵרַשְׁתַּנִי נֶאֱמֶנֶת, שֶׁאֵינָהּ מְעִזָּה פָּנֶיהָ בִּפְנֵי בַּעְלָהּ. לְפִיכָךְ הָאִשָּׁה שֶׁהוֹצִיאָה שְׁטַר כְּתֻבָּה וְאֵין עִמָּהּ גֵּט וְאָמְרָה לְבַעְלָהּ גֵּרַשְׁתַּנִי וְאָבַד גִּטִּי תֵּן לִי כְּתֻבָּתִי וְהוּא אוֹמֵר לֹא גֵּרַשְׁתִּיךְ חַיָּב לִתֵּן לָהּ עִקַּר כְּתֻבָּה. אֲבָל אֵינוֹ נוֹתֵן לָהּ הַתּוֹסֶפֶת עַד שֶׁתָּבִיא רְאָיָה שֶׁגֵּרְשָׁהּ אוֹ שֶׁיָּצָא גֵּט עִם הַכְּתֻבָּה מִתַּחַת יָדָהּ:","אָמַר לָהּ הַבַּעַל כָּךְ הָיָה גֵּרַשְׁתִּי וְנָתַתִּי לָהּ כָּל הַכְּתֻבָּה עִקָּר וְתוֹסֶפֶת וְכָתְבָה לִי שׁוֹבֵר וְאָבַד שׁוֹבְרִי. מִתּוֹךְ שֶׁיָּכוֹל לוֹמַר לֹא גֵּרַשְׁתִּי וְלֹא יִתְחַיֵּב בְּתוֹסֶפֶת נֶאֱמָן וּמַשְׁבִּיעָהּ בִּנְקִיטַת חֵפֶץ וְנוֹתֵן לָהּ אֶת הָעִקָּר וְנִשְׁבָּע הוּא שְׁבוּעַת הֶסֵּת עַל הַתּוֹסֶפֶת:","הוֹצִיאָה גֵּט וְאֵין בְּיָדָהּ שְׁטַר כְּתֻבָּה. אִם דֶּרֶךְ אוֹתוֹ מָקוֹם שֶׁלֹּא יִכְתְּבוּ כְּתֻבָּה גּוֹבָה עִקַּר כְּתֻבָּתָהּ בַּגֵּט שֶׁבְּיָדָהּ. וְאִם דַּרְכָּן לִכְתֹּב כְּתֻבָּה אֲפִלּוּ עִקָּר אֵין לָהּ עַד שֶׁתּוֹצִיא שְׁטַר כְּתֻבָּה כְּמוֹ שֶׁבֵּאַרְנוּ. וְנִשְׁבָּע הַבַּעַל שְׁבוּעַת הֶסֵּת עַל טַעֲנָתָהּ וְנִפְטָר:","הוֹצִיאָה שְׁתֵּי גִּטִּין וּשְׁתֵּי כְּתֻבּוֹת גּוֹבָה שְׁתֵּי כְּתֻבּוֹת. הוֹצִיאָה שְׁתֵּי כְּתֻבּוֹת וְגֵט אֶחָד אֵינָהּ גּוֹבָה אֶלָּא כְּתֻבָּה אַחַת. וְאֵי זוֹ מֵהֶן גּוֹבָה אִם שְׁתֵּיהֶן שָׁווֹת בִּטְּלָה הָאַחֲרוֹנָה אֶת הָרִאשׁוֹנָה וְאֵינָהּ טוֹרֶפֶת אֶלָּא מִזְּמַן הָאַחֲרוֹנָה. וְאִם הָיָה בְּאַחַת מִשְּׁתֵּיהֶן תּוֹסֶפֶת עַל חֲבֵרְתָהּ גּוֹבָה בְּאֵיזוֹ מֵהֶן שֶׁתִּרְצֶה וּתְבַטֵּל הַשְּׁנִיָּה:","הוֹצִיאָה שְׁתֵּי גִּטִּין וּכְתֻבָּה אַחַת אֵין לָהּ אֶלָּא כְּתֻבָּה אַחַת. שֶׁהַמְגָרֵשׁ אֶת אִשְׁתּוֹ וְהֶחֱזִירָהּ סְתָם עַל כְּתֻבָּתָהּ הָרִאשׁוֹנָה הֶחֱזִירָהּ. הוֹצִיאָה גֵּט וּכְתֻבָּה אַחַר מִיתַת הַבַּעַל. אִם גֵּט קוֹדֵם לִכְתֻבָּה גּוֹבָה בְּגֵט זֶה עִקַּר כְּתֻבָּה אִם אֵין דַּרְכָּן לִכְתֹּב כְּתֻבָּה וְגוֹבָה כָּל מַה שֶּׁיֵּשׁ בִּכְתֻבָּתָהּ זוֹ שֶׁהֲרֵי זָכְתָה בָּהּ בְּמִיתָתוֹ. וְאִם כְּתֻבָּה קָדְמָה אֶת הַגֵּט אֵין לָהּ אֶלָּא כְּתֻבָּה אַחַת. שֶׁעַל כְּתֻבָּתָהּ הָרִאשׁוֹנָה הֶחֱזִירָהּ:","הָאִשָּׁה נֶאֱמֶנֶת לוֹמַר מֵת בַּעְלִי כְּדֵי שֶׁתִּנָּשֵׂא כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת גֵּרוּשִׁין. וּמִתְּנָאֵי הַכְּתֻבָּה שֶׁאִם תִּנָּשֵׂא לְאַחֵר אַחַר מוֹתוֹ תִּטּל כָּל מַה שֶּׁכָּתַב לָהּ בִּכְתֻבָּתָהּ. לְפִיכָךְ אִם בָּאָה לְבֵית דִּין וְאָמְרָה מֵת בַּעְלִי הַתִּירוּנִי לְהִנָּשֵׂא וְלֹא הִזְכִּירָה שֵׁם כְּתֻבָּה בָּעוֹלָם מַתִּירִין אוֹתָהּ לְהִנָּשֵׂא וּמַשְׁבִּיעִין אוֹתָהּ וְנוֹתְנִין לָהּ כְּתֻבָּתָהּ. בָּאָה וְאָמְרָה מֵת בַּעְלִי תְּנוּ לִי אֶת כְּתֻבָּתִי אַף לְהִנָּשֵׂא אֵין מַתִּירִין אוֹתָהּ שֶׁעַל עִסְקֵי הַכְּתֻבָּה בָּאָה וַהֲרֵי זֶה בְּחֶזְקַת שֶׁלֹּא מֵת. וְאֵין דַּעְתָּהּ לְהִנָּשֵׂא אֶלָּא לִטּל כְּתֻבָּה מֵחַיִּים בִּלְבַד. בָּאָה וְאָמְרָה מֵת בַּעְלִי הַתִּירוּנִי לְהִנָּשֵׂא וּתְנוּ לִי אֶת כְּתֻבָּתִי מַתִּירִין אוֹתָהּ לְהִנָּשֵׂא וְנוֹתְנִין לָהּ כְּתֻבָּתָהּ מִפְּנֵי שֶׁעִקַּר דְּבָרֶיהָ עַל עִסְקֵי הַנִּשּׂוּאִין בָּאָה. אֲבָל אִם בָּאָה וְאָמְרָה תְּנוּ לִי אֶת כְּתֻבָּתִי וְהַתִּירוּנִי לְהִנָּשֵׂא מַתִּירִין אוֹתָהּ וְאֵין נוֹתְנִין לָהּ כְּתֻבָּה. וְאִם תָּפְשָׂה אֵין מוֹצִיאִין מִיָּדָהּ:"],"Mishneh Torah, Marriage 4":["אֵין הָאִשָּׁה מִתְקַדֶּשֶׁת אֶלָּא לִרְצוֹנָהּ וְהַמְקַדֵּשׁ אִשָּׁה בְּעַל כָּרְחָהּ אֵינָהּ מְקֻדֶּשֶׁת. אֲבָל הָאִישׁ שֶׁאֲנָסוּהוּ עַד שֶׁקִּדֵּשׁ בְּעַל כָּרְחוֹ הֲרֵי זוֹ מְקֻדֶּשֶׁת. וְיֵשׁ לָאִישׁ לְקַדֵּשׁ נָשִׁים רַבּוֹת כְּאַחַת וְהוּא שֶׁיִּהְיֶה בְּכֶסֶף אִם קִדֵּשׁ בְּכֶסֶף פְּרוּטָה לְכָל אַחַת וְאַחַת. וְיֵשׁ לְאַחַת מֵהֶן אוֹ לְאַחֵר לְקַבֵּל הַקִּדּוּשִׁין עַל יְדֵי כֻּלָּן מִדַּעְתָּן:","הַמְקַדֵּשׁ אֶת הָאִשָּׁה וְנָתַן הַקִּדּוּשִׁין מִדַּעְתָּהּ בְּיַד חֲבֶרְתָּהּ וְאָמַר לַחֲבֶרְתָּהּ כְּשֶׁנָּתַן הַקִּדּוּשִׁין בְּיָדָהּ וְאַתְּ נַמִּי. אוֹ וְכֵן גַּם אַתְּ וְכַיּוֹצֵא בָּזֶה. הֲרֵי שְׁתֵּיהֶן מְקֻדָּשׁוֹת. אֲבָל אִם נָתַן בְּיָדָהּ וְאָמַר לָהּ וְאַתְּ. הֲרֵי זוֹ שֶׁקִּבְּלָה הַקִּדּוּשִׁין מְקֻדֶּשֶׁת בְּסָפֵק. שֶׁמָּא לֹא נִתְכַּוִּן אֶלָּא לִרְאוֹת מַה בְּלִבָּהּ וּכְאִלּוּ אָמַר לָהּ וְאַתְּ מַה תֹּאמְרִי בְּדָבָר זֶה. וּלְפִיכָךְ קִבְּלָה הַקִּדּוּשִׁין הִיא שֶׁהֲרֵי זֶה עֲדַיִן שׁוֹאֲלָהּ לִרְאוֹת מַה בְּלִבָּהּ וּמִפְּנֵי זֶה הִיא סָפֵק מְקֻדֶּשֶׁת:","אָמַר לָהּ הִתְקַדְּשִׁי לִי בְּדִינָר זֶה נְטָלַתּוּ וּזְרָקַתּוּ לְפָנָיו אוֹ לַיָּם אוֹ לָאוּר אוֹ לְדָבָר הָאָבֵד אֵינָהּ מְקֻדֶּשֶׁת. אָמְרָה לוֹ תְּנֵהוּ לְאַבָּא אוֹ לְאָבִיךָ אוֹ לְאִישׁ פְּלוֹנִי וְנָתַן אֵינָהּ מְקֻדֶּשֶׁת. וְאִם אָמְרָה לוֹ תְּנֵהוּ לוֹ שֶׁיְּקַבְּלֵהוּ לִי וְנָתַן הֲרֵי זוֹ מְקֻדֶּשֶׁת:","אָמְרָה הַנִּיחֵהוּ עַל הַסֶּלַע אֵינָהּ מְקֻדֶּשֶׁת וְאִם הָיָה סֶלַע שֶׁלָּהּ מְקֻדֶּשֶׁת. הָיָה סֶלַע שֶׁל שְׁנֵיהֶם הֲרֵי זוֹ מְקֻדֶּשֶׁת בְּסָפֵק. אָמַר לָהּ הִתְקַדְּשִׁי לִי בְּכִכָּר זֶה אָמְרָה לוֹ תְּנֵהוּ לֶעָנִי אֲפִלּוּ הָיָה עָנִי הַסָּמוּךְ עָלֶיהָ אֵינָהּ מְקֻדֶּשֶׁת. תְּנֵהוּ לַכֶּלֶב הֲרֵי זוֹ אֵינָהּ מְקֻדֶּשֶׁת וְאִם הָיָה הַכֶּלֶב שֶׁלָּהּ מְקֻדֶּשֶׁת. וְאִם הָיָה רָץ אַחֲרֶיהָ לְנָשְׁכָהּ וְאָמְרָה לוֹ תְּנֵהוּ לְכֶלֶב זֶה הֲרֵי זוֹ סָפֵק מְקֻדֶּשֶׁת:","הָיָה מוֹכֵר פֵּרוֹת אוֹ כֵּלִים וְכַיּוֹצֵא בָּהֶן בָּאָה אִשָּׁה וְאָמְרָה לוֹ תֵּן לִי מְעַט מֵאֵלּוּ וְאָמַר לָהּ אִם אֶתֵּן לָךְ תְּהִי מְקֻדֶּשֶׁת לִי. אִם אָמְרָה הֵן וְנָתַן לָהּ הֲרֵי זוֹ מְקֻדֶּשֶׁת אֲבָל אִם אָמְרָה לוֹ תֵּן לִי מֵהֶן אוֹ הַשְׁלֵךְ לִי אוֹ דְּבָרִים שֶׁעִנְיָנָם לֹא תִּשְׂחַק עִמִּי בִּדְבָרִים אֵלּוּ אֶלָּא תֵּן לִי בִּלְבַד וְנָתַן אֵינָהּ מְקֻדֶּשֶׁת. וְכֵן אִם הָיָה שׁוֹתֶה יַיִן וְאָמְרָה לוֹ תֵּן לִי כּוֹס אֶחָד וְאָמַר לָהּ אִם אֶתֵּן לָךְ הֲרֵי אַתְּ מְקֻדֶּשֶׁת לִי בּוֹ וְאָמְרָה הַשְׁקֵנִי הַשְׁקוֹת אוֹ תֵּן הַשְׁקֵה הַשְׁלֵךְ אֵינָהּ מְ [קֵ] דֶּשֶׁת שֶׁאֵין הַדְּבָרִים נִרְאִין אֶלָּא הַשְׁקֵנִי בִּלְבַד וְלֹא תִּשְׂחַק עִמִּי בְּדָבָר אַחֵר:","הַמְקַדֵּשׁ בְּעֵד אֶחָד אֵין חוֹשְׁשִׁין לְקִדּוּשָׁיו וְאַף עַל פִּי שֶׁשְּׁנֵיהֶם מוֹדִין. קַל וָחֹמֶר לִמְקַדֵּשׁ בְּלֹא עֵדִים. הַמְקַדֵּשׁ בִּפְסוּלֵי עֵדוּת שֶׁל תּוֹרָה אֵינָהּ מְקֻדֶּשֶׁת. בִּפְסוּלֵי עֵדוּת שֶׁל דִּבְרֵי סוֹפְרִים אוֹ בְּעֵדִים שֶׁהֵן סָפֵק פְּסוּלֵי תּוֹרָה אִם רָצָה לִכְנֹס חוֹזֵר וּמְקַדֵּשׁ בִּכְשֵׁרִים וְאִם לֹא רָצָה לִכְנֹס צְרִיכָה גֵּט מִמֶּנּוּ מִסָּפֵק. וַאֲפִלּוּ כָּפְרָה הָאִשָּׁה וְהִכְחִישָׁה אֶת הָעֵדִים וְאָמְרָה לֹא קִדַּשְׁתַּנִי כּוֹפִין אוֹתָהּ לִקַּח גֵּט. וְכֵן דִּין כָּל קִדּוּשֵׁי סָפֵק אִם רָצָה לִכְנֹס חוֹזֵר וּמְקַדֵּשׁ וַדַּאי וְאִם לֹא רָצָה לִכְנֹס צְרִיכָה גֵּט מִמֶּנּוּ מִסָּפֵק:","קָטָן שֶׁקִּדֵּשׁ אֵין קִדּוּשָׁיו קִדּוּשִׁין. אֲבָל גָּדוֹל שֶׁקִּדֵּשׁ אֶת הַקְּטַנָּה הַיְתוֹמָה. אוֹ קְטַנָּה שֶׁיָּצְאָה מֵרְשׁוּת אָבִיהָ. אִם הָיְתָה פְּחוּתָה מִבַּת שֵׁשׁ אַף עַל פִּי שֶׁהִיא נְבוֹנַת לַחַשׁ בְּיוֹתֵר וּמַכֶּרֶת וּמַבְחֶנֶת אֵין כָּאן שֵׁם קִדּוּשִׁין וְאֵינָהּ צְרִיכָה לְמָאֵן. וְאִם הָיְתָה מִבַּת עֶשֶׂר שָׁנִים וּלְמַעְלָה אַף עַל פִּי שֶׁהִיא סְכָלָה בְּיוֹתֵר הוֹאִיל וְנִתְקַדְּשָׁה לְדַעְתָּהּ הֲרֵי זוֹ מְקֻדֶּשֶׁת לְמֵאוּן. הָיְתָה מִבַּת שֵׁשׁ וְעַד סוֹף עֶשֶׂר בּוֹדְקִין אֶת יְפִי דַּעְתָּהּ אִם מַכֶּרֶת וּמַבְחֶנֶת עִסְקֵי הַנִּשּׂוּאִין וְהַקִּדּוּשִׁין צְרִיכָה לְמָאֵן. וְאִם לָאו אֵינָהּ מְקֻדֶּשֶׁת לְמֵאוּן וְאֵינָהּ צְרִיכָה לְמָאֵן:","כֵּיצַד מְקֻדֶּשֶׁת לְמֵאוּן. שֶׁאִם נִתְקַדְּשָׁה וְלֹא רָצְתָה לֵישֵׁב עִם בַּעְלָהּ צְרִיכָה לְמָאֵן בִּפְנֵי שְׁנַיִם וְלוֹמַר אֵינִי רוֹצָה בּוֹ וְיוֹצְאָה בְּלֹא גֵּט כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת גֵּרוּשִׁין. וְזוֹ הִיא הַנִּקְרֵאת מְמָאֶנֶת. וְלָמָּה יוֹצְאָה בְּלֹא גֵּט מִפְּנֵי שֶׁאֵין קִדּוּשֶׁיהָ קִדּוּשִׁין גְּמוּרִין מִן הַתּוֹרָה אֶלָּא מִדִּבְרֵי סוֹפְרִים וְהֵן תְּלוּיִין שֶׁאִם יָשְׁבָה עִם בַּעְלָהּ עַד שֶׁגָּדְלָה גָּמְרוּ קִדּוּשֶׁיהָ וְנַעֲשֵׂית אֵשֶׁת אִישׁ גְּמוּרָה וְאֵינוֹ צָרִיךְ לַחֲזֹר וּלְקַדְּשָׁהּ אַחַר שֶׁגָּדְלָה. וְאִם לֹא רָצְתָה לֵישֵׁב צְרִיכָה לְמָאֵן וְתֵצֵא בְּלֹא גֵּט:","חֵרֵשׁ שֶׁנָּשָׂא פִּקַּחַת וְכֵן חֵרֶשֶׁת שֶׁנִּשֵּׂאת לְפִקֵּחַ אֵין קִדּוּשֵׁיהֶן גְּמוּרִין מִן הַתּוֹרָה אֶלָּא מִדִּבְרֵי סוֹפְרִים לְפִיכָךְ אִם בָּא פִּקֵּחַ וְקִדֵּשׁ אֵשֶׁת חֵרֵשׁ הַפִּקַּחַת הֲרֵי זוֹ מְקֻדֶּשֶׁת לַשֵּׁנִי קִדּוּשִׁין גְּמוּרִין וְנוֹתֵן גֵּט וְהִיא מֻתֶּרֶת לְבַעְלָהּ הַחֵרֵשׁ. אֲבָל הַשּׁוֹטֶה שֶׁקִּדֵּשׁ פִּקַּחַת אוֹ פִּקֵּחַ שֶׁקִּדֵּשׁ שׁוֹטָה אֵין כָּאן קִדּוּשִׁין כְּלָל לֹא מִדִּבְרֵי תּוֹרָה וְלֹא מִדִּבְרֵי סוֹפְרִים:","סָרִיס שֶׁקִּדֵּשׁ בֵּין סְרִיס חַמָּה בֵּין סְרִיס אָדָם וְכֵן אַיְלוֹנִית שֶׁנִּתְקַדְּשָׁה הֲרֵי אֵלּוּ קִדּוּשִׁין גְּמוּרִין:","טֻמְטוּם וְאַנְדְּרוֹגִינוּס שֶׁקִּדְּשׁוּ אִשָּׁה אוֹ שֶׁקִּדְּשָׁן אִישׁ הֲרֵי אֵלּוּ קִדּוּשֵׁי סָפֵק וּצְרִיכִין גֵּט מִסָּפֵק:","הַמְקַדֵּשׁ אַחַת מִן הָעֲרָיוֹת לֹא עָשָׂה כְּלוּם שֶׁאֵין קִדּוּשִׁין תּוֹפְסִין לָעֶרְוָה חוּץ מִן הַנִּדָּה שֶׁהַמְקַדֵּשׁ אֶת הַנִּדָּה הֲרֵי זוֹ מְקֻדֶּשֶׁת קִדּוּשִׁין גְּמוּרִין וְאֵין רָאוּי לַעֲשׂוֹת כֵּן:","אֵשֶׁת אִישׁ שֶׁפָּשְׁטָה יָדָהּ וְקִבְּלָה קִדּוּשִׁין מֵאַחֵר בִּפְנֵי בַּעְלָהּ הֲרֵי זוֹ מְקֻדֶּשֶׁת לַשֵּׁנִי. שֶׁהָאִשָּׁה שֶׁאָמְרָה לְבַעְלָהּ בְּפָנָיו גֵרַשְׁתַּנִי נֶאֱמֶנֶת חֲזָקָה אֵין אִשָּׁה מְעִזָּה פָּנֶיהָ בִּפְנֵי בַּעְלָהּ. אֲבָל אִם קִדְּשָׁהּ אַחֵר שֶׁלֹּא בִּפְנֵי בַּעְלָהּ אֵין קִדּוּשִׁין תּוֹפְסִין בָּהּ עַד שֶׁתָּבִיא רְאָיָה שֶׁנִּתְגָּרְשָׁה קֹדֶם שֶׁתְּקַבֵּל הַקִּדּוּשִׁין, כָּל שֶׁלֹּא בְּפָנָיו מְעִזָּה:","הַמְקַדֵּשׁ אַחַת מִן הַשְּׁנִיּוֹת אוֹ מֵאִסּוּרֵי לָאוִין אוֹ מֵאִסּוּרֵי עֲשֵׂה. וְכֵן יָבָם שֶׁקִּדֵּשׁ צָרַת יְבָמָה. הֲרֵי זוֹ מְקֻדֶּשֶׁת קִדּוּשִׁין גְּמוּרִין חוּץ מִיבָמָה שֶׁנִּתְקַדְּשָׁה לְזָר שֶׁהִיא מְקֻדֶּשֶׁת בְּסָפֵק. נִסְתַּפֵּק לַחֲכָמִים אִם הַקִּדּוּשִׁין תּוֹפְסִין בִּיבָמָה כִּשְׁאָר חִיּוּבֵי לָאוִין אוֹ אֵין קִדּוּשִׁין תּוֹפְסִין בָּהּ כְּעֶרְוָה. וְאַף עַל פִּי שֶׁאָסוּר לוֹ לִכְנֹס אַחַת מִכָּל אֵלּוּ הֲרֵי זֶה מְגָרֵשׁ בְּגֵט:","הַמְקַדֵּשׁ כּוּתִית אוֹ שִׁפְחָה אֵינָן קִדּוּשִׁין אֶלָּא הֲרֵי הִיא אַחַר הַקִּדּוּשִׁין כְּמוֹ שֶׁהָיְתָה קֹדֶם הַקִּדּוּשִׁין. וְכֵן עַכּוּ\"ם וְעֶבֶד שֶׁקִּדְּשׁוּ בַּת יִשְׂרָאֵל אֵין קִדּוּשֵׁיהֶן קִדּוּשִׁין. יִשְׂרָאֵל מוּמָר שֶׁקִּדֵּשׁ אַף עַל פִּי שֶׁהוּא עוֹבֵד עַכּוּ\"ם בִּרְצוֹנוֹ הֲרֵי אֵלּוּ קִדּוּשִׁין גְּמוּרִין וּצְרִיכָה גֵּט מִמֶּנּוּ:","הַמְקַדֵּשׁ אִשָּׁה שֶׁחֶצְיָהּ שִׁפְחָה וְחֶצְיָהּ בַּת חוֹרִין אֵינָהּ מְקֻדֶּשֶׁת קִדּוּשִׁין גְּמוּרִין עַד שֶׁתִּשְׁתַּחְרֵר וְכֵיוָן שֶׁנִּשְׁתַּחְרְרָה גָּמְרוּ קִדּוּשֶׁיהָ כְּקִדּוּשֵׁי קְטַנָּה שֶׁגָּדְלָה וְאֵינוֹ צָרִיךְ לְקַדְּשָׁהּ קִדּוּשִׁין אֲחֵרִים. בָּא אַחֵר וְקִדְּשָׁהּ אַחַר שֶׁנִּשְׁתַּחְרְרָה הֲרֵי זֶה סָפֵק קִדּוּשִׁין לִשְׁנֵיהֶם:","וְאֵי זוֹ הִיא שִׁפְחָה חֲרוּפָה הָאֲמוּרָה בַּתּוֹרָה זוֹ מִי שֶׁחֶצְיָהּ שִׁפְחָה וְחֶצְיָהּ בַּת חוֹרִין שֶׁקִּדְּשָׁהּ עֶבֶד עִבְרִי. וּמִי שֶׁחֶצְיוֹ עֶבֶד וְחֶצְיוֹ בֶּן חוֹרִין שֶׁקִּדֵּשׁ בַּת חוֹרִין הֲרֵי זוֹ סָפֵק קִדּוּשִׁין:","שִׁכּוֹר שֶׁקִּדֵּשׁ קִדּוּשָׁיו קִדּוּשִׁין וְאַף עַל פִּי שֶׁנִּשְׁתַּכֵּר הַרְבֵּה. וְאִם הִגִּיעַ לְשִׁכְרוּתוֹ שֶׁל לוֹט אֵין קִדּוּשָׁיו קִדּוּשִׁין. וּמִתְיַשְּׁבִין בְּדָבָר זֶה:","הַמְקַדֵּשׁ בְּפָחוֹת מִפְּרוּטָה אֵינָהּ מְקֻדֶּשֶׁת. קִדְּשָׁהּ בְּאֹכֶל אוֹ בִּכְלִי וְכַיּוֹצֵא בּוֹ שֶׁשָּׁוֶה פָּחוֹת מִפְּרוּטָה הֲרֵי זוֹ מְקֻדֶּשֶׁת בְּסָפֵק וּצְרִיכָה גֵּט מִסָּפֵק שֶׁמָּא דָּבָר זֶה שָׁוֶה פְּרוּטָה בְּמָקוֹם אַחֵר. הָא לָמַדְתָּ שֶׁכָּל הַמְקַדֵּשׁ בִּשְׁוֵה כֶּסֶף אִם הָיָה בְּאוֹתָהּ הַמְּדִינָה שְׁוֵה פְּרוּטָה הֲרֵי אֵלּוּ קִדּוּשֵׁי וַדַּאי וְאִם אֵינוֹ שְׁוֵה פְּרוּטָה הֲרֵי אֵלּוּ קִדּוּשֵׁי סָפֵק. יֵרָאֶה לִי שֶׁאִם קִדֵּשׁ בְּתַבְשִׁיל אוֹ בְּיָרָק שֶׁאֵינוֹ מִתְקַיֵּם וְכַיּוֹצֵא בָּהֶם אִם לֹא הָיוּ שְׁוֵה פְּרוּטָה בְּאוֹתוֹ הַמָּקוֹם אֵינָהּ מְקֻדֶּשֶׁת כְּלָל שֶׁהֲרֵי דָּבָר זֶה אֵינוֹ מַגִּיעַ לְמָקוֹם אַחֵר עַד שֶׁיִּפָּסֵד וְיֹאבַד וְלֹא יִהְיוּ שְׁוֵה פְּרוּטָה. וְדָבָר שֶׁל טַעַם הוּא זֶה וְרָאוּי לִסְמֹךְ עָלָיו:","הַמְקַדֵּשׁ (אִשָּׁה) בְּפָחוֹת מִפְּרוּטָה אוֹ שֶׁקִּדֵּשׁ שְׁתֵּי נָשִׁים בִּפְרוּטָה אַף עַל פִּי שֶׁשָּׁלַח סִבְלוֹנוֹת לְאַחַר מִכֵּן אֵינָהּ מְקֻדֶּשֶׁת. וְכֵן קָטָן שֶׁקִּדֵּשׁ אַף עַל פִּי שֶׁשָּׁלַח סִבְלוֹנוֹת לְאַחַר שֶׁהִגְדִּיל אֵינָהּ מְקֻדֶּשֶׁת שֶׁמֵּחֲמַת קִדּוּשִׁין הָרִאשׁוֹנִים שְׁלָחָן שֶׁהָיוּ קִדּוּשִׁין פְּסוּלִין:","הַמְקַדֵּשׁ אֶת הָאִשָּׁה בְּכֶסֶף אוֹ בִּשְׁטָר אֵינוֹ צָרִיךְ שֶׁיִּתֵּן הַקִּדּוּשִׁין לְתוֹךְ יָדָהּ אֶלָּא כֵּיוָן שֶׁרָצְתָה לִזְרֹק לָהּ קִדּוּשֶׁיהָ וּזְרָקָן בֵּין לְתוֹךְ יָדָהּ בֵּין לְתוֹךְ חֵיקָהּ אוֹ לְתוֹךְ חֲצֵרָהּ אוֹ לְתוֹךְ שָׂדֶה שֶׁלָּהּ הֲרֵי זוֹ מְקֻדֶּשֶׁת. הָיְתָה עוֹמֶדֶת בִּרְשׁוּת הַבַּעַל צָרִיךְ שֶׁיִּתֵּן לְתוֹךְ יָדָהּ אוֹ לְתוֹךְ חֵיקָהּ. הָיְתָה עוֹמֶדֶת בִּרְשׁוּת שֶׁהִיא שֶׁל שְׁנֵיהֶן וְזָרַק לָהּ קִדּוּשֶׁיהָ מִדַּעְתָּהּ וְלֹא הִגִּיעוּ לְיָדָהּ אוֹ לְחֵיקָהּ הֲרֵי זוֹ מְקֻדֶּשֶׁת קִדּוּשֵׁי סָפֵק. וַאֲפִלּוּ אָמְרָה לוֹ הַנַּח קִדּוּשִׁין עַל מָקוֹם זֶה וְאוֹתוֹ הַמָּקוֹם שֶׁל שְׁנֵיהֶם הֲרֵי אֵלּוּ קִדּוּשֵׁי סָפֵק:","הָיוּ עוֹמְדִים בִּרְשׁוּת הָרַבִּים אוֹ בִּרְשׁוּת שֶׁאֵינוֹ שֶׁל שְׁנֵיהֶם וְזָרַק לָהּ קִדּוּשֶׁיהָ. קָרוֹב לוֹ אֵינָהּ מְקֻדֶּשֶׁת. קָרוֹב לָהּ הֲרֵי זוֹ מְקֻדֶּשֶׁת. מֶחֱצָה עַל מֶחֱצָה אוֹ שֶׁהָיוּ סָפֵק קָרוֹב לוֹ סָפֵק קָרוֹב לָהּ וְאָבְדוּ קֹדֶם שֶׁיַּגִּיעוּ לְיָדָהּ הֲרֵי זוֹ סָפֵק מְקֻדֶּשֶׁת. כֵּיצַד הוּא קָרוֹב לוֹ וְקָרוֹב לָהּ. כָּל שֶׁהוּא יָכוֹל לִשְׁמֹר אוֹתָן וְהִיא אֵינָהּ יְכוֹלָה זֶה הוּא קָרוֹב לוֹ. הִיא יְכוֹלָה לִשְׁמֹר אוֹתָן וְהוּא אֵינוֹ יָכוֹל זֶהוּ קָרוֹב לָהּ. שְׁנֵיהֶן יְכוֹלִין לִשְׁמֹר אוֹתָן אוֹ שְׁנֵיהֶן אֵין יְכוֹלִים לִשְׁמֹר אוֹתָן זֶה הוּא מֶחֱצָה עַל מֶחֱצָה:"],"Mishneh Torah, Mourning 2":["אֵלוּ שֶׁאָדָם חַיָּב לְהִתְאַבֵּל עֲלֵיהֶן דִּין תּוֹרָה. אִמּוֹ וְאָבִיו בְּנוֹ וּבִתּוֹ וְאָחִיו וַאֲחוֹתוֹ מֵאָבִיו. וּמִדִּבְרֵיהֶם שֶׁיִּתְאַבֵּל הָאִישׁ עַל אִשְׁתּוֹ הַנְּשׂוּאָה. וְכֵן הָאִשָּׁה עַל בַּעְלָהּ. וּמִתְאַבֵּל עַל אָחִיו וְעַל אֲחוֹתוֹ שֶׁהֵן מֵאִמּוֹ:","אֲפִלּוּ הַכֹּהֵן שֶׁאֵינוֹ מִתְטַמֵּא לְאָחִיו וַאֲחוֹתוֹ מֵאִמּוֹ וְלַאֲחוֹתוֹ הַנְּשׂוּאָה אַף עַל פִּי שֶׁהִיא מֵאָבִיו. מִתְאַבֵּל הוּא עֲלֵיהֶן. וְאִם הָיְתָה אֲחוֹתוֹ זוֹ הַנְּשׂוּאָה מֵאָבִיו הֲרֵי הוּא מִתְאַבֵּל עָלֶיהָ דִּין תּוֹרָה:","בְּנוֹ אוֹ אָחִיו הַבָּא מִן הַשִּׁפְחָה וּמִן הַנָּכְרִית אֵינוֹ מִתְאַבֵּל עֲלֵיהֶן כְּלָל. וְכֵן מִי שֶׁנִּתְגַּיֵּר הוּא וּבָנָיו אוֹ נִשְׁתַּחְרֵר הוּא וְאִמּוֹ אֵין מִתְאַבְּלִין זֶה עַל זֶה. וְכֵן אִשְׁתּוֹ אֲרוּסָה אֵינוֹ מִתְאַבֵּל עָלֶיהָ וְלֹא אוֹנֵן וְכֵן הִיא לֹא אוֹנֶנֶת וְלֹא מִתְאַבֶּלֶת עָלָיו:","כָּל קְרוֹבִים שֶׁהוּא חַיָּב לְהִתְאַבֵּל עֲלֵיהֶן הֲרֵי זֶה מִתְאַבֵּל עִמָּהֶם בִּפְנֵיהֶם מִדִּבְרֵי סוֹפְרִים. כֵּיצַד. הֲרֵי שֶׁמֵּת בֶּן בְּנוֹ אוֹ אֲחִי בְּנוֹ אוֹ אֵם בְּנוֹ חַיָּב לִקְרֹעַ בִּפְנֵי בְּנוֹ וְלִנְהֹג אֲבֵלוּת בְּפָנָיו אֲבָל שֶׁלֹּא בְּפָנָיו אֵינוֹ חַיָּב. וְכֵן בִּשְׁאָר הַקְּרוֹבִים:","אִשְׁתּוֹ הַנְּשׂוּאָה אַף עַל פִּי שֶׁהוּא מִתְאַבֵּל עָלֶיהָ אֵינוֹ מִתְאַבֵּל עִמָּהּ עַל שְׁאָר קְרוֹבִים אֶלָּא עַל אָבִיהָ וְעַל אִמָּהּ מִשּׁוּם כְּבוֹד אִשְׁתּוֹ נוֹהֵג אֲבֵלוּת עֲלֵיהֶן בְּפָנֶיהָ. כֵּיצַד. מִי שֶׁמֵּת חָמִיו אוֹ חֲמוֹתוֹ כּוֹפֶה מִטָּתוֹ וְנוֹהֵג אֲבֵלוּת עִם אִשְׁתּוֹ בְּפָנֶיהָ אֲבָל לֹא שֶׁלֹּא בְּפָנֶיהָ. וְכֵן הָאִשָּׁה שֶׁמֵּת חָמִיהָ אוֹ חֲמוֹתָהּ נוֹהֶגֶת אֲבֵלוּת בְּפָנָיו. אֲבָל שְׁאָר קְרוֹבִים כְּגוֹן שֶׁמֵּת אֲחִי אִשְׁתּוֹ אוֹ בְּנָהּ וְהָאִשָּׁה שֶׁמֵּת אֲחִי בַּעְלָהּ אוֹ בְּנוֹ אֵין מִתְאַבְּלִין זֶה עַל זֶה. וְכֵן יֵרָאֶה לִי שֶׁאִם מֵתָה אֵשֶׁת קְרוֹבוֹ אוֹ בַּעַל קְרוֹבָתוֹ כְּגוֹן שֶׁמֵּתָה אֵשֶׁת בְּנוֹ אוֹ בַּעַל בִּתּוֹ אֵינוֹ חַיָּב לְהִתְאַבֵּל עֲלֵיהֶן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כַּמָּה חֲמוּרָה מִצְוַת אֲבֵלוּת. שֶׁהֲרֵי נִדְחֵית לוֹ הַטֻּמְאָה מִפְּנֵי קְרוֹבָיו כְּדֵי שֶׁיִּתְעַסֵּק עִמָּהֶן וְיִתְאַבֵּל עֲלֵיהֶן. שֶׁנֶּאֱמַר (ויקרא כא ב) \"כִּי אִם לִשְׁאֵרוֹ הַקָּרֹב אֵלָיו לְאִמּוֹ\" וְגוֹ' (ויקרא כא ג) \"לָהּ יִטַּמָּא\" מִצְוַת עֲשֵׂה שֶׁאִם לֹא רָצָה לְהִטָּמֵא מְטַמְּאִין אוֹתוֹ עַל כָּרְחוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְכָרִים שֶׁהֻזְהֲרוּ עַל הַטֻּמְאָה אֲבָל הַכֹּהֲנוֹת הוֹאִיל וְאֵינָן מֻזְהָרוֹת עַל הַטֻּמְאָה כֵּן אֵינָן מְצֻוּוֹת לְהִתְטַמֵּא לַקְּרוֹבִים. אֶלָּא אִם רָצוּ מִתְטַמְּאוֹת וְאִם לָאו לֹא מִטַּמְּאוֹת:","אִשְׁתּוֹ שֶׁל כֹּהֵן מִתְטַמֵּא לָהּ עַל כָּרְחוֹ. וְאֵינוֹ מִטַּמֵּא לָהּ אֶלָּא מִדִּבְרֵי סוֹפְרִים. עֲשָׂאוּהָ כְּמֵת מִצְוָה. כֵּיוָן שֶׁאֵין לָהּ יוֹרֵשׁ אֶלָּא הוּא לֹא תִּמְצָא מִי שֶׁיִּתְעַסֵּק בָּהּ. וְאֵינוֹ מִטַּמֵּא אֶלָּא לִנְשׂוּאָהּ בִּלְבַד אֲבָל הָאֲרוּסָה אֵינוֹ מִטַּמֵּא לָהּ:","וְכֵן כָּל אוֹתָן שֶׁאָמְרוּ שֶׁאֵין מִתְאַבְּלִין עֲלֵיהֶן כְּגוֹן הֲרוּגֵי בֵּית דִּין וְשֶׁפָּרְשׁוּ מִדַּרְכֵי צִבּוּר וְהַנְּפָלִים וְהַמְאַבֵּד עַצְמוֹ לָדַעַת אֵין הַכֹּהֵן מִטַּמֵּא לָהֶן. וְעַד מָתַי מְצֻוֶּה לְהִתְטַמֵּא לִקְרוֹבָיו עַד שֶׁיִּסָּתֵם הַגּוֹלֵל. אֲבָל מֵאַחַר שֶׁנִּסְתַּם הַגּוֹלֵל הֲרֵי הֵן כִּשְׁאָר כָּל הַמֵּתִים שֶׁאִם נִטְמָא בָּהֶן לוֹקֶה:","אִשְׁתּוֹ הַפְּסוּלָה אֵינוֹ מִטַּמֵּא לָהּ. לְפִיכָךְ מִי שֶׁשָּׁמְעָה שְׁמוּעָה שֶׁמֵּת בַּעְלָהּ וְנִשֵּׂאת וּבָא בַּעְלָהּ. שְׁנֵיהֶן אֵין מִטַּמְּאִין לָהּ שֶׁהֲרֵי הִיא פְּסוּלָה לִשְׁנֵיהֶן. אֲבָל מִטַּמֵּא הוּא לְאִמּוֹ אַף עַל פִּי שֶׁהִיא חֲלָלָה. וְכֵן מִטַּמֵּא לִבְנוֹ וּלְבִתּוֹ וּלְאָחִיו וְלַאֲחוֹתוֹ אַף עַל פִּי שֶׁהֵן פְּסוּלִין. אֲפִלּוּ הָיוּ מַמְזֵרִים מִטַּמֵּא לָהֶן:","אֲחוֹתוֹ הַנְּשׂוּאָה אֵינוֹ מִטַּמֵּא לָהּ אַף עַל פִּי שֶׁהִיא נְשׂוּאָה לְכֹהֵן. שֶׁנֶּאֱמַר (ויקרא כא ג) \"הַבְּתוּלָה הַקְּרוֹבָה אֵלָיו אֲשֶׁר לֹא הָיְתָה לְאִישׁ\". הַבְּתוּלָה פְּרָט לַאֲנוּסָה וּמְפֻתָּה. יָכוֹל שֶׁאֲנִי מוֹצִיא אֶת הַבּוֹגֶרֶת וּמֻכַּת עֵץ תַּלְמוּד לוֹמַר אֲשֶׁר לֹא הָיְתָה לְאִישׁ מִי שֶׁהֲוָיָתָהּ בִּידֵי אִישׁ. אֲשֶׁר לֹא הָיְתָה לְאִישׁ פְּרָט לַאֲרוּסָה שֶׁאֵינוֹ מִטַּמֵּא לָהּ אַף עַל פִּי שֶׁהִיא אֲרוּסָה לְכֹהֵן:","נִתְגָּרְשָׁה אֲחוֹתוֹ מִן הָאֵרוּסִין מִטַּמֵּא לָהּ. שֶׁנֶּאֱמַר (ויקרא כא ג) \"הַקְּרוֹבָה אֵלָיו\" לְהָבִיא אֶת הַמְגֹרֶשֶׁת מִן הָאֵרוּסִין:","אָחִיו וַאֲחוֹתוֹ מֵאִמּוֹ אֵינוֹ מִטַּמֵּא לָהֶן. שֶׁנֶּאֱמַר (ויקרא כא ב) \"וְלִבְנוֹ וּלְבִתּוֹ וּלְאָחִיו\" (ויקרא כא ג) \"וְלַאֲחֹתוֹ\". מַה בְּנוֹ הָרָאוּי לִירֻשָּׁתוֹ אַף אָחִיו וַאֲחוֹתוֹ הָרְאוּיִים לִירֻשָּׁתוֹ:","הַסְּפֵקוֹת אֵינוֹ מִטַּמֵּא לָהֶן שֶׁנֶּאֱמַר (ויקרא כא ג) \"לָהּ יִטַּמָּא\" מִטַּמֵּא הוּא עַל הַוַּדַּאי וְאֵינוֹ מִטַּמֵּא עַל הַסָּפֵק. לְפִיכָךְ הַוְּלָדוֹת שֶׁנִּתְעָרְבוּ וְהַבֵּן שֶׁהוּא סָפֵק בֶּן שִׁבְעָה לָאַחֲרוֹן אוֹ בֶּן תִּשְׁעָה לָרִאשׁוֹן וְכֵן כָּל כַּיּוֹצֵא בָּהֶן אֵינוֹ מִטַּמֵּא לָהֶן מִסָּפֵק. וְכֵן כָּל הַמִּתְגָּרֶשֶׁת סְפֵק גֵּרוּשִׁין אוֹ בְּגֵט פָּסוּל אֵינוֹ מִטַּמֵּא לָהּ:","אֵין הַכֹּהֵן מִטַּמֵּא לְאֵבֶר מִן הַחַי מֵאָבִיו וְלֹא לְעֶצֶם מֵעַצְמוֹת אָבִיו. וְכֵן הַמְלַקֵּט עַצְמוֹת אָבִיו אֵינוֹ מִטַּמֵּא לָהֶן אַף עַל פִּי שֶׁהַשִּׁדְרָה קַיֶּמֶת:","נִקְטַע רֹאשׁוֹ שֶׁל אָבִיו אֵינוֹ מִטַּמֵּא לוֹ שֶׁנֶּאֱמַר (ויקרא כא ב) \"לְאָבִיו\" בִּזְמַן שֶׁהוּא שָׁלֵם וְלֹא בִּזְמַן שֶׁהוּא חָסֵר. וְכֵן שְׁאָר הַקְּרוֹבִים. הַטֻּמְאָה לַקְּרוֹבִים דְּחוּיָה הִיא וְלֹא הֻתְּרָה לַכּל. לְפִיכָךְ אָסוּר לְכֹהֵן לְהִתְטַמֵּא לְמֵת אֲפִלּוּ בְּעֵת שֶׁמִּתְטַמֵּא לִקְרוֹבָיו שֶׁנֶּאֱמַר (ויקרא כא ג) \"לָהּ יִטַּמָּא\" אֵינוֹ מִטַּמֵּא לַאֲחֵרִים עִמָּהּ. שֶׁלֹּא יֹאמַר הוֹאִיל וְנִטְמֵאתִי עַל אָבִי אֲלַקֵּט עַצְמוֹת פְּלוֹנִי אוֹ אֶגַּע בְּקֶבֶר פְּלוֹנִי. לְפִיכָךְ כֹּהֵן שֶׁמֵּת לוֹ מֵת צָרִיךְ לְהִזָּהֵר וּלְקָבְרוֹ בְּסוֹף בֵּית הַקְּבָרוֹת כְּדֵי שֶׁלֹּא יִכָּנֵס לְבֵית הַקְּבָרוֹת וְלֹא יִתְטַמֵּא בְּקִבְרוֹת אֲחֵרִים כְּשֶׁיִּקְבֹּר מֵתוֹ:"],"Mishneh Torah, Murderer and the Preservation of Life 13":["מִי שֶׁפָּגַע בַּחֲבֵרוֹ בַּדֶּרֶךְ וּבְהֶמְתּוֹ רוֹבֶצֶת תַּחַת מַשָּׂאָה בֵּין שֶׁהָיָה עָלֶיהָ מַשָּׂא הָרָאוּי לָהּ בֵּין שֶׁהָיָה עָלֶיהָ יוֹתֵר מִמַּשָּׂאָהּ הֲרֵי זֶה מִצְוָה לִפְרֹק מֵעָלֶיהָ וְזוֹ מִצְוַת עֲשֵׂה שֶׁנֶּאֱמַר (שמות כג ה) \"עָזֹב תַּעֲזֹב עִמּוֹ\":","וְלֹא יִפְרֹק וְיַנִּיחֶנּוּ נִבְהָל וְיֵלֵךְ אֶלָּא יָקִים עִמּוֹ וְיַחְזֹר וְיִטְעֹן מַשָּׂאוֹ עָלֶיהָ שֶׁנֶּאֱמַר (דברים כב ד) \"הָקֵם תָּקִים עִמּוֹ\" זוֹ מִצְוַת עֲשֵׂה אַחֶרֶת. וְאִם הִנִּיחוֹ נִבְהָל וְלֹא פָּרַק וְלֹא טָעַן בִּטֵּל מִצְוַת עֲשֵׂה וְעָבַר עַל מִצְוַת לֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים כב ד) \"לֹא תִרְאֶה אֶת חֲמוֹר אָחִיךָ\":","הָיָה כֹּהֵן וְהַבְּהֵמָה רוֹבֶצֶת בְּבֵית הַקְּבָרוֹת אֵינוֹ מִתְטַמֵּא לָהּ כְּשֵׁם שֶׁאֵינוֹ מִתְטַמֵּא לְהֶשֵּׁב אֲבֵדָה. וְכֵן אִם הָיָה זָקֵן שֶׁאֵין דַּרְכּוֹ לִטְעֹן וְלִפְרֹק הוֹאִיל וְאֵינָהּ לְפִי כְּבוֹדוֹ פָּטוּר:","זֶה הַכְּלָל כָּל שֶׁאִלּוּ הָיְתָה שֶׁלּוֹ הָיָה טוֹעֵן וּפוֹרֵק הֲרֵי זֶה חַיָּב לִטְעֹן וְלִפְרֹק בְּשֶׁל חֲבֵרוֹ. וְאִם הָיָה חָסִיד וְעוֹשֶׂה לִפְנִים מִשּׁוּרַת הַדִּין אֲפִלּוּ הָיָה הַנָּשִׂיא הַגָּדוֹל וְרָאָה בֶּהֱמַת חֲבֵרוֹ רוֹבֶצֶת תַּחַת מַשָּׂאָה שֶׁל תֶּבֶן אוֹ קָנִים וְכַיּוֹצֵא בָּהֶן פּוֹרֵק וְטוֹעֵן עִמּוֹ:","פָּרַק וְטָעַן וְחָזְרָה וְנָפְלָה חַיָּב לִטְעֹן וְלִפְרֹק פַּעַם אַחֶרֶת אֲפִלּוּ מֵאָה פְּעָמִים שֶׁנֶּאֱמַר (שמות כג ה) \"עָזֹב תַּעֲזֹב\" (דברים כב ד) \"הָקֵם תָּקִים עִמּוֹ\". לְפִיכָךְ צָרִיךְ לְהִדַּדּוֹת עִמּוֹ עַד פַּרְסָה אֶלָּא אִם כֵּן אוֹמֵר לוֹ בַּעַל הַמַּשָּׂא אֵינִי צָרִיךְ לְךָ:","מֵאֵימָתַי יִתְחַיֵּב לִפְרֹק וְלִטְעֹן עִמּוֹ. מִשֶּׁיִּרְאֵהוּ רְאִיָּה שֶׁהִיא כִּפְגִיעָה שֶׁהֲרֵי נֶאֱמַר (שמות כג ה) \"כִּי תִרְאֶה\" וְנֶאֱמַר (שמות כג ד) \"כִּי תִפְגַּע\". וְכַמָּה. שִׁעֲרוּ חֲכָמִים מִשֶּׁיִּהְיֶה בֵּינֵיהֶם מָאתַיִם וְשִׁשִּׁים וְשֵׁשׁ אַמָּה וּשְׁנֵי שְׁלִישֵׁי אַמָּה שֶׁהוּא אֶחָד מִשִּׁבְעָה וּמֶחֱצָה בְּמִיל. הָיָה רָחוֹק מִמֶּנּוּ יֶתֶר מִזֶּה אֵינוֹ זָקוּק לוֹ:","מִצְוָה מִן הַתּוֹרָה לִפְרֹק עִמּוֹ בְּחִנָּם. אֲבָל לִטְעֹן עָלָיו הֲרֵי זוֹ מִצְוָה וְנוֹטֵל שְׂכָרוֹ. וְכֵן בְּשָׁעָה שֶׁמְּדַדֶּה עִמּוֹ עַד פַּרְסָה יֵשׁ לוֹ שָׂכָר:","מָצָא בֶּהֱמַת חֲבֵרוֹ רְבוּצָה אַף עַל פִּי שֶׁאֵין הַבְּעָלִים עִמָּהּ מִצְוָה לִפְרֹק מֵעָלֶיהָ וְלִטְעֹן עָלֶיהָ שֶׁנֶּאֱמַר (שמות כג ה) \"עָזֹב תַּעֲזֹב\" (דברים כב ד) \"הָקֵם תָּקִים\" מִכָּל מָקוֹם. אִם כֵּן לָמָּה נֶאֱמַר עִמּוֹ שֶׁאִם הָיָה בַּעַל הַבְּהֵמָה שָׁם וְהָלַךְ וְיָשַׁב לוֹ וְאָמַר לָזֶה שֶׁפָּגַע בּוֹ הוֹאִיל וְעָלֶיךָ מִצְוָה אִם רָצִיתָ לִפְרֹק לְבַדְּךָ פְּרֹק הֲרֵי זֶה פָּטוּר שֶׁנֶּאֱמַר (שמות כג ה) \"עִמּוֹ\". וְאִם הָיָה בַּעַל הַבְּהֵמָה זָקֵן אוֹ חוֹלֶה חַיָּב לִטְעֹן וְלִפְרֹק לְבַדּוֹ:","בֶּהֱמַת הָעַכּוּ\"ם וְהַמַּשָּׂא שֶׁל יִשְׂרָאֵל אִם הָיָה הָעַכּוּ\"ם מְחַמֵּר אַחֵר בְּהֶמְתּוֹ אֵינוֹ זָקוּק לָהּ. וְאִם לָאו חַיָּב לִפְרֹק וְלִטְעֹן מִשּׁוּם צַעַר יִשְׂרָאֵל. וְכֵן אִם הָיְתָה הַבְּהֵמָה שֶׁל יִשְׂרָאֵל וְהַמַּשּׂוֹי שֶׁל עַכּוּ\"ם חַיָּב לִפְרֹק וְלִטְעֹן מִשּׁוּם צַעַר יִשְׂרָאֵל אֲבָל בֶּהֱמַת הָעַכּוּ\"ם וּמַשָּׂאוֹ אֵינוֹ חַיָּב לְהִטַּפֵּל בָּהֶן אֶלָּא מִשּׁוּם אֵיבָה:","חַמָּרִים שֶׁרַגְלָיו שֶׁל אֶחָד מֵהֶן רְעוּעוֹת אֵינָן רַשָּׁאִין חֲבֵרָיו לְהַקְדִּים וְלַעֲבֹר מֵעָלָיו. נָפַל רַשָּׁאִין לַעֲבֹר מֵעָלָיו:","הָיָה אֶחָד טָעוּן וְאֶחָד רוֹכֵב וּדְחָקָן הַדֶּרֶךְ. מַעֲבִירִין אֶת הָרוֹכֵב מִפְּנֵי הַטָּעוּן. אֶחָד טָעוּן וְאֶחָד רֵיקָן מַעֲבִירִין אֶת הָרֵיקָן מִפְּנֵי הַטָּעוּן. אֶחָד רָכוּב וְאֶחָד רֵיקָן מַעֲבִירִין אֶת הָרֵיקָן מִפְּנֵי הָרָכוּב. שְׁנֵיהֶן טְעוּנִין שְׁנֵיהֶן רוֹכְבִין שְׁנֵיהֶן רֵיקָנִין עוֹשִׂין פְּשָׁרָה בֵּינֵיהֶן:","וְכֵן שְׁתֵּי סְפִינוֹת הָעוֹבְרוֹת וּפוֹגְעוֹת זוֹ בָּזוֹ אִם עוֹבְרוֹת שְׁתֵּיהֶן בְּבַת אַחַת טוֹבְעוֹת וְאִם בָּזוֹ אַחַר זוֹ עוֹבְרוֹת. וְכֵן שְׁנֵי גְּמַלִּים הָעוֹלִים בְּמַעֲלֶה גָּבוֹהַּ וּפָגְעוּ זֶה בָּזֶה אִם עוֹבְרִין שְׁנֵיהֶם בְּבַת אַחַת נוֹפְלִין וְאִם בָּזֶה אַחַר זֶה עוֹלִין. כֵּיצַד הֵן עוֹשִׂין. טְעוּנָה וְשֶׁאֵינָהּ טְעוּנָה תִּדָּחֶה שֶׁאֵינָהּ טְעוּנָה מִפְּנֵי הַטְּעוּנָה. קְרוֹבָה וּרְחוֹקָה תִּדָּחֶה קְרוֹבָה מִפְּנֵי שֶׁאֵינָהּ קְרוֹבָה. שְׁתֵּיהֶן רְחוֹקוֹת אוֹ קְרוֹבוֹת אוֹ טְעוּנוֹת הוֹאִיל וְכֻלָּן בְּדֹחַק אֶחָד הַטֵּל פְּשָׁרָה בֵּינֵיהֶן וְהֵן מַעֲלוֹת שָׂכָר זֶה לָזֶה. וּבָזֶה וְכַיּוֹצֵא בּוֹ נֶאֱמַר (ויקרא יט טו) \"בְּצֶדֶק תִּשְׁפֹּט עֲמִיתֶךָ\":","הַפּוֹגֵעַ בִּשְׁנַיִם אֶחָד רוֹבֵץ תַּחַת מַשָּׂאוֹ וְאֶחָד פָּרַק מֵעָלָיו וְלֹא מָצָא מִי שֶׁיִּטְעֹן עִמּוֹ. מִצְוָה לִפְרֹק בַּתְּחִלָּה מִשּׁוּם צַעַר בַּעֲלֵי חַיִּים וְאַחַר כָּךְ טוֹעֵן. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיוּ שְׁנֵיהֶם שׂוֹנְאִים אוֹ אוֹהֲבִים. אֲבָל אִם הָיָה אֶחָד שׂוֹנֵא וְאֶחָד אוֹהֵב מִצְוָה לִטְעֹן עִם הַשּׂוֹנֵא תְּחִלָּה כְּדֵי לָכֹף אֶת יִצְרוֹ הָרַע:","הַשּׂוֹנֵא שֶׁנֶּאֱמַר בַּתּוֹרָה לֹא מֵאֻמּוֹת הָעוֹלָם הוּא אֶלָּא מִיִּשְׂרָאֵל. וְהֵיאַךְ יִהְיֶה לְיִשְׂרָאֵל שׂוֹנֵא מִיִּשְׂרָאֵל וְהַכָּתוּב אוֹמֵר (ויקרא יט יז) \"לֹא תִשְׂנָא אֶת אָחִיךָ בִּלְבָבֶךָ\". אָמְרוּ חֲכָמִים כְּגוֹן שֶׁרָאָהוּ לְבַדּוֹ שֶׁעָבַר עֲבֵרָה וְהִתְרָה בּוֹ וְלֹא חָזַר הֲרֵי זֶה מִצְוָה לְשָׂנְאוֹ עַד שֶׁיַּעֲשֶׂה תְּשׁוּבָה וְיָשׁוּב מֵרִשְׁעוֹ. וְאַף עַל פִּי שֶׁעֲדַיִן לֹא עָשָׂה תְּשׁוּבָה אִם מְצָאוֹ נִבְהָל בְּמַשָּׂאוֹ מִצְוָה לִטְעֹן וְלִפְרֹק עִמּוֹ וְלֹא יַנִּיחֶנּוּ נוֹטֶה לָמוּת שֶׁמָּא יִשְׁהֶה בִּשְׁבִיל מָמוֹנוֹ וְיָבוֹא לִידֵי סַכָּנָה. וְהַתּוֹרָה הִקְפִּידָה עַל נַפְשׁוֹת יִשְׂרָאֵל. בֵּין רְשָׁעִים בֵּין צַדִּיקִים. מֵאַחַר שֶׁהֵם נִלְוִים אֶל ה' וּמַאֲמִינִים בְּעִקַּר הַדָּת. שֶׁנֶּאֱמַר (יחזקאל לג יא) \"אֱמֹר אֲלֵיהֶם חַי אָנִי נְאֻם ה' אֱלֹהִים אִם אֶחְפֹּץ בְּמוֹת הָרָשָׁע כִּי אִם בְּשׁוּב רָשָׁע מִדַּרְכּוֹ וְחָיָה\"."],"Mishneh Torah, Nazariteship 3":["סְתָם נְזִירוּת שְׁלֹשִׁים יוֹם. כֵּיצַד. מִי שֶׁאָמַר הֲרֵינִי נָזִיר אֵין פָּחוֹת מִשְּׁלֹשִׁים יוֹם. וַאֲפִלּוּ אָמַר הֲרֵינִי נָזִיר נְזִירוּת גְּדוֹלָה עַד מְאֹד הַרְבֵּה הֲרֵי זֶה נָזִיר שְׁלֹשִׁים יוֹם. שֶׁהֲרֵי לֹא פֵּרֵשׁ זְמַן:","פֵּרֵשׁ זְמַן פָּחוֹת מִשְּׁלֹשִׁים כְּגוֹן שֶׁאָמַר הֲרֵינִי נָזִיר יוֹם אֶחָד אוֹ עֲשָׂרָה יָמִים אוֹ עֶשְׂרִים יוֹם הֲרֵי זֶה נָזִיר שְׁלֹשִׁים יוֹם שֶׁאֵין נְזִירוּת פְּחוּתָה מִשְּׁלֹשִׁים יוֹם. וְדָבָר זֶה הֲלָכָה מִפִּי הַקַּבָּלָה:","פֵּרֵשׁ זְמַן יוֹתֵר מִשְּׁלֹשִׁים יוֹם כְּגוֹן שֶׁאָמַר אֶחָד וּשְׁלֹשִׁים יוֹם אוֹ אַרְבָּעִים אוֹ מֵאָה יוֹם אוֹ מֵאָה שָׁנָה הֲרֵי זֶה נָזִיר כִּזְמַן שֶׁפֵּרֵשׁ לֹא פָּחוֹת וְלֹא יוֹתֵר:","הָאוֹמֵר הֲרֵינִי נָזִיר שָׁעָה אַחַת הֲרֵי זֶה נָזִיר שְׁלֹשִׁים יוֹם. אָמַר הֲרֵינִי נָזִיר שְׁלֹשִׁים יוֹם וְשָׁעָה אַחַת הֲרֵי זֶה נָזִיר אֶחָד וּשְׁלֹשִׁים יוֹם שֶׁאֵין נוֹזְרִין שָׁעוֹת:","הָאוֹמֵר הֲרֵינִי נָזִיר מִכָּאן עַד מָקוֹם פְּלוֹנִי. אִם לֹא הֶחֱזִיק בַּדֶּרֶךְ הֲרֵי זֶה נָזִיר שְׁלֹשִׁים יוֹם בִּלְבַד. שֶׁלֹּא נִתְכַּוֵּן זֶה אֶלָּא לִנְזִירוּת גְּדוֹלָה וַהֲרֵי לֹא פֵּרֵשׁ זְמַן. וְאִם הֶחֱזִיק בַּדֶּרֶךְ אִם הָיָה מְהַלֵּךְ פָּחוֹת מִשְּׁלֹשִׁים יוֹם הֲרֵי זֶה נָזִיר שְׁלֹשִׁים יוֹם. וְאִם הָיָה יוֹתֵר מִשְּׁלֹשִׁים יוֹם הֲרֵי זֶה נָזִיר נְזִירוּת אַחַת כְּמִנְיַן הַיָּמִים:","מִי שֶׁאָמַר הֲרֵינִי נָזִיר שְׁתֵּי נְזִירוּת אוֹ שָׁלֹשׁ אוֹ אַרְבַּע הֲרֵי זֶה נָזִיר כַּמִּנְיָן שֶׁאָמַר כָּל נְזִירוּת מֵהֶן שְׁלֹשִׁים יוֹם. וּבְסוֹף כָּל שְׁלֹשִׁים וּשְׁלֹשִׁים מְגַלֵּחַ וּמֵבִיא קָרְבְּנוֹתָיו וּמַתְחִיל לִמְנוֹת נְזִירוּת שְׁנִיָּה. אֲפִלּוּ אָמַר הֲרֵינִי נָזִיר מֵאָה אֶלֶף נְזִירִיּוֹת שֶׁאִי אֶפְשָׁר שֶׁיִּחְיֶה כַּזְּמַן הַזֶּה הֲרֵי זֶה מוֹנֶה אַחַת אַחַר אַחַת עַד שֶׁיָּמוּת אוֹ עַד שֶׁיַּשְׁלִים מִנְיַן נְזִירוּתָיו:","הָאוֹמֵר הֲרֵינִי נָזִיר כְּמִנְיַן יְמוֹת הַשָּׁנָה. מוֹנֶה נְזִירוּתָיו כְּמִנְיַן יְמוֹת הַשָּׁנָה. אִם פֵּרֵשׁ שְׁנַת הַחַמָּה מוֹנֶה שְׁלֹשׁ מֵאוֹת וְשִׁשִּׁים וְחָמֵשׁ נְזִירוּת כָּל אַחַת מֵהֶן שְׁלֹשִׁים יוֹם. וְאִם פֵּרֵשׁ שְׁנַת לְבָנָה מוֹנֶה שְׁלֹשׁ מֵאוֹת אַרְבַּע וַחֲמִשִּׁים נְזִירוּת. וְאִם סְתָם מוֹנֶה שְׁלֹשׁ מֵאוֹת וְאַרְבַּע וַחֲמִשִּׁים נְזִירוּת שֶׁהֲרֵי בֵּאַרְנוּ שֶׁכָּל הַנְּדָרִים הוֹלְכִין אַחַר לְשׁוֹן בְּנֵי אָדָם. וְרֹב שְׁנֵי הַחַמָּה שְׁלֹשׁ מֵאוֹת וַחֲמִשָּׁה וְשִׁשִּׁים יוֹם מוֹנִין לָהּ. וְרֹב שְׁנֵי הַלְּבָנָה שְׁלֹשׁ מֵאוֹת וְאַרְבַּע וַחֲמִשִּׁים יוֹם מוֹנִין לָהּ. וְאֵין קוֹרִין כָּל הָעָם שָׁנָה סְתָם אֶלָּא לִשְׁנַת הַלְּבָנָה:","הָאוֹמֵר הֲרֵינִי נָזִיר אַחַת וּמֶחֱצָה הֲרֵי זֶה נָזִיר שְׁתֵּי נְזִירוּת. אָמַר הֲרֵינִי נָזִיר וְיוֹם אֶחָד אוֹ שֶׁאָמַר הֲרֵינִי נָזִיר וְשָׁעָה אַחַת הֲרֵי זֶה נָזִיר שְׁתֵּי נְזִירוּת. אָמַר הֲרֵינִי נָזִיר וְאַחַת הֲרֵי זֶה נָזִיר שְׁתַּיִם. הֲרֵינִי נָזִיר וְאַחַת וְעוֹד הֲרֵי זֶה נָזִיר שָׁלֹשׁ נְזִירוּת. הֲרֵינִי נָזִיר וְאַחַת וְעוֹד וְשׁוּב הֲרֵי זֶה נָזִיר אַרְבַּע נְזִירוּת. הֲרֵינִי נָזִיר שְׁלֹשִׁים יוֹם וְיוֹם אֶחָד הֲרֵי זֶה נָזִיר נְזִירוּת אַחַת שֶׁל שְׁלֹשִׁים וְאֶחָד יוֹם:","מִי שֶׁהָיוּ שְׁתֵּי כִּתֵּי עֵדִים מְעִידִין אוֹתוֹ. אֵלּוּ מְעִידִין שֶׁנָּזַר שְׁתַּיִם וְאֵלּוּ מְעִידִין שֶׁנָּזַר חָמֵשׁ. הֲרֵי זֶה נָזִיר שְׁתַּיִם שֶׁבִּכְלַל חָמֵשׁ שְׁתַּיִם וַהֲרֵי כֻּלָּן מְעִידִים בִּשְׁתַּיִם:","מִי שֶׁנָּזַר שְׁתֵּי נְזִירוּת בֵּין שֶׁנָּדַר שְׁתֵּיהֶן בְּבַת אַחַת בֵּין שֶׁנָּדַר זוֹ אַחַר זוֹ. כְּגוֹן שֶׁאָמַר הֲרֵינִי נָזִיר יוֹם הֲרֵינִי נָזִיר יוֹם וּמָנָה אֶת הָרִאשׁוֹנָה וְהִפְרִישׁ קָרְבָּן. וְאַחַר כָּךְ נִשְׁאַל עַל הָרִאשׁוֹנָה וְהִתִּיר נִדְרוֹ. עָלְתָה לוֹ רִאשׁוֹנָה בַּשְּׁנִיָּה וּמֵבִיא זֶה הַקָּרְבָּן וְנִפְטָר. וַאֲפִלּוּ הֵבִיא כַּפָּרָתוֹ וַאֲפִלּוּ גִּלֵּחַ שְׂעָרוֹ וְאַחַר כָּךְ נִשְׁאַל עָלֶיהָ עָלְתָה לוֹ רִאשׁוֹנָה בַּשְּׁנִיָּה. שֶׁהֲרֵי אֵין הַשְּׁנִיָּה חָלָה אֶלָּא לְאַחַר הָרִאשׁוֹנָה וְהָרִאשׁוֹנָה כֵּיוָן שֶׁהִתִּירָהּ כְּאִלּוּ אֵינָהּ מֵעִקָּרָהּ:","מִי שֶׁאָמַר הֲרֵינִי נָזִיר לְעוֹלָם אוֹ הֲרֵינִי נָזִיר כָּל יְמֵי חַיַּי הֲרֵי זֶה נָזִיר לְעוֹלָם. וְאִם אָמַר הֲרֵינִי נָזִיר אֶלֶף שָׁנָה הֲרֵי זֶה נָזִיר לִזְמַן קָצוּב. וְאַף עַל פִּי שֶׁאִי אֶפְשָׁר שֶׁיִּחְיֶה הָאָדָם אֶלֶף שָׁנָה:","ומַה בֵּין נְזִיר עוֹלָם לְנָזִיר לִזְמַן קָצוּב. שֶׁהַנָּזִיר לִזְמַן אָסוּר לְגַלֵּחַ עַד סוֹף יְמֵי נְזִירוֹ שֶׁנֶּאֱמַר (במדבר ו ה) \"כָּל יְמֵי נֶדֶר נִזְרוֹ תַּעַר לֹא יַעֲבֹר עַל רֹאשׁוֹ עַד מְלֹאת הַיָּמִם\". וּנְזִיר עוֹלָם אִם הִכְבִּיד שְׂעָרוֹ מֵקֵל בְּתַעַר מִשְּׁנֵים עָשָׂר חֹדֶשׁ עַד שְׁנֵים עָשָׂר חֹדֶשׁ. וּמֵבִיא קָרְבָּנוֹ שָׁלֹשׁ בְּהֵמוֹת כְּשֶׁיְּגַלֵּחַ שֶׁנֶּאֱמַר (שמואל ב יד כו) \"וַיְהִי מִקֵּץ יָמִים לַיָּמִים אֲשֶׁר יְגַלֵּחַ כִּי כָבֵד עָלָיו וְגִלְּחוֹ\". וְאַבְשָׁלוֹם נְזִיר עוֹלָם הָיָה. וְדָבָר זֶה הֲלָכָה הִיא מִפִּי הַקַּבָּלָה. וּנְזִיר עוֹלָם שֶׁנִּטְמָא הֲרֵי זֶה מֵבִיא קָרְבַּן טֻמְאָה וּמְגַלֵּחַ תִּגְלַחַת טֻמְאָה כְּמוֹ נָזִיר לִזְמַן קָצוּב:","שִׁמְשׁוֹן לֹא הָיָה נָזִיר גָּמוּר. שֶׁהֲרֵי לֹא נָדַר בְּנָזִיר אֶלָּא הַמַּלְאָךְ הִפְרִישׁוֹ מִן הַטֻּמְאָה. וְכֵיצַד הָיָה דִּינוֹ. הָיָה אָסוּר בְּיַיִן וְאָסוּר בְּתִגְלַחַת וּמֻתָּר לְהִטָּמֵא לַמֵּתִים. וְדָבָר זֶה הֲלָכָה מִפִּי הַקַּבָּלָה:","לְפִיכָךְ מִי שֶׁאָמַר הֲרֵינִי נָזִיר כְּשִׁמְשׁוֹן הֲרֵי זֶה נָזִיר מִן הַתִּגְלַחַת וּמִן הַיַּיִן לְעוֹלָם. וְאֵינוֹ מְגַלֵּחַ כָּל שְׁנֵים עָשָׂר חֹדֶשׁ כִּשְׁאָר נְזִירֵי עוֹלָם. וּמֻתָּר לְהִטָּמֵא לַמֵּתִים. וְאִם אָמַר לֹא נִתְכַּוַּנְתִּי אֶלָּא לְאִישׁ אַחֵר שֶׁשְּׁמוֹ שִׁמְשׁוֹן אֵינוֹ נָזִיר. וּמִי שֶׁנָּדַר נָזִיר כְּשִׁמְשׁוֹן אֵינוֹ יָכוֹל לְהִשָּׁאֵל עַל נִדְרוֹ שֶׁנְּזִירוּת שִׁמְשׁוֹן לְעוֹלָם הָיְתָה:","הָאוֹמֵר הֲרֵינִי כְּשִׁמְשׁוֹן כְּבֶן מָנוֹחַ. כְּבַעַל דְּלִילָה. כְּמִי שֶׁעָקַר דַּלְתוֹת עַזָּה. כְּמִי שֶׁנִּקְּרוּ פְּלִשְׁתִּים אֶת עֵינָיו. הֲרֵי זֶה נָזִיר כִּנְזִירוּת שִׁמְשׁוֹן. וְאַף עַל פִּי שֶׁאֶפְשָׁר שֶׁנַּעֲשׂוּ מַעֲשִׂים אֵלּוּ לְאִישׁ אַחֵר:","שְׁמוּאֵל הָרָמָתִי נְזִיר עוֹלָם הָיָה. לְפִיכָךְ הָאוֹמֵר הֲרֵינִי כִּשְׁמוּאֵל הָרָמָתִי. כְּבֶן חַנָּה. כְּבֶן אֶלְקָנָה. כְּמִי שֶׁשִּׁסֵּף אֶת אֲגַג בַּגִּלְגָּל. וְכַיּוֹצֵא בְּאֵלּוּ. הֲרֵי זֶה נְזִיר עוֹלָם. וְאֵין אוֹמְרִין שֶׁמָּא לְאִישׁ אַחֵר שֶׁמַּעֲשָׂיו כָּאֵלֶּה נִתְכַּוֵּן:","הָאוֹמֵר הֲרֵינִי נָזִיר מְלֹא הַבַּיִת אוֹ מְלֹא הַקֻּפָּה. בּוֹדְקִין אוֹתוֹ אִם אָמַר לֹא הָיָה בְּדַּעְתִּי שֶׁאֶהֱיֶה נָזִיר כָּל יָמַי וְלֹא נִתְכַּוַּנְתִּי אֶלָּא לְהַאֲרִיךְ זְמַן הַנְּזִירוּת זְמַן מְרֻבֶּה הֲרֵי זֶה נָזִיר שְׁלֹשִׁים יוֹם בִּלְבַד. וְאִם אָמַר סְתָם נָדַרְתִּי רוֹאִים אֶת הַקֻּפָּה כְּאִלּוּ הִיא מְלֵאָה חַרְדָּל וְיִהְיֶה נָזִיר כָּל יָמָיו. וְיֵשׁ לוֹ לְגַלֵּחַ מִשְּׁנֵים עָשָׂר חֹדֶשׁ לִשְׁנֵים עָשָׂר חֹדֶשׁ וְיָבִיא קָרְבְּנוֹתָיו כִּשְׁאָר נְזִירֵי עוֹלָם:","הָאוֹמֵר הֲרֵינִי נָזִיר כִּשְׂעַר רֹאשִׁי. אוֹ כַּעֲפַר הָאָרֶץ. אוֹ כְּחוֹל הַיָּם. הֲרֵי זֶה כְּמִי שֶׁאָמַר הֲרֵי נְזִירוּת עָלַי כְּמִנְיַן שְׂעַר רֹאשִׁי אוֹ כְּמִנְיַן עֲפַר הָאָרֶץ אוֹ כְּמִנְיַן חוֹל הַיָּם. לְפִיכָךְ יְגַלֵּחַ כָּל שְׁלֹשִׁים יוֹם וְיַתְחִיל לִמְנוֹת נְזִירוּת שְׁנִיָּה שְׁלֹשִׁים יוֹם וִיגַלֵּחַ וְכֵן עַד שֶׁיָּמוּת. וּבְכָל תִּגְלַחַת וְתִגְלַחַת אֵינוֹ שׁוֹתֶה יַיִן וְלֹא מִטַּמֵּא לַמֵּתִים וְאִם שָׁתָה אוֹ נִטְמָא אֲפִלּוּ בְּיוֹם הַתִּגְלַחַת הֲרֵי זֶה לוֹקֶה:","הָאוֹמֵר הֲרֵינִי נָזִיר אִם אֹכַל כִּכָּר זוֹ. הֲרֵינִי נָזִיר אִם אֹכָלֶנָּה. הֲרֵינִי נָזִיר אִם אֹכָלֶנָּה. וַאֲכָלָהּ. הֲרֵי זֶה חַיָּב בִּנְזִירוּת כַּמִּנְיָן שֶׁאָמַר וּמוֹנֶה אַחַת אַחַר אַחַת כָּל אַחַת מֵהֶן שְׁלֹשִׁים וּמְגַלֵּחַ בְּסוֹף כָּל שְׁלֹשִׁים וּמֵבִיא קָרְבָּנוֹ:"],"Mishneh Torah, Negative Mitzvot 103":["שלא ליתן עליה לבונה, שנאמר \"ולא ייתן עליה לבונה\" (ויקרא ה,יא)."],"Mishneh Torah, Negative Mitzvot 114":["שלא לגזוז את הקודשים, שנאמר \"ולא תגוז בכור צאנך\" (דברים טו,יט)."],"Mishneh Torah, Negative Mitzvot 125":["שלא לאכול בשר הפסח נא ומבושל, שנאמר \"אל תאכלו ממנו נא, ובשל\" (שמות יב,ט)."],"Mishneh Torah, Negative Mitzvot 136":["שלא יאכל כוהן טמא תרומה, שנאמר \"איש מזרעך . . . בקודשים לא יאכל\" (ראה ויקרא כא,יז; ויקרא כב,ד)."],"Mishneh Torah, Negative Mitzvot 147":["שלא לאכול בשר קודשים קלים קודם זריקת דמים, שנאמר \"לא תוכל . . . ונדבותיך\" (דברים יב,יז); כלומר, לא תוכל לאכול נדבותיך עד שייזרק דמם."],"Mishneh Torah, Negative Mitzvot 158":["שלא ייקח כוהן זונה, שנאמר \"אישה זונה וחללה לא ייקחו\" (ויקרא כא,ז)."],"Mishneh Torah, Negative Mitzvot 169":["שלא ייקח כל שבט לוי חלק בארץ, שנאמר \"ונחלה לא יהיה לו\" (דברים יח,ב)."],"Mishneh Torah, Negative Mitzvot 18":["שלא לעזוב השנאה למסית, שנאמר \"ולא תשמע אליו\" (דברים יג,ט)."],"Mishneh Torah, Negative Mitzvot 190":["שלא לאכול קלי מן החדש, שנאמר \"וקלי . . . לא תאכלו\" (ויקרא כג,יד)."],"Mishneh Torah, Negative Mitzvot 200":["שלא ייראה חמץ, שנאמר \"לא ייראה לך חמץ\" (שמות יג,ז)."],"Mishneh Torah, Negative Mitzvot 211":["שלא ללקוט השיבולים הנופלות בשעת קצירה, שנאמר \"ולקט קצירך, לא תלקט\" (ויקרא יט,ט; ויקרא כג,כב)."],"Mishneh Torah, Negative Mitzvot 222":["שלא לקצור ספיחי שביעית כדרך שקוצרין בשאר השנים, שנאמר \"את ספיח קצירך לא תקצור\" (ויקרא כה,ה)."],"Mishneh Torah, Negative Mitzvot 233":["שלא לשלח עבד עברי ריקם כשייצא חופשי, שנאמר \"לא תשלחנו, ריקם\" (דברים טו,יג)."],"Mishneh Torah, Negative Mitzvot 244":["שלא לגנוב ממון, שנאמר \"לא, תגנובו\" (ויקרא יט,יא); זו היא גניבת ממון."],"Mishneh Torah, Negative Mitzvot 255":["שלא להונות עבד זה, שנאמר \"עִמְּךָ יֵשֵׁב בְּקִרְבֶּךָ... בַּטּוֹב לוֹ לֹא תּוֹנֶנּוּ\" (דברים כג, יז)."],"Mishneh Torah, Negative Mitzvot 266":["שלא להתאוות, שנאמר \"לֹא תִתְאַוֶּה בֵּית רֵעֶךָ\" (דברים ה, יז)."],"Mishneh Torah, Negative Mitzvot 277":["שלא לרחם על עני בדין, שנאמר \"וְדָל לֹא תֶהְדַּר בְּרִיבוֹ\" (שמות כג, ג)."],"Mishneh Torah, Negative Mitzvot 288":["שלא לכרות הדין על פי עד אחד, שנאמר \"לֹא יָקוּם עֵד אֶחָד בְּאִישׁ\" (דברים יט, טו)."],"Mishneh Torah, Negative Mitzvot 299":["שלא להכשיל תם בדרך, שנאמר \"וְלִפְנֵי עִוֵּר לֹא תִתֵּן מִכְשׁוֹל\" (ויקרא יט, יד)."],"Mishneh Torah, Negative Mitzvot 309":["שלא לעבוד ולזרוע בנחל איתן, שנאמר \"אשר לא ייעבד בו, ולא ייזרע\" (דברים כא,ד)."],"Mishneh Torah, Negative Mitzvot 32":["שלא לעונן, שנאמר \"לא תעוננו\" (ויקרא יט,כו)."],"Mishneh Torah, Negative Mitzvot 330":["שלא לגלות ערוות אם, שנאמר \"אימך היא, לא תגלה ערוותה\" (ויקרא יח,ז)."],"Mishneh Torah, Negative Mitzvot 341":["שלא לגלות ערוות אחות האם, שנאמר \"ערוות אחות אימך, לא תגלה\" (ויקרא יח,יג)."],"Mishneh Torah, Negative Mitzvot 352":["שלא לגלות ערוות אחי האב עצמו, שנאמר \"ערוות אחי אביך, לא תגלה\" (ויקרא יח,יד)."],"Mishneh Torah, Negative Mitzvot 363":["שלא ירבה המלך סוסים, שנאמר \"לא ירבה לו סוסים\" (דברים יז,טז)."],"Mishneh Torah, Negative Mitzvot 45":["שלא להתגודד כעובדי עבודה זרה, שנאמר \"לא תתגודדו\" (דברים יד,א); וגדידה ושריטה אחת היא."],"Mishneh Torah, Negative Mitzvot 56":["שלא לקרוא שלום לעמון ומואב בתחילה בשעת מלחמה כשאר גויים, שנאמר \"לא תדרוש שלומם, וטובתם\" (דברים כג,ז)."],"Mishneh Torah, Negative Mitzvot 67":["שלא להשבית שמירה סביב למקדש, שנאמר \"וּשְׁמַרְתֶּם אֶת מִשְׁמַרְתִּי\" (ויקרא יח, ל)."],"Mishneh Torah, Negative Mitzvot 78":["שלא יכנס טמא למחנה לויה שכנגדו לדורות הר הבית, שנאמר \"לֹא יָבֹא אֶל תּוֹךְ הַמַּחֲנֶה\" (דברים כג, יא); זה מחנה לויה."],"Mishneh Torah, Negative Mitzvot 89":["שלא להעלות קודשים בחוץ, שנאמר \"הישמר לך, פן תעלה עולותיך\" (דברים יב,יג)."],"Mishneh Torah, Neighbors 1":["אֶחָד הַקּוֹנֶה מֵחֲבֵרוֹ חֲצִי שָׂדֵהוּ. אוֹ שְׁנַיִם שֶׁקָּנוּ מֵאֶחָד שָׂדֶה. אוֹ שֶׁיָּרְשׁוּ. אוֹ שֶׁנִּתְּנָה לָהֶן בְּמַתָּנָה. אוֹ שֶׁהֶחְזִיקוּ בָּהּ מִן הַהֶפְקֵר. אוֹ נִכְסֵי גֵּר. כְּלָלוֹ שֶׁל דָּבָר כָּל שֶׁיֵּשׁ בֵּינֵיהֶם שֻׁתָּפוּת בַּקַּרְקַע וּבִקֵּשׁ אֶחָד מִן הַשֻּׁתָּפִין לַחֲלֹק וְלִטּל חֶלְקוֹ לְבַדּוֹ. אִם יֵשׁ בְּאוֹתָהּ קַרְקַע דִּין חֲלוּקָה כּוֹפֶה אֶת שְׁאָר הַשֻּׁתָּפִין וְחוֹלְקִין עִמּוֹ. וְאִם אֵין בָּהּ דִּין חֲלוּקָה אֵין אֶחָד מֵהֶן יָכוֹל לָכֹף אֶת חֲבֵרוֹ לַחֲלֹק. וְכֵן הַדִּין בְּמִטַּלְטְלִין. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁאֵין אֶחָד מֵהֶן מַכִּיר אֶת חֶלְקוֹ בַּמָּקוֹם שֶׁהֵן שֻׁתָּפִין בּוֹ אֶלָּא יַד כֻּלָּן מִשְׁתַּמֵּשׁ בְּכָל הַמָּקוֹם. אֲבָל אִם הָיָה אֶחָד מֵהֶן מַכִּיר חֶלְקוֹ אַף עַל פִּי שֶׁאֵין בָּהּ דִּין חֲלוּקָה כּוֹפֶה כָּל אֶחָד מֵהֶן אֶת חֲבֵרוֹ לְהַבְדִּיל בֵּין חֶלְקוֹ לְחֵלֶק חֲבֵרוֹ:","אֶחָד מִן הַשֻּׁתָּפִין שֶׁאָמַר לַחֲבֵרוֹ בְּמָקוֹם שֶׁאֵין בּוֹ דִּין חֲלוּקָה. אוֹ בְּדָבָר שֶׁאִי אֶפְשָׁר שֶׁיַּחְלְקוּ כְּגוֹן שִׁפְחָה אוֹ כְּלִי. מְכֹר לִי חֶלְקְךָ בְּכָךְ וְכָךְ אוֹ קְנֵה מִמֶּנִּי כַּשַּׁעַר הַזֶּה. הַדִּין עִמּוֹ וְכוֹפִין אֶת הַנִּתְבָּע לִמְכֹּר לַחֲבֵרוֹ אוֹ לִקְנוֹת מִמֶּנּוּ. אֲבָל אִם אֵין הַתּוֹבֵעַ רוֹצֶה לִקְנוֹת אוֹ לֹא יִמְצָא בְּמָה יִקְנֶה. אֵינוֹ יָכוֹל לָכֹף אֶת חֲבֵרוֹ לִקְנוֹת מִמֶּנּוּ אֲפִלּוּ כַּשַּׁעַר הַזּוֹל. שֶׁהֲרֵי חֲבֵרוֹ יָכוֹל לוֹמַר לוֹ אֵין רְצוֹנִי שֶׁאֶקְנֶה אֶלָּא שֶׁאֶמְכֹּר. לְפִיכָךְ שְׁנֵי אַחִין אֶחָד עָנִי וְאֶחָד עָשִׁיר שֶׁהִנִּיחַ לָהֶם אֲבִיהֶם מֶרְחָץ אוֹ בֵּית הַבַּד. אִם עֲשָׂאָן הָאָב לְשָׂכָר הַשָּׂכָר לָאֶמְצַע כָּל זְמַן שֶׁיִּרְצוּ לַעֲמֹד בְּשֻׁתָּפוּת. עֲשָׂאָן הָאָב לְעַצְמוֹ אֵינוֹ יָכוֹל לָכֹף אָחִיו לְהַשְׂכִּיר אוֹתָם אֶלָּא מִשְׁתַּמְּשִׁין בָּהֶם כְּדֶרֶךְ שֶׁהִשְׁתַּמֵּשׁ אֲבִיהֶם. וַהֲרֵי עָשִׁיר אוֹמֵר לְעָנִי קַח לְךָ זֵיתִים וּבוֹא וַעֲשֵׂה אוֹתָם בְּבֵית הַבַּד. קְנֵה לְךָ עֲבָדִים וְיָבוֹאוּ וְיִרְחֲצוּ בַּמֶּרְחָץ. וְאֵין הֶעָנִי כּוֹפֶה אֶת הֶעָשִׁיר לִקְנוֹת חֶלְקוֹ אֶלָּא אִם כֵּן אָמַר לוֹ קְנֵה מִמֶּנִּי אוֹ מְכֹר לִי וַהֲרֵינִי לוֹוֶה וְקוֹנֶה אוֹ מוֹכֵר לַאֲחֵרִים וְקוֹנִין הַדִּין עִמּוֹ. אָמַר כָּל אֶחָד מֵהֶן אֵינִי קוֹנֶה אֶלָּא הֲרֵינִי מוֹכֵר חֶלְקִי מוֹכְרִין אוֹתָהּ לַאֲחֵרִים. אָמַר כָּל אֶחָד מֵהֶם אֵינִי מוֹכֵר אֶלָּא כָּל אֶחָד מֵהֶן רוֹצֶה שֶׁיִּקְנֶה חֵלֶק חֲבֵרוֹ. אוֹ שֶׁאֵין אֶחָד מֵהֶן רוֹצֶה לֹא לִקְנוֹת חֵלֶק חֲבֵרוֹ וְלֹא לִמְכֹּר חֶלְקוֹ אֶלָּא יִשָּׁאֲרוּ שֻׁתָּפִין בַּגּוּף. הֵיאַךְ הֵן עוֹשִׂין. אִם הָיָה הַמָּקוֹם עָשׂוּי לְשָׂכָר מַשְׂכִּירִין אוֹתוֹ וְחוֹלְקִין שְׂכָרוֹ. וְאִם אֵינוֹ עָשׂוּי לְשָׂכָר אִם חָצֵר הוּא שׁוֹכְנִין בָּהּ שָׁנָה שָׁנָה שֶׁאִי אֶפְשָׁר שֶׁיִּשְׁכְּנוּ שְׁנֵיהֶם כְּאַחַת מִפְּנֵי הֶזֵּק רְאִיָּה שֶׁהֲרֵי אֵין בָּהּ דִּין חֲלוּקָה וְאֵין אָדָם עָשׂוּי לִטְרֹחַ כָּל שְׁלֹשִׁים יוֹם לִפְנוֹת מֵחָצֵר לֶחָצֵר אֶלָּא מִשָּׁנָה לְשָׁנָה. וְאִם מֶרְחָץ הוּא נִכְנָסִין לָהּ שְׁנֵיהֶם תָּמִיד בְּכָל יוֹם. וְכֵן כָּל דָּבָר שֶׁרָאוּי לְהִשְׁתַּמֵּשׁ בּוֹ תָּמִיד וְאֵינוֹ עָשׂוּי לְשָׂכָר כְּגוֹן מֶרְחָץ אוֹ מַצָּע אוֹ סֵפֶר תּוֹרָה אֵינוֹ יָכוֹל לוֹמַר לוֹ הִשְׁתַּמֵּשׁ אַתָּה יוֹם וַאֲנִי יוֹם שֶׁהֲרֵי אוֹמֵר לוֹ בְּכָל יוֹם אֲנִי רוֹצֶה לְהִשְׁתַּמֵּשׁ בּוֹ:","אֶחָד הַשּׂוֹכֵר מֵחֲבֵרוֹ מִקְצָת חָצֵר. אוֹ שָׂדֶה שֶׁאֵין בָּהּ דִּין חֲלוּקָה. אוֹ שְׁנַיִם שֶׁשָּׂכְרוּ מָקוֹם אֶחָד בְּשֻׁתָּפוּת. כָּל אֶחָד מֵהֶן יָכוֹל לָכֹף אֶת חֲבֵרוֹ וְלוֹמַר לוֹ אוֹ שְׂכֹר מִמֶּנִּי חֶלְקִי אוֹ הַשְׂכִּיר לִי חֶלְקְךָ. וְאִם יֵשׁ בָּהּ דִּין חֲלוּקָה חוֹלְקִין:","אֵי זֶהוּ דִּין חֲלוּקָה. כָּל שֶׁאִלּוּ יְחַלֵּק לְפִי הַשֻּׁתָּפִין יַגִּיעַ לַפָּחוּת שֶׁבָּהֶם חֵלֶק שֶׁשֵּׁם הַכּל קָרוּי עָלָיו. אֲבָל אִם אֵין שֵׁם הַכּל נִקְרָא עַל הַחֵלֶק אֵין בָּהּ דִּין חֲלוּקָה. כֵּיצַד. כָּל חָצֵר שֶׁאֵין בָּהּ אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת אֵינָהּ קְרוּיָה חָצֵר. וְכָל שָׂדֶה שֶׁאֵין בָּהּ כְּדֵי זְרִיעַת תִּשְׁעָה קַבִּין אֵינָהּ קְרוּיָה שָׂדֶה. וְכָל גִּנָּה שֶׁאֵין בָּהּ כְּדֵי זְרִיעַת חֲצִי קַב אֵינָהּ קְרוּיָה גִּנָּה. וְכָל פַּרְדֵּס שֶׁאֵין בּוֹ כְּדֵי זְרִיעַת שְׁלֹשָׁה קַבִּין אֵינוֹ קָרוּי פַּרְדֵּס. לְפִיכָךְ אֵין חוֹלְקִין אֶת הֶחָצֵר עַד שֶׁיִּהְיֶה אַרְבַּע אַמּוֹת לְכָל אֶחָד וְאֶחָד מִן הַשֻּׁתָּפִין. וְלֹא אֶת הַשָּׂדֶה עַד שֶׁיִּהְיֶה בָּהּ כְּדֵי זְרִיעַת תִּשְׁעָה קַבִּין [לְכָל אֶחָד וְאֶחָד]. וְלֹא אֶת הַגִּנָּה עַד שֶׁיְּהֵא בָּהּ חֲצִי קַב לְכָל אֶחָד וְאֶחָד. וְלֹא אֶת הַפַּרְדֵּס עַד שֶׁיְּהֵא בּוֹ בֵּית שְׁלֹשָׁה קַבִּין לְכָל אֶחָד וְאֶחָד. בַּמֶּה דְּבָרִים אֲמוּרִים בְּאֶרֶץ יִשְׂרָאֵל וְכַיּוֹצֵא בָּהּ. אֲבָל בְּבָבֶל וְכַיּוֹצֵא בָּהּ אֵין חוֹלְקִין אֶת הַשָּׂדֶה עַד שֶׁיִּהְיֶה בָּהּ כְּדֵי חֲרִישַׁת יוֹם לָזֶה וַחֲרִישַׁת יוֹם לָזֶה. וְלֹא אֶת הַפַּרְדֵּס עַד שֶׁיִּהְיֶה בּוֹ שְׁלֹשִׁים וְשִׁשָּׁה אִילָנוֹת לָזֶה [וּשְׁלֹשִׁים וְשִׁשָּׁה אִילָנוֹת לָזֶה] כְּדֵי עֲבוֹדַת אָדָם אֶחָד בַּיּוֹם אֶחָד. וְשָׂדֶה שֶׁמַּשְׁקִין אוֹתָהּ בִּכְלִי עַד שֶׁיְּהֵא בָּהּ כְּדֵי שֶׁיְּמַלֵּא הַפּוֹעֵל יוֹם אֶחָד לָזֶה וְיוֹם אֶחָד לָזֶה:","אֵין חוֹלְקִין אֶת הַטְּרַקְלִין וְלֹא אֶת הַמּוֹרָן וְלֹא אֶת הַשּׁוֹבָךְ וְלֹא אֶת בֵּית הַבַּד וְלֹא אֶת הַמֶּרְחָץ וְלֹא אֶת הַטַּלִּית עַד שֶׁיְּהֵא בְּכָל חֵלֶק מֵהֶן כְּדֵי לָזֶה וּכְדֵי לָזֶה. אִם מֶרְחָץ חָלְקוּ עַד שֶׁיְּהֵא בְּכָל חֵלֶק מֵהֶן כְּדֵי מֶרְחָץ. וְאִם שׁוֹבָךְ עַד שֶׁיְּהֵא כָּל חֵלֶק שׁוֹבָךְ בִּפְנֵי עַצְמוֹ. וְכֵן בְּטַלִּית וּבִשְׁאָר כָּל הַדְּבָרִים. אֵין בָּהֶן כְּדֵי לָזֶה וּכְדֵי לָזֶה מַעֲלִין אוֹתוֹ בְּדָמִים וְיֵשׁ [לוֹ] לוֹמַר לַחֲבֵרוֹ אוֹ מְכֹר לִי אוֹ קְנֵה מִמֶּנִּי. אָמַר אֶחָד מֵהֶן חֲלֹק זֶה אַף עַל פִּי שֶׁאֵין הַחֲלָקִין שָׁוִים אֲנִי אֶטּל אֶת הַפָּחוּת וְטל אַתָּה אֶת הַיֶּתֶר אֵין שׁוֹמְעִין לוֹ שֶׁהֲרֵי אוֹמֵר לוֹ אֵין רְצוֹנִי לִקַּח מַתָּנָה. אֶלָּא הוֹאִיל וְאֵין בָּהּ דִּין חֲלוּקָה בְּשָׁוֶה הֲרֵי אָנוּ מַעֲלִין בְּדָמִים:"],"Mishneh Torah, Neighbors 8":["הַמְבַקֵשׁ לְהוֹצִיא זִיז מִכָּתְלוֹ עַל אֲוִיר חֲצַר חֲבֵרוֹ כָּל שֶׁהוּא בַּעַל הֶחָצֵר מְעַכֵּב עָלָיו שֶׁהֲרֵי מַזִּיקוֹ בִּרְאִיָּה בְּעֵת שֶׁתּוֹלֶה בּוֹ וּמִשְׁתַּמֵּשׁ בּוֹ. הוֹצִיא אֶת הַזִּיז וְלֹא מִחָה בּוֹ לְאַלְתַּר בַּעַל הֶחָצֵר הֲרֵי הֶחֱזִיק בַּעַל הַזִּיז:","הָיָה הַזִּיז טֶפַח הֶחֱזִיק בַּאֲוִיר הֶחָצֵר כְּנֶגְדּוֹ. וְאִם רָצָה בַּעַל הֶחָצֵר לִבְנוֹת תַּחַת הַזִּיז וּלְבַטֵּל תַּשְׁמִישׁוֹ בַּעַל הַזִּיז מְעַכֵּב עָלָיו. וְאִם אֵין בַּזִּיז טֶפַח לֹא הֶחֱזִיק בַּאֲוִיר הֶחָצֵר וְכָל עֵת שֶׁיִּרְצֶה בַּעַל הֶחָצֵר לִבְנוֹת תַּחְתָּיו וּלְבַטֵּל תַּשְׁמִישׁוֹ שֶׁל זִיז אֵין בַּעַל הַזִּיז יָכוֹל לְעַכֵּב עָלָיו:","הָיָה הַזִּיז שֶׁהוֹצִיא רָחְבּוֹ טֶפַח וּמָשׁוּךְ בַּאֲוִיר חֲצֵרוֹ שֶׁל חֲבֵרוֹ אַרְבָּעָה טְפָחִים וְלֹא מִחָה בּוֹ הֶחֱזִיק בּוֹ בְּאַרְבָּעָה עַל אַרְבָּעָה וְאִם רָצָה לְהַרְחִיב אֶת הַזִּיז עַד שֶׁיַּעֲשֶׂה אַרְבָּעָה עַל אַרְבָּעָה הֲרֵי זֶה מַרְחִיב וְאֵין בַּעַל הֶחָצֵר יָכוֹל לִבְנוֹת בַּאֲוִיר חֲצֵרוֹ תַּחַת הַזִּיז כְּלוּם אֶלָּא אִם כֵּן הִנִּיחַ לוֹ תַּחְתָּיו גֹּבַהּ אֲוִיר עֲשָׂרָה טְפָחִים כְּדֵי שֶׁיִּשְׁתַּמֵּשׁ בַּזִּיז:","הַמַּעֲמִיד סֻלָּם קָטָן שֶׁאֵין לוֹ אַרְבָּעָה חַוָּקִין בְּצַד כָּתְלוֹ בְּתוֹךְ חָצֵר שֶׁל חֲבֵרוֹ אוֹ בְּתוֹךְ שָׂדֵהוּ לֹא הֶחֱזִיק בְּנֵזֶק זֶה וְכָל זְמַן שֶׁיִּרְצֶה בַּעַל הֶחָצֵר בּוֹנֶה בְּצַד סֻלָּם וּמְבַטֵּל תַּשְׁמִישׁוֹ. וְאִם הָיָה סֻלָּם גָּדוֹל שֶׁיֵּשׁ לוֹ אַרְבָּעָה חַוָּקִין אוֹ יָתֵר הֶחֱזִיק וְאִם בָּא לִבְנוֹת וּלְבַטְּלוֹ בַּעַל הַסֻּלָּם מְעַכֵּב עָלָיו עַד שֶׁיַּרְחִיק כַּשִּׁעוּר שֶׁהֲרֵי מָחַל לוֹ לְהַעֲמִיד סֻלָּם גָּדוֹל. לְפִיכָךְ כְּשֶׁיָּבוֹא בַּעַל הַגַּג לְהַעֲמִיד סֻלָּם גָּדוֹל בַּעַל הֶחָצֵר יָכוֹל לִמְחוֹת כְּדֵי שֶׁלֹּא יַחֲזִיק עָלָיו. אֲבָל אִם הֶעֱמִיד סֻלָּם קָטָן אֵינוֹ יָכוֹל לְמָנְעוֹ שֶׁהֲרֵי אוֹמְרִין לוֹ אֵין עָלֶיךָ הֶפְסֵד בָּזֶה כָּל זְמַן שֶׁתִּרְצֶה תִּטְּלֶנּוּ:","הָרוֹצֶה לְהוֹצִיא צִנּוֹר עַל חֲצַר חֲבֵרוֹ כְּדֵי שֶׁיְּקַלֵּחַ שָׁם הַמַּיִם. אוֹ שֶׁעָשָׂה מַזְחֵילָה עַל כָּתְלוֹ כְּדֵי שֶׁיִּהְיוּ הַמַּיִם נִזְחָלִין וְיוֹרְדִין לַחֲצַר חֲבֵרוֹ. בַּעַל הֶחָצֵר מְעַכֵּב עָלָיו. וְאִם לֹא מִחָה בּוֹ הֶחֱזִיק זֶה בַּצִּנּוֹר. רָצָה אַחַר כָּךְ לִסְתֹּם הַצִּנּוֹר בַּעַל הֶחָצֵר מְעַכֵּב עָלָיו. שֶׁכְּשֵׁם שֶׁהֶחְזִיק בַּעַל הַגַּג לִשְׁפֹּךְ מֵימָיו לַחֲצַר חֲבֵרוֹ כָּךְ הֶחֱזִיק בַּעַל הֶחָצֵר שֶׁיִּהְיוּ מֵימֵי גַּגּוֹ שֶׁל חֲבֵרוֹ בָּאִין אֶצְלוֹ לִרְשׁוּתוֹ. רָצָה בַּעַל הַגַּג לַעֲקֹר הַצִּנּוֹר מִצַּד זֶה וּלְהַחְזִירוֹ בְּצַד אַחֵר אוֹ שֶׁהָיָה אָרֹךְ וְרָצָה לְקַצְּרוֹ אֵין בַּעַל הֶחָצֵר יָכוֹל לְעַכֵּב עָלָיו שֶׁלֹּא הֶחֱזִיק אֶלָּא בְּמֵימֵי הַגַּג וַהֲרֵי הֵם בָּאִים אֶצְלוֹ מִכָּל מָקוֹם. וְכֵן אִם רָצָה בַּעַל הֶחָצֵר לִבְנוֹת תַּחַת הַצִּנּוֹר אֵין בַּעַל הַגַּג יָכוֹל לְעַכֵּב עָלָיו שֶׁאֵין הַצִּנּוֹר עָשׂוּי לְתַשְׁמִישׁ כְּזִיז כְּדֵי שֶׁיַּחְזִיק בַּאֲוִיר הֶחָצֵר. שֶׁאֵינוֹ עָשׂוּי אֶלָּא לְקִלּוּחַ הַמַּיִם:","מִי שֶׁהוֹרִיד מֵי גַּגּוֹ עַל חֲצַר חֲבֵרוֹ וְלֹא מִחָה בּוֹ וְהֶחֱזִיק בְּדָבָר זֶה. אִם הַמַּיִם מְנַטְּפִין וְרָצָה לְקַבְּצָם לְמָקוֹם אֶחָד וְלַעֲשׂוֹתָם צִנּוֹר עוֹשֶׂה. וְכֵן אִם הָיוּ בָּאִין דֶּרֶךְ צִנּוֹר מִמָּקוֹם אַחֵר וְחִלְּקָן עַל רֹחַב הַכֹּתֶל וְהֶחֱזִירָן נוֹטְפִין עוֹשֶׂה. וַאֲפִלּוּ לִבְנוֹת עַל גַּגּוֹ כְּמִין צְרִיף עַד שֶׁיֵּרְדוּ הַמַּיִם בִּמְהֵרָה לַחֲצַר חֲבֵרוֹ בּוֹנֶה שֶׁהֲרֵי הֻחְזְקוּ מֵימָיו שֶׁל זֶה לֵירֵד לַחֲצַר חֲבֵרוֹ:","כֹּתֶל שֶׁבֵּין רְאוּבֵן וְשִׁמְעוֹן אִם הָיוּ שֻׁתָּפִין בּוֹ שְׁנֵיהֶם מִשְׁתַּמְּשִׁין בּוֹ זֶה חוֹפֵר מִצַּד זֶה וּמַכְנִיס קוֹרוֹתָיו כָּל שֶׁהֵן. וְזֶה חוֹפֵר מִצַּד זֶה וּמַכְנִיס קוֹרוֹתָיו. הָיָה הַכֹּתֶל שֶׁל רְאוּבֵן לְבַדּוֹ אֵין שִׁמְעוֹן יָכוֹל לְהִשְׁתַּמֵּשׁ בּוֹ. חָפַר שִׁמְעוֹן בְּכֹתֶל זֶה וְהִכְנִיס בָּהּ קוֹרָה אַחַת וְשָׁתַק רְאוּבֵן וְלֹא מִחָה בּוֹ הֶחֱזִיק בִּמְקוֹם הַקּוֹרָה. אֲפִלּוּ הָיְתָה קְטַנָּה וְרָצָה שִׁמְעוֹן לְהַחְלִיפָהּ בְּקוֹרָה גְּדוֹלָה וְעָבָה מַחְלִיף. הָיְתָה הַקּוֹרָה סֻכַּת עַרְאַי כָּל שְׁלֹשִׁים יוֹם לֹא הֶחֱזִיק בָּהּ סְתָם שֶׁהֲרֵי רְאוּבֵן אוֹמֵר לֹא מָחַלְתִּי וְהִנַּחְתִּיךָ אֶלָּא מִפְּנֵי שֶׁהוּא עַרְאַי. לְאַחַר שְׁלֹשִׁים יוֹם הֶחֱזִיק שֶׁאֵין זֶה עַרְאַי. וְאִם סֻכַּת יְמֵי הֶחָג הִיא כָּל שִׁבְעַת יְמֵי הֶחָג לֹא הֶחֱזִיק לְאַחַר שִׁבְעָה הֶחֱזִיק. וְאִם חִבֵּר רֹאשׁ הַקּוֹרָה בַּכֹּתֶל בְּטִיט מִיָּד הֶחֱזִיק וְהוּא שֶׁיָּבִיא רְאָיָה שֶׁרְאוּבֵן סִיֵּעַ עִמּוֹ אוֹ רָאָה וְלֹא מִחָה:","מִי שֶׁהֶחְזִיק בְּכֹתֶל זֶה בְּקוֹרָה אַחַת אֵינוֹ יָכוֹל לְהַחֲזִיק בְּקוֹרָה שְׁנִיָּה שֶׁהֲרֵי לֹא מָחַל לוֹ אֶלָּא עַל הָאַחַת. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהוֹדָה שֶׁאֵין הַכֹּתֶל זֶה שֶׁלּוֹ אֶלָּא חֲבֵרוֹ מָחַל לוֹ עַל הַכְנָסַת קוֹרָה זוֹ. אֲבָל אִם טָעַן שֶׁכֹּתֶל זֶה שֻׁתָּף אֲנִי בּוֹ הוֹאִיל וְהִשְׁתַּמֵּשׁ בָּהּ בְּקוֹרָה אַחַת נֶאֱמָן וּמִשְׁתַּמֵּשׁ בְּכֻלָּן אַחַר שֶׁיִּשָּׁבַע שְׁבוּעַת הֶסֵּת שֶׁהוּא שֻׁתָּף בְּכָל הַכֹּתֶל:","הָיוּ קוֹרוֹתָיו שֶׁל רְאוּבֵן בְּתוֹךְ הַכֹּתֶל וּבְצַד שִׁמְעוֹן מְקוֹמוֹת חֲפוּרִין לְהַכְנִיס בָּהֶן רָאשֵׁי הַקּוֹרוֹת לֹא הֶחֱזִיק בָּהֶן שִׁמְעוֹן לְהַכְנִיס בָּהּ קוֹרוֹת וְאֵינוֹ יָכוֹל לִטְעֹן שֶׁהוּא שֻׁתָּף בּוֹ שֶׁהֲרֵי אֵין לוֹ בּוֹ תַּשְׁמִישׁ וְיָכוֹל רְאוּבֵן לִטְעֹן שֶׁאֲנִי חָפַרְתִּי מְקוֹמוֹת אֵלּוּ בְּצִדְּךָ כְּדֵי שֶׁיִּהְיוּ מוּכָנִים עַד שֶׁתִּקְנֶה מִמֶּנִּי אוֹ שֶׁתְּבַקֵּשׁ מִמֶּנִּי וְאֶמְחל לְךָ וְתַכְנִיס הַקּוֹרוֹת בְּלֹא חֲפִירָה בַּכֹּתֶל כְּדֵי שֶׁלֹּא יִתְמַטְמֵט כָּתְלִי בְּעֵת חֲפִירָה:"],"Mishneh Torah, Oaths 8":["הַגּוֹנֵּב שׁוֹרוֹ שֶׁל חֲבֵרוֹ וּטְבָחוֹ אוֹ מְכָרוֹ. תְּבָעוֹ בַּעַל הַשּׁוֹר וְאָמַר לוֹ גָנַבְתָּ שׁוֹרִי וְטָבַחְתָּ אוֹ מָכַרְתָּ וְהוּא אוֹמֵר גָּנַבְתִּי אֲבָל לֹא טָבַחְתִּי וְלֹא מָכַרְתִּי וְנִשְׁבַּע הֲרֵי זֶה פָּטוּר מִשְּׁבוּעַת הַפִּקָּדוֹן. שֶׁאִלּוּ הוֹדָה מֵעַצְמוֹ שֶׁטָּבַח אוֹ מָכַר לֹא הָיָה מְשַׁלֵּם תַּשְׁלוּמֵי אַרְבָּעָה וַחֲמִשָּׁה מִפְּנֵי שֶׁהוּא קְנָס כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת גְּנֵבָה. וְנִמְצָא זֶה כְּמוֹ שֶׁלֹּא כָּפַר מָמוֹן וּלְפִיכָךְ פָּטוּר מִשְּׁבוּעַת הַפִּקָּדוֹן וְחַיָּב בִּשְׁבוּעַת בִּטּוּי שֶׁהֲרֵי נִשְׁבַּע עַל שֶׁקֶר שֶׁלֹּא טָבַח וְהוּא טָבַח:","וְכֵן הָאוֹמֵר לַחֲבֵרוֹ הֵמִית שׁוֹרְךָ אֶת עַבְדִּי וְכָפַר וְנִשְׁבַּע וְהָעֶבֶד שֶׁתָּבַע רַבּוֹ וְאָמַר הִפַּלְתָּ שִׁנִּי וְסִמֵּיתָ עֵינִי וְכָפַר וְנִשְׁבַּע פָּטוּר מִשְּׁבוּעַת הַפִּקָּדוֹן. שֶׁאִלּוּ הוֹדָה לֹא הָיָה מְשַׁלֵּם מִפְּנֵי שֶׁהוּא קְנָס. אֲבָל חַיָּב בִּשְׁבוּעַת בִּטּוּי. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַתּוֹבֵעַ אֶת חֲבֵרוֹ בְּדָבָר שֶׁיֵּשׁ בּוֹ קְנָס שֶׁאֵינוֹ מְשַׁלֵּם אוֹתוֹ עַל פִּי עַצְמוֹ כְּמוֹ שֶׁבֵּאַרְנוּ. וְיֵשׁ בּוֹ מָמוֹן שֶׁהוּא מְשַׁלֵּם אוֹתוֹ עַל פִּי עַצְמוֹ. וְכָפַר בְּכָל דָּבָר וְנִשְׁבַּע הֲרֵי זֶה חַיָּב מִשּׁוּם שְׁבוּעַת הַפִּקָּדוֹן. כֵּיצַד. תְּבָעוֹ וְאָמַר לוֹ אָנַסְתָּ אוֹ פִּתִּיתָ בִּתִּי וְהוּא אָמַר לֹא אָנַסְתִּי וְלֹא פִּתֵּיתִי וְנִשְׁבַּע חַיָּב בִּשְׁבוּעַת הַפִּקָּדוֹן. שֶׁאַף עַל פִּי שֶׁאֵינוֹ מְשַׁלֵּם קְנָס עַל פִּי עַצְמוֹ אִלּוּ הוֹדָה הָיָה מְשַׁלֵּם בּשֶׁת וּפְגַם עַל פִּי עַצְמוֹ. וְכֵן הָאוֹמֵר לַחֲבֵרוֹ גָּנַבְתָּ שׁוֹרִי וְהוּא אוֹמֵר לֹא גָּנַבְתִּי וְנִשְׁבַּע חַיָּב בִּשְׁבוּעַת הַפִּקָּדוֹן שֶׁאַף עַל פִּי שֶׁאֵינוֹ מְשַׁלֵּם כֶּפֶל בְּהוֹדָאָתוֹ מְשַׁלֵּם הוּא אֶת הַקֶּרֶן בְּהוֹדָאָתוֹ:","הָאוֹמֵר לַחֲבֵרוֹ עָשִׂיתָ בִּי חַבּוּרָה וְהוּא אוֹמֵר לֹא עָשִׂיתִי. הֵמִית שׁוֹרְךָ אֶת שׁוֹרִי וְהוּא אוֹמֵר לֹא הֵמִית וְנִשְׁבַּע חַיָּב בִּשְׁבוּעַת הַפִּקָּדוֹן שֶׁאִלּוּ הוֹדָה הָיָה חַיָּב לְשַׁלֵּם:","נָתַן שׁוֹרוֹ לְשׁוֹמֵר חִנָּם וּמֵת הַשּׁוֹר. תְּבָעוֹ וְאָמַר לוֹ הֵיכָן שׁוֹרִי שֶׁהִפְקַדְתִּי אֶצְלְךָ אָמַר לוֹ לֹא הִפְקַדְתָּ אֶצְלִי כְּלוּם אוֹ שֶׁאָמַר לוֹ הִפְקַדְתָּ וְנִגְנַב אוֹ אָבַד וְנִשְׁבַּע הֲרֵי זֶה פָּטוּר מִשְּׁבוּעַת הַפִּקָּדוֹן. שֶׁאִלּוּ הוֹדָה וְאָמַר הַדָּבָר כְּשֶׁהָיָה לֹא הָיָה חַיָּב לְשַׁלֵּם מָמוֹן מִפְּנֵי שֶׁהוּא שׁוֹמֵר חִנָּם. אֲבָל חַיָּב הוּא מִשּׁוּם שְׁבוּעַת בִּטּוּי שֶׁהֲרֵי נִשְׁבַּע עַל שֶׁקֶר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הִשְׁאִיל שׁוֹרוֹ לַחֲבֵרוֹ וּתְבָעוֹ וְאָמַר לוֹ הֵיכָן שׁוֹרִי שֶׁשָּׁאַלְתָּ מִמֶּנִּי וַהֲרֵי הַשּׁוֹר מֵת. וְאָמַר לוֹ הַשּׁוֹאֵל נִגְנַב אוֹ אָבַד וְנִשְׁבַּע עַל זֶה הֲרֵי זֶה פָּטוּר מִשְּׁבוּעַת הַפִּקָּדוֹן. שֶׁהֲרֵי לֹא פָּטַר עַצְמוֹ מִן הַתַּשְׁלוּמִין בִּכְפִירָתוֹ. וּמִכָּל מָקוֹם חַיָּב הוּא לְשַׁלֵּם בֵּין מֵת אוֹ נִגְנַב אוֹ אָבַד אוֹ נִשְׁבָּה מִפְּנֵי שֶׁהוּא שׁוֹאֵל כְּמוֹ שֶׁיִּתְבָּאֵר בִּמְקוֹמוֹ. אֲבָל חַיָּב הוּא מִשּׁוּם שְׁבוּעַת בִּטּוּי שֶׁהֲרֵי נִשְׁבַּע עַל שֶׁקֶר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","זֶה הַכְּלָל כָּל שֶׁאֵינוֹ פּוֹטֵר עַצְמוֹ מִן הַתַּשְׁלוּמִין אֶלָּא בִּכְפִירָה זוֹ וְנִשְׁבַּע בֵּין מִפִּי עַצְמוֹ בֵּין שֶׁהִשְׁבִּיעוֹ הַתּוֹבֵעַ וְכָפַר הֲרֵי זֶה חַיָּב בִּשְׁבוּעַת הַפִּקָּדוֹן אַף עַל פִּי שֶׁלֹּא עָנָה אָמֵן וְלֹא הוֹצִיא שְׁבוּעָה מִפִּיו:","הַגּוֹנֵב שׁוֹר חֲבֵרוֹ וּתְבָעוֹ וְאָמַר לוֹ שׁוֹרִי גָּנַבְתָּ וְהוּא אוֹמֵר לֹא גָּנַבְתִּי. מַה טִּיבוֹ אֶצְלְךָ אַתָּה הִפְקַדְתּוֹ אֶצְלִי וְנִשְׁבַּע. חַיָּב בִּשְׁבוּעַת הַפִּקָּדוֹן. שֶׁאִלּוּ הוֹדָה שֶׁגְּנָבוֹ הָיָה חַיָּב לְשַׁלֵּם דְּמֵי הַשּׁוֹר מִכָּל מָקוֹם וְעַכְשָׁו שֶׁאָמַר פִּקָּדוֹן הוּא הֲרֵי פָּטַר עַצְמוֹ בִּכְפִירָה זוֹ מִן הַגְּנֵבָה וּמִן הָאֲבֵדָה שֶׁאִם נִגְנַב הַשּׁוֹר אוֹ אָבַד אַחַר הוֹדָאָה זוֹ הָיָה פָּטוּר מִלְּשַׁלֵּם:","וְכֵן אִם טָעַן שֶׁשְּׂכָרוֹ וְנִשְׁבַּע חַיָּב בִּשְׁבוּעַת הַפִּקָּדוֹן שֶׁהֲרֵי פָּטַר עַצְמוֹ מִן הַשְּׁבוּרָה וּמִן הַמִּיתָה. וְכֵן אִם טָעַן וְאָמַר הִשְׁאַלְתּוֹ לִי וְנִשְׁבַּע חַיָּב בִּשְׁבוּעַת הַפִּקָּדוֹן שֶׁהֲרֵי פָּטַר עַצְמוֹ מִן הַמִּיתָה בִּשְׁעַת הַמְּלָאכָה כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת הַשְּׁאֵלָה:","לְפִיכָךְ אִם אָמַר לֹא גָּנַבְתִּי אֲבָל אַתָּה הִפְקַדְתּוֹ אֶצְלִי אוֹ שְׂכַרְתַּנִי לְשָׁמְרוֹ אוֹ הִשְׁאַלְתִּיהוּ לִי וַהֲרֵי שׁוֹרְךָ לְפָנֶיךָ קָחֵהוּ וְנִשְׁבַּע עַל זֶה הֲרֵי זֶה פָּטוּר מִשְּׁבוּעַת הַפִּקָּדוֹן. שֶׁהֲרֵי הוֹדָה בַּקֶּרֶן וְלֹא פָּטַר עַצְמוֹ בִּכְפִירָה זוֹ מִכְּלוּם:","וְכֵן אִם אָמַר לוֹ אַתָּה מְכַרְתּוֹ לִי וַעֲדַיִן לֹא נָתַתִּי דָּמָיו אִם תִּרְצֶה קַח דָּמָיו אוֹ הֲרֵי שֶׁלְּךָ לְפָנֶיךָ. אוֹ שֶׁאָמַר לוֹ אַתָּה נְתַתּוֹ לִי בִּשְׂכַר מְלָאכָה שֶׁאֶעֱשֶׂה לְךָ אִם תִּרְצֶה שֶׁאֶעֱשֶׂה לְךָ אוֹ קָחֶנּוּ וָלֵךְ. תּוֹעֶה בַּדֶּרֶךְ מְצָאתִיו וְלֹא יָדַעְתִּי שֶׁהוּא שֶׁלְּךָ עַכְשָׁו שֶׁיָּדַעְתִּי קָחֶנּוּ וָלֵךְ. אוֹ שֶׁאָמַר אַחַר פָּרָתִי רָץ וַהֲרֵי הוּא לְפָנֶיךָ. וְנִשְׁבַּע עַל כָּל טַעֲנָה מֵאֵלּוּ פָּטוּר מִשְּׁבוּעַת הַפִּקָּדוֹן שֶׁהֲרֵי לֹא פָּטַר עַצְמוֹ מִכְּלוּם. וְחַיָּב בִּשְׁבוּעַת בִּטּוּי שֶׁהֲרֵי נִשְׁבַּע עַל שֶׁקֶר:","מִי שֶׁהָיָה חַיָּב מָמוֹן לִשְׁנֵי שֻׁתָּפִין וּתְבָעוֹ אֶחָד מֵהֶן וְכָפַר בּוֹ וְנִשְׁבַּע חַיָּב בִּשְׁבוּעַת הַפִּקָּדוֹן שֶׁהֲרֵי כָּפַר מָמוֹן. תְּבָעוּהוּ שְׁנֵיהֶם וְהוֹדָה בַּכּל לְאֶחָד מֵהֶם וְאָמַר לֹא לָוִיתִי אֶלָּא מִזֶּה לְבַדּוֹ וְנִשְׁבַּע פָּטוּר מִשְּׁבוּעַת הַפִּקָּדוֹן שֶׁהֲרֵי לֹא פָּטַר עַצְמוֹ מִכְּלוּם. אֲבָל חַיָּב בִּשְׁבוּעַת בִּטּוּי:","וְכֵן מִי שֶׁהָיְתָה עָלָיו מִלְוֶה בִּשְׁטָר וְכָפַר בָּהּ וְנִשְׁבַּע פָּטוּר מִשְּׁבוּעַת הַפִּקָּדוֹן. שֶׁהֲרֵי בִּשְׁטָר נִשְׁתַּעְבֵּד הַקַּרְקַע וְנִמְצָא זֶה כְּכוֹפֵר בְּקַרְקַע. וּכְבָר בֵּאַרְנוּ שֶׁהַכּוֹפֵר בְּקַרְקַע פָּטוּר מִשְּׁבוּעַת הַפִּקָּדוֹן וְחַיָּב בִּשְׁבוּעַת בִּטּוּי שֶׁהֲרֵי נִשְׁבַּע עַל שֶׁקֶר:","הָיְתָה עָלָיו מִלְוֶה בְּעֵדִים בִּלְבַד וְכָפַר וְנִשְׁבַּע חַיָּב בִּשְׁבוּעַת הַפִּקָּדוֹן שֶׁהֲרֵי פָּטַר עַצְמוֹ בִּכְפִירָתוֹ מִלְּשַׁלֵּם עַתָּה. וְאַף עַל פִּי שֶׁכְּשֶׁיָּבוֹאוּ הָעֵדִים יִתְחַיֵּב לְשַׁלֵּם וְנִמְצָא שֶׁלֹּא הוֹעִילָה לוֹ כְּפִירָתוֹ. הֲרֵי הוֹעִילָה בְּעִתָּהּ וְשֶׁמָּא לֹא יָבוֹאוּ הָעֵדִים אוֹ יָבוֹאוּ וְלֹא תִּתְקַיֵּם עֵדוּתָן אוֹ יִפָּסְלוּ וּלְפִיכָךְ חַיָּב:"],"Mishneh Torah, Offerings for Unintentional Transgressions 14":["בֵית דִּין שֶׁשָּׁגְגוּ וְהוֹרוּ לַעֲקֹר גּוּף מִגּוּפֵי תּוֹרָה וְעָשׂוּ כָּל הָעָם עַל פִּיהֶם בֵּית דִּין פְּטוּרִין וְכָל אֶחָד וְאֶחָד מִן הָעוֹשִׂים חַיָּב חַטָּאת קְבוּעָה שֶׁנֶּאֱמַר (ויקרא ד יג) \"וְנֶעְלַם דָּבָר\" וְלֹא כָּל הַגּוּף:","לְעוֹלָם אֵין בֵּית דִּין חַיָּבִין עַד שֶׁיּוֹרוּ לְבַטֵּל מִקְצָת וּלְקַיֵּם מִקְצָת בִּדְבָרִים שֶׁאֵינָן מְפֹרָשִׁין בַּתּוֹרָה וּמְבֹאָרִים וְאַחַר כָּךְ יִהְיוּ בֵּית דִּין חַיָּבִין בְּקָרְבָּן וְהָעוֹשִׂים עַל פִּיהֶם פְּטוּרִין. כֵּיצַד. שָׁגְגוּ וְהוֹרוּ שֶׁמֻּתָּר לְהִשְׁתַּחֲווֹת לַעֲבוֹדָה זָרָה. אוֹ שֶׁמֻּתָּר לְהוֹצִיא מֵרְשׁוּת לִרְשׁוּת בְּשַׁבָּת. אוֹ שֶׁמֻּתָּר לָבוֹא עַל שׁוֹמֶרֶת יוֹם כְּנֶגֶד יוֹם. הֲרֵי אֵלּוּ כְּמִי שֶׁאָמְרוּ אֵין שַׁבָּת בַּתּוֹרָה אוֹ אֵין עֲבוֹדָה זָרָה בַּתּוֹרָה אוֹ אֵין נִדָּה בַּתּוֹרָה שֶׁעָקְרוּ כָּל הַגּוּף וְאֵין זוֹ וְכַיּוֹצֵא בָּזֶה שִׁגְגַת הוֹרָאָה אֶלָּא שִׁכְחָה. לְפִיכָךְ פְּטוּרִין מִן הַקָּרְבָּן וְכָל הָעוֹשֶׂה עַל פִּיהֶן חַיָּב חַטָּאת בִּפְנֵי עַצְמוֹ. אֲבָל אִם טָעוּ וְהוֹרוּ וְאָמְרוּ הַמּוֹצִיא מֵרְשׁוּת לִרְשׁוּת הוּא שֶׁחָיַּב שֶׁנֶּאֱמַר (שמות טז כט) \"אַל יֵצֵא אִישׁ מִמְּקֹמוֹ\" אֲבָל הַזּוֹרֵק אוֹ הַמּוֹשִׁיט מֻתָּר. אוֹ שֶׁעָקְרוּ אָב מֵאֲבוֹת מְלָאכוֹת וְהוֹרוּ שֶׁאֵינָהּ מְלָאכָה. הֲרֵי אֵלּוּ חַיָּבִין. וְכֵן אִם טָעוּ וְאָמְרוּ הַמִּשְׁתַּחֲוֶה לַעֲבוֹדָה זָרָה בְּפִשּׁוּט יָדַיִם וְרַגְלַיִם הוּא הַחַיָּב שֶׁנֶּאֱמַר בּוֹ (שמות לד יד) \"לֹא תִשְׁתַּחֲוֶה לְאֵל אַחֵר\" אֲבָל הַכּוֹרֵעַ עַל הָאָרֶץ וְלֹא פָּשַׁט יָדָיו וְרַגְלָיו הֲרֵי הוּא מֻתָּר הֲרֵי אֵלּוּ חַיָּבִין. וְכֵן אִם טָעוּ וְאָמְרוּ הַבָּא עַל שׁוֹמֶרֶת יוֹם כְּנֶגֶד יוֹם שֶׁרָאֲתָה דָּם בַּיּוֹם הוּא חַיָּב שֶׁנֶּאֱמַר (ויקרא טו כו) \"כָּל יְמֵי זוֹבָהּ\" אֲבָל רָאֲתָה בַּלַּיְלָה מֻתָּר לָבוֹא עָלֶיהָ. וְכֵן אִם הוֹרוּ וְאָמְרוּ שֶׁמִּי שֶׁפֵּרְשָׂה אִשְׁתּוֹ נִדָּה בִּשְׁעַת תַּשְׁמִישׁ מֻתָּר לִפְרשׁ מִמֶּנָּה כְּשֶׁהוּא מִתְקַשֶּׁה. הֲרֵי אֵלּוּ חַיָּבִין. וְכֵן אִם טָעוּ וְאָמְרוּ שֶׁהָאוֹכֵל דָּם שֶׁיָּצָא בִּשְׁעַת שְׁחִיטָה הוּא הַחַיָּב אֲבָל הָאוֹכֵל דַּם הַלֵּב מֻתָּר הֲרֵי אֵלּוּ חַיָּבִים. וְכֵן כָּל כַּיּוֹצֵא בְּטָעֵיּוֹת אֵלּוּ אִם הוֹרוּ בָּהֶן וְעָשׂוּ רֹב הַקָּהָל עַל פִּיהֶן פְּטוּרִין וּבֵית דִּין מְבִיאִין קָרְבָּן עַל שִׁגְגָתָן:","הוֹרוּ בֵּית דִּין שֶׁיָּצָא הַשַּׁבָּת לְפִי שֶׁנִּתְכַּסֵּית הַחַמָּה וְדִמּוּ שֶׁשָּׁקְעָה חַמָּה וְאַחַר כָּךְ זָרְחָה אֵין זוֹ הוֹרָאָה אֶלָּא טָעוּת וְכָל שֶׁעָשָׂה מְלָאכָה חַיָּב אֲבָל בֵּית דִּין פְּטוּרִין. וְכֵן אִם הִתִּירוּ בֵּית דִּין אֵשֶׁת אִישׁ לְהִנָּשֵׂא לְפִי שֶׁהֵעִידוּ בִּפְנֵיהֶם שֶׁמֵּת בַּעְלָהּ וְאַחַר כָּךְ בָּא בַּעְלָהּ אֵין זוֹ הוֹרָאָה אֶלָּא טָעוּת וְהָאִשָּׁה וּבַעְלָהּ הָאַחֲרוֹן חַיָּבִין חַטָּאת עַל שִׁגְגָתָן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","בֵּית דִּין שֶׁהוֹרוּ בִּשְׁגָגָה וְשָׁכְחוּ עַצְמוֹ שֶׁל חֵטְא שֶׁהוֹרוּ בּוֹ. אַף עַל פִּי שֶׁהֵן יוֹדְעִים בְּוַדַּאי שֶׁחָטְאוּ בִּשְׁגָגָה וְאַף עַל פִּי שֶׁהָעָם מוֹדִיעִין אוֹתָן וְאוֹמְרִים לָהֶן בְּכָךְ וְכָךְ הוֹרֵיתֶם לָנוּ. הֵם פְּטוּרִין וְהָעוֹשִׂים עַל פִּיהֶם חַיָּבִין בִּפְנֵי עַצְמָן. שֶׁנֶּאֱמַר (ויקרא ד יד) \"וְנוֹדְעָה הַחַטָּאת אֲשֶׁר חָטְאוּ עָלֶיהָ\" לֹא שֶׁיּוֹדִיעוּ אוֹתוֹ הַחוֹטְאִים. כֵּיצַד. שָׁגְגוּ וְהִתִּירוּ חֵלֶב שֶׁעַל גַּבֵּי הַקֵּבָה וַאֲכָלוּהוּ רֹב הָעָם וְאַחַר שֶׁיָּדְעוּ שֶׁשָּׁגוּ בְּהוֹרָאָה וְשֶׁהִתִּירוּ דָּבָר שֶׁחַיָּבִים עַל זְדוֹנוֹ כָּרֵת וְעַל שִׁגְגָתוֹ חַטָּאת קְבוּעָה נִסְתַּפֵּק לָהֶם אִם מִקְצָת הַחֲלָבִים הִתִּירוּ אוֹ מִקְצָת הַדָּמִים הִתִּירוּ הֲרֵי אֵלּוּ פְּטוּרִין וְכָל מִי שֶׁאָכַל מֵבִיא חַטָּאת קְבוּעָה:","בֵּית דִּין שֶׁהוֹרוּ בִּשְׁגָגָה וְנוֹדְעָה לָהֶם שִׁגְגָתָן בֵּין שֶׁהֵבִיאוּ כַּפָּרָתָן בֵּין שֶׁלֹּא הֵבִיאוּ כָּל הָעוֹשֶׂה כְּפִי הוֹרָאָתָן שֶׁפָּשְׁטָה בְּרֹב הַצִּבּוּר מֵאַחַר שֶׁיָּדְעוּ הֲרֵי זֶה מֵבִיא אָשָׁם תָּלוּי. הוֹאִיל וְהָיָה לוֹ לִשְׁאל בְּכָל עֵת עַל דְּבָרִים שֶׁנִּתְחַדְּשׁוּ בְּבֵית דִּין וְלֹא שָׁאַל הֲרֵי זֶה כְּמִי שֶׁנִּסְתַּפֵּק לוֹ אִם חָטָא אוֹ לֹא חָטָא. בַּמֶּה דְּבָרִים אֲמוּרִים בְּמִי שֶׁהָיָה עִם בֵּית דִּין בַּמְּדִינָה. אֲבָל מִי שֶׁרָאָה הַהוֹרָאָה וְהָלַךְ לִמְדִינָה אַחֶרֶת אַף עַל פִּי שֶׁעָשָׂה אַחַר שֶׁיָּדְעוּ פָּטוּר מִפְּנֵי שֶׁתָּלָה בָּהֶן וַהֲרֵי אִי אֶפְשָׁר לוֹ לִשְׁאל. וְלֹא עוֹד אֶלָּא הַנִּבְהָל לָצֵאת אַף עַל פִּי שֶׁעֲדַיִן לֹא יָצָא לַדֶּרֶךְ וְעָשָׂה עַל פִּיהֶם מֵאַחַר שֶׁיָּדְעוּ הֲרֵי זֶה פָּטוּר:"],"Mishneh Torah, One Who Injures a Person or Property 3":["כֵּיצַד מְשַׁעֲרִין הַבּשֶׁת. הַכּל לְפִי הַמְבַיֵּשׁ וְהַמִּתְבַּיֵּשׁ. אֵינוֹ דּוֹמֶה מִתְבַּיֵּשׁ מִן הַקָּטָן לְמִתְבַּיֵּשׁ מֵאָדָם גָּדוֹל וּמְכֻבָּד שֶׁזֶּה שֶׁבִּיְּשׁוֹ זֶה הַקַּל בָּשְׁתּוֹ מְרֻבָּה:","הַמְבַיֵּשׁ אֶת הֶעָרֹם אוֹ מִי שֶׁהוּא בְּמֶרְחָץ פָּטוּר. נָשְׁבָה הָרוּחַ וְהָפְכָה שׁוּלָיו עַל פָּנָיו וַהֲרֵי הוּא עָרֹם וְהוֹסִיף זֶה בְּהַפְשָׁטָתוֹ חַיָּב בְּבֹשֶׁת. וְאֵינוֹ דּוֹמֶה מְבַיֵּשׁ אֶת זֶה שֶׁנַּעֲשָׂה עָרֹם לִמְבַיֵּשׁ אֶת שֶׁאֵינוֹ עָרֹם. וְכֵן אִם הִגְבִּיהַּ בְּגָדָיו לֵירֵד לַנָּהָר אוֹ שֶׁעָלָה מִן הַנָּהָר וּבִיְּשׁוֹ חַיָּב. וְאֵינוֹ דּוֹמֶה מְבַיֵּשׁ זֶה לִמְבַיֵּשׁ אֶת הַמְכֻסֶּה בִּבְגָדָיו:","הַמְבַיֵּשׁ אֶת הַיָּשֵׁן חַיָּב בְּבשֶׁת. וְאִם מֵת בְּתוֹךְ שְׁנָתוֹ וְלֹא הֵקִיץ וְלֹא הִרְגִּישׁ בָּזֶה שֶׁבִּיְּשׁוֹ אֵין גּוֹבִין בּשֶׁת זֶה מִן הַמְבַיֵּשׁ. וְאִם תָּפְשׂוּ הַיּוֹרְשִׁין אֵין מוֹצִיאִין מִיָּדָן:","הַמְבַיֵּשׁ אֶת הַשּׁוֹטֶה פָּטוּר. וְהַמְבַיֵּשׁ אֶת הַחֵרֵשׁ חַיָּב. הַמְבַיֵּשׁ אֶת הַגֵּר אוֹ אֶת הָעֶבֶד חַיָּב. הַמְבַיֵּשׁ אֶת הַקָּטָן אִם כְּשֶׁמַּכְלִימִין אוֹתוֹ נִכְלָם חַיָּב וְאִם לָאו פָּטוּר. וּמִכָּל מָקוֹם אֵינוֹ דּוֹמֶה הַמְבַיֵּשׁ אֶת הַקָּטָן לִמְבַיֵּשׁ אֶת הַגָּדוֹל. וְלֹא הַמְבַיֵּשׁ אֶת הָעֶבֶד לִמְבַיֵּשׁ אֶת בֶּן חוֹרִין. וְלֹא מְבַיֵּשׁ חֵרֵשׁ לִמְבַיֵּשׁ פִּקֵּחַ:","הַמְבַיֵּשׁ אֶת חֲבֵרוֹ בִּדְבָרִים אוֹ שֶׁרָקַק עַל בְּגָדָיו פָּטוּר מִן הַתַּשְׁלוּמִין. וְיֵשׁ לְבֵית דִּין לִגְדֹּר בַּדָּבָר בְּכָל מָקוֹם וּבְכָל זְמַן כְּפִי שֶׁיִּרְאוּ. וְאִם בִּיֵּשׁ תַּלְמִיד חֲכָמִים חַיָּב לְשַׁלֵּם לוֹ בּשֶׁת שְׁלֵמָה אַף עַל פִּי שֶׁלֹּא בִּיְּשׁוֹ אֶלָּא בִּדְבָרִים. כְּבָר נִפְסַק הַדִּין שֶׁכָּל הַמְבַיֵּשׁ תַּלְמִיד חָכָם אֲפִלּוּ בִּדְבָרִים קוֹנְסִין אוֹתוֹ וְגוֹבִין מִמֶּנּוּ מִשְׁקַל שְׁלֹשִׁים וַחֲמִשָּׁה דִּינָר מִן הַזָּהָב שֶׁהוּא מִשְׁקַל תֵּשַׁע סְלָעִים פָּחוֹת רְבִיעַ. וְקַבָּלָה הִיא בְּיָדֵינוּ שֶׁגּוֹבִין קְנָס זֶה בְּכָל מָקוֹם בֵּין בָּאָרֶץ בֵּין בְּחוּצָה לָאָרֶץ:","מַעֲשִׂים הָיוּ אֶצְלֵנוּ תָּמִיד בְּכָךְ בִּסְפָרַד. וְיֵשׁ תַּלְמִידֵי חֲכָמִים שֶׁהָיוּ מוֹחֲלִין עַל זֶה וְכָךְ נָאֶה לָהֶם. וְיֵשׁ שֶׁתּוֹבֵעַ וְעוֹשִׂין פְּשָׁרָה בֵּינֵיהֶן. אֲבָל הַדַּיָּנִים הָיוּ אוֹמְרִין לַמְבַיֵּשׁ חַיָּב אַתָּה לִתֵּן לוֹ לִיטְרָא זָהָב:","אַף עַל פִּי שֶׁהַמְבַיֵּשׁ שְׁאָר הָעָם בִּדְבָרִים פָּטוּר מִן הַתַּשְׁלוּמִין עָוֹן גָּדוֹל הוּא. וְאֵינוֹ מְחָרֵף וּמְגַדֵּף לָעָם אֶלָּא רָשָׁע שׁוֹטֶה. וְאָמְרוּ חֲכָמִים הָרִאשׁוֹנִים שֶׁכָּל הַמַּלְבִּין פְּנֵי אָדָם כָּשֵׁר מִיִּשְׂרָאֵל בִּדְבָרִים אֵין לוֹ חֵלֶק לָעוֹלָם הַבָּא:","יֵשׁ הַכָּאוֹת רַבּוֹת שֶׁיֵּשׁ בָּהֶן בִּזּוּי וְצַעַר מְעַט וְאֵין בָּהֶן נֵזֶק. וּכְבָר פָּסְקוּ לָהֶם חֲכָמִים דָּמִים קְצוּבִים. וְכָל הַמַּכֶּה לַחֲבֵרוֹ הַכָּאָה מֵהֶן מְשַׁלֵּם אוֹתוֹ הַמָּמוֹן הַקָּצוּב וְכֻלָּן קְנָסוֹת הֵן. וְאוֹתוֹ הַמָּמוֹן הַקָּצוּב הוּא דְּמֵי הַצַּעַר וְהַבּשֶׁת וְהָרִפּוּי וְהַשֶּׁבֶת. בֵּין צָרִיךְ לִרְפוּאָה וְשֶׁבֶת בֵּין לֹא צָרִיךְ כָּזֶה הוּא מְשַׁלֵּם:","וְכַמָּה הוּא מְשַׁלֵּם. הַבּוֹעֵט בַּחֲבֵרוֹ בְּרַגְלוֹ מְשַׁלֵּם חָמֵשׁ סְלָעִים. הִכָּהוּ בְּאַרְכֻּבָּתוֹ מְשַׁלֵּם שָׁלֹשׁ סְלָעִים. קִבֵּץ אֶצְבְּעוֹתָיו כְּמוֹ אוֹגֵד אֲגוּדָה וְהִכָּהוּ בְּיָדוֹ כְּשֶׁהִיא אֲגוּדָה מְשַׁלֵּם שְׁלֹשׁ עֶשְׂרֵה סְלָעִים. תָּקַע אֶת חֲבֵרוֹ בְּכַפּוֹ מְשַׁלֵּם סֶלַע. סְטָרוֹ עַל פָּנָיו מְשַׁלֵּם חֲמִשִּׁים סְלָעִים. סְטָרוֹ מֵאֲחוֹרֵי יָדוֹ מְשַׁלֵּם מֵאָה סֶלַע. וְכֵן אִם צִירֵם בְּאָזְנוֹ אוֹ תָּלַשׁ בִּשְׂעָרוֹ אוֹ שֶׁרָקַק וְהִגִּיעוֹ [הָרֹק בִּבְשָׂרוֹ אוֹ הֶעֱבִיר טַלִּית מֵעָלָיו וּפָרַע רֹאשׁ הָאִשָּׁה] מְשַׁלֵּם מֵאָה סֶלַע. וְכָזֶה הוּא מְשַׁלֵּם עַל כָּל מַעֲשֶׂה וּמַעֲשֶׂה. כֵּיצַד. כְּגוֹן שֶׁבָּעַט בַּחֲבֵרוֹ אַרְבַּע בְּעִיטוֹת אֲפִלּוּ זוֹ אַחַר זוֹ מְשַׁלֵּם עֶשְׂרִים סְלָעִים. סְטָרוֹ עַל פָּנָיו שְׁתֵּי סְטִירוֹת מְשַׁלֵּם מֵאָה סֶלַע. וְכֵן בַּשְּׁאָר:","כָּל אֵלּוּ הַסְּלָעִים הֵם מִכֶּסֶף אֶרֶץ יִשְׂרָאֵל בְּאוֹתוֹ הַזְּמַן. שֶׁהָיָה בְּכָל סֶלַע חֲצִי דִּינָר כֶּסֶף וּשְׁלֹשָׁה דִּינָרִין וּמֶחֱצָה נְחשֶׁת. לְפִיכָךְ מִי שֶׁנִּתְחַיֵּב בְּהַכָּאוֹת אֵלּוּ לְשַׁלֵּם מֵאָה סֶלַע הֲרֵי זֶה מְשַׁלֵּם שְׁתֵּים עֶשְׂרֵה סֶלַע וּמֶחֱצָה כֶּסֶף נָקִי:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּמְכֻבָּד. אֲבָל אָדָם שֶׁהוּא מְבֻזֶּה וְאֵינוֹ מַקְפִּיד בְּכָל אֵלּוּ הַדְּבָרִים וְכַיּוֹצֵא בָּהֶן אֵינוֹ נוֹטֵל אֶלָּא לְפִי מַה שֶּׁרָאוּי לוֹ וּכְמוֹ שֶׁיִּרְאוּ הַדַּיָּנִים שֶׁהוּא רָאוּי לִטּל. לְפִי שֶׁיֵּשׁ בְּנֵי אָדָם כְּעוּרִין שֶׁאֵין מַקְפִּידִין עַל בָּשְׁתָּם וְכָל הַיּוֹם מְבַזִּים עַצְמָן בְּכָל מִינֵי בִּזּוּי דֶּרֶךְ שְׂחוֹק וְקַלּוּת רֹאשׁ אוֹ כְּדֵי לִטּל פְּרוּטָה אַחַת מִן הַלֵּצִים הַמְשַׂחֲקִים עִמָּהֶם:"],"Mishneh Torah, Other Sources of Defilement 15":["סְפֵק דִּבְרֵי סוֹפְרִים כֵּיצַד. סָפֵק אָכַל אֳכָלִין טְמֵאִין וְשָׁתָה מַשְׁקִין טְמֵאִין סָפֵק שֶׁלֹּא אָכַל וְשֶׁלֹּא שָׁתָה. סָפֵק שֶׁבָּא רֹאשׁוֹ וְרֻבּוֹ בְּמַיִם שְׁאוּבִין אוֹ שֶׁנָּפְלוּ עָלָיו שְׁלֹשָׁה לוֹגִין מַיִם שְׁאוּבִין סָפֵק שֶׁלֹּא בָּא וְשֶׁלֹּא נָפְלוּ הֲרֵי זֶה טָהוֹר. וְכֵן אִם אָכַל אֳכָלִין טְמֵאִין אוֹ שָׁתָה מַשְׁקִין טְמֵאִין אוֹ בָּא בְּמַיִם שְׁאוּבִין אוֹ נָפְלוּ עָלָיו שְׁלֹשָׁה לוֹגִין מַיִם שְׁאוּבִין וְסָפֵק נָגַע בְּטָהֳרוֹת אֵלּוּ סָפֵק לֹא נָגַע הֲרֵי טָהֳרוֹת אֵלּוּ טְהוֹרוֹת. וְכֵן הָאוֹכֵל סְפֵק אֳכָלִין טְמֵאִים וְהַשּׁוֹתֶה מַשְׁקִין שֶׁהֵן טְמֵאִים בְּסָפֵק הֲרֵי זֶה טָהוֹר. וְכֵן הָאוֹכֵל תְּרוּמָה תְּלוּיָה טָהוֹר. וְכֵן כָּל כַּיּוֹצֵא בְּאֵלּוּ מִוַּלְדֵי טֻמְאוֹת שֶׁהֵן מִדִּבְרֵי סוֹפְרִים סְפֵקָן טָהוֹר. אֲבָל אַב [הַטֻּמְאָה] שֶׁהוּא מִדִּבְרֵי סוֹפְרִים סְפֵקוֹ טָמֵא אֶלָּא אִם כֵּן הָיָה הָאָב עַצְמוֹ טָמֵא בְּסָפֵק כְּגוֹן בֵּית הַפְּרָס וְאֶרֶץ הָעַמִּים שֶׁאֵין שׂוֹרְפִין עַל סְפֵק מַגָּעָן כְּמוֹ שֶׁבֵּאַרְנוּ:","סְפֵק הַחֻלִּין הִיא טָהֳרַת אוֹכְלֵי חֻלֵּיהֶן בְּטָהֳרָה וְהֵן הַנִּקְרָאִים פְּרוּשִׁים. כֵּיצַד. אוֹכְלֵי חֻלֵּיהֶן בְּטָהֳרָה שֶׁנּוֹלַד לָהֶן סְפֵק טֻמְאָה בְּטָהֳרוֹתֵיהֶן הֲרֵי אֵלּוּ טְהוֹרִים כְּכָל הַסְּפֵקוֹת כֻּלָּן. וְאֵין לָהֶן טֻמְאָה אֶלָּא טֻמְאָה וַדָּאִית:","סְפֵק הַקָּרְבָּנוֹת כֵּיצַד. מְחֻסַּר כִּפּוּרִים שֶׁיֵּשׁ עָלָיו סְפֵק חֲמִשָּׁה קָרְבָּנוֹת. כְּגוֹן הָאִשָּׁה שֶׁיֵּשׁ עָלֶיהָ סְפֵק חָמֵשׁ זִיבוֹת אוֹ סְפֵק חָמֵשׁ לֵידוֹת. מְבִיאִין קָרְבָּן אֶחָד וְטָהוֹר לֶאֱכל בְּקָדָשִׁים וְאֵין הַשְּׁאָר עָלָיו חוֹבָה כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת מְחֻסְּרֵי כַּפָּרָה:","סְפֵק נְגָעִים כֵּיצַד. עַד שֶׁלֹּא נִזְקַק לְטֻמְאָה סְפֵקוֹ טָהוֹר כְּמוֹ שֶׁבֵּאַרְנוּ בְּפֶרֶק שִׁשִּׁי מֵהִלְכוֹת נְגָעִים:","סָפֵק עוֹמֵד וְעוֹבֵר כֵּיצַד. מְצֹרָע שֶׁיּוֹשֵׁב תַּחַת הָאִילָן וְהַטָּהוֹר עוֹבֵר סָפֵק הֶאֱהִיל עָלָיו הָאִילָן וְטָמֵא סָפֵק לֹא הֶאֱהִיל עָלָיו וְכֵן אִם הָיָה הַטָּהוֹר יוֹשֵׁב תַּחַת הָאִילָן וְהַמְצֹרָע עוֹבֵר תַּחְתָּיו סָפֵק עָמַד הַמְצֹרָע וְנִטְמָא הַטָּהוֹר סָפֵק לֹא עָמַד סְפֵקוֹ טָהוֹר:","סְפֵק שְׁרָצִים זֶה סְפֵק הַנִּזְרָקִין. כֵּיצַד. זָרַק שֶׁרֶץ אוֹ דָּבָר טָמֵא לְבֵין הַכִּכָּרוֹת אוֹ שֶׁזָּרַק כִּכָּר לְבֵין הַטְּמֵאוֹת וְסָפֵק נָגַע סָפֵק לֹא נָגַע הֲרֵי זֶה טָהוֹר הוֹאִיל וּמָצָא הַכִּכָּר הַטָּהוֹר שֶׁאֵינוֹ נוֹגֵעַ בַּטֻּמְאָה שֶׁכָּל הַטֻּמְאוֹת כִּשְׁעַת מְצִיאָתָן. וְאֵין אוֹמְרִין שֶׁמָּא נָגַע בּוֹ וְאַחַר כָּךְ נָפַל בְּצִדּוֹ אֶלָּא הֲרֵי הֵן כִּשְׁעַת מְצִיאָתָן:","הַשֶּׁרֶץ בְּפִי הַחֻלְדָּה וּמְהַלֶּכֶת עַל גַּבֵּי כִּכָּרוֹת שֶׁל תְּרוּמָה סָפֵק נָגַע סָפֵק לֹא נָגַע סְפֵקוֹ טָהוֹר מִפְּנֵי שֶׁלֹּא נָחָה הַטֻּמְאָה. הָיְתָה מְהַלֶּכֶת בּוֹ וְנוֹגַעַת בְּכִכָּרוֹת סָפֵק חַי סָפֵק מֵת הֲרֵי הֵן טְהוֹרוֹת. בַּמֶּה דְּבָרִים אֲמוּרִים בִּזְמַן שֶׁנְּטָלַתּוּ וְהָלְכָה לָהּ. אֲבָל אִם נִמְצָא מֵת בְּפִיהָ הֲרֵי אֵלּוּ טְמֵאוֹת. רָאוּהוּ חַי בְּפִיהָ אַף עַל פִּי שֶׁמְּצָאוּהוּ מֵת בְּפִיהָ הֲרֵי אֵלּוּ טְהוֹרוֹת. וְכֵן הַשֶּׁרֶץ בְּפִי הַחֻלְדָּה וְהַנְּבֵלָה בְּפִי הַכֶּלֶב וְעָבְרוּ בֵּין הַטְּהוֹרִים אוֹ שֶׁעָבְרוּ טְהוֹרִים בֵּינֵיהֶן סְפֵקוֹ טָהוֹר. מִפְּנֵי שֶׁאֵין לַטֻּמְאָה מָקוֹם קָבוּעַ. הָיוּ מְנַקְּרִין בָּהֶן עַל הָאָרֶץ הֲרֵי הֵן כְּמֻנָּחִין וּמְטַמְּאִין לְמַפְרֵעַ מִסָּפֵק אִם הָיוּ בִּרְשׁוּת הַיָּחִיד כְּמוֹ שֶׁיִּתְבָּאֵר:","סָפֵק רְשׁוּת הָרַבִּים כֵּיצַד. טֻמְאָה שֶׁמֻּנַּחַת בִּרְשׁוּת הָרַבִּים סָפֵק נָגַע בָּהּ סָפֵק לֹא נָגַע סְפֵקוֹ טָהוֹר. הָיְתָה בִּרְשׁוּת הַיָּחִיד וְסָפֵק נָגַע בָּהּ סָפֵק לֹא נָגַע סְפֵקוֹ טָמֵא. וְכָל אֵלּוּ הַסְּפֵקוֹת שֶׁטִּהֲרוּ חֲכָמִים אֲפִלּוּ בִּרְשׁוּת הַיָּחִיד מִפְּנֵי שֶׁאֵין בָּהֶן דַּעַת לְהִשָּׁאֵל כְּמוֹ שֶׁיִּתְבָּאֵר:","סָפֵק שְׁתֵּי רְשׁוּיוֹת כֵּיצַד. הָיָה דָּבָר טָמֵא בִּרְשׁוּת הַיָּחִיד וְדָבָר טָהוֹר בִּרְשׁוּת הָרַבִּים אוֹ שֶׁהָיָה הַדָּבָר לְהֵפֶךְ וְנָגַע בְּאֶחָד מֵהֶם וְאֵין יָדוּעַ בְּאֵי זֶה מֵהֶן נָגַע. אוֹ שֶׁהֵסִיט אֶת אֶחָד מֵהֶן וְאֵין יָדוּעַ אֵי זֶה הֵסִיט. אִם הָיָה הַדָּבָר הַטָּמֵא מְטַמֵּא בְּמַשָּׂא אוֹ שֶׁהָיָה אֶחָד מֵהֶן מְטַמֵּא בְּאֹהֶל וְהֶאֱהִיל עַל אֶחָד מֵהֶן וְאֵין יָדוּעַ אֵי זֶה מֵהֶן הֶאֱהִיל הֲרֵי זֶה טָהוֹר אַף עַל פִּי שֶׁסָּפֵק רְשׁוּת הָרַבִּים טָהוֹר. כְּשֶׁיָּבוֹא לִשָּׁאֵל אוֹמְרִין לוֹ אִם טָבַלְתָּ אֵין בְּכָךְ הֶפְסֵד. אִם טָבַל הֲרֵי זֶה מְשֻׁבָּח. וְאִם לֹא טָבַל וְעָשָׂה טָהֳרוֹת הֲרֵי הֵן טְהוֹרוֹת שֶׁסְּפֵק רְשׁוּת הָרַבִּים טָהוֹר:","שֶׁרֶץ שֶׁנִּמְצָא שָׂרוּף וּמֻנָּח עַל גַּבֵּי אֳכָלִין וְכֵן טַלִּית שֶׁנִּמְצֵאת בְּלוּיָה וּמַחַט שֶׁנִּמְצֵאת שְׁבוּרָה אוֹ חֲלוּדָה בֵּין הַכֵּלִים הֲרֵי אֵלּוּ טְהוֹרִין בֵּין בִּרְשׁוּת הָרַבִּים בֵּין בִּרְשׁוּת הַיָּחִיד. וְאֵין אוֹמְרִין שֶׁמָּא אַחַר שֶׁנָּגַע בָּאֳכָלִין נִשְׂרַף וְאַחַר שֶׁנִּטְמְאוּ הַכֵּלִים בְּמַגַּע הַטַּלִּית וְהַמַּחַט נִשְׁבְּרָה אוֹ הֶחְלִידָה וּבָלְתָה הַטַּלִּית עַד שֶׁטָּהֲרָה שֶׁכָּל הַטֻּמְאוֹת כִּשְׁעַת מְצִיאָתָן:","שְׁנֵי עֵדִים אוֹמְרִין לוֹ נִטְמָא וְהוּא אוֹמֵר טָהוֹר אֲנִי הוּא נֶאֱמָן עַל יְדֵי עַצְמוֹ. וְאַף עַל פִּי כֵן אֵין אוֹמְרִין לוֹ עֲסֹק בְּטָהֳרוֹת אֶלָּא אִם עָשָׂה טָהֳרוֹת הֲרֵי הֵן טְהוֹרוֹת וְיָחוּשׁ לְעַצְמוֹ. עֵד אוֹמֵר נִטְמָא וּשְׁנַיִם אוֹמְרִים לֹא נִטְמָא בֵּין בִּרְשׁוּת הָרַבִּים בֵּין בִּרְשׁוּת הַיָּחִיד טָהוֹר. שְׁנַיִם אוֹמְרִים נִטְמָא וְעֵד אֶחָד אוֹמֵר לֹא נִטְמָא בֵּין בִּרְשׁוּת הַיָּחִיד בֵּין בִּרְשׁוּת הָרַבִּים הֲרֵי זֶה נִטְמָא. עֵד אוֹמֵר נִטְמָא וְעֵד אוֹמֵר לֹא נִטְמָא אִשָּׁה אוֹמֶרֶת נִטְמָא וְאִשָּׁה אוֹמֶרֶת לֹא נִטְמָא בִּרְשׁוּת הַיָּחִיד טָמֵא בִּרְשׁוּת הָרַבִּים טָהוֹר:"],"Mishneh Torah, Other Sources of Defilement 8":["כָּל הַנּוֹגֵעַ בְּיָדָיו בְּרִאשׁוֹן לְטֻמְאָה בֵּין שֶׁהָיָה אוֹתוֹ רִאשׁוֹן אָדָם אוֹ כְּלִי אוֹ אֹכֶל אוֹ מַשְׁקִין טְמֵאִין נִטְמְאוּ יָדָיו בִּלְבַד עַד הַפֶּרֶק. וְכֵן הַמַּכְנִיס יָדָיו לַאֲוִיר כְּלִי חֶרֶס שֶׁנִּטְמָא בְּאַב הַטֻּמְאָה אוֹ שֶׁהִכְנִיס יָדָיו לְבַיִת מְנֻגָּע נִטְמְאוּ יָדָיו. וְטֻמְאַת הַיָּדָיִם מִדִּבְרֵי סוֹפְרִים:","הַיָּדָיִם שְׁנִיּוֹת מִדִּבְרֵי סוֹפְרִים לְעוֹלָם שֶׁאֵין טֻמְאָתָן אֶלָּא מִדִּבְרֵיהֶם וּכְשֶׁגָּזְרוּ טֻמְאָה עֲלֵיהֶן גָּזְרוּ שֶׁיִּהְיוּ כְּשֵׁנִי לְטֻמְאָה. אֲפִלּוּ הִכְנִיס יָדָיו לְבַיִת הַמְנֻגָּע אוֹ שֶׁנָּגַע בְּיָדָיו בְּאָדָם שֶׁמְּטַמֵּא בְּגָדִים עַד שֶׁלֹּא פֵּרַשׁ מִמְּטַמְּאָיו הֲרֵי יָדָיו שְׁנִיּוֹת:","הַפִּגּוּל וְהַנּוֹתָר וְצָרִיד שֶׁל מְנָחוֹת הֲרֵי הֵן כְּרִאשׁוֹן לְטֻמְאָה וּמוֹנִין בָּהֶן רִאשׁוֹן וְשֵׁנִי לְפִיכָךְ מְטַמְּאִין אֶת הַיָּדָיִם בִּכְבֵיצָה. וְאֵין הַפִּגּוּל וְהַנּוֹתָר מִצְטָרְפִין אַף עַל פִּי שֶׁשִּׁעוּרָן שָׁוָה בִּכְבֵיצָה הוֹאִיל וְטֻמְאַת הַיָּדַיִם מִדִּבְרֵיהֶן. אֲבָל שְׁאָר הָאֳכָלִין מִצְטָרְפִין שֶׁאֵין אֳכָלִים טְמֵאִין מְטַמְּאִין אֶת הַיָּדַיִם עַד שֶׁיִּהְיוּ כְּבֵיצָה:","קוּלִית הַפִּגּוּל אוֹ הַנּוֹתָר אַף עַל פִּי שֶׁהִיא סְתוּמָה הַנּוֹגֵעַ בָּהּ בְּיָדָיו נִטְמְאוּ יָדָיו שֶׁהָעֲצָמוֹת שֶׁל קָדָשִׁים שֶׁשִּׁמְּשׁוּ נוֹתָר אוֹ פִּגּוּל מְטַמְּאִין אֶת הַיָּדַיִם הוֹאִיל וְנַעֲשׂוּ בָּסִיס לְדָבָר הָאָסוּר:","בְּשַׂר קֹדֶשׁ שֶׁיָּצָא חוּץ לִמְחִצָּתוֹ הֲרֵי הוּא סָפֵק אִם מְטַמֵּא אֶת הַיָּדַיִם אוֹ לֹא. לְפִיכָךְ אֵינוֹ מְטַמֵּא שֶׁסְּפֵק טֻמְאַת הַיָּדַיִם טָהוֹר כְּמוֹ שֶׁיִּתְבָּאֵר. וְאִם בְּשַׂר פֶּסַח שֶׁיָּצָא חוּץ לַבַּיִת הוּא הֲרֵי הוּא טָהוֹר, בְּנֵי חֲבוּרָה זְרִיזִין הֵן:","אֵין טֻמְאַת יָדַיִם בַּמִּקְדָּשׁ. שֶׁבְּשָׁעָה שֶׁגָּזְרוּ טֻמְאָה עַל הַיָּדַיִם לֹא גָּזְרוּ בַּמִּקְדָּשׁ אֶלָּא הַנּוֹגֵעַ בָּאֳכָלִין טְמֵאִים וְכַיּוֹצֵא בָּהֶן בֵּין שֶׁנָּגַע בַּמִּקְדָּשׁ בֵּין שֶׁנָּגַע חוּץ לַמִּקְדָּשׁ וְנָגַע בְּקָדָשִׁים בַּמִּקְדָּשׁ לֹא טִמְּאָן. וְאִם נָגַע חוּץ לַמִּקְדָּשׁ הֲרֵי זֶה מְטַמֵּא אֶת הַקֹּדֶשׁ וּפוֹסֵל אֶת הַתְּרוּמָה כְּמוֹ שֶׁיִּתְבָּאֵר:","מִי שֶׁנִּטְמֵאת יָדוֹ אַחַת וְנָגְעָה בַּאֲחֶרֶת הָאַחֶרֶת טְהוֹרָה וְנוֹטֵל אֶת הַטְּמֵאָה וְדַיּוֹ. בַּמֶּה דְּבָרִים אֲמוּרִים לִתְרוּמָה. אֲבָל לְקֹדֶשׁ אִם נִטְמֵאת יָדוֹ אַחַת וְנָגַע בַּשְּׁנִיָּה טִמְּאָהּ. וּשְׁתֵּיהֶן צְרִיכוֹת טְבִילָה לְקֹדֶשׁ אֲבָל לִתְרוּמָה בִּנְטִילַת יָדַיִם בִּלְבַד יִטָּהֲרוּ יָדָיו:","שְׁלֹמֹה הַמֶּלֶךְ וּבֵית דִּינוֹ גָּזְרוּ עַל כָּל הַיָּדַיִם שֶׁיִּהְיוּ שְׁנִיּוֹת וְאַף עַל פִּי שֶׁלֹּא יָדַע בְּוַדַּאי שֶׁנִּטְמְאוּ מִפְּנֵי שֶׁהַיָּדַיִם עַסְקָנִיּוֹת. וְלֹא גָּזַר שְׁלֹמֹה עַל הַיָּדַיִם טֻמְאָה אֶלָּא לְקֹדֶשׁ. וְאַחַר כָּךְ גָּזְרוּ חֲכָמִים שֶׁאַחֲרָיו אַף לִתְרוּמָה. וּלְפִיכָךְ צָרִיךְ נְטִילַת יָדַיִם לִתְרוּמָה וְאִם נָגַע בִּתְרוּמָה קֹדֶם שֶׁיִּטּל יָדָיו פְּסוּלָה וְנִשְׂרֶפֶת עַל טֻמְאָה זוֹ:","לָט אָדָם יָדָיו בְּמַפָּה וְאוֹכֵל תְּרוּמָה בְּלֹא נְטִילַת יָדַיִם וְאֵין חוֹשְׁשִׁין שֶׁמָּא יִגַּע אֲבָל לֹא יַעֲשֶׂה כֵּן בְּחֻלִּין שֶׁנַּעֲשׂוּ עַל טָהֳרַת הַקֹּדֶשׁ אוֹ עַל טָהֳרַת תְּרוּמָה גְּזֵרָה שֶׁמָּא יִגַּע לְפִי שֶׁאֵינוֹ מַקְפִּיד עֲלֵיהֶן:","הוֹאִיל וְהַיָּדַיִם שְׁנִיּוֹת אִם נָגְעוּ בְּמַשְׁקֶה עֲשָׂאוּם תְּחִלָּה. וְאִם נָגְעוּ מַשְׁקִין אֵלּוּ בָּאֳכָלִין עוֹשִׂין אוֹתָן שֵׁנִי. וְאִם נָגְעוּ בְּמַשְׁקִין אֲחֵרִים עוֹשִׂין אוֹתָן תְּחִלָּה שֶׁהַמַּשְׁקִין תְּחִלָּה לְעוֹלָם כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל אֵין מַשְׁקִין אֵלּוּ שֶׁנִּטְמְאוּ מֵחֲמַת הַיָּדַיִם מְטַמְּאִין כֵּלִים שֶׁעִקַּר טֻמְאַת הַיָּדַיִם מִדִּבְרֵיהֶם. וְכֵן גָּזְרוּ חֲכָמִים עַל כָּל אָדָם שֶׁיֹּאכַל אֳכָלִין טְמֵאִין בֵּין שֶׁאָכַל אֹכֶל רִאשׁוֹן אוֹ אֹכֶל שֵׁנִי וְעַל כָּל הַשּׁוֹתֶה מַשְׁקִין טְמֵאִים שֶׁיִּהְיֶה שֵׁנִי לְטֻמְאָה עַד שֶׁיִּטְבּל. וְאִם נָגַע בָּאֳכָלִין עֲשָׂאָן שְׁלִישִׁי. וְאִם נָגַע בְּמַשְׁקִין אֲפִלּוּ מַשְׁקֶה חֻלִּין עֲשָׂאָן תְּחִלָּה לְטַמֵּא אֳכָלִין וּמַשְׁקִין אֲחֵרִים. אֲבָל לֹא לְטַמֵּא כֵּלִים הוֹאִיל וְעִקַּר טֻמְאַת אָדָם זֶה מִדִּבְרֵיהֶם. וּמִפְּנֵי מָה גָּזְרוּ טֻמְאָה עַל הָאוֹכֵל אֳכָלִין טְמֵאִים. שֶׁמָּא יֹאכַל אֹכֶל רִאשׁוֹן אוֹ שֵׁנִי וְיִשְׁתֶּה עָלָיו מַשְׁקֶה תְּרוּמָה וְנִמְצָא הַמַּשְׁקֶה תְּרוּמָה טָמֵא בָּאֹכֶל שֶׁבְּפִיו. וְכֵן הַשּׁוֹתֶה מַשְׁקִין טְמֵאִים שֶׁמָּא יֹאכַל עִמָּהֶן אֹכֶל תְּרוּמָה וְנִמְצָא טָמֵא בְּמַשְׁקִין שֶׁבְּפִיו. וּכְבָר בֵּאַרְנוּ בִּתְרוּמוֹת שֶׁאָסוּר לֶאֱכל תְּרוּמָה טְמֵאָה:","אֵינוֹ מִתְטַמֵּא עַד שֶׁיֹּאכַל מַאֲכָלִים טְמֵאִים כַּחֲצִי פְּרָס שֶׁהוּא כְּבֵיצָה וּמֶחֱצָה שׂוֹחֶקֶת. וְכֵן הַשּׁוֹתֶה אֵינוֹ מִתְטַמֵּא עַד שֶׁיִּשְׁתֶּה מִמַּשְׁקִין טְמֵאִין רְבִיעִית. וְכָל הָאֳכָלִין מִצְטָרְפִין לְכַחֲצִי פְּרָס לִפְסל אֶת הַגְּוִיָּה. וְכָל הַמַּשְׁקִין מִצְטָרְפִין לִרְבִיעִית. וְאִם אָכַל אוֹ שָׁתָה פָּחוֹת מִשִּׁעוּר זֶה טָהוֹר. אָכַל מְעַט וְשָׁהָה וְאָכַל מְעַט אִם יֵשׁ מִתְּחִלָּה וְעַד סוֹף כְּדֵי אֲכִילַת פְּרָס מִצְטָרְפִין וְאִם לָאו אֵין מִצְטָרְפִין. וְכֵן אִם שָׁתָה מְעַט וְשָׁהָה וְשָׁתָה מְעַט אִם יֵשׁ מִתְּחִלָּה וְעַד סוֹף כְּדֵי אֲכִילַת פְּרָס מִצְטָרְפִין וְאִם לָאו אֵין מִצְטָרְפִין. אָכַל פָּחוֹת מִכְּשִׁעוּר וְטָבַל וְעָלָה וְאָכַל מְעַט מִיָּד אִם לֹא שָׁהָה בֵּינֵיהֶן וַהֲרֵי בֵּין אֲכִילָה שֶׁלִּפְנֵי טְבִילָה וְשֶׁלְּאַחַר טְבִילָה בִּכְדֵי אֲכִילַת פְּרָס הֲרֵי אֵלּוּ מִצְטָרְפִין:","אִשָּׁה שֶׁהִיא רִאשׁוֹן לְטֻמְאָה וּמֵינִיקָה אֶת בְּנָהּ הֲרֵי הַבֵּן טָהוֹר וְלֹא גָּזְרוּ עָלָיו טֻמְאָה שֶׁאֲפִלּוּ תֹּאמַר שֶׁיָּנַק רְבִיעִית אֶפְשָׁר שֶׁיֵּשׁ מִתְּחִלָּה וְעַד סוֹף יֶתֶר מִכְּדֵי אֲכִילַת פְּרָס שֶׁהֲרֵי אֵינוֹ יוֹנֵק בְּבַת אַחַת:","הַמְעֻבֶּרֶת הִתִּירוּ לָהּ לֶאֱכל אֳכָלִין טְמֵאִין פָּחוֹת מִכְּשִׁעוּר. וְאַף עַל פִּי שֶׁהִיא אוֹכֶלֶת הַרְבֵּה מִפְּנֵי הַסַּכָּנָה. וְאֵינָהּ צְרִיכָה טְבִילָה אֶלָּא הֲרֵי הִיא טְהוֹרָה:"],"Mishneh Torah, Overview of Mishneh Torah Contents 6":["ספר הפלאה","הלכותיו ארבע, וזה הוא סידורן: הלכות שבועות, הלכות נדרים, הלכות נזירות, הלכות ערכין וחרמים.","הלכות שבועות. יש בכללן חמש מצוות – אחת מצות עשה, וארבע מצוות לא תעשה; וזה הוא פרטן: (א) שלא לישבע בשמו לשקר; (ב) שלא לישא את שמו לשוא; (ג) שלא לכפור בפיקדון; (ד) שלא לישבע על כפירת ממון; (ה) לישבע בשמו באמת.","הלכות נדרים. יש בכללן שלוש מצוות – שתיים מצוות עשה, ואחת מצות לא תעשה; וזה הוא פרטן: (א) שישמור מוצא שפתיו ויעשה כמו שנדר; (ב) שלא יחל דברו; (ג) שיופר הנדר או השבועה, וזה הוא דין הפר נדרים המפורש בתורה שבכתב.","הלכות נזירות. יש בכללן עשר מצוות – שתיים מצוות עשה, ושמונה מצוות לא תעשה; וזה הוא פרטן: (א) שיגדל הנזיר פרע; (ב) שלא יגלח שיערו כל ימי נזרו; (ג) שלא ישתה הנזיר יין ולא תערובת יין, ואפילו חומץ שלהן; (ד) שלא יאכל ענבים לחים; (ה) שלא יאכל צימוקין; (ו) שלא יאכל חרצנים; (ז) שלא יאכל זוגים; (ח) שלא ייכנס לאוהל המת; (ט) שלא ייטמא למתים; (י) שיגלח על הקרבנות, כשישלים נזירותו או כשייטמא.","הלכות ערכין וחרמים. יש בכללן שבע מצוות – חמש מצוות עשה, ושתיים מצוות לא תעשה; וזה הוא פרטן: (א) לדון בערכי אדם כאשר מפורש בתורה, וזה הוא דין ערכי אדם; (ב) דין ערכי בהמה; (ג) דין ערכי בתים; (ד) דין ערכי שדות; (ה) דין מחרים נכסיו; (ו) שלא יימכר חרם; (ז) שלא ייגאל חרם.","נמצאו כל המצוות הנכללות בספר זה, חמש ועשרים – עשר מהן מצוות עשה, וחמש עשרה מצוות לא תעשה."],"Mishneh Torah, Ownerless Property and Gifts 6":["לְעוֹלָם אוֹמְדִין דַּעַת הַנּוֹתֵן. אִם הָיוּ הַדְּבָרִים מַרְאִין סוֹף דַּעְתּוֹ עוֹשִׂין עַל פִּי הָאֹמֶד אַף עַל פִּי שֶׁלֹּא פֵּרֵשׁ. כֵּיצַד. מִי שֶׁהָלַךְ בְּנוֹ לִמְדִינַת הַיָּם וְשָׁמַע שֶׁמֵּת וְכָתַב כָּל נְכָסָיו לְאַחֵר מַתָּנָה גְּלוּיָה גְּמוּרָה וְאַחַר כָּךְ בָּא בְּנוֹ אֵין מַתְּנָתוֹ קַיֶּמֶת. שֶׁהַדְּבָרִים מוֹכִיחִין שֶׁאִלּוּ יָדַע שֶׁבְּנוֹ קַיָּם לֹא הָיָה נוֹתֵן כָּל נְכָסָיו. לְפִיכָךְ אִם שִׁיֵּר מִנְּכָסָיו כָּל שֶׁהוּא בֵּין קַרְקַע בֵּין בְּמִטַּלְטְלִין מַתְּנָתוֹ קַיֶּמֶת:","וְכֵן הַכּוֹתֵב כָּל נְכָסָיו מַתָּנָה לְאֶחָד מִבָּנָיו בֵּין שֶׁהָיָה בָּרִיא בֵּין שֶׁהָיָה שְׁכִיב מֵרַע. אֲפִלּוּ הָיָה בֵּן קָטָן הַמֻּטָּל בָּעֲרִיסָה לֹא עָשָׂהוּ אֶלָּא אַפּוֹטְרוֹפּוֹס. וַהֲרֵי הוּא בְּכָל הַנְּכָסִים כְּאֶחָד מֵאֶחָיו. אֻמְדַּן דַּעַת הוּא שֶׁלֹּא נִתְכַּוֵּן אֶלָּא לִהְיוֹת אֶחָיו נִשְׁמָעִין לוֹ. וְאִם שִׁיֵּר כָּל שֶׁהוּא בֵּין קַרְקַע בֵּין בְּמִטַּלְטְלִין זָכָה הַבֵּן בְּמַתָּנָה:","בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁכָּתַב לְבֵן בֵּין הַבָּנִים. אֲבָל אִם כָּתַב כָּל נְכָסָיו לְבֵן בֵּין הַבָּנוֹת אוֹ לְבַת בֵּין הַבָּנוֹת אוֹ לְאֶחָד מִן הַיּוֹרְשִׁין בֵּין שְׁאָר הַיּוֹרְשִׁין. אַף עַל פִּי שֶׁלֹּא שִׁיֵּר כְּלוּם מַתְּנָתוֹ קַיֶּמֶת:","וְכֵן הַכּוֹתֵב כָּל נְכָסָיו לְאִשְׁתּוֹ בֵּין בָּרִיא בֵּין שְׁכִיב מֵרַע אַף עַל פִּי שֶׁקָּנוּ מִיָּדוֹ לֹא עֲשָׂאָהּ אֶלָּא אַפּוֹטְרוֹפָּא עַל יוֹרְשָׁיו. בֵּין שֶׁהָיוּ יוֹרְשֵׁי בָּנָיו מִמֶּנָּה אוֹ מֵאִשָּׁה אַחֶרֶת אוֹ אֶחָיו אוֹ שְׁאָר יוֹרְשָׁיו. וְאִם שִׁיֵּר כָּל שֶׁהוּא בֵּין קַרְקַע בֵּין מִטַּלְטְלִין קָנְתָה כָּל שֶׁכָּתַב לָהּ:","בַּמֶּה דְּבָרִים אֲמוּרִים בִּנְשׂוּאָה. אֲבָל אִם כָּתַב כָּל נְכָסָיו לְאִשְׁתּוֹ אֲרוּסָה אוֹ לִגְרוּשָׁה אַף עַל פִּי שֶׁלֹּא שִׁיֵּר כְּלוּם הֲרֵי הִיא כִּשְׁאָר בְּנֵי אָדָם וּמַתְּנָתוֹ קַיֶּמֶת:","הַכּוֹתֵב כָּל נְכָסָיו לְאֶחָד מִבָּנָיו וּלְאַחֵר. זֶה הָאַחֵר קָנָה חֲצִי הַנְּכָסִים בְּמַתָּנָה. וְנִשְׁאַר הַחֵצִי לְבָנָיו. וְהַבֵּן שֶׁנָּתְנוּ לוֹ אַפּוֹטְרוֹפּוֹס מִנָּהוּ עַל שְׁאָר אֶחָיו:","וְכֵן אִם כָּתַב כָּל נְכָסָיו לְאִשְׁתּוֹ וּלְאַחֵר. זֶה הָאַחֵר קָנָה מֶחֱצָה וְאִשְׁתּוֹ אַפּוֹטְרוֹפָּא עַל מֶחֱצָה:","כָּל אִשָּׁה שֶׁקָּנְתָה כָּל נִכְסֵי בַּעְלָהּ בְּמַתָּנָה. אִבְּדָה כְּתֻבָּתָהּ וְתִקָּרַע. לְפִיכָךְ אִם יָצָא שְׁטַר חוֹב עָלָיו וְהָלְכוּ כָּל הַנְּכָסִים בְּחוֹבוֹ שֶׁקָּדַם הַמַּתָּנָה תִּשָּׁאֵר הִיא בְּלֹא כְּלוּם וְלֹא תִּקַּח בִּכְתֻבָּתָהּ שֶׁקָּדְמָה הַחוֹב. שֶׁאֻמְדַּן דַּעַת הוּא שֶׁבַּהֲנָאָה שֶׁבָּאָה לָהּ בִּשְׁמוּעָה זוֹ שֶׁכָּתַב לָהּ כָּל נְכָסָיו אִבְּדָה כָּל זְכוּת שֶׁיֵּשׁ לָהּ בַּנְּכָסִים חוּץ מִמַּתָּנָה זוֹ:","וְכֵן הַכּוֹתֵב נְכָסָיו לְבָנָיו בֵּין זְכָרִים בֵּין נְקֵבוֹת בֵּין בָּרִיא בֵּין שְׁכִיב מֵרַע וְכָתַב לְאִשְׁתּוֹ עִמָּהֶן קַרְקַע כָּל שֶׁהוּא. הוֹאִיל וְעָשָׂה אוֹתָהּ שֻׁתָּף בֵּין הַבָּנִים וְלֹא מָחֲתָה אִבְּדָה כְּתֻבָּתָהּ וְאֵינָהּ טוֹרֶפֶת מִנְּכָסִים אֵלּוּ כְּלוּם. אֲבָל מִנְּכָסָיו שֶׁיָּבוֹאוּ לוֹ אַחַר אֵלּוּ נוֹטֶלֶת מֵהֶן כְּתֻבָּתָהּ:","כָּתַב לָהּ עִמָּהֶן מִטַּלְטְלִין בִּלְבַד אוֹ שֶׁשִּׁיֵּר לְעַצְמוֹ קַרְקַע כָּל שֶׁהוּא. כְּתֻבָּתָהּ קַיֶּמֶת. וְתַקָּנַת הַגְּאוֹנִים הִיא שֶׁאֲפִילוּ שִׁיֵּר מִטַּלְטְלִים כָּל שֶׁהוּא. שֶׁהֲרֵי הִיא אוֹמֶרֶת מִמַּה שֶּׁשִּׁיֵּר אֲנִי גּוֹבָה וּמִתּוֹךְ שֶׁתֵּרֵד לְמַה שֶּׁשִּׁיֵּר תֵּרֵד לִשְׁאָר נְכָסִים וְתִטְרֹף:","הַכּוֹתֵב כָּל נְכָסָיו לְבָנָיו וְכָתַב לְאִשְׁתּוֹ חֵלֶק עִמָּהֶן. וּמֵת אֶחָד מִן הַבָּנִים בְּחַיֵּי אָבִיו. הֲרֵי זוֹ תִּגְבֶּה כְּתֻבָּתָהּ מֵחֵלֶק זֶה שֶׁמֵּת. שֶׁלֹּא אִבְּדָה כְּתֻבָּתָהּ אֶלָּא מִלִּטְרֹף מֵהֶן:","הָרוֹצָה לְהִנָּשֵׂא וְכָתְבָה כָּל נְכָסֶיהָ בֵּין לִבְנָהּ בֵּין לְאַחֵר. וְאַחַר כָּךְ נִשֵּׂאת וְנִתְגָּרְשָׁה אוֹ שֶׁמֵּת בַּעְלָהּ. מַתְּנָתָהּ בְּטֵלָה שֶׁזּוֹ מַבְרַחַת הִיא וְלֹא כָּתְבָה כָּל נְכָסֶיהָ אֶלָּא לְהַבְרִיחַ מִבַּעְלָהּ שֶׁלֹּא יִירָשֶׁנָּה. וּכְשֶׁתִּהְיֶה צְרִיכָה לָהֶן יַחְזְרוּ לָהּ. לְפִיכָךְ אִם מֵתָה הִיא בְּחַיֵּי בַּעְלָהּ קָנָה הַמְקַבֵּל מַתָּנָה אֶת הַכּל. וְאִם שִׁיְּרָה כְּלוּם אֲפִלּוּ מִטַּלְטְלִין מַתְּנָתָהּ קַיֶּמֶת וְאַף עַל פִּי שֶׁנִּתְגָּרְשָׁה אֵינָהּ חוֹזֶרֶת:","כָּל הַנּוֹתְנִין כָּל נִכְסֵיהֶם. מִשֶּׁתִּבָּטֵל הַמַּתָּנָה וְיַחְזְרוּ כָּל הַנְּכָסִין לַבְּעָלִים הָרִאשׁוֹנִים אֵין הַמְקַבֵּל מַתָּנָה מַחְזִיר פֵּרוֹת. שֶׁאֲפִילוּ נָתַן הָאָדָם מַתָּנָה בְּפֵרוּשׁ עַל מְנָת לְהַחְזִיר כָּל יְמֵי חַיֵּי פְּלוֹנִי הֲרֵי זֶה אוֹכֵל פֵּרוֹת כָּל זְמַן הַמַּתָּנָה כְּמוֹ שֶׁבֵּאַרְנוּ:","מִי שֶׁשָּׁלַח כֵּלִים מִמְּדִינַת הַיָּם וְאָמַר יִנָּתְנוּ אֵלּוּ לְבָנַי. הֲרֵי אֵלּוּ יִנָּתְנוּ לַבָּנִים וְלַבָּנוֹת. הָרָאוּי לַבָּנִים כְּגוֹן סְפָרִים וּכְלֵי מִלְחָמָה לַבָּנִים. וְהָרָאוּי לַבָּנוֹת כְּגוֹן כְּלֵי מֶשִׁי הַצְּבוּעִים וַחֲלִי זָהָב יִטְּלוּם הַבָּנוֹת. הָיוּ רְאוּיִין לִזְכָרִים וְלִנְקֵבוֹת יִטְּלוּ אוֹתָן הַזְּכָרִים. וְכֵן הַמְשַׁלֵּחַ כֵּלִים לְבֵיתוֹ סְתָם וְהָיוּ בָּהֶן כֵּלִים הָרְאוּיִין לְבָנוֹת. יִטְּלוּ אוֹתָן בְּנוֹתָיו. אֻמְדַּן דַּעַת הוּא שֶׁלָּהֶן שָׁלַח. וְאִם אֵין לוֹ בָּנוֹת אוֹ שֶׁהָיוּ בְּנוֹתָיו נְשׂוּאוֹת. יִטְּלוּ אוֹתָן נְשֵׁי בָּנָיו. שֶׁהַדַּעַת נוֹטָה שֶׁלָּהֶן שָׁלַח:","הַמַּשִּׂיא בְּנוֹ גָּדוֹל לִבְתוּלָה בַּבַּיִת קָנָה הַבַּיִת. וְהוּא שֶׁיִּהְיוּ נִשּׂוּאִין רִאשׁוֹנִים לְזֶה הַבֵּן. וְלֹא הִשִּׂיא הָאָב בֵּן אַחֵר קֹדֶם לוֹ וְלֹא שִׁיֵּר הָאָב בְּזֶה הַבַּיִת שֶׁיִּחֵד לוֹ כְּלוּם. וּדְבָרִים אֵלּוּ כַּהֲלָכָה שֶׁאֵין לָהֶם טַעַם הֵם. וְנָגְעוּ חֲכָמִים בַּדָּבָר הַזֶּה מֵאֻמְדַּן הַדַּעַת. שֶׁמֵּרֹב שִׂמְחָתוֹ וְאַהֲבָתוֹ גָּמַר וְהִקְנָהוּ הַבַּיִת. שֶׁהֲרֵי לֹא שִׁיֵּר בָּהּ לְעַצְמוֹ כְּלוּם. לְפִיכָךְ אִם שִׁיֵּר שָׁם אֲפִלּוּ פַּךְ אֶחָד לֹא קָנָה הַבַּיִת. יִחֵד לוֹ בַּיִת וּכְלֵי בַּיִת אַף עַל פִּי שֶׁשִּׁיֵּר בַּבַּיִת כְּלִי אֶחָד לְעַצְמוֹ אוֹ הָיָה לוֹ שָׁם אוֹצָר וְכַיּוֹצֵא בּוֹ. קָנָה כְּלֵי הַבַּיִת אֲבָל הַבַּיִת לֹא קָנָה:","יִחֵד לוֹ בַּיִת וַעֲלִיָּה. בַּיִת קָנָה עֲלִיָּה לֹא קָנָה. וְכֵן אִם יִחֵד לוֹ בַּיִת וְאַכְסַדְרָה בַּיִת קָנָה אַכְסַדְרָה לֹא קָנָה. שְׁנֵי בָּתִּים זֶה לְפָנִים מִזֶּה לֹא קָנָה אֶלָּא הָאֶחָד שֶׁנָּשָׂא בּוֹ:","כְּבָר בֵּאַרְנוּ בְּנִשּׂוּאִין שֶׁשְּׁנַיִם שֶׁהָיָה בֵּינֵיהֶם שִׁדּוּכִין וּפָסַק זֶה עַל יְדֵי בְּנוֹ וְזֶה עַל יְדֵי בִּתּוֹ. וְאָמְרוּ כַּמָּה אַתָּה נוֹתֵן לְבִנְךָ. כָּךְ וְכָךְ. וְכַמָּה אַתָּה נוֹתֵן לְבִתְּךָ. כָּךְ וְכָךְ. וְעָמְדוּ וְקִדְּשׁוּ. קָנוּ בַּאֲמִירָה. וְאֵין קוֹנִין בַּאֲמִירָה זוֹ עַד שְׁעַת נִשּׂוּאִין שֶׁכָּל הַפּוֹסֵק דַּעְתּוֹ לִכְנֹס. וּצְרִיכִין שֶׁיִּהְיוּ הַדְּבָרִים שֶׁהֵן פּוֹסְקִין מְצוּיִין בִּרְשׁוּתוֹ. שֶׁאֵין אָדָם מַקְנֶה דָּבָר שֶׁלֹּא בָּא לָעוֹלָם כְּמוֹ שֶׁבֵּאַרְנוּ. וּדְבָרִים אֵלּוּ לֹא נִתְּנוּ לְהִכָּתֵב. לְפִיכָךְ אֵינָן כִּשְׁטָר עַד שֶׁיִּטְרֹף בָּהֶן:","הַמְקַדֵּשׁ אֶת הָאִשָּׁה. אֲפִלּוּ קִדְּשָׁהּ בְּאֶלֶף דִּינָר. בֵּין שֶׁחָזְרָה הִיא בֵּין שֶׁחָזַר הוּא. בֵּין שֶׁמֵּת הוּא בֵּין שֶׁמֵּתָה הִיא. אֵין הַקִּדּוּשִׁין חוֹזְרִין לְעוֹלָם. אֶלָּא הֲרֵי הֵן מַתָּנָה גְּמוּרָה שֶׁאֵין לָהֶם חֲזָרָה:","וְאִם הָיוּ קִדּוּשֵׁי טָעוּת חוֹזְרִין הַמָּעוֹת:","והַמְקַדֵּשׁ אֲחוֹתוֹ הַמָּעוֹת מַתָּנָה. אָדָם יוֹדֵעַ שֶׁאֵין קִדּוּשִׁין תּוֹפְסִין בַּעֲרָיוֹת וְאֵין זֶה טוֹעֶה אֶלָּא גָּמַר וְנָתַן לְשֵׁם מַתָּנָה:","הַשּׁוֹלֵחַ סִבְלוֹנוֹת לְבֵית חָמִיו בֵּין מְרֻבִּין בֵּין מוּעָטִין. בֵּין שֶׁאָכַל שָׁם סְעוּדַת אֵרוּסִין בֵּין שֶׁלֹּא אָכַל. בֵּין שֶׁמֵּת הוּא בֵּין שֶׁמֵּתָה הִיא. אוֹ שֶׁחָזַר בּוֹ הָאִישׁ. יַחְזְרוּ הַסִּבְלוֹנוֹת כֻּלָּן חוּץ מִן הַמַּאֲכָל וְהַמַּשְׁקֶה:","וְכֵן כֵּלִים מֻעָטִים שֶׁשָּׁלַח לָהּ לְהִשְׁתַּמֵּשׁ שָׁם בְּבֵית אָבִיהָ. אִם נִשְׁתַּמְּשָׁה בָּהֶן וּבָלוּ אוֹ אָבְדוּ אֵינָן מִשְׁתַּלְּמִין. אֲבָל אִם הָיוּ קַיָּמִין חוֹזֵר הַכּל וְגוֹבֶה אוֹתָם בְּבֵית דִּין. שֶׁהַדָּבָר יָדוּעַ שֶׁלֹּא שְׁלָחָם אֶלָּא דֶּרֶךְ נוֹי בִּלְבַד:","חָזְרָה הִיא בָּהּ חוֹזֵר הַכּל. וַאֲפִלּוּ הַמַּאֲכָל וְהַמַּשְׁקֶה נוֹתֶנֶת דָּמָיו בְּזוֹל. וּכְבָר הִסְכִּימוּ הַגְּאוֹנִים שֶׁאִם הָיוּ דְּמֵי מַאֲכָל וּמַשְׁקֶה [שָׁוֶה] שִׁשָּׁה מִשְׁתַּלֶּמֶת אַרְבָּעָה אִם חָזְרָה בָּהּ. שֶׁלֹּא נָתַן לָהּ מַתָּנָה זוֹ אֶלָּא לְדַעַת שֶׁלֹּא תַּחְזֹר בָּהּ:","הוֹרוּ רַבּוֹתַי שֶׁאִם הָיָה מִנְהַג הַמְּדִינָה שֶׁיַּעֲשֶׂה כָּל אָדָם סְעוּדָה וְיַאֲכִיל לְרֵעָיו אוֹ יְחַלֵּק מָעוֹת לַשַּׁמָּשִׁין וְלַחַזָּנִין וְכַיּוֹצֵא בָּהֶן וְעָשָׂה כְּדֶרֶךְ שֶׁעוֹשִׂין כָּל הָעָם וְחָזְרָה בָּהּ מְשַׁלֶּמֶת הַכּל. שֶׁהֲרֵי גָּרְמָה לוֹ לְאַבֵּד מָמוֹן וְכָל הַגּוֹרֵם לְאַבֵּד מָמוֹן חֲבֵרוֹ מְשַׁלֵּם. וְהוּא שֶׁיִּהְיוּ לוֹ עֵדִים כַּמָּה הוֹצִיא. שֶׁאֵין זֶה נִשְׁבָּע וְנוֹטֵל:"],"Mishneh Torah, Paschal Offering 8":["אֲכִילַת בְּשַׂר הַפֶּסַח בְּלֵיל חֲמִשָּׁה עָשָׂר מִצְוַת עֲשֵׂה שֶׁנֶּאֱמַר (שמות יב ח) \"וְאָכְלוּ אֶת הַבָּשָׂר בַּלַּיְלָה הַזֶּה צְלִי אֵשׁ וּמַצּוֹת עַל מְרֹרִים יֹאכְלֻהוּ\":","וְאֵין מַצָּה וּמָרוֹר מְעַכְּבִין. אִם לֹא מָצְאוּ מַצָּה וּמָרוֹר יוֹצְאִין יְדֵי חוֹבָתָן בַּאֲכִילַת בְּשַׂר הַפֶּסַח לְבַדּוֹ. אֲבָל מָרוֹר בְּלֹא פֶּסַח אֵינוֹ מִצְוָה שֶׁנֶּאֱמַר (במדבר ט יא) \"עַל מַצּוֹת וּמְרֹרִים יֹאכְלֻהוּ\":","מִצְוָה מִן הַמֻּבְחָר לֶאֱכל בְּשַׂר הַפֶּסַח אֲכִילַת שֹׂבַע. לְפִיכָךְ אִם הִקְרִיב שַׁלְמֵי חֲגִיגָה בְּאַרְבָּעָה עָשָׂר. אוֹכֵל מֵהֶן תְּחִלָּה וְאַחַר כָּךְ אוֹכֵל בְּשַׂר הַפֶּסַח כְּדֵי לִשְׂבֹּעַ מִמֶּנּוּ. וְאִם לֹא אָכַל אֶלָּא כְּזַיִת יָצָא יְדֵי חוֹבָתוֹ. וְכֵן אֲכִילַת בְּשַׂר פֶּסַח שֵׁנִי בְּלֵילֵי חֲמִשָּׁה עָשָׂר לְחֹדֶשׁ אִיָּר מִצְוַת עֲשֵׂה. שֶׁנֶּאֱמַר בּוֹ (במדבר ט יא) \"עַל מַצּוֹת וּמְרֹרִים יֹאכְלֻהוּ\":","וּשְׁנֵיהֶן אֵינָן נֶאֱכָלִין אֶלָּא צְלִי אֵשׁ. וְהָאוֹכֵל מֵהֶן כְּזַיִת נָא אוֹ מְבֻשָּׁל בְּלֵילֵי פְּסָחִים לוֹקֶה שֶׁנֶּאֱמַר (שמות יב ט) \"אַל תֹאכְלוּ מִמֶּנּוּ נָא וּבָשֵׁל מְבֻשָּׁל בַּמָּיִם\". אָכַל נָא וּמְבֻשָּׁל כְּאַחַת אֵינוֹ לוֹקֶה אֶלָּא אַחַת. לְפִי שֶׁשְּׁנֵיהֶן נִכְלָלוֹת בְּלָאו אֶחָד. אָכַל מִמֶּנּוּ נָא אוֹ מְבֻשָּׁל מִבְּעוֹד יוֹם אֵינוֹ לוֹקֶה שֶׁנֶּאֱמַר (שמות יב ט) \"כִּי אִם צְלִי אֵשׁ\" בְּשָׁעָה שֶׁמִּצְוָה לְאָכְלוֹ צָלִי חַיָּב עַל אֲכִילַת נָא וּמְבֻשָּׁל. אֲבָל מִבְּעוֹד יוֹם פָּטוּר:","אָכַל מִמֶּנּוּ כְּזַיִת צָלִי מִבְּעוֹד יוֹם עָבַר עַל מִצְוַת עֲשֵׂה. שֶׁנֶּאֱמַר (שמות יב ח) \"וְאָכְלוּ אֶת הַבָּשָׂר בַּלַּיְלָה הַזֶּה\". בַּלַּיְלָה וְלֹא בַּיּוֹם. וְלָאו הַבָּא מִכְּלַל עֲשֵׂה עֲשֵׂה הוּא:","(שמות יב ט) \"נָא\" שֶׁהִזְהִירָה עָלָיו תּוֹרָה הוּא הַבָּשָׂר שֶׁהִתְחִיל בּוֹ מַעֲשֵׂה הָאוּר וְנִצְלָה מְעַט וְאֵינוֹ רָאוּי לַאֲכִילַת אָדָם עֲדַיִן. אֲבָל אִם אָכַל מִמֶּנּוּ בָּשָׂר חַי אֵינוֹ לוֹקֶה וּבִטֵּל מִצְוַת עֲשֵׂה. שֶׁנֶּאֱמַר (שמות יב ט) \"צְלִי אֵשׁ\". הָא שֶׁאֵינוֹ צָלִי אָסוּר. צָלָהוּ כָּל צָרְכּוֹ עַד שֶׁנִּתְחָרֵךְ וַאֲכָלוֹ פָּטוּר:","(שמות יב ט) \"מְבֻשָּׁל\" שֶׁהִזְהִירָה עָלָיו תּוֹרָה בֵּין שֶׁנִּתְבַּשֵּׁל בְּמַיִם בֵּין שֶׁנִּתְבַּשֵּׁל בִּשְׁאָר מַשְׁקִין אוֹ בְּמֵי פֵּרוֹת שֶׁנֶּאֱמַר (שמות יב ט) \"וּבָשֵׁל מְבֻשָּׁל\" רִבָּה הַכּל:","צָלָהוּ וְאַחַר כָּךְ בִּשְּׁלוֹ. אוֹ שֶׁבִּשְּׁלוֹ וְאַחַר כָּךְ צָלָהוּ. אוֹ שֶׁעָשָׂהוּ צְלִי קְדֵרָה וַאֲכָלוֹ חַיָּב. אֲבָל מֻתָּר לָסוּךְ אוֹתוֹ בְּיַיִן וְשֶׁמֶן וּדְבַשׁ וּבִשְׁאָר מַשְׁקִין וּמֵי פֵּרוֹת. חוּץ מִן הַמַּיִם. וּמֻתָּר לְטַבֵּל הַבָּשָׂר אַחַר שֶׁנִּצְלָה בְּמַשְׁקִים וּבְמֵי פֵּרוֹת:","אֵין צוֹלִין אֶת הַפֶּסַח עַל גַּבֵּי כְּלֵי אֶבֶן אוֹ כְּלֵי מַתָּכוֹת שֶׁנֶּאֱמַר (שמות יב ח ט) \"צְלִי אֵשׁ\" לֹא צְלִי דָּבָר אַחֵר. לְפִיכָךְ אִם הָיָה כְּלִי מְנֻקָּב כְּדֵי שֶׁתִּשְׁלֹט בּוֹ הָאוּר צוֹלִין עָלָיו. וְאֵין צוֹלִין אוֹתוֹ בְּשִׁפּוּד שֶׁל מַתֶּכֶת שֶׁהֲרֵי הַשִּׁפּוּד כֻּלּוֹ חַם וְצוֹלֶה מְקוֹמוֹ:","הִסִּיק אֶת הַתַּנּוּר וְגָרַף אֶת כָּל הָאֵשׁ וְתָלָהוּ בַּתַּנּוּר וְצָלָהוּ הֲרֵי זֶה אָסוּר שֶׁאֵין זֶה צְלִי אֵשׁ. חֲתָכוֹ וְתָלָהוּ עַל גַּבֵּי גֶּחָלִים הֲרֵי זֶה צְלִי אֵשׁ. צָלָהוּ עַל גַּבֵּי סִיד אוֹ חַרְסִית אוֹ חַמֵּי טְבֶרְיָה הֲרֵי זֶה אָסוּר שֶׁאֵין זֶה צְלִי אֵשׁ. כֵּיצַד צוֹלִין אוֹתוֹ. תּוֹחֲבוֹ מִתּוֹךְ פִּיו עַד בֵּית נְקוּבָתוֹ בְּשִׁפּוּד שֶׁל עֵץ וְתוֹלֵהוּ לְתוֹךְ הַתַּנּוּר וְהָאֵשׁ לְמַטּה וְתוֹלֶה כְּרָעָיו וּבְנֵי מֵעָיו בְּתַנּוּר חוּצָה לוֹ וְלֹא יִתְּנֵם בְּתוֹכוֹ שֶׁזֶּה כְּמִין בִּשּׁוּל הוּא. ושִׁפּוּד שֶׁל רִמּוֹן הָיוּ בּוֹרְרִין לִצְלִיָּתוֹ כְּדֵי שֶׁלֹּא יִזְרֹק אֶת מֵימָיו וִיבַשְּׁלֵהוּ:","נָגַע הַבָּשָׂר בְּחַרְסוֹ שֶׁל תַּנּוּר יִקְלֹף אֶת מְקוֹמוֹ מִפְּנֵי שֶׁהוּא צְלִי הַחֶרֶס:","נָטָף מֵרָטְבּוֹ עַל הַחֶרֶס וְחָזַר עָלָיו יִטּל אֶת מְקוֹמוֹ שֶׁכָּל הַמָּרָק וְהַלֵּחָה שֶׁתִּפְרשׁ מִמֶּנּוּ כְּשֶׁיִּצָּלֶה אֲסוּרָה שֶׁהֲרֵי אֵינָהּ בְּשַׂר צָלִי:","נָטַף מֵרָטְבּוֹ עַל הַסּלֶת יִקְלֹף אֶת מְקוֹמוֹ וְיַשְׁלִכֶנּוּ:","סָכוֹ בְּשֶׁמֶן שֶׁל תְּרוּמָה אִם חֲבוּרַת הַכֹּהֲנִים יֹאכְלוּ. וְאִם שֶׁל יִשְׂרָאֵל אִם חַי הוּא יְדִיחֶנּוּ וִינַגֵּב וְאִם צָלִי יִקְלֹף אֶת הַחִיצוֹן. סָכוֹ בְּשֶׁמֶן שֶׁל מַעֲשֵׂר שֵׁנִי לֹא יַעֲשֶׂנּוּ דָּמִים עַל בְּנֵי חֲבוּרָה שֶׁאֵין פּוֹדִין מַעֲשֵׂר שֵׁנִי בִּירוּשָׁלַיִם כְּמוֹ שֶׁבֵּאַרְנוּ בִּמְקוֹמוֹ. וְאֵין צוֹלִין שְׁנֵי פְּסָחִים כְּאַחַת מִפְּנֵי הַתַּעֲרוֹבוֹת אֲפִלּוּ גְּדִי וְטָלֶה:","כְּבָר בֵּאַרנוּ בְּכַמָּה מְקוֹמוֹת שֶׁאֵין הַפֶּסַח נֶאֱכָל אֶלָּא עַד חֲצוֹת כְּדֵי לְהַרְחִיק מִן הָעֲבֵרָה וְדִין תּוֹרָה שֶׁיֹּאכַל כָּל הַלַּיְלָה עַד שֶׁיַּעֲלֶה עַמּוּד הַשַּׁחַר. וּכְבָר בֵּאַרְנוּ בְּהִלְכוֹת חָמֵץ וּמַצָּה שֶׁהוּא טָעוּן הַלֵּל בִּשְׁעַת אֲכִילָתוֹ וְשֶׁאֵין בְּנֵי חֲבוּרָה חוֹזְרִין וְאוֹכְלִין אַחַר שִׁנִּרְדְּמוּ בְּשֵׁנָה אֲפִלּוּ בִּתְחִלַּת הַלַּיְלָה:"],"Mishneh Torah, Plaintiff and Defendant 4":["אֵין מוֹדֶה בְּמִקְצָת חַיָּב שְׁבוּעָה מִן הַתּוֹרָה עַד שֶׁיִּטְעָנֶנּוּ בְּדָבָר שֶׁבְּמִדָּה אוֹ בְּמִשְׁקָל אוֹ בְּמִנְיָן וְיוֹדֶה לוֹ בְּדָבָר שֶׁבְּמִדָּה אוֹ שֶׁבְּמִשְׁקָל אוֹ שֶׁבְּמִנְיָן. כֵּיצַד. עֲשָׂרָה דִּינָרִין יֵשׁ לִי בְּיָדְךָ אֵין לְךָ בְּיָדִי אֶלָּא חֲמִשָּׁה. כּוֹר חִטִּים יֵשׁ לִי בְּיָדְךָ אֵין לְךָ בְּיָדִי אֶלָּא לֶתֶךְ. שְׁתֵּי לִיטְרִין שֶׁל מֶשִׁי יֵשׁ לִי בְּיָדְךָ אֵין לְךָ בְּיָדִי אֶלָּא רוֹטֶל הֲרֵי זֶה חַיָּב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. אֲבָל אָמַר לוֹ כִּיס מָלֵא דִּינָרִין מָסַרְתִּי לְךָ לֹא מָסַרְתָּ לִי אֶלָּא חֲמִשִּׁים. מֵאָה דִּינָרִין מָסַרְתִּי לְךָ לֹא מָסַרְתָּ לִי אֶלָּא צְרוֹר שֶׁל דִּינָרִין וְלֹא מָנִיתָ אוֹתָן בְּפָנַי וְאֵינִי יוֹדֵעַ מֶה הָיָה בּוֹ וּמַה שֶּׁהִנַּחְתָּ אַתָּה נוֹטֵל הֲרֵי זֶה פָּטוּר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","בַּיִת מָלֵא תְּבוּאָה מָסַרְתִּי לְךָ וְהַלָּה אוֹמֵר לֹא מָסַרְתָּ לִי אֶלָּא עֲשָׂרָה כּוֹרִין. עֲשָׂרָה כּוֹרִין מָסַרְתִּי לְךָ אֵינִי יוֹדֵעַ כַּמָּה הֵם שֶׁהֲרֵי לֹא מְדַדְתָּם בְּפָנַי אֶלָּא מַה שֶּׁהִנַּחְתָּ אַתָּה נוֹטֵל פָּטוּר:","בַּיִת זֶה מָלֵא עַד הַזִּיז מָסַרְתִּי לְךָ וְהַלָּה אוֹמֵר עַד הַחַלּוֹן חַיָּב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","אֵין מוֹדֶה בְּמִקְצָת חַיָּב שְׁבוּעָה עַד שֶׁיּוֹדֶה בְּדָבָר שֶׁאֶפְשָׁר לוֹ לִכְפֹּר בּוֹ. כֵּיצַד. מִי שֶׁטָּעַן חֲבֵרוֹ וְאָמַר מֵאָה דִּינָרִין יֵשׁ לִי אֶצְלְךָ חֲמִשִּׁים שֶׁבִּשְׁטָר זֶה וַחֲמִשִּׁים בְּלֹא שְׁטָר. אֵין לְךָ בְּיָדִי אֶלָּא חֲמִשִּׁים שֶׁבַּשְּׁטָר אֵין זֶה מוֹדֶה בְּמִקְצָת שֶׁהַשְּׁטָר לֹא תּוֹעִיל בּוֹ כְּפִירָתוֹ וַהֲרֵי כָּל נְכָסָיו מְשֻׁעְבָּדִין בּוֹ וַאֲפִלּוּ כָּפַר בּוֹ הָיָה חַיָּב לְשַׁלֵּם. לְפִיכָךְ נִשְׁבָּע הֶסֵּת עַל הַחֲמִשִּׁים:","שְׁטָר שֶׁכָּתוּב בּוֹ סְלָעִים וְלֹא הִזְכִּיר מִנְיָן. מַלְוֶה אוֹמֵר חָמֵשׁ סְלָעִים שֶׁיֵּשׁ לִי בְּיָדְךָ הֵם הַכְּתוּבִים בּוֹ וְהַלּוֶֹה אוֹמֵר אֵין לְךָ בְּיָדִי אֶלָּא שָׁלֹשׁ וְהֵם הַכְּתוּבִים בַּשְּׁטָר. אַף עַל פִּי שֶׁאֵין מְחַיְּבִין אוֹתוֹ בִּשְׁטָר זֶה אֶלָּא בִּשְׁתַּיִם וַהֲרֵי הוֹדָה בְּסֶלַע שֶׁאֶפְשָׁר לִכְפֹּר בָּהּ הֲרֵי זֶה פָּטוּר מִפְּנֵי שֶׁהוּא כְּמֵשִׁיב אֲבֵדָה וְתַקָּנַת חֲכָמִים הִיא שֶׁכָּל שֶׁיָּשִׁיב אֲבֵדָה לֹא יִשָּׁבַע כְּמוֹ שֶׁבֵּאַרְנוּ בִּמְקוֹמוֹ. וְכֵן הָאוֹמֵר לַחֲבֵרוֹ אָמַר לִי אַבָּא שֶׁיֵּשׁ לִי בְּיָדְךָ מָנֶה וְהַלָּה אוֹמֵר אֵין לְךָ בְּיָדִי אֶלָּא חֲמִשִּׁים הֲרֵי זֶה מֵשִׁיב אֲבֵדָה וּפָטוּר אַף מִשְּׁבוּעַת הֶסֵּת. וְאֵין צָרִיךְ לוֹמַר אִם הוֹדָה מֵעַצְמוֹ וְאָמַר מָנֶה הָיָה לְאָבִיךָ בְּיָדִי וְנָתַתִּי לוֹ חֲמִשִּׁים דִּינָרִין וְנִשְׁאַר לוֹ חֲמִשִּׁים שֶׁזֶּה פָּטוּר אַף מִשְּׁבוּעַת הֶסֵּת. אֲבָל יוֹרֵשׁ שֶׁטָּעַן וְאָמַר אֲנִי יוֹדֵעַ בְּוַדַּאי שֶׁיֵּשׁ לְאָבִי בְּיָדְךָ אוֹ בְּיַד אָבִיךָ מָנֶה וְהוּא אוֹמֵר אֵין לוֹ בְּיָדִי אֶלָּא חֲמִשִּׁים אוֹ אֵין לְךָ בְּיַד אָבִי אֶלָּא חֲמִשִּׁים הֲרֵי זֶה מוֹדֶה מִקְצָת וְיִשָּׁבַע:","מָנֶה לִי בְּיָדְךָ עַל מַשְׁכּוֹן זֶה אֵין בְּיָדִי עָלָיו אֶלָּא חֲמִשִּׁים הֲרֵי זֶה מוֹדֶה וְיִשָּׁבַע. אֵין הַמַּשְׁכּוֹן שָׁוֶה אֶלָּא חֲמִשִּׁים אוֹ פָּחוֹת הֲרֵי זֶה נִשְׁבָּע וּמְשַׁלֵּם הַחֲמִשִּׁים שֶׁהוֹדָה בָּהֶן. הָיָה הַמַּשְׁכּוֹן שָׁוֶה מֵאָה אוֹ יֶתֶר הוֹאִיל וְהַמַּלְוֶה יָכוֹל לִטְעֹן עָלָיו עַד כְּדֵי דָּמָיו הֲרֵי הַמַּלְוֶה נִשְׁבָּע וְנוֹטֵל מִדְּמֵי הַמַּשְׁכּוֹן. הָיָה שָׁוֶה שְׁמוֹנִים נִשְׁבָּע הַמַּלְוֶה שֶׁאֵין לוֹ פָּחוֹת מִשְּׁמוֹנִים וְנוֹטְלָן מִן הַמַּשְׁכּוֹן. וְנִשְׁבָּע הַלּוֶֹה מִן הַתּוֹרָה עַל הָעֶשְׂרִים שֶׁכָּפַר בָּהֶן. כָּפַר בַּכּל וְאָמַר אֵין זֶה מַשְׁכּוֹן אֶלָּא פִּקָּדוֹן וְאֵין לוֹ אֶצְלִי כְּלוּם נִשְׁבָּע הַמַּלְוֶה שֶׁאֵין פָּחוֹת מִשְּׁמוֹנִים וְנִשְׁבָּע הַלּוֶֹה הֶסֵּת עַל הָעֶשְׂרִים:","מָנֶה לִי בְּיָדְךָ וְהַלָּה אוֹמֵר חֲמִשִּׁים וַדַּאי יֵשׁ לְךָ בְּיָדִי אֲבָל הַחֲמִשִּׁים אֵינִי יוֹדֵעַ אִם אֲנִי חַיָּב בָּהֶן אוֹ לָאו הֲרֵי זֶה מְחֻיָּב שְׁבוּעָה מִפְּנֵי שֶׁהוֹדָה בְּמִקְצָת וְאֵינוֹ יָכוֹל לְהִשָּׁבַע בַּמִּקְצָת שֶׁכָּפַר בּוֹ שֶׁהֲרֵי אֵינוֹ יוֹדֵעַ לְפִיכָךְ מְשַׁלֵּם הַמָּנֶה בְּלֹא שְׁבוּעָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְיֵשׁ לוֹ לְהַחֲרִים עַל מִי שֶׁטּוֹעֵן עָלַי דָּבָר שֶׁאֵינוֹ יוֹדֵעַ בְּוַדַּאי שֶׁאֲנִי חַיָּב בּוֹ:","מָנֶה לִי בְּיָדְךָ וַהֲרֵי עֵד אֶחָד מֵעִיד עָלָיו וְהַנִּטְעָן אוֹמֵר כֵּן הוּא אֲבָל אַתָּה חַיָּב לִי כְּנֶגֶד אוֹתוֹ מָנֶה הֲרֵי זֶה מְחֻיָּב שְׁבוּעָה וְאֵינוֹ יָכוֹל לִשָּׁבַע וּמְשַׁלֵּם. וּמִפְּנֵי מָה אֵינוֹ יָכוֹל לִשָּׁבַע שֶׁהֲרֵי הוּא מוֹדֶה בְּמַה שֶּׁהֵעִיד בּוֹ הָעֵד וְאֵין הַנִּשְׁבָּע בְּהַעֲדָאַת עֵד אֶחָד נִשְׁבָּע עַד שֶׁיַּכְחִישׁ אֶת הָעֵד וְיִכְפֹּר בְּעֵדוּתוֹ וְיִשָּׁבַע עַל כְּפִירָתוֹ. לְפִיכָךְ שְׁטָר שֶׁיֵּשׁ בּוֹ עֵד אֶחָד וְטָעַן שֶׁפְּרָעוֹ. וְכֵן כַּפְרָן שֶׁבָּא עָלָיו עֵד אֶחָד וְטָעַן שֶׁפָּרַע אוֹ הֶחְזַרְתִּי לְךָ הַפִּקָּדוֹן הֲרֵי זֶה מְחֻיָּב שְׁבוּעָה וְאֵינוֹ יָכוֹל לְהִשָּׁבַע וּמְשַׁלֵּם. מַעֲשֶׂה בְּאֶחָד שֶׁחָטַף לְשׁוֹן כֶּסֶף מֵחֲבֵרוֹ בִּפְנֵי עֵד אֶחָד וְאָמַר אַחַר כֵּן חָטַפְתִּי וְשֶׁלִּי חָטַפְתִּי וְאָמְרוּ חֲכָמִים הֲרֵי זֶה מְחֻיָּב שְׁבוּעָה וְאֵינוֹ יָכוֹל לְהִשָּׁבַע וּמְשַׁלֵּם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מָנֶה הִלְוֵיתִיךָ לֹא הָיוּ דְּבָרִים מֵעוֹלָם הֵבִיא עֵד אֶחָד שֶׁלָּוָה מִמֶּנּוּ בְּפָנָיו. הוֹאִיל וְאִלּוּ הָיוּ שְׁנַיִם הָיָה מֻחְזָק כַּפְרָן וּמְשַׁלֵּם כְּמוֹ שֶׁיִּתְבָּאֵר הֲרֵי זֶה נִשְׁבָּע עַל פִּי עֵד אֶחָד שֶׁכָּל מָקוֹם שֶׁשְּׁנַיִם מְחַיְּבִין אוֹתוֹ מָמוֹן אֶחָד מְחַיְּבוֹ שְׁבוּעָה. חָזַר וְאָמַר פָּרַעְתִּי מְשַׁלֵּם בְּלֹא שְׁבוּעָה כְּמוֹ שֶׁבֵּאַרְנוּ:","מָנֶה לִי בְּיָדְךָ אֵין לְךָ בְּיָדִי כְּלוּם וְהָעֵדִים מְעִידִין עָלָיו שֶׁעֲדַיִן יֵשׁ לוֹ אֶצְלוֹ חֲמִשִּׁים. פָּסְקוּ כָּל הַגְּאוֹנִים הֲלָכָה שֶׁיְּשַׁלֵּם חֲמִשִּׁים וְיִשָּׁבַע עַל הַשְּׁאָר. שֶׁלֹּא תְּהֵא הוֹדָיַת פִּיו גְּדוֹלָה מֵהַעֲדָאַת עֵדִים:"],"Mishneh Torah, Positive Mitzvot 104":["להיות הזב מטמא."],"Mishneh Torah, Positive Mitzvot 115":["להיות מעריך בהמה טמאה נותן דמיה, שנאמר: \"וְהֶעֱמִיד אֶת הַבְּהֵמָה\" (ויקרא כז, יא)."],"Mishneh Torah, Positive Mitzvot 126":["להפריש תרומה גדולה לכהן, שנאמר: \"רֵאשִׁית דְּגָנְךָ תִּתֵּן לוֹ\" (דברים יח, ד)."],"Mishneh Torah, Positive Mitzvot 137":["לתקוע בשופר בשנת היובל, שנאמר: \"והעברת שופר תרועה\" (ויקרא כה,ט)."],"Mishneh Torah, Positive Mitzvot 148":["לשלח הקן, שנאמר: \"שלח תשלח את האם ואת הבנים תיקח לך\" (דברים כב,ז)."],"Mishneh Torah, Positive Mitzvot 159":["לשבות בראשון של פסח, שנאמר: \"וביום הראשון, מקרא קודש\" (שמות יב,טז)."],"Mishneh Torah, Positive Mitzvot 17":["לִכְתֹּב כָּל אִישׁ סֵפֶר תּוֹרָה לְעַצְמוֹ, שֶׁנֶּאֱמָר: \"כִּתְבוּ לָכֶם אֶת הַשִּׁירָה הַזֹּאת\" (דברים לא, יט)."],"Mishneh Torah, Positive Mitzvot 180":["לעשות לעדים זוממין כמו שזממו לעשות, שנאמר: \"ועשיתם לו, כאשר זמם\" (דברים יט,יט)."],"Mishneh Torah, Positive Mitzvot 191":["למשוח כוהן למלחמה, שנאמר: \"והיה, כקרבכם אל המלחמה; וניגש הכוהן\" (דברים כ,ב)."],"Mishneh Torah, Positive Mitzvot 201":["להיות השכיר אוכל בזמן שכירותו, שנאמר: \"כי תבוא בכרם ריעך\" (דברים כג,כה), \"כי תבוא בקמת ריעך\" (דברים כג,כו)."],"Mishneh Torah, Positive Mitzvot 212":["לפרות ולרבות, שנאמר: \"פרו ורבו\" (בראשית ט, ז)."],"Mishneh Torah, Positive Mitzvot 223":["לעשות לסוטה כתורה, שנאמר: \"ועשה לה הכוהן, את כל התורה הזאת\" (במדבר ה,ל)."],"Mishneh Torah, Positive Mitzvot 234":["לפדות אמה עברייה, שנאמר: \"והפדה\" (שמות כא,ח)."],"Mishneh Torah, Positive Mitzvot 245":["לדון בדין מקח וממכר, שנאמר: \"וכי תמכרו ממכר לעמיתך\" (ויקרא כה,יד)."],"Mishneh Torah, Positive Mitzvot 32":["לחלוק כבוד לזרעו של אהרן, ולהקדימו לכל דבר שבקדושה, שנאמר: \"וְקִדַּשְׁתּוֹ\" (ויקרא כא, ח)."],"Mishneh Torah, Positive Mitzvot 43":["להוסיף קרבן בחג הפסח, שנאמר: \"שִׁבְעַת יָמִים תַּקְרִיבוּ אִשֶּׁה לַיי\" (ויקרא כג, לו)."],"Mishneh Torah, Positive Mitzvot 54":["לשמוח ברגלים, שנאמר: \"וְשָׂמַחְתָּ בְּחַגֶּךָ\" (דברים טז, יד)."],"Mishneh Torah, Positive Mitzvot 65":["מעשה האשם, שנאמר: \"זֹאת תּוֹרַת הָאָשָׁם\" (ויקרא ז, א)."],"Mishneh Torah, Positive Mitzvot 76":["להקריב היולדת קרבן אחר שתטהר, שנאמר: \"ובמלאות ימי טהרה\" (ויקרא יב,ו)."],"Mishneh Torah, Positive Mitzvot 87":["להיות התמורה קודש, שנאמר: \"והיה הוא ותמורתו יהיה קודש\" (ויקרא כז,י; ויקרא כז,לג)."],"Mishneh Torah, Positive Mitzvot 98":["להיות האוכלין מיטמאין, שנאמר \"מכל האוכל אשר יאכל\" (ויקרא יא, לד)."],"Mishneh Torah, Prayer and the Priestly Blessing 5":["שְׁמוֹנָה דְּבָרִים צָרִיךְ הַמִּתְפַּלֵּל לְהִזָּהֵר בָּהֶן וְלַעֲשׂוֹתָן. וְאִם הָיָה דָּחוּק אוֹ נֶאֱנַס אוֹ שֶׁעָבַר וְלֹא עָשָׂה אוֹתָן אֵין מְעַכְּבִין. וְאֵלּוּ הֵן. עֲמִידָה. וְנֹכַח הַמִּקְדָּשׁ. וְתִקּוּן הַגּוּף. וְתִקּוּן הַמַּלְבּוּשִׁים. וְתִקּוּן הַמָּקוֹם. וְהַשְׁוָיַת הַקּוֹל. וְהַכְּרִיעָה. וְהִשְׁתַּחֲוָיָה:","עֲמִידָה כֵּיצַד. אֵין מִתְפַּלֵּל אֶלָּא מְעֻמָּד. הָיָה יוֹשֵׁב בִּסְפִינָה אוֹ בַּעֲגָלָה אִם יָכוֹל לַעֲמֹד יַעֲמֹד. וְאִם לָאו יֵשֵׁב בִּמְקוֹמוֹ וְיִתְפַּלֵּל. חוֹלֶה מִתְפַּלֵּל אֲפִלּוּ שׁוֹכֵב עַל צִדּוֹ וְהוּא שֶׁיָּכוֹל לְכַוֵּן אֶת דַּעְתּוֹ. וְכֵן הַצָּמֵא וְהָרָעֵב הֲרֵי הֵן בִּכְלַל חוֹלִים אִם יֵשׁ בּוֹ יְכלֶת לְכַוֵּן אֶת דַּעְתּוֹ יִתְפַּלֵּל וְאִם לָאו אַל יִתְפַּלֵּל עַד שֶׁיֹּאכַל וְיִשְׁתֶּה. הָיָה רוֹכֵב עַל הַבְּהֵמָה אַף עַל פִּי שֶׁיֵּשׁ לוֹ מִי שֶׁיֹּאחַז בְּהֶמְתּוֹ לֹא יֵרֵד אֶלָּא יֵשֵׁב בִּמְקוֹמוֹ וְיִתְפַּלֵּל כְּדֵי שֶׁתְּהֵא דַּעְתּוֹ מְיֻשֶּׁבֶת עָלָיו:","נֹכַח הַמִּקְדָּשׁ כֵּיצַד. הָיָה עוֹמֵד בְּחוּצָה לָאָרֶץ מַחֲזִיר פָּנָיו נֹכַח אֶרֶץ יִשְׂרָאֵל וּמִתְפַּלֵּל. הָיָה עוֹמֵד בָּאָרֶץ מְכַוֵּן אֶת פָּנָיו כְּנֶגֶד יְרוּשָׁלַיִם. הָיָה עוֹמֵד בִּירוּשָׁלַיִם מְכַוֵּן פָּנָיו כְּנֶגֶד הַמִּקְדָּשׁ. הָיָה עוֹמֵד בַּמִּקְדָּשׁ מְכַוֵּן פָּנָיו כְּנֶגֶד בֵּית קֹדֶשׁ הַקָּדָשִׁים. סוּמָא וּמִי שֶׁלֹּא יָכוֹל לְכַוֵּן אֶת הָרוּחוֹת וְהַמְהַלֵּךְ בִּסְפִינָה יְכַוֵּן אֶת לִבּוֹ כְּנֶגֶד הַשְּׁכִינָה וְיִתְפַּלֵּל:","תִּקּוּן הַגּוּף כֵּיצַד. כְּשֶׁהוּא עוֹמֵד בִּתְפִלָּה צָרִיךְ לְכַוֵּן אֶת רַגְלָיו זוֹ בְּצַד זוֹ וְנוֹתֵן עֵינָיו לְמַטָּה כְּאִלּוּ הוּא מַבִּיט לָאָרֶץ. וְיִהְיֶה לִבּוֹ פָּנוּי לְמַעְלָה כְּאִלּוּ הוּא עוֹמֵד בַּשָּׁמַיִם וּמַנִּיחַ יָדָיו עַל לִבּוֹ כְּפוּתִין הַיְמָנִית עַל הַשְּׂמָאלִית וְעוֹמֵד כְּעֶבֶד לִפְנֵי רַבּוֹ בְּאֵימָה בְּיִרְאָה וָפַחַד. וְלֹא יַנִּיחַ יָדָיו עַל חֲלָצָיו:","תִּקּוּן הַמַּלְבּוּשִׁים כֵּיצַד. מְתַקֵּן מַלְבּוּשָׁיו תְּחִלָּה וּמְצַיֵּן עַצְמוֹ וּמְהַדֵּר שֶׁנֶּאֱמַר הִשְׁתַּחֲווּ לַה׳‎ בְּהַדְרַת קֹדֶשׁ. וְלֹא יַעֲמֹד בִּתְפִלָּה בַּאֲפוּנְדָתוֹ, וְלֹא בְּרֹאשׁ מְגֻלֶּה, וְלֹא בְּרַגְלַיִם מְגֻלּוֹת אִם דֶּרֶךְ אַנְשֵׁי הַמָּקוֹם שֶׁלֹּא יַעַמְדוּ בִּפְנֵי הַגְּדוֹלִים אֶלָּא בְּבָתֵּי הָרַגְלַיִם. וּבְכָל מָקוֹם לֹא יֶאֱחֹז תְּפִלִּין בְּיָדוֹ וְסֵפֶר תּוֹרָה בִּזְרוֹעוֹ וְיִתְפַּלֵּל מִפְּנֵי שֶׁלִּבּוֹ טָרוּד בָּהֶן. וְלֹא יֶאֱחֹז כֵּלִים וּמָעוֹת בְּיָדוֹ. אֲבָל מִתְפַּלֵּל הוּא וְלוּלָב בְּיָדוֹ בִּימוֹת הֶחָג מִפְּנֵי שֶׁהוּא מִצְוַת הַיּוֹם. הָיָה מַשּׂוֹי עַל רֹאשׁוֹ וְהִגִּיעַ זְמַן תְּפִלָּה אִם הָיָה פָּחוֹת מֵאַרְבָּעָה קַבִּין מַפְשִׁילוֹ לַאֲחוֹרָיו וּמִתְפַּלֵּל בּוֹ. הָיָה אַרְבָּעָה קַבִּין מַנִּיחוֹ עַל גַּבֵּי קַרְקַע וְאַחַר כָּךְ יִתְפַּלֵּל. דֶּרֶךְ כָּל הַחֲכָמִים וְתַלְמִידֵיהֶם שֶׁלֹּא יִתְפַּלְּלוּ אֶלָּא כְּשֶׁהֵן עֲטוּפִים:","תִּקּוּן הַמָּקוֹם כֵּיצַד. יַעֲמֹד בְּמָקוֹם נָמוּךְ וְיַחֲזִיר פָּנָיו לַכֹּתֶל. וְצָרִיךְ לִפְתֹּחַ חַלּוֹנוֹת אוֹ פְּתָחִים כְּנֶגֶד יְרוּשָׁלַיִם כְּדֵי לְהִתְפַּלֵּל כְּנֶגְדָּן שֶׁנֶּאֱמַר (דניאל ו יא) ״וְכַוִּין פְּתִיחָן לֵהּ בְּעִלִּיתֵהּ״ וְגוֹ׳‎. וְקוֹבֵעַ מָקוֹם לִתְפִלָּתוֹ תָּמִיד. וְאֵין מִתְפַּלֵּל בְּחֻרְבָּה וְלֹא אֲחוֹרֵי בֵּית הַכְּנֶסֶת אֶלָּא אִם כֵּן הֶחֱזִיר פָּנָיו לְבֵית הַכְּנֶסֶת. וְאָסוּר לֵישֵׁב בְּצַד הָעוֹמֵד בִּתְפִלָּה אוֹ לַעֲבֹר לְפָנָיו עַד שֶׁיַּרְחִיק מִמֶּנּוּ אַרְבַּע אַמּוֹת:","לֹא יַעֲמֹד בְּמָקוֹם גָּבוֹהַּ שְׁלֹשָׁה טְפָחִים אוֹ יוֹתֵר וְיִתְפַּלֵּל. וְלֹא עַל גַּבֵּי מִטָּה וְלֹא עַל גַּבֵּי סַפְסָל וְלֹא עַל גַּבֵּי כִּסֵּא. הָיָה בִּנְיָן גָּבוֹהַּ אִם יֵשׁ בּוֹ אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת שֶׁהוּא שִׁעוּר הַבַּיִת הֲרֵי הוּא כַּעֲלִיָּה וּמֻתָּר לְהִתְפַּלֵּל בּוֹ. וְכֵן אִם הָיָה מֻקָּף מְחִצּוֹת מִכָּל רוּחוֹתָיו אַף עַל פִּי שֶׁאֵין בּוֹ אַרְבַּע אַמּוֹת עַל אַרְבַּע אַמּוֹת מֻתָּר לְהִתְפַּלֵּל בּוֹ מִפְּנֵי שֶׁאֵין גָּבְהוֹ נִכָּר שֶׁהֲרֵי חָלַק רְשׁוּת לְעַצְמוֹ:","הָאֻמָּנִין שֶׁהָיוּ עוֹשִׂין מְלָאכָה בְּרֹאשׁ הָאִילָן אוֹ בְּרֹאשׁ הַנִּדְבָּךְ אוֹ בְּרֹאשׁ הַכֹּתֶל וְהִגִּיעַ זְמַן תְּפִלָּה יוֹרְדִין לְמַטָּה וּמִתְפַּלְּלִין וְחוֹזְרִין לִמְלַאכְתָּן. וְאִם הָיוּ בְּרֹאשׁ הַזַּיִת אוֹ בְּרֹאשׁ הַתְּאֵנָה מִתְפַּלְּלִין בִּמְקוֹמָן מִפְּנֵי שֶׁטָּרְחָן מְרֻבֶּה. וּמַה הֵן מִתְפַּלְּלִין. אִם הָיוּ עוֹשִׂין בִּסְעֻדָּתָן בִּלְבַד מִתְפַּלְּלִין שָׁלֹשׁ תְּפִלּוֹת שֶׁל תִּשְׁעָה עָשָׂר בְּרָכוֹת. הָיוּ עוֹשִׂין בִּשְׂכָרָן מִתְפַּלְּלִין הֲבִינֵנוּ. וּבֵין כָּךְ וּבֵין כָּךְ אֵין יוֹרְדִין לִפְנֵי הַתֵּבָה וְאֵין נוֹשְׂאִין אֶת כַּפֵּיהֶן:","הַשְׁוָיַת הַקּוֹל כֵּיצַד. לֹא יַגְבִּיהַּ קוֹלוֹ בִּתְפִלָּתוֹ וְלֹא יִתְפַּלֵּל בְּלִבּוֹ אֶלָּא מְחַתֵּךְ הַדְּבָרִים בִּשְׂפָתָיו וּמַשְׁמִיעַ לְאָזְנָיו בְּלַחַשׁ. וְלֹא יַשְׁמִיעַ קוֹלוֹ אֶלָּא אִם כֵּן הָיָה חוֹלֶה אוֹ שֶׁאֵינוֹ יָכוֹל לְכַוֵּן אֶת לִבּוֹ עַד שֶׁיַּשְׁמִיעַ קוֹלוֹ, הֲרֵי זֶה מֻתָּר. וּבִלְבַד שֶׁלֹּא יְהֵא בְּצִבּוּר כְּדֵי שֶׁלֹּא תִּטָּרֵף דַּעְתָּן מִקּוֹלוֹ:","כְּרִיעָה כֵּיצַד. הַמִּתְפַּלֵּל כּוֹרֵעַ חָמֵשׁ כְּרִיעוֹת בְּכָל תְּפִלָּה וּתְפִלָּה. בִּבְרָכָה רִאשׁוֹנָה בַּתְּחִלָּה וּבַסּוֹף. וּבְהוֹדָיָה בַּתְּחִלָּה וּבַסּוֹף. וּכְשֶׁגּוֹמֵר הַתְּפִלָּה כּוֹרֵעַ וּפוֹסֵעַ שָׁלֹשׁ פְּסִיעוֹת לַאֲחוֹרָיו. וּכְשֶׁהוּא כּוֹרֵעַ נוֹתֵן שָׁלוֹם מִשְּׂמֹאל עַצְמוֹ וְאַחַר כָּךְ מִימִין עַצְמוֹ וְאַחַר כָּךְ מַגְבִּיהַּ רֹאשׁוֹ מִן הַכְּרִיעָה. וּכְשֶׁהוּא כּוֹרֵעַ בְּאַרְבַּע הַכְּרִיעוֹת כּוֹרֵעַ בְּבָרוּךְ וּכְשֶׁהוּא זוֹקֵף זוֹקֵף בַּשֵּׁם. בַּמֶּה דְּבָרִים אֲמוּרִים בְּהֶדְיוֹט. אֲבָל כֹּהֵן גָּדוֹל כּוֹרֵעַ בִּתְחִלַּת כָּל בְּרָכָה וּבְסוֹף כָּל בְּרָכָה. וְהַמֶּלֶךְ כֵּיוָן שֶׁשָּׁחָה בָּרִאשׁוֹנָה אֵינוֹ מַגְבִּיהַּ רֹאשׁוֹ עַד שֶׁגּוֹמֵר כָּל תְּפִלָּתוֹ:","וְלָמָּה נוֹתֵן שָׁלוֹם לִשְׂמֹאלוֹ תְּחִלָּה. מִפְּנֵי שֶׁשְּׂמֹאלוֹ הוּא יָמִין שֶׁכְּנֶגֶד פָּנָיו. כְּלוֹמַר כְּשֶׁהוּא עוֹמֵד לִפְנֵי הַמֶּלֶךְ נוֹתֵן שָׁלוֹם לִימִין הַמֶּלֶךְ וְאַחַר כָּךְ לִשְׂמֹאל הַמֶּלֶךְ. וְקָבְעוּ שֶׁיִּפָּטֵר מִן הַתְּפִלָּה כְּמוֹ שֶׁנִּפְטָרִין מִלִּפְנֵי הַמֶּלֶךְ:","כָּל הַכְּרִיעוֹת הָאֵלּוּ צָרִיךְ שֶׁיִּכְרַע בָּהֶן עַד שֶׁיִּתְפַּקְּקוּ כָּל חֻלְיוֹת שֶׁבַּשִּׁדְרָה וְיַעֲשֶׂה עַצְמוֹ כְּקֶשֶׁת. וְאִם שָׁחָה מְעַט וְצִעֵר עַצְמוֹ וְנִרְאֶה כְּכוֹרֵעַ בְּכָל כֹּחוֹ אֵינוֹ חוֹשֵׁשׁ:","הִשְׁתַּחֲוָיָה כֵּיצַד. אַחַר שֶׁמַּגְבִּיהַּ רֹאשׁוֹ מִכְּרִיעָה חֲמִישִׁית יֵשֵׁב לָאָרֶץ וְנוֹפֵל עַל פָּנָיו אַרְצָה וּמִתְחַנֵּן בְּכָל הַתַּחֲנוּנִים שֶׁיִּרְצֶה. כְּרִיעָה הָאֲמוּרָה בְּכָל מָקוֹם עַל בִּרְכַּיִם. קִידָה עַל אַפַּיִם. הִשְׁתַּחֲוָיָה זֶה פִּשּׁוּט יָדַיִם וְרַגְלַיִם עַד שֶׁנִּמְצָא מֻטָּל עַל פָּנָיו אַרְצָה:","כְּשֶׁהוּא עוֹשֶׂה נְפִילַת פָּנִים אַחַר תְּפִלָּה יֵשׁ מִי שֶׁהוּא עוֹשֶׂה קִידָה וְיֵשׁ מִי שֶׁהוּא עוֹשֶׂה הִשְׁתַּחֲוָיָה. וְאָסוּר לַעֲשׂוֹת הִשְׁתַּחֲוָיָה עַל הָאֲבָנִים אֶלָּא בַּמִּקְדָּשׁ כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת עֲבוֹדַת כּוֹכָבִים. וְאֵין אָדָם חָשׁוּב רַשַּׁאי לִפּל עַל פָּנָיו אֶלָּא אִם כֵּן הוּא יוֹדֵעַ בְּעַצְמוֹ שֶׁהוּא צַדִּיק כִּיהוֹשֻׁעַ. אֲבָל מַטֶּה פָּנָיו מְעַט וְאֵינוֹ כּוֹבֵשׁ אוֹתָן בַּקַּרְקַע. וּמֻתָּר לְאָדָם לְהִתְפַּלֵּל בְּמָקוֹם זֶה וְלִפּל עַל פָּנָיו בְּמָקוֹם אַחֵר:","מִנְהָג פָּשׁוּט בְּכָל יִשְׂרָאֵל שֶׁאֵין נְפִילַת אַפַּיִם בְּשַׁבָּתוֹת וּבְמוֹעֲדִים וְלֹא בְּרֹאשׁ הַשָּׁנָה וְלֹא בְּרָאשֵׁי חֳדָשִׁים וּבַחֲנֻכָּה וּבְפוּרִים וְלֹא בְּמִנְחָה שֶׁל עַרְבֵי שַׁבָּתוֹת וְיָמִים טוֹבִים וְלֹא בְּעַרְבִית שֶׁבְּכָל יוֹם. וְיֵשׁ יְחִידִים שֶׁנּוֹפְלִים עַל פְּנֵיהֶם בְּעַרְבִית. וּבְיוֹם הַכִּפּוּרִים בִּלְבַד נוֹפְלִים עַל פְּנֵיהֶם בְּכָל תְּפִלָּה וּתְפִלָּה מִפְּנֵי שֶׁהוּא יוֹם תְּחִנָּה וּבַקָּשָׁה וְתַעֲנִית:"],"Mishneh Torah, Rebels 4":["זֶה שֶׁחָלַק עַל בֵּית דִּין הַגָּדוֹל בְּדָבָר שֶׁחַיָּבִין עַל זְדוֹנוֹ כָּרֵת וְעַל שִׁגְגָתוֹ חַטָּאת. בֵּין שֶׁהָיוּ הֵן אוֹסְרִים וְהוּא מַתִּיר בֵּין שֶׁהָיוּ הֵן מַתִּירִין וְהוּא אוֹסֵר הֲרֵי זֶה חַיָּב מִיתָה. אֲפִלּוּ הוּא הָיָה אוֹמֵר מִפִּי הַקַּבָּלָה וְאָמַר כָּךְ קִבַּלְתִּי מֵרַבּוֹתַי וְהֵן אוֹמְרִים כָּךְ נִרְאֶה בְּעֵינֵינוּ שֶׁהַדִּין נוֹתֵן. הוֹאִיל וְנָשָׂא וְנָתַן עֲלֵיהֶן בַּדָּבָר וְעָשָׂה אוֹ שֶׁהוֹרָה לַעֲשׂוֹת הֲרֵי זֶה חַיָּב. וְאֵין צָרִיךְ לוֹמַר אִם הֵם מוֹרִים מִפִּי הַקַּבָּלָה. וְכֵן אִם חָלַק עֲלֵיהֶם בִּגְזֵרָה מִן הַגְּזֵרוֹת שֶׁגָּזְרוּ בְּדָבָר שֶׁיֵּשׁ בְּשִׁגְגָתוֹ חַטָּאת וּזְדוֹנוֹ כָּרֵת. כְּגוֹן שֶׁהִתִּיר הֶחָמֵץ בְּיוֹם אַרְבָּעָה עָשָׂר בְּנִיסָן בְּשָׁעָה שִׁשִּׁית. אוֹ אֲסָרוֹ בַּהֲנָאָה בְּשָׁעָה חֲמִישִׁית. הֲרֵי זֶה חַיָּב מִיתָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","אֶחָד שֶׁנֶּחְלְקוּ בְּדָבָר שֶׁחַיָּבִין עַל זְדוֹנוֹ כָּרֵת וְעַל שִׁגְגָתוֹ חַטָּאת. אוֹ שֶׁנֶּחְלְקוּ בְּדָבָר הַמֵּבִיא לִידֵי דָּבָר שֶׁחַיָּבִין עַל זְדוֹנוֹ כָּרֵת וְעַל שִׁגְגָתוֹ חַטָּאת. כֵּיצַד. נֶחְלְקוּ בְּאִשָּׁה זוֹ אִם הִיא עֶרְוָה אִם לָאו. אִם מַרְאֵה דָּם זֶה מְטַמֵּא בְּאִשָּׁה אוֹ לֹא. אִם זוֹ טְמֵאָה לֵידָה אוֹ לֹא. אִם זוֹ זָבָה אוֹ לֹא. אִם חֵלֶב זֶה אָסוּר אוֹ מֻתָּר. וְכָל כַּיּוֹצֵא בְּאֵלּוּ. הֲרֵי זֶה חוֹלֵק בְּדָבָר שֶׁחַיָּבִין עַל זְדוֹנוֹ כָּרֵת וְעַל שִׁגְגָתוֹ חַטָּאת. וְכֵיצַד דָּבָר הַמֵּבִיא לִידֵי דָּבָר שֶׁחַיָּבִין עַל זְדוֹנוֹ כָּרֵת וְעַל שִׁגְגָתוֹ חַטָּאת כְּגוֹן שֶׁנֶּחְלְקוּ בְּעִבּוּר שָׁנָה אִם מְעַבְּרִים עַד הַפּוּרִים אוֹ בְּכָל אֲדָר הֲרֵי זֶה חַיָּב שֶׁזֶּה מֵבִיא לִידֵי חָמֵץ בְּפֶסַח. וְכֵן אִם נֶחְלְקוּ בְּדִין מִדִּינֵי מָמוֹנוֹת אוֹ בְּמִנְיַן הַדַּיָּנִין שֶׁדָּנִין דִּינֵי מָמוֹנוֹת הֲרֵי זֶה חַיָּב. שֶׁהֲרֵי לִדְבָרָיו שֶׁל זֶה שֶׁאוֹמֵר שֶׁזֶּה חַיָּב לָזֶה כָּל שֶׁנָּטַל מִמֶּנּוּ כְּדִין נָטַל וְעַל פִּי בֵּית דִּין נָטַל. וְלִדְבָרָיו שֶׁל זֶה שֶׁאוֹמֵר פָּטוּר אוֹ שֶׁאָמַר שֶׁאֵין אֵלּוּ רְאוּיִין לָדוּן כָּל שֶׁנָּטַל גֵּזֶל הוּא בְּיָדוֹ וְאִם קִדֵּשׁ בּוֹ אִשָּׁה אֵינָהּ מְקֻדֶּשֶׁת. וּלְדִבְרֵי הָאוֹמֵר שֶׁלֹּא נָטַל הַבָּא עָלֶיהָ בְּמֵזִיד עָנוּשׁ כָּרֵת בְּשׁוֹגֵג חַיָּב חַטָּאת וְנִמְצָא הַדָּבָר מֵבִיא לִידֵי דָּבָר שֶׁחַיָּבִין עַל זְדוֹנוֹ כָּרֵת וְעַל שִׁגְגָתוֹ חַטָּאת. וְכֵן אִם נֶחְלְקוּ בְּדִינֵי מַכּוֹת אִם זֶה חַיָּב מַלְקוֹת אוֹ אֵינוֹ אוֹ שֶׁחָלַק בְּמִנְיַן הַדַּיָּנִים שֶׁלּוֹקִין בִּפְנֵיהֶם הֲרֵי זֶה חַיָּב שֶׁהֲרֵי לְדִבְרֵי הָאוֹמֵר אֵינוֹ לוֹקֶה חוֹבְלִין הֵם בּוֹ וְחַיָּבִין לְשַׁלֵּם וְכָל שֶׁיִּטּל מֵהֶן כְּדִין נוֹטֵל. וּלְדִבְרֵי הָאוֹמֵר בֶּן מַלְקוֹת הוּא כָּל שֶׁיִּטּל מֵהֶן גֵּזֶל הוּא בְּיָדוֹ וְאִם קִדֵּשׁ בּוֹ אִשָּׁה אֵינָהּ מְקֻדֶּשֶׁת. וְכֵן אִם נֶחְלְקוּ בַּעֲרָכִין אוֹ בַּחֲרָמִין אִם זֶה חַיָּב לִתֵּן אוֹ אֵינוֹ הֲרֵי זֶה חַיָּב. שֶׁהֲרֵי לְדִבְרֵי הָאוֹמֵר אֵינוֹ חַיָּב לִתֵּן אִם לָקְחוּ מִמֶּנּוּ הֲרֵי זֶה גֵּזֶל וְהַמְקַדֵּשׁ בּוֹ אִשָּׁה אֵינָהּ מְקֻדֶּשֶׁת. וְכֵן אִם חָלַק עֲלֵיהֶן בְּפִדְיוֹן קָדָשִׁים אִם נִפְדּוּ אוֹ לֹא נִפְדּוּ הֲרֵי זֶה חַיָּב שֶׁהֲרֵי לְדִבְרֵי הָאוֹמֵר אֵין זֶה פִּדְיוֹן אִם קִדֵּשׁ בּוֹ אִשָּׁה אֵינָהּ מְקֻדֶּשֶׁת. וְכֵן אִם נֶחְלְקוּ בַּעֲרִיפַת הָעֶגְלָה אִם אֵלּוּ חַיָּבִין לְהָבִיא אוֹ לֹא הֲרֵי זֶה חַיָּב שֶׁהֲרֵי לְדִבְרֵי הָאוֹמֵר חַיָּבִים לְהָבִיא הֲרֵי הִיא אֲסוּרָה בַּהֲנָאָה וְהַמְקַדֵּשׁ בּוֹ אִשָּׁה אֵינָהּ מְקֻדֶּשֶׁת. וְכֵן אִם נֶחְלְקוּ בְּעָרְלָה. וְכֵן אִם נֶחְלְקוּ בְּלֶקֶט שִׁכְחָה וּפֵאָה אִם זֶה לַעֲנִיִּים אוֹ לְבַעַל הַבַּיִת הֲרֵי זֶה חַיָּב שֶׁהֲרֵי לְדִבְרֵי הָאוֹמֵר לְבַעַל הַבַּיִת הֲרֵי זֶה גֵּזֶל בְּיַד הֶעָנִי וְאִם קִדֵּשׁ בּוֹ אִשָּׁה אֵינָהּ מְקֻדֶּשֶׁת. וְכֵן אִם חָלַק עֲלֵיהֶן בְּאָב מֵאֲבוֹת הַטֻּמְאָה כְּגוֹן נִגְעֵי בָּשָׂר אוֹ נִגְעֵי בָּתִּים אוֹ נִגְעֵי בְּגָדִים הֲרֵי זֶה חַיָּב שֶׁהֲרֵי לְדִבְרֵי הָאוֹמֵר טָהוֹר מֻתָּר לְהִכָּנֵס בַּמִּקְדָּשׁ לֶאֱכל קָדָשִׁים וּלְדִבְרֵי הָאוֹמֵר טָמֵא אִם נִכְנַס אוֹ אָכַל בְּמֵזִיד עָנוּשׁ כָּרֵת וּבְשׁוֹגֵג חַיָּב חַטָּאת. וְכֵן אִם נֶחְלְקוּ בְּטָהֳרַת מְצֹרָע אִם יֵשׁ לָזֶה טָהֳרָה אוֹ אֵין לוֹ. וְכֵן אִם נֶחְלְקוּ בְּהַשְׁקָאַת סוֹטָה אִם זוֹ צְרִיכָה לִשְׁתּוֹת אוֹ אֵינָהּ צְרִיכָה הֲרֵי זֶה חַיָּב שֶׁהֲרֵי לְדִבְרֵי הָאוֹמֵר צְרִיכָה אִם מֵת הַבַּעַל קֹדֶם שֶׁתִּשְׁתֶּה הֲרֵי זוֹ אֲסוּרָה לִיבָמָהּ וּלְדִבְרֵי הָאוֹמֵר אֵינָהּ צְרִיכָה מִתְיַבֶּמֶת. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה צְרִיכִין לִבְדֹּק וְלַחְקֹר אִם הָיְתָה מַחְלֹקֶת זוֹ מְבִיאָה לִידֵי דָּבָר זֶה וְדָבָר זֶה מֵבִיא לִידֵי דָּבָר שֵׁנִי אֲפִלּוּ אַחַר מֵאָה דְּבָרִים אִם יָבוֹא בַּסּוֹף לְדָבָר שֶׁזְּדוֹנוֹ כָּרֵת וְשִׁגְגָתוֹ חַטָּאת. בֵּין שֶׁהָיָה הַזָּקֵן מֵקֵל וְהֵן מַחֲמִירִין בֵּין שֶׁהָיָה הוּא מַחְמִיר וְהֵן מְקִילִין חַיָּב:","וְאִם לֹא תָּבִיא הַמַּחֲלֹקֶת לִידֵי כָּךְ הֲרֵי זֶה פָּטוּר. חוּץ מִמִּצְוַת תְּפִלִּין בִּלְבַד. כֵּיצַד. הוֹרָה לְהוֹסִיף טוֹטֶפֶת חֲמִישִׁית בַּתְּפִלִּין וְיַעֲשֶׂנָּה חָמֵשׁ טוֹטָפוֹת הֲרֵי זֶה חַיָּב. וְהוּא שֶׁיַּעֲשֶׂה בַּתְּחִלָּה אַרְבָּעָה בָּתִּים כְּהִלְכָתָן וְיָבִיא חֲמִישִׁית וִידַבֵּק בַּחִיצוֹן. שֶׁהַבַּיִת הַחִיצוֹן שֶׁאֵינוֹ רוֹאֶה אֶת הָאֲוִיר תָּמִיד פָּסוּל. וְחִיּוּב זָקֵן מַמְרֵא עַל דָּבָר זֶה הֲלָכָה מִפִּי הַקַּבָּלָה. אֲבָל אִם נֶחְלְקוּ בִּשְׁאָר מִצְוֹת כְּגוֹן שֶׁחָלַק בְּדָבָר מִדִּבְרֵי לוּלָב אוֹ צִיצִית אוֹ שׁוֹפָר זֶה אוֹמֵר פָּסוּל וְזֶה אוֹמֵר כָּשֵׁר. זֶה אוֹמֵר יָצָא יְדֵי חוֹבָתוֹ וְזֶה אוֹמֵר לֹא יָצָא. זֶה אוֹמֵר טָהוֹר וְזֶה אוֹמֵר שֵׁנִי לְטֻמְאָה הֲרֵי זֶה פָּטוּר מִן הַמִּיתָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:"],"Mishneh Torah, Red Heifer 3":["אֵין שׂוֹרְפִין אֶת הַפָּרָה אֶלָּא חוּץ לְהַר הַבַּיִת שֶׁנֶּאֱמַר (במדבר יט ג) \"וְהוֹצִיא אֹתָהּ\" אֶל מִחוּץ לַמַּחֲנֶה. וּבְהַר הַמִּשְׁחָה הָיוּ שׂוֹרְפִין אוֹתָהּ. וְכֶבֶשׁ הָיוּ עוֹשִׂין מֵהַר הַבַּיִת לְהַר הַמִּשְׁחָה וְתַחְתָּיו בָּנוּי כִּפִּין כִּפִּין וְכִפָּה עַל כָּל שְׁנֵי כִּפִּין כְּדֵי שֶׁיִּהְיוּ שְׁנֵי רַגְלֵי הַכִּפָּה עַל גַּג שְׁנֵי כִּפִּין שֶׁתַּחְתֶּיהָ. כְּדֵי שֶׁתִּהְיֶה תַּחַת הַכּל חָלוּל מִפְּנֵי קֶבֶר הַתְּהוֹם. אַף מְקוֹם שְׂרֵפָתָהּ וּמְקוֹם הַטְּבִילָה שֶׁהָיוּ בְּהַר הַמִּשְׁחָה תַּחְתֵּיהֶן חָלוּל מִפְּנֵי קֶבֶר הַתְּהוֹם. וְהַפָּרָה וְהַשּׂוֹרֵף וְכָל הַמְסַעֲדִין בִּשְׂרֵפָתָהּ יוֹצְאִין מֵהַר הַבַּיִת לְהַר הַמִּשְׁחָה עַל גַּבֵּי כֶּבֶשׁ זֶה:","כֵּיצַד שׂוֹרְפִין אוֹתָהּ. זִקְנֵי יִשְׂרָאֵל הָיוּ מַקְדִּימִין בְּרַגְלֵיהֶן לְהַר הַמִּשְׁחָה וּבֵית טְבִילָה הָיָה שָׁם. וְכֹהֵן וְהַמְסַעֲדִין בִּשְׂרֵפָתָהּ וְהַפָּרָה יוֹצְאִין עַל הַכֶּבֶשׁ וּבָאִין לְהַר הַמִּשְׁחָה. וּמְטַמְּאִין אֶת הַכֹּהֵן וְסוֹמְכִין הַזְּקֵנִים אֶת יְדֵיהֶם עַל הַכֹּהֵן וְאוֹמְרִים לוֹ טְבל אַחַת. וְאִם הָיָה כֹּהֵן גָּדוֹל אוֹמְרִים לוֹ אִישִׁי כֹּהֵן גָּדוֹל טְבל אַחַת. יָרַד וְטָבַל וְעָלָה וְנִסְתַּפֵּג. וְעֵצִים מְסֻדָּרִים הָיוּ שָׁם אֲרָזִים אַלּוֹנִים וּבְרוֹשִׁים וַעֲצֵי תְּאֵנָה חֲלָקָה. וְעוֹשִׂין מַעֲרָכָה כְּמִין מִגְדָּל וּמְפַתְּחִין בָּהּ חַלּוֹנוֹת כְּדֵי שֶׁתִּהְיֶה הָאוּר מְלַבֶּבֶת בָּהֶן. וּמַרְאֵה הַמַּעֲרָכָה בְּמַעֲרָב. וְכוֹפְתִין אֶת הַפָּרָה בְּחֶבֶל שֶׁל מֶגֶג וְנוֹתְנִין אוֹתָהּ עַל גַּבֵּי הַמַּעֲרָכָה רֹאשָׁהּ לְדָרוֹם וּפָנֶיהָ לְמַעֲרָב. הַכֹּהֵן עוֹמֵד בַּמִּזְרָח וּפָנָיו לַמַּעֲרָב. שׁוֹחֵט בִּימִינוֹ וּמְקַבֵּל הַדָּם בִּשְׂמֹאלוֹ. וּמַזֶּה בְּאֶצְבָּעוֹ הַיְמָנִית מִן הַדָּם שֶׁבְּכַפּוֹ הַשְּׂמָאלִית שֶׁבַע פְּעָמִים כְּנֶגֶד בֵּית קָדְשֵׁי הַקָּדָשִׁים. עַל כָּל הַזָּאָה טְבִילַת אֶצְבַּע בְּדָם. וּשְׁיָרֵי הַדָּם שֶׁבָּאֶצְבַּע פְּסוּלִים לְהַזָּיָה לְפִיכָךְ עַל כָּל הַזָּאָה מְקַנֵּחַ אֶצְבָּעוֹ בְּגוּפָהּ שֶׁל פָּרָה. גָּמַר מִלְּהַזּוֹת מְקַנֵּחַ אֶת יָדָיו בְּגוּפָהּ שֶׁל פָּרָה וְיוֹרֵד מִן הַמַּעֲרָכָה וְהִצִּית אֶת הָאֵשׁ בְּעֵצִים קְטַנִּים וְהִכְנִיסָן תַּחַת עֲצֵי הַמַּעֲרָכָה וְהִתְחִיל הָאֵשׁ בָּהּ וְהַכֹּהֵן עוֹמֵד בְּרָחוֹק וּמְשַׁמֵּר לָהּ עַד שֶׁיִּצַּת אֶת הָאוּר בְּרֻבָּהּ וְתִקָּרַע בִּטְנָהּ. וְאַחַר כָּךְ נוֹטֵל עֵץ אֶרֶז וְאֵזוֹב אֵין פָּחוֹת מִטֶּפַח וְצֶמֶר צָבוּעַ בְּתוֹלַעַת מִשְׁקַל חֲמִשָּׁה סְלָעִים וְאוֹמֵר לָעוֹמְדִים שָׁם. עֵץ אֶרֶז זֶה עֵץ אֶרֶז זֶה עֵץ אֶרֶז זֶה. אֵזוֹב זֶה אֵזוֹב זֶה אֵזוֹב זֶה. שְׁנִי תּוֹלַעַת זֶה שְׁנִי תּוֹלַעַת זֶה שְׁנִי תּוֹלַעַת זֶה. שָׁלֹשׁ פְּעָמִים עַל כָּל אֶחָד וְאֶחָד. וְהֵן אוֹמְרִין לוֹ הֵין הֵין הֵין שָׁלֹשׁ פְּעָמִים עַל כָּל אֶחָד וְאֶחָד. וְכָל כָּךְ לָמָּה לְפִי שֶׁמִּינֵי אֲרָזִים שִׁבְעָה הֵן וּמִינֵי אֵזוֹב אַרְבָּעָה וְהַצָּבוּעַ אָדֹם יֵשׁ שֶׁצּוֹבְעִין אוֹתוֹ בְּפוּאָה וְיֵשׁ שֶׁצּוֹבְעִין אוֹתוֹ בְּלַכָּא וְיֵשׁ שֶׁצּוֹבְעִין אוֹתוֹ בְּתוֹלַעַת וְהַתּוֹלַעַת הִיא הַגַּרְגְּרִים הָאֲדֻמִּים בְּיוֹתֵר הַדּוֹמִים לְגַרְעִינֵי הֶחָרוּבִים וְהֵן כְּמוֹ הָאוֹג וְתוֹלַעַת כְּמוֹ יַתּוּשׁ יֵשׁ בְּכָל גַּרְגִּיר מֵהֶן וּלְפִיכָךְ מוֹדִיעַ לַכּל וּמְגַלֶּה לָהֶן שֶׁאֵלּוּ הֵן הַמִּינִים הָאֲמוּרִים בַּתּוֹרָה. וְהָאֵזוֹב הָאָמוּר בַּתּוֹרָה הוּא הָאֵזוֹב שֶׁאוֹכְלִין אוֹתוֹ בַּעֲלֵי בָּתִּים וּמְתַבְּלִין בּוֹ הַקְּדֵרוֹת. הָאֵזוֹב וְהָאֶרֶז וְהַתּוֹלַעַת שְׁלָשְׁתָּן מְעַכְּבִין זֶה אֶת זֶה. וְכוֹרֵךְ הָאֵזוֹב עִם הָאֶרֶז בְּלָשׁוֹן שֶׁל שָׁנִי וּמַשְׁלִיךְ אֶל תּוֹךְ בִּטְנָהּ שֶׁנֶּאֱמַר (במדבר יט ו) \"וְהִשְׁלִיךְ אֶל תּוֹךְ שְׂרֵפַת הַפָּרָה\". וְאֵינוֹ מַשְׁלִיךְ קֹדֶם שֶׁיַּצִּית הָאוּר בְּרֻבָּהּ וְלֹא אַחַר שֶׁתֵּעָשֶׂה אֵפֶר וְאִם הִשְׁלִיךְ פְּסוּלָה שֶׁנֶּאֱמַר אֶל תּוֹךְ שְׂרֵפַת לֹא קֹדֶם שֶׁיִּצַּת הָאוּר בְּרֻבָּהּ וְלֹא אַחַר שֶׁתֵּעָשֶׂה אֵפֶר. בֵּין שֶׁהִשְׁלִיךְ שְׁלָשְׁתָּן כְּאַחַת בֵּין שֶׁהִשְׁלִיךְ זֶה אַחַר זֶה בֵּין שֶׁהִשְׁלִיךְ לְתוֹךְ גּוּפָהּ אוֹ לְתוֹךְ שְׂרֵפָתָהּ בֵּין שֶׁנִּקְרְעָה מֵאֵלֶיהָ וְאַחַר כָּךְ הִשְׁלִיךְ בֵּין שֶׁקְּרָעָהּ בְּיָדוֹ אוֹ בִּכְלִי כְּשֵׁרָה:","נִגְמְרָה שְׂרֵפָתָהּ חוֹבְטִין אוֹתָהּ בְּמַקְלוֹת הִיא וְכָל עֲצֵי הַמַּעֲרָכָה שֶׁנִּשְׂרְפָה בָּהֶן וְכוֹבְרִין אֶת הַכּל בִּכְבָרוֹת וְכָל שָׁחֹר שֶׁאֶפְשָׁר שֶׁיִּכָּתֵשׁ וְיִהְיֶה אֵפֶר בֵּין מִבְּשָׂרָהּ בֵּין מִן הָעֵצִים כּוֹתְשִׁין אוֹתוֹ עַד שֶׁיֵּעָשֶׂה אֵפֶר וְשֶׁאֵין בּוֹ אֵפֶר מַנִּיחִין אוֹתוֹ וְכָל עֶצֶם שֶׁנִּשְׁאַר מֵעֲצָמֶיהָ בְּלֹא שְׂרֵפָה בֵּין כָּךְ וּבֵין כָּךְ הָיָה נִכְתַּשׁ:","אֵין מַכְנִיסִין כְּלוּם מֵאֶפְרָהּ לְהַנִּיחוֹ בָּעֲזָרָה שֶׁנֶּאֱמַר (במדבר יט ט) \"וְהִנִּיחַ מִחוּץ לַמַּחֲנֶה\". וּשְׁלֹשָׁה חֲלָקִים הָיוּ חוֹלְקִין אֶת כָּל אֶפְרָהּ אֶחָד נִתַּן בַּחֵיל וְאֶחָד בְּהַר הַמִּשְׁחָה וְאֶחָד מִתְחַלֵּק לְכָל הַמִּשְׁמָרוֹת. זֶה שֶׁמִּתְחַלֵּק לְכָל הַמִּשְׁמָרוֹת הָיוּ הַכֹּהֲנִים מְקַדְּשִׁין מִמֶּנּוּ. וְזֶה שֶׁנִּתַּן בְּהַר הַמִּשְׁחָה הָיוּ יִשְׂרָאֵל מַזִּין מִמֶּנּוּ. וְזֶה שֶׁנִּתַּן בַּחֵיל הָיָה מוּכָן וּמֻצְנָע שֶׁנֶּאֱמַר (במדבר יט ט) \"וְהָיְתָה לַעֲדַת בְּנֵי יִשְׂרָאֵל לְמִשְׁמֶרֶת\" מְלַמֵּד שֶׁמַּצְנִיעִין מִמֶּנּוּ. וְכֵן הָיוּ מַצְנִיעִין מֵאֵפֶר כָּל פָּרָה וּפָרָה שֶׁשּׂוֹרְפִין בַּחֵיל. וְתֵשַׁע פָּרוֹת אֲדֻמּוֹת נַעֲשׂוּ מִשֶּׁנִּצְטַוּוּ בְּמִצְוָה זוֹ עַד שֶׁחָרַב הַבַּיִת בַּשְּׁנִיָּה. רִאשׁוֹנָה עָשָׂה משֶׁה רַבֵּנוּ. שְׁנִיָּה עָשָׂה עֶזְרָא. וְשֶׁבַע מֵעֶזְרָא עַד חֻרְבַּן הַבַּיִת. וְהָעֲשִׂירִית יַעֲשֶׂה הַמֶּלֶךְ הַמָּשִׁיחַ מְהֵרָה יִגָּלֶה אָמֵן כֵּן יְהִי רָצוֹן:"],"Mishneh Torah, Repentance 5":["רְשׁוּת לְכָל אָדָם נְתוּנָה. אִם רָצָה לְהַטּוֹת עַצְמוֹ לְדֶרֶךְ טוֹבָה וְלִהְיוֹת צַדִּיק הָרְשׁוּת בְּיָדוֹ. וְאִם רָצָה לְהַטּוֹת עַצְמוֹ לְדֶרֶךְ רָעָה וְלִהְיוֹת רָשָׁע הָרְשׁוּת בְּיָדוֹ. הוּא שֶׁכָּתוּב בַּתּוֹרָה (בראשית ג כב) \"הֵן הָאָדָם הָיָה כְּאַחַד מִמֶּנּוּ לָדַעַת טוֹב וָרָע\". כְּלוֹמַר הֵן מִין זֶה שֶׁל אָדָם הָיָה יָחִיד בָּעוֹלָם וְאֵין מִין שֵׁנִי דּוֹמֶה לוֹ בְּזֶה הָעִנְיָן שֶׁיְּהֵא הוּא מֵעַצְמוֹ בְּדַעְתּוֹ וּבְמַחֲשַׁבְתּוֹ יוֹדֵעַ הַטּוֹב וְהָרַע וְעוֹשֶׂה כָּל מַה שֶּׁהוּא חָפֵץ וְאֵין מִי שֶׁיְּעַכֵּב בְּיָדוֹ מִלַּעֲשׂוֹת הַטּוֹב אוֹ הָרַע. וְכֵיוָן שֶׁכֵּן הוּא פֶּן יִשְׁלַח יָדוֹ:","אַל יַעֲבֹר בְּמַחֲשַׁבְתְּךָ דָּבָר זֶה שֶׁאוֹמְרִים טִפְּשֵׁי אֻמּוֹת הָעוֹלָם וְרֹב גָּלְמֵי בְּנֵי יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא גּוֹזֵר עַל הָאָדָם מִתְּחִלַּת בְּרִיָּתוֹ לִהְיוֹת צַדִּיק אוֹ רָשָׁע. אֵין הַדָּבָר כֵּן אֶלָּא כָּל אָדָם רָאוּי לוֹ לִהְיוֹת צַדִּיק כְּמשֶׁה רַבֵּנוּ אוֹ רָשָׁע כְּיָרָבְעָם אוֹ חָכָם אוֹ סָכָל אוֹ רַחֲמָן אוֹ אַכְזָרִי אוֹ כִּילַי אוֹ שׁוּעַ וְכֵן שְׁאָר כָּל הַדֵּעוֹת. וְאֵין לוֹ מִי שֶׁיִּכְפֵּהוּ וְלֹא גּוֹזֵר עָלָיו וְלֹא מִי שֶׁמּוֹשְׁכוֹ לְאֶחָד מִשְּׁנֵי הַדְּרָכִים אֶלָּא הוּא מֵעַצְמוֹ וּמִדַּעְתּוֹ נוֹטֶה לְאֵי זוֹ דֶּרֶךְ שֶׁיִּרְצֶה. הוּא שֶׁיִּרְמְיָהוּ אָמַר (איכה ג לח) \"מִפִּי עֶלְיוֹן לֹא תֵצֵא הָרָעוֹת וְהַטּוֹב\". כְּלוֹמַר אֵין הַבּוֹרֵא גּוֹזֵר עַל הָאָדָם לִהְיוֹת טוֹב וְלֹא לִהְיוֹת רַע. וְכֵיוָן שֶׁכֵּן הוּא נִמְצָא זֶה הַחוֹטֵא הוּא הִפְסִיד אֶת עַצְמוֹ. וּלְפִיכָךְ רָאוּי לוֹ לִבְכּוֹת וּלְקוֹנֵן עַל חֲטָאָיו וְעַל מַה שֶּׁעָשָׂה לְנַפְשׁוֹ וּגְמָלָהּ רָעָה. הוּא שֶׁכָּתוּב אַחֲרָיו (איכה ג לט) \"מַה יִּתְאוֹנֵן אָדָם חָי\" וְגוֹ'. וְחָזַר וְאָמַר הוֹאִיל וּרְשׁוּתֵנוּ בְּיָדֵינוּ וּמִדַּעְתֵּנוּ עָשִׂינוּ כָּל הָרָעוֹת רָאוּי לָנוּ לַחֲזֹר בִּתְשׁוּבָה וְלַעֲזֹב רִשְׁעֵנוּ שֶׁהָרְשׁוּת עַתָּה בְּיָדֵינוּ. הוּא שֶׁכָּתוּב אַחֲרָיו (איכה ג מ) \"נַחְפְּשָׂה דְרָכֵינוּ וְנַחְקֹרָה וְנָשׁוּבָה\" וְגוֹ':","וְדָבָר זֶה עִקָּר גָּדוֹל הוּא וְהוּא עַמּוּד הַתּוֹרָה וְהַמִּצְוָה שֶׁנֶּאֱמַר (דברים ל טו) \"רְאֵה נָתַתִּי לְפָנֶיךָ הַיּוֹם אֶת הַחַיִּים\". וּכְתִיב (דברים יא כו) \"רְאֵה אָנֹכִי נֹתֵן לִפְנֵיכֶם הַיּוֹם\". כְּלוֹמַר שֶׁהָרְשׁוּת בְּיֶדְכֶם. וְכָל שֶׁיַּחְפֹּץ הָאָדָם לַעֲשׂוֹת מִמַּעֲשֵׂה בְּנֵי הָאָדָם עוֹשֶׂה בֵּין טוֹבִים בֵּין רָעִים. וּמִפְּנֵי זֶה הָעִנְיָן נֶאֱמַר (דברים ה כו) \"מִי יִתֵּן וְהָיָה לְבָבָם זֶה לָהֶם\". כְּלוֹמַר שֶׁאֵין הַבּוֹרֵא כּוֹפֶה בְּנֵי הָאָדָם וְלֹא גּוֹזֵר עֲלֵיהֶן לַעֲשׂוֹת טוֹבָה אוֹ רָעָה אֶלָּא הַכּל מָסוּר לָהֶם:","אִלּוּ הָאֵל הָיָה גּוֹזֵר עַל הָאָדָם לִהְיוֹת צַדִּיק אוֹ רָשָׁע אוֹ אִלּוּ הָיָה שָׁם דָּבָר שֶׁמּוֹשֵׁךְ אֶת הָאָדָם בְּעִקַּר תּוֹלַדְתּוֹ לְדֶרֶךְ מִן הַדְּרָכִים אוֹ לְמַדָּע מִן הַמַּדָּעוֹת אוֹ לְדֵעָה מִן הַדֵּעוֹת אוֹ לְמַעֲשֶׂה מִן הַמַּעֲשִׂים כְּמוֹ שֶׁבּוֹדִים מִלִּבָּם הַטִּפְּשִׁים הֹבְרֵי שָׁמַיִם הֵיאַךְ הָיָה מְצַוֶּה לָנוּ עַל יְדֵי הַנְּבִיאִים עֲשֵׂה כָּךְ וְאַל תַּעֲשֶׂה כָּךְ הֵיטִיבוּ דַּרְכֵיכֶם וְאַל תֵּלְכוּ אַחֲרֵי רִשְׁעֲכֶם וְהוּא מִתְּחִלַּת בְּרִיָּתוֹ כְּבָר נִגְזַר עָלָיו אוֹ תּוֹלַדְתּוֹ תִּמְשֹׁךְ אוֹתוֹ לְדָבָר שֶׁאִי אֶפְשָׁר לָזוּז מִמֶּנּוּ. וּמַה מָּקוֹם הָיָה לְכָל הַתּוֹרָה כֻּלָּהּ וּבְאֵי זֶה דִּין וְאֵיזֶה מִשְׁפָּט נִפְרָע מִן הָרָשָׁע אוֹ מְשַׁלֵּם שָׂכָר לַצַּדִּיק. הֲשֹׁפֵט כָּל הָאָרֶץ לֹא יַעֲשֶׂה מִשְׁפָּט. וְאַל תִּתְמַהּ וְתֹאמַר הֵיאַךְ יִהְיֶה הָאָדָם עוֹשֶׂה כָּל מַה שֶּׁיַּחְפֹּץ וְיִהְיוּ מַעֲשָׂיו מְסוּרִים לוֹ וְכִי יֵעָשֶׂה בָּעוֹלָם דָּבָר שֶׁלֹּא בִּרְשׁוּת קוֹנוֹ וְלֹא חֶפְצוֹ וְהַכָּתוּב אוֹמֵר (תהילים קלה ו) \"כּל אֲשֶׁר חָפֵץ ה' עָשָׂה בַּשָּׁמַיִם וּבָאָרֶץ\". דַּע שֶׁהַכּל כְּחֶפְצוֹ יֵעָשֶׂה וְאַף עַל פִּי שֶׁמַּעֲשֵׂינוּ מְסוּרִין לָנוּ. כֵּיצַד. כְּשֵׁם שֶׁהַיּוֹצֵר חָפֵץ לִהְיוֹת הָאֵשׁ וְהָרוּחַ עוֹלִים לְמַעְלָה וְהַמַּיִם וְהָאָרֶץ יוֹרְדִים לְמַטָּה וְהַגַּלְגַּל סוֹבֵב בְּעִגּוּל וְכֵן שְׁאָר בְּרִיּוֹת הָעוֹלָם לִהְיוֹת כְּמִנְהָגָן שֶׁחָפֵץ בּוֹ. כָּכָה חָפֵץ לִהְיוֹת הָאָדָם רְשׁוּתוֹ בְּיָדוֹ וְכָל מַעֲשָׂיו מְסוּרִין לוֹ וְלֹא יִהְיֶה לוֹ לֹא כּוֹפֶה וְלֹא מוֹשֵׁךְ אֶלָּא הוּא מֵעַצְמוֹ וּבְדַעְתּוֹ שֶׁנָּתַן לוֹ הָאֵל עוֹשֶׂה כָּל שֶׁהָאָדָם יָכוֹל לַעֲשׂוֹת. לְפִיכָךְ דָּנִין אוֹתוֹ לְפִי מַעֲשָׂיו. אִם עָשָׂה טוֹבָה מֵיטִיבִין לוֹ וְאִם עָשָׂה רָעָה מְרֵעִין לוֹ. הוּא שֶׁהַנָּבִיא אוֹמֵר (מלאכי א ט) מִיֶּדְכֶם הָיְתָה זֹּאת לָכֶם. (ישעיה סו ג) גַּם הֵמָּה בָּחֲרוּ בְּדַרְכֵיהֶם. וּבְעִנְיָן זֶה אָמַר שְׁלֹמֹה (קהלת יא ט) \"שְׂמַח בָּחוּר בְּיַלְדוּתֶיךָ\" (קהלת יא ט) \"וְדָע כִּי עַל כָּל אֵלֶּה יְבִיאֲךָ הָאֱלֹהִים בַּמִּשְׁפָּט\". כְּלוֹמַר דַּע שֶׁיֵּשׁ בְּיָדְךָ כֹּחַ לַעֲשׂוֹת וְעָתִיד אַתָּה לִתֵּן אֶת הַדִּין:","שֶׁמָּא תֹּאמַר וַהֲלֹא הַקָּדוֹשׁ בָּרוּךְ הוּא יוֹדֵעַ כָּל מַה שֶּׁיִּהְיֶה וְקֹדֶם שֶׁיִּהְיֶה יֵדַע שֶׁזֶּה יִהְיֶה צַדִּיק אוֹ רָשָׁע אוֹ לֹא יֵדַע. אִם יֵדַע שֶׁהוּא יִהְיֶה צַדִּיק אִי אֶפְשָׁר שֶׁלֹּא יִהְיֶה צַדִּיק וְאִם תֹּאמַר שֶׁיֵּדַע שֶׁיִּהְיֶה צַדִּיק וְאֶפְשָׁר שֶׁיִּהְיֶה רָשָׁע הֲרֵי לֹא יֵדַע הַדָּבָר עַל בֻּרְיוֹ. דַּע שֶׁתְּשׁוּבַת שְׁאֵלָה זוֹ אֲרֻכָּה מֵאֶרֶץ מִדָּה וּרְחָבָה מִנִּי יָם וְכַמָּה עִקָּרִים גְּדוֹלִים וַהֲרָרִים רָמִים תְּלוּיִים בָּהּ אֲבָל צָרִיךְ אַתָּה לֵידַע וּלְהָבִין בְּדָבָר זֶה שֶׁאֲנִי אוֹמֵר. כְּבָר בֵּאַרְנוּ בְּפֶרֶק שֵׁנִי מֵהִלְכוֹת יְסוֹדֵי הַתּוֹרָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא אֵינוֹ יוֹדֵעַ מִדֵּעָה שֶׁהִיא חוּץ מִמֶּנּוּ כִּבְנֵי אָדָם שֶׁהֵם וְדַעְתָּם שְׁנַיִם. אֶלָּא הוּא יִתְעַלֶּה שְׁמוֹ וְדַעְתּוֹ אֶחָד וְאֵין דַּעְתּוֹ שֶׁל אָדָם יְכוֹלָה לְהַשִּׂיג דָּבָר זֶה עַל בֻּרְיוֹ. וּכְשֵׁם שֶׁאֵין כֹּחַ בָּאָדָם לְהַשִּׂיג וְלִמְצֹא אֲמִתַּת הַבּוֹרֵא שֶׁנֶּאֱמַר (שמות לג כ) \"כִּי לֹא יִרְאַנִי הָאָדָם וָחָי\" כָּךְ אֵין כֹּחַ בָּאָדָם לְהַשִּׂיג וְלִמְצֹא דַּעְתּוֹ שֶׁל הַבּוֹרֵא. הוּא שֶׁהַנָּבִיא אָמַר (ישעיה נה ח) \"כִּי לֹא מַחְשְׁבוֹתַי מַחְשְׁבוֹתֵיכֶם וְלֹא דַרְכֵיכֶם דְרָכָי\". וְכֵיוָן שֶׁכֵּן הוּא אֵין בָּנוּ כֹּחַ לֵידַע הֵיאַךְ יֵדַע הַקָּדוֹשׁ בָּרוּךְ הוּא כָּל הַבְּרוּאִים וְהַמַּעֲשִׂים אֲבָל נֵדַע בְּלֹא סָפֵק שֶׁמַּעֲשֵׂה הָאָדָם בְּיַד הָאָדָם וְאֵין הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹשְׁכוֹ וְלֹא גּוֹזֵר עָלָיו לַעֲשׂוֹת כָּךְ. וְלֹא מִפְּנֵי קַבָּלַת הַדָּת בִּלְבַד נוֹדַע דָּבָר זֶה אֶלָּא בִּרְאָיוֹת בְּרוּרוֹת מִדִּבְרֵי הַחָכְמָה. וּמִפְּנֵי זֶה נֶאֱמַר בַּנְּבוּאָה שֶׁדָּנִין אֶת הָאָדָם עַל מַעֲשָׂיו כְּפִי מַעֲשָׂיו אִם טוֹב וְאִם רַע וְזֶה הוּא הָעִקָּר שֶׁכָּל דִּבְרֵי הַנְּבוּאָה תְּלוּיִין בּוֹ:"],"Mishneh Torah, Rest on a Holiday 8":["נְּהָרוֹת הַמּוֹשְׁכִין מִן הָאֲגַמִּים מֻתָּר לְהַשְׁקוֹת מֵהֶן בֵּית הַשְּׁלָחִין בַּמּוֹעֵד וְהוּא שֶׁלֹּא פָּסְקוּ. וְכֵן הַבְּרֵכוֹת שֶׁאַמַּת הַמַּיִם עוֹבֶרֶת בֵּינֵיהֶן מֻתָּר לְהַשְׁקוֹת מֵהֶן. וְכֵן בְּרֵכָה שֶׁנָּטְפָה מִבֵּית הַשְּׁלָחִין וַעֲדַיִן הִיא נוֹטֶפֶת מֻתָּר לְהַשְׁקוֹת מִמֶּנָּה בֵּית הַשְּׁלָחִין אַחֶרֶת. וְהוּא שֶׁלֹּא פָּסַק הַמַּעְיָן הַמַּשְׁקֶה בֵּית הַשְּׁלָחִין הָעֶלְיוֹנָה:","עֲרוּגָה שֶׁחֶצְיָהּ נָמוּךְ וְחֶצְיָהּ גָּבוֹהַּ לֹא יִדְלֶה מִמָּקוֹם נָמוּךְ לְהַשְׁקוֹת מָקוֹם גָּבוֹהַּ מִפְּנֵי שֶׁהוּא טֹרַח גָּדוֹל. וּמֻתָּר לִדְלוֹת מַיִם לְהַשְׁקוֹת הַיְרָקוֹת כְּדֵי לְאָכְלָן בַּמּוֹעֵד. וְאִם בִּשְׁבִיל לְיַפּוֹתָן אָסוּר:","אֵין עוֹשִׂין עוּגִיּוֹת בְּעִקְּרֵי הַגְּפָנִים כְּדֵי שֶׁיִּתְמַלְּאוּ מַיִם. וְאִם הָיוּ עֲשׂוּיוֹת וְנִתְקַלְקְלוּ הֲרֵי זֶה מְתַקְּנָם בַּמּוֹעֵד. וְכֵן אַמַּת הַמַּיִם שֶׁנִּתְקַלְקְלָה מְתַקְּנִין אוֹתָהּ בַּמּוֹעֵד. כֵּיצַד. הָיְתָה עֲמֻקָּה טֶפַח חוֹפֵר בָּהּ עַד שִׁשָּׁה. הָיְתָה עֲמֻקָּה טְפָחַיִם מַעֲמִיקָהּ עַד שִׁבְעָה. וּמוֹשְׁכִין אֶת הַמַּיִם מֵאִילָן לְאִילָן וּבִלְבַד שֶׁלֹּא יַשְׁקֶה אֶת כָּל הַשָּׂדֶה. וְאִם הָיְתָה שָׂדֶה לָחָה מֻתָּר לְהַשְׁקוֹת אֶת כֻּלָּהּ. וּמַרְבִּיצִין אֶת הַשָּׂדֶה בַּמּוֹעֵד. שֶׁכָּל הַדְּבָרִים הָאֵלּוּ אֵין בָּהֶן טֹרַח יוֹתֵר:","זְרָעִים שֶׁלֹּא שָׁתוּ מִלִּפְנֵי הַמּוֹעֵד לֹא יַשְׁקֵם בַּמּוֹעֵד מִפְּנֵי שֶׁהֵן צְרִיכִין מַיִם רַבִּים וְיָבוֹא לִידֵי טֹרַח יוֹתֵר. וּמֻתָּר לְהָסֵב אֶת הַנָּהָר מִמָּקוֹם לְמָקוֹם וְלִפְתֹּחַ נָהָר שֶׁנִּסְתַּם. בּוֹרוֹת שִׁיחִין וּמְעָרוֹת שֶׁל יָחִיד אִם הָיָה צָרִיךְ לָהֶם חוֹטְטִין אוֹתָן וְשָׁפִין אֶת סִדְקֵיהֶם אֲבָל אֵין חוֹפְרִין אוֹתָן לְכַתְּחִלָּה. וְכוֹנְסִים לְתוֹכָהּ מַיִם אַף עַל פִּי שֶׁאֵינוֹ צָרִיךְ לָהֶן. וְעוֹשִׂין נִבְרֶכֶת בַּמּוֹעֵד:","עַכְבָּרִים שֶׁהֵן מַפְסִידִין אֶת הָאִילָנוֹת צָדִין אוֹתָן בַּמּוֹעֵד. בִּשְׂדֵה הָאִילָן צָד כְּדַרְכּוֹ. כֵּיצַד. חוֹפֵר וְתוֹלֶה הַמְּצוּדָה. וְאִם הָיָה שָׂדֶה לָבָן סָמוּךְ לִשְׂדֵה הָאִילָן צָדִין אוֹתָן בַּשָּׂדֶה הַלָּבָן בְּשִׁנּוּי כְּדֵי שֶׁלֹּא יִכָּנְסוּ לִשְׂדֵה הָאִילָן וְיַחְרִיבוּהָ. וְכֵיצַד צָד, בְּשִׁנּוּי. נוֹעֵץ שִׁפּוּד בָּאָרֶץ וּמַכֶּה בְּקוֹרְדוֹם וְאַחַר כָּךְ מְנַתְּקוֹ וְנִמְצָא מְקוֹמוֹ גּוּמָא:","כֹּתֶל גִּנָּה שֶׁנָּפַל בּוֹנֵהוּ מַעֲשֵׂה הֶדְיוֹט אוֹ גּוֹדֵר אוֹתוֹ בְּקָנִים וְגֹמֶא וְכַיּוֹצֵא בָּהֶן. וְכֵן אִם עָשָׂה מַעֲקֶה לַגַּג בּוֹנֶה אוֹתוֹ מַעֲשֵׂה הֶדְיוֹט. אֲבָל כֹּתֶל חָצֵר שֶׁנָּפַל בּוֹנֵהוּ כְּדַרְכּוֹ. וְאִם הָיָה גּוֹהֶה סוֹתְרוֹ מִפְּנֵי הַסַּכָּנָה וּבוֹנֵהוּ כְּדַרְכּוֹ:","בּוֹנֶה אָדָם אִצְטַבָּא לֵישֵׁב אוֹ לִישֹׁן עָלֶיהָ. הַצִּיר וְהַצִּנּוֹר וְהַקּוֹרָה וְהַמַּנְעוּל וְהַמַּפְתֵּחַ שֶׁנִּשְׁבְּרוּ מְתַקְּנָן בַּמּוֹעֵד כְּדַרְכּוֹ בֵּין בְּשֶׁל בַּרְזֶל בֵּין בְּשֶׁל עֵץ. שֶׁזֶּה הֶפְסֵד גָּדוֹל הוּא שֶׁאִם יָנִיחַ הַפֶּתַח פָּתוּחַ וּדְלָתוֹת שְׁבוּרוֹת נִמְצָא מְאַבֵּד כָּל מַה שֶּׁבַּבַּיִת. וּכְבָר בֵּאַרְנוּ כָּל שֶׁיֵּשׁ בּוֹ הֶפְסֵד אֵינוֹ צָרִיךְ שִׁנּוּי:","אֵין חוֹפְרִין קֶבֶר לִהְיוֹת מוּכָן לְמֵת שֶׁיָּמוּת וְאֵין בּוֹנִין אוֹתוֹ. אֲבָל אִם הָיָה עָשׂוּי הֲרֵי זֶה מְתַקְּנוֹ בַּמּוֹעֵד. כֵּיצַד. מוֹסִיף בְּמִדָּתוֹ אוֹ מְקַצֵּר מִמִּדָּתוֹ כְּדֵי שֶׁיִּהְיֶה נָכוֹן לְעֵת שֶׁיִּקְבֹּר בּוֹ:","אֵין מְפַנִּין אֶת הַמֵּת וְלֹא אֶת הָעֲצָמוֹת מִקֶּבֶר לְקֶבֶר לֹא מִמְּכֻבָּד לְבָזוּי וְלֹא מִבָּזוּי לִמְכֻבָּד. וְאָסוּר לַעֲשׂוֹת כֵּן לְעוֹלָם בִּשְׁאָר הַיָּמִים אֶלָּא אִם כֵּן הָיָה מְפַנֵּהוּ בְּתוֹךְ שֶׁלּוֹ מְפַנֵּהוּ בִּשְׁאָר הַיָּמִים אֲפִלּוּ מִמְּכֻבָּד לְבָזוּי:","אֵין מַתְלִיעִין אֶת הָאִילָנוֹת וְלֹא מַזְהִימִין אֶת הַנְּטִיעוֹת וְלֹא מְגַזְּמִין. אֲבָל סָכִין אֶת הָאִילָנוֹת וְאֶת הַפֵּרוֹת שֶׁבָּהֶן בְּשֶׁמֶן וְעוֹקְרִין אֶת הַפִּשְׁתָּה מִפְּנֵי שֶׁהִיא רְאוּיָה לַחֲפֹף בָּהּ בַּמּוֹעֵד. וְקוֹצְרִין אֶת הַכִּשּׁוּת מִפְּנֵי שֶׁהִיא רְאוּיָה לְהַטִּילָהּ לְשֵׁכָר בַּמּוֹעֵד. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","אֵין מְכַנְּסִין אֶת הַצֹּאן לַדִּיר כְּדֵי שֶׁיְּזַבְּלוּ אֶת הַקַּרְקַע. שֶׁהֲרֵי הוּא מְדַיֵּיר שָׂדֵהוּ בַּמּוֹעֵד. וְאִם בָּאוּ מֵאֲלֵיהֶן מֻתָּר. וְאֵין מְסַיְּעִין אוֹתָן וְאֵין מוֹסְרִין לָהֶן שׁוֹמֵר לְנַעֵר אֶת הַצֹּאן. הָיָה שְׂכִיר שַׁבָּת שְׂכִיר חֹדֶשׁ שְׂכִיר שָׁנָה שְׂכִיר שָׁבוּעַ מְסַיְּעִין אוֹתָן וְשׂוֹכְרִין שׁוֹמֵר לְנַעֵר אֶת צֹאנָם מִמָּקוֹם לְמָקוֹם כְּדֵי שֶׁיְּזַבְּלוּ כָּל הַשָּׂדֶה. הַזֶּבֶל שֶׁבֶּחָצֵר מְסַלְּקִין אוֹתוֹ לַצְּדָדִין. וְאִם נַעֲשָׂה חָצֵר כְּרֶפֶת בָּקָר מוֹצִיאִין אוֹתוֹ לָאַשְׁפָּה:","הַמַּשְׁוֶה פְּנֵי הַקַּרְקַע אִם נִתְכַּוֵּן לְתַקֵּן מָקוֹם שֶׁיַּעֲמִיד בּוֹ כְּרִי שֶׁל תְּבוּאָה אוֹ שֶׁיָּדוּשׁ בּוֹ מֻתָּר. וְאִם נִתְכַּוֵּן לַעֲבוֹדַת הָאָרֶץ אָסוּר. וְכֵן הַמְלַקֵּט עֵצִים מִתּוֹךְ שָׂדֵהוּ אִם לְצֹרֶךְ עֵצִים מֻתָּר וְאִם לְתַקֵּן הַקַּרְקַע אָסוּר. וְכֵן הַפּוֹתֵק מַיִם לְגִנָּה אִם נִתְכַּוֵּן שֶׁיִּכָּנְסוּ הַדָּגִים מֻתָּר וְאִם לְהַשְׁקוֹת הָאָרֶץ אָסוּר. וְכֵן הַקּוֹצֵץ חֲרָיוֹת מִן הַדֶּקֶל אִם נִתְכַּוֵּן לְהַאֲכִיל לַבְּהֵמָה מֻתָּר וְאִם נִתְכַּוֵּן לַעֲבוֹדַת הָאִילָן אָסוּר. וּמִמַּעֲשָׂיו יֻכַּר לְאֵי זֶה דָּבָר הוּא מִתְכַּוֵּן:","תַּנּוּר וְכִירַיִם שֶׁאֶפְשָׁר שֶׁיִיבְשׁוּ וְיֹאפֶה בָּהֶן בַּמּוֹעֵד עוֹשִׂין וְאִם לָאו אֵין עוֹשִׂין אוֹתָן. ובֵּין כָּךְ וּבֵין כָּךְ בּוֹנִין עַל חֶרֶשׂ שֶׁל תַּנּוּר וְעַל הִכִּירָה הַטְּפֵלָה שֶׁלָּהֶן וּמְסָרְגִין אֶת הַמִּטּוֹת. וְנוֹקְרִין אֶת הָרֵחָיִם וּפוֹתְחִים לָהֶן עַיִן וּמַעֲמִידִין אוֹתָן וּבוֹנִין אַמַּת הַמַּיִם שֶׁל רֵחַיִם:","זוֹפְתִין אֶת הֶחָבִית כְּדֵי שֶׁלֹּא יִפָּסֵד הַיַּיִן. וְזוֹפְתִין אֶת הַבַּקְבּוּק מִפְּנֵי שֶׁאֵין בּוֹ טֹרַח. וְסוֹתְמִין פִּי הֶחָבִית שֶׁל שֵׁכָר כְּדֵי שֶׁלֹּא תִּפָּסֵד. וּמְחַפִּין אֶת הַקְּצִיעוֹת בְּקַשׁ כְּדֵי שֶׁלֹּא יֹאבְדוּ. וּמְרַכְּכִין אֶת הַבְּגָדִים בַּיָּדַיִם. מִפְּנֵי שֶׁהוּא מַעֲשֵׂה הֶדְיוֹט. אֲבָל אֵין עוֹשִׂין קִשְׁרֵי בֵּית הַיָּדַיִם מִפְּנֵי שֶׁהוּא מַעֲשֵׂה אֻמָּן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","קוֹצְצִין צִפָּרְנֵי חֲמוֹר שֶׁל רֵחַיִם וּבוֹנִין אֵבוּס לַבְּהֵמָה. וְסוּס שֶׁיִּרְכַּב עָלָיו מֻתָּר לִטּל צִפָּרְנָיו וּלְסָרְקוֹ כְּדֵי לְיַפּוֹתוֹ. וְאֵין מַרְבִּיעִין בְּהֵמָה בַּמּוֹעֵד. אֲבָל מַקִּיזִין לָהּ דָּם. וְאֵין מוֹנְעִין מִמֶּנָּה רְפוּאָה. וְכָל מַאֲכָלוֹת וּמַשְׁקִים שֶׁאֵינָן מַאֲכַל בְּרִיאִים אֶלָּא לִרְפוּאָה מֻתָּר לָאָדָם לְאָכְלָן וְלִשְׁתּוֹתָן בַּמּוֹעֵד:","אֵין מְפַנִּין מֵחָצֵר לְחָצֵר בַּמּוֹעֵד. וְלֹא מִכְּעוּרָה לְנָאָה וְלֹא מִנָּאָה לִכְעוּרָה. אֲבָל מְפַנֶּה הוּא מִבַּיִת לְבַיִת בְּאוֹתָהּ חָצֵר. וּמְבִיאִין כֵּלִים שֶׁהֵן לְצֹרֶךְ הַמּוֹעֵד מִבֵּית הָאֻמָּן. כְּגוֹן כָּרִים וּכְסָתוֹת וּצְלוֹחִיּוֹת. אֲבָל כֵּלִים שֶׁאֵינָן לְצֹרֶךְ הַמּוֹעֵד כְּגוֹן מַחְרֵשָׁה מִן הַלּוֹטֵשׁ אוֹ צֶמֶר מִבֵּית הַצַּבָּע אֵין מְבִיאִין. וְאִם אֵין לָאֻמָּן מַה יֹּאכַל נוֹתֵן לוֹ שְׂכָרוֹ וּמַנִּיחָן אֶצְלוֹ. וְאִם אֵינוֹ מַאֲמִינוֹ מַנִּיחָן בַּבַּיִת הַסָּמוּךְ לוֹ. וְאִם חוֹשֵׁשׁ לָהֶם שֶׁמָּא יִגָּנְבוּ מְפַנָּן לְחָצֵר אַחֶרֶת אֲבָל לֹא יָבִיא לְבֵיתוֹ אֶלָּא בְּצִנְעָה:","אָסוּר לַעֲשׂוֹת מְלָאכָה בְּעַרְבֵי יָמִים טוֹבִים מִן הַמִּנְחָה וּלְמַעְלָה כְּמוֹ עַרְבֵי שַׁבָּתוֹת. וְכָל הָעוֹשֶׂה מְלָאכָה בָּהֶן אֵינוֹ רוֹאֶה סִימָן בְּרָכָה לְעוֹלָם. וְגוֹעֲרִין בּוֹ וּמְבַטְּלִין אוֹתוֹ בְּעַל כָּרְחוֹ. אֲבָל אֵין מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. וְאֵין צָרִיךְ לוֹמַר שֶׁאֵין מְנַדִּין אוֹתוֹ. חוּץ מֵעֶרֶב הַפֶּסַח אַחַר חֲצוֹת שֶׁהָעוֹשֶׂה בּוֹ מְלָאכָה אַחַר חֲצוֹת מְנַדִּין אוֹתוֹ. וְאֵין צָרִיךְ לוֹמַר שֶׁמַּכִּין אוֹתוֹ מַכַּת מַרְדּוּת אִם לֹא נִדּוּהוּ. לְפִי שֶׁיּוֹם אַרְבָּעָה עָשָׂר בְּנִיסָן אֵינוֹ כִּשְׁאָר עַרְבֵי יָמִים טוֹבִים מִפְּנֵי שֶׁיֵּשׁ בּוֹ חֲגִיגָה וּשְׁחִיטַת קָרְבָּן:","לְפִיכָךְ יוֹם אַרְבָּעָה עָשָׂר בְּנִיסָן אָסוּר בַּעֲשִׂיַּת מְלָאכָה מִדִּבְרֵי סוֹפְרִים כְּמוֹ חֻלּוֹ שֶׁל מוֹעֵד. וְהוּא קַל מֵחֻלּוֹ שֶׁל מוֹעֵד. וְאֵינוֹ אָסוּר אֶלָּא מֵחֲצִי הַיּוֹם וּלְמַעְלָה שֶׁהוּא זְמַן הַשְּׁחִיטָה. אֲבָל מֵהָנֵץ הַחַמָּה עַד חֲצִי הַיּוֹם תָּלוּי בַּמִּנְהָג. מָקוֹם שֶׁנָּהֲגוּ לַעֲשׂוֹת עוֹשִׂין מָקוֹם שֶׁנָּהֲגוּ שֶׁלֹּא לַעֲשׂוֹת אֵין עוֹשִׂין:","וַאֲפִלּוּ בְּמָקוֹם שֶׁנָּהֲגוּ לַעֲשׂוֹת לֹא יַתְחִיל בַּתְּחִלָּה לַעֲשׂוֹת מְלָאכָה בְּאַרְבָּעָה עָשָׂר אַף עַל פִּי שֶׁהוּא יָכוֹל לְגָמְרָהּ קֹדֶם חֲצוֹת. אֶלָּא שָׁלֹשׁ אֻמָּנֻיּוֹת בִּלְבַד הֵן שֶׁמַּתְחִילִין בָּהֶם בְּמָקוֹם שֶׁנָּהֲגוּ לַעֲשׂוֹת וְעוֹשִׂין עַד חֲצוֹת. וְאֵלּוּ הֵן הַחַיָּטִין. וְהַסַּפָּרִין. וְהַכּוֹבְסִין. אֲבָל שְׁאָר אֻמָּנֻיּוֹת אִם הִתְחִיל בָּהֶן קֹדֶם אַרְבָּעָה עָשָׂר הוּא שֶׁיִּגְמֹר עַד חֲצוֹת שֶׁאֵין הָעָם צְרִיכִין לִשְׁאָר אֻמָּנֻיּוֹת צֹרֶךְ הַרְבֵּה:","הַהוֹלֵךְ מִמָּקוֹם שֶׁעוֹשִׂין לְמָקוֹם שֶׁאֵין עוֹשִׂין לֹא יַעֲשֶׂה בַּיִּשּׁוּב מִפְּנֵי הַמַּחֲלֹקֶת אֲבָל עוֹשֶׂה הוּא בַּמִּדְבָּר. וְהַהוֹלֵךְ מִמָּקוֹם שֶׁאֵין עוֹשִׂין לְמָקוֹם שֶׁעוֹשִׂין לֹא יַעֲשֶׂה. נוֹתְנִין עָלָיו חֻמְרֵי מָקוֹם שֶׁיָּצָא מִשָּׁם וְחֻמְרֵי מָקוֹם שֶׁהָלַךְ לְשָׁם. וְאַף עַל פִּי כֵן לֹא יִתְרָאֶה בִּפְנֵיהֶם שֶׁהוּא בָּטֵל מִפְּנֵי הָאִסּוּר. לְעוֹלָם אַל יְשַׁנֶּה אָדָם מִפְּנֵי הַמַּחֲלֹקֶת. וְכֵן מִי שֶׁדַּעְתּוֹ לַחֲזֹר לִמְקוֹמוֹ נוֹהֵג כְּאַנְשֵׁי מְקוֹמוֹ בֵּין לְהָקֵל בֵּין לְהַחֲמִיר. וְהוּא שֶׁלֹּא יִתְרָאֶה בִּפְנֵי אַנְשֵׁי הַמָּקוֹם שֶׁהוּא בּוֹ מִפְּנֵי הַמַּחֲלֹקֶת:","מוֹלִיכִין וּמְבִיאִין כֵּלִים מִבֵּית הָאֻמָּן בְּאַרְבָּעָה עָשָׂר אַחַר חֲצוֹת אַף עַל פִּי שֶׁאֵינָן לְצֹרֶךְ הַמּוֹעֵד. וְגוֹרְפִין זֶבֶל מִתַּחַת רַגְלֵי בְּהֵמָה וּמוֹצִיאִים אוֹתוֹ לָאַשְׁפָּה. וּמוֹשִׁיבִין שׁוֹבָכִין לַתַּרְנְגוֹלִים. תַּרְנְגֹלֶת שֶׁיָּשְׁבָה עַל הַבֵּיצִים שְׁלֹשָׁה יָמִים אוֹ יֶתֶר וּמֵתָה מוֹשִׁיבִין אַחֶרֶת תַּחְתֶּיהָ בְּאַרְבָּעָה עָשָׂר כְּדֵי שֶׁלֹּא יִפָּסְדוּ הַבֵּיצִים. וּבַמּוֹעֵד אֵין מוֹשִׁיבִין. אֲבָל אִם בָּרְחָה בַּמּוֹעֵד מֵעַל הַבֵּיצִים מַחְזִירִין אוֹתָהּ לִמְקוֹמָהּ: סְלִיקוּ לְהוּ הִלְכוֹת שְׁבִיתַת יוֹם טוֹב"],"Mishneh Torah, Ritual Slaughter 4":["יִשְׂרָאֵל שֶׁאֵינוֹ יוֹדֵעַ חֲמִשָּׁה דְּבָרִים שֶׁמַּפְסִידִין אֶת הַשְּׁחִיטָה וְכַיּוֹצֵא בָּהֶן מֵהִלְכוֹת שְׁחִיטָה שֶׁבֵּאַרְנוּ וְשָׁחַט בֵּינוֹ לְבֵין עַצְמוֹ אָסוּר לֶאֱכל מִשְּׁחִיטָתוֹ. לֹא הוּא וְלֹא אֲחֵרִים. וַהֲרֵי זוֹ קְרוֹבָה לִסְפֵק נְבֵלָה וְהָאוֹכֵל מִמֶּנָּה כְּזַיִת מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","וַאֲפִלּוּ שָׁחַט בְּפָנֵינוּ אַרְבַּע וְחָמֵשׁ פְּעָמִים שְׁחִיטָה כְּשֵׁרָה וַהֲרֵי שְׁחִיטָה זוֹ שֶׁשָּׁחַט בֵּינוֹ לְבֵין עַצְמוֹ שְׁחִיטָה נְכוֹנָה וּגְמוּרָה אָסוּר לֶאֱכל מִמֶּנָּה. הוֹאִיל וְאֵינוֹ יוֹדֵעַ דְּבָרִים הַמַּפְסִידִים אֶפְשָׁר שֶׁיַּפְסִיד הַשְּׁחִיטָה וְהוּא אֵינוֹ יוֹדֵעַ כְּגוֹן שֶׁיִּשְׁהֶה אוֹ יִדְרֹס אוֹ יִשְׁחֹט בְּסַכִּין פְּגוּמָה וְכַיּוֹצֵא בְּאֵלּוּ בְּלֹא כַּוָּנָתוֹ:","יִשְׂרָאֵל שֶׁיּוֹדֵעַ הִלְכוֹת שְׁחִיטָה הֲרֵי זֶה לֹא יִשְׁחֹט בֵּינוֹ לְבֵין עַצְמוֹ לְכַתְּחִלָּה עַד שֶׁיִּשְׁחֹט בִּפְנֵי חָכָם פְּעָמִים רַבּוֹת עַד שֶׁיִּהְיֶה רָגִיל וְזָרִיז. וְאִם שָׁחַט תְּחִלָּה בֵּינוֹ לְבֵין עַצְמוֹ שְׁחִיטָתוֹ כְּשֵׁרָה:","הַיּוֹדֵעַ הִלְכוֹת שְׁחִיטָה וְשָׁחַט בִּפְנֵי חָכָם עַד שֶׁנַּעֲשָׂה רָגִיל הוּא הַנִּקְרָא מֻמְחֶה. וְכָל הַמֻּמְחִין שׁוֹחֲטִין לְכַתְּחִלָּה בֵּינָן לְבֵין עַצְמָן. וַאֲפִלּוּ נָשִׁים וַעֲבָדִים אִם הָיוּ מֻמְחִין הֲרֵי אֵלּוּ שׁוֹחֲטִין לְכַתְּחִלָּה:","חֵרֵשׁ שׁוֹטֶה וְקָטָן וְשִׁכּוֹר שֶׁנִּתְבַּלְבְּלָה דַּעְתּוֹ שֶׁשָּׁחֲטוּ שְׁחִיטָתָן פְּסוּלָה מִפְּנֵי שֶׁאֵין בָּהֶן דַּעַת שֶׁמָּא יְקַלְקְלוּ. לְפִיכָךְ אִם שָׁחֲטוּ בִּפְנֵי הַיּוֹדֵעַ וְרָאָה אוֹתָן שֶׁשָּׁחֲטוּ כַּהֹגֶן שְׁחִיטָתָן כְּשֵׁרָה:","מִי שֶׁאֵינוֹ יָדוּעַ אֶצְלֵנוּ שֶׁשָּׁחַט בֵּינוֹ לְבֵין עַצְמוֹ שׁוֹאֲלִין אוֹתוֹ. אִם נִמְצָא יוֹדֵעַ עִקְּרֵי הִלְכוֹת שְׁחִיטָה שְׁחִיטָתוֹ כְּשֵׁרָה:","הֲרֵי שֶׁרָאִינוּ יִשְׂרְאֵלִי מֵרָחוֹק שֶׁשָּׁחַט וְהָלַךְ לוֹ וְלֹא יָדַעְנוּ אִם יוֹדֵעַ אִם אֵינוֹ יוֹדֵעַ הֲרֵי זוֹ מֻתֶּרֶת. וְכֵן הָאוֹמֵר לִשְׁלוּחוֹ צֵא וּשְׁחֹט לִי וּמָצָא הַבְּהֵמָה שְׁחוּטָה וְאֵין יָדוּעַ אִם שְׁלוּחוֹ שְׁחָטָהּ אוֹ אַחֵר הֲרֵי זוֹ מֻתֶּרֶת. שֶׁרֹב הַמְּצוּיִין אֵצֶל שְׁחִיטָה מֻמְחִין הֵן:","אָבַד לוֹ גְּדִי אוֹ תַּרְנְגוֹל וּמְצָאוֹ שָׁחוּט בַּבַּיִת מֻתָּר. שֶׁרֹב הַמְּצוּיִין אֵצֶל שְׁחִיטָה מֻמְחִים הֵן. מְצָאוֹ בַּשּׁוּק אָסוּר שֶׁמָּא נִתְנַבֵּל וּלְפִיכָךְ הֻשְׁלַךְ. וְכֵן אִם מְצָאוֹ בָּאַשְׁפָּה שֶׁבַּבַּיִת אָסוּר:","מֻמְחֶה שֶׁנִּשְׁתַּתֵּק וַהֲרֵי הוּא מֵבִין וְשׁוֹמֵעַ וְדַעְתּוֹ נְכוֹנָה הֲרֵי זֶה שׁוֹחֵט לְכַתְּחִלָּה. וְכֵן מִי שֶׁאֵינוֹ שׁוֹמֵעַ הֲרֵי זֶה שׁוֹחֵט:","הַסּוּמָא לֹא יִשְׁחֹט לְכַתְּחִלָּה אֶלָּא אִם כֵּן אֲחֵרִים רוֹאִים אוֹתוֹ וְאִם שָׁחַט שְׁחִיטָתוֹ כְּשֵׁרָה:","עַכּוּ\"ם שֶׁשָּׁחַט אַף עַל פִּי שֶׁשָּׁחַט בִּפְנֵי יִשְׂרָאֵל בְּסַכִּין יָפָה וַאֲפִלּוּ הָיָה קָטָן שְׁחִיטָתוֹ נְבֵלָה וְלוֹקֶה עַל אֲכִילָתָהּ מִן הַתּוֹרָה. שֶׁנֶּאֱמַר (שמות לד טו) \"וְקָרָא לְךָ וְאָכַלְתָּ מִזִּבְחוֹ\". מֵאַחַר שֶׁהִזְהִיר שֶׁמָּא יֹאכַל מִזִּבְחוֹ אַתָּה לָמֵד שֶׁזִּבְחוֹ אָסוּר וְאֵינוֹ דּוֹמֶה לְיִשְׂרָאֵל שֶׁאֵינוֹ יוֹדֵעַ הִלְכוֹת שְׁחִיטָה:","וְגָדֵר גָּדוֹל גָּדְרוּ בַּדָּבָר שֶׁאֲפִלּוּ עַכּוּ\"ם שֶׁאֵינוֹ עוֹבֵד עֲבוֹדָה זָרָה שְׁחִיטָתוֹ נְבֵלָה:","הִתְחִיל הָעַכּוּ\"ם לִשְׁחֹט מִעוּט סִימָנִין וְגָמַר יִשְׂרָאֵל אוֹ הִתְחִיל יִשְׂרָאֵל וְגָמַר הָעַכּוּ\"ם פְּסוּלָה. יֶשְׁנָהּ לִשְׁחִיטָתוֹ מִתְּחִלָּה וְעַד סוֹף. אֲבָל אִם שָׁחַט הָעַכּוּ\"ם דָּבָר שֶׁאֵינוֹ עוֹשֶׂה אוֹתוֹ נְבֵלָה כְּגוֹן שֶׁשָּׁחַט חֲצִי הַגַּרְגֶּרֶת בִּלְבַד וְגָמַר יִשְׂרָאֵל הֲרֵי זוֹ כְּשֵׁרָה:","יִשְׂרָאֵל מוּמָר לַעֲבֵרָה מִן הָעֲבֵרוֹת שֶׁהָיָה מֻמְחֶה הֲרֵי זֶה שׁוֹחֵט לְכַתְּחִלָּה. וְצָרִיךְ יִשְׂרָאֵל כָּשֵׁר לִבְדֹּק אֶת הַסַּכִּין וְאַחַר כָּךְ יִתְּנֶנָּה לְמוּמָר זֶה לִשְׁחֹט בָּהּ מִפְּנֵי שֶׁחֶזְקָתוֹ שֶׁאֵינוֹ טוֹרֵחַ לִבְדֹּק. וְאִם הָיָה מוּמָר לַעֲבוֹדָה זָרָה אוֹ מְחַלֵּל שַׁבָּת בְּפַרְהֶסְיָא אוֹ אֶפִּיקוֹרוֹס וְהוּא הַכּוֹפֵר בַּתּוֹרָה וּבְמשֶׁה רַבֵּנוּ כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת תְּשׁוּבָה הֲרֵי הוּא כְּעַכּוּ\"ם וּשְׁחִיטָתוֹ נְבֵלָה:","מִי שֶׁהוּא פָּסוּל לְעֵדוּת בַּעֲבֵרָה מִן הָעֲבֵרוֹת שֶׁל תּוֹרָה הֲרֵי זֶה שׁוֹחֵט בֵּינוֹ לְבֵין עַצְמוֹ אִם הָיָה מֻמְחֶה. שֶׁאֵינוֹ מֵנִיחַ דָּבָר מֻתָּר וְאוֹכֵל דְּבַר אִסּוּר. שֶׁזּוֹ חֲזָקָה הִיא עַל כָּל יִשְׂרָאֵל וַאֲפִלּוּ הָרְשָׁעִים מֵהֶן:","אֵלּוּ הַצְּדוֹקִין וְהַבַּיְתוֹסִין וְתַלְמִידֵיהֶן וְכָל הַטּוֹעִים אַחֲרֵיהֶן שֶׁאֵינָן מַאֲמִינִים בַּתּוֹרָה שֶׁבְּעַל פֶּה שְׁחִיטָתָן אֲסוּרָה. וְאִם שָׁחֲטוּ בְּפָנֵינוּ הֲרֵי זוֹ מֻתֶּרֶת. שֶׁאֵין אִסּוּר שְׁחִיטָתָן אֶלָּא שֶׁמָּא יְקַלְקְלוּ וְהֵם אֵינָן מַאֲמִינִין בְּתוֹרַת הַשְּׁחִיטָה לְפִיכָךְ אֵינָן נֶאֱמָנִין לוֹמַר לֹא קִלְקַלְנוּ:","כְּשֶׁהָיוּ יִשְׂרָאֵל בַּמִּדְבָּר לֹא נִצְטַוּוּ בִּשְׁחִיטַת הַחֻלִּין אֶלָּא הָיוּ נוֹחֲרִין אוֹ שׁוֹחֲטִין וְאוֹכְלִין כִּשְׁאָר הָאֻמּוֹת. וְנִצְטַוּוּ בַּמִּדְבָּר שֶׁכָּל הָרוֹצֶה לִשְׁחֹט לֹא יִשְׁחֹט אֶלָּא שְׁלָמִים שֶׁנֶּאֱמַר (ויקרא יז ג) \"אִישׁ אִישׁ מִבֵּית יִשְׂרָאֵל אֲשֶׁר יִשְׁחַט שׁוֹר\" וְגוֹ' (ויקרא יז ד) \"וְאֶל פֶּתַח אֹהֶל מוֹעֵד\" וְגוֹ' (ויקרא יז ה) \"לְמַעַן אֲשֶׁר יָבִיאוּ\" וְגוֹ' (ויקרא יז ה) \"וְזָבְחוּ זִבְחֵי שְׁלָמִים לַה'\" וְגוֹ'. אֲבָל הָרוֹצֶה לִנְחֹר וְלֶאֱכל בַּמִּדְבָּר הָיָה נוֹחֵר:","וּמִצְוָה זוֹ אֵינָהּ נוֹהֶגֶת לְדוֹרוֹת אֶלָּא בַּמִּדְבָּר בִּלְבַד בְּעֵת הֶתֵּר הַנְּחִירָה. וְנִצְטַוּוּ שָׁם שֶׁכְּשֶׁיִּכָּנְסוּ לָאָרֶץ תֵּאָסֵר הַנְּחִירָה וְלֹא יֹאכְלוּ חֻלִּין אֶלָּא בִּשְׁחִיטָה. וְיִשְׁחֲטוּ בְּכָל מָקוֹם לְעוֹלָם חוּץ לַעֲזָרָה שֶׁנֶּאֱמַר (דברים יב כ) \"כִּי יַרְחִיב ה' אֱלֹהֶיךָ אֶת גְּבוּלְךָ\" וְגוֹ' (דברים יב כא) \"וְזָבַחְתָּ מִבְּקָרְךָ וּמִצֹּאנְךָ אֲשֶׁר נָתַן ה' אֱלֹהֶיךָ\" וְגוֹ'. וְזוֹ הִיא הַמִּצְוָה הַנּוֹהֶגֶת לְדוֹרוֹת לִשְׁחֹט וְאַחַר כָּךְ יֵאָכֵל:"],"Mishneh Torah, Robbery and Lost Property 15":["כָּל הַמּוֹצֵא אֲבֵדָה בֵּין שֶׁיֵּשׁ בָּהּ סִימָן בֵּין שִׁאִין בָּהּ סִימָן אִם מְצָאָהּ דֶּרֶךְ הַנָּחָה אָסוּר לִגַּע בָּהּ שֶׁמָּא בְּעָלֶיהָ הִנִּיחוּהָ שָׁם עַד שֶׁיַּחְזְרוּ לָהּ וְאִם יָבוֹא לִטְּלֶנָּה וְהָיָה דָּבָר שֶׁאֵין בּוֹ סִימָן הֲרֵי אִבֵּד מָמוֹן חֲבֵרוֹ בְּיָדוֹ שֶׁהֲרֵי אֵין לוֹ בָּהּ סִימָן לְהַחְזִיר בּוֹ. וְאִם הָיָה דָּבָר שֶׁיֵּשׁ לוֹ סִימָן הֲרֵי זֶה הִטְרִיחָן לִרְדֹּף אַחֲרֶיהָ וְלָתֵת סִימָנֶיהָ. וּלְפִיכָךְ אָסוּר לוֹ שֶׁיִּגַּע בָּהּ עַד שֶׁיִּמְצָאֶנָּה דֶּרֶךְ נְפִילָה. וַאֲפִלּוּ נִסְתַּפֵּק לוֹ הַדָּבָר וְלֹא יָדַע אִם דָּבָר זֶה אָבוּד אוֹ מֻנָּח הֲרֵי זֶה לֹא יִגַּע בּוֹ. וְאִם עָבַר וּנְטָלוֹ אָסוּר לוֹ לְהַחְזִירוֹ לְשָׁם. וְאִם הָיָה דָּבָר שֶׁאֵין בּוֹ סִימָן זָכָה בּוֹ וְאֵינוֹ חַיָּב לְהַחְזִירוֹ:","וְכָל דָּבָר שֶׁיֵּשׁ בּוֹ סִימָן בֵּין בְּדֶרֶךְ הַנָּחָה בֵּין בְּדֶרֶךְ נְפִילָה בֵּין בִּרְשׁוּת הַיָּחִיד בֵּין בִּרְשׁוּת הָרַבִּים חַיָּב לְהַכְרִיז. כֵּיצַד. דֶּרֶךְ הַנָּחָה כְּגוֹן שֶׁמָּצָא חֲמוֹר אוֹ פָּרָה רוֹעִים בַּדֶּרֶךְ בַּיּוֹם אוֹ שֶׁמָּצָא כְּלִי מְכֻסֶּה בָּאַשְׁפָּה הֲרֵי זֶה לֹא יִגַּע בָּהֶן שֶׁנֶּאֱמַר (דברים כב א) \"נִדָּחִים בַּדֶּרֶךְ\". אֲבָל אִם מָצָא חֲמוֹר וְכֵלָיו הֲפוּכִים וּפָרָה רָצָה בֵּין הַכְּרָמִים אוֹ כְּלִי מְגֻלֶּה בָּאַשְׁפָּה הֲרֵי זוֹ אֲבֵדָה וְנוֹטֵל וּמַכְרִיז:","רָאָה חֲמוֹר אוֹ פָּרָה רוֹעִים בַּאֲפָר כְּדַרְכָּן בַּלַּיְלָה הֲרֵי זוֹ אֲבֵדָה. בִּפְנוֹת הַיּוֹם וּבַנֶּשֶׁף אִם רָאָה אוֹתָן שְׁלֹשָׁה יָמִים זֶה אַחַר זֶה הֲרֵי זוֹ אֲבֵדָה וְנוֹטֵל וּמַכְרִיז. רָאָה פָּרָה רָצָה בַּדֶּרֶךְ אִם פָּנֶיהָ כְּלַפֵּי הָעִיר אֵין זוֹ אֲבֵדָה. כְּלַפֵּי הַשָּׂדֶה הֲרֵי זוֹ אֲבֵדָה:","מְצָאָהּ רוֹעָה בֵּין הַכְּרָמִים חַיָּב לְהַחְזִיר מִשּׁוּם אֲבֵדַת הַקַּרְקַע. לְפִיכָךְ אִם הָיוּ הַכְּרָמִים שֶׁל עַכּוּ\"ם אֵינָהּ אֲבֵדָה וְאֵינוֹ חַיָּב לְהַחְזִיר. וְאִם חָשַׁשׁ שֶׁמָּא יַהַרְגֶנָּה הָעַכּוּ\"ם כְּשֶׁיִּמְצָאֶנָּה מִפְּנֵי שֶׁהִפְסִידָה הַכֶּרֶם הֲרֵי זוֹ אֲבֵדָה וְנוֹטֵל וּמַכְרִיז:","מָצָא פָּרָה בִּרְשׁוּת הָרַבִּים אִם עוֹמֶדֶת חוּץ לַתְּחוּם חַיָּב לְהַחְזִיר. הָיְתָה רוֹעָה בָּעֲשָׂבִים אוֹ שֶׁהָיְתָה בְּרֶפֶת שֶׁאֵינָהּ מִשְׁתַּמֶּרֶת וְאֵינָהּ מְאַבֶּדֶת לֹא יִגַּע בָּהּ שֶׁאֵין זוֹ אֲבֵדָה. מָצָא טַלִּית אוֹ קַרְדֹּם בְּצַד הַגָּדֵר הֲרֵי זֶה לֹא יִגַּע בָּהֶן. בִּסְרַטְיָא הֲרֵי זֶה נוֹטֵל וּמַכְרִיז. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מָצָא גּוֹזָלוֹת מְקֻשָּׁרִין בְּכַנְפֵיהֶן וּמְדַדִּין אַחַר הַגָּדֵר אוֹ אַחַר הַגַּפָּה אוֹ בַּשְּׁבִילִין שֶׁבַּשָּׂדוֹת הֲרֵי זֶה לֹא יִגַּע בָּהֶן שֶׁמָּא בַּעֲלֵיהֶן הִנִּיחוּם שָׁם. וְאִם נְטָלָן הֲרֵי אֵלּוּ שֶׁלּוֹ. וְאִם הָיוּ קְשׁוּרִין קֶשֶׁר שֶׁהוּא סִימָן חַיָּב לְהַכְרִיז. וְכֵן אִם מְצָאָן קְבוּעִים בִּמְקוֹמָן חַיָּב לְהַכְרִיז שֶׁהַמָּקוֹם סִימָן:","מָצָא בָּאַשְׁפָּה כְּלִי מְכֻסֶּה הֲרֵי זֶה לֹא יִגַּע בּוֹ כְּמוֹ שֶׁבֵּאַרְנוּ. וְאִם אַשְׁפָּה שֶׁאֵינָהּ עֲשׂוּיָה לְהִתְפַּנּוֹת הִיא וְנִמְלַךְ עָלֶיהָ לְפַנּוֹתָהּ אַף עַל פִּי שֶׁמְּצָאוֹ מְכֻסֶּה נוֹטֵל וּמַכְרִיז. וְכֵן אִם הָיוּ כֵּלִים קְטַנִּים כְּגוֹן סַכִּין וְשִׁפּוּד וְכַיּוֹצֵא בָּהֶן אֲפִלּוּ הָיוּ מְכֻסִּין בָּאַשְׁפָּה הַקְּבוּעָה נוֹטֵל וּמַכְרִיז:","מָצָא פֵּרוֹת מְפֻזָּרִין דֶּרֶךְ הַנָּחָה לֹא יִגַּע בָּהֶן. דֶּרֶךְ נְפִילָה הֲרֵי הֵן שֶׁלּוֹ. וְכֵן אִם מָצָא כְּרִיכוֹת קְטַנּוֹת שֶׁל שִׁבֳּלִים בִּרְשׁוּת הָרַבִּים שֶׁהֲרֵי אֵין בָּהֶן סִימָן. אוֹ שֶׁמָּצָא עִגּוּלֵי דְּבֵלָה וְכִכָּרוֹת שֶׁל נַחְתּוֹם וּמַחְרוֹזוֹת שֶׁל דָּגִים וַחֲתִיכוֹת שֶׁל בָּשָׂר וְגִזֵּי צֶמֶר הַבָּאוֹת מִמְּדִינָתָן וַאֲנִיצֵי פִּשְׁתָּן וּלְשׁוֹנוֹת שֶׁל אַרְגָּמָן הֲרֵי אֵלּוּ שֶׁלּוֹ מִפְּנֵי שֶׁאֵין בָּהֶן סִימָן. וְאִם יֵשׁ בָּהֶן סִימָן נוֹטֵל וּמַכְרִיז שֶׁסִּימָן הֶעָשׂוּי לִדָּרֵס הֲרֵי הוּא סִימָן:","אֲבָל אִם מָצָא כִּכָּרוֹת שֶׁל בַּעַל הַבַּיִת וְגִזֵּי צֶמֶר הַלְּקוּחוֹת מִבֵּית הָאֻמָּן כַּדֵּי יַיִן וְכַדֵּי שֶׁמֶן חַיָּב לְהַכְרִיז שֶׁכָּל אֵלּוּ יֵשׁ לָהֶם סִימָנִין מֻבְהָקִין. וְאִם נִפְתְּחוּ הָאוֹצָרוֹת שֶׁל יַיִן וְשֶׁל שֶׁמֶן הֲרֵי אֵלּוּ שֶׁלּוֹ. וְאַף עַל פִּי שֶׁהֵם רְשׁוּמִין. שֶׁכָּל הַכַּדּוֹת כָּךְ הָיוּ רְשׁוּמוֹת וְנִמְצְאוּ אֵלּוּ הַכַּדִּין כְּכִכְּרוֹת הַנַּחְתּוֹם שֶׁיֵּשׁ צוּרָה אַחַת לְכֻלָּן וּמִשְׁקָל אֶחָד לְכֻלָּם:","מָצָא כְּרִיכוֹת בִּרְשׁוּת הַיָּחִיד אִם דֶּרֶךְ נְפִילָה הֲרֵי אֵלּוּ שֶׁלּוֹ. וְאִם דֶּרֶךְ הַנָּחָה חַיָּב לְהַכְרִיז שֶׁאַף עַל פִּי שֶׁאֵין לָהֶם סִימָן הַמָּקוֹם סִימָן (אַף עַל פִּי שֶׁאֵינוֹ סִימָן מֻבְהָק). מָצָא אֲלֻמּוֹת בֵּין בִּרְשׁוּת הַיָּחִיד בֵּין בִּרְשׁוּת הָרַבִּים נוֹטֵל וּמַכְרִיז:","מָצָא עִגּוּל וּבְתוֹכוֹ חֶרֶשׂ. כִּכָּר וּבְתוֹכוֹ מָעוֹת. חֲתִיכָה שֶׁל בָּשָׂר שֶׁהוּא מְשֻׁנֶּה בַּחֲתִיכוֹת. דָּג נָשׁוּךְ. וְכֵן כָּל כַּיּוֹצֵא בְּאֵלּוּ הוֹאִיל וְיֵשׁ בָּהֶן שִׁנּוּי חַיָּב לְהַכְרִיז. שֶׁלֹּא עֲשָׂאוּם בַּעֲלֵיהֶן אֶלָּא לְסִימָן:","מָצָא פֵּרוֹת מְפֻזָּרִין בְּמָקוֹם הַגֳּרָנוֹת אִם הָיוּ כְּמוֹ קַב בְּתוֹךְ אַרְבַּע אַמּוֹת אוֹ בְּיֶתֶר עַל אַרְבַּע אַמּוֹת הֲרֵי אֵלּוּ שֶׁלּוֹ מִפְּנֵי שֶׁאֵין הַבְּעָלִים מְטַפְּלִים בַּאֲסִיפָתָן. הָיוּ מְפֻזָּרִין בְּפָחוֹת מֵאַרְבַּע אַמּוֹת לֹא יִגַּע בָּהֶן שֶׁמָּא הַבְּעָלִים הִנִּיחוּם שָׁם. הָיוּ כְּמוֹ חֲצִי קַב בִּשְׁתֵּי אַמּוֹת אוֹ קַבַּיִם בִּשְׁמוֹנֶה אַמּוֹת אוֹ שֶׁהָיָה הַקַּב מִשְּׁנַיִם וּשְׁלֹשָׁה מִינִין כְּמוֹ תְּמָרִים שֻׁמְשְׁמִין [וְרִמּוֹנִים] כָּל אֵלּוּ סָפֵק לְפִיכָךְ לֹא יִטּל. וְאִם נָטַל אֵינוֹ חַיָּב לְהַכְרִיז:","הַמּוֹצֵא צִבּוּרֵי פֵּרוֹת אוֹ פֵּרוֹת בִּכְלִי אוֹ כְּלִי כְּמוֹת שֶׁהוּא חַיָּב לְהַכְרִיז. מָצָא כְּלִי וּלְפָנָיו פֵּרוֹת הֲרֵי אֵלּוּ שֶׁלּוֹ הַפֵּרוֹת. וְהַכְּלִי נוֹטֵל וּמַכְרִיז. שֶׁאֲנִי אוֹמֵר הַכְּלִי שֶׁל אֶחָד וְהַפֵּרוֹת שֶׁל אַחֵר וַהֲרֵי אֵין בּוֹ סִימָן. וְאִם מַרְאִין הַדְּבָרִים שֶׁהֵן שֶׁל אָדָם אֶחָד חַיָּב לְהַכְרִיז:","כֵּיצַד. הָיוּ אֲחוֹרֵי הַכְּלִי לִפְנֵי הַפֵּרוֹת הֲרֵי אֵלּוּ שֶׁלּוֹ. הָיוּ פְּנֵי הַכְּלִי לִפְנֵי הַפֵּרוֹת חוֹשְׁשִׁין שֶׁמָּא מִן הַכְּלִי נִשְׁפְּכוּ. וְאִם הָיוּ אָגֳּנִים לַכְּלִי אַף עַל פִּי שֶׁפָּנָיו כְּלַפֵּי הַפֵּרוֹת הֲרֵי אֵלּוּ שֶׁלּוֹ שֶׁאִלּוּ נִשְׁפְּכוּ מִן הַכְּלִי הָיָה נִשְׁאַר מֵהֶן בְּתוֹכוֹ מִפְּנֵי הָאָגֳּנִים. הָיוּ מִקְצָת הַפֵּרוֹת בַּכְּלִי וּמִקְצָתָן בָּאָרֶץ חַיָּב לְהַכְרִיז:","הַמּוֹצֵא קְצִיעוֹת בַּדֶּרֶךְ וַאֲפִלּוּ בְּצַד שְׂדֵה קְצִיעוֹת הֲרֵי אֵלּוּ שֶׁלּוֹ. וְכֵן תְּאֵנָה שֶׁהִיא נוֹטָה לַדֶּרֶךְ וְנִמְצְאוּ תְּאֵנִים תַּחְתֶּיהָ מֻתָּרוֹת מִשּׁוּם גֵּזֶל. שֶׁהַתְּאֵנָה וְכַיּוֹצֵא בָּהּ עִם נְפִילָתָהּ נִמְאֶסֶת. וּפְטוּרוֹת מִשּׁוּם מַעֲשֵׂר. אֲבָל זֵיתִים וְחָרוּבִין וְכַיּוֹצֵא בָּהֶן אֲסוּרִין:","תְּמָרִים שֶׁמְּשִׁירָן הָרוּחַ מֻתָּרוֹת שֶׁהַבְּעָלִים מְחָלוּם לְכָל אָדָם וְזוֹ הִיא חֶזְקָתָן. וְאִם הָיוּ שֶׁל יְתוֹמִים שֶׁאֵינָן בְּנֵי מְחִילָה אֲסוּרִין. וְכֵן אִם הִקְפִּיד בַּעַל הַשָּׂדֶה וְהִקִּיף מְקוֹם הָאִילָנוֹת אוֹ תִּקֵּן מָקוֹם שֶׁיִּפְּלוּ בּוֹ הַנּוֹבְלוֹת עַד שֶׁיְּלַקְּטֵם הֲרֵי אֵלּוּ אֲסוּרוֹת שֶׁהֲרֵי גִּלָּה דַּעְתּוֹ שֶׁלֹּא מָחַל:","חָתוּל רַע שֶׁהוֹרֵג אֶת הַקְּטַנִּים אָסוּר לְקַיְּמוֹ וְאֵין בּוֹ מִשּׁוּם גֵּזֶל וְאֵין בּוֹ מִשּׁוּם הֶשֵּׁב אֲבֵדָה אַף עַל פִּי שֶׁעוֹרוֹ מוֹעִיל אֶלָּא כָּל הַמּוֹצְאוֹ זָכָה בּוֹ וְהוֹרְגוֹ וְהָעוֹר שֶׁלּוֹ:","גּוֹזָל הַנִּמְצָא קָרוֹב לַשּׁוֹבָךְ בְּתוֹךְ חֲמִשִּׁים אַמָּה הֲרֵי הוּא שֶׁל בַּעַל הַשּׁוֹבָךְ חוּץ לַחֲמִשִּׁים אַמָּה הֲרֵי הוּא שֶׁל מוֹצְאוֹ שֶׁאֵין הַגּוֹזָל מְדַדֶּה יֶתֶר עַל חֲמִשִּׁים אַמָּה. נִמְצָא בֵּין שְׁנֵי שׁוֹבָכוֹת הֲרֵי הוּא שֶׁל קָרוֹב. מֶחֱצָה לְמֶחֱצָה יַחֲלֹקוּ. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיוּ יוֹנֵי שְׁתֵּי הַשּׁוֹבָכוֹת שָׁוִים בְּמִנְיָן. אֲבָל אִם הָיוּ יוֹנֵי הָאֶחָד רַבִּים הַלֵּךְ אַחַר הָרֹב אַף עַל פִּי שֶׁהוּא רָחוֹק:"],"Mishneh Torah, Sabbath 1":["שְׁבִיתָה בַּשְּׁבִיעִי מִמְּלָאכָה מִצְוַת עֲשֵׂה שֶׁנֶּאֱמַר (שמות לד כא) \"וּבַיּוֹם הַשְּׁבִיעִי תִּשְׁבֹּת\". וְכָל הָעוֹשֶׂה בּוֹ מְלָאכָה בִּטֵּל מִצְוַת עֲשֵׂה וְעָבַר עַל לֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים ה יד) \"לֹא תַעֲשֶׂה כָל מְלָאכָה\". וּמַה הוּא חַיָּב עַל עֲשִׂיַּת מְלָאכָה. אִם עָשָׂה בִּרְצוֹנוֹ בְּזָדוֹן חַיָּב כָּרֵת. וְאִם הָיוּ שָׁם עֵדִים וְהַתְרָאָה נִסְקָל. וְאִם עָשָׂה בִּשְׁגָגָה חַיָּב קָרְבַּן חַטָּאת קְבוּעָה:","כָּל מָקוֹם שֶׁנֶּאֱמַר בְּהִלְכוֹת שַׁבָּת שֶׁהָעוֹשֶׂה דָּבָר זֶה חַיָּב הֲרֵי זֶה חַיָּב כָּרֵת. וְאִם הָיוּ שָׁם עֵדִים וְהַתְרָאָה חַיָּב סְקִילָה. וְאִם הָיָה שׁוֹגֵג חַיָּב חַטָּאת:","וְכָל מָקוֹם שֶׁנֶּאֱמַר שֶׁהָעוֹשֶׂה דָּבָר זֶה פָּטוּר הֲרֵי זֶה פָּטוּר מִן הַכָּרֵת וּמִן הַסְּקִילָה וּמִן הַקָּרְבָּן אֲבָל אָסוּר לַעֲשׂוֹת אוֹתוֹ דָּבָר בְּשַׁבָּת וְאִסּוּרוֹ מִדִּבְרֵי סוֹפְרִים וְהוּא הַרְחָקָה מִן הַמְּלָאכָה. וְהָעוֹשֶׂה אוֹתוֹ בְּזָדוֹן מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת. וְכֵן כָּל מָקוֹם שֶׁנֶּאֱמַר אֵין עוֹשִׂין כָּךְ וְכָךְ אוֹ אָסוּר לַעֲשׂוֹת כָּךְ וְכָךְ בְּשַׁבָּת הָעוֹשֶׂה אוֹתוֹ דָּבָר בְּזָדוֹן מַכִּין אוֹתוֹ מַכַּת מַרְדּוּת:","וְכָל מָקוֹם שֶׁנֶּאֱמַר מֻתָּר לַעֲשׂוֹת כָּךְ וְכָךְ הֲרֵי זֶה מֻתָּר לְכַתְּחִלָּה. וְכֵן כָּל מָקוֹם שֶׁנֶּאֱמַר אֵינוֹ חַיָּב כְּלוּם אוֹ פָּטוּר מִכְּלוּם אֵין מַכִּין אוֹתוֹ כְּלָל:","דְּבָרִים הַמֻּתָּרִים לַעֲשׂוֹתָן בְּשַׁבָּת וּבִשְׁעַת עֲשִׂיָּתָן אֶפְשָׁר שֶׁתֵּעָשֶׂה בִּגְלָלָן מְלָאכָה וְאֶפְשָׁר שֶׁלֹּא תֵּעָשֶׂה. אִם לֹא נִתְכַּוֵּן לְאוֹתָהּ מְלָאכָה הֲרֵי זֶה מֻתָּר. כֵּיצַד. גּוֹרֵר אָדָם מִטָּה וְכִסֵּא וְסַפְסָל וְכַיּוֹצֵא בָּהֶן בְּשַׁבָּת וּבִלְבַד שֶׁלֹּא יִתְכַּוֵּן לַחְפֹּר חָרִיץ בַּקַּרְקַע בִּשְׁעַת גְּרִירָתָן. וּלְפִיכָךְ אִם חָפְרוּ הַקַּרְקַע אֵינוֹ חוֹשֵׁשׁ בְּכָךְ לְפִי שֶׁלֹּא נִתְכַּוֵּן. וְכֵן מְהַלֵּךְ אָדָם עַל גַּבֵּי עֲשָׂבִים בְּשַׁבָּת וּבִלְבַד שֶׁלֹּא יִתְכַּוֵּן לַעֲקֹר אוֹתָן. לְפִיכָךְ אִם נֶעֶקְרוּ אֵינוֹ חוֹשֵׁשׁ. וְרוֹחֵץ יָדָיו בַּעֲפַר הַפֵּרוֹת וְכַיּוֹצֵא בּוֹ וּבִלְבַד שֶׁלֹּא יִתְכַּוֵּן לְהַשִּׁיר הַשֵּׂעָר. לְפִיכָךְ אִם נָשַׁר אֵינוֹ חוֹשֵׁשׁ. וְכֵן פִּרְצָה דְּחוּקָה מֻתָּר לְהִכָּנֵס בָּהּ בְּשַׁבָּת אַף עַל פִּי שֶׁמַּשִּׁיר צְרוֹרוֹת. וְכֵן כָּל דָּבָר שֶׁאֵין מִתְכַּוֵּן כְּגוֹן זֶה הֲרֵי זֶה מֻתָּר:","אֲבָל עָשָׂה מַעֲשֶׂה וְנַעֲשֵׂית בִּגְלָלוֹ מְלָאכָה שֶׁוַּדַּאי תֵּעָשֶׂה בִּשְׁבִיל אוֹתוֹ מַעֲשֶׂה אַף עַל פִּי שֶׁלֹּא נִתְכַּוֵּן לָהּ חַיָּב. שֶׁהַדָּבָר יָדוּעַ שֶׁאִי אֶפְשָׁר שֶׁלֹּא תֵּעָשֶׂה אוֹתָהּ מְלָאכָה. כֵּיצַד. הֲרֵי שֶׁצָּרִיךְ לְרֹאשׁ עוֹף לְצַחֵק בּוֹ הַקָּטָן וְחָתַךְ רֹאשׁוֹ בְּשַׁבָּת אַף עַל פִּי שֶׁאֵין סוֹף מְגַמָּתוֹ לַהֲרִיגַת הָעוֹף בִּלְבַד חַיָּב שֶׁהַדָּבָר יָדוּעַ שֶׁאִי אֶפְשָׁר שֶׁיַּחְתֹּךְ רֹאשׁ הַחַי וְיִחְיֶה אֶלָּא הַמָּוֶת בָּא בִּשְׁבִילוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כָּל הָעוֹשֶׂה מְלָאכָה בְּשַׁבָּת אַף עַל פִּי שֶׁאֵינוֹ צָרִיךְ לְגוּפָהּ שֶׁל מְלָאכָה חַיָּב עָלֶיהָ. כֵּיצַד. הֲרֵי שֶׁכִּבָּה אֶת הַנֵּר מִפְּנֵי שֶׁהוּא צָרִיךְ לַשֶּׁמֶן אוֹ לַפְּתִילָה כְּדֵי שֶׁלֹּא יֹאבַד אוֹ כְּדֵי שֶׁלֹּא יִשָּׂרֵף אוֹ כְּדֵי שֶׁלֹּא יִבָּקַע חֶרֶשׂ שֶׁל נֵר. מִפְּנֵי שֶׁהַכִּבּוּי מְלָאכָה וַהֲרֵי נִתְכַּוֵּן לְכַבּוֹת וְאַף עַל פִּי שֶׁאֵינוֹ צָרִיךְ לְגוּף הַכִּבּוּי וְלֹא כִּבָּה אֶלָּא מִפְּנֵי הַשֶּׁמֶן אוֹ מִפְּנֵי הַחֶרֶשׂ אוֹ מִפְּנֵי הַפְּתִילָה הֲרֵי זֶה חַיָּב. וְכֵן הַמַּעֲבִיר אֶת הַקּוֹץ אַרְבַּע אַמּוֹת בִּרְשׁוּת הָרַבִּים אוֹ הַמְכַבֶּה אֶת הַגַּחֶלֶת כְּדֵי שֶׁלֹּא יִזּוֹקוּ בָּהֶן רַבִּים חַיָּב וְאַף עַל פִּי שֶׁאֵינוֹ צָרִיךְ לְגוּף הַכִּבּוּי אוֹ לְגוּף הַהַעֲבָרָה אֶלָּא לְהַרְחִיק הַהֶזֵּק הֲרֵי זֶה חַיָּב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כָּל הַמִּתְכַּוֵּן לַעֲשׂוֹת מְלָאכָה וְנַעֲשָׂה לוֹ מְלָאכָה אַחֶרֶת שֶׁלֹּא נִתְכַּוֵּן לָהּ פָּטוּר עָלֶיהָ לְפִי שֶׁלֹּא נַעֲשֵׂית מַחֲשַׁבְתּוֹ. כֵּיצַד. זָרַק אֶבֶן אוֹ חֵץ בַּחֲבֵרוֹ אוֹ בִּבְהֵמָה כְּדֵי לְהָרְגָן וְהָלַךְ וְעָקַר אִילָן בַּהֲלִיכָתוֹ וְלֹא הָרַג הֲרֵי זֶה פָּטוּר. הֲרֵי זֶה קַל וָחֹמֶר אִם נִתְכַּוֵּן לְאִסּוּר קַל וְנַעֲשָׂה אִסּוּר חָמוּר. כְּגוֹן שֶׁנִּתְכַּוֵּן לִזְרֹק בְּכַרְמְלִית וְעָבְרָה הָאֶבֶן לִרְשׁוּת הָרַבִּים שֶׁהוּא פָּטוּר. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. נִתְכַּוֵּן לַעֲשׂוֹת דָּבָר הַמֻּתָּר וְעָשָׂה דָּבָר אַחֵר כְּגוֹן שֶׁנִּתְכַּוֵּן לַחְתֹּךְ אֶת הַתָּלוּשׁ וְחָתַךְ אֶת הַמְחֻבָּר אֵינוֹ חַיָּב כְּלוּם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","נִתְכַּוֵּן לִלְקֹט תְּאֵנִים שְׁחוֹרוֹת וְלִקֵּט לְבָנוֹת אוֹ שֶׁנִּתְכַּוֵּן לִלְקֹט תְּאֵנִים וְאַחַר כָּךְ עֲנָבִים וְנֶהְפַּךְ הַדָּבָר וְלִקֵּט הָעֲנָבִים בַּתְּחִלָּה וְאַחַר כָּךְ תְּאֵנִים פָּטוּר אַף עַל פִּי שֶׁלִּקֵּט כָּל מַה שֶּׁחָשַׁב הוֹאִיל וְלֹא לִקֵּט כַּסֵּדֶר שֶׁחָשַׁב פָּטוּר שֶׁבְּלֹא כַּוָּנָה עָשָׂה שֶׁלֹּא אָסְרָה תּוֹרָה אֶלָּא מְלֶאכֶת מַחְשֶׁבֶת:","הָיוּ לְפָנָיו שְׁתֵּי נֵרוֹת דּוֹלְקוֹת אוֹ כְּבוּיוֹת נִתְכַּוֵּן לְכַבּוֹת זוֹ וְכִבָּה אֶת זוֹ לְהַדְלִיק זוֹ וְהִדְלִיק אֶת זוֹ חַיָּב שֶׁהֲרֵי עָשָׂה מִן הַמְּלָאכָה שֶׁחָשַׁב לַעֲשׂוֹתָהּ. הָא לְמָה הוּא דּוֹמֶה לְמִי שֶׁנִּתְכַּוֵּן לִלְקֹט תְּאֵנָה זוֹ וְלִקֵּט תְּאֵנָה אַחֶרֶת. אוֹ לְמִי שֶׁנִּתְכַּוֵּן לַהֲרֹג אֶת זֶה וְהָרַג אֶת זֶה שֶׁהֲרֵי נַעֲשֵׂית מְלָאכָה שֶׁחָשַׁב לַעֲשׂוֹתָהּ:","אֲבָל אִם נִתְכַּוֵּן לְהַדְלִיק רִאשׁוֹנָה וּלְכַבּוֹת שְׁנִיָּה אַחֲרֶיהָ וְנֶהְפַּךְ הַדָּבָר וְכִבָּה רִאשׁוֹנָה וְאַחַר כָּךְ הִדְלִיק שְׁנִיָּה אַחֲרֶיהָ פָּטוּר. כִּבָּה זוֹ וְהִדְלִיק זוֹ בִּנְשִׁימָה אַחַת חַיָּב. שֶׁאַף עַל פִּי שֶׁלֹּא הִקְדִּים הַהַדְלָקָה הֲרֵי זֶה לֹא אִחֵר אוֹתָהּ אֶלָּא שְׁתֵּיהֶן כְּאַחַת וּלְפִיכָךְ חַיָּב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְכָל הָעוֹשֶׂה מְלָאכָה בְּמִתְעַסֵּק וְלֹא נִתְכַּוֵּן לָהּ פָּטוּר:","כָּל הַמִּתְכַּוֵּן לַעֲשׂוֹת מְלָאכָה וְנַעֲשֵׂית בְּיוֹתֵר עַל כַּוָּנָתוֹ חַיָּב. בְּפָחוֹת מִכַּוָּנָתוֹ פָּטוּר. כֵּיצַד. הֲרֵי שֶׁנִּתְכַּוֵּן לְהוֹצִיא מַשָּׂא לְאַחֲרָיו וּבָא לוֹ לְפָנָיו חַיָּב שֶׁהֲרֵי נִתְכַּוֵּן לִשְׁמִירָה פְּחוּתָה וְנַעֲשֵׂית שְׁמִירָה מְעֻלָּה. אֲבָל אִם נִתְכַּוֵּן לְהוֹצִיא לְפָנָיו וּבָא לוֹ לְאַחֲרָיו פָּטוּר שֶׁהֲרֵי נִתְכַּוֵּן לְהוֹצִיא בִּשְׁמִירָה מְעֻלָּה וְהוֹצִיא בִּשְׁמִירָה פְּחוּתָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הָיָה חָגוּר בְּסִנָּר וְהִשְׁלִיךְ הַמַּשָּׂא בֵּין בְּשָׂרוֹ וַחֲלוּקוֹ בֵּין שֶׁבָּא זֶה הַמַּשָּׂא שֶׁדַּרְכּוֹ לְהוֹצִיאוֹ בַּדֶּרֶךְ הַזֹּאת לְפָנָיו בֵּין שֶׁבָּא לְאַחֲרָיו חַיָּב שֶׁכֵּן דַּרְכּוֹ לִהְיוֹת חוֹזֵר:","כָּל הַמִתְכַּוֵּן לַעֲשׂוֹת מְלָאכָה בְּשַׁבָּת וְהִתְחִיל בָּהּ וְעָשָׂה כַּשִּׁעוּר חַיָּב. אַף עַל פִּי שֶׁלֹּא הִשְׁלִים כָּל הַמְּלָאכָה שֶׁנִּתְכַּוֵּן לְהַשְׁלִימָהּ. כֵּיצַד. הֲרֵי שֶׁנִּתְכַּוֵּן לִכְתֹּב אִגֶּרֶת אוֹ שְׁטָר בְּשַׁבָּת אֵין אוֹמְרִים לֹא יִתְחַיֵּב זֶה עַד שֶׁיַּשְׁלִים חֶפְצוֹ וְיִכְתֹּב כָּל הַשְּׁטָר אוֹ כָּל הָאִגֶּרֶת אֶלָּא מִשֶּׁיִּכְתֹּב שְׁתֵּי אוֹתִיּוֹת חַיָּב. וְכֵן אִם נִתְכַּוֵּן לֶאֱרֹג בֶּגֶד שָׁלֵם מִשֶּׁיֶאֱרֹג שְׁנֵי חוּטִין חַיָּב וְאַף עַל פִּי שֶׁכַּוָּנָתוֹ לְהַשְׁלִים הַבֶּגֶד הוֹאִיל וְעָשָׂה כַּשִּׁעוּר בְּכַוָּנָה חַיָּב. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כָּל מְלָאכָה שֶׁהַיָּחִיד יָכוֹל לַעֲשׂוֹת אוֹתָהּ לְבַדּוֹ וְעָשׂוּ אוֹתָהּ שְׁנַיִם בְּשֻׁתָּפוּת בֵּין שֶׁעָשָׂה זֶה מִקְצָתָהּ וְזֶה מִקְצָתָהּ כְּגוֹן שֶׁעָקַר זֶה הַחֵפֶץ מֵרְשׁוּת זוֹ וְהִנִּיחוֹ הַשֵּׁנִי בִּרְשׁוּת אַחֶרֶת בֵּין שֶׁעָשׂוּ אוֹתָהּ שְׁנֵיהֶם כְּאֶחָד מִתְּחִלָּה וְעַד סוֹף כְּגוֹן שֶׁאָחֲזוּ שְׁנֵיהֶם בְּקֻלְמוֹס וְכָתְבוּ אוֹ אָחֲזוּ כִּכָּר וְהוֹצִיאוּהוּ מֵרְשׁוּת לִרְשׁוּת הֲרֵי אֵלּוּ פְּטוּרִין:","וְאִם אֵין אֶחָד מֵהֶן יָכוֹל לַעֲשׂוֹתָהּ לְבַדּוֹ עַד שֶׁיִּצְטָרְפוּ כְּגוֹן שְׁנַיִם שֶׁאָחֲזוּ קוֹרָה וְהוֹצִיאוּהָ לִרְשׁוּת הָרַבִּים הוֹאִיל וְאֵין כֹּחַ בְּאֶחָד מֵהֶן לַעֲשׂוֹתָהּ לְבַדּוֹ וְעָשׂוּ אוֹתָהּ בְּשֻׁתָּפוּת מִתְּחִלָּה וְעַד סוֹף שְׁנֵיהֶן חַיָּבִין וְשִׁעוּר אֶחָד לִשְׁנֵיהֶן. הָיָה כֹּחַ בְּאֶחָד לְהוֹצִיא קוֹרָה זוֹ לְבַדּוֹ וְהַשֵּׁנִי אֵינוֹ יָכוֹל לְהוֹצִיאָהּ לְבַדּוֹ וְנִשְׁתַּתְּפוּ שְׁנֵיהֶם וְהוֹצִיאוּהָ. זֶה הָרִאשׁוֹן שֶׁיָּכוֹל חַיָּב וְהַשֵּׁנִי מְסַיֵּעַ הוּא וּמְסַיֵּעַ אֵינוֹ חַיָּב כְּלוּם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כָּל הַמְקַלְקְלִין פְּטוּרִין. כֵּיצַד. הֲרֵי שֶׁחָבַל בַּחֲבֵרוֹ אוֹ בִּבְהֵמָה דֶּרֶךְ הַשְׁחָתָה וְכֵן אִם קָרַע בְּגָדִים אוֹ שְׂרָפָן אוֹ שָׁבַר כֵּלִים דֶּרֶךְ הַשְׁחָתָה הֲרֵי זֶה פָּטוּר. חָפַר גּוּמָא וְאֵינוֹ צָרִיךְ אֶלָּא לַעֲפָרָהּ הֲרֵי זֶה מְקַלְקֵל וּפָטוּר. אַף עַל פִּי שֶׁעָשָׂה מְלָאכָה הוֹאִיל וְכַוָּנָתוֹ לְקַלְקֵל פָּטוּר:","כָּל הַמְקַלְקֵל עַל מְנָת לְתַקֵּן חַיָּב. כֵּיצַד. הֲרֵי שֶׁסָּתַר כְּדֵי לִבְנוֹת בִּמְקוֹמוֹ אוֹ שֶׁמָּחַק כְּדֵי לִכְתֹּב בַּמָּקוֹם שֶׁמָּחַק אוֹ שֶׁחָפַר גּוּמָא כְּדֵי לִבְנוֹת בְּתוֹכָהּ יְסוֹדוֹת וְכָל כַּיּוֹצֵא בָּזֶה חַיָּב. וְשִׁעוּרָן כְּשִׁעוּר הַמְתַקֵּן:","כָּל הָעוֹשֶׂה מְלָאכָה בְּשַׁבָּת מִקְצָתָהּ בְּשׁוֹגֵג וּמִקְצָתָהּ בְּזָדוֹן בֵּין שֶׁהֵזִיד וּלְבַסּוֹף שָׁגַג בֵּין שֶׁשָּׁגַג וּלְבַסּוֹף הֵזִיד פָּטוּר עַד שֶׁיַּעֲשֶׂה שִׁעוּר הַמְּלָאכָה כֻּלָּהּ מִתְּחִלָּה וְעַד סוֹף בְּזָדוֹן וְאַחַר כָּךְ יִהְיֶה חַיָּב כָּרֵת. וְאִם יִהְיֶה בְּעֵדִים וְהַתְרָאָה חַיָּב סְקִילָה. אוֹ שֶׁיַּעֲשֶׂה שִׁעוּר מְלָאכָה כֻּלָּהּ בִּשְׁגָגָה מִתְּחִלָּה וְעַד סוֹף וְאַחַר כָּךְ יִהְיֶה חַיָּב חַטָּאת קְבוּעָה:"],"Mishneh Torah, Sabbath 20":["אָסוּר לְהוֹצִיא מַשָּׂא עַל הַבְּהֵמָה בְּשַׁבָּת שֶׁנֶּאֱמַר (שמות כג יב) \"לְמַעַן יָנוּחַ שׁוֹרְךָ וַחֲמֹרֶךָ\" וְכָל בְּהֶמְתֶּךָ. אֶחָד שׁוֹר וַחֲמוֹר וְאֶחָד כָּל בְּהֵמָה חַיָּה וָעוֹף. וְאִם הוֹצִיא עַל הַבְּהֵמָה אַף עַל פִּי שֶׁהוּא מְצֻוֶּה עַל שְׁבִיתָתָהּ אֵינוֹ לוֹקֶה לְפִי שֶׁאִסּוּרוֹ בָּא מִכְּלַל עֲשֵׂה. לְפִיכָךְ הַמְחַמֵּר אַחַר בְּהֶמְתּוֹ בְּשַׁבָּת וְהָיָה עָלֶיהָ מַשּׂאוֹי פָּטוּר:","וַהֲלֹא לָאו מְפֹרָשׁ בַּתּוֹרָה שֶׁנֶּאֱמַר (שמות כ י) \"לֹא תַעֲשֶׂה כָל מְלָאכָה אַתָּה וּבִנְךָ וּבִתֶּךָ וְעַבְדְּךָ וַאֲמָתֶךָ וּבְהֶמְתֶּךָ\", שֶׁלֹּא יַחֲרשׁ בָּהּ וְכַיּוֹצֵא בַּחֲרִישָׁה. וְנִמְצָא לָאו שֶׁנִּתָּן לְאַזְהָרַת מִיתַת בֵּית דִּין וְאֵין לוֹקִין עָלָיו:","אָסוּר לְיִשְׂרָאֵל לְהַשְׁאִיל אוֹ לְהַשְׂכִּיר בְּהֵמָה גַּסָּה לְנָכְרִי שֶׁלֹּא יַעֲשֶׂה בָּהּ מְלָאכָה בְּשַׁבָּת וַהֲרֵי הוּא מְצֻוֶּה עַל שְׁבִיתַת בְּהֶמְתּוֹ. אָסְרוּ חֲכָמִים לִמְכֹּר בְּהֵמָה גַּסָּה לְנָכְרִי שֶׁמָּא יַשְׁאִיל אוֹ יַשְׂכִּיר. וְאִם מָכַר קוֹנְסִין אוֹתוֹ עַד עֲשָׂרָה בְּדָמֶיהָ וּמַחֲזִירָהּ. וַאֲפִלּוּ שְׁבוּרָה אֵין מוֹכְרִין. וּמֻתָּר לוֹ לִמְכֹּר לָהֶם עַל יְדֵי סַרְסוּר שֶׁהַסַּרְסוּר אֵינוֹ מַשְׂכִּיר וְאֵינוֹ מַשְׁאִיל:","וּמֻתָּר לִמְכֹּר לָהֶם סוּס שֶׁאֵין הַסּוּס עוֹמֵד אֶלָּא לִרְכִיבַת אָדָם לֹא לְמַשּׂאוֹי וְהַחַי נוֹשֵׂא אֶת עַצְמוֹ. וּכְדֶרֶךְ שֶׁאָסְרוּ לִמְכֹּר לְנָכְרִי כָּךְ אָסְרוּ לִמְכֹּר לְיִשְׂרָאֵל הֶחָשׁוּד לִמְכֹּר לְנָכְרִי. וּמֻתָּר לִמְכֹּר לָהֶם פָּרָה לִשְׁחִיטָה וְשׁוֹחֵט אוֹתָהּ בְּפָנָיו. וְלֹא יִמְכֹּר סְתָם אֲפִלּוּ שׁוֹר שֶׁל פְּטָם שֶׁמָּא יַשְׁהֵא אוֹתוֹ וְיַעֲבֹד בּוֹ:","מָקוֹם שֶׁנָּהֲגוּ לִמְכֹּר לָהֶן בְּהֵמָה דַּקָּה מוֹכְרִין. מָקוֹם שֶׁנָּהֲגוּ שֶׁלֹּא לִמְכֹּר אֵין מוֹכְרִין. וּבְכָל מָקוֹם אֵין מוֹכְרִין לָהֶם חַיָּה גַּסָּה כְּמוֹ שֶׁאֵין מוֹכְרִין לָהֶם בְּהֵמָה גַּסָּה אֶלָּא עַל יְדֵי סַרְסוּר:","מִי שֶׁהֶחְשִׁיךְ בַּדֶּרֶךְ וְלֹא הָיָה עִמּוֹ נָכְרִי שֶׁיִּתֵּן לוֹ כִּיסוֹ וְהָיְתָה עִמּוֹ בְּהֵמָה. מַנִּיחַ כִּיסוֹ עָלֶיהָ כְּשֶׁהִיא מְהַלֶּכֶת וּכְשֶׁתִּרְצֶה לַעֲמֹד נוֹטְלוֹ מֵעָלֶיהָ כְּדֵי שֶׁלֹּא תַּעֲמֹד וְהוּא עָלֶיהָ וּכְדֵי שֶׁלֹּא תִּהְיֶה שָׁם לֹא עֲקִירָה וְלֹא הַנָּחָה. וְאָסוּר לוֹ לְהַנְהִיגָהּ וַאֲפִלּוּ בְּקוֹל כָּל זְמַן שֶׁהַכִּיס עָלֶיהָ כְּדֵי שֶׁלֹּא יִהְיֶה מְחַמֵּר בְּשַׁבָּת. וּגְזֵרַת חֲכָמִים הִיא שֶׁלֹּא יַנִּיחַ כִּיסוֹ עַל גַּבֵּי בְּהֵמָה אֶלָּא אִם אֵין עִמּוֹ נָכְרִי:","הָיָה עִמּוֹ חֵרֵשׁ שׁוֹטֶה וְקָטָן מַנִּיחַ כִּיסוֹ עַל הַחֲמוֹר וְאֵינוֹ נוֹתְנוֹ לְאֶחָד מֵהֶן מִפְּנֵי שֶׁהֵן אָדָם מִיִּשְׂרָאֵל. הָיָה עִמּוֹ חֵרֵשׁ וְשׁוֹטֶה וְאֵין עִמּוֹ בְּהֵמָה נוֹתְנוֹ לְשׁוֹטֶה. שׁוֹטֶה וְקָטָן נוֹתְנוֹ לְשׁוֹטֶה. חֵרֵשׁ וְקָטָן נוֹתְנוֹ לְאֵי זֶה מֵהֶן שֶׁיִּרְצֶה. לֹא הָיְתָה עִמּוֹ בְּהֵמָה וְלֹא נָכְרִי וְלֹא אֶחָד מִכָּל אֵלּוּ מְהַלֵּךְ בּוֹ פָּחוֹת פָּחוֹת מֵאַרְבַּע אַמּוֹת. וַאֲפִלּוּ מְצִיאָה שֶׁבָּאָה לְיָדוֹ מְהַלֵּךְ בָּהּ פָּחוֹת פָּחוֹת מֵאַרְבַּע אַמּוֹת. אֲבָל קֹדֶם שֶׁתָּבוֹא לְיָדוֹ אִם יָכוֹל לְהַחְשִׁיךְ עָלֶיהָ מַחְשִׁיךְ וְאִם לָאו מוֹלִיכָהּ פָּחוֹת פָּחוֹת מֵאַרְבַּע אַמּוֹת:","מֻתָּר לִמְשֹׁךְ אֶת הַבְּהֵמָה בְּמֶתֶג וָרֶסֶן שֶׁלָּהּ לִרְשׁוּת הָרַבִּים וְהוּא שֶׁתִּהְיֶה רְאוּיָה לְאוֹתוֹ הָרֶסֶן. כְּגוֹן שִׁיר לְסוּס וְאַפְסָר לְגָמָל וַחֲטָם לְנָאקָה וְסוּגַר לְכֶלֶב. אֲבָל אִם הוֹצִיא בְּהֵמָה בְּמֶתֶג שֶׁאֵין מִשְׁתַּמֶּרֶת בּוֹ כְּגוֹן שֶׁקָּשַׁר חֶבֶל בְּפִי הַסּוּס אוֹ בְּמֶתֶג שֶׁאֵינָהּ צְרִיכָה לוֹ אֶלָּא מִשְׁתַּמֶּרֶת בְּפָחוֹת מִמֶּנּוּ. כְּגוֹן שֶׁהוֹצִיא חֲמוֹר בְּשִׁיר שֶׁל סוּס אוֹ חָתוּל בְּסוּגַר הֲרֵי זֶה מַשּׂאוֹי. שֶׁכָּל שְׁמִירָה מְעֻלָּה אוֹ שְׁמִירָה פְּחוּתָה מַשּׂאוֹי הוּא לָהּ:","לֹא יִקְשֹׁר גְּמַלִּים זֶה בָּזֶה וְיִמְשֹׁךְ אֲפִלּוּ הָיוּ קְשׁוּרִין מֵעֶרֶב שַׁבָּת אֵינָן נִמְשָׁכִין בְּשַׁבָּת. אֲבָל מַכְנִיס הוּא חֲבָלִים לְתוֹךְ יָדוֹ וְהוּא שֶׁלֹּא יֵצֵא חֶבֶל מִתּוֹךְ יָדוֹ טֶפַח. וְצָרִיךְ שֶׁיִּהְיֶה הַחֶבֶל שֶׁמִּפִּי הַבְּהֵמָה עַד יָדוֹ גָּבוֹהַּ מִן הָאָרֶץ טֶפַח אוֹ יוֹתֵר. וּמִפְּנֵי מָה לֹא יִמְשֹׁךְ הַגְּמַלִּים הַקְּשׁוּרִים זֶה בָּזֶה מִפְּנֵי שֶׁהוּא נִרְאֶה כְּמִי שֶׁמּוֹלִיכָן לְשׁוּק שֶׁמּוֹכְרִין בּוֹ הַבְּהֵמוֹת אוֹ שֶׁמְּשַׂחֲקִין בָּהֶן שָׁם. וּמִפְּנֵי זֶה לֹא תֵּצֵא בְּהֵמָה בְּזוֹג שֶׁבְּצַוָּארָהּ וַאֲפִלּוּ הָיָה פָּקוּק שֶׁאֵין לוֹ קוֹל:","לֹא תֵּצֵא בְּהֵמָה בְּזוּג שֶׁבִּכְסוּתָהּ וְלֹא בְּחוֹתָם שֶׁבְּצַוָּארָהּ וְלֹא בְּחוֹתָם שֶׁבִּכְסוּתָהּ וְלֹא בִּרְצוּעָה שֶׁבְּרַגְלָהּ וְלֹא בְּסֻלָּם שֶׁבְּצַוָּארָהּ. וְאֵין חֲמוֹר יוֹצֵא בְּמַרְדַּעַת אֶלָּא אִם כֵּן הָיְתָה קְשׁוּרָה לוֹ מֵעֶרֶב שַׁבָּת. וְלֹא יֵצֵא גָּמָל בַּמְּטוּטֶלֶת הַתְּלוּיָה לוֹ בְּדַבַּשְׁתּוֹ אוֹ בִּזְנָבוֹ אֶלָּא אִם כֵּן הָיְתָה קְשׁוּרָה בִּזְנָבוֹ וְחוֹטַרְתּוֹ. וְלֹא יֵצֵא הַגָּמָל עֲקוּד יָד וְלֹא עֲקוּד רֶגֶל וְכֵן שְׁאָר כָּל הַבְּהֵמוֹת:","אֵין הַתַּרְנְגוֹלִים יוֹצְאִין בְּחוּטִין וְלֹא בָּרְצוּעוֹת שֶׁבְּרַגְלֵיהֶם. וְאֵין הַכְּבָשִׂין יוֹצְאִין בָּעֲגָלָה שֶׁתַּחַת אַלְיָה שֶׁלָּהֶן. וְאֵין הַכְּבָשׂוֹת יוֹצְאוֹת בָּעֵצִים שֶׁמַּנִּיחִים לָהֶן בְּחָטְמָן כְּדֵי שֶׁיִּתְעַטְּשׁוּ וְיִפְּלוּ הַתּוֹלָעִין שֶׁבְּמֹחָן. וְאֵין הָעֵגֶל יוֹצֵא בְּעל קָטָן שֶׁמַּנִּיחִין לוֹ עַל צַוָּארוֹ כְּדֵי שֶׁיִּכָּנַע וְיִהְיֶה נוֹחַ לַחֲרִישָׁה. וְלֹא תֵּצֵא בְּהֵמָה בִּשְׂבָכָה שֶׁמַּנִּיחִין לָהּ בְּפִיהָ כְּדֵי שֶׁלֹּא תִּשֹּׁךְ אוֹ שֶׁלֹּא תֹּאכַל. לֹא תֵּצֵא הַפָּרָה בְּעוֹר הַקּוּפָּר שֶׁמַּנִּיחִין לָהּ עַל דַּדֶּיהָ כְּדֵי שֶׁלֹּא יִינַק מִמֶּנָּה הַשֶּׁרֶץ כְּשֶׁהִיא יְשֵׁנָה. וְלֹא תֵּצֵא בָּרְצוּעָה שֶׁבֵּין קַרְנֶיהָ בֵּין לְנוֹי בֵּין לְשַׁמֵּר. עֵז שֶׁחָקַק לָהּ בְּקַרְנֶיהָ יוֹצְאָה בְּאַפְסָר הַקָּשׁוּר בְּחֶקֶק בְּשַׁבָּת. וְאִם תְּחָבוֹ בִּזְקָנָהּ אָסוּר שֶׁמָּא תְּנַתְּחֶנּוּ וִיבִיאֶנּוּ בְּיָדוֹ בִּרְשׁוּת הָרַבִּים. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַזְּכָרִים יוֹצְאִים בָּעוֹר הַקָּשׁוּר לָהֶן עַל זַכְרוּתָן כְּדֵי שֶׁלֹּא יַעֲלוּ עַל הַנְּקֵבוֹת. וּבָעוֹר הַקָּשׁוּר לָהֶם עַל לִבֵּיהֶם כְּדֵי שֶׁלֹּא יִפְּלוּ עֲלֵיהֶם זְאֵבִים. וּבְמַטְלָנִיּוֹת הַמְרֻקָּמוֹת שֶׁמְּיַפִּין אוֹתָן בָּהֶן. וְהָרְחֵלוֹת יוֹצְאוֹת וְאַלְיָה שֶׁלָּהֶן קְשׁוּרָה לְמַעְלָה עַל גַּבָּן כְּדֵי שֶׁיַּעֲלוּ עֲלֵיהֶן הַזְּכָרִים. אוֹ קְשׁוּרָה לְמַטָּה כְּדֵי שֶׁלֹּא יַעֲלוּ עֲלֵיהֶם הַזְּכָרִים. וְיוֹצְאוֹת מְלֻפָּפוֹת בְּמַטְלָנִיּוֹת כְּדֵי שֶׁיִּהְיֶה הַצֶּמֶר שֶׁלָּהֶן נָקִי. הָעִזִּים יוֹצְאוֹת וְדַדֵּיהֶן קְשׁוּרוֹת כְּדֵי שֶׁיִּיבַשׁ מֵהֶן הֶחָלָב. אֲבָל אִם קְשָׁרָן כְּדֵי שֶׁלֹּא יֵצֵא הֶחָלָב עַד שֶׁיַּחֲלֹב אוֹתוֹ לָעֶרֶב הֲרֵי אֵלּוּ לֹא יֵצְאוּ:","אֵין חֲמוֹר יוֹצֵא בְּאֻכָּף אַף עַל פִּי שֶׁקָּשׁוּר מֵעֶרֶב שַׁבָּת. וְלֹא יֵצֵא הַסּוּס בִּזְנַב שׁוּעָל וְלֹא בִּזְהוֹרִית שֶׁבֵּין עֵינָיו. וְלֹא תֵּצֵא בְּהֵמָה בִּקְרַסְטָל שֶׁבְּפִיהָ וְלֹא בְּסַנְדָּל שֶׁבְּרַגְלָהּ וְלֹא בְּקָמֵעַ שֶׁאֵינוֹ מֻמְחֶה לִבְהֵמָה. אֲבָל יוֹצְאָה הִיא בְּאֶגֶד שֶׁעַל גַּב הַמַּכָּה וּבְקַשְׁקַשִּׁים שֶׁעַל גַּבֵּי הַשֶּׁבֶר. וּבְשִׁלְיָה הַמְדֻלְדֶּלֶת בָּהּ. וּפוֹקֵק לָהּ זוֹג שֶׁבְּצַוָּארָהּ וּמְטַיֶּלֶת בּוֹ בֶּחָצֵר. וְנוֹתֵן לוֹ מַרְדַּעַת עַל הַחֲמוֹר בְּשַׁבָּת וּמְטַיֵּל בֶּחָצֵר. אֲבָל אֵין תּוֹלִין לָהּ קְרַסְטָל בְּפִיהָ בְּשַׁבָּת:","כְּשֵׁם שֶׁאָדָם מְצֻוֶּה עַל שְׁבִיתַת בְּהֶמְתּוֹ בְּשַׁבָּת כָּךְ הוּא מְצֻוֶּה עַל שְׁבִיתַת עַבְדּוֹ וַאֲמָתוֹ וְאַף עַל פִּי שֶׁהֵן בְּנֵי דַּעַת וּלְדַעַת עַצְמָן עוֹשִׂין מִצְוָה עָלֵינוּ לְשָׁמְרָן וּלְמָנְעָן מֵעֲשִׂיַּת מְלָאכָה בְּשַׁבָּת שֶׁנֶּאֱמַר (שמות כג יב) \"לְמַעַן יָנוּחַ שׁוֹרְךָ וַחֲמֹרֶךָ וְיִנָּפֵשׁ בֶּן אֲמָתְךָ וְהַגֵּר\". עֶבֶד וְאָמָה שֶׁאָנוּ מְצֻוִּין עַל שְׁבִיתָתָן הֵם עֲבָדִים שֶׁמָּלוּ וְטָבְלוּ לְשֵׁם עַבְדוּת וְקִבְּלוּ מִצְוֹת שֶׁהָעֲבָדִים חַיָּבִין בָּהֶן. אֲבָל עֲבָדִים שֶׁלֹּא מָלוּ וְלֹא טָבְלוּ אֶלָּא קִבְּלוּ עֲלֵיהֶן שֶׁבַע מִצְוֹת שֶׁנִּצְטַוּוּ בְּנֵי נֹחַ בִּלְבַד הֲרֵי הֵן כְּגֵר תּוֹשָׁב וּמֻתָּרִין לַעֲשׂוֹת מְלָאכָה בְּשַׁבָּת לְעַצְמָן בְּפַרְהֶסְיָא כְּיִשְׂרָאֵל בְּחל. וְאֵין מְקַבְּלִין גֵּר תּוֹשָׁב אֶלָּא בִּזְמַן שֶׁהַיּוֹבֵל נוֹהֵג. הוֹאִיל וְגֵר תּוֹשָׁב עוֹשֶׂה מְלָאכָה לְעַצְמוֹ בְּשַׁבָּת וְגֵר צֶדֶק הֲרֵי הוּא כְּיִשְׂרָאֵל לְכָל דָּבָר. בְּמִי נֶאֱמַר וְיִנָּפֵשׁ בֶּן אֲמָתְךָ וְהַגֵּר. זֶה גֵּר תּוֹשָׁב שֶׁהוּא לְקִיטוֹ וּשְׂכִירוֹ שֶׁל יִשְׂרָאֵל כְּמוֹ בֶּן אֲמָתוֹ. שֶׁלֹּא יַעֲשֶׂה מְלָאכָה לְיִשְׂרָאֵל רַבּוֹ בְּשַׁבָּת אֲבָל לְעַצְמוֹ עוֹשֶׂה. וַאֲפִלּוּ הָיָה הַגֵּר זֶה עַבְדּוֹ הֲרֵי זֶה עוֹשֶׂה לְעַצְמוֹ:"],"Mishneh Torah, Sabbath 4":["יֵשׁ דְּבָרִים שֶׁאִם טָמַן בָּהֶן הַתַּבְשִׁיל הוּא מִתְחַמֵּם וּמוֹסִיפִין בְּבִשּׁוּלוֹ כְּעֵין הָאֵשׁ. כְּגוֹן הַגֶּפֶת וְזֶבֶל וּמֶלַח וְסִיד וְחוֹל אוֹ זַגִּין וּמוֹכִין וַעֲשָׂבִים בִּזְמַן שֶׁשְּׁלָשְׁתָּן לַחִים וַאֲפִלּוּ מֵחֲמַת עַצְמָן. וּדְבָרִים אֵלּוּ נִקְרָאִין דָּבָר הַמּוֹסִיף הֶבֶל. וְיֵשׁ דְּבָרִים שֶׁאִם טָמַן בָּהֶן הַתַּבְשִׁיל יִשָּׁאֵר בַּחֲמִימוּתוֹ בִּלְבַד וְאֵינָן מוֹסִיפִין לוֹ בִּשּׁוּל אֶלָּא מוֹנְעִין אוֹתוֹ מִלְּהִצְטַנֵּן. כְּגוֹן זַגִּין וּמוֹכִין וַעֲשָׂבִים יְבֵשִׁין וּכְסוּת וּפֵרוֹת וְכַנְפֵי יוֹנָה וּנְעֹרֶת הַפִּשְׁתָּן וּנְסֹרֶת חָרָשִׁים וּשְׁלָחִין וְגִזֵּי צֶמֶר. וּדְבָרִים אֵלּוּ נִקְרָאִין דָּבָר שֶׁאֵינוֹ מוֹסִיף הֶבֶל:","מִן הַדִּין הָיָה שֶׁטּוֹמְנִין בְּדָבָר הַמּוֹסִיף הֶבֶל מִבְּעוֹד יוֹם וְיִשָּׁאֵר הַתַּבְשִׁיל טָמוּן בְּשַׁבָּת. שֶׁהֲרֵי מַשְׁהִין עַל גַּבֵּי הָאֵשׁ בְּשַׁבָּת. אֲבָל אָסְרוּ חֲכָמִים לְהַטְמִין בְּדָבָר הַמּוֹסִיף הֶבֶל מִבְּעוֹד יוֹם גְּזֵרָה שֶׁמָּא תַּרְתִּיחַ הַקְּדֵרָה בְּשַׁבָּת וְיִצְטָרֵךְ לְגָלוֹתָן עַד שֶׁתָּנוּחַ הָרְתִיחָה וְיַחֲזֹר וִיכַסֶּה בְּשַׁבָּת וְנִמְצָא טוֹמֵן בְּדָבָר הַמּוֹסִיף הֶבֶל בְּשַׁבָּת שֶׁהוּא אָסוּר. לְפִיכָךְ מֻתָּר לְהַטְמִין בְּדָבָר הַמּוֹסִיף הֶבֶל בֵּין הַשְּׁמָשׁוֹת שֶׁסְּתָם קְדֵרוֹת בֵּין הַשְּׁמָשׁוֹת כְּבָר רָתְחוּ וְנָחוּ מִבִּעֲבּוּעָן וְכֵיוָן שֶׁנָּחוּ שׁוּב אֵינָן רוֹתְחִין:","וְכֵן מִן הַדִּין הָיָה לִטְמֹן הַתַּבְשִׁיל בְּדָבָר שֶׁאֵינוֹ מוֹסִיף הֶבֶל בְּשַׁבָּת עַצְמָהּ. אֲבָל אָסְרוּ חֲכָמִים דָּבָר זֶה גְּזֵרָה שֶׁמָּא יַטְמִין בְּרֶמֶץ וְיִהְיֶה בּוֹ נִיצוֹצוֹת שֶׁל אֵשׁ וְנִמְצָא חוֹתֶה בַּגֶּחָלִים. לְפִיכָךְ אָסְרוּ לְהַטְמִין דָּבָר חַם בְּשַׁבָּת וַאֲפִלּוּ בְּדָבָר שֶׁאֵינוֹ מוֹסִיף הֶבֶל:","סָפֵק חֲשֵׁכָה סָפֵק אֵינָהּ חֲשֵׁכָה מֻתָּר לִטְמוֹן אֶת דָּבָר חַם. וּמֻתָּר לִטְמוֹן אֶת דָּבָר הַצּוֹנֵן בְּשַׁבָּת בְּדָבָר שֶׁאֵינוֹ מוֹסִיף כְּדֵי שֶׁלֹּא יִצְטַנֵּן בְּיוֹתֵר אוֹ כְּדֵי שֶׁתָּפוּג צִנָּתָן. חַמִּין שֶׁטְּמָנָן מֵעֶרֶב שַׁבָּת וְנִתְגַּלּוּ בְּשַׁבָּת מֻתָּר לְכַסּוֹתָן. שֶׁהֲרֵי אֵינוֹ מוֹסִיף. וּמֻתָּר לְהַחֲלִיף הַכִּסּוּי בְּשַׁבָּת. כֵּיצַד. נוֹטֵל כְּסוּת וּמַנִּיחַ כַּנְפֵי יוֹנָה אוֹ נוֹטֵל כַּנְפֵי יוֹנָה וּמַנִּיחַ הַכְּסוּת:","פִּנָּה הַתַּבְשִׁיל אוֹ הַמַּיִם הַחַמִּין מִכְּלִי לִכְלִי אַחֵר מֻתָּר לְהַטְמִין הַכְּלִי הָאַחֵר בְּשַׁבָּת בְּדָבָר שֶׁאֵינוֹ מוֹסִיף. כְּמוֹ הַדָּבָר הַצּוֹנֵן. שֶׁלֹּא אָסְרוּ לְהַטְמִין בְּשַׁבָּת אֶלָּא דָּבָר חַם שֶׁהוּא בִּכְלִי רִאשׁוֹן שֶׁנִתְבַּשֵּׁל בּוֹ אֲבָל אִם פִּנָּהוּ מֻתָּר:","מַנִּיחִין מֵיחַם עַל גַּבֵּי מֵיחַם בְּשַׁבָּת וּקְדֵרָה עַל גַּבֵּי קְדֵרָה וּקְדֵרָה עַל גַּבֵּי מֵיחַם וּמֵיחַם עַל גַּבֵּי קְדֵרָה וְטָח פִּיהֶם בְּבָצֵק לֹא בִּשְׁבִיל שֶׁיּוּחַמּוּ אֶלָּא בִּשְׁבִיל שֶׁיַּעַמְדוּ עַל חֻמָּם. שֶׁלֹּא אָסְרוּ אֶלָּא לְהַטְמִין בְּשַׁבָּת אֲבָל לְהַנִּיחַ כְּלִי חַם עַל גַּב כְּלִי חַם כְּדֵי שֶׁיִּהְיוּ עוֹמְדִין בַּחֲמִימוּתָן מֻתָּר. אֲבָל אֵין מַנִּיחִין כְּלִי שֶׁיֵּשׁ בּוֹ דָּבָר צוֹנֵן עַל גַּבֵּי כְּלִי חַם בְּשַׁבָּת שֶׁהֲרֵי מוֹלִיד בּוֹ חֹם בְּשַׁבָּת וְאִם הִנִּיחוֹ מִבָּעֶרֶב מֻתָּר וְאֵינוֹ כְּטוֹמֵן בְּדָבָר הַמּוֹסִיף:"],"Mishneh Torah, Sabbatical Year and the Jubilee 3":["עֲבוֹדַת הָאָרֶץ בְּשָׁנָה שִׁשִּׁית שְׁלֹשִׁים יוֹם סָמוּךְ לַשְּׁבִיעִית אֲסוּרָה הֲלָכָה לְמשֶׁה מִסִּינַי. מִפְּנֵי שֶׁהוּא מְתַקְּנָהּ לַשְּׁבִיעִית. וְדָבָר זֶה בִּזְמַן שֶׁבֵּית הַמִּקְדָּשׁ קַיָּם הוּא שֶׁנֶּאֱסַר מִפִּי הַשְּׁמוּעָה. וְגָזְרוּ חֲכָמִים שֶׁלֹּא יִהְיוּ חוֹרְשִׁים שְׂדֵה הָאִילָן עֶרֶב שְׁבִיעִית בִּזְמַן הַמִּקְדָּשׁ אֶלָּא עַד הָעֲצֶרֶת. וּשְׂדֵה הַלָּבָן עַד הַפָּסַח. וּבַזְּמַן שֶׁאֵין מִקְדָּשׁ מֻתָּרִין בַּעֲבוֹדַת הָאָרֶץ עַד רֹאשׁ הַשָּׁנָה כְּדִין תּוֹרָה:","אֵי זוֹ הִיא שְׂדֵה הָאִילָן. כָּל שְׁלֹשָׁה אִילָנוֹת לְבֵית סְאָה. אֶחָד אִילַן סְרָק וְאַחַד אִילַן מַאֲכָל וַאֲפִלּוּ הֵן שֶׁל שְׁלֹשָׁה אֲנָשִׁים רוֹאִין אוֹתָן כְּאִלּוּ הֵם תְּאֵנִים. אִם רְאוּיִין לַעֲשׂוֹת כִּכַּר דְּבֵלָה שֶׁל שִׁשִּׁים מָנֶה חוֹרְשִׁין כָּל בֵּית סְאָה בִּשְׁבִילָם. וְהוּא שֶׁיִּהְיֶה רָחוֹק בֵּין כָּל אֶחָד וְאֶחָד כְּדֵי שֶׁיִּהְיֶה הַבָּקָר יָכוֹל לַעֲבֹר בְּכֵלָיו:","הָיוּ פָּחוֹת מִשְּׁלֹשָׁה לְבֵית סְאָה. אוֹ שֶׁהָיוּ שְׁלֹשָׁה וְאֶחָד רָאוּי לַעֲשׂוֹת שִׁשִּׁים מָנֶה אוֹ יֶתֶר וְהַשְּׁנַיִם אֵינָן רְאוּיִין לַעֲשׂוֹת. אוֹ שְׁנַיִם רְאוּיִין לַעֲשׂוֹת אֲפִלּוּ מֵאָה מָנֶה וְאֶחָד אֵינוֹ עוֹשֶׂה. אֵין חוֹרְשִׁין לָהֶן אֶלָּא לְצָרְכָּם וְהוּא מְלֹא הָאוֹרֶה וְסַלּוֹ חוּצָה לוֹ:","הָיוּ מִשְׁלֹשָׁה וְעַד תִּשְׁעָה וּרְאוּיִין לַעֲשׂוֹת שִׁשִּׁים מָנֶה חוֹרְשִׁין כָּל בֵּית סְאָה בִּשְׁבִילָן וְאַף עַל פִּי שֶׁיֵּשׁ בָּהֶם מִי שֶׁאֵינוֹ רָאוּי לַעֲשׂוֹת:","הָיוּ עֲשָׂרָה אִילָנוֹת לְתוֹךְ בֵּית סְאָה אוֹ יֶתֶר בֵּין עוֹשִׂין בֵּין אֵינָם עוֹשִׂין חוֹרְשִׁין כָּל בֵּית סְאָה בִּשְׁבִילָן. עֶשֶׂר נְטִיעוֹת מְפֻזָּרוֹת לְתוֹךְ בֵּית סְאָה חוֹרְשִׁין כָּל בֵּית סְאָה בִּשְׁבִילָן עַד רֹאשׁ הַשָּׁנָה וְדָבָר זֶה הֲלָכָה לְמשֶׁה מִסִּינַי:","הָיוּ עֲשׂוּיוֹת שׁוּרָה אַחַת (אוֹ) מֻקָּפוֹת עֲטָרָה אֵין חוֹרְשִׁין לָהֶן אֶלָּא צָרְכָּן לְכָל אֶחָד וְאֶחָד. וְהַדִּלּוּעִין עִם הַנְּטִיעוֹת מִצְטָרְפוֹת לַעֲשָׂרָה:","אֵי זוֹ הִיא נְטִיעָה זֶה הָאִילָן הַקָּטָן כָּל זְמַן שֶׁקּוֹרְאִין לוֹ נְטִיעָה:","אִילָן שֶׁנִּקְצַץ וְהוֹצִיא חֲלִיפִין אִם נִקְצַץ מִטֶּפַח וּלְמַעְלָה הֲרֵי הוּא כְּאִילָן. מִטֶּפַח וּלְמַטָּה הֲרֵי הוּא כִּנְטִיעָה:","וְכָל הַדְּבָרִים הָאֵלּוּ בִּזְמַן הַמִּקְדָּשׁ כְּמוֹ שֶׁאָמַרְנוּ. אֲבָל בַּזְּמַן הַזֶּה מֻתָּרִין בַּעֲבוֹדַת הָאָרֶץ עַד רֹאשׁ הַשָּׁנָה. אַף בִּזְמַן הַמִּקְדָּשׁ מֻתָּר לְסַקֵּל וּלְזַבֵּל הַשָּׂדוֹת וְלַעֲדֹר הַמִּקְשָׁאוֹת וְהַמִּדְלָעוֹת וּבֵית הַשְּׁלָחִין עַד רֹאשׁ הַשָּׁנָה. וּמְזַבְּלִין וּמְפָרְקִין וּמְאַבְּקִין וּמְעַשְּׁנִין וּמְקַרְסְמִין וּמְזָרְדִין וּמְפַסְּלִין וּמְזַהֲמִין אֶת הַנְּטִיעוֹת וְכוֹרְכִין וְקוֹטְמִין אוֹתָן. וְעוֹשִׂין לָהֶם בָּתִּים וּמַשְׁקִין אוֹתָם. וְסָכִין אֶת הַפַּגִּין. וּמְנַקְּבִין אוֹתָן. כָּל עֲבוֹדוֹת אֵלּוּ מֻתָּרוֹת בְּעֶרֶב שְׁבִיעִית עַד רֹאשׁ הַשָּׁנָה שֶׁל שְׁבִיעִית וַאֲפִלּוּ בִּזְמַן הַמִּקְדָּשׁ:","פַּגֵּי עֶרֶב שְׁבִיעִית שֶׁנִּכְנְסוּ לִשְׁבִיעִית וְשֶׁל שְׁבִיעִית שֶׁיָּצְאוּ לְמוֹצָאֵי שְׁבִיעִית לֹא סָכִין וְלֹא מְנַקְּבִין. וּבִזְמַן הַמִּקְדָּשׁ אֵין בּוֹנִין מַדְרֵגוֹת עַל פִּי הַגֵּאָיוֹת עֶרֶב שְׁבִיעִית מִשֶּׁיִּפָּסְקוּ הַגְּשָׁמִים. מִפְּנֵי שֶׁהוּא מְתַקְּנָן לַשְּׁבִיעִית:","אַף בַּזְּמַן הַזֶּה אֵין נוֹטְעִין אִילָנוֹת וְאֵין מַרְכִּיבִין וְאֵין מַבְרִיכִין עֶרֶב שְׁבִיעִית אֶלָּא כְּדֵי שֶׁתִּקְלֹט הַנְּטִיעָה וְתִשְׁהֶה אַחַר הַקְּלִיטָה שְׁלֹשִׁים יוֹם קֹדֶם רֹאשׁ הַשָּׁנָה שֶׁל שְׁבִיעִית. וּסְתָם קְלִיטָה שְׁתֵּי שַׁבָּתוֹת. וְדָבָר זֶה אָסוּר לְעוֹלָם מִפְּנֵי מַרְאִית הָעַיִן שֶׁמָּא יֹאמַר הָרוֹאֶה בַּשְּׁבִיעִית נִטְּעוּ. נִמְצֵאתָ אוֹמֵר שֶׁהַנּוֹטֵעַ אוֹ הַמַּבְרִיךְ אוֹ הַמַּרְכִּיב עֶרֶב שְׁבִיעִית קֹדֶם רֹאשׁ הַשָּׁנָה בְּמ\"ד יוֹם יְקַיֵּם. פָּחוֹת מִכֵּן יַעֲקֹר. וְאִם לֹא עָקַר הַפֵּרוֹת מֻתָּרִין. וְאִם מֵת קֹדֶם שֶׁיַּעֲקֹר מְחַיְּבִין אֶת הַיּוֹרֵשׁ לַעֲקֹר:"],"Mishneh Torah, Sacrifices Rendered Unfit 14":["אֵין הַמַּחֲשָׁבָה הוֹלֶכֶת אֶלָּא אַחַר הָעוֹבֵד. אֲבָל מַחֲשֶׁבֶת בַּעַל הַקָּרְבָּן אֵינָהּ מוֹעֶלֶת כְּלוּם. אֲפִלּוּ שָׁמַעְנוּ הַבְּעָלִים שֶׁפִּגְּלוּ וְהָיְתָה מַחֲשֶׁבֶת הָעוֹבֵד נְכוֹנָה הֲרֵי זֶה כָּשֵׁר:","וְאֵין הַמַּחְשָׁבָה מוֹעֶלֶת אֶלָּא מִמִּי שֶׁהוּא רָאוּי לַעֲבוֹדָה. וּבַדָּבָר הָרָאוּי לַעֲבוֹדָה. וּבְמָקוֹם רָאוּי לַעֲבוֹדָה. מִמִּי שֶׁהוּא רָאוּי כֵּיצַד. אֶחָד מִן הַפְּסוּלִין לַעֲבוֹדָה שֶׁקִּבֵּל הַדָּם. אוֹ הוֹלִיךְ. אוֹ זָרַק. וְחִשֵּׁב בִּשְׁעַת הָעֲבוֹדָה מַחֲשֶׁבֶת מָקוֹם אוֹ מַחֲשֶׁבֶת הַזְּמַן. לֹא פָּסַל בְּמַחֲשַׁבְתּוֹ. לְפִי שֶׁאֵינוֹ רָאוּי לַעֲבוֹדָה. וְאוֹתוֹ הַדָּם שֶׁקִּבֵּל אוֹ שֶׁזָּרַק מִקְצָתוֹ יִשָּׁפֵךְ לָאַמָּה. וְאִם נִשְׁאַר דַּם הַנֶּפֶשׁ יַחְזֹר הָרָאוּי לַעֲבוֹדָה וִיקַבֵּל בְּמַחְשָׁבָה נְכוֹנָה. אֲבָל אִם חָשַׁב הַפָּסוּל בִּשְׁעַת שְׁחִיטָה פָּסַל בְּמַחֲשַׁבְתּוֹ. שֶׁהַשְּׁחִיטָה כְּשֵׁרָה בִּפְסוּלִין כְּמוֹ שֶׁבֵּאַרְנוּ. יֵשׁ קָרְבָּנוֹת שֶׁאִם נַעֲשׂוּ שֶׁלֹּא לִשְׁמָן כְּשֵׁרִין כְּמוֹ שֶׁיִּתְבָּאֵר. לְפִיכָךְ אִם קִבֵּל הַדָּם כֹּהֵן זֶה שֶׁאֵינוֹ רָאוּי לַעֲבוֹדָה. אוֹ הוֹלִיכוֹ. אוֹ זְרָקוֹ. פָּסַל הַזֶּבַח כְּאִלּוּ עֲשָׂאָהוּ לִשְׁמוֹ שֶׁהוּא פָּסוּל. וְאַף עַל פִּי שֶׁיֵּשׁ דַּם הַנֶּפֶשׁ וְחָזַר הַכָּשֵׁר וְקִבֵּל וְזָרַק כְּבָר נִפְסַל הַזֶּבַח. וְלֹא מִפְּנֵי מַחֲשֶׁבֶת שִׁנּוּי הַשֵּׁם פָּסַל אוֹתוֹ אֶלָּא מִפְּנֵי שֶׁהוּא פָּסוּל לַעֲבוֹדָה כְּמוֹ שֶׁבֵּאַרְנוּ:","בְּדָבָר הָרָאוּי לַעֲבוֹדָה כֵּיצַד. מִנְחַת הָעֹמֶר שֶׁקְּמָצָהּ שֶׁלֹּא לִשְׁמָהּ הֲרֵי זוֹ כְּמִי שֶׁנַּעֲשֵׂית לִשְׁמָהּ וּשְׁיָרֶיהָ נֶאֱכָלִין. מִפְּנֵי שֶׁהִיא מִן הַשְּׂעוֹרִים וְאֵין הַשְּׂעוֹרִים דָּבָר הָרָאוּי לִשְׁאָר קָרְבָּנוֹת. וְכֵן הַמְחַשֵּׁב בְּמִנְחַת קְנָאוֹת וְהַלְּבוֹנָה עָלֶיהָ קֹדֶם שֶׁיְּלַקֵּט הַלְּבוֹנָה אֵין מַחְשַׁבְתּוֹ מוֹעֶלֶת שֶׁהֲרֵי אֵינָהּ דָּבָר הָרָאוּי לַעֲבוֹדָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","בְּמָקוֹם הָרָאוּי לַעֲבוֹדָה כֵּיצַד. מִזְבֵּחַ שֶׁנִּפְגַּם וְחִשֵּׁב מַחֲשֶׁבֶת זְמַן אוֹ מַחֲשֶׁבֶת מָקוֹם. לֹא פָּסַל הַזֶּבַח בְּמַחְשָׁבָה זוֹ שֶׁהֲרֵי אֵין הַמָּקוֹם עַתָּה רָאוּי לַעֲבוֹדָה. קָמַץ אֶת הַמִּנְחָה בַּחוּץ וְחִשֵּׁב בִּשְׁעַת קְמִיצָה מַחֲשֶׁבֶת זְמַן אוֹ מַחֲשֶׁבֶת מָקוֹם. אֵין מַחֲשָׁבָה זוֹ כְּלוּם:","אֵלּוּ דְּבָרִים שֶׁאֵינָן רְאוּיִין לַאֲכִילָה מִן הַקָּרְבָּנוֹת וּרְאוּיִין לְהַקְטָרָה. הַדָּם וְהָאֵימוּרִין וּבְשַׂר הָעוֹלָה וְהַקֹּמֶץ וְהַלְּבוֹנָה מִן הַמְּנָחוֹת הַנִּקְמָצוֹת:","וְאֵלּוּ רְאוּיִין לַאֲכִילָה וְאֵינָן רְאוּיִין לְהַקְטָרָה. הַבָּשָׂר הַנֶּאֱכָל מִכָּל הַזְּבָחִים בֵּין הַנֶּאֱכָל לַכֹּהֲנִים בֵּין הַנֶּאֱכָל לְכָל אָדָם. וּשְׁיָרֵי הַמְּנָחוֹת. וּשְׁתֵּי הַלֶּחֶם וְלֶחֶם הַפָּנִים:","וְאֵלּוּ דְּבָרִים שֶׁאֵינָן רְאוּיִין לֹא לַאֲכִילָה וְלֹא לְהַקְטָרָה. בְּשַׂר חַטָּאת הַנִּשְׂרֶפֶת. וְהָעוֹר שֶׁל בְּהֵמָה כֻּלּוֹ חוּץ מֵעוֹר הָאַלְיָה שֶׁהוּא [רָאוּי] לַאֲכִילָה. אֲבָל הַמּוּרְאָה וְהוּא הַקְּרוּם הַדַּק הַדָּבֵק בָּעוֹר וּמַבְדִּיל בֵּינוֹ וּבֵין הַבָּשָׂר אֵינוֹ רָאוּי לַאֲכִילָה. וְכֵן הָעֲצָמוֹת וְהַגִּידִים וְהַקַּרְנַיִם וְהַטְּלָפַיִם. וְהַנּוֹצָה שֶׁל עוֹף וְהַצִּפָּרְנַיִם וְהַחַרְטֹם שֶׁלּוֹ וְרָאשֵׁי אֲגַפַּיִים וְרֹאשׁ הַזָּנָב. אֲפִלּוּ מְקוֹמוֹת הָרַכִּים מִכָּל אֵלּוּ הַדְּבוּקִים בַּבָּשָׂר שֶׁאִלּוּ יֵחָתְכוּ מִן הַחַי יְבַצְבֵּץ הַדָּם וְיֵצֵא הוֹאִיל וְאֵינָן חֲשׁוּבִין נִקְרָאִים דָּבָר שֶׁאֵינוֹ רָאוּי לַאֲכִילָה לְעִנְיַן הַקָּרְבָּנוֹת. וְכֵן הַמָּרָק וְהַתַּבְלִין וְהַשָּׁלִיל וְהַשִּׁלְיָא וּבֵיצַת הָעוֹף וְהַבָּשָׂר שֶׁפּוֹלַטְתּוֹ הַסַּכִּין בִּשְׁעַת הֶפְשֵׁט וְיִשָּׁאֵר מֻדְבָּק בָּעוֹר וְהוּא הַנִּקְרָא אָלָל. כָּל אֵלּוּ אֵינָן חֲשׁוּבִין לְעִנְיָן מַחֲשֶׁבֶת הַקָּרְבָּנוֹת וַהֲרֵי הֵן כְּדָבָר שֶׁאֵין רָאוּי לַאֲכִילָה:","וּמְחַשְּׁבִין עַל דָּבָר הָעוֹמֵד לְאִבּוּד אוֹ עַל דָּבָר הָעוֹמֵד לִשְׂרֵפָה. הַמְחַשֵּׁב בְּאַחַת מֵאוֹתָן אַרְבַּע הָעֲבוֹדוֹת אוֹ בְּכֻלָּן. לֶאֱכל דָּבָר שֶׁאֵין דַּרְכּוֹ לַאֲכִילָה אוֹ לְהַקְטִיר דָּבָר שֶׁאֵין דַּרְכּוֹ לְהַקְטָרָה. בֵּין בְּמַחְשֶׁבֶת הַמָּקוֹם בֵּין בְּמַחְשֶׁבֶת הַזְּמַן. הַזֶּבַח כָּשֵׁר. כֵּיצַד. חִשֵּׁב לִשְׁתּוֹת מִדַּם הַזֶּבַח אוֹ לֶאֱכל מֵאֵימוּרָיו אוֹ מִן הַקֹּמֶץ וּמִן הַלְּבוֹנָה. בַּחוּץ אוֹ לְמָחָר. אוֹ שֶׁחִשֵּׁב לְהַקְטִיר מִבְּשַׂר הַזֶּבַח אוֹ מִשְּׁיָרֵי הַמִּנְחָה בַּחוּץ אוֹ לְמָחָר. הֲרֵי הַזֶּבַח כָּשֵׁר. וְכֵן אִם חִשֵּׁב לֶאֱכל אוֹ לְהַקְטִיר מִן הָעוֹר וּמִן הָעֲצָמוֹת וְהַגִּידִין וְהַמָּרָק אוֹ הָאָלָל וְכַיּוֹצֵא בָּהֶן. בֵּין בְּמַחְשֶׁבֶת זְמַן בֵּין בְּמַחְשֶׁבֶת מָקוֹם. הַזֶּבַח כָּשֵׁר. וְכֵן אִם חִשֵּׁב לֶאֱכל מִפָּרִים וּשְׂעִירִים הַנִּשְׂרָפִין בַּחוּץ אוֹ לְמָחָר הֲרֵי הֵן כְּשֵׁרִים. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","חִשֵּׁב שֶׁיֹּאכְלוּ הַטְּמֵאִים אוֹ הַפְּסוּלִין מִדָּבָר הָרָאוּי לַאֲכִילָה אוֹ שֶׁיַּקְטִירוּ הַטְּמֵאִים אוֹ הַפְּסוּלִין מִדָּבָר הָרָאוּי לְהַקְטָרָה חוּץ לִזְמַן אֲכִילָה וְהַקְטָרָה. הַזֶּבַח פִּגּוּל כְּמוֹ שֶׁבֵּאַרְנוּ. חוּץ לִמְקוֹם אֲכִילָה וְהַקְטָרָה הֲרֵי זֶה פָּסוּל וְאֵינוֹ פִּגּוּל:","אֵין אֲכִילָה פְּחוּתָה מִכְּזַיִת. וְלֹא הַקְטָרָה פְּחוּתָה מִכְּזַיִת. לְפִיכָךְ הַמְחַשֵּׁב לֶאֱכל מִדָּבָר הָרָאוּי לַאֲכִילָה פָּחוֹת מִכְּזַיִת אוֹ שֶׁחִשֵּׁב לְהַקְטִיר מִדָּבָר הָרָאוּי לְהַקְטָרָה פָּחוֹת מִכְּזַיִת בֵּין בְּמַחְשֶׁבֶת זְמַן בֵּין בְּמַחְשֶׁבֶת מָקוֹם. הַזֶּבַח כָּשֵׁר. חִשֵּׁב לֶאֱכל כַּחֲצִי זַיִת בַּחוּץ וּלְהַקְטִיר כַּחֲצִי זַיִת בַּחוּץ. אוֹ שֶׁחִשֵּׁב לֶאֱכל כַּחֲצִי זַיִת אַחַר זְמַן אֲכִילָה וּלְהַקְטִיר כַּחֲצִי זַיִת אַחַר זְמַן הַקְטָרָה. הַזֶּבַח כָּשֵׁר שֶׁאֵין אֲכִילָה וְהַקְטָרָה מִצְטָרְפִין. וְאִם הוֹצִיאוֹ בִּלְשׁוֹן אֲכִילָה וְאָמַר שֶׁיֹּאכַל כַּחֲצִי זַיִת וְתֹאכַל הָאֵשׁ חֲצִי זַיִת. הֲרֵי אֵלּוּ מִצְטָרְפִין לְשׁוֹן אֲכִילָה אֶחָד הוּא. חִשֵּׁב לֶאֱכל אוֹ לְהַקְטִיר כַּחֲצִי זַיִת וְחָזַר וְחִשֵּׁב עַל חֲצִי זַיִת אַחֵר בְּאוֹתָהּ הַמַּחְשָׁבָה. הֲרֵי אֵלּוּ מִצְטָרְפִין. חִשֵּׁב לֶאֱכל כַּחֲצִי זַיִת וְשֶׁתֹּאכַל בְּהֵמָה אוֹ חַיָּה כַּחֲצִי זַיִת. בֵּין בְּמַחְשֶׁבֶת מָקוֹם בֵּין בְּמַחְשֶׁבֶת זְמַן. הֲרֵי אֵלּוּ מִצְטָרְפִין שֶׁשֵּׁם אֲכִילָה אֶחָד הוּא. חִשֵּׁב עַל כְּזַיִת שֶׁיֹּאכְלוּהוּ שְׁנַיִם הֲרֵי אֵלּוּ מִצְטָרְפִין. חִשֵּׁב לֶאֱכל כְּזַיִת בְּיוֹתֵר מִכְּדֵי אֲכִילַת פְּרָס הֲרֵי זֶה מִצְטָרֵף. חִשֵּׁב בִּשְׁעַת זְבִיחָה לֶאֱכל כַּחֲצִי זַיִת וּבִשְׁעַת זְרִיקָה לֶאֱכל כַּחֲצִי זַיִת הֲרֵי אֵלּוּ מִצְטָרְפִין בֵּין בְּמַחְשֶׁבֶת הַמָּקוֹם בֵּין בְּמַחְשֶׁבֶת הַזְּמַן. וְכֵן אִם חִשֵּׁב עַל כְּזַיִת בִּשְׁעַת קַבָּלָה וְעַל כְּזַיִת בִּשְׁעַת הוֹלָכָה. שֶׁאַרְבַּע הָעֲבוֹדוֹת מִצְטָרְפוֹת וַהֲרֵי הֵן כָּעֲבוֹדָה אַחַת. חִשֵּׁב לְהַקְטִיר כַּחֲצִי זַיִת מִן הַקֹּמֶץ וְכַחֲצִי זַיִת מִן הַלְּבוֹנָה הֲרֵי אֵלּוּ מִצְטָרְפִין. שֶׁהַלְּבוֹנָה עִם הַקֹּמֶץ לַמִּנְחָה כְּאֵימוּרִין לְזֶבַח. לְפִיכָךְ אִם חִשֵּׁב לְהַקְטִיר כְּזַיִת מִן הַלְּבוֹנָה חוּץ לִזְמַנּוֹ הֲרֵי זֶה פִּגּוּל כְּמוֹ שֶׁנִּתְבָּאֵר. אֶחָד הַמְחַשֵּׁב לִזְרֹק דַּם הַזֶּבַח כֻּלּוֹ בַּחוּץ אוֹ לְמָחָר אוֹ שֶׁחִשֵּׁב לִזְרֹק מִקְצָת דָּמוֹ בַּחוּץ אוֹ לְמָחָר. כֵּיוָן שֶׁחִשֵּׁב עַל כְּדֵי הַזָּיָה מִן הַדָּם פָּסַל:"],"Mishneh Torah, Sacrifices Rendered Unfit 8":["חַטַאת הָעוֹף שֶׁנִּתְעָרְבָה בְּעוֹלַת הָעוֹף. אוֹ עוֹלַת הָעוֹף שֶׁנִּתְעָרְבָה בְּחַטַּאת הָעוֹף. אֲפִלּוּ אַחַת בְּרִבּוֹא כֻּלָּן יָמוּתוּ. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיוּ מְפֹרָשׁוֹת בִּשְׁעַת לְקִיחַת הַבְּעָלִים זוֹ חַטָּאת וְזוֹ עוֹלָה. אֲבָל אִם הֵבִיא עוֹפוֹת לְחוֹבָתוֹ מֵהֶן חַטָּאת וּמֵהֶן עוֹלָה וְלֹא פֵּרֵשׁ אֶלָּא כֻּלָּן סְתוּמוֹת וְנִתְעָרְבָה חַטָּאת אוֹ עוֹלָה בְּחוֹבָה זוֹ הַסְּתוּמָה יֵשׁ לָהֶן דִּינִים אֲחֵרִים:","וְכֵיצַד דִּינֵיהֶן. אִם נִתְעָרְבָה חַטָּאת בְּחוֹבָה זוֹ הַסְּתוּמָה אֵין כָּשֵׁר אֶלָּא מִנְיַן חַטָּאוֹת שֶׁבְּחוֹבָה בִּלְבַד. אֲבָל מִנְיַן הָעוֹלוֹת שֶׁבְּחוֹבָה עִם הַחַטָּאת שֶׁנִּתְעָרְבָה בָּהֶן פְּסוּלִין שֶׁהֲרֵי נִתְעָרְבָה חַטָּאת בְעוֹלוֹת:","לְפִיכָךְ אִם הָיְתָה הַחוֹבָה שְׁתַּיִם בְּחַטָּאת. חֲצִי הַחוֹבָה כָּשֵׁר וְחֶצְיָהּ פָּסוּל. וְיֵרָאֶה לִי שֶׁהוּא עוֹשֶׂה כֻּלָּן לְמַטָּן כְּמַעֲשֵׂה חַטָּאת:","וְכֵן אִם נִתְעָרְבָה עוֹלָה בְּחוֹבָה זוֹ הַסְּתוּמָה. אֵין כָּשֵׁר אֶלָּא מִנְיַן עוֹלוֹת שֶׁבְּחוֹבָה. אֲבָל מִנְיַן הַחַטָּאוֹת שֶׁבְּחוֹבָה עִם הָעוֹלָה שֶׁנִּתְעָרְבָה בָּהֶן פְּסוּלִין. שֶׁהֲרֵי נִתְעָרְבָה עוֹלָה בְּחַטָּאת. בֵּין שֶׁהָיְתָה הַחוֹבָה הַסְּתוּמָה מְרֻבָּה עַל הָעוֹלוֹת שֶׁנִּתְעָרֵב בָּהּ. בֵּין שֶׁהָיוּ הָעוֹלוֹת מְרֻבִּין עַל הַחוֹבָה הַסְּתוּמָה. בֵּין שֶׁהָיוּ שְׁתֵּיהֶן שָׁווֹת. אֵין כָּשֵׁר אֶלָּא מִנְיַן עוֹלוֹת שֶׁבְּחוֹבָה. לְפִיכָךְ אִם הָיְתָה הַחוֹבָה שְׁתַּיִם בָּעוֹלוֹת חֲצִי הַחוֹבָה כָּשֵׁר וְחֶצְיָהּ פָּסוּל. וְיֵרָאֶה לִי שֶׁהוּא עוֹשֶׂה כֻּלָּן לְמַעְלָה כְּמַעֲשֵׂה עוֹלָה:","חוֹבָה סְתוּמָה וְחוֹבָה אַחֶרֶת סְתוּמָה שֶׁנִּתְעָרְבוּ. בֵּין שֶׁהָיוּ שְׁתֵּיהֶן מִשֵּׁם אֶחָד. כְּגוֹן קִנֵּי זָבִים עִם קִנֵּי זָבִים. אוֹ מִשְּׁנֵי שֵׁמוֹת כְּגוֹן קִנֵּי זָבִים עִם קִנֵּי יוֹלְדוֹת. בֵּין שֶׁהָיוּ שְׁתֵּיהֶם לְאָדָם אֶחָד. בֵּין שֶׁהָיוּ לִשְׁנַיִם. אִם הָיוּ שְׁתֵּיהֶן שָׁווֹת מֶחֱצָה כָּשֵׁר וּמֶחֱצָה פָּסוּל. בֵּין שֶׁעָשָׂה הַכּל לְמַעְלָה אוֹ הַכּל לְמַטָּה אוֹ עָשָׂה חֶצְיָן לְמַעְלָה וְחֶצְיָן לְמַטָּה לְעוֹלָם מֶחֱצָה כָּשֵׁר וּמֶחֱצָה פָּסוּל. מִפְּנֵי שֶׁהַכּל חֶצְיָן עוֹלָה וְחֶצְיָן חַטָּאת. וְהַחַטָּאת לְמַטָּה וְהָעוֹלָה לְמַעְלָה. אִם עָשָׂה הַכּל לְמַעְלָה חֶצְיָן כְּשֵׁרוֹת וְהֵן עוֹלוֹת. וְאִם עָשָׂה כֻּלָּן לְמַטָּה חֶצְיָן כְּשֵׁרוֹת וְהֵן חַטָּאוֹת. עָשָׂה חֶצְיָן לְמַטָּה וְחֶצְיָן לְמַעְלָה חֲצִי הַחֵצִי שֶׁנַּעֲשָׂה לְמַעְלָה כָּשֵׁר מִפְּנֵי הַתַּעֲרֹבֶת וְהוּא עוֹלוֹת וַחֲצִי הַחֵצִי שֶׁל מַטָּה כָּשֵׁר וְהוּא חַטָּאוֹת:","הָיוּ שְׁתֵּי הַחוֹבוֹת הַסְּתוּמוֹת שֶׁנִּתְעָרְבוּ זוֹ גְּדוֹלָה מִזּוֹ. כְּגוֹן שֶׁהָיְתָה אַחַת אַרְבַּע עוֹפוֹת וְהַשְּׁנִיָּה שֵׁשׁ. אִם עָשָׂה הַכּל לְמַעְלָה אוֹ עָשָׂה הַכּל לְמַטָּה מֶחֱצָה פָּסוּל וּמֶחֱצָה כָּשֵׁר וּמִטַּעַם שֶׁבֵּאַרְנוּ. עָשָׂה חֶצְיָן לְמַטָּה וְחֶצְיָן לְמַעְלָה. אִם אַחַר שֶׁשָּׁאַל עָשָׂה כֵן הַמֻּעָט כָּשֵׁר. וְאִם מִדַּעְתּוֹ עָשָׂה הַמְרֻבֶּה כָּשֵׁר:","זֶה הַכְּלָל כָּל שֶׁעָשָׂה הַכֹּהֵן מִדַּעְתּוֹ חֶצְיָן לְמַעְלָה וְחֶצְיָן לְמַטָּה. וְאִי אֶפְשָׁר שֶׁלֹּא יִהְיֶה מִשֶּׁל אֶחָד לְמַעְלָה וּלְמַטָּה. הֲרֵי זֶה הַמְרֻבֶּה כָּשֵׁר הוֹאִיל וְדָבָר יָדוּעַ שֶׁמִּקְצָת קָרְבְּנוֹתָיו לְמַעְלָה וּמִקְצָתָם לְמַטָּה יִהְיוּ כָּל קָרְבְּנוֹתָיו כְּשֵׁרִים:","שְׁנַיִם שֶׁלָּקְחוּ קִנֵּיהֶן בְּעֵרוּב אוֹ שֶׁנָּתְנוּ דְּמֵי קִנֵּיהֶן לַכֹּהֵן לְאֵיזֶה שֶׁיִּרְצֶה הַכֹּהֵן יַקְרִיב חַטָּאת וּלְאֵיזֶה שֶׁיִּרְצֶה יַקְרִיב עוֹלָה. שֶׁאֵין הַקִּינִין מִתְפָּרְשִׁין אֶלָּא בִּלְקִיחַת הַבְּעָלִים אוֹ בַּעֲשִׂיַּת הַכֹּהֵן כְּמוֹ שֶׁבֵּאַרְנוּ:","הָיוּ לִפְנֵי הַכֹּהֵן חַטָּאוֹת וְעוֹלוֹת. עָשָׂה שְׁתֵּיהֶן לְמַעְלָה אוֹ שְׁתֵּיהֶן לְמַטָּה מֶחֱצָה כָּשֵׁר וּמֶחֱצָה פָּסוּל. עָשָׂה חֶצְיָן לְמַעְלָה וְחֶצְיָן לְמַטָּה וְלֹא יָדַע אִם הַחַטָּאוֹת הֵם שֶׁעָשָׂה לְמַטָּה אוֹ הָעוֹלוֹת. הֲרֵי הַכּל פָּסוּל. שֶׁאֲנִי אוֹמֵר הָעוֹלוֹת הֵם שֶׁעָשָׂה לְמַטָּה וְהַחַטָּאוֹת לְמַעְלָה:","הָיוּ לְפָנָיו שְׁלֹשָׁה צִבּוּרֵי עוֹפוֹת אֶחָד חַטָּאוֹת וְאֶחָד עוֹלוֹת וְהָאֶחָד סָתוּם חֶצְיוֹ עוֹלוֹת וְחֶצְיוֹ חַטָּאוֹת וְלֹא פֵּרֵשׁ. אִם עָשָׂה כֻּלָּן לְמַעְלָה אוֹ לְמַטָּה. מֶחֱצָה כָּשֵׁר וּמֶחֱצָה פָּסוּל:","עָשָׂה חֶצְיָן לְמַעְלָה וְחֶצְיָן לְמַטָּה. אֵין הַכָּשֵׁר אֶלָּא הַסָּתוּם בִּלְבַד שֶׁעָשָׂה חֶצְיוֹ לְמַעְלָה וְחֶצְיוֹ לְמַטָּה. וְהוּא מִתְחַלֵּק בֵּין הַבְּעָלִים וְעוֹלֶה לִשְׁנֵיהֶן. שֶׁהֲרֵי הַכֹּהֵן אֵינוֹ יוֹדֵעַ לְאֵי זֶה מֵהֶן פֵּרֵשׁ וּלְאֵי זֶה מֵהֶן הָיָה הַסָּתוּם. וּשְׁנֵי הַצִּבּוּרִין הַמְפֹרָשִׁין פְּסוּלִין שֶׁהֲרֵי לֹא יָדַע אֵי זֶה עָשָׂה לְמַעְלָה וְאֵי זֶה עָשָׂה לְמַטָּה וְשֶׁמָּא הָעוֹלָה נַעֲשֵׂית לְמַטָּה וְהַחַטָּאת לְמַעְלָה:"],"Mishneh Torah, Sacrificial Procedure 19":["אֵין הַמַּעֲלֶה בַּחוּץ חַיָּב עַד שֶׁיַּעֲלֶה לְרֹאשׁ הַמִּזְבֵּחַ שֶׁיַּעֲשֶׂה בַּחוּץ. אֲבָל אִם הֶעֱלָה עַל הַסֶּלַע אוֹ עַל הָאֶבֶן פָּטוּר. שֶׁאֵין קָרוּי קָרְבָּן אֶלָּא עַל הַמִּזְבֵּחַ וְאַף עַל פִּי שֶׁהוּא בַּחוּץ שֶׁנֶּאֱמַר (בראשית ח כ) \"וַיִּבֶן נֹחַ מִזְבֵּחַ\". וְאֵינוֹ חַיָּב עַד שֶׁיַּעֲלֶה לַשֵּׁם שֶׁנֶּאֱמַר (ויקרא יז ט) \"לַעֲשׂוֹת אֹתוֹ לַה'\" עַד שֶׁיִּתְכַּוֵּן לַשֵּׁם:","אֵינוֹ חַיָּב אֶלָּא עַל הַעֲלָאַת דָּבָר הָרָאוּי לָאִשִּׁים וְלַמִּזְבֵּחַ כְּגוֹן הָעוֹלָה שֶׁנֶּאֱמַר (ויקרא יז ח) \"אֲשֶׁר יַעֲלֶה עלָה אוֹ זָבַח\" מָה עוֹלָה שֶׁרְאוּיָה לָאִשִּׁים אַף כָּל שֶׁרָאוּי לָאִשִּׁים הוּא שֶׁחַיָּבִין עַל הַעֲלָאָתוֹ בַּחוּץ:","מִכָּאן אָמְרוּ הַזּוֹרֵק אֶת הַדָּם אוֹ הַמַּקְטִיר אֵיבְרֵי עוֹלָה אוֹ אֵימוּרִין אוֹ קֹמֶץ אוֹ לְבוֹנָה אוֹ קְטֹרֶת אוֹ מִנְחַת כֹּהֲנִים אוֹ מִנְחַת נְסָכִים אוֹ הַמְנַסֵּךְ שְׁלֹשָׁה לוֹגִין יַיִן אוֹ מַיִם בַּחוּץ חַיָּב שֶׁנֶּאֱמַר (ויקרא יז ט) \"לֹא יְבִיאֶנּוּ לַעֲשׂוֹת אֹתוֹ\" כָּל הַמִּתְקַבֵּל בִּפְנִים חַיָּבִין עָלָיו בַּחוּץ:","אֲבָל הַזּוֹרֵק שְׁיָרֵי הַדָּם בַּחוּץ אֲפִלּוּ שְׁיָרֵי דָּמִים הַפְּנִימִים פָּטוּר. שֶׁזְּרִיקַת שְׁיָרֵי הַדָּם שְׁיָרֵי מִצְוָה הֵם וְאֵינָן מְעַכְּבִין. וְכֵן הַמְנַסֵּךְ יַיִן אוֹ מַיִם פָּחוֹת מִשְּׁלֹשָׁה לוֹגִין בַּחוּץ פָּטוּר בֵּין בֶּחָג בֵּין בִּשְׁאָר יְמוֹת הַשָּׁנָה. הוֹאִיל וְחָסֵר הַשִּׁעוּר הֲרֵי אֵינָן רְאוּיִין לְהִתְקַבֵּל בִּפְנִים. וְכֵן הַמַּעֲלֶה מִבְּשַׂר חַטָּאת מִבְּשַׂר אָשָׁם מִבְּשַׂר שְׁלָמִים בֵּין שֶׁל יָחִיד בֵּין שֶׁל צִבּוּר מִשְּׁיָרֵי מְנָחוֹת מִשְּׁתֵי הַלֶּחֶם מִלֶּחֶם הַפָּנִים בַּחוּץ פָּטוּר. שֶׁכָּל אֵלּוּ רְאוּיִין לַאֲכִילָה לֹא לָאִשִּׁים:","הַמַּעֲלֶה אֶת הַבְּהֵמָה כֻּלָּהּ בַּחוּץ חַיָּב מִפְּנֵי הָאֵימוּרִין. וְאַף עַל פִּי שֶׁלֹּא הִפְרִישָׁן אֵין בְּשַׂר הַזֶּבַח חוֹצֵץ. וּכְאִלּוּ הִקְטִיר הָאֵימוּרִים בִּפְנֵי עַצְמָן. אֲבָל הַמַּעֲלֶה מִנְחָה שֶׁלֹּא נִקְמְצָה פָּטוּר. שֶׁאֵין הַקֹּמֶץ בָּרוּר וּמֻבְדָּל. קְמָצָהּ וְחָזַר קֻמְצָהּ לְתוֹכָהּ וְהִקְרִיב כֻּלָּהּ בַּחוּץ חַיָּב:","הַיּוֹצֵק וְהַבּוֹלֵל וְהַפּוֹתֵת וְהַמּוֹלֵחַ וְהַמֵּנִיף וְהַמַּגִּישׁ וְהַמְסַדֵּר אֶת הַשֻּׁלְחָן וְהַמֵּטִיב אֶת הַנֵּרוֹת וְהַקּוֹמֵץ וְהַמְקַבֵּל דָּמִים בַּחוּץ פָּטוּר. לְפִי שֶׁכָּל אֶחָד מֵאֵלּוּ אֵינוֹ גְּמַר עֲבוֹדָה וְנֶאֱמַר (ויקרא יז ח) \"אֲשֶׁר יַעֲלֶה עלָה אוֹ זָבַח\". מַה הַעֲלָאָה שֶׁהִיא גְּמַר עֲבוֹדָה אַף כָּל שֶׁהוּא גְּמַר עֲבוֹדָה חַיָּבִין עָלָיו:","פָּרָה אֲדֻמָּה שֶׁשְּׂרָפָהּ חוּץ מִמְּקוֹם שְׂרֵפָתָהּ. וְכֵן שָׂעִיר הַמִּשְׁתַּלֵּחַ שֶׁהִקְרִיבוֹ בַּחוּץ אַחַר שֶׁהִתְוַדָּה עָלָיו פָּטוּר. שֶׁנֶּאֱמַר (ויקרא יז ט) \"וְאֶל פֶּתַח אֹהֶל מוֹעֵד לֹא יְבִיאֶנּוּ\" כָּל שֶׁאֵינוֹ רָאוּי לָבוֹא אֶל פֶּתַח אֹהֶל מוֹעֵד אֵין חַיָּבִין עָלָיו. אֲבָל קָדָשִׁים פְּסוּלִין שֶׁהָיָה פִּסּוּלָן בַּקֹּדֶשׁ אִם הֶעֱלָה מֵהֶן בַּחוּץ חַיָּב. כֵּיצַד. כְּגוֹן הַלָּן וְהַיּוֹצֵא וְהַטָּמֵא וְשֶׁנִּפְסַל בְּמַחְשֶׁבֶת הָעוֹבֵד שֶׁכֻּלָּן נִשְׂרָפִין כְּמוֹ שֶׁיִּתְבָּאֵר בְּהִלְכוֹת פְּסוּלֵי הַמֻּקְדָּשִׁין. אִם עָבַר וְהֶעֱלָה מֵהֶם בַּחוּץ חַיָּב שֶׁנֶּאֱמַר (ויקרא יז ט) \"לַעֲשׂוֹת אֹתוֹ לַה'\" כָּל הַנַּעֲשֶׂה לַה' חַיָּבִין עָלָיו וְאֵלּוּ נַעֲשׂוּ לַשֵּׁם:","כָּל דָּבָר שֶׁחַיָּבִין עַל הַעֲלָאָתוֹ בַּחוּץ כֵּיוָן שֶׁהֶעֱלָה מִמֶּנּוּ כְּזַיִת בַּחוּץ חַיָּב. בֵּין שֶׁהֶעֱלָה בִּפְנִים תְּחִלָּה וְשִׁיֵּר מִמֶּנּוּ כְּזַיִת וְהֶעֱלָהוּ בַּחוּץ. בֵּין שֶׁהִנִּיחַ הַכּל בִּפְנִים וְלָקַח מִמֶּנּוּ כְּזַיִת וְהֶעֱלָהוּ בַּחוּץ. אֲבָל אִם חִסֵּר אוֹתוֹ דָּבָר הַקָּרֵב כָּל שֶׁהוּא בִּפְנִים וְהֶעֱלָה שְׁאֵרִיתוֹ בַּחוּץ פָּטוּר:","כֵּיצַד. הַקֹּמֶץ אוֹ הַלְּבוֹנָה וְהָאֵימוּרִין וְהָעוֹלָה וּמִנְחָה הַנִּשְׂרֶפֶת וְהַנְּסָכִין שֶׁחָסְרוּ מִקְצָתָם בִּפְנִים וְהִקְרִיב שְׁאֵרִיתָן בַּחוּץ פָּטוּר. שֶׁהֲרֵי נֶאֱמַר (ויקרא יז ט) \"לַעֲשׂוֹת אוֹתוֹ\" עַל הַשָּׁלֵם הוּא חַיָּב וְאֵינוֹ חַיָּב עַל הֶחָסֵר. הוֹצִיאוֹ שָׁלֵם וְחָסַר בַּחוּץ וְהֶעֱלָהוּ הֲרֵי זֶה סָפֵק לְפִיכָךְ אֵינוֹ לוֹקֶה:","הֶעֱלָה אֵיבָר שֶׁאֵין בּוֹ כְּזַיִת בָּשָׂר וְהָיָה הָעֶצֶם מַשְׁלִימוֹ לִכְזַיִת חַיָּב. מִפְּנֵי שֶׁהוּא מְחֻבָּר. הָיָה מֶלַח מַשְׁלִימוֹ לִכְזַיִת הֲרֵי זֶה סָפֵק לְפִיכָךְ אֵינוֹ לוֹקֶה. וְעוֹלָה וְאֵימוּרֶיהָ מִצְטָרְפִין לִכְזַיִת:","הֶעֱלָה וְחָזַר וְהֶעֱלָה חַיָּב עַל כָּל אֵיבָר וְאֵיבָר. זָרַק הַדָּם וְהֶעֱלָה הָאֵיבָרִים חַיָּב שְׁתַּיִם. שֶׁהֲרֵי חָלַק הַכָּתוּב בֵּין מַעֲלֶה לְעוֹשֶׂה. שֶׁהֲרֵי נֶאֱמַר (ויקרא יז ח) \"אֲשֶׁר יַעֲלֶה עלָה\" וְנֶאֱמַר (ויקרא יז ט) \"לַעֲשׂוֹת אוֹתוֹ\". הֶעֱלָה אֵיבָר חָסֵר פָּטוּר שֶׁנֶּאֱמַר לַעֲשׂוֹת אֹתוֹ עַל הַשָּׁלֵם הוּא חַיָּב:","שְׁנַיִם שֶׁשָּׁחֲטוּ פְּטוּרִים. שְׁנַיִם שֶׁאָחֲזוּ בְּאֵיבָר וְהֶעֱלוּהוּ בַּחוּץ חַיָּבִין. שֶׁנֶּאֱמַר (ויקרא יז ח) \"אִישׁ אִישׁ\" (ויקרא יז ח) \"אֲשֶׁר יַעֲלֶה עלָה\" אֲפִלּוּ אִישׁ וְאִישׁ שֶׁהֶעֱלוּ חַיָּבִין:","הַזּוֹרֵק מִקְצָת מַתָּנוֹת בַּחוּץ חַיָּב. הַמְקַבֵּל דַּם חַטָּאת בְּכוֹס אֶחָד נָתַן מִמֶּנּוּ בַּחוּץ וְחָזַר וְנָתַן בִּפְנִים חַיָּב עַל הֲנָיָתָן בַּחוּץ. שֶׁהֲרֵי כֻּלּוֹ רָאוּי לִקָּרֵב בִּפְנִים. וְאִם נָתַן מִמֶּנּוּ בִּפְנִים וְחָזַר וְנָתַן בַּחוּץ פָּטוּר מִפְּנֵי שֶׁהֵן שְׁיָרִים. אֲבָל אִם קִבֵּל בִּשְׁנֵי כּוֹסוֹת. בֵּין שֶׁנָּתַן שְׁנֵיהֶן בַּחוּץ. אוֹ אֶחָד בַּחוּץ וְאֶחָד בִּפְנִים. אוֹ אֶחָד בִּפְנִים וְאֶחָד בַּחוּץ. הֲרֵי זֶה חַיָּב:","הַקֹּמֶץ וְהַלְּבוֹנָה שֶׁל מִנְחָה שֶׁהִקְרִיב אֶחָד מֵהֶן בַּחוּץ אוֹ הִקְרִיב הָאֶחָד בִּפְנִים וְהַשֵּׁנִי בַּחוּץ חַיָּב. וְכֵן שְׁנֵי בְּזִיכֵי לְבוֹנָה שֶׁל לֶחֶם הַפָּנִים שֶׁהִקְרִיב אֶחָד מֵהֶן בַּחוּץ אוֹ אֶחָד בִּפְנִים וְהַשֵּׁנִי בַּחוּץ חַיָּב:","מִי שֶׁשָּׁחַט קָדָשִׁים בַּזְּמַן הַזֶּה וְהֶעֱלָם חוּץ לַעֲזָרָה חַיָּב. מִפְּנֵי שֶׁהוּא רָאוּי לִקָּרֵב בִּפְנִים. שֶׁהֲרֵי מֻתָּר לְהַקְרִיב אַף עַל פִּי שֶׁאֵין בַּיִת מִפְּנֵי שֶׁקְּדֻשָּׁה רִאשׁוֹנָה קָדְשָׁה לִשְׁעָתָהּ וְקָדְשָׁה לֶעָתִיד לָבוֹא:","הַשּׁוֹחֵט קָדְשֵׁי נָכְרִים בַּחוּץ חַיָּב. וְכֵן הַמַּעֲלֶה אוֹתָן בַּחוּץ. וְהַנָּכְרִים מֻתָּרִין לְהַקְרִיב עוֹלוֹת לַשֵּׁם בְּכָל מָקוֹם. וְהוּא שֶׁיַּקְרִיבוּ בְּבָמָה שֶׁיִּבְנוּ. וְאָסוּר לְסַיְּעָן וְלַעֲשׂוֹת שְׁלִיחוּתָן שֶׁהֲרֵי נֶאֱסַר עָלֵינוּ לְהַקְרִיב בַּחוּץ. וּמֻתָּר לְהוֹרוֹת לָהֶם וּלְלַמְּדָם הֵיאַךְ יַקְרִיבוּ לְשֵׁם הָאֵל בָּרוּךְ הוּא:"],"Mishneh Torah, Sales 12":["אָסוּר לַמּוֹכֵר אוֹ לַקּוֹנֶה לְהוֹנוֹת אֶת חֲבֵרוֹ שֶׁנֶּאֱמַר (ויקרא כה יד) \"וְכִי תִמְכְּרוּ מִמְכָּר לַעֲמִיתֶךָ אוֹ קָנֹה מִיַּד עֲמִיתֶךָ אַל תּוֹנוּ\". וְאַף עַל פִּי שֶׁהוּא עוֹבֵר בְּלֹא תַּעֲשֶׂה אֵינוֹ לוֹקֶה מִפְּנֵי שֶׁנִּתָּן לְהִשָּׁבוֹן. וּבֵין שֶׁהוֹנָה בְּמֵזִיד בֵּין שֶׁלֹּא יָדַע שֶׁיֵּשׁ בְּמֶכֶר זֶה הוֹנָיָה חַיָּב לְשַׁלֵּם:","וְכַמָּה תְּהֵא הוֹנָיָה וְיִהְיֶה חַיָּב לְהָשִׁיב. שְׁתוּת בְּשָׁוֶה. כֵּיצַד. הֲרֵי שֶׁמָּכַר שְׁוֵה שֵׁשׁ בְּחָמֵשׁ. אוֹ שְׁוֵה שֶׁבַע בְּשֵׁשׁ. אוֹ שְׁוֵה חָמֵשׁ בְּשֵׁשׁ. אוֹ שְׁוֵה שֵׁשׁ בְּשֶׁבַע. הֲרֵי זֶה הוֹנָיָה וְנִקְנֶה הַמִּקָּח וְחַיָּב הַמְאַנֶּה לְשַׁלֵּם אֶת הַהוֹנָיָה וּלְהַחֲזִירָהּ כֻּלָּהּ לַמִּתְאַנֶּה:","הָיְתָה הַהוֹנָיָה פָּחוֹת מִזֶּה בְּכָל שֶׁהוּא. כְּגוֹן שֶׁמָּכַר שְׁוֵה שִׁשִּׁים דִּינָר בַּחֲמִשִּׁים וּפְרוּטָה. אֵינוֹ חַיָּב לְהַחְזִיר כְּלוּם. שֶׁכָּל פָּחוֹת מִשְּׁתוּת דֶּרֶךְ הַכּל לִמְחל בּוֹ:","הָיְתָה הַהוֹנָיָה יְתֵרָה עַל הַשְּׁתוּת בְּכָל שֶׁהוּא. כְּגוֹן שֶׁמָּכַר שְׁוֵה שִׁשִּׁים בַּחֲמִשִּׁים פָּחוֹת פְּרוּטָה. בָּטֵל מִקָּח. וְהַמִּתְאַנֶּה יָכוֹל לְהַחְזִיר הַחֵפֶץ וְלֹא יִקְנֶה כְּלָל. אֲבָל הַמְאַנֶּה אוֹתוֹ אֵינוֹ יָכוֹל לַחְזֹר אִם רָצָה זֶה וְקִבֵּל. וְאַף עַל פִּי שֶׁבָּטַל הַמִּקָּח. אֵין הַמְאַנֶּה חַיָּב לְהַחְזִיר עַד שֶׁתִּהְיֶה הַהוֹנָיָה יֶתֶר עַל פְּרוּטָה. הָיְתָה פְּרוּטָה בְּשָׁוֶה אֵינוֹ מַחְזִיר שֶׁאֵין הוֹנָיָה לִפְרוּטוֹת:","עַד מָתַי יִהְיֶה לוֹ לַחְזֹר וְלִתְבֹּעַ הַהוֹנָיָה אוֹ לְבַטֵּל הַמִּקָּח. עַד כְּדֵי שֶׁיַּרְאֶה לְתַגָּר אוֹ לִקְרוֹבוֹ. וְאִם שָׁהָה יוֹתֵר מִזֶּה אֲפִלּוּ לָקַח שְׁוֵה מֵאָה בְּמָאתַיִם אֵינוֹ חוֹזֵר:","בַּמֶּה דְּבָרִים אֲמוּרִים בְּלוֹקֵחַ שֶׁהֲרֵי הַמִּקָּח בְּיָדוֹ וּמַרְאֵהוּ. אֲבָל הַמּוֹכֵר חוֹזֵר בְּהוֹנָיָה לְעוֹלָם. וְאֵין צָרִיךְ לוֹמַר בְּבִטּוּל מִקָּח שֶׁאֵינוֹ יוֹדֵעַ דְּמֵי זֶה שֶׁמָּכַר עַד שֶׁיִּרְאֶה כְּמוֹתוֹ שֶׁנִּמְכַּר בַּשּׁוּק. לְפִיכָךְ אִם הָיָה הַמִּקָּח דָּבָר שֶׁאֵין בְּמִינוֹ שִׁנּוּי וְהוּא כֻּלּוֹ שָׁוֶה כְּגוֹן פִּלְפְּלִין וְכַיּוֹצֵא בָּהֶן הֲרֵי זֶה אֵינוֹ חוֹזֵר אֶלָּא עַד כְּדֵי שֶׁיִּשְׁאַל עַל שַׁעַר שֶׁבַּשּׁוּק בִּלְבַד:","וְכֵן אִם נוֹדַע שֶׁבָּא לְיָדוֹ כְּמִמְכָּרוֹ וְיָדַע שֶׁטָּעָה וְלֹא תָּבַע אֵינוֹ יוּכַל לַחְזֹר וְלִתְבֹּעַ שֶׁהֲרֵי מָחַל:","כְּשֵׁם שֶׁהוֹנָיָה לְהֶדְיוֹט כָּךְ הוֹנָיָה לְתַגָּר אַף עַל פִּי שֶׁהוּא בָּקִי. וּכְשֵׁם שֶׁהוֹנָיָה בְּפֵרוֹת וּבִבְהֵמָה כָּךְ יֵשׁ דִּין הוֹנָיָה בְּמַטְבְּעוֹת:","כֵּיצַד. הֲרֵי שֶׁהָיָה דִּינָר שֶׁל זָהָב בְּעֶשְׂרִים וְאַרְבָּעָה דִּינָר שֶׁל כֶּסֶף וְצֵרְפָה בְּעֶשְׂרִים דִּינָר אוֹ בְּעֶשְׂרִים וּשְׁמוֹנָה הֲרֵי זֶה מַחְזִיר אֶת הַהוֹנָיָה. הָיָה יָתֵר עַל זֶה בָּטֵל הַצֵּרוּף. פָּחוֹת מִכָּאן מְחִילָה:","וְכֵן אִם הָיָה הַסֶּלַע חֲסֵרָה שְׁתוּת וְהָיוּ מוֹצִיאִין הַסְּלָעִים בְּמִנְיָן וְלֹא בְּמִשְׁקָל מַחְזִיר הַהוֹנָיָה:","עַד מָתַי חַיָּב לְהַחְזִיר הַדִּינָר אוֹ הַסֶּלַע. בַּכְּרַכִּים עַד כְּדֵי שֶׁיַּרְאֶה לַשֻּׁלְחָנִי. בִּכְפָרִים שֶׁאֵין הַשֻּׁלְחָנִי מָצוּי שָׁם יֵשׁ לוֹ לְהַחְזִיר עַד עַרְבֵי שַׁבָּתוֹת. שֶׁאֵין מַכִּיר הַסֶּלַע וְחֶסְרוֹנָהּ וְדָמֶיהָ אֶלָּא הַשֻּׁלְחָנִי. וְהוּא הַדִּין לְמוֹכֵר סְפָרִים אֲבָנִים טוֹבוֹת וּמַרְגָּלִיּוֹת שֶׁיֵּשׁ לַלּוֹקֵחַ לַחְזֹר עַד שֶׁיַּרְאֶה אוֹתָם לְתַגָּרִים הַבְּקִיאִים בָּהֶן בְּכָל מָקוֹם שֶׁהֵן. שֶׁאֵין הַכּל בְּקִיאִים בִּדְבָרִים אֵלּוּ. לְפִיכָךְ אִם לֹא הָיָה מַכִּיר בְּאוֹתָהּ מְדִינָה וְהוֹלִיךְ הַמִּקָּח לְמָקוֹם אַחֵר. אוֹ שֶׁבָּא הַבָּקִי לְאַחַר זְמַן מְרֻבֶּה וְהוֹדִיעוֹ שֶׁטָּעָה. הֲרֵי זֶה חוֹזֵר:","הַנּוֹתֵן סֶלַע חֲסֵרָה לַחֲבֵרוֹ אִם הָיָה מַכִּירָהּ אֲפִלּוּ לְאַחַר שְׁנֵים עָשָׂר חֹדֶשׁ הֲרֵי זֶה מַחְזִירָהּ. וְאִם הָיָה אֶפְשָׁר לְהוֹצִיאָהּ עַל יְדֵי הַדְּחָק אֵינוֹ יָכוֹל לְהַחְזִירָהּ לְאַחַר זְמַן אֶלָּא אִם כֵּן קִבְּלָהּ מִמֶּנּוּ בְּמִדַּת חֲסִידוּת:","הַמּוֹכֵר לַחֲבֵרוֹ שְׁוֵה אַרְבַּע בְּחָמֵשׁ שֶׁהֲרֵי הַמִּקָּח בָּטֵל כְּמוֹ שֶׁבֵּאַרְנוּ וְלֹא הִסְפִּיק לְהַרְאוֹת לְתַגָּר אוֹ לִקְרוֹבוֹ עַד שֶׁהוּקַר וְעָמַד בְּשֶׁבַע. לוֹקֵחַ יָכוֹל לַחְזֹר בּוֹ וְלֹא הַמּוֹכֵר. שֶׁהֲרֵי הַלּוֹקֵחַ אוֹמֵר לַמּוֹכֵר אִלּוּ לֹא הוֹנֵיתַנִי לֹא הָיִיתָ יָכוֹל לַחְזֹר וְעַתָּה שֶׁהוֹנֵיתַנִי תַּחְזֹר הֵיאַךְ יִהְיֶה הַחוֹטֵא נִשְׂכָּר:","וְכֵן מוֹכֵר שֶׁמָּכַר שְׁוֵה חָמֵשׁ בְּאַרְבַּע וְזָל וְעָמַד בְּשָׁלֹשׁ. מוֹכֵר יָכוֹל לַחְזֹר בּוֹ וְלֹא לוֹקֵחַ. שֶׁהֲרֵי אוֹמֵר לוֹ הַמּוֹכֵר לַלּוֹקֵחַ לֹא מִפְּנֵי שֶׁהוֹנֵיתַנִי תַּחְזֹר בְּךָ:","הַמּוֹכֵר שְׁוֵה חָמֵשׁ בְּשֵׁשׁ וְלֹא הִסְפִּיק לְהַרְאוֹתוֹ עַד שֶׁהוּקַר וְעָמַד בִּשְׁמוֹנֶה. הֲרֵי הַמּוֹכֵר חַיָּב לְהַחְזִיר הָאַחַת שֶׁל הוֹנָיָה שֶׁהֲרֵי נִקְנָה הַמִּקָּח וְחַיָּב לְהַחְזִיר וּכְשֶׁהוֹקִיר בִּרְשׁוּת לוֹקֵחַ הוּקַר. וְכֵן אִם מָכַר שָׁוֶה שֵׁשׁ בְּחָמֵשׁ וְהוּזְלוּ וְעָמְדוּ עַל שָׁלֹשׁ. הֲרֵי הַלּוֹקֵחַ חַיָּב לְהַחְזִיר סֶלַע אַחַת שֶׁל הוֹנָיָה. שֶׁהֲרֵי נִקְנָה הַמִּקָּח וּבִרְשׁוּת הַלּוֹקֵחַ הוּזַל:"],"Mishneh Torah, Sales 23":["מַקְנֶה אָדָם הַגּוּף לְפֵרוֹתָיו בֵּין בְּמֶכֶר בֵּין בְּמַתָּנָה בֵּין בְּמַתְּנַת שְׁכִיב מֵרַע. וְאֵין זֶה מַקְנֶה דָּבָר שֶׁלֹּא בָּא לְעוֹלָם שֶׁהֲרֵי הַגּוּף מָצוּי וּמַקְנֶה לְפֵרוֹת. הָא לְמָה זֶה דּוֹמֶה לְשׂוֹכֵר בַּיִת אוֹ שָׂדֶה לַחֲבֵרוֹ שֶׁלֹּא הִקְנָה לוֹ הַגּוּף אֶלָּא הֲנָאַת הַגּוּף:","כֵּיצַד. כְּגוֹן שֶׁמָּכַר אוֹ שֶׁנָּתַן שָׂדֶה לְפֵרוֹתֶיהָ בֵּין לִזְמַן קָצוּב בֵּין כָּל יְמֵי חַיָּיו שֶׁל מוֹכֵר אוֹ שֶׁל לוֹקֵחַ. וְהוּא הַדִּין לְמוֹכֵר וּלְנוֹתֵן אִילָן לְפֵרוֹתָיו. אוֹ רָחֵל לְגִזָּתָהּ. אוֹ בְּהֵמָה וְשִׁפְחָה לְוַלְדוֹתֵיהֶם. אוֹ עֶבֶד לְמַעֲשֵׂה יָדָיו. בַּכּל מִמְכָּרוֹ אוֹ מַתְּנוֹתָיו קַיָּמִין:","מָכַר עַבְדּוֹ לִקְנָס שֶׁאִם יֵגֲּח וְיָמוּת יִהְיֶה קְנָס שֶׁל לוֹקֵחַ. הֲרֵי זֶה סָפֵק לְפִיכָךְ לֹא קָנָה. וְאִם תָּפַשׂ הַקְּנָס אֵין מוֹצִיאִין מִיָּדוֹ:","מָכַר אִילָן לָזֶה וּפֵרוֹתָיו לְאַחֵר לֹא שִׁיֵּר מְקוֹם הַפֵּרוֹת וְאֵין לָאַחֵר כְּלוּם. אֲבָל אִם מָכַר אִילָן וְשִׁיֵּר פֵּרוֹתָיו לְעַצְמוֹ הֲרֵי שִׁיֵּר מְקוֹם הַפֵּרוֹת, אַף עַל פִּי שֶׁלֹּא פֵּרֵשׁ לְגַבֵּי עַצְמוֹ בְּעַיִן יָפָה מְשַׁיֵּר:","הַמּוֹכֵר גּוּף הַקַּרְקַע לִזְמַן קָצוּב הֲרֵי זֶה מְכִירָה. וּמִשְׁתַּמֵּשׁ הַלּוֹקֵחַ בַּגּוּף כְּחֶפְצוֹ וְאוֹכֵל הַפֵּרוֹת כָּל זְמַן הַמְּכִירָה וּבַסּוֹף תַּחְזֹר לִבְעָלֶיהָ:","וּמַה הֶפְרֵשׁ יֵשׁ בֵּין הַמּוֹכֵר קַרְקַע לִזְמַן קָצוּב וּבֵין הַמַּקְנֶה אוֹתָהּ לְפֵרוֹתֶיהָ. שֶׁהַקּוֹנֶה לְפֵרוֹת אֵינוֹ יָכוֹל לְשַׁנּוֹת צוּרַת הַקַּרְקַע וְלֹא יִבְנֶה וְלֹא יַהֲרֹס. אֲבָל הַקּוֹנֶה לִזְמַן קָצוּב הוּא בּוֹנֶה וְהוֹרֵס וְעוֹשֶׂה בְּכָל זְמַנּוֹ הַקָּצוּב כְּמוֹ שֶׁעוֹשֶׂה הַקּוֹנֶה קִנְיַן עוֹלָם לְעוֹלָם:","וּמַה הֶפְרֵשׁ יֵשׁ בֵּין הַמּוֹכֵר שָׂדֶה זוֹ לְפֵרוֹתֶיהָ וּבֵין הַמּוֹכֵר פֵּרוֹת שָׂדֶה זוֹ לַחֲבֵרוֹ. שֶׁהַמּוֹכֵר פֵּרוֹת הַשָּׂדֶה אֵין לַלּוֹקֵחַ לְהִשְׁתַּמֵּשׁ בְּשָׂדֶה זוֹ כְּלָל אֲפִלּוּ לְהִכָּנֵס אֶלָּא בִּשְׁעַת הוֹצָאַת הַפֵּרוֹת וְיֵשׁ לְבַעַל הַשָּׂדֶה לְהִשְׁתַּמֵּשׁ בָּהּ כְּחֶפְצוֹ. אֲבָל הַמּוֹכֵר שָׂדֶה לְפֵרוֹתֶיהָ אֵין בַּעַל הַשָּׂדֶה יָכוֹל לְהִכָּנֵס בָּהּ אֶלָּא מִדַּעַת הַלּוֹקֵחַ וְיֵשׁ לַלּוֹקֵחַ לְהִשְׁתַּמֵּשׁ בָּהּ כְּחֶפְצוֹ:","וּמַה הֶפְרֵשׁ יֵשׁ בֵּין הַקּוֹנֶה שָׂדֶה זוֹ לְפֵרוֹתֶיהָ וּבֵין הַשּׂוֹכֵר שָׂדֶה מֵחֲבֵרוֹ. שֶׁהַקּוֹנֶה שָׂדֶה לְפֵרוֹתֶיהָ יֵשׁ לוֹ לְנָטְעָהּ אוֹ לְזָרְעָהּ כָּל זְמַן שֶׁיִּרְצֶה אוֹ לְהוֹבִירָהּ. וְהַשּׂוֹכֵר אֵינוֹ כֵן כְּמוֹ שֶׁיִּתְבָּאֵר בְּעִנְיַן שְׂכִירוּת. וְאֵין הַשּׂוֹכֵר רַשַּׁאי לְהַשְׂכִּיר אֲבָל הַקּוֹנֶה מַקְנֶה לַאֲחֵרִים כָּל מַה שֶּׁקָּנָה:","הַמּוֹכֵר פֵּרוֹת שׁוֹבָךְ וּפֵרוֹת כַּוֶּרֶת לַחֲבֵרוֹ קָנָה וְאֵין זֶה מוֹכֵר דָּבָר שֶׁלֹּא בָּא לָעוֹלָם. לְפִי שֶׁאֵינוֹ מוֹכֵר יוֹנִים שֶׁיִּוָּלְדוּ אוֹ דְּבַשׁ שֶׁיָּבוֹא לַכַּוֶּרֶת. אֶלָּא הוּא מוֹכֵר שׁוֹבָךְ לְפֵרוֹתָיו אוֹ כַּוֶּרֶת לְדִבְשָׁהּ. שֶׁהֲרֵי הוּא כְּשׂוֹכֵר אַמַּת הַמַּיִם לַחֲבֵרוֹ שֶׁהוּא נֶהֱנֶה בְּכָל מַה שֶּׁיָּצוּד בָּהּ. כָּךְ זֶה הִקְנָה שׁוֹבָךְ זֶה לְפֵרוֹתָיו כְּמוֹ שֶׁמּוֹכֵר אִילָן לְפֵרוֹתָיו. וְדִין כֻּלָּם כְּדִין הַשּׂוֹכֵר בַּיִת מֵחֲבֵרוֹ כְּמוֹ שֶׁאָמַרְנוּ. שֶׁהוּא נֶהֱנֶה בְּכָל הֲנָיוֹת שֶׁיֵּשׁ בּוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הַבֵּיצִים וְהָאֶפְרוֹחִין עַצְמָן שֶׁיֵּשׁ בַּשּׁוֹבָךְ לֹא קָנָה אוֹתָם בַּעַל שׁוֹבָךְ כָּל זְמַן שֶׁלֹּא פָּרְחוּ. וְדָבָר זֶה גְּזֵרַת חֲכָמִים הִיא וּמִשּׁוּם (דברים כב ו) \"לֹא תִקַּח הָאֵם עַל הַבָּנִים\" נָגְעוּ בָּהּ. לְפִיכָךְ הָרוֹצֶה לְהַקְנוֹת אֶפְרוֹחִים וּבֵיצִים אֵלּוּ לַחֲבֵרוֹ. מְטַפֵּחַ עַל הַשּׁוֹבָךְ שֶׁיִּפְרְחוּ הָאִמָּהוֹת וְיִגְבְּהוּ מֵעַל הָאָרֶץ וְאַחַר כָּךְ יַקְנֶה אוֹתָן לַחֲבֵרוֹ בְּקִנְיָן אוֹ עַל גַּבֵּי קַרְקַע אוֹ בִּשְׁאָר דְּבָרִים שֶׁהַמִּטַּלְטְלִין נִקְנִין בָּהֶן:","הַלּוֹקֵחַ פֵּרוֹת שׁוֹבָךְ מֵחֲבֵרוֹ אֵינוֹ יָכוֹל לִטּל כָּל הַגּוֹזָלוֹת שֶׁיִּוָּלְדוּ בּוֹ מֵעַתָּה מִפְּנֵי שֶׁהָאִמָּהוֹת בּוֹרְחוֹת נִמְצָא שֶׁהֶחֱרִיב כָּל הַשּׁוֹבָךְ אֶלָּא מַנִּיחַ מֵהֶן כְּדֵי לְיַשֵּׁב הַשּׁוֹבָךְ:","וְכַמָּה מַנִּיחַ. אִם הָיוּ בּוֹ אִמָּהוֹת וּבָנוֹת בְּעֵת מְכִירַת הַפֵּרוֹת. מַנִּיחַ בְּרֵכָה רִאשׁוֹנָה שֶׁיּוֹלִידוּ הָאִמָּהוֹת כְּדֵי שֶׁיִּצְטַוְּתוּ הָאִמָּהוֹת עִם הַבְּרֵכָה הָרִאשׁוֹנָה וְעִם הַבָּנוֹת שֶׁעִמָּהֶם. וּמַנִּיחַ מִמַּה שֶּׁיּוֹלִידוּ הַבָּנוֹת שְׁתֵּי בְּרֵכוֹת כְּדֵי שֶׁיִּצְטַוְּתוּ הַבָּנוֹת עִם שְׁתֵּי הַבְּרֵכוֹת שֶׁהוֹלִידוּ. וְכָל הַנּוֹלָד מֵאַחַר שְׁתֵּי בְּרֵכוֹת שֶׁל בָּנוֹת וְהַבְּרֵכָה הָרִאשׁוֹנָה שֶׁל אִמָּהוֹת הֲרֵי אֵלּוּ שֶׁלּוֹ:","הַלּוֹקֵחַ פֵּרוֹת כַּוֶּרֶת מֵחֲבֵרוֹ נוֹטֵל שְׁלֹשָׁה נְחִילִים זֶה אַחַר זֶה מִכָּאן וְאֵילָךְ נוֹטֵל נְחִיל וּמֵנִיחַ נְחִיל כְּדֵי לְיַשֵּׁב אֶת הַכַּוֶּרֶת:","הַלּוֹקֵחַ חַלּוֹת דְּבַשׁ מֵחֲבֵרוֹ מַנִּיחַ בַּכַּוֶּרֶת שְׁתֵּי חַלּוֹת כְּדֵי שֶׁלֹּא יִפְרְחוּ הַדְּבוֹרִים וְיֵלְכוּ לָהֶן:","הַלּוֹקֵחַ זֵיתִים מֵחֲבֵרוֹ לָקֹץ. מַנִּיחַ הָאִילָן סָמוּךְ לָאָרֶץ שְׁתֵּי גְּרוֹפִיּוֹת וְקוֹצֵץ. לָקַח בְּתוּלַת שִׁקְמָה מַגְבִּיהַּ שְׁלֹשָׁה טְפָחִים וְקוֹצֵץ. סַדָּן שֶׁל שִׁקְמָה שְׁנֵי טְפָחִים. וּבִשְׁאָר אִילָנוֹת טֶפַח וְקוֹצֵץ. בְּקָנִים וּבִגְפָנִים מִן הַפְּקָק וּלְמַעְלָה. בִּדְקָלִים וַאֲרָזִים חוֹפֵר וּמְשָׁרֵשׁ לְפִי שֶׁאֵין גִּזְעוֹ מַחְלִיף:"],"Mishneh Torah, Sales 7":["מִי שֶׁנָּתַן הַדָּמִים וְלֹא מָשַׁךְ הַפֵּרוֹת. אַף עַל פִּי שֶׁלֹּא נִקְנוּ הַמִּטַּלְטְלִין כְּמוֹ שֶׁבֵּאַרְנוּ. כָּל הַחוֹזֵר בּוֹ בֵּין לוֹקֵחַ בֵּין מוֹכֵר לֹא עָשָׂה מַעֲשֵׂה יִשְׂרָאֵל וְחַיָּב לְקַבֵּל מִי שֶׁפָּרַע. וַאֲפִלּוּ נָתַן הָעֵרָבוֹן כָּל הַחוֹזֵר מְקַבֵּל מִי שֶׁפָּרַע:","וְכֵיצַד מְקַבֵּל מִי שֶׁפָּרַע. אוֹרְרִין אוֹתוֹ בְּבֵית דִּין וְאוֹמְרִין מִי שֶׁפָּרַע מֵאַנְשֵׁי דּוֹר הַמַּבּוּל וּמֵאַנְשֵׁי דּוֹר הַפַּלָּגָה וּמֵאַנְשֵׁי סְדוֹם וַעֲמוֹרָה וּמִמִּצְרַיִם שֶׁטָּבְעוּ בַּיָּם הוּא יִפָּרַע מִמִּי שֶׁאֵינוֹ עוֹמֵד בְּדִבּוּרוֹ. וְאַחַר כָּךְ יַחְזְרוּ הַדָּמִים:","הַנּוֹתֵן דְּמֵי הַמִּטַּלְטְלִין אוֹ מִקְצָת הַדָּמִים וְחָזַר בּוֹ הַלּוֹקֵחַ וְאָמַר לוֹ הַמּוֹכֵר בֹּא וְטֹל מְעוֹתֶיךָ. הֲרֵי הַמָּעוֹת אֶצְלוֹ כְּמוֹ פִּקָּדוֹן. וְאִם נִגְנְבוּ אוֹ אָבְדוּ אֵינוֹ חַיָּב בְּאַחֲרָיוּתָן. אֲבָל אִם חָזַר בּוֹ הַמּוֹכֵר הֲרֵי הַמָּעוֹת בִּרְשׁוּתוֹ וְחַיָּב בְּאַחֲרָיוּתָן. וְאַף עַל פִּי שֶׁחָזַר בּוֹ וְאָמַר לַלּוֹקֵחַ בּוֹא וְטֹל אֶת שֶׁלְּךָ. עַד שֶׁיְּקַבֵּל עָלָיו מִי שֶׁפָּרַע וְיֹאמַר לוֹ אַחַר כָּךְ בּוֹא וְטֹל אֶת שֶׁלְּךָ:","מִי שֶׁהָיָה לוֹ חוֹב אֵצֶל חֲבֵרוֹ וְאָמַר לוֹ מְכֹר לִי חָבִית שֶׁל יַיִן בַּחוֹב שֶׁיֵּשׁ לִי אֶצְלְךָ וְרָצָה הַמּוֹכֵר. הֲרֵי זֶה כְּמִי שֶׁנָּתַן הַדָּמִים עַתָּה. וְכָל הַחוֹזֵר בּוֹ מְקַבֵּל מִי שֶׁפָּרַע. לְפִיכָךְ אִם מָכַר לוֹ קַרְקַע בְּחוֹבוֹ אֵין אֶחָד מֵהֶן יָכוֹל לַחְזֹר בּוֹ וְאַף עַל פִּי שֶׁאֵין מְעוֹת הַמַּלְוֶה מְצוּיוֹת בִּשְׁעַת הַמֶּכֶר:","הַלּוֹקֵחַ מֵחֲבֵרוֹ קַרְקַע אוֹ עֲבָדִים אוֹ שְׁאָר מִטַּלְטְלִין וּפָסְקוּ הַדָּמִים וְהִנִּיחַ מַשְׁכּוֹן עַל הַדָּמִים לֹא קָנָה. וְכָל הָרוֹצֶה לַחְזֹר מִשְּׁנֵיהֶם חוֹזֵר וְאֵינוֹ חַיָּב לְקַבֵּל מִי שֶׁפָּרַע:","מָכַר לוֹ בִּדְבָרִים בִּלְבַד וּפָסְקוּ הַדָּמִים. וְרָשַׁם הַלּוֹקֵחַ רשֶׁם עַל הַמִּקָּח כְּדֵי שֶׁיִּהְיֶה לוֹ סִימָן יָדוּעַ שֶׁהוּא שֶׁלּוֹ. אַף עַל פִּי שֶׁלֹּא נָתַן מֵהַדָּמִים כְּלוּם כָּל הַחוֹזֵר בּוֹ אַחַר שֶׁרָשַׁם מְקַבֵּל מִי שֶׁפָּרַע. וְאִם מִנְהַג הַמְּדִינָה הוּא שֶׁיִּקְנֶה הָרשֶׁם קִנְיָן גָּמוּר נִקְנָה הַמִּקָּח. וְאֵין אֶחָד מֵהֶן יָכוֹל לַחְזֹר בּוֹ. וְיִהְיֶה זֶה חַיָּב לִתֵּן דָּמִים:","דָּבָר בָּרוּר הוּא שֶׁאֵין דִּין זֶה אֶלָּא בְּשֶׁרָשַׁם בִּפְנֵי הַמּוֹכֵר. אוֹ שֶׁאָמַר לוֹ הַמּוֹכֵר רְשֹׁם מִקָּחֲךָ. שֶׁהֲרֵי גָּמַר לְהַקְנוֹתָן כְּמוֹ שֶׁבֵּאַרְנוּ בַּחֲזָקָה וּבִמְשִׁיכָה:","הַנּוֹשֵׂא וְנוֹתֵן בִּדְבָרִים בִּלְבַד הֲרֵי זֶה רָאוּי לַעֲמֹד לוֹ בְּדִבּוּרוֹ אַף עַל פִּי שֶׁלֹּא לָקַח מִן הַדָּמִים כְּלוּם וְלֹא רָשַׁם וְלֹא הִנִּיחַ מַשְׁכּוֹן. וְכָל הַחוֹזֵר בּוֹ בֵּין לוֹקֵחַ בֵּין מוֹכֵר אַף עַל פִּי שֶׁאֵינוֹ חַיָּב לְקַבֵּל מִי שֶׁפָּרַע הֲרֵי זֶה מִמְּחֻסְּרֵי אֲמָנָה וְאֵין רוּחַ חֲכָמִים נוֹחָה הֵימֶנּוּ:","וְכֵן מִי שֶׁאָמַר לַחֲבֵרוֹ לִתֵּן לוֹ מַתָּנָה וְלֹא נָתַן הֲרֵי זֶה מִמְּחֻסְּרֵי אֲמָנָה. בַּמֶּה דְּבָרִים אֲמוּרִים בְּמַתָּנָה מוּעֶטֶת שֶׁהֲרֵי סָמְכָה דַּעְתּוֹ שֶׁל מְקַבֵּל כְּשֶׁהִבְטִיחוֹ. אֲבָל בְּמַתָּנָה מְרֻבָּה אֵין בָּהּ חֶסְרוֹן אֲמָנָה. שֶׁהֲרֵי לֹא הֶאֱמִין זֶה שֶׁיִּתֵּן לוֹ דְּבָרִים אֵלּוּ עַד שֶׁיִּקְנֶה אוֹתָן בִּדְבָרִים שֶׁקּוֹנִין בָּהֶן:","הַנּוֹתֵן מָעוֹת לַחֲבֵרוֹ לִקְנוֹת לוֹ קַרְקַע אוֹ מִטַּלְטְלִין וְהִנִּיחַ מְעוֹת חֲבֵרוֹ אֶצְלוֹ וְהָלַךְ וְקָנָה לְעַצְמוֹ בִּמְעוֹתָיו מַה שֶּׁעָשָׂה עָשׂוּי וַהֲרֵי הוּא מִכְּלַל הָרַמָּאִין:","הָיָה יוֹדֵעַ שֶׁזֶּה הַמּוֹכֵר אוֹהֵב אוֹתוֹ וּמְכַבְּדוֹ וּמוֹכֵר לוֹ וְאֵינוֹ מוֹכֵר לִמְשַׁלְּחוֹ הֲרֵי זֶה מֻתָּר לִקְנוֹת לְעַצְמוֹ. וְהוּא שֶׁיַּחֲזֹר וְיוֹדִיעוֹ. וְאִם מְפַחֵד שֶׁמָּא יָבוֹא אַחֵר וִיקַדְּמֶנּוּ לִקְנוֹת הֲרֵי זֶה קוֹנֶה לְעַצְמוֹ וְאַחַר כָּךְ מוֹדִיעוֹ:","הוֹרוּ מִקְצָת הַמּוֹרִים שֶׁאִם קָנָה לְעַצְמוֹ בִּמְעוֹת חֲבֵרוֹ אַחַר שֶׁזְּקָפָן עָלָיו מִלְוֶה הֲרֵי קָנָה לְעַצְמוֹ. וּמְקַבְּלִין מִמֶּנּוּ כְּשֶׁאָמַר זָקַפְתִּי אוֹתָם הַמָּעוֹת עַל עַצְמִי בְּמִלְוֶה. וַאֲנִי אוֹמֵר שֶׁאֵין דִּין זֶה דִּין אֱמֶת. אֶלָּא הַמִּקָּח שֶׁל מְשַׁלֵּחַ כְּמוֹ שֶׁיִּתְבָּאֵר בְּדִין הָעֵסֶק:","שְׁלֹשָׁה שֶׁנָּתְנוּ מָעוֹת לְאֶחָד לִקְנוֹת לָהֶם הַמִּקָּח. אִם הָיוּ הַמָּעוֹת מְעֹרָבוֹת וְקָנָה בְּמִקְצָת הַדָּמִים אַף עַל פִּי שֶׁהָיְתָה כַּוָּנַת הַשָּׁלִיחַ שֶׁזֶּה שֶׁקָּנָה לְאֶחָד מֵהֶן הֲרֵי הַמִּקָּח שֶׁל כֻּלָּן וְחוֹלְקִין אוֹתוֹ לְפִי מְעוֹתֵיהֶן:","הָיוּ מָעוֹת שֶׁל אֶחָד מֵהֶן צְרוּרִין וַחֲתוּמִין אַף עַל פִּי שֶׁהָיָה בְּלֵב הַשָּׁלִיחַ הַזֶּה שֶׁיַּקְנֶה הַמִּקָּח לְכֻלָּן לֹא קָנָה אֶלָּא זֶה שֶׁנִּקְנָה הַמִּקָּח בִּמְעוֹתָיו בִּלְבַד:"],"Mishneh Torah, Sanctification of the New Month 18":["דָבָר יָדוּעַ וּבָרוּר שֶׁאִם יוֹצִיא לְךָ הַחֶשְׁבּוֹן שֶׁהַיָּרֵחַ יֵרָאֶה בַּלַּיִלָה. אֶפְשָׁר שֶׁיֵּרָאֶה וְאֶפְשָׁר שֶׁלֹּא יֵרָאֶה מִפְּנֵי הֶעָבִים שֶׁמְּכַסִּין אוֹתוֹ אוֹ מִפְּנֵי הַמָּקוֹם שֶׁהוּא גַּיְא אוֹ שֶׁיִּהְיֶה הַר גָּבוֹהַּ כְּנֶגֶד רוּחַ מַעֲרָב לְאַנְשֵׁי אוֹתוֹ הַמָּקוֹם שֶׁנִּמְצְאוּ כְּאִלּוּ הֵן יוֹשְׁבִין בַּגַּיְא. שֶׁהַיָּרֵחַ לֹא יֵרָאֶה לְמִי שֶׁהוּא בְּמָקוֹם נָמוּךְ אֲפִלּוּ הָיָה גָּדוֹל וְיֵרָאֶה לְמִי שֶׁהוּא עוֹמֵד בְּרֹאשׁ הַר גָּבוֹהַּ וְתָלוּל אַף עַל פִּי שֶׁהַיָּרֵחַ קָטָן בְּיוֹתֵר. וְכֵן יֵרָאֶה לְמִי שֶׁשּׁוֹכֵן עַל שְׂפַת הַיָּם אוֹ לְמִי שֶׁמְּהַלֵּךְ בִּסְפִינָה בַּיָּם הַגָּדוֹל אַף עַל פִּי שֶׁהוּא קָטָן בְּיוֹתֵר:","וְכֵן בִּימוֹת הַגְּשָׁמִים אִם יִהְיֶה יוֹם צַח יֵרָאֶה הַיָּרֵחַ יוֹתֵר מִמַּה שֶּׁיֵּרָאֶה בִּימוֹת הַחַמָּה. לְפִי שֶׁבִּימוֹת הַגְּשָׁמִים אִם יִהְיֶה יוֹם צַח יִהְיֶה הָאֲוִיר זַךְ הַרְבֵּה וְיֵרָאֶה הָרָקִיעַ בְּטֹהַר יוֹתֵר מִפְּנֵי שֶׁאֵין שָׁם אָבָק שֶׁיִּתְעָרֵב בָּאֲוִיר. אֲבָל בִּימוֹת הַחַמָּה יִהְיֶה הָאֲוִיר כְּאִלּוּ הוּא מְעֵשָּׁן מִפְּנֵי הָאָבָק וְיֵרָאֶה הַיָּרֵחַ קָטָן:","וְכָל זְמַן שֶׁתִּמָּצֵא קֶשֶׁת הָרְאִיָּה וְהָאֹרֶךְ הָרִאשׁוֹן שֶׁתַּעֲרֹךְ לָהּ עִם שְׁנֵי הַקִּצִּין שֶׁלָּהֶם בְּצִמְצוּם. יִהְיֶה הַיָּרֵחַ קָטָן בְּיוֹתֵר וְלֹא יֵרָאֶה אֶלָּא בְּמָקוֹם גָּבוֹהַּ בְּיוֹתֵר. וְאִם תִּמָּצֵא קֶשֶׁת הָרְאִיָּה וְהָאֹרֶךְ הָרִאשׁוֹן אֲרֻכִּין הַרְבֵּה וְהוֹסִיפוּ עַד סוֹף הַקִּצִּים שֶׁלָּהֶן מִמַּעֲלוֹת. יֵרָאֶה הַיָּרֵחַ גָּדוֹל וּלְפִי אֹרֶךְ הַקֶּשֶׁת וְהָאֹרֶךְ הָרִאשׁוֹן יִהְיֶה גָּדְלוֹ וּגְלִיָּתוֹ לַכּל:","לְפִיכָךְ רָאוּי לְבֵית דִּין לָשׂוּם שְׁנֵי דְּבָרִים אֵלּוּ בְּלִבָּם. שֶׁהֵן זְמַן הָרְאִיָּה וּמְקוֹמָהּ. וְשׁוֹאֲלִין אֶת הָעֵדִים בְּאֵי זֶה מָקוֹם רְאִיתֶם. שֶׁאִם הָיְתָה קֶשֶׁת הָרְאִיָּה קְצָרָה וְיִתֵּן הַחֶשְׁבּוֹן שֶׁיֵּרָאֶה בְּצִמְצוּם. כְּגוֹן שֶׁהָיְתָה קֶשֶׁת הָרְאִיָּה ט' מַעֲלוֹת וְה' חֲלָקִים וְהָיָה הָאֹרֶךְ הָרִאשׁוֹן י\"ג מַעֲלוֹת בְּשָׁוֶה וּבָאוּ עֵדִים שֶׁרָאוּהוּ. אִם הָיָה בִּימוֹת הַחַמָּה אוֹ שֶׁהָיוּ בְּמָקוֹם נָמוּךְ חוֹשְׁשִׁין לָהֶן וּבוֹדְקִין אוֹתָן הַרְבֵּה וְאִם הָיָה בִּימוֹת הַגְּשָׁמִים אוֹ בְּמָקוֹם גָּבוֹהַּ בְּיוֹתֵר וַדַּאי יֵרָאֶה אִם לֹא יִהְיוּ שָׁם עָבִים הַמַּבְדִּילִין:","עֵדִים שֶׁרָאוּ אֶת הַחֹדֶשׁ בִּזְמַנּוֹ וּבָאוּ וְהֵעִידוּ וְקִבְּלוּם בֵּית דִּין וְקִדְּשׁוּ אֶת הַחֹדֶשׁ הַזֶּה הָרִאשׁוֹן וּמָנוּ כ\"ט יוֹם מִן הַיּוֹם הַמְ [קֵ] דָּשׁ. וְלֵיל שְׁלֹשִׁים לֹא נִרְאָה הַיָּרֵחַ מִפְּנֵי שֶׁאִי אֶפְשָׁר לוֹ לְהֵרָאוֹת אוֹ מִפְּנֵי שֶׁכִּסּוּהוּ עָבִים. וַהֲרֵי בֵּית דִּין מְצַפִּין לוֹ כָּל יוֹם שְׁלֹשִׁים כְּמוֹ שֶׁבֵּאַרְנוּ. וְלֹא בָּאוּ עֵדִים וְעִבְּרוּ אֶת הַחֹדֶשׁ וְנִמְצָא יוֹם ר\"ח הַשֵּׁנִי יוֹם ל\"א כְּמוֹ שֶׁבֵּאַרְנוּ:","וְהִתְחִילוּ לִמְנוֹת כ\"ט יוֹם מִן יוֹם רֹאשׁ הַחֹדֶשׁ הַשֵּׁנִי וְלֵיל שְׁלֹשִׁים לֹא נִרְאָה הַיָּרֵחַ. אִם תֹּאמַר שֶׁכָּךְ מְעַבְּרִין אֶת זֶה וְעוֹשִׂין אוֹתוֹ שְׁלֹשִׁים וְקוֹבְעִין רֹאשׁ הַחֹדֶשׁ הַשְּׁלִישִׁי יוֹם ל\"א. כָּךְ אֶפְשָׁר שֶׁלֹּא יֵרָאֶה הַיָּרֵחַ בְּלֵיל שְׁלֹשִׁים גַּם מֵחֹדֶשׁ זֶה וְנִמְצְאוּ מְעַבְּרִין וְהוֹלְכִין וְעוֹשִׂין חֳדָשִׁים אַחַר שְׁלֹשִׁים כָּל הַשָּׁנָה כֻּלָּהּ. וְנִמְצָא בְּחֹדֶשׁ אַחֲרוֹן אֶפְשָׁר שֶׁיֵּרָאֶה הַיָּרֵחַ בְּלֵיל כ\"ה בּוֹ אוֹ בְּלֵיל כ\"ו. וְאֵין לְךָ דְּבַר שְׂחוֹק וְהֶפְסֵד יוֹתֵר מִזֶּה:","וְאַל תֹּאמַר שֶׁהַדָּבָר הַזֶּה דָּבָר שֶׁאֵינוֹ מָצוּי הוּא שֶׁלֹּא יֵרָאֶה הַיָּרֵחַ בְּכָל הַשָּׁנָה. אֶלָּא דָּבָר קָרוֹב הוּא הַרְבֵּה. וּפְעָמִים רַבּוֹת יֶאֱרַע זֶה וְכַיּוֹצֵא בּוֹ בַּמְּדִינוֹת שֶׁזְּמַן הַגְּשָׁמִים שָׁם אָרֹךְ וְהֶעָבִים רַבִּים. שֶׁאֵין אָנוּ אוֹמְרִין שֶׁלֹּא יֵרָאֶה הַיָּרֵחַ בְּכָל הַשָּׁנָה אֶלָּא שֶׁלֹּא יֵרָאֶה בִּתְחִלַּת הֶחֳדָשִׁים וְיֵרָאֶה אַחַר כָּךְ. וּפְעָמִים לֹא יֵרָאֶה מִפְּנֵי שֶׁאִי אֶפְשָׁר לוֹ שֶׁיֵּרָאֶה בָּהֶם וְחֳדָשִׁים שֶׁאֶפְשָׁר שֶׁיֵּרָאֶה בָּהֶם לֹא יֵרָאֶה מִפְּנֵי הֶעָבִים אוֹ מִפְּנֵי שֶׁהָיָה קָטָן בְּיוֹתֵר וְלֹא נִתְכַּוֵּן אָדָם לִרְאוֹתוֹ:","אֶלָּא הַקַּבָּלָה שֶׁהָיָה בְּיַד חֲכָמִים אִישׁ מִפִּי אִישׁ מִפִּי משֶׁה רַבֵּנוּ כָּךְ הִיא. שֶׁבִּזְמַן שֶׁלֹּא יֵרָאֶה הַיָּרֵחַ בִּתְחִלַּת הֶחֳדָשִׁים חֹדֶשׁ אַחַר חֹדֶשׁ. בֵּית דִּין קוֹבְעִין חֹדֶשׁ מְעֵבָּר מִשְּׁלֹשִׁים יוֹם וְחֹדֶשׁ חָסֵר מִכ\"ט יוֹם. וְכֵן מְחַשְּׁבִין וְקוֹבְעִין חֹדֶשׁ מְעֻבָּר וְחֹדֶשׁ חָסֵר בִּקְבִיעָה לֹא בְּקִדּוּשׁ. שֶׁאֵין מְקַדְּשִׁין אֶלָּא עַל הָרְאִיָּה. וּפְעָמִים עוֹשִׂין מָלֵא אַחַר מָלֵא אוֹ חָסֵר אַחַר חָסֵר כְּמוֹ שֶׁיֵּרָאֶה לָהֶם מִן הַחֶשְׁבּוֹן:","וּמִתְכַּוְּנִין לְעוֹלָם בְּחֶשְׁבּוֹנָם שֶׁאִם יֵרָאֶה הַיָּרֵחַ בַּחֹדֶשׁ הַבָּא יֵרָאֶה בִּזְמַנּוֹ אוֹ בְּלֵיל עִבּוּרוֹ. לֹא שֶׁיֵּרָאֶה קֹדֶם זְמַנּוֹ שֶׁהוּא לֵיל כ\"ח. וּבְחֶשְׁבּוֹנוֹת הָרְאִיָּה הָאֵלּוּ שֶׁבֵּאַרְנוּ יִתְבָּאֵר לְךָ וְתֵדַע מָתַי אֶפְשָׁר שֶׁיֵּרָאֶה, וּמָתַי אִי אֶפְשָׁר, שֶׁלֹּא יֵרָאֶה. וְעַל זֶה סוֹמְכִין וּמְעַבְּרִין חֹדֶשׁ אַחַר חֹדֶשׁ אוֹ עוֹשִׂין חֹדֶשׁ חָסֵר אַחַר חֹדֶשׁ חָסֵר. וּלְעוֹלָם אֵין פּוֹחֲתִין מֵאַרְבָּעָה חֳדָשִׁים הַמְעֻבָּרִין בְּשָׁנָה וְלֹא מוֹסִיפִין עַל שְׁמוֹנָה חֳדָשִׁים הַמְעֻבָּרִין. וְגַם לְעִבּוּר חֳדָשִׁים אֵלּוּ שֶׁמְּעַבְּרִין לְפִי חֶשְׁבּוֹן עוֹשִׂין סְעֻדַּת עִבּוּר הַחֹדֶשׁ כְּמוֹ שֶׁאָמַרְנוּ בְּפֶרֶק שְׁלִישִׁי:","וְכָל שֶׁתִּמְצָא בַּגְּמָרָא מִדְּבָרִיִם שֶּׁמַּרְאִין שֶׁבֵּית דִּין סוֹמְכִין עַל הַחֶשְׁבּוֹן וּמִפִּי משֶׁה מִסִּינַי שֶׁהַדָּבָר מָסוּר לָהֶם וְהָרְשׁוּת בְּיָדָם לְחַסֵּר אוֹ לְעַבֵּר. וְכֵן זֶה שֶׁחָסֵר תִּשְׁעָה חֳדָשִׁים בַּשָּׁנָה וְכָל כַּיּוֹצֵא בָּזֶה הַכּל עַל עִקָּר זֶה הוּא בָּנוּי בִּזְמַן שֶׁלֹּא נִרְאֶה הַחֹדֶשׁ בִּזְמַנּוֹ:","וְכֵן זֶה שֶׁאָמְרוּ חֲכָמִים שֶׁמְּעַבְּרִין אֶת הַחֹדֶשׁ לְצֹרֶךְ הוּא בֶּחֳדָשִׁים אֵלּוּ שֶׁמְּעַבְּרִין אוֹתָן לְפִי חֶשְׁבּוֹן וְעוֹשִׂין אֶחָד מָלֵא וְאֶחָד חָסֵר. וְיֵשׁ לָהֶם לְעַבֵּר חֹדֶשׁ אַחַר חֹדֶשׁ אוֹ לְחַסֵּר. בָּזֶה הוּא שֶׁמְּעַבְּרִין לְצֹרֶךְ מִפְּנֵי שֶׁלֹּא נִרְאֶה הַיָּרֵחַ בִּזְמַנּוֹ. אֶלָּא בְּעֵת שֶׁיֵּרָאֶה הַיָּרֵחַ בִּזְמַנּוֹ שֶׁהוּא תְּחִלַּת הֱיוֹתוֹ נִרְאֶה אַחַר שֶׁנִּתְקַבֵּץ עִם הַשֶּׁמֶשׁ מְקַדְּשִׁין לְעוֹלָם:","וְכָל הַדְּבָרִים הָאֵלּוּ בִּזְמַן שֶׁיֵּשׁ שָׁם בֵּית דִּין וְסוֹמְכִין עַל הָרְאִיָּה. אֲבָל בִּזְמַנִּים אֵלּוּ אֵין סוֹמְכִין אֶלָּא עַל הַקְּבִיעָה בְּזֶה הַחֶשְׁבּוֹן הָאֶמְצָעִי הַפָּשׁוּט בְּכָל יִשְׂרָאֵל כְּמוֹ שֶׁבֵּאַרְנוּ בַּהֲלָכוֹת אֵלּוּ:","יִתְבָּאֵר בְּסִפְרֵי הַחֶשְׁבּוֹן הַתְּקוּפוֹת וְהַגִּימַטְרִיָּאוֹת שֶׁאִם יֵרָאֶה הַיָּרֵחַ בְּאֶרֶץ יִשְׂרָאֵל יֵרָאֶה בְּכָל מְדִינוֹת הָעוֹלָם שֶׁהֵן לְמַעֲרַב אֶרֶץ יִשְׂרָאֵל וּמְכֻוָּנוֹת כְּנֶגְדָּהּ. וְאִם יִתֵּן הַחֶשְׁבּוֹן שֶׁלֹּא יֵרָאֶה בְּאֶרֶץ יִשְׂרָאֵל אֶפְשָׁר שֶׁיֵּרָאֶה בִּמְדִינוֹת אֲחֵרוֹת שֶׁהֵן לְמַעֲרַב אֶרֶץ יִשְׂרָאֵל וּמְכֻוָּנוֹת כְּנֶגְדָּהּ. לְפִיכָךְ אִם יֵרָאֶה הַיָּרֵחַ בִּמְדִינָה שֶׁהִיא לְמַעֲרַב אֶרֶץ יִשְׂרָאֵל אֵין בָּזֶה רְאָיָה שֶׁלֹּא יֵרָאֶה בְּאֶרֶץ יִשְׂרָאֵל אֶלָּא אֶפְשָׁר שֶׁנִּרְאֶה הַיָּרֵחַ בְּאֶרֶץ יִשְׂרָאֵל:","אֲבָל אִם לֹא יֵרָאֶה הַיָּרֵחַ בְּרֹאשׁ הֶהָרִים בַּמְּדִינָה הַמַּעֲרָבִית הַמְכֻוֶּנֶת כְּנֶגֶד אֶרֶץ יִשְׂרָאֵל בְּיָדוּעַ שֶׁלֹּא נִרְאֶה בְּאֶרֶץ יִשְׂרָאֵל:","וְכֵן אִם לֹא יֵרָאֶה הַיָּרֵחַ בְּאֶרֶץ יִשְׂרָאֵל בְּיָדוּעַ שֶׁלֹּא נִרְאֶה בְּכָל מְדִינוֹת הָעוֹלָם שֶׁהֵן לְמִזְרַח אֶרֶץ יִשְׂרָאֵל וּמְכֻוָּנוֹת כְּנֶגְדָּהּ. וְאִם יֵרָאֶה בְּאֶרֶץ יִשְׂרָאֵל אֶפְשָׁר שֶׁיֵּרָאֶה בִּמְדִינוֹת מִזְרָחִיּוֹת וְאֶפְשָׁר שֶׁלֹּא יֵרָאֶה. לְפִיכָךְ אִם יֵרָאֶה בִּמְדִינָה שֶׁהִיא לְמִזְרַח אֶרֶץ יִשְׂרָאֵל וּמְכֻוֶּנֶת כְּנֶגְדָּהּ בְּיָדוּעַ שֶׁנִּרְאֶה בְּאֶרֶץ יִשְׂרָאֵל. וְאִם לֹא נִרְאֶה בַּמְּדִינָה הַמִּזְרָחִית אֵין בָּזֶה רְאָיָה אֶלָּא אֶפְשָׁר שֶׁיֵּרָאֶה בְּאֶרֶץ יִשְׂרָאֵל:","וְכָל אֵלּוּ הַדְּבָרִים כְּשֶׁהָיוּ הַמְּדִינוֹת שֶׁבַּמַּעֲרָב וְשֶׁבַּמִּזְרָח מְכֻוָּנוֹת. כְּגוֹן שֶׁהָיוּ נוֹטוֹת לִצְפוֹן הָעוֹלָם מִשְּׁלֹשִׁים מַעֲלוֹת עַד ל\"ה מַעֲלוֹת. אֲבָל אִם הָיוּ נוֹטוֹת לַצָּפוֹן יוֹתֵר מִזֶּה אוֹ פָּחוֹת. מִשְׁפָּטִים אֲחֵרִים יֵשׁ לָהֶן שֶׁהֲרֵי אֵינָן מְכֻוָּנוֹת כְּנֶגֶד אֶרֶץ יִשְׂרָאֵל. וּדְבָרִים אֵלּוּ שֶׁבֵּאַרְנוּ בְּעָרֵי מִזְרָח וּמַעֲרָב אֵינָן אֶלָּא לְהַגִּיד כָּל מִשְׁפְּטֵי הָרְאִיָּה לְהַגְדִּיל תּוֹרָה וּלְהַאְדִּירָהּ. לֹא שֶׁיִּהְיוּ בְּנֵי מִזְרָח אוֹ בְּנֵי מַעֲרָב סוֹמְכִין עַל רְאִיַּת הַיָּרֵחַ אוֹ תּוֹעִיל לָהֶם כְּלוּם. אֶלָּא לְעוֹלָם אֵין סוֹמְכִין אֶלָּא עַל קִדּוּשׁ בֵּית דִּין שֶׁבְּאֶרֶץ יִשְׂרָאֵל כְּמוֹ שֶׁבֵּאַרְנוּ כַּמָּה פְּעָמִים:"],"Mishneh Torah, Scroll of Esther and Hanukkah 3":["בְבַיִת שֵׁנִי כְּשֶׁמַּלְכֵי יָוָן גָּזְרוּ גְּזֵרוֹת עַל יִשְׂרָאֵל וּבִטְּלוּ דָּתָם וְלֹא הֵנִיחוּ אוֹתָם לַעֲסֹק בְּתוֹרָה וּבְמִצְוֹת. וּפָשְׁטוּ יָדָם בְּמָמוֹנָם וּבִבְנוֹתֵיהֶם וְנִכְנְסוּ לַהֵיכָל וּפָרְצוּ בּוֹ פְּרָצוֹת וְטִמְּאוּ הַטָּהֳרוֹת. וְצָר לָהֶם לְיִשְׂרָאֵל מְאֹד מִפְּנֵיהֶם וּלְחָצוּם לַחַץ גָּדוֹל עַד שֶׁרִחֵם עֲלֵיהֶם אֱלֹהֵי אֲבוֹתֵינוּ וְהוֹשִׁיעָם מִיָּדָם וְהִצִּילָם וְגָבְרוּ בְּנֵי חַשְׁמוֹנַאי הַכֹּהֲנִים הַגְּדוֹלִים וַהֲרָגוּם וְהוֹשִׁיעוּ יִשְׂרָאֵל מִיָּדָם וְהֶעֱמִידוּ מֶלֶךְ מִן הַכֹּהֲנִים וְחָזְרָה מַלְכוּת לְיִשְׂרָאֵל יֶתֶר עַל מָאתַיִם שָׁנָה עַד הַחֻרְבָּן הַשֵּׁנִי:","וּכְשֶׁגָּבְרוּ יִשְׂרָאֵל עַל אוֹיְבֵיהֶם וְאִבְּדוּם בְּכ\"ה בְּחֹדֶשׁ כִּסְלֵו הָיָה וְנִכְנְסוּ לַהֵיכָל וְלֹא מָצְאוּ שֶׁמֶן טָהוֹר בַּמִּקְדָּשׁ אֶלָּא פַּךְ אֶחָד וְלֹא הָיָה בּוֹ לְהַדְלִיק אֶלָּא יוֹם אֶחָד בִּלְבַד וְהִדְלִיקוּ מִמֶּנּוּ נֵרוֹת הַמַּעֲרָכָה שְׁמוֹנָה יָמִים עַד שֶׁכָּתְשׁוּ זֵיתִים וְהוֹצִיאוּ שֶׁמֶן טָהוֹר:","וּמִפְּנֵי זֶה הִתְקִינוּ חֲכָמִים שֶׁבְּאוֹתוֹ הַדּוֹר שֶׁיִּהְיוּ שְׁמוֹנַת הַיָּמִים הָאֵלּוּ שֶׁתְּחִלָּתָן כ\"ה בְּכִסְלֵו יְמֵי שִׂמְחָה וְהַלֵּל וּמַדְלִיקִין בָּהֶן הַנֵּרוֹת בָּעֶרֶב עַל פִּתְחֵי הַבָּתִּים בְּכָל לַיְלָה וְלַיְלָה מִשְּׁמוֹנַת הַלֵּילוֹת לְהַרְאוֹת וּלְגַלּוֹת הַנֵּס. וְיָמִים אֵלּוּ הֵן הַנִּקְרָאִין חֲנֻכָּה וְהֵן אֲסוּרִין בְּהֶסְפֵּד וְתַעֲנִית כִּימֵי הַפּוּרִים. וְהַדְלָקַת הַנֵּרוֹת בָּהֶן מִצְוָה מִדִּבְרֵי סוֹפְרִים כִּקְרִיאַת הַמְּגִלָּה:","כָּל שֶׁחַיָּב בִּקְרִיאַת הַמְּגִלָּה חַיָּב בְּהַדְלָקַת נֵר חֲנֻכָּה וְהַמַּדְלִיק אוֹתָהּ בַּלַּיְלָה הָרִאשׁוֹן מְבָרֵךְ שָׁלֹשׁ בְּרָכוֹת וְאֵלּוּ הֵן. בָּרוּךְ אַתָּה ה' אֱלֹקֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לְהַדְלִיק נֵר שֶׁל חֲנֻכָּה וְשֶׁעָשָׂה נִסִּים לַאֲבוֹתֵינוּ וְכוּ'. וְשֶׁהֶחֱיָנוּ וְקִיְּמָנוּ וְכוּ'. וְכָל הָרוֹאֶה אוֹתָהּ וְלֹא בֵּרֵךְ מְבָרֵךְ שְׁתַּיִם. שֶׁעָשָׂה נִסִּים לַאֲבוֹתֵינוּ וְשֶׁהֶחֱיָנוּ. וּבִשְׁאָר הַלֵּילוֹת הַמַּדְלִיק מְבָרֵךְ שְׁתַּיִם וְהָרוֹאֶה מְבָרֵךְ אַחַת שֶׁאֵין מְבָרְכִין שֶׁהֶחֱיָנוּ אֶלָּא בַּלַּיְלָה הָרִאשׁוֹן:","בְּכָל יוֹם וָיוֹם מִשְּׁמוֹנַת הַיָּמִים אֵלּוּ גּוֹמְרִין אֶת הַהַלֵּל וּמְבָרֵךְ לְפָנָיו אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לִגְמֹר אֶת הַהַלֵּל בֵּין יָחִיד בֵּין צִבּוּר. אַף עַל פִּי שֶׁקְּרִיאַת הַהַלֵּל מִצְוָה מִדִּבְרֵי סוֹפְרִים מְבָרֵךְ עָלָיו אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ כְּדֶרֶךְ שֶׁמְּבָרֵךְ עַל הַמְּגִלָּה וְעַל הָעֵרוּב. שֶׁכָּל וַדַּאי שֶׁל דִּבְרֵיהֶם מְבָרְכִין עָלָיו. אֲבָל דָּבָר שֶׁהוּא מִדִּבְרֵיהֶם וְעִקַּר עֲשִׂיָּתָן לוֹ מִפְּנֵי הַסָּפֵק כְּגוֹן מַעֲשֵׂר דְּמַאי אֵין מְבָרְכִין עָלָיו. וְלָמָּה מְבָרְכִין עַל יוֹם טוֹב שֵׁנִי וְהֵם לֹא תִּקְּנוּהוּ אֶלָּא מִפְּנֵי הַסָּפֵק כְּדֵי שֶׁלֹּא יְזַלְזְלוּ בּוֹ:","וְלֹא הַלֵּל שֶׁל חֲנֻכָּה בִּלְבַד הוּא שֶׁמִּדִּבְרֵי סוֹפְרִים אֶלָּא קְרִיאַת הַהַלֵּל לְעוֹלָם מִדִּבְרֵי סוֹפְרִים בְּכָל הַיָּמִים שֶׁגּוֹמְרִין בָּהֶן אֶת הַהַלֵּל. וּשְׁמוֹנָה עָשָׂר יוֹם בַּשָּׁנָה מִצְוָה לִגְמֹר בָּהֶן אֶת הַהַלֵּל. וְאִלּוּ הֵן. שְׁמוֹנַת יְמֵי הֶחָג. וּשְׁמוֹנַת יְמֵי חֲנֻכָּה. וְרִאשׁוֹן שֶׁל פֶּסַח וְיוֹם עֲצֶרֶת. אֲבָל רֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים אֵין בָּהֶן הַלֵּל לְפִי שֶׁהֵן יְמֵי תְּשׁוּבָה וְיִרְאָה וָפַחַד לֹא יְמֵי שִׂמְחָה יְתֵרָה. וְלֹא תִּקְּנוּ הַלֵּל בְּפוּרִים שֶׁקְּרִיאַת הַמְּגִלָּה הִיא הַהַלֵּל:","מְקוֹמוֹת שֶׁעוֹשִׂין יוֹם טוֹב שְׁנֵי יָמִים גּוֹמְרִין אֶת הַהַלֵּל עֶשְׂרִים וְאֶחָד יוֹם. תִּשְׁעָה יְמֵי הֶחָג. וּשְׁמוֹנָה יְמֵי חֲנֻכָּה. וּשְׁנֵי יָמִים שֶׁל פֶּסַח. וּשְׁנֵי יָמִים שֶׁל עֲצֶרֶת. אֲבָל בְּרָאשֵׁי חֳדָשִׁים קְרִיאַת הַהַלֵּל מִנְהָג וְאֵינוֹ מִצְוָה. וּמִנְהָג זֶה בְּצִבּוּר לְפִיכָךְ קוֹרְאִין בְּדִלּוּג. וְאֵין מְבָרְכִין עָלָיו שֶׁאֵין מְבָרְכִין עַל הַמִּנְהָג. וְיָחִיד לֹא יִקְרָא כְּלָל. וְאִם הִתְחִיל יַשְׁלִים וְיִקְרָא בְּדִלּוּג כְּדֶרֶךְ שֶׁקּוֹרְאִין הַצִּבּוּר. וְכֵן בִּשְׁאָר יְמֵי הַפֶּסַח קוֹרְאִין בְּדִלּוּג כְּרָאשֵׁי חֳדָשִׁים:","כֵּיצַד מְדַלְּגִין. מַתְחִילִין מִתְּחִלַּת הַהַלֵּל עַד (תהילים קיד ח) \"חַלָּמִישׁ לְמַעְיְנוֹ מָיִם\" וּמְדַלֵּג וְאוֹמֵר (תהילים קטו יב) \"ה' זְכָרָנוּ יְבָרֵךְ\" כוּ' עַד (תהילים קטו יח) \"הַלְלוּיָהּ\" וּמְדַלֵּג וְאוֹמֵר (תהילים קטז יב) \"מָה אָשִׁיב לַה'\" עַד (תהילים קטז יט) \"הַלְלוּיָהּ\" וּמְדַלֵּג וְאוֹמֵר (תהילים קיח ה) \"מִן הַמֵּצַר קָרָאתִי יָהּ\" עַד סוֹף הַהַלֵּל. זֶה הוּא הַמִּנְהָג הַפָּשׁוּט. וְיֵשׁ מְדַלְּגִין דִּלּוּג אַחֵר:","כָּל הַיּוֹם כָּשֵׁר לִקְרִיאַת הַהַלֵּל. וְהַקּוֹרֵא אֶת הַהַלֵּל לְמַפְרֵעַ לֹא יָצָא. קָרָא וְשָׁהָה וְחָזַר וְקָרָא אַף עַל פִּי שֶׁשָּׁהָה כְּדֵי לִגְמֹר אֶת כֻּלּוֹ יָצָא. יָמִים שֶׁגּוֹמְרִין בָּהֶן אֶת הַהַלֵּל יֵשׁ לוֹ לְהַפְסִיק בֵּין פֶּרֶק לְפֶרֶק אֲבָל בְּאֶמְצַע הַפֶּרֶק לֹא יַפְסִיק. וְיָמִים שֶׁקּוֹרְאִין בָּהֶן בְּדִלּוּג אֲפִלּוּ בְּאֶמְצַע הַפֶּרֶק פּוֹסֵק:","כָּל יוֹם שֶׁגּוֹמְרִין בּוֹ אֶת הַהַלֵּל מְבָרֵךְ לְפָנָיו. וּמָקוֹם שֶׁנָּהֲגוּ לְבָרֵךְ אַחֲרָיו מְבָרֵךְ. כֵּיצַד מְבָרֵךְ. יְהַלְלוּךָ ה' אֱלֹהֵינוּ כָּל מַעֲשֶׂיךָ וְצַדִּיקִים וַחֲסִידִים עוֹשֵׂי רְצוֹנֶךָ וְכָל עַמְּךָ בֵּית יִשְׂרָאֵל בְּרִנָּה יוֹדוּ לְשִׁמְךָ כִּי אַתָּה ה' לְךָ טוֹב לְהוֹדוֹת וְנָעִים לְשִׁמְךָ לְזַמֵּר וּמֵעוֹלָם וְעַד עוֹלָם אַתָּה הָאֵל בָּרוּךְ אַתָּה ה' הַמֶּלֶךְ הַמְהֻלָּל הַמְשֻׁבָּח הַמְפֹאָר חַי וְקַיָּם תָּמִיד יִמְלוֹךְ לְעוֹלָם וָעֶד:","יֵשׁ מְקוֹמוֹת שֶׁנָּהֲגוּ לִכְפּל מֵ (תהילים קיח כא) \"אוֹדְךָ כִּי עֲנִיתָנִי\" עַד סוֹף הַהַלֵּל כּוֹפְלִין כָּל דָּבָר וְדָבָר שְׁתֵּי פְּעָמִים. וּמָקוֹם שֶׁנָּהֲגוּ לִכְפּל יִכְפּל וּמָקוֹם שֶׁנָּהֲגוּ שֶׁלֹּא לִכְפּל אֵין כּוֹפְלִין:","מִנְהַג קְרִיאַת הַהַלֵּל בִּימֵי חֲכָמִים הָרִאשׁוֹנִים כָּךְ הָיָה. אַחַר שֶׁמְּבָרֵךְ הַגָּדוֹל שֶׁמַּקְרֵא אֶת הַהַלֵּל מַתְחִיל וְאוֹמֵר הַלְלוּיָהּ וְכָל הָעָם עוֹנִין הַלְלוּיָהּ וְחוֹזֵר וְאוֹמֵר הַלְלוּ עַבְדֵי ה' וְכָל הָעָם עוֹנִין הַלְלוּיָהּ וְחוֹזֵר וְאוֹמֵר הַלְלוּ אֶת שֵׁם ה' וְכָל הָעָם עוֹנִין הַלְלוּיָהּ וְחוֹזֵר וְאוֹמֵר יְהִי שֵׁם ה' מְבֹרָךְ מֵעַתָּה וְעַד עוֹלָם וְכָל הָעָם עוֹנִין הַלְלוּיָהּ וְכֵן עַל כָּל דָּבָר. עַד שֶׁנִּמְצְאוּ עוֹנִין בְּכָל הַהַלֵּל הַלְלוּיָהּ מֵאָה וְשָׁלֹשׁ וְעֶשְׂרִים פְּעָמִים סִימָן לָהֶם שְׁנוֹתָיו שֶׁל אַהֲרֹן:","וְכֵן כְּשֶׁהַקּוֹרֵא מַגִּיעַ לְרֹאשׁ כָּל פֶּרֶק וּפֶרֶק הֵן חוֹזְרִין וְאוֹמְרִין מַה שֶּׁאָמַר. כֵּיצַד. כְּשֶׁהוּא אוֹמֵר בְּצֵאת יִשְׂרָאֵל מִמִּצְרַיִם כָּל הָעָם חוֹזְרִין וְאוֹמְרִין בְּצֵאת יִשְׂרָאֵל מִמִּצְרָיִם. וְהַקּוֹרֵא אוֹמֵר בֵּית יַעֲקֹב מֵעַם לֹעֵז וְכָל הָעָם עוֹנִין הַלְלוּיָהּ עַד שֶׁיֹּאמַר אָהַבְתִּי כִּי יִשְׁמַע ה' אֶת קוֹלִי תַּחֲנוּנָי וְכָל הָעָם חוֹזְרִין וְאוֹמְרִין אָהַבְתִּי כִּי יִשְׁמַע ה' וְכוּ'. וְכֵן כְּשֶׁיֹּאמַר הַקּוֹרֵא הַלְלוּ אֶת ה' כָּל גּוֹיִם כָּל הָעָם חוֹזְרִין וְאוֹמְרִין הַלְלוּ אֶת ה' כָּל גּוֹיִם:","הַקּוֹרֵא אוֹמֵר אָנָּא ה' הוֹשִׁיעָה נָּא וְהֵם עוֹנִין אַחֲרָיו אָנָּא ה' הוֹשִׁיעָה נָּא. אַף עַל פִּי שֶׁאֵינוֹ רֹאשׁ פֶּרֶק. הוּא אוֹמֵר אָנָּא ה' הַצְלִיחָה נָּא וְהֵם עוֹנִים אָנָּא ה' הַצְלִיחָה נָּא. הוּא אוֹמֵר בָּרוּךְ הַבָּא וְכָל הָעָם אוֹמְרִים בָּרוּךְ הַבָּא. וְאִם הָיָה הַמַּקְרֵא אֶת הַהַלֵּל קָטָן אוֹ עֶבֶד אוֹ אִשָּׁה עוֹנָה אַחֲרֵיהֶם מַה שֶּׁהֵן אוֹמְרִין מִלָּה מִלָּה בְּכָל הַהַלֵּל. זֶהוּ הַמִּנְהָג הָרִאשׁוֹן וּבוֹ רָאוּי לֵילֵךְ. אֲבָל בִּזְמַנִּים אֵלּוּ רָאִיתִי בְּכָל הַמְּקוֹמוֹת מִנְהָגוֹת מְשֻׁנּוֹת בִּקְרִיאָתוֹ וּבַעֲנִיַּת הָעָם וְאֵין אֶחָד מֵהֶם דּוֹמֶה לְאֶחָד:"],"Mishneh Torah, Second Tithes and Fourth Year's Fruit 9":["נֶּטַע רְבָעִי הֲרֵי הוּא קֹדֶשׁ. שֶׁנֶּאֱמַר (ויקרא יט כד) \"וּבַשָּׁנָה הָרְבִיעִת יִהְיֶה כָּל פִּרְיוֹ קֹדֶשׁ הִלּוּלִים לַה'\". וְדִינוֹ לְהֵאָכֵל בִּירוּשָׁלַיִם לִבְעָלָיו כְּמַעֲשֵׂר שֵׁנִי. וּכְשֵׁם שֶׁאֵין מַעֲשֵׂר שֵׁנִי בְּסוּרְיָא כָּךְ אֵין נֶטַע רְבָעִי בְּסוּרְיָא. וּבְנֶטַע רְבָעִי הוּא אוֹמֵר (במדבר ה י) \"וְאִישׁ אֶת קֳדָשָׁיו לוֹ יִהְיוּ\" שֶׁאֵין לְךָ קֹדֶשׁ שֶׁלֹּא נִתְפָּרֵשׁ דִּינוֹ בַּתּוֹרָה לְמִי שֶׁהוּא חוּץ מִנֶּטַע רְבָעִי:","הָרוֹצֶה לִפְדּוֹת נֶטַע רְבָעִי פּוֹדֵהוּ כְּמַעֲשֵׂר שֵׁנִי. וְאִם פָּדָהוּ לְעַצְמוֹ מוֹסִיף חֹמֶשׁ. וְאֵין פּוֹדִין אוֹתוֹ עַד שֶׁיַּגִּיעוּ לְעוֹנַת הַמַּעֲשֵׂר שֶׁנֶּאֱמַר (ויקרא יט כה) \"לְהוֹסִיף לָכֶם תְּבוּאָתוֹ\" עַד שֶׁיַּעֲשֶׂה תְּבוּאָה. וְאֵין פּוֹדִין אוֹתוֹ בִּמְחֻבָּר כְּמַעֲשֵׂר שֵׁנִי וַהֲרֵי הוּא מָמוֹן גָּבוֹהַּ כְּמַעֲשֵׂר. לְפִיכָךְ אֵינוֹ נִקְנֶה בְּמַתָּנָה אֶלָּא אִם נְתָנוֹ בֹּסֶר. וְדִינוֹ בִּשְׁאָר הַדְּבָרִים לְעִנְיַן אֲכִילָה וּשְׁתִיָּה וּפְדִיָּה כְּמַעֲשֵׂר:","וְהַפּוֹדֶה כֶּרֶם רְבָעִי רָצָה פּוֹדֵהוּ עֲנָבִים רָצָה פּוֹדֵהוּ יַיִן. וְכֵן הַזֵּיתִים. אֲבָל שְׁאָר הַפֵּרוֹת אֵין מְשַׁנִּין אוֹתָן מִבְּרִיָּתָן:","כֶּרֶם רְבָעִי אֵין לוֹ לֹא שִׁכְחָה וְלֹא פֵּאָה וְלֹא פֶּרֶט וְלֹא עוֹלֵלוֹת. וְאֵין מַפְרִישִׁין מִמֶּנּוּ תְּרוּמָה וּמַעַשְׂרוֹת כְּשֵׁם שֶׁאֵין מַפְרִישִׁין מִמַּעֲשֵׂר שֵׁנִי. אֶלָּא כֻּלּוֹ עוֹלֶה לִירוּשָׁלַיִם אוֹ נִפְדֶּה וְיַעֲלוּ הַדָּמִים וְיֵאָכְלוּ בִּירוּשָׁלַיִם כְּמַעֲשֵׂר:","עֲנָבִים שֶׁל כֶּרֶם רְבָעִי הִתְקִינוּ בֵּית דִּין שֶׁיִּהְיוּ עוֹלִין לִירוּשָׁלַיִם מַהֲלַךְ יוֹם לְכָל צַד כְּדֵי לְעַטֵּר שׁוּקֵי יְרוּשָׁלַיִם בְּפֵרוֹת. וּמִשֶׁחָרַב בֵּית הַמִּקְדָּשׁ נִפְדֶּה אֲפִלּוּ סָמוּךְ לַחוֹמָה. וּשְׁאָר כָּל הַפֵּרוֹת אֲפִלּוּ בִּזְמַן בֵּית הַמִּקְדָּשׁ נִפְדִּין סָמוּךְ לַחוֹמָה:","כֵּיצַד פּוֹדִין נֶטַע רְבָעִי. מֵנִיחַ אֶת הַסַּל עַל פִּי שְׁלֹשָׁה וְאוֹמְדִין כַּמָּה אָדָם רוֹצֶה לִפְדּוֹת לוֹ בַּסֶּלַע עַל מְנָת שֶׁיּוֹצִיא יְצִיאוֹת הַשּׁוֹמְרִים וְהַחֲמָרִים וְהַפּוֹעֲלִים מִבֵּיתוֹ. וְאַחַר שֶׁקּוֹצְבִין אֶת הַשַּׁעַר מַנִּיחַ אֶת הַמָּעוֹת וְאוֹמֵר כָּל הַנִּלְקָט מִזֶּה מְחֻלָּל עַל הַמָּעוֹת אֵלּוּ מִשַּׁעַר כָּךְ וְכָךְ סַלִּים בְּסֶלַע. וּבַשְּׁבִיעִית פּוֹדֵהוּ בְּשָׁוְיוֹ שֶׁאֵין שָׁם לֹא שׁוֹמְרִים וְלֹא פּוֹעֲלִים. וְאִם הָיָה הֶפְקֵר אֵין לוֹ אֶלָּא שְׂכַר לְקִיטָה בִּלְבַד:","מִי שֶׁהָיָה לוֹ נֶטַע רְבָעִי בִּשְׁנַת הַשְּׁמִטָּה שֶׁיַּד הַכּל שָׁוָה צָרִיךְ לְצַיְּנוֹ בְּקוֹזָזוֹת אֲדָמָה כְּדֵי שֶׁיַּכִּירוּ בּוֹ. וְלֹא יֹאכְלוּ מִמֶּנּוּ עַד שֶׁיִּפָּדוּ. וְאִם הָיָה בְּתוֹךְ שְׁנֵי עָרְלָה מְצַיְּנִין אוֹתוֹ בַּחֲרָסִים כְּדֵי שֶׁיִּפְרְשׁוּ מִמֶּנּוּ. שֶׁאִם צִיְּנוּ בְּקוֹזָזוֹת אֲדָמָה שֶׁמָּא יִתְפָּרְרוּ. שֶׁאִסּוּר עָרְלָה חָמוּר הוּא שֶׁהִיא אֲסוּרָה בַּהֲנָיָה. וְהַצְּנוּעִין הָיוּ מַנִּיחִין אֶת הַמָּעוֹת בִּשְׁנַת שְׁמִטָּה וְאוֹמְרִין כָּל הַנִּלְקָט מִפֵּרוֹת רְבָעִי אֵלּוּ מְחֻלָּל עַל הַמָּעוֹת הָאֵלּוּ שֶׁהֲרֵי אִי אֶפְשָׁר לִפְדּוֹתוֹ בִּמְחֻבָּר כְּמוֹ שֶׁבֵּאַרְנוּ:","בְּאֶחָד בְּתִשְׁרֵי רֹאשׁ הַשָּׁנָה לְעָרְלָה וְלִרְבָעִי. וּמֵאֵימָתַי מוֹנִין לָהֶם מִשְּׁעַת נְטִיעָה. וְאֵינוֹ מוֹנֶה מֵרֹאשׁ הַשָּׁנָה לְרֹאשׁ הַשָּׁנָה אֶלָּא שְׁלֹשִׁים יוֹם בְּשָׁנָה חֲשׁוּבִין שָׁנָה. וְהוּא שֶׁתִּקְלֹט הַנְּטִיעָה קֹדֶם שְׁלֹשִׁים יוֹם. וְכַמָּה הוּא סְתַם הַקְּלִיטָה לְכָל הָאִילָנוֹת שְׁתֵּי שַׁבָּתוֹת:","נִמְצֵאת לָמֵד שֶׁהַנּוֹטֵעַ מ\"ד יוֹם קֹדֶם רֹאשׁ הַשָּׁנָה עָלְתָה לוֹ שָׁנָה. וְאַף עַל פִּי כֵן אֵין פֵּרוֹת הַנְּטִיעָה הַזֹּאת מֻתָּרוֹת בְּעָרְלָה אֶלָּא בִּרְבִיעִית עַד ט\"ו בִּשְׁבָט שֶׁהוּא רֹאשׁ הַשָּׁנָה לָאִילָנוֹת:","כֵּיצַד. הַנּוֹטֵעַ אִילַן מַאֲכָל בְּט\"ו בְּאָב מִשָּׁנָה עֲשִׂירִית בַּיּוֹבֵל. הֲרֵי הוּא בְּתוֹךְ שְׁנֵי עָרְלָה עַד ט\"ו בִּשְׁבָט מִשְּׁנַת י\"ג. וְכָל מַה שֶּׁיּוֹצִיא הָאִילָן בְּתוֹךְ זְמַן זֶה הֲרֵי הוּא עָרְלָה אַף עַל פִּי שֶׁנִּגְמְרוּ לְאַחַר כַּמָּה יָמִים. וּמִט\"ו בִּשְׁבָט מִשְּׁנַת י\"ג בְּיוֹבֵל עַד ט\"ו בִּשְׁבָט מִשְּׁנַת י\"ד הוּא נֶטַע רְבָעִי. וְכָל מַה שֶּׁיּוֹצִיא בְּתוֹךְ זְמַן זֶה הֲרֵי הוּא רְבָעִי וְצָרִיךְ פִּדְיוֹן. וְאִם נִתְעַבְּרָה הַשָּׁנָה נִתְעַבְּרָה לַעָרְלָה אוֹ לַרְבָעִי:","נִטְעַן בְּשִׁשָּׁה עָשָׂר בְּאָב מִשְּׁנַת עֶשֶׂר לֹא עָלְתָה לוֹ שְׁנַת עֶשֶׂר אֶלָּא הֲרֵי הוּא עָרְלָה שְׁנַת י\"א וְי\"ב וְי\"ג כֻּלָּהּ. וַהֲרֵי הוּא נֶטַע רְבָעִי מֵרֹאשׁ הַשָּׁנָה שֶׁל שְׁנַת י\"ד עַד סוֹפָהּ:","נָטַע הַנְּטִיעָה מֵרֹאשׁ חֹדֶשׁ תִּשְׁרֵי עַד ט\"ו בִּשְׁבָט מוֹנֶה לָהּ שָׁלֹשׁ שָׁנִים מִיּוֹם לְיוֹם לְעָרְלָה וּמִיּוֹם לְיוֹם לִרְבָעִי. וְרָאִיתִי לַגְּאוֹנִים דְּבָרִים בְּחֶשְׁבּוֹן עָרְלָה וּרְבָעִי אֵין רָאוּי לְהַאֲרִיךְ וּלְהָשִׁיב עֲלֵיהֶן וּבְוַדַּאי טָעוּת סוֹפְרִים הֵם וְהָאֱמֶת כְּבָר בֵּאַרְנוּ דַּרְכָּהּ:","הֶעָלִין וְהַלּוּלָבִין וּמֵי גְּפָנִים וְהַסְּמָדַר מֻתָּרִין בְּעָרְלָה וּבִרְבָעִי. וְהָעֲנָבִים שֶׁשְּׂרָפָם הַקָּדִים וְהִפְסִידָן וְהַחַרְצַנִּים וְהַזַּגִּין וְהַתֶּמֶד שֶׁלָּהֶן וּקְלִפֵּי רִמּוֹן וְהַנֵּץ שֶׁלּוֹ וּקְלִפֵּי אֱגוֹזִים וְהַגַּרְעִינִים אֲסוּרִין בְּעָרְלָה וּמֻתָּרִין בִּרְבָעִי. וְהַנּוֹבְלוֹת כֻּלָּן אֲסוּרוֹת:"],"Mishneh Torah, Shofar, Sukkah and Lulav 3":["כַּמָּה תְּקִיעוֹת חַיָּב אָדָם לִשְׁמֹעַ בְּרֹאשׁ הַשָּׁנָה. תֵּשַׁע תְּקִיעוֹת. לְפִי שֶׁנֶּאֱמַר תְּרוּעָה בְּיוֹבֵל וּבְרֹאשׁ הַשָּׁנָה שָׁלֹשׁ פְּעָמִים. וְכָל תְּרוּעָה פְּשׁוּטָה לְפָנֶיהָ וּפְשׁוּטָה לְאַחֲרֶיהָ. וּמִפִּי הַשְּׁמוּעָה לָמְדוּ שֶׁכָּל תְּרוּעוֹת שֶׁל חֹדֶשׁ הַשְּׁבִיעִי אֶחָד הֵן. בֵּין בְּרֹאשׁ הַשָּׁנָה בֵּין בְּיוֹם הַכִּפּוּרִים שֶׁל יוֹבֵל תֵּשַׁע תְּקִיעוֹת תּוֹקְעִין בְּכָל אֶחָד מִשְּׁנֵיהֶן. תְּקִיעָה וּתְרוּעָה וּתְקִיעָה. תְּקִיעָה וּתְרוּעָה וּתְקִיעָה. תְּקִיעָה וּתְרוּעָה וּתְקִיעָה:","תְּרוּעָה זוֹ הָאֲמוּרָה בַּתּוֹרָה נִסְתַּפֵּק לָנוּ בָּהּ סָפֵק לְפִי אֹרֶךְ הַשָּׁנִים וְרֹב הַגָּלוּת וְאֵין אָנוּ יוֹדְעִין הֵיאַךְ הִיא. אִם הִיא הַיְלָלָה שֶׁמְּיַלְּלִין הַנָּשִׁים בֵּינֵיהֶן בְּעֵת שֶׁמְּיַבְּבִין. אוֹ הָאֲנָחָה כְּדֶרֶךְ שֶׁיֵּאָנַח הָאָדָם פַּעַם אַחַר פַּעַם כְּשֶׁיִּדְאַג לִבּוֹ מִדָּבָר גָּדוֹל. אוֹ שְׁנֵיהֶם כְּאֶחָד הָאֲנָחָה וְהַיְלָלָה שֶׁדַּרְכָּהּ לָבוֹא אַחֲרֶיהָ הֵן הַנִּקְרָאִין תְּרוּעָה. שֶׁכָּךְ דֶּרֶךְ הַדּוֹאֵג מִתְאַנֵּחַ תְּחִלָּה וְאַחַר כָּךְ מְיַלֵּל. לְכָךְ אָנוּ עוֹשִׂין הַכּל:","הַיְלָלָה הִיא שֶׁאָנוּ קוֹרְאִין תְּרוּעָה. וְהָאֲנָחָה זוֹ אַחַר זוֹ הִיא שֶׁאָנוּ קוֹרְאִין אוֹתָהּ שְׁלֹשָׁה שְׁבָרִים. נִמְצָא סֵדֶר הַתְּקִיעוֹת כָּךְ הוּא. מְבָרֵךְ וְתוֹקֵעַ תְּקִיעָה וְאַחֲרֶיהָ שְׁלֹשָׁה שְׁבָרִים וְאַחֲרֶיהָ תְּרוּעָה וְאַחֲרֶיהָ תְּקִיעָה. וְחוֹזֵר כְּסֵדֶר זֶה שָׁלֹשׁ פְּעָמִים. וְתוֹקֵעַ תְּקִיעָה וְאַחֲרֶיהָ שְׁלֹשָׁה שְׁבָרִים וְאַחֲרֶיהָ תְּקִיעָה וְחוֹזֵר כַּסֵּדֶר הַזֶּה שָׁלֹשׁ פְּעָמִים. וְתוֹקֵעַ תְּקִיעָה וְאַחֲרֶיהָ תְּרוּעָה וְאַחֲרֶיהָ תְּקִיעָה וְחוֹזֵר כְּסֵדֶר זֶה שָׁלֹשׁ פְּעָמִים. נִמְצָא מִנְיַן הַתְּקִיעוֹת שְׁלֹשִׁים כְּדֵי לְהִסְתַּלֵּק מִן הַסָּפֵק:","שִׁעוּר תְּרוּעָה כִּשְׁתֵּי תְּקִיעוֹת. שִׁעוּר שְׁלֹשָׁה שְׁבָרִים כִּתְרוּעָה. הֲרֵי שֶׁתָּקַע וְהֵרִיעַ וְתָקַע תְּקִיעָה אֲרֻכָּה וּמָשַׁךְ בָּהּ כִּשְׁתַּיִם בָּרִאשׁוֹנָה. אֵין אוֹמְרִין תֵּחָשֵׁב כִּשְׁתֵּי תְּקִיעוֹת וְיָרִיעַ אַחֲרֶיהָ וְיַחֲזֹר וְיִתְקַע. אֶלָּא אֲפִלּוּ מָשַׁךְ בָּהּ כָּל הַיּוֹם אֵינָהּ אֶלָּא תְּקִיעָה אַחַת וְחוֹזֵר וְתוֹקֵעַ וּמֵרִיעַ וְתוֹקֵעַ שָׁלֹשׁ פְּעָמִים:","שָׁמַע תְּקִיעָה אַחַת בְּשָׁעָה אַחַת וּשְׁנִיָּה בְּשָׁעָה שְׁנִיָּה אֲפִלּוּ שָׁהָה כָּל הַיּוֹם כֻּלּוֹ הֲרֵי אֵלּוּ מִצְטָרְפִין וְיָצָא יְדֵי חוֹבָתוֹ. וְהוּא שֶׁיִּשְׁמַע כָּל בָּבָא מֵהֶן עַל סִדְרָה. לֹא שֶׁיִּשְׁמַע תְּרוּעָה וְאַחֲרֶיהָ שְׁתֵּי תְּקִיעוֹת אוֹ שְׁתֵּי תְּקִיעוֹת וְאַחֲרֵיהֶן תְּרוּעָה וְכַיּוֹצֵא בָּזֶה:","שָׁמַע תֵּשַׁע תְּקִיעוֹת מִתִּשְׁעָה בְּנֵי אָדָם כְּאֶחָד לֹא יָצָא אֲפִלּוּ יְדֵי אַחַת. תְּקִיעָה מִזֶּה וּתְרוּעָה מִזֶּה וּתְקִיעָה מִשְּׁלִישִׁי בָּזֶה אַחַר זֶה יָצָא וַאֲפִלּוּ בְּסֵרוּגִין וַאֲפִלּוּ כָּל הַיּוֹם כֻּלּוֹ. וְאֵינוֹ יוֹצֵא יְדֵי חוֹבָתוֹ עַד שֶׁיִּשְׁמַע כָּל הַתֵּשַׁע תְּקִיעוֹת שֶׁכֻּלָּן מִצְוָה אַחַת הֵן לְפִיכָךְ מְעַכְּבוֹת זוֹ אֶת זוֹ:","הַצִּבּוּר חַיָּבִין לִשְׁמֹעַ הַתְּקִיעוֹת עַל סֵדֶר הַבְּרָכוֹת. כֵּיצַד. אוֹמֵר שְׁלִיחַ צִבּוּר אָבוֹת וּגְבוּרוֹת וּקְדֻשַּׁת הַשֵּׁם וּמַלְכֻיּוֹת וְתוֹקֵעַ שָׁלֹשׁ. וְאוֹמֵר זִכְרוֹנוֹת וְתוֹקֵעַ שָׁלֹשׁ. וְאוֹמֵר שׁוֹפָרוֹת וְתוֹקֵעַ שָׁלֹשׁ. וְאוֹמֵר עֲבוֹדָה וְהוֹדָיָה וּבִרְכַּת כֹּהֲנִים:","שָׁלֹשׁ בְּרָכוֹת אֶמְצָעִיּוֹת אֵלּוּ שֶׁל רֹאשׁ הַשָּׁנָה וְיוֹם הַכִּפּוּרִים שֶׁל יוֹבֵל שֶׁהֵן מַלְכֻיּוֹת וְזִכְרוֹנוֹת וְשׁוֹפָרוֹת מְעַכְּבוֹת זוֹ אֶת זוֹ. וְצָרִיךְ לוֹמַר בְּכָל בְּרָכָה מֵהֶן עֲשָׂרָה פְּסוּקִים מֵעֵין הַבְּרָכָה. שְׁלֹשָׁה פְּסוּקִים מִן הַתּוֹרָה. וּשְׁלֹשָׁה מִסֵּפֶר תְּהִלִּים. וּשְׁלֹשָׁה מִן הַנְּבִיאִים. וְאֶחָד מִן הַתּוֹרָה מַשְׁלִים בּוֹ. וְאִם הִשְׁלִים בְּנָבִיא יָצָא. וְאִם אָמַר פָּסוּק אֶחָד מִן הַתּוֹרָה וְאֶחָד מִן הַכְּתוּבִים וְאֶחָד מִן הַנְּבִיאִים יָצָא. וַאֲפִלּוּ אָמַר וּבְתוֹרָתְךָ ה' אֱלֹהֵינוּ כָּתוּב לֵאמֹר וְאָמַר פָּסוּק שֶׁל תּוֹרָה וְהִפְסִיק שׁוּב אֵינוֹ צָרִיךְ כְּלוּם:","אֵין מַזְכִּירִין זִכְרוֹנוֹת מַלְכֻיּוֹת וְשׁוֹפָרוֹת שֶׁל פֻּרְעָנוּת. זִכְרוֹנוֹת כְּגוֹן (תהילים עח לט) \"וַיִּזְכֹּר כִּי בָשָׂר הֵמָּה\" וְכוּ'. מַלְכֻיּוֹת כְּגוֹן (יחזקאל כ לג) \"בְּחֵמָה שְׁפוּכָה אֶמְלוֹךְ עֲלֵיכֶם\". שׁוֹפָרוֹת כְּגוֹן (הושע ה ח) \"תִּקְעוּ שׁוֹפָר בַּגִּבְעָה\" וְכוּ'. וְלֹא זִכְרוֹן יָחִיד אֲפִלּוּ לְטוֹבָה כְּגוֹן (תהילים קו ד) \"זָכְרֵנִי ה' בִּרְצוֹן עַמֶּךָ\". (נחמיה ה יט) (נחמיה יג לא) \"זָכְרָה לִּי אֱלֹהַי לְטוֹבָה\". וּפִקְדוֹנוֹת אֵינָן כְּזִכְרוֹנוֹת. כְּגוֹן (שמות ג טז) \"פָּקֹד פָּקַדְתִּי אֶתְכֶם\". וְיֵשׁ לוֹ לְהַזְכִּיר פֻּרְעָנוּת שֶׁל אֻמּוֹת עַכּוּ\"ם כְּגוֹן (תהילים צט א) \"ה' מָלָךְ יִרְגְּזוּ עַמִּים\". (תהילים קלז ז) \"זְכֹר ה' לִבְנֵי אֱדוֹם אֶת יוֹם יְרוּשָׁלָםִ\". (זכריה ט יד) \" וַה' אֱלֹהִים בַּשּׁוֹפָר יִתְקָע וְהָלַךְ בְּסַעֲרוֹת תֵּימָן\". (דברים ו ד) \"שְׁמַע יִשְׂרָאֵל ה' אֱלֹהֵינוּ ה' אֶחָד\". (דברים ד לה) \"אַתָּה הָרְאֵתָ לָדַעַת\" וְכוּ'. (דברים ד לט) \"וְיָדַעְתָּ הַיּוֹם וַהֲשֵׁבֹתָ אֶל לְבָבֶךָ\" וְכוּ'. כָּל פָּסוּק מֵאֵלּוּ מַלְכוּת הוּא עִנְיָנוֹ אַף עַל פִּי שֶׁאֵין בּוֹ זֵכֶר מַלְכוּת וַהֲרֵי הוּא כְּמוֹ (שמות טו יח) \"ה' יִמְלוֹךְ לְעוֹלָם וָעֶד\", (דברים לג ה) \"וַיְהִי בִישֻׁרוּן מֶלֶךְ\" וְכוּ':","הַמִּנְהָג הַפָּשׁוּט בְּסֵדֶר הַתְּקִיעוֹת שֶׁל רֹאשׁ הַשָּׁנָה בְּצִבּוּר כָּךְ הוּא. אַחַר שֶׁקּוֹרְאִין בַּתּוֹרָה וּמַחְזִירִין הַסֵּפֶר לִמְקוֹמוֹ יוֹשְׁבִין כָּל הָעָם וְאֶחָד עוֹמֵד וּמְבָרֵךְ בָּרוּךְ אַתָּה ה' אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לִשְׁמֹעַ קוֹל שׁוֹפָר וְכָל הָעָם עוֹנִין אָמֵן. וְחוֹזֵר וּמְבָרֵךְ שֶׁהֶחֱיָנוּ וְכָל הָעָם עוֹנִין אַחֲרָיו אָמֵן. וְתוֹקֵעַ שְׁלֹשִׁים תְּקִיעוֹת שֶׁאָמַרְנוּ מִפְּנֵי הַסָּפֵק עַל הַסֵּדֶר. וְאוֹמְרִים קַדִּישׁ וְעוֹמְדִין וּמִתְפַּלְּלִין תְּפִלַּת מוּסָף. וְאַחַר שֶׁגּוֹמֵר שְׁלִיחַ צִבּוּר בְּרָכָה רְבִיעִית שֶׁהִיא מַלְכֻיּוֹת תּוֹקֵעַ תְּקִיעָה שְׁלֹשָׁה שְׁבָרִים תְּרוּעָה תְּקִיעָה פַּעַם אַחַת. וּמְבָרֵךְ בְּרָכָה חֲמִישִׁית שֶׁהִיא זִכְרוֹנוֹת. וְאַחַר שֶׁגּוֹמְרָהּ תּוֹקֵעַ תְּקִיעָה שְׁלֹשָׁה שְׁבָרִים וּתְקִיעָה. וּמְבָרֵךְ בְּרָכָה שִׁשִּׁית שֶׁהִיא שׁוֹפָרוֹת. וְאַחַר שֶׁגּוֹמְרָהּ תּוֹקֵעַ תְּקִיעָה תְּרוּעָה וּתְקִיעָה פַּעַם אַחַת וְגוֹמֵר הַתְּפִלָּה:","זֶה שֶׁתּוֹקֵעַ כְּשֶׁהֵן יוֹשְׁבִין הוּא שֶׁתּוֹקֵעַ עַל סֵדֶר הַבְּרָכוֹת כְּשֶׁהֵן עוֹמְדִים. וְאֵינוֹ מְדַבֵּר בֵּין תְּקִיעוֹת שֶׁמְּיֻשָּׁב לִתְקִיעוֹת שֶׁמְּעֻמָּד. וְאִם סָח בֵּינֵיהֶן אַף עַל פִּי שֶׁעָבַר אֵינוֹ חוֹזֵר וּמְבָרֵךְ:","בְּדִין הָיָה שֶׁיִּתְקְעוּ עַל כָּל בְּרָכָה כָּל בָּבָא מֵהֶן שָׁלֹשׁ פְּעָמִים כְּדֶרֶךְ שֶׁתָּקְעוּ כְּשֶׁהֵן יוֹשְׁבִין אֶלָּא כֵּיוָן שֶׁיָּצְאוּ מִידֵי סָפֵק בַּתְּקִיעוֹת שֶׁמְּיֻשָּׁב אֵין מַטְרִיחִין עַל הַצִּבּוּר לַחֲזֹר בָּהֶן כֻּלָּן עַל סֵדֶר בְּרָכוֹת. אֶלָּא דַּי לָהֶן בָּבָא אַחַת עַל כָּל בְּרָכָה כְּדֵי שֶׁיִּשְׁמְעוּ תְּקִיעוֹת עַל סֵדֶר בְּרָכוֹת. וְכָל הַדְּבָרִים הָאֵלּוּ בְּצִבּוּר אֲבָל הַיָּחִיד בֵּין שֶׁשָּׁמַע עַל סֵדֶר בְּרָכוֹת בֵּין שֶׁלֹּא שָׁמַע עַל הַסֵּדֶר בֵּין מְעֻמָּד בֵּין מְיֻשָּׁב יָצָא וְאֵין בָּזֶה מִנְהָג:","הַתְּקִיעוֹת אֵינָן מְעַכְּבוֹת אֶת הַבְּרָכוֹת וְהַבְּרָכוֹת אֵינָן מְעַכְּבוֹת אֶת הַתְּקִיעוֹת. שְׁתֵּי עֲיָרוֹת בְּאַחַת יוֹדֵעַ בְּוַדַּאי שֶׁיֵּשׁ שָׁם מִי שֶׁיְּבָרֵךְ לָהֶן תֵּשַׁע בְּרָכוֹת וְאֵין שָׁם תּוֹקֵעַ. וּבַשְּׁנִיָּה סָפֵק יֵשׁ שָׁם תּוֹקֵעַ סָפֵק אֵין שָׁם תּוֹקֵעַ הוֹלֵךְ לַשְּׁנִיָּה. שֶׁהַתְּקִיעָה מִדִּבְרֵי תּוֹרָה וְהַבְּרָכוֹת מִדִּבְרֵי סוֹפְרִים:"],"Mishneh Torah, Slaves 7":["גֵּט שִׁחְרוּר צָרִיךְ שֶׁיִּהְיֶה עִנְיָנוֹ דָּבָר הַכּוֹרֵת בֵּינוֹ לְבֵין אֲדוֹנָיו וְלֹא יִשָּׁאֵר לָאָדוֹן בּוֹ זְכוּת. לְפִיכָךְ הַכּוֹתֵב לְעַבְדּוֹ עַצְמְךָ וְכָל נְכָסַי קְנוּיִין לְךָ חוּץ מִמָּקוֹם פְּלוֹנִי אוֹ חוּץ מִטַּלִּית פְּלוֹנִית אֵין זֶה כּוֹרֵת וְהַגֵּט בָּטֵל וּמִתּוֹךְ שֶׁאֵינוֹ גֵּט אֵין הָעֶבֶד מְשֻׁחְרָר וְלֹא קָנָה מִן הַנְּכָסִים כְּלוּם. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","עֶבֶד שֶׁהֵבִיא גֵּט וְכָתוּב בּוֹ עַצְמְךָ וּנְכָסַי קְנוּיִין לְךָ עַצְמוֹ קָנָה וַהֲרֵי הוּא בֶּן חוֹרִין אֲבָל הַנְּכָסִים לֹא קָנָה עַד שֶׁיִּתְקַיֵּם הַגֵּט בְּחוֹתְמָיו כִּשְׁאָר הַשְּׁטָרוֹת. וְכֵן אִם הָיָה כָּתוּב בּוֹ כָּל נְכָסַי קְנוּיִין לְךָ קָנָה עַצְמוֹ וְלֹא קָנָה הַנְּכָסִים עַד שֶׁיִּתְקַיֵּם הַגֵּט בְּחוֹתְמָיו שֶׁחוֹלְקִים הַדִּבּוּר וְאוֹמְרִים עַצְמוֹ קָנָה מִפְּנֵי שֶׁהוּא נֶאֱמָן לְהָבִיא גֵּט שִׁחְרוּרוֹ וְאֵינוֹ צָרִיךְ לְקַיְּמוֹ אֲבָל הַנְּכָסִים שֶׁאֵין אָדָם קוֹנֶה אוֹתָם אֶלָּא בִּרְאָיָה בְּרוּרָה לֹא יִקְנֶה אוֹתָם עַד שֶׁיִּתְקַיֵּם הַשְּׁטָר:","הַמְשַׁחְרֵר שְׁנֵי עֲבָדִים בִּשְׁטָר אֶחָד לֹא קָנוּ עַצְמָן אֶלָּא כּוֹתְבִין שְׁטָר לְכָל אֶחָד וְאֶחָד. לְפִיכָךְ הַכּוֹתֵב כָּל נְכָסָיו לִשְׁנֵי עֲבָדָיו בִּשְׁטָר אֶחָד אַף עַצְמָן לֹא קָנוּ. וְאִם כָּתַב בִּשְׁנֵי שְׁטָרוֹת קָנוּ וּמְשַׁחְרְרִין זֶה אֶת זֶה. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁכָּתַב בְּכָל שְׁטָר מִשְּׁנֵיהֶם כָּל נְכָסַי נְתוּנִים לִפְלוֹנִי וּפְלוֹנִי עַבְדִּי. אֲבָל אִם כָּתַב חֲצִי נְכָסַי לִפְלוֹנִי עַבְדִּי וַחֲצִי נְכָסַי לִפְלוֹנִי עַבְדִּי אַף בִּשְׁנֵי שְׁטָרוֹת לֹא קָנוּ כְּלוּם שֶׁהָעֶבֶד מִכְּלַל נְכָסִים וַהֲרֵי שִׁיֵּר בּוֹ חֶצְיוֹ וְאֵין זֶה שִׁחְרוּר וְכֵיוָן שֶׁלֹּא נִשְׁתַּחְרֵר לֹא קָנָה מִן הַנְּכָסִים כְּלוּם:","הַמְשַׁחְרֵר חֲצִי עַבְדּוֹ בִּשְׁטָר לֹא קָנָה הָעֶבֶד חֶצְיוֹ וַהֲרֵי הוּא עֶבֶד כְּשֶׁהָיָה. אֲבָל אִם שִׁחְרֵר חֶצְיוֹ בְּכֶסֶף כְּגוֹן שֶׁלָּקַח חֲצִי דָּמָיו עַל מְנָת לְשַׁחְרֵר חֶצְיוֹ קָנָה וְנִמְצָא חֶצְיוֹ עֶבֶד וְחֶצְיוֹ בֶּן חוֹרִין. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁשִּׁחְרֵר חֶצְיוֹ בִּשְׁטָר וְהִנִּיחַ חֶצְיוֹ. אֲבָל אִם שִׁחְרֵר חֶצְיוֹ וּמָכַר חֶצְיוֹ אוֹ שֶׁשִּׁחְרֵר חֶצְיוֹ וְנָתַן חֶצְיוֹ בְּמַתָּנָה הוֹאִיל וְיָצָא הָעֶבֶד כֻּלּוֹ מֵרְשׁוּתוֹ קָנָה הָעֶבֶד חֶצְיוֹ וַהֲרֵי זֶה חֶצְיוֹ עֶבֶד וְחֶצְיוֹ בֶּן חוֹרִין. וְכֵן עֶבֶד שֶׁל שְׁנֵי שֻׁתָּפִין וְשִׁחְרֵר אֶחָד מֵהֶן חֶלְקוֹ בֵּין בְּכֶסֶף בֵּין בִּשְׁטָר קָנָה הָעֶבֶד חֶצְיוֹ וַהֲרֵי הוּא חֶצְיוֹ עֶבֶד וְחֶצְיוֹ בֶּן חוֹרִין:","הַכּוֹתֵב לְשִׁפְחָתוֹ מְעֻבֶּרֶת הֲרֵי אַתְּ בַּת חוֹרִין וּוְלָדֵךְ עֶבֶד דְּבָרָיו קַיָּמִין. הֲרֵי אַתְּ שִׁפְחָה וּוְלָדֵךְ בֶּן חוֹרִין לֹא אָמַר וְלֹא כְּלוּם שֶׁזֶּה כְּמִי שֶׁמְּשַׁחְרֵר חֶצְיָהּ:","שִׁפְחָה חֲרוּפָה אִם רָצָה לְשַׁחְרֵר חֶצְיָהּ הַנִּשְׁאָר וְתֵעָשֶׂה אֵשֶׁת אִישׁ גְּמוּרָה הֲרֵי זֶה מְשַׁחְרֵר בֵּין בְּכֶסֶף בֵּין בִּשְׁטָר שֶׁאַף הַכֶּסֶף גּוֹמֵר שִׁחְרוּרָהּ:","מִי שֶׁחֶצְיוֹ עֶבֶד וְחֶצְיוֹ בֶּן חוֹרִין הוֹאִיל וְאֵינוֹ מֻתָּר לֹא בְּשִׁפְחָה וְלֹא בְּבַת חוֹרִין כּוֹפִין אֶת רַבּוֹ וְעוֹשֶׂה אוֹתוֹ בֶּן חוֹרִין וְכוֹתֵב שְׁטָר עָלָיו בַּחֲצִי דָּמָיו. בַּמֶּה דְּבָרִים אֲמוּרִים בְּעֶבֶד מִפְּנֵי שֶׁהָאִישׁ מְצֻוֶּה עַל פְּרִיָּה וּרְבִיָּה. אֲבָל הַשִּׁפְחָה תִּשָּׁאֵר כְּמוֹת שֶׁהִיא וְעוֹבֶדֶת אֶת רַבָּה יוֹם אֶחָד וְאֶת עַצְמָהּ יוֹם אֶחָד. וְאִם נָהֲגוּ בָּהּ הַחוֹטְאִים מִנְהַג הֶפְקֵר כּוֹפִין אֶת רַבָּה לְשַׁחְרֵר וְכוֹתֵב עָלֶיהָ שְׁטָר בַּחֲצִי דָּמֶיהָ:","מִי שֶׁחֶצְיוֹ עֶבֶד וְחֶצְיוֹ בֶּן חוֹרִין שֶׁעָמַד רַבּוֹ וְהִקְנָה חֶצְיוֹ לִבְנוֹ הַקָּטָן כְּדֵי שֶׁלֹּא יָכֹפוּ אוֹתוֹ בֵּית דִּין לְשַׁחְרְרוֹ מַעֲמִידִין בֵּית דִּין לַקָּטָן אַפּוֹטְרוֹפּוֹס וְכוֹתֵב לוֹ הָאַפּוֹטְרוֹפּוֹס גֵּט שִׁחְרוּר וְכוֹתֵב לוֹ שְׁטַר חוֹב בַּחֲצִי דָּמָיו. וְאִם נִצְטָרֵךְ הַקָּטָן בְּעֶבֶד וְיֵשׁ לוֹ גַּעְגּוּעִין עָלָיו מַפְלִיגִין אוֹתוֹ מִמֶּנּוּ בְּמָעוֹת שֶׁדַּעְתּוֹ שֶׁל קָטָן קָרוֹב אֵצֶל מָעוֹת:","שְׁכִיב מֵרַע שֶׁכָּתַב כָּל נְכָסָיו לְעַבְדּוֹ וְעָמַד חוֹזֵר בַּנְּכָסִים וְאֵינוֹ חוֹזֵר בָּעֶבֶד שֶׁהֲרֵי יָצָא עָלָיו שֵׁם בֶּן חוֹרִין:"],"Mishneh Torah, Tefillin, Mezuzah and the Torah Scroll 5":["כֵּיצַד כּוֹתְבִין אֶת הַמְּזוּזָה. כּוֹתְבִין שְׁתֵּי פָּרָשִׁיּוֹת (דברים ו ד) ״שְׁמַע״ (דברים יא יג) ״וְהָיָה אִם שָׁמֹעַ״ עַל דַּף אֶחָד בִּירִיעָה אַחַת וְעוֹשֶׂה לָהּ רֶוַח מִלְּמַטָּה וְרֶוַח מִלְּמַעְלָה כְּמוֹ חֲצִי צִפֹּרֶן. וְאִם כְּתָבָהּ בִּשְׁנַיִם אוֹ בִּשְׁלֹשָׁה דַּפִּין כְּשֵׁרָה. וּבִלְבַד שֶׁלֹּא יַעֲשֶׂנָּה כְּזָנָב אוֹ כְּמוֹ עִגּוּל אוֹ כְּקוּבָּה וְאִם עָשָׂה כְּאַחַת מֵאֵלֶּה פְּסוּלָה. כְּתָבָהּ שֶׁלֹּא עַל הַסֵּדֶר כְּגוֹן שֶׁהִקְדִּים פָּרָשָׁה לְפָרָשָׁה פְּסוּלָה. כְּתָבָהּ בִּשְׁנֵי עוֹרוֹת אַף עַל פִּי שֶׁתְּפָרָן פְּסוּלָה. סֵפֶר תּוֹרָה שֶׁבָּלָה וּתְפִלִּין שֶׁבָּלוּ אֵין עוֹשִׂין מֵהֶן מְזוּזָה. וְלֹא מִן הַגִּלְיוֹנִים שֶׁל סֵפֶר תּוֹרָה אֵין כּוֹתְבִין עָלָיו מְזוּזָה לְפִי שֶׁאֵין מוֹרִידִין מִקְּדֻשָּׁה חֲמוּרָה לִקְדֻשָּׁה קַלָּה:","וּמִצְוָה לַעֲשׂוֹת רֶוַח שֶׁבֵּין פָּרָשַׁת (דברים ו ד) ״שְׁמַע״ לִ (דברים יא יג) ״וְהָיָה אִם שָׁמֹעַ״ פָּרָשָׁה סְתוּמָה. וְאִם עָשָׂה אוֹתָהּ פְּתוּחָה כְּשֵׁרָה לְפִי שֶׁאֵינָהּ סְמוּכָה לָהּ מִן הַתּוֹרָה. וְצָרִיךְ לְהִזָּהֵר בְּתָגִין שֶׁבָּהּ. וְאֵלּוּ הֵן הַתָּגִין שֶׁעוֹשִׂין בַּמְּזוּזָה:","פָּרָשָׁה רִאשׁוֹנָה יֵשׁ בָּהּ שֶׁבַע אוֹתִיּוֹת עַל כָּל אוֹת מֵהֶן שְׁלֹשָׁה זַיִנִּי״ן. וְאֵלּוּ הֵן. שִׁי״ן עַיִ״ן שֶׁל (דברים ו ד) ״שְׁמַע״ וְנוּ״ן דְּ(דברים ו ה) ״נַפְשְׁךָ״ וּתְרֵי זַיִנִּי״ן שֶׁל מְזוּזֹת וּתְרֵי טֵיתִי״ן שֶׁל (דברים ו ח) ״טֹטָפֹת״. וּפָרָשָׁה שְׁנִיָּה יֵשׁ בָּהּ שֵׁשׁ אוֹתִיּוֹת עַל כָּל אוֹת מֵהֶן שְׁלֹשָׁה זַיִנִּי״ן. וְאֵלּוּ הֵן. גִּימֶ״ל שֶׁל (דברים יא יד) ״דְגָנֶךָ״ וּתְרֵי זַיִנִּי״ן שֶׁל (דברים ו ט) ״מְזוּזוֹת״ וּתְרֵי טֵיתִי״ן שֶׁל טֹטָפוֹת וְצַדִּי״ק שֶׁל (דברים יא כא) ״הָאָרֶץ״. וְאִם לֹא עָשָׂה תָּגִין אוֹ שֶׁהוֹסִיף בָּהֶן אוֹ גָּרַע מֵהֶן לֹא פָּסַל. וְאִם כְּתָבָהּ שֶׁלֹּא בְּשִׂרְטוּט אוֹ שֶׁלֹּא דִּקְדֵּק בְּמָלֵא וְחָסֵר אוֹ שֶׁהוֹסִיף מִבִּפְנִים אֲפִלּוּ אוֹת אַחַת הֲרֵי זוֹ פְּסוּלָה:","מִנְהָג פָּשׁוּט שֶׁכּוֹתְבִים עַל הַמְּזוּזָה מִבַּחוּץ כְּנֶגֶד הָרֶוַח שֶׁבֵּין פָּרָשָׁה לְפָרָשָׁה שַׁדַּי וְאֵין בָּזֶה הֶפְסֵד לְפִי שֶׁהוּא מִבַּחוּץ. אֲבָל אֵלּוּ שֶׁכּוֹתְבִין מִבִּפְנִים שְׁמוֹת הַמַּלְאָכִים אוֹ שֵׁמוֹת קְדוֹשִׁים אוֹ פָּסוּק אוֹ חוֹתָמוֹת הֲרֵי הֵן בִּכְלַל מִי שֶׁאֵין לָהֶם חֵלֶק לָעוֹלָם הַבָּא. שֶׁאֵלּוּ הַטִּפְּשִׁים לֹא דַּי לָהֶם שֶׁבִּטְּלוּ הַמִּצְוָה אֶלָּא שֶׁעָשׂוּ מִצְוָה גְּדוֹלָה שֶׁהִיא יִחוּד הַשֵּׁם שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וְאַהֲבָתוֹ וַעֲבוֹדָתוֹ כְּאִלּוּ הוּא קָמֵעַ שֶׁל הֲנָיַת עַצְמָן כְּמוֹ שֶׁעָלָה עַל לִבָּם הַסָּכָל שֶׁזֶּהוּ דָּבָר הַמְהַנֶּה בְּהַבְלֵי הָעוֹלָם:","וּמִצְוָה לִכְתֹּב (דברים יא כא) ״עַל הָאָרֶץ״ בְּשִׁיטָה אַחֲרוֹנָה בֵּין בְּרֹאשׁ בֵּין (בְּאֶמְצַע) הַשִּׁיטָה. וְנָהֲגוּ כָּל הַסּוֹפְרִים לִכְתֹּב אוֹתָהּ בִּשְׁתַּיִם וְעֶשְׂרִים שִׁיטוֹת וְעַל הָאָרֶץ בְּרֹאשׁ שִׁיטָה אַחֲרוֹנָה. וְאֵלּוּ הֵן הָאוֹתִיּוֹת שֶׁבְּרֹאשׁ כָּל שִׁיטָה וְשִׁיטָה עַל הַסֵּדֶר. שְׁמַע. ה׳‎. הַדְּבָרִים. לְבָנֶיךָ. וּבְשָׁכְבְּךָ. בֵּין. וְהָיָה. מְצַוֶּה. בְּכָל. יוֹרֶה. עֵשֶׂב. פֶּן. וְהִשְׁתַּחֲוִיתֶם. הַשָּׁמַיִם. וַאֲבַדְתֶּם. וְשַׂמְתֶּם. אֹתָם. אֹתָם. בַּדֶּרֶךְ. וּבִשְׁעָרֶיךָ. אֲשֶׁר. עַל הָאָרֶץ:","כְּשֶׁכּוֹפְלִין אוֹתָהּ גּוֹלְלִין אוֹתָהּ מִסּוֹף הַשִּׁיטָה לִתְחִלָּתָהּ עַד שֶׁתִּמְצָא כְּשֶׁיִּפְתַּח הַקּוֹרֵא לִקְרוֹת יִקְרָא מֵרֹאשׁ הַשִּׁיטָה לְסוֹפָהּ. וְאַחַר שֶׁגּוֹלְלָהּ מַנִּיחָהּ בִּשְׁפוֹפֶרֶת שֶׁל קָנֶה אוֹ שֶׁל עֵץ אוֹ שֶׁל כָּל דָּבָר וּמְחַבֵּר אוֹתָהּ אֶל מְזוּזַת הַפֶּתַח בְּמַסְמֵר אוֹ חוֹפֵר בִּמְזוּזַת הַפֶּתַח וּמַכְנִיס בָּהּ הַמְּזוּזָה:","וְקֹדֶם שֶׁיִּקְבָּעֶנָּה בִּמְזוּזַת הַפֶּתַח מְבָרֵךְ תְּחִלָּה. בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ מֶלֶךְ הָעוֹלָם אֲשֶׁר קִדְּשָׁנוּ בְּמִצְוֹתָיו וְצִוָּנוּ לִקְבֹּעַ מְזוּזָה. וְאֵינוֹ מְבָרֵךְ בִּשְׁעַת כְּתִיבָתָהּ שֶׁקְּבִיעָתָהּ זוֹ הִיא הַמִּצְוָה:","תְּלָאָהּ בְּמַקֵּל פְּסוּלָה שֶׁאֵין זוֹ קְבוּעָה. הִנִּיחָהּ אַחֲרֵי הַדֶּלֶת לֹא עָשָׂה כְּלוּם. חָפַר בִּמְזוּזַת הַפֶּתַח וְהִכְנִיס הַמְּזוּזָה כְּמוֹ נֶגֶר וְהִיא כִּבְרִיחַ הַקְּרָשִׁים בַּטַּבָּעוֹת פְּסוּלָה. הֶעֱמִיק לָהּ טֶפַח פְּסוּלָה. חָתַךְ קָנֶה וְהִכְנִיס בּוֹ מְזוּזָה וְאַחַר כָּךְ חִבֵּר הַקָּנֶה אֶל קָנִים אֲחֵרִים וְהֶעֱמִיד מִן הַכּל מְזוּזַת הַפֶּתַח פְּסוּלָה מִפְּנֵי שֶׁקָּדְמָה קְבִיעַת הַמְּזוּזָה לַעֲשִׂיַּת מְזוּזַת הַפֶּתַח:","מְזוּזַת הַיָּחִיד נִבְדֶּקֶת פַּעֲמַיִם בְּשָׁבוּעַ. וּמְזוּזַת רַבִּים פַּעֲמַיִם בְּיוֹבֵל. שֶׁמָּא נִקְרְעָה מִמֶּנָּה אוֹת אַחַת אוֹ נִמְחֲקָה מִפְּנֵי שֶׁהִיא קְבוּעָה בַּכְּתָלִים מַרְקֶבֶת:","הַכּל חַיָּבִין בִּמְזוּזָה אֲפִלּוּ נָשִׁים וַעֲבָדִים. וּמְחַנְּכִים אֶת הַקְּטַנִּים לַעֲשׂוֹת מְזוּזָה לְבָתֵּיהֶם. הַשּׂוֹכֵר בַּיִת בְּחוּצָה לָאָרֶץ וְהַדָּר בְּפֻנְדָּק בְּאֶרֶץ יִשְׂרָאֵל פָּטוּר מִן הַמְּזוּזָה שְׁלֹשִׁים יוֹם. אֲבָל הַשּׂוֹכֵר בַּיִת בְּאֶרֶץ יִשְׂרָאֵל חַיָּב בִּמְזוּזָה מִיָּד:","הַמַּשְׂכִּיר בַּיִת לַחֲבֵרוֹ עַל הַשּׂוֹכֵר לְהָבִיא מְזוּזָה וְלִקְבֹּעַ אוֹתָהּ אֲפִלּוּ הָיָה נוֹתֵן שָׂכָר עַל קְבִיעָתָהּ. מִפְּנֵי שֶׁהַמְּזוּזָה חוֹבַת הַדָּר הִיא וְאֵינָהּ חוֹבַת הַבַּיִת. וּכְשֶׁהוּא יוֹצֵא לֹא יִטְּלֶנָּה בְּיָדוֹ וְיֵצֵא. וְאִם הָיָה הַבַּיִת שֶׁל כּוּתִי הֲרֵי זֶה נוֹטְלָהּ כְּשֶׁיֵּצֵא:"],"Mishneh Torah, Testimony 16":["רְאוּבֵן שֶׁגָּזַל שָׂדֶה אוֹ טַלִּית מִשִּׁמְעוֹן וּבָא יְהוּדָה וְעִרְעֵר עַל רְאוּבֵן וְאָמַר שָׂדֶה זוֹ אוֹ טַלִּית זוֹ שֶׁלִּי הִיא. אֵין שִׁמְעוֹן יָכוֹל לְהָעִיד לִרְאוּבֵן שֶׁאֵין זוֹ הַשָּׂדֶה שֶׁל יְהוּדָה וְלֹא זוֹ הַטַּלִּית שֶׁל יְהוּדָה. שֶׁהֲרֵי שִׁמְעוֹן רוֹצֶה לְהַעֲמִיד שָׂדֶה זוֹ אוֹ טַלִּית זוֹ בְּיַד רְאוּבֵן שֶׁהוּא גְּזָלָהּ מִמֶּנּוּ כְּדֵי שֶׁיַּחְזְרוּ לוֹ מִיַּד הַגַּזְלָן. שֶׁהֲרֵי אֶפְשָׁר שֶׁתִּהְיֶה הָרְאָיָה שֶׁל שִׁמְעוֹן שֶׁמּוֹצִיא בָּהּ מִיַּד רְאוּבֵן אֶפְשָׁר שֶׁאֵינוֹ יָכוֹל לְהוֹצִיא בָּהּ מִיַּד יְהוּדָה. וְכֵן אִם מָכַר רְאוּבֵן הַשָּׂדֶה הַגְּזוּלָה אוֹ הוֹרִישָׁהּ לְלֵוִי וּבָא יְהוּדָה לְעַרְעֵר עַל לֵוִי. אֵין שִׁמְעוֹן מֵעִיד שֶׁאֵינָהּ שֶׁל יְהוּדָה שֶׁמָּא נַחַת רוּחַ יֵשׁ לוֹ לְהוֹצִיאָהּ מִיַּד לֵוִי:","מָכַר הַטַּלִּית הַגְּזוּלָה לְלֵוִי וּבָא יְהוּדָה לְעַרְעֵר. אִם מֵת רְאוּבֵן שִׁמְעוֹן מֵעִיד עָלֶיהָ שֶׁאֵינָהּ שֶׁל יְהוּדָה שֶׁהֲרֵי אֵין טַלִּית זוֹ חוֹזֶרֶת לְשִׁמְעוֹן לְעוֹלָם שֶׁכְּבָר קְנָאָהּ הַלּוֹקֵחַ בְּיֵאוּשׁ וְשִׁנּוּי רְשׁוּת וּכְבָר מֵת רְאוּבֵן הַגַּזְלָן וְאֵין לוֹ מִמִּי יִטּל דָּמֶיהָ. אֲבָל אִם עֲדַיִן רְאוּבֵן קַיָּם אֵין שִׁמְעוֹן מֵעִיד אַף עַל הַטַּלִּית. שֶׁהֲנָאָה הִיא לוֹ שֶׁלֹּא תַּעֲמֹד בְּיַד יְהוּדָה כְּדֵי שֶׁיָּבִיא רְאָיָה שֶׁרְאוּבֵן גְּזָלָהּ וִישַׁלֵּם דָּמֶיהָ. וְכֵן אִם הָיְתָה הַטַּלִּית בְּיַד יוֹרְשֵׁי רְאוּבֵן אֵין שִׁמְעוֹן מֵעִיד עָלֶיהָ מִפְּנֵי שֶׁסּוֹפָהּ שֶׁאִם תַּעֲמֹד בְּיַד הַיּוֹרֵשׁ לַחְזֹר לוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","רְאוּבֵן שֶׁמָּכַר שָׂדֶה לְשִׁמְעוֹן שֶׁלֹּא בְּאַחֲרָיוּת וּבָא יְהוּדָה לְעַרְעֵר עַל שִׁמְעוֹן וּלְהוֹצִיאָהּ מִתַּחַת יָדוֹ. אֵין רְאוּבֵן מֵעִיד לוֹ עָלֶיהָ. אַף עַל פִּי שֶׁאֵין עָלֶיהָ אַחֲרָיוּת הֲרֵי הוּא רוֹצֶה שֶׁתַּעֲמֹד בְּיַד שִׁמְעוֹן כְּדֵי שֶׁיָּבוֹא בַּעַל חוֹב שֶׁל רְאוּבֵן וְיִטְרְפֶנָּה בְּחוֹבוֹ וְלֹא יִהְיֶה לוֶֹה רָשָׁע וְלֹא יְשַׁלֵּם:","רְאוּבֵן שֶׁמָּכַר פָּרָה אוֹ טַלִּית לְשִׁמְעוֹן וּבָא יְהוּדָה לְעַרְעֵר וּלְהוֹצִיא מִיַּד שִׁמְעוֹן. רְאוּבֵן מֵעִיד לוֹ עָלֶיהָ שֶׁהִיא שֶׁל שִׁמְעוֹן שֶׁאֲפִלּוּ עָמְדָה בְּיַד שִׁמְעוֹן אֵין בַּעַל חוֹבוֹ שֶׁל רְאוּבֵן טוֹרֵף מִן הַמִּטַּלְטְלִין וַאֲפִלּוּ הָיוּ אַפּוֹתֵיקֵי. בַּמֶּה דְּבָרִים אֲמוּרִים כְּשֶׁהָיָה שִׁמְעוֹן מוֹדֶה שֶׁזּוֹ הַפָּרָה וְהַטַּלִּית הֵם שֶׁל רְאוּבֵן הַמּוֹכֵר בְּוַדַּאי וְהוּא יוֹדֵעַ שֶׁבֶּאֱמֶת הֵן שֶׁלּוֹ. אֲבָל אִם לֹא הוֹדָה שִׁמְעוֹן אֵין רְאוּבֵן מֵעִיד לְאַבֵּד זְכוּת יְהוּדָה. שֶׁאִם תֵּצֵא מִתַּחַת יְדֵי שִׁמְעוֹן יַחְזֹר שִׁמְעוֹן וְיִתְבַּע דָּמִים וְיֹאמַר לוֹ מָכַרְתָּ לִי דָּבָר שֶׁאֵינוֹ שֶׁלְּךָ שֶׁהֲרֵי בָּאוּ עֵדִים וְאָמְרוּ שֶׁהֵן שֶׁל יְהוּדָה. בַּמֶּה דְּבָרִים אֲמוּרִים שֶׁיָּעִיד רְאוּבֵן לְאַבֵּד זְכוּת יְהוּדָה וְיַעֲמִיד הַמִּטַּלְטְלִין בְּיַד שִׁמְעוֹן כְּשֶׁבָּאוּ עֵדִים וְהֵעִידוּ שֶׁהֵם יוֹדְעִים שֶׁרְאוּבֵן זֶה לֹא הָיְתָה לוֹ קַרְקַע מֵעוֹלָם. אֲבָל אִם לֹא בָּאוּ עֵדִים לְכָךְ אַף עַל הַפָּרָה וְהַטַּלִּית אֵינוֹ מֵעִיד. וְלָמָּה אֵינוֹ מֵעִיד עֲלֵיהֶן. שֶׁמָּא הִקְנָה אוֹתָם לְבַעַל חוֹבוֹ אַגַּב קַרְקַע וְכָתַב דְּאִיקְנֵי וְהִקְנָה לוֹ מִטַּלְטְלִין אַגַּב קַרְקַע שֶׁנִּמְצָא בַּעַל חוֹבוֹ טוֹרֵף אַף הַפָּרָה וְהַטַּלִּית. לְפִיכָךְ לֹא יָעִיד עֲלֵיהֶן שֶׁהֲרֵי רוֹצֶה לְהַעֲמִידָן בְּיַד שִׁמְעוֹן כְּדֵי שֶׁיָּבוֹא בַּעַל חוֹבוֹ וְיִטְרְפֵם. וְכֵן כָּל כַּיּוֹצֵא בִּדְבָרִים אֵלּוּ. וּדְבָרִים אֵלּוּ אֵינָן תְּלוּיִין אֶלָּא בְּדַעַת הַדַּיָּן וְעֹצֶם בִּינָתוֹ שֶׁיָּבִין עִקַּר הַמִּשְׁפָּטִים וְיֵדַע דָּבָר הַגּוֹרֵם לְדָבָר אַחֵר וְיַעֲמִיק לִרְאוֹת. אִם יִמָּצֵא שֶׁיֵּשׁ לְזֶה הָעֵד צַד הֲנָאָה בְּעֵדוּת זוֹ אֲפִלּוּ בְּדֶרֶךְ רְחוֹקָה וְנִפְלָאָה הֲרֵי זֶה לֹא יָעִיד בָּהּ. וּכְדֶרֶךְ שֶׁלֹּא יָעִיד בְּדָבָר זֶה שֶׁמָּא נוֹגֵעַ בְּעֵדוּתוֹ הוּא כָּךְ לֹא יָדוּן בְּאוֹתוֹ דָּבָר. וְכֵן שְׁאָר מִינֵי פְּסוּלִין כְּשֵׁם שֶׁפּוֹסְלִין בְּעֵדִים כָּךְ פּוֹסְלִין בְּדַיָּנִים:","וּלְפִיכָךְ אֵין סוֹמְכִין בְּסַנְהֶדְרִין שְׁנַיִם הַקְּרוֹבִים זֶה לָזֶה בֵּין בְּסַנְהֶדְרִי קְטַנָּה בֵּין בְּסַנְהֶדְרִי גְּדוֹלָה. אֲבָל אֵלּוּ שֶׁמּוֹסִיפִין עַד שִׁבְעָה לְעַבֵּר הַשָּׁנָה כְּמוֹ שֶׁבֵּאַרְנוּ בְּהִלְכוֹת קִדּוּשׁ הַחֹדֶשׁ יֵרָאֶה לִי שֶׁאִם הָיָה בָּהֶן קְרוֹבִים אֵין בְּכָךְ כְּלוּם:","כָּל הַכָּשֵׁר לָדוּן כָּשֵׁר לְהָעִיד. וְיֵשׁ כָּשֵׁר לְהָעִיד וְאֵינוֹ כָּשֵׁר לָדוּן. הָאוֹהֵב. וְהַשּׂוֹנֵא. וְהַגֵּר. וְהַמְשֻׁחְרָר. וְכֵן הַזָּקֵן. וְהַסָּרִיס. וְהַמַּמְזֵר. וְסוּמָא בְּאַחַת מֵעֵינָיו. כְּשֵׁרִין לְהָעִיד וְאֵינָן כְּשֵׁרִים לָדוּן דִּינֵי נְפָשׁוֹת כְּמוֹ שֶׁבֵּאַרְנוּ:"],"Mishneh Torah, Testimony 7":["מֵעִיד קָרוֹב עַל כְּתַב קְרוֹבוֹ. כֵּיצַד. שְׁטָר שֶׁעֵדָיו רְאוּבֵן וְשִׁמְעוֹן וּמֵתוּ אוֹ שֶׁהָלְכוּ לִמְדִינַת הַיָּם וּבָא בְּנוֹ שֶׁל רְאוּבֵן וְאָמַר זֶה כְּתַב יָדוֹ שֶׁל אָבִי וּבָא בְּנוֹ שֶׁל שִׁמְעוֹן וְאָמַר זֶה כְּתַב יָדוֹ שֶׁל אָבִי הֲרֵי אֵלּוּ כִּשְׁנֵי עֵדִים כְּשֵׁרִים שֶׁאֵינָן קְרוֹבִים וְאִם יִצְטָרֵף עִמָּהֶם שְׁלִישִׁי וְהֵעִיד עַל כְּתַב יָדָן שֶׁל שְׁנֵיהֶם הֲרֵי נִתְקַיֵּם הַשְּׁטָר:","וְאֵלּוּ מִדְּבָרִים שֶׁנֶּאֱמָנִים הַגְּדוֹלִים לְהָעִיד בְּגָדְלָם מַה שֶּׁרָאוּ בְּקָטְנָם. נֶאֱמָן אָדָם לוֹמַר כְּשֶׁהוּא גָּדוֹל זֶהוּ כְּתַב יָדוֹ שֶׁל אָבִי זֶהוּ כְּתַב יָדוֹ שֶׁל רַבִּי זֶהוּ כְּתַב יָדוֹ שֶׁל אָחִי שֶׁהָיִיתִי מַכִּיר בִּכְתַב יָדָם כְּשֶׁהָיִיתִי קָטָן. וְהוּא שֶׁיִּצְטָרֵף עִמּוֹ אַחֵר שֶׁמַּכִּיר כְּתַב יָדָן כְּשֶׁהוּא גָּדוֹל:","שְׁטָר שֶׁעֵדָיו רְאוּבֵן וְשִׁמְעוֹן וּבָאוּ שְׁנַיִם וְהֵעִידוּ שֶׁזֶּה כְּתַב יָדוֹ שֶׁל רְאוּבֵן וְזֶה כְּתַב יָדוֹ שֶׁל שִׁמְעוֹן נִתְקַיֵּם הַשְּׁטָר. אֲבָל אִם הֵעִיד זֶה עַל כְּתַב יָדוֹ [שֶׁל] רְאוּבֵן וְהַשֵּׁנִי הֵעִיד עַל כְּתַב יָדוֹ [שֶׁל] שִׁמְעוֹן לֹא נִתְקַיֵּם הַשְּׁטָר לְפִי שֶׁצָּרִיךְ שְׁנֵי עֵדִים עַל כְּתַב [כָּל] יַד אֶחָד מִשְּׁנֵיהֶם. וְאִם יֵשׁ שְׁלִישִׁי מֵעִיד עַל כְּתַב רְאוּבֵן וְשִׁמְעוֹן כְּאֶחָד נִתְקַיֵּם:","אָמַר הָרִאשׁוֹן זֶה כְּתַב יָדִי וְהֵעִיד הוּא וְאַחֵר עַל כְּתַב יְדֵי הַשֵּׁנִי לֹא נִתְקַיֵּם לְפִי שֶׁנִּמְצָא שְׁלֹשֶׁת רִבְעֵי הַמָּמוֹן שֶׁבַּשְּׁטָר תָּלוּי בְּעֵדוּת הָאֶחָד. וְכֵן אִם הֵעִיד אָחִיו אוֹ בְּנוֹ שֶׁל רִאשׁוֹן עִם אַחֵר עַל כְּתַב יְדֵי הַשֵּׁנִי לֹא נִתְקַיֵּם שֶׁהֲרֵי שְׁלֹשֶׁת רִבְעֵי הַמָּמוֹן תָּלוּי בְּעֵדוּת הַקְּרוֹבִים:","שְׁנַיִם שֶׁחֲתוּמִין עַל הַשְּׁטָר וּמֵת אֶחָד מֵהֶן צָרִיךְ שְׁנֵי עֵדִים לְהָעִיד עַל כְּתַב יָדוֹ שֶׁל מֵת וְאִם לֹא נִמְצָא אֶלָּא עֵד אֶחָד עִם זֶה הָעֵד הַחַי כּוֹתֵב חֲתִימַת יָדוֹ בִּפְנֵי עֵדִים אֲפִלּוּ עַל הַחֶרֶס וּמַשְׁלִיכוֹ בְּבֵית דִּין עַד שֶׁתֻּחְזַק כְּתַב יָדוֹ בְּבֵית דִּין וְלֹא יִהְיֶה צָרִיךְ לוֹמַר שֶׁזֶּה כְּתַב יָדוֹ וְיָעִיד הוּא וְאַחֵר עַל כְּתַב יְדֵי הַמֵּת וְיִתְקַיֵּם כְּתַב יָדוֹ שֶׁלֹּא בְּפָנָיו:","שְׁלֹשָׁה שֶׁיָּשְׁבוּ לְקַיֵּם אֶת הַשְּׁטָר שְׁנַיִם מֵהֶן מַכִּירִין חֲתִימַת יְדֵי עֵדִים וְאֶחָד אֵינוֹ מַכִּיר. עַד שֶׁלֹּא חָתְמוּ מְעִידִין בְּפָנָיו וְחוֹתֵם. שֶׁהָעֵדִים נַעֲשִׂים דַּיָּנִים בְּדָבָר שֶׁהוּא מִדִּבְרֵיהֶם כְּמוֹ שֶׁבֵּאַרְנוּ. אֲבָל אַחַר שֶׁחָתְמוּ אֵין מְעִידִין בְּפָנָיו וְחוֹתֵם [שֶׁהֲרֵי בְּעֵת שֶׁחָתְמוּ לֹא הָיוּ מַכִּירִין אֶלָּא הַשְּׁנַיִם] וְאֵין מְקַיְּמִין אֶלָּא עַד שֶׁיִּהְיוּ שְׁלָשְׁתָּן מַכִּירִין אוֹ יָעִידוּ הָעֵדִים עַל הַכְּתָב בִּפְנֵי כָּל אֶחָד וְאֶחָד:","שְׁנַיִם שֶׁהָיוּ חֲתוּמִין עַל הַשְּׁטָר וּמֵתוּ וּבָאוּ שְׁנַיִם וְאָמְרוּ כְּתַב יָדָן הוּא זֶה אֲבָל אֲנוּסִים הָיוּ קְטַנִּים הָיוּ פְּסוּלֵי עֵדוּת הָיוּ. אַף עַל פִּי שֶׁיֵּשׁ שָׁם עֵדִים אֲחֵרִים שֶׁזֶּה כְּתַב יָדָן אוֹ שֶׁהָיָה כְּתַב יָדָן יוֹצֵא מִשְּׁטָר אַחֵר שֶׁקָּרָא עָלָיו עַרְעָר וְהֻחְזַק בְּבֵית דִּין הֲרֵי זֶה לֹא נִתְקַיֵּם. אֶלָּא מְעִידִין הַשְּׁנַיִם שֶּׁבַּשְּׁטָר כְּנֶגֶד הַשְּׁנַיִם שֶׁהֵעִידוּ עֲלֵיהֶן שֶׁהֵן פְּסוּלִין וְאֵין גּוֹבִין בּוֹ כְּלוּם:"],"Mishneh Torah, The Order of Prayer 2":["נסח ברכות התפלה וסדורן","(א) בָּרוּךְ אַתָּה יְיָ׳‎ אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ אֱלֹהֵי אַבְרָהָם אֱלֹהֵי יִצְחָק וֵאלֹהֵי יַעֲקֹב הָאֵל הַגָּדוֹל הַגִּבּוֹר וְהַנּוֹרָא וְכוּ׳‎:","(ב) אַתָּה גִּבּוֹר לְעוֹלָם אֲדֹנָי מְחַיֵּה מֵתִים אַתָּה רַב לְהוֹשִׁיעַ (מוֹרִיד הַטָּל) (מַשִּׁיב הָרוּחַ וּמוֹרִיד הַגָּשֶׁם) מְכַלְכֵּל חַיִּים בְּחֶסֶד מְחַיֵּה מֵתִים בְּרַחֲמִים רַבִּים סוֹמֵךְ נוֹפְלִים וְכוּ׳‎:","(ג) אַתָּה קָדוֹשׁ וְשִׁמְךָ קָדוֹשׁ וּקְדוֹשִׁים בְּכָל יוֹם יְהַלְלוּךָ סֶלָה בָּרוּךְ אַתָּה יְיָ׳‎ הָאֵל הַקָּדוֹשׁ:","(ד) אַתָּה חוֹנֵן לְאָדָם דַּעַת וּמְלַמֵּד לֶאֱנוֹשׁ בִּינָה וְחָנֵּנוּ מֵאִתְּךָ דֵּעָה חָכְמָה וּבִינָה וְהַשְׂכֵּל בָּרוּךְ אַתָּה יְיָ׳‎ חוֹנֵן הַדָּעַת:","(ה) הֲשִׁיבֵנוּ אָבִינוּ לְתוֹרָתֶךָ וְדַבְּקֵנוּ בְּמִצְוֹתֶיךָ וְקָרְבֵנוּ מַלְכֵּנוּ לַעֲבוֹדָתֶךָ וְהַחֲזִירֵנוּ בִּתְשׁוּבָה שְׁלֵמָה לְפָנֶיךָ בָּרוּךְ אַתָּה יְיָ׳‎ הָרוֹצֶה בִּתְשׁוּבָה:","(ו) סְלַח לָנוּ אָבִינוּ כִּי חָטָאנוּ מְחל לָנוּ מַלְכֵּנוּ כִּי פָּשַׁעְנוּ לְךָ כִּי אֵל טוֹב וְסַלָּח אַתָּה בָּרוּךְ אַתָּה יְיָ׳‎ חַנּוּן הַמַּרְבֶּה לִסְלֹחַ:","(ז) רְאֵה נָא בְעָנְיֵנוּ וְרִיבָה רִיבֵנוּ וְדוּן דִּינֵנוּ וּמַהֵר לְגָאֳלֵנוּ כִּי אֵל מֶלֶךְ גּוֹאֵל חָזָק אַתָּה בָּרוּךְ אַתָּה יְיָ׳‎ גּוֹאֵל יִשְׂרָאֵל:","(ח) רְפָאֵנוּ יְיָ׳‎ אֱלֹהֵינוּ וְנֵרָפֵא הוֹשִׁיעֵנוּ וְנִוָּשֵׁעָה כִּי תְהִלָּתֵנוּ אָתָּה וְהַעֲלֵה רְפוּאָה שְׁלֵמָה לְכָל תַּחֲלוּאֵינוּ כִּי אֵל רוֹפֵא וְרַחֲמָן אָתָּה בָּרוּךְ אַתָּה יְיָ׳‎ רוֹפֵא חוֹלֵי עַמּוֹ יִשְׂרָאֵל:","(ט) בָּרְכֵנוּ יְיָ׳‎ אֱלֹהֵינוּ בְּכָל מַעֲשֵׂה יָדֵינוּ וּבָרֵךְ אֶת שְׁנוֹתֵינוּ וְתֵן (טַל וּמָטָר לִ) בְּרָכָה עַל כָּל פְּנֵי הָאֲדָמָה וְשַׂבַּע אֶת הָעוֹלָם מִבִּרְכוֹתֶיךָ וְרַוֵּה פְּנֵי תֵּבֵל בָּרוּךְ אַתָּה יְיָ׳‎ מְבָרֵךְ הַשָּׁנִים:","(י) תְּקַע בְּשׁוֹפָר גָּדוֹל לְחֵרוּתֵנוּ וְשָׂא נֵס לְקַבֵּץ אֶת כָּל גָּלֻיּוֹתֵינוּ מֵאַרְבַּע כַּנְפוֹת כָּל הָאָרֶץ לְאַרְצֵנוּ בָּרוּךְ אַתָּה יְיָ׳‎ מְקַבֵּץ נִדְּחֵי עַמּוֹ יִשְׂרָאֵל:","(יא) הָשִׁיבָה שׁוֹפְטֵינוּ כְּבָרִאשׁוֹנָה וְיוֹעֲצֵינוּ כְּבַתְּחִלָּה וְהָסֵר מִמֶּנּוּ יָגוֹן וַאֲנָחָה וּמְלֹךְ עָלֵינוּ אַתָּה לְבַדֶּךָ בְּחֶסֶד וּבְרַחֲמִים בְּצֶדֶק וּבְמִשְׁפָּט בָּרוּךְ אַתָּה יְיָ׳‎ מֶלֶךְ אוֹהֵב צְדָקָה וּמִשְׁפָּט:","(יב) לַמַּלְשִׁינִים אַל תְּהִי תִקְוָה וְכָל הָאֶפִּיקוֹרוֹסִין כֻּלָּם כְּרֶגַע יֹאבֵדוּ וּמַלְכוּת זָדוֹן תְּעַקֵּר וּתְשַׁבֵּר בִּמְהֵרָה בְיָמֵינוּ בָּרוּךְ אַתָּה יְיָ׳‎ שׁוֹבֵר רְשָׁעִים וּמַכְנִיעַ זֵדִים:","(יג) עַל הַחֲסִידִים וְעַל הַצַּדִּיקִים וְעַל גֵּרֵי הַצֶּדֶק וְעַל שְׁאֵרִית עַמְּךָ בֵּית יִשְׂרָאֵל יֶהֱמוּ רַחֲמֶיךָ יְיָ׳‎ אֱלֹהֵינוּ וְתֵן שָׂכָר טוֹב לְכָל הַבּוֹטְחִים בְּשִׁמְךָ בֶּאֱמֶת וְכוּ׳‎:","(יד) תִּשְׁכֹּן בְּתוֹךְ יְרוּשָׁלַיִם עִירְךָ כַּאֲשֶׁר דִּבַּרְתָּ וּבְנֵה אוֹתָהּ בִּנְיַן עוֹלָם בִּמְהֵרָה בְיָמֵינוּ בָּרוּךְ אַתָּה יְיָ׳‎ בּוֹנֵה יְרוּשָׁלָיִם:","(טו) אֶת צֶמַח דָּוִד בִּמְהֵרָה תַצְמִיחַ וְקַרְנוֹ תָּרוּם בִּישׁוּעָתֶךָ בָּרוּךְ אַתָּה יְיָ׳‎ מַצְמִיחַ קֶרֶן יְשׁוּעָה:","(טז) שְׁמַע קוֹלֵנוּ יְיָ׳‎ אֱלֹהֵינוּ וְחוּס וְרַחֵם עָלֵינוּ וְקַבֵּל בְּרַחֲמִים וּבְרָצוֹן אֶת תְּפִלָּתֵנוּ מַלְכֵּנוּ רֵיקָם אַל תְּשִׁיבֵנוּ כִּי אַתָּה שׁוֹמֵעַ וְכוּ׳‎:","(יז) רְצֵה יְיָ׳‎ אֱלֹהֵינוּ בְּעַמְּךָ יִשְׂרָאֵל וְלִתְפִלָּתָם שְׁעֵה וְהָשֵׁב הָעֲבוֹדָה לִדְבִיר בֵּיתֶךָ וְאִשֵּׁי יִשְׂרָאֵל וּתְפִלָּתָם וְכוּ׳‎ בָּרוּךְ אַתָּה יְיָ׳‎ הַמַּחֲזִיר שְׁכִינָתוֹ לְצִיּוֹן:","(יח) מוֹדִים אֲנַחְנוּ לָךְ שָׁאַתָּה הוּא יְיָ׳‎ אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ צוּר חַיֵּינוּ וּמָגֵן יִשְׁעֵנוּ אַתָּה לְדוֹר וָדוֹר נוֹדֶה לְּךָ וּנְסַפֵּר תְּהִלָּתֶךָ עַל חַיֵּינוּ וְכוּ׳‎:","(יט) שִׂים שָׁלוֹם טוֹבָה וּבְרָכָה חֵן וָחֶסֶד וְרַחֲמִים עָלֵינוּ וְעַל יִשְׂרָאֵל עַמֶּךָ וּבָרְכֵנוּ כֻּלָּנוּ מִמְּאוֹר פָּנֶיךָ נָתַתָּ לָנוּ יְיָ׳‎ אֱלֹהֵינוּ תּוֹרָה וְחַיִּים אַהֲבָה וְכוּ׳‎.","בִּימוֹת הַחַמָּה אוֹמֵר בִּבְרָכָה שְׁנִיָּה רַב לְהוֹשִׁיעַ מוֹרִיד הַטָּל מְכַלְכֵּל חַיִּים בְּחֶסֶד וְכוּ׳‎. וּמְבָרֵךְ בְּרָכָה תְּשִׁיעִית בְּנֹסַח זֶה בָּרְכֵנוּ יְיָ׳‎ אֱלֹהֵינוּ בְּכָל מַעֲשֵׂה יָדֵינוּ וּבָרֵךְ אֶת שְׁנָתֵנוּ בְּטַלְלֵי רָצוֹן בְּרָכָה וּנְדָבָה כַּשָּׁנִים הַטּוֹבוֹת בָּרוּךְ אַתָּה יְיָ׳‎ מְבָרֵךְ הַשָּׁנִים.","בְּלֵיל מוֹצָאֵי שַׁבָּת וּבְמוֹצָאֵי יוֹם הַכִּפּוּרִים וּבְמוֹצָאֵי יָמִים טוֹבִים מְבָרֵךְ בְּרָכָה רְבִיעִית בְּנֹסַח זֶה. אַתָּה חוֹנֵן לְאָדָם דַּעַת וּמְלַמֵּד לֶאֱנוֹשׁ בִּינָה אַתָּה הִבְדַּלְתָּ בֵּין קֹדֶשׁ לְחל בֵּין אוֹר לְחשֶׁךְ בֵּין יִשְׂרָאֵל לָעַמִּים בֵּין יוֹם הַשְּׁבִיעִי לְשֵׁשֶׁת יְמֵי הַמַּעֲשֶׂה כְּשֵׁם שֶׁהִבְדַּלְתָּ בֵּין קֹדֶשׁ לְחל כֵּן פְּדֵנוּ וְהַצִּילֵנוּ מִכָּל מִינֵי מַשְׁחִית וּמִכָּל מִינֵי פֻרְעָנֻיּוֹת הַמִּתְרַגְּשׁוֹת לָבוֹא בָּעוֹלָם וְשָׁמְרֵנוּ מִן הַכּל וְחָנֵּנוּ מֵאִתְּךָ וְכוּ׳‎.","בְּרָאשֵׁי חֳדָשִׁים וּבְחֻלּוֹ שֶׁל מוֹעֵד מוֹסִיף בְּבִרְכַּת י״ז בְּעַרְבִית וְשַׁחֲרִית וּמִנְחָה וּמְבָרֵךְ אוֹתָהּ בְּנֹסַח זֶה. רְצֵה יְיָ׳‎ אֱלֹהֵינוּ וְכוּ׳‎ עַד עֲבוֹדַת יִשְׂרָאֵל עַמֶּךָ אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ יַעֲלֶה וְיָבוֹא וְכוּ׳‎ וְתֶחֱזֶינָה עֵינֵינוּ וְכוּ׳‎.","וּבְחֻלּוֹ שֶׁל מוֹעֵד אוֹמֵר בְּיוֹם מִקְרָא קֹדֶשׁ הַזֶּה בְּיוֹם מוֹעֵד חַג הַמַּצּוֹת הַזֶּה אוֹ בְּיוֹם מוֹעֵד חַג הַשָּׁבוּעוֹת הַזֶּה אוֹ בְּיוֹם מוֹעֵד חַג הַסֻּכּוֹת הַזֶּה.","בְּיוֹם תַּעֲנִית מְבָרֵךְ הַיָּחִיד בִּרְכַּת י״ו בְּנֹסַח זֶה. שְׁמַע קוֹלֵנוּ יְיָ׳‎ אֱלֹהֵינוּ חוּס וְרַחֵם עָלֵינוּ וְקַבֵּל בְּרַחֲמִים וּבְרָצוֹן אֶת תְּפִלָּתֵנוּ מִלְּפָנֶיךָ מַלְכֵּנוּ רֵיקָם אַל תְּשִׁיבֵנוּ עֲנֵנוּ אָבִינוּ עֲנֵנוּ בְּיוֹם צוֹם תַּעֲנִיתֵנוּ כִּי בְצָרָה גְדוֹלָה אֲנָחְנוּ אַל תַּסְתֵּר פָּנֶיךָ מִמֶּנּוּ וְאַל תַּעֲלֵם אָזְנְךָ מִשְּׁמוֹעַ בַּקָּשָׁתֵנוּ וֶהֱיֵה קָרוֹב לְשַׁוְעֵנוּ טֶרֶם נִקְרָא וְאַתָּה תַּעֲנֶה נְדַבֵּר וְאַתָּה תִּשְׁמַע כַּדָּבָר שֶׁנֶּאֱמַר וְהָיָה טֶרֶם יִקְרָאוּ וַאֲנִי אֶעֱנֶה עוֹד הֵם מְדַבְּרִים וַאֲנִי אֶשְׁמָע כִּי אַתָּה שׁוֹמֵעַ תְּפִלַּת כָּל פֶּה בָּרוּךְ אַתָּה יְיָ׳‎ שׁוֹמֵעַ תְּפִלָּה. וּשְׁלִיחַ צִבּוּר אוֹמֵר נֹסַח זֶה בְּרָכָה בִּפְנֵי עַצְמָהּ אַחַר בְּרָכָה שְׁבִיעִית אוֹמֵר עֲנֵנוּ וְכוּ׳‎ עַד כִּי אֵל עוֹנֶה בְּעֵת צָרָה פּוֹדֶה וּמַצִּיל בְּכָל עֵת צָרָה וְצוּקָה בָּרוּךְ אַתָּה יְיָ׳‎ הָעוֹנֶה בְּעֵת צָרָה.","בְּתִשְׁעָה בְּאָב מְבָרֵךְ בִּרְכַּת אַרְבַּע עֶשְׂרֵה בְּנֹסַח זֶה. רַחֵם יְיָ׳‎ עָלֵינוּ עַל יִשְׂרָאֵל עַמֶּךָ וְעַל יְרוּשָׁלַיִם עִירֶךָ הָעִיר הָאָבֵלָה הַחֲרֵבָה הַשּׁוֹמֵמָה הַנְּתוּנָה בְּיַד זָרִים הַיּוֹשֶׁבֶת וְרֹאשׁ לָהּ חָפוּי כְּאִשָּׁה עֲקָרָה שֶׁלֹּא יָלָדָה וַיְּבַלְּעוּהָ לִגְיוֹנוֹת וַיִּרָשׁוּהָ עוֹבְדֵי פְסִילִים וַיִּתְּנוּ נִבְלַת עֲבָדֶיךָ מַאֲכָל לְעוֹף הַשָּׁמַיִם וּלְבֶהֱמַת הָאָרֶץ עַל כֵּן צִיּוֹן (בְּמֶרֶר) [בְּמַר] תִּבְכֶּה וִירוּשָׁלַיִם תִּתֵּן קוֹלָהּ לִבִּי לִבִּי עַל חַלְלֵיהֶם מֵעַי מֵעַי עַל הֲרוּגֵיהֶם רְאֵה יְיָ׳‎ וְהַבִּיטָה וּרְאֵה שׁוֹמְמוֹתֶיהָ וְנַחֲמֶנָּה כִּי בָאֵשׁ הִצַּתָּהּ וּבָאֵשׁ אַתָּה עָתִיד לִבְנוֹתָהּ כַּכָּתוּב וַאֲנִי אֶהְיֶה לָּהּ נְאֻם יְיָ׳‎ חוֹמַת אֵשׁ סָבִיב וּלְכָבוֹד אֶהְיֶה בְתוֹכָהּ בָּרוּךְ אַתָּה יְיָ׳‎ בּוֹנֵה יְרוּשָׁלָיִם.","בְּפוּרִים מְבָרֵךְ בִּרְכַּת שְׁמוֹנֶה עֶשְׂרֵה בְּנֹסַח זֶה. מוֹדִים אֲנַחְנוּ לָךְ שָׁאַתָּה הוּא יְיָ׳‎ אֱלֹהֵינוּ עַל חַיֵּינוּ הַמְּסוּרִים בְּיָדֶךָ עַל נִשְׁמוֹתֵינוּ הַפְּקוּדוֹת לָךְ עַל נִסֶּיךָ שֶׁבְּכָל יוֹם וָיוֹם וְעַל נִפְלְאוֹתֶיךָ שֶׁבְּכָל עֵת כוּ׳‎ עַל הַנִּסִּים וְעַל הַגְּבוּרוֹת וְעַל הַתְּשׁוּעוֹת וְכוּ׳‎. וְעַל כֻּלָּם יְיָ׳‎ אֱלֹהֵינוּ אָנוּ מוֹדִים לָךְ הַטּוֹב כִּי לֹא כָלוּ וְכוּ׳‎.","בַּחֲנֻכָּה מְבָרֵךְ בְּרָכָה זוֹ בְּנֹסַח זֶה. מוֹדִים אֲנַחְנוּ לָךְ כוּ׳‎ עַד וְעַל נִפְלְאוֹתֶיךָ שֶׁבְּכָל עֵת עֶרֶב וָבֹקֶר וְצָהֳרָיִם עַל הַנִּסִּים כוּ׳‎ עַד וְאַחַר כֵּן בָּאוּ בָנֶיךָ וְכוּ׳‎.","שְׁלִיחַ צִבּוּר מְבָרֵךְ לְעוֹלָם בְּרָכָה שְׁלִישִׁית בְּנֹסַח זֶה. נַקְדִּישְׁךָ וְנַמְלִיכְךָ וּנְשַׁלֵּשׁ לְךָ קְדֻשָּׁה מְשֻׁלֶּשֶׁת כַּדָּבָר הָאָמוּר עַל יַד נְבִיאֶךָ וְקָרָא זֶה אֶל זֶה וְאָמַר קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ יְיָ׳‎ צְבָאוֹת מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ. כְּבוֹדוֹ וְגָדְלוֹ מָלֵא עוֹלָם וּמְשָׁרְתָיו שׁוֹאֲלִים אַיֵּה מְקוֹם כְּבוֹדוֹ לְהַעֲרִיצוֹ לְעֻמָּתָם מְשַׁבְּחִים וְאוֹמְרִים בָּרוּךְ כְּבוֹד יְיָ׳‎ מִמְּקוֹמוֹ. מִמְּקוֹמְךָ מַלְכֵּנוּ תּוֹפִיעַ וְתִמְלוֹךְ עָלֵינוּ כִּי מְחַכִּים אֲנַחְנוּ לָךְ מָתַי תִּמְלוֹךְ בְּצִיּוֹן בְּחַיֵּינוּ וּבְיָמֵינוּ תִּשְׁכֹּן תִּתְגַּדַּל וְתִתְקַדַּשׁ בְּתוֹךְ יְרוּשָׁלַיִם עִירְךָ לְדוֹר וָדוֹר לְנֵצַח נְצָחִים וְעֵינֵינוּ תִרְאֶינָה בְּמַלְכוּת עֻזֶּךָ כַּדָּבָר הָאָמוּר בְּדִבְרֵי קָדְשֶׁךָ עַל יְדֵי דָּוִד מְשִׁיחַ צִדְקֶךָ יִמְלוֹךְ יְיָ׳‎ לְעוֹלָם אֱלֹהַיִךְ צִיּוֹן לְדוֹר וָדוֹר הַלְלוּיָהּ. לְדוֹר וָדוֹר נַגִּיד גָּדְלֶךָ וּלְנֵצַח נְצָחִים קְדֻשָּׁתְךָ נַקְדִּישׁ וְשִׁבְחֲךָ אֱלֹהֵינוּ מִפִּינוּ לֹא יָמוּשׁ כִּי אֵל מֶלֶךְ גָּדוֹל וְקָדוֹשׁ אָתָּה בָּרוּךְ אַתָּה יְיָ׳‎ הָאֵל הַקָּדוֹשׁ. בְּעֵת שֶׁשְּׁלִיחַ צִבּוּר אוֹמֵר בִּבְרָכָה זוֹ וְקָרָא זֶה אֶל זֶה כָּל הָעָם עוֹנִין קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ וְכוּ׳‎. וּכְשֶׁהוּא אוֹמֵר אַיֵּה מְקוֹם כְּבוֹדוֹ כָּל הָעָם עוֹנִין מְשַׁבְּחִים וְאוֹמְרִים בָּרוּךְ כוּ׳‎. וּכְשֶׁהוּא אוֹמֵר בְּחַיֵּינוּ וּבְיָמֵינוּ כָּל הָעָם עוֹנִין אָמֵן. וּכְשֶׁהוּא אוֹמֵר עַל יְדֵי דָּוִד מְשִׁיחַ צִדְקֶךָ כָּל הָעָם אוֹמְרִים יִמְלוֹךְ יְיָ׳‎ לְעוֹלָם. וְכָל אֵלּוּ הַדְּבָרִים שֶׁעוֹנִין הַצִּבּוּר הוּא קוֹרֵא עִמָּהֶן. וְלֹא יַגְבִּיהַּ קוֹלוֹ בְּעֵת שֶׁהֵן עוֹנִין עִמּוֹ. וְאֶחָד הַיָּחִיד וְאֶחָד הַשַּׁ״ץ בַּעֲשָׂרָה יָמִים שֶׁמֵּרֹאשׁ הַשָּׁנָה עַד יוֹם הַכִּפּוּרִים אוֹמֵר בְּסוֹף בְּרָכָה זוֹ כָּאָמוּר וַיִּגְבַּהּ יְ״יָ צְבָאוֹת בַּמִּשְׁפָּט וְהָאֵל הַקָּדוֹשׁ נִקְדַּשׁ בִּצְדָקָה בָּרוּךְ אַתָּה יְ״יָ הַמֶּלֶךְ הַקָּדוֹשׁ.","קדיש ונפילת אפים","שְׁלִיחַ צִבּוּר אוֹמֵר קַדִּישׁ לְעוֹלָם קֹדֶם כָּל תְּפִלָּה וְאַחַר כָּל תְּפִלָּה וְאַחַר שֶׁאוֹמֵר סֵדֶר הַיּוֹם בְּכָל עֵת שֶׁיֹּאמַר סֵדֶר הַיּוֹם יִתְחַנֵּן מְעַט וְיֹאמַר קַדִּישׁ. וּכְשֶׁיַּשְׁלִים לִקְרוֹת בַּתּוֹרָה וּבְכָל עֵת שֶׁיִּתְחַנֵּן בְּדִבְרֵי תַּחֲנוּנִים כְּשֶׁיִּגְמֹר תַּחֲנוּנָיו יֹאמַר קַדִּישׁ:","נסח הקדיש","יִתְגַדַּל וְיִתְקַדַּשׁ שְׁמֵיהּ רַבָּא בְּעָלְמָא דִּבְרָא כִרְעוּתֵיהּ וְיַמְלִיךְ מַלְכוּתֵיהּ וְיַצְמַח פּוּרְקָנֵיהּ וִיקָרֵב מְשִׁיחֵיהּ וְיִפְרֹק עַמֵּיהּ בְּחַיֵּיכוֹן וּבְיוֹמֵיכוֹן וּבְחַיֵּיהוֹן דְּכָל בֵּית יִשְׂרָאֵל בַּעֲגָלָא וּבִזְמַן קָרִיב וְאִמְרוּ אָמֵן יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא יִתְבָּרַךְ וְכוּ׳‎. בְּעֵת שֶׁיֹּאמַר שְׁלִיחַ צִבּוּר יִתְגַדַּל וְיִתְקַדַּשׁ שְׁמֵיהּ רַבָּא כָּל הָעָם עוֹנִין אָמֵן. וּבְעֵת שֶׁהוּא אוֹמֵר תְּחִלָּה וְאִמְרוּ אָמֵן כָּל הָעָם עוֹנִין אָמֵן יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא. וּמִצְוַת חֲכָמִים הָרִאשׁוֹנִים לַעֲנוֹת אָמֵן יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךְ בְּכָל כֹּחוֹ שֶׁל אָדָם. וּכְשֶׁהוּא אוֹמֵר יִתְבָּרַךְ כָּל הָעָם עוֹנִין אָמֵן. וּכְשֶׁהוּא אוֹמֵר בְּרִיךְ הוּא כָּל הָעָם עוֹנִין אָמֵן. וּכְשֶׁהוּא אוֹמֵר בַּסּוֹף וְאִמְרוּ אָמֵן כָּל הָעָם עוֹנִין אָמֵן. וְכַסֵּדֶר הַזֶּה עוֹנִין בְּכָל קַדִּישׁ וְקַדִּישׁ. קַדִּישׁ בַּתְרָא כָּל קַדִּישׁ שֶׁאוֹמֵר שְׁלִיחַ צִבּוּר אַחַר שֶׁגּוֹמֵר הַתְּפִלָּה שֶׁאֵינוֹ אוֹמֵר אַחֲרָיו כְּלוּם אֶלָּא כָּל הָעָם שׁוֹמְעִין אוֹתוֹ וְנִפְטָרִין נָהֲגוּ הָעָם לְהוֹסִיף בְּסוֹפוֹ נֻסְחָא זוֹ. תִּתְקַבֵּל צְלוֹתְהוֹן וְתִתְעַבֵּד בָּעוּתְהוֹן וּצְלוֹתְהוֹן וּבָעוּתְהוֹן דְּכָל בֵּית יִשְׂרָאֵל קֳדָם אֲבוּהוֹן דְּבִשְׁמַיָּא. יְהֵא שְׁלָמָא רַבָּא וְסִיַּעְתָּא וּפוּרְקָנָא מִשְּׁמַיָּא עֲלֵיכוֹן וַעֲלָנָא וְעַל קְהָלְהוֹן דְּיִשְׂרָאֵל וְאִמְרוּ אָמֵן. עשֶֹׁה שָׁלוֹם בִּמְרוֹמָיו הוּא בְרַחֲמָיו יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל אָמֵן. קַדִּישׁ דְּרַבָּנָן כָּל עֲשָׂרָה מִיִּשְׂרָאֵל אוֹ יָתֵר שֶׁעוֹסְקִין בְּתַלְמוּד תּוֹרָה שֶׁעַל פֶּה וַאֲפִלּוּ בְּמִדְרָשׁוֹת אוֹ בְּהַגָּדוֹת כְּשֶׁהֵן מְסַיְּמִין אוֹמֵר אֶחָד מֵהֶן קַדִּישׁ בְּנֹסַח זֶה. יִתְגַדַּל וְיִתְקַדַּשׁ שְׁמֵיהּ רַבָּא דְּעָתִיד לְחַדְתָּא עָלְמָא וּלְאַחָיָא מֵתַיָּא וּלְמִפְרַק חַיָּיא וּלְמִבְנֵי קַרְתָּא דִּירוּשָׁלֵם וּלְשַׁכְלָלָא הֵיכָלָא קַדִּישָׁא וּלְמֵעֲקַר פּוּלְחָנָא נוּכְרָאָה מִן אַרְעָא וְלַאֲתָבָא פּוּלְחָנָא דִּשְׁמַיָּא לְאַתְרֵיהּ בְּזִיוֵיהּ וְיִחוּדֵיהּ וְיַמְלִיךְ מַלְכוּתֵיהּ וְכוּ׳‎ עַד וְנֶחָמָתָא דַּאֲמִירָן בְּעָלְמָא וְאִמְרוּ אָמֵן. עַל רַבָּנָן וְעַל תַּלְמִידֵיהוֹן וְעַל תַּלְמִידֵי תַלְמִידֵיהוֹן דְּעָסְקִין בְּאוֹרַיְתָא דִּי בְאַתְרָא הָדֵין וְדִי בְכָל אֲתַר וַאֲתַר יְהֵא לְהוֹן וּלְכוֹן חִנָּא וְחִסְדָּא וְרַחֲמֵי וְסִיַּעְתָּא וְרַוְחָא מִקֳדָם אֲבוּהוֹן דְּבִשְׁמַיָּא וְאִמְרוּ אָמֵן. יְהֵא שְׁלָמָא וְכוּ׳‎. וְזֶהוּ הַנִּקְרָא קַדִּישׁ דְּרַבָּנָן.","מִנְהָגֵנוּ לְהִתְחַנֵּן בִּנְפִילַת פָּנִים בִּדְבָרִים וּפְסוּקִים אֵלּוּ פְּעָמִים בְּכֻלָּן וּפְעָמִים בְּמִקְצָתָן. לְפִיכָךְ אֲנִי כּוֹרֵעַ וּמִשְׁתַּחֲוֶה וּמִתְחַנֵּן לְפָנֶיךָ אֲדוֹן הָעוֹלָם אֱלֹהֵי הָאֱלֹהִים וַאֲדוֹנֵי הָאֲדוֹנִים כִּי לֹא עַל צִדְקֹתֵינוּ אֲנַחְנוּ מַפִּילִים תַּחֲנוּנֵינוּ לְפָנֶיךָ כִּי עַל רַחֲמֶיךָ הָרַבִּים. יְיָ׳‎ שְׁמָעָה יְיָ׳‎ סְלָחָה יְיָ׳‎ הַקְשִׁיבָה וַעֲשֵׂה אַל תְּאַחַר. מַה נֹּאמַר לְפָנֶיךָ הַשֵּׁם מַה נְּדַבֵּר וּמַה נִּצְטַדָּק חָטָאנוּ עָוִינוּ וְהִרְשַׁעְנוּ וּמָרַדְנוּ וְסַרְנוּ מִמִּצְוֹתֶיךָ וּמִמִּשְׁפָּטֶיךָ לְךָ יְיָ׳‎ הַצְּדָקָה וְלָנוּ בֹּשֶׁת הַפָּנִים. הֻשְׁחֲרוּ פָּנֵינוּ מִפְּנֵי חַטֹּאתֵינוּ וְנִכְפְּפָה קוֹמָתֵנוּ מִפְּנֵי אַשְׁמוֹתֵינוּ אֵין לָנוּ פֶּה לְהָשִׁיב וְלֹא מֵצַח לְהָרִים רֹאשׁ. אֱלֹהַי בּשְׁתִּי וְנִכְלַמְתִּי לְהָרִים אֱלֹהַי פָּנַי אֵלֶיךָ כִּי עֲוֹנוֹתֵינוּ רָבוּ עַד לְמַעְלָה רֹאשׁ וְאַשְׁמָתֵנוּ גָדְלָה עַד לַשָּׁמָיִם. אֵין בָּנוּ מַעֲשִׂים עֲשֵׂה עִמָּנוּ צְדָקָה לְמַעַן שְׁמֶךָ וְהוֹשִׁיעֵנוּ כְּמוֹ שֶּׁהִבְטַחְתָּנוּ עַל יְדֵי נְבִיאֶךָ לְמַעַן שְׁמִי אַאֲרִיךְ אַפִּי וּתְהִלָּתִי אֶחֱטָם לָךְ לְבִלְתִּי הַכְרִיתֶךָ לֹא לְמַעַנְכֶם אֲנִי עשֶֹׁה בֵּית יִשְׂרָאֵל כִּי אִם לְשֵׁם קָדְשִׁי אֲשֶׁר חִלַּלְתֶּם בַּגּוֹיִם אֲשֶׁר בָּאתֶם שָׁם. לֹא לָנוּ יְיָ׳‎ לֹא לָנוּ כִּי לְשִׁמְךָ תֵּן כָּבוֹד עַל חַסְדְּךָ עַל אֲמִתֶּךָ לָמָּה יֹאמְרוּ הַגּוֹיִם אַיֵּה נָא אֱלֹהֵיהֶם אָנָּא יְיָ׳‎ אַל תֵּפֶן אֶל קְשִׁי הָעָם הַזֶּה וְאֶל רִשְׁעוֹ וְאֶל חַטָּאתוֹ סְלַח נָא לַעֲוֹן הָעָם הַזֶּה כְּגֹדֶל חַסְדֶּךָ וְכַאֲשֶׁר נָשָׂאתָה לָעָם הַזֶּה מִמִּצְרַיִם וְעַד הֵנָּה וְסָלַחְתָּ לַעֲוֹנֵנוּ כִּי רַב הוּא. יְיָ׳‎ שְׁמָעָה יְיָ׳‎ סְלָחָה יְיָ׳‎ הַקְשִׁיבָה וַעֲשֵׂה וְאַל תְּאַחַר לְמַעַנְךָ אֱלֹהַי כִּי שִׁמְךָ נִקְרָא עַל עִירְךָ וְעַל עַמֶּךָ:","נָהֲגוּ הָעָם לְהִתְחַנֵּן אַחַר נְפִילַת פָּנִים כְּשֶׁמַּגְבִּיהַּ פָּנָיו מִן הַקַּרְקַע בִּפְסוּקִים אֵלּוּ. וַאֲנַחְנוּ לֹא נֵדַע מַה נַּעֲשֶׂה כִּי עָלֶיךָ עֵינֵינוּ. זְכֹר רַחֲמֶיךָ יְיָ׳‎ וַחֲסָדֶיךָ כִּי מֵעוֹלָם הֵמָּה. אַל תִּזְכָּר לָנוּ עֲוֹנֹת רִאשֹׁנִים מַהֵר יְקַדְּמוּנוּ רַחֲמֶיךָ כִּי דַלּוֹנוּ מְאֹד. קוּמָה עֶזְרָתָה לָנוּ וּפְדֵנוּ לְמַעַן חַסְדֶּךָ. יְהִי חַסְדְּךָ יְיָ׳‎ עָלֵינוּ כַּאֲשֶׁר יִחַלְנוּ לָךְ. אִם עֲוֹנוֹת תִּשְׁמָר יָהּ יְיָ׳‎ מִי יַעֲמֹד כִּי עִמְּךָ הַסְּלִיחָה לְמַעַן תִּוָּרֵא. יְיָ׳‎ הוֹשִׁיעָה הַמֶּלֶךְ יַעֲנֵנוּ בְיוֹם קָרְאֵנוּ. כִּי הוּא יָדַע יִצְרֵנוּ זָכוּר כִּי עָפָר אֲנָחְנוּ. עָזְרֵנוּ אֱלֹהֵי יִשְׁעֵנוּ עַל דְּבַר כְּבוֹד שְׁמֶךָ וְהַצִּילֵנוּ וְכַפֵּר עַל חַטֹּאתֵינוּ לְמַעַן שְׁמֶךָ. וְכֵן נָהֲגוּ הָעָם לְהִתְחַנֵּן אַחַר סֵדֶר הַיּוֹם בְּתַחֲנוּנִים אֵלּוּ. יְיָ׳‎ אֱלֹהֵי אַבְרָהָם יִצְחָק וְיִשְׂרָאֵל אֲבֹתֵינוּ שָׁמְרָה זֹּאת לְעוֹלָם לְיֵצֶר מַחְשְׁבוֹת לְבַב עַמֶּךָ וְהָכֵן לְבָבָם אֵלֶיךָ וְהוּא רַחוּם יְכַפֵּר עָוֹן וְגוֹ׳‎. כִּי אַתָּה יְיָ׳‎ טוֹב וְסַלָּח וְרַב חֶסֶד לְכָל קוֹרְאֶיךָ צִדְקָתְךָ צֶדֶק לְעוֹלָם וְתוֹרָתְךָ אֱמֶת. מִי אֵל כָּמוֹךָ נוֹשֵׂא עָוֹן וְעוֹבֵר עַל פֶּשַׁע יָשׁוּב יְרַחֲמֵנוּ יִכְבּשׁ עֲוֹנוֹתֵינוּ וְגוֹ׳‎. בָּרוּךְ יְיָ׳‎ יוֹם יוֹם יַעֲמָס לָנוּ הָאֵל יְשׁוּעָתֵנוּ סֶלָה. יְיָ׳‎ צְבָאוֹת עִמָּנוּ מִשְׂגָּב לָנוּ אֱלֹהֵי יַעֲקֹב סֶלָה יְיָ׳‎ צְבָאוֹת אַשְׁרֵי אָדָם בּוֹטֵחַ בָּךְ. בָּרוּךְ אֲדוֹנֵנוּ בָּרוּךְ בּוֹרְאֵנוּ בָּרוּךְ שֶׁבְּרָאָנוּ לִכְבוֹדוֹ וְהִבְדִּילָנוּ מִן הַתּוֹעִים וְנָתַן לָנוּ תּוֹרַת אֱמֶת עַל יְדֵי משֶׁה רַבֵּנוּ וְחַיֵּי עוֹלָם נָטַע בְּתוֹכֵנוּ. הָרַחֲמָן יִפְתַּח לִבֵּנוּ לְתַלְמוּד תּוֹרָתוֹ וְיִתֵּן בְּלִבֵּנוּ אַהֲבָתוֹ וְיִרְאָתוֹ וְתוֹרָתוֹ לַעֲשׂוֹת רְצוֹנוֹ וּלְעָבְדוֹ בְּלֵבָב שָׁלֵם וּבְנֶפֶשׁ חֲפֵצָה לְמַעַן לֹא נִיגַע לָרִיק וְלֹא נֵלֵד לַבֶּהָלָה. כֵּן יְהִי רָצוֹן וְרַחֲמִים מִלְּפָנֶיךָ יְיָ׳‎ אֱלֹהֵינוּ שֶׁנִּחְיֶה לִשְׁמֹר חֻקֶּיךָ בָּעוֹלָם הַזֶּה וְלִימוֹת הַמָּשִׁיחַ כְּדֵי שֶׁנִּזְכֶּה וְנִירַשׁ טוֹב לְחַיֵּי הָעוֹלָם הַבָּא לְמַעַן יְזַמֶּרְךָ כָבוֹד וְלֹא יִדֹּם יְיָ׳‎ אֱלֹהַי לְעוֹלָם אוֹדֶךָּ. יִהְיוּ לְרָצוֹן אִמְרֵי פִי וְהֶגְיוֹן לִבִּי לְפָנֶיךָ יְיָ׳‎ צוּרִי וְגוֹאֲלִי:","נָהֲגוּ מִקְצָת הָעָם לִקְרֹא בְּכָל יוֹם אַחַר תַּחֲנוּנִים אֵלּוּ שִׁיר מִזְמוֹר שֶׁהָיוּ הַלְוִיִּם אוֹמְרִים בְּבֵית הַמִּקְדָּשׁ בְּאוֹתוֹ הַיּוֹם וְקוֹרִין לְדָוִד אֵלֶיךָ יְיָ׳‎ נַפְשִׁי אֶשָּׂא כָּל הַמִּזְמוֹר. וְקוֹרִין אָמַר רַבִּי אֶלְעָזָר אָמַר רַבִּי חֲנִינָא תַּלְמִידֵי חֲכָמִים מַרְבִּים שָׁלוֹם וְכוּ׳‎. אֵין כֵּאלֹהֵינוּ אֵין כַּאדוֹנֵנוּ אֵין כְּמַלְכֵּנוּ אֵין כְּמוֹשִׁיעֵנוּ מִי כֵאלֹהֵינוּ מִי כַאדוֹנֵנוּ מִי כְמַלְכֵּנוּ מִי כְמוֹשִׁיעֵנוּ נוֹדֶה לֵאלֹהֵינוּ נוֹדֶה לַאדוֹנֵנוּ נוֹדֶה לְמַלְכֵּנוּ נוֹדֶה לְמוֹשִׁיעֵנוּ אַתָּה הוּא אֱלֹהֵינוּ אַתָּה הוּא אֲדוֹנֵנוּ אַתָּה הוּא מַלְכֵּנוּ אַתָּה הוּא מוֹשִׁיעֵנוּ. אַתָּה תָקוּם תְּרַחֵם צִיּוֹן כִּי עֵת לְחֶנְנָהּ כִּי בָא מוֹעֵד. אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךָ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךָ וְיִבְטְחוּ בְךָ יוֹדְעֵי שְׁמֶךָ כִּי לֹא עָזַבְתָּ דֹרְשֶׁיךָ יְיָ׳‎. כִּי כָּל הָעַמִּים יֵלְכוּ אִישׁ בְּשֵׁם אֱלֹהָיו וַאֲנַחְנוּ נֵלֵךְ בְּשֵׁם יְיָ׳‎ אֱלֹהֵינוּ לְעוֹלָם וָעֶד.","כְּבָר אָמַרְנוּ בַּסֵּפֶר הַזֶּה שֶׁבִּימֵי הַשַּׁבָּתוֹת וְיָמִים טוֹבִים מִתְפַּלֵּל אָדָם בְּכָל תְּפִלָּה שֶׁבַע בְּרָכוֹת שָׁלֹשׁ רִאשׁוֹנוֹת וְשָׁלֹשׁ אַחֲרוֹנוֹת וּבְרָכָה אַחַת אֶמְצָעִית מֵעֵין הַיּוֹם. וּבְרֹאשׁ הַשָּׁנָה וּבְיוֹם הַכִּפּוּרִים שֶׁל יוֹבֵל מִתְפַּלֵּל בָּאֶמְצַע שָׁלֹשׁ בְּרָכוֹת וּבִתְפִלַּת מוּסָף בִּלְבַד. וְנִמְצָא מִתְפַּלֵּל בְּמוּסָף בִּשְׁנֵי יָמִים אֵלּוּ תֵּשַׁע בְּרָכוֹת. וּבְמוּסַף רֹאשׁ חֹדֶשׁ וּבְמוּסַף חֻלּוֹ שֶׁל מוֹעֵד מִתְפַּלֵּל שֶׁבַע שָׁלֹשׁ רִאשׁוֹנוֹת וְשָׁלֹשׁ אַחֲרוֹנוֹת וּבְרָכָה אַחַת בָּאֶמְצַע:"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 17":["כֵּיצַד מַלְקִין אֶת הַמְחֻיָּב מַלְקוֹת. כְּפִי כֹּחוֹ שֶׁנֶּאֱמַר (דברים כה ב) \"כְּדֵי רִשְׁעָתוֹ בְּמִסְפָּר\". וְזֶה שֶׁנֶּאֱמַר (דברים כה ג) \"אַרְבָּעִים\" שֶׁאֵין מוֹסִיפִין עַל הָאַרְבָּעִים אֲפִלּוּ הָיָה חָזָק וּבָרִיא כְּשִׁמְשׁוֹן. אֲבָל פּוֹחֲתִין לַחַלָּשׁ שֶׁאִם יַכֶּה לַחַלָּשׁ מַכָּה רַבָּה בְּוַדַּאי הוּא מֵת. לְפִיכָךְ אָמְרוּ חֲכָמִים שֶׁאֲפִלּוּ הַבָּרִיא בְּיוֹתֵר מַכִּין אוֹתוֹ שְׁלֹשִׁים וְתֵשַׁע שֶׁאִם יוֹסִיף לוֹ אַחַת נִמְצֵאת שֶׁלֹּא הִכָּהוּ אֶלָּא אַרְבָּעִים הָרְאוּיוֹת לוֹ:","כְּשֶׁאוֹמְדִין אֶת הַחוֹטֵא כַּמָּה הוּא יָכוֹל לְקַבֵּל אֵין אוֹמְדִין אֶלָּא בְּמַכּוֹת הָרְאוּיוֹת לְהִשְׁתַּלֵּשׁ. אֲמָדוּהוּ שֶׁיָּכוֹל לְקַבֵּל עֶשְׂרִים אֵין אוֹמְרִין יִלְקֶה עֶשְׂרִים וְאַחַת כְּדֵי שֶׁיִּהְיוּ יְכוֹלִין לְהִשְׁתַּלֵּשׁ אֶלָּא יִלְקֶה שְׁמוֹנֶה עֶשְׂרֵה. אֲמָדוּהוּ לְקַבֵּל אַרְבָּעִים וְכֵיוָן שֶׁהִתְחִיל לִלְקוֹת רָאוּהוּ חַלָּשׁ וְאָמְרוּ אֵינוֹ יָכוֹל לְקַבֵּל יוֹתֵר עַל אֵלּוּ הַתֵּשַׁע אוֹ הַשְּׁתֵּים עֶשְׂרֵה שֶׁלָּקָה הֲרֵי זֶה פָּטוּר. אֲמָדוּהוּ לְקַבֵּל שְׁתֵּים עֶשְׂרֵה וְאַחַר שֶׁלָּקָה רָאוּהוּ חָזָק וְיָכוֹל לְקַבֵּל יוֹתֵר הֲרֵי זֶה פָּטוּר וְאֵינוֹ לוֹקֶה יוֹתֵר עַל הָאֹמֶד:","אֲמָדוּהוּ הַיּוֹם שֶׁיִּלְקֶה שְׁתֵּים עֶשְׂרֵה וְלֹא הִלְקוּהוּ עַד לְמָחָר וַהֲרֵי הוּא לְמָחָר יָכוֹל לְקַבֵּל שְׁמוֹנֶה עֶשְׂרֵה אֵינוֹ לוֹקֶה אֶלָּא שְׁתֵּים עֶשְׂרֵה. אֲמָדוּהוּ שֶׁיִּלְקֶה לְמָחָר שְׁתֵּים עֶשְׂרֵה וְלֹא לָקָה עַד יוֹם שְׁלִישִׁי וַהֲרֵי הוּא חָזָק לְקַבֵּל שְׁמוֹנֶה עֶשְׂרֵה לוֹקֶה שְׁמוֹנֶה עֶשְׂרֵה שֶׁהֲרֵי בִּשְׁעַת הָאֹמֶד לֹא אֲמָדוּהוּ לִלְקוֹת אֶלָּא לְאַחַר זְמַן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","מִי שֶׁנִּתְחַיֵּב מַלְקִיּוֹת הַרְבֵּה בֵּין עַל עֲבֵרוֹת הַרְבֵּה בֵּין עַל מַעֲשֶׂה אֶחָד שֶׁחַיָּבִין עָלָיו מַלְקִיּוֹת הַרְבֵּה. אִם אֲמָדוּהוּ אֹמֶד אֶחָד לוֹקֶה וּפָטוּר וְאִם לָאו לוֹקֶה וּמִתְרַפֵּא וְחוֹזֵר וְלוֹקֶה. כֵּיצַד. נִתְחַיֵּב שְׁתֵּי מַלְקִיּוֹת וְאָמְדוּ שֶׁיָּכוֹל הוּא לְקַבֵּל אַרְבָּעִים וְחָמֵשׁ כֵּיוָן שֶׁלָּקָה אַרְבָּעִים וְחָמֵשׁ נִפְטָר. אֲבָל אִם אֲמָדוּהוּ לְמַלְקוּת אַחַת וְהִכָּהוּ שָׁלֹשׁ אוֹ תֵּשַׁע אוֹ שְׁלֹשִׁים כְּמוֹ הָאֹמֶד הֲרֵי זֶה מִתְרַפֵּא וְחוֹזְרִין וְאוֹמְדִין אוֹתוֹ לְמַלְקוּת שְׁנִיָּה עַד שֶׁיִּלְקֶה לְכָל מַלְקִיּוֹת שֶׁהוּא חַיָּב בָּהֶן:","מִי שֶׁאֲמָדוּהוּ וּכְשֶׁהִתְחִיל לִלְקוֹת נִתְקַלְקֵל מִכֹּחַ הַהַכָּאָה בֵּין בְּרֵיעִי בֵּין בְּמֵימֵי רַגְלַיִם אֵין מַכִּין אוֹתוֹ יוֹתֵר שֶׁנֶּאֱמַר (דברים כה ג) \"וְנִקְלָה אָחִיךָ לְעֵינֶיךָ\" כֵּיוָן שֶׁנִּקְלָה פָּטוּר. אֲבָל אִם נִתְקַלְקֵל מִן הַפַּחַד מִקֹּדֶם הַהַכָּאָה אֲפִלּוּ נִתְקַלְקֵל מִשֶּׁיָּצָא מִבֵּית דִּין לִלְקוֹת וַאֲפִלּוּ מִבָּעֶרֶב הֲרֵי זֶה לוֹקֶה כָּל הָאֹמֶד שֶׁאֲמָדוּהוּ. אֲמָדוּהוּ לִשְׁתֵּי מַלְקִיּוֹת וְלָקָה וְנִתְקַלְקֵל בֵּין בָּרִאשׁוֹנָה בֵּין בַּשְּׁנִיָּה פָּטוּר. נִפְסְקָה הָרְצוּעָה בַּשְּׁנִיָּה פּוֹטְרִין אוֹתוֹ. נִפְסְקָה בָּרִאשׁוֹנָה נִפְטָר מִמַּלְקוֹת רִאשׁוֹנָה וְלוֹקֶה הָאֹמֶד הַשֵּׁנִי:","כְּפָתוּהוּ עַל הָעַמּוּד לִלְקוֹת וְכָרַת אֶת הַמֵיתָרִים וּבָרַח פָּטוּר וְאֵין מַחֲזִירִין אוֹתוֹ:","כָּל מִי שֶׁחָטָא וְלָקָה חוֹזֵר לְכַשְׁרוּתוֹ שֶׁנֶּאֱמַר (דברים כה ג) \"וְנִקְלָה אָחִיךָ לְעֵינֶיךָ\" כֵּיוָן שֶׁלָּקָה הֲרֵי הוּא אָחִיךָ. אַף כָּל מְחֻיְּבֵי כָּרֵת שֶׁלָקוּ נִפְטְרוּ מִידֵי כְּרִיתָתָן:","כֹּהֵן גָּדוֹל שֶׁחָטָא לוֹקֶה בִּשְׁלֹשָׁה כִּשְׁאָר כָּל הָעָם וְחוֹזֵר לִגְדֻלָּתוֹ:","אֲבָל רֹאשׁ הַיְשִׁיבָה שֶׁחָטָא מַלְקִין אוֹתוֹ וְאֵינוֹ חוֹזֵר לִשְׂרָרוּתוֹ. גַּם אֵינוֹ חוֹזֵר לִהְיוֹת כְּאֶחָד מִשְּׁאָר הַסַּנְהֶדְרִין. שֶׁמַּעֲלִין בַּקֹּדֶשׁ וְלֹא מוֹרִידִין:"],"Mishneh Torah, The Sanhedrin and the Penalties within Their Jurisdiction 4":["אֶחָד בֵּית דִּין הַגָּדוֹל וְאֶחָד סַנְהֶדְרִין קְטַנָּה אוֹ בֵּית דִּין שֶׁל שְׁלֹשָׁה צָרִיךְ שֶׁיִּהְיֶה אֶחָד מֵהֶן סָמוּךְ מִפִּי הַסָּמוּךְ. וּמשֶׁה רַבֵּנוּ סָמַךְ יְהוֹשֻׁעַ בַּיָּד שֶׁנֶּאֱמַר (במדבר כז כג) \"וַיִּסְמֹךְ אֶת יָדָיו עָלָיו וַיְצַוֵּהוּ\". וְכֵן הַשִּׁבְעִים זְקֵנִים משֶׁה רַבֵּנוּ סְמָכָם וְשָׁרְתָה עֲלֵיהֶן שְׁכִינָה. וְאוֹתָן הַזְּקֵנִים סָמְכוּ לַאֲחֵרִים וַאֲחֵרִים לַאֲחֵרִים וְנִמְצְאוּ הַסְּמוּכִין אִישׁ מִפִּי אִישׁ עַד בֵּית דִּינוֹ שֶׁל יְהוֹשֻׁעַ וְעַד בֵּית דִּינוֹ שֶׁל משֶׁה רַבֵּנוּ. וְאֶחָד הַנִּסְמָךְ מִפִּי הַנָּשִׂיא אוֹ מִפִּי אֶחָד מִן הַסְּמוּכִין אֲפִלּוּ לֹא הָיָה אוֹתוֹ סָמוּךְ בַּסַּנְהֶדְרִין מֵעוֹלָם:","וְכֵיצַד הִיא הַסְּמִיכָה לְדוֹרוֹת. לֹא שֶׁיִּסְמְכוּ יְדֵיהֶן עַל רֹאשׁ הַזָּקֵן אֶלָּא שֶׁקּוֹרִין לוֹ רַבִּי וְאוֹמְרִים לוֹ הֲרֵי אַתְּ סָמוּךְ וְיֵשׁ לְךָ רְשׁוּת לָדוּן אֲפִלּוּ דִּינֵי קְנָסוֹת:","וְאֵין סוֹמְכִין סְמִיכָה שֶׁהִיא מִנּוּי הַזְּקֵנִים לְדַיָּנוּת אֶלָּא בִּשְׁלֹשָׁה וְהוּא שֶׁיִּהְיֶה הָאֶחָד מֵהֶן סָמוּךְ מִפִּי אֲחֵרִים כְּמוֹ שֶׁבֵּאַרְנוּ:","אֵין קָרוּי אֱלֹהִים אֶלָּא בֵּית דִּין שֶׁנִּסְמַךְ בְּאֶרֶץ יִשְׂרָאֵל בִּלְבַד וְהֵם הָאֲנָשִׁים הַחֲכָמִים הָרְאוּיִין לָדוּן שֶׁבָּדְקוּ אוֹתָן בֵּית דִּין שֶׁל אֶרֶץ יִשְׂרָאֵל וּמִנּוּ אוֹתָם וְסָמְכוּ אוֹתָן:","בָּרִאשׁוֹנָה הָיָה כָּל מִי שֶׁנִּסְמָךְ סוֹמֵךְ לְתַלְמִידָיו. וַחֲכָמִים חָלְקוּ כָּבוֹד לְהִלֵּל הַזָּקֵן וְהִתְקִינוּ שֶׁלֹּא יְהֵא אָדָם נִסְמָךְ אֶלָּא בִּרְשׁוּת הַנָּשִׂיא. וְשֶׁלֹּא יְהֵא הַנָּשִׂיא סוֹמֵךְ אֶלָּא אִם כֵּן הָיָה אַב בֵּית דִּין עִמּוֹ. וְשֶׁלֹּא יִהְיֶה אַב בֵּית דִּין סוֹמֵךְ אֶלָּא אִם כֵּן הָיָה הַנָּשִׂיא עִמּוֹ. אֲבָל שְׁאָר הַחֲבוּרָה יֵשׁ לְכָל אֶחָד מֵהֶם לִסְמֹךְ בִּרְשׁוּת הַנָּשִׂיא. וְהוּא שֶׁיִּהְיוּ שְׁנַיִם עִמּוֹ שֶׁאֵין סְמִיכָה פָּחוֹת מִשְּׁלֹשָׁה:","אֵין סוֹמְכִין זְקֵנִים בְּחוּצָה לָאָרֶץ וְאַף עַל פִּי שֶׁאֵלּוּ הַסּוֹמְכִין נִסְמְכוּ בְּאֶרֶץ יִשְׂרָאֵל. אֲפִלּוּ הָיוּ הַסּוֹמְכִין בָּאָרֶץ וְהַנִּסְמָךְ חוּצָה לָאָרֶץ אֵין סוֹמְכִין. וְאֵין צָרִיךְ לוֹמַר אִם הָיוּ הַסּוֹמְכִין בְּחוּצָה לָאָרֶץ וְהַנִּסְמָכִין בָּאָרֶץ. הָיוּ שְׁנֵיהֶם בָּאָרֶץ סוֹמְכִין אוֹתוֹ אַף עַל פִּי שֶׁאֵינוֹ עִם הַסְּמוּכִים בְּמָקוֹם אֶחָד. אֶלָּא שׁוֹלְחִין לוֹ אוֹ כּוֹתְבִין לוֹ שֶׁהוּא סָמוּךְ וְנוֹתְנִין לוֹ רְשׁוּת לָדוּן דִּינֵי קְנָסוֹת הוֹאִיל וּשְׁנֵיהֶם בָּאָרֶץ. וְכָל אֶרֶץ יִשְׂרָאֵל שֶׁהֶחְזִיקוּ בָּהּ עוֹלֵי מִצְרַיִם רְאוּיָה לִסְמִיכָה:","יֵשׁ לַסּוֹמְכִין לִסְמֹךְ אֲפִלּוּ מֵאָה בְּפַעַם אַחַת. וְדָוִד הַמֶּלֶךְ סָמַךְ שְׁלֹשִׁים אֶלֶף בְּיוֹם אֶחָד:","וְיֵשׁ לָהֶן לְמַנּוֹת כָּל מִי שֶׁיִּרְצוּ לִדְבָרִים יְחִידִים. וְהוּא שֶׁיִּהְיֶה רָאוּי לְכָל הַדְּבָרִים. כֵּיצַד. חָכָם מֻפְלָא שֶׁרָאוּי לְהוֹרוֹת לְכָל הַתּוֹרָה כֻּלָּהּ יֵשׁ לְבֵית דִּין לִסְמֹךְ אוֹתוֹ וְלִתֵּן לוֹ רְשׁוּת לָדוּן וְלֹא לְהוֹרוֹת בְּאִסּוּר וְהֶתֵּר. אוֹ יִתְּנוּ לוֹ רְשׁוּת בְּאִסּוּר וְהֶתֵּר וְלֹא לָדוּן דִּינֵי מָמוֹנוֹת. אוֹ יִתְּנוּ רְשׁוּת לָזֶה וְלָזֶה אֲבָל לֹא לָדוּן דִּינֵי קְנָסוֹת. אוֹ לָדוּן דִּינֵי קְנָסוֹת אֲבָל לֹא לְהַתִּיר בְּכוֹרוֹת בְּמוּמִין. אוֹ יִתְּנוּ לוֹ רְשׁוּת לְהַתִּיר נְדָרִים בִּלְבַד אוֹ לִרְאוֹת כְּתָמִים. וְכֵן כָּל כַּיּוֹצֵא בָּהֶן:","וְכֵן יֵשׁ לַסּוֹמְכִין לִתֵּן רְשׁוּת עַד זְמַן וְלוֹמַר לַנִּסְמָךְ יֵשׁ לְךָ רְשׁוּת לָדוּן אוֹ לְהוֹרוֹת עַד שֶׁיָּבוֹא הַנָּשִׂיא לְכָאן. אוֹ כָּל זְמַן שֶׁאֵין אַתָּה עִמָּנוּ בַּמְּדִינָה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","חָכָם מֻפְלָא שֶׁהוּא סוּמָא בְּעֵינוֹ אַחַת אַף עַל פִּי שֶׁהוּא רָאוּי לְדִינֵי מָמוֹנוֹת אֵין סוֹמְכִין אוֹתוֹ לְדִינֵי מָמוֹנוֹת מִפְּנֵי שֶׁאֵינוֹ רָאוּי לְכָל הַדְּבָרִים. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","הֲרֵי שֶׁלֹּא הָיָה בְּאֶרֶץ יִשְׂרָאֵל אֶלָּא סוֹמֵךְ אֶחָד מוֹשִׁיב שְׁנַיִם בְּצִדּוֹ וְסוֹמֵךְ שִׁבְעִים כְּאֶחָד אוֹ זֶה אַחַר זֶה וְאַחַר כָּךְ יַעֲשֶׂה הוּא וְהַשִּׁבְעִים בֵּית דִּין הַגָּדוֹל וְיִסְמְכוּ בָּתֵּי דִּינִין אֲחֵרִים. נִרְאִין לִי הַדְּבָרִים שֶׁאִם הִסְכִּימוּ כָּל הַחֲכָמִים שֶׁבְּאֶרֶץ יִשְׂרָאֵל לְמַנּוֹת דַּיָּנִים וְלִסְמֹךְ אוֹתָם הֲרֵי אֵלּוּ סְמוּכִים וְיֵשׁ לָהֶן לָדוּן דִּינֵי קְנָסוֹת וְיֵשׁ לָהֶן לִסְמֹךְ לַאֲחֵרִים. אִם כֵּן לָמָּה הָיוּ הַחֲכָמִים מִצְטַעֲרִין עַל הַסְּמִיכָה כְּדֵי שֶׁלֹּא יִבָּטְלוּ דִּינֵי קְנָסוֹת מִיִּשְׂרָאֵל. לְפִי שֶׁיִּשְׂרָאֵל מְפֻזָּרִין וְאִי אֶפְשָׁר שֶׁיַּסְכִּימוּ כֻּלָּן. וְאִם הָיָה שָׁם סָמוּךְ מִפִּי סָמוּךְ אֵינוֹ צָרִיךְ דַּעַת כֻּלָּן אֶלָּא דָּן דִּינֵי קְנָסוֹת לַכּל שֶׁהֲרֵי נִסְמַךְ מִפִּי בֵּית דִּין. וְהַדָּבָר צָרִיךְ הֶכְרֵעַ:","בֵּית דִּין שֶׁנִּסְמְכוּ בְּאֶרֶץ יִשְׂרָאֵל וְיָצְאוּ חוּצָה לָאָרֶץ הֲרֵי הֵם דָּנִים דִּינֵי קְנָסוֹת בְּחוּצָה לָאָרֶץ כְּדֶרֶךְ שֶׁדָּנִים בָּאָרֶץ. שֶׁסַּנְהֶדְרִין נוֹהֶגֶת בָּאָרֶץ וּבְחוּצָה לָאָרֶץ וְהוּא שֶׁיִּהְיוּ סְמוּכִים:","רָאשֵׁי גָּלֻיּוֹת שֶׁבְּבָבֶל בִּמְקוֹם מֶלֶךְ הֵן עוֹמְדִים. וְיֵשׁ לָהֶן לִרְדּוֹת אֶת יִשְׂרָאֵל בְּכָל מָקוֹם וְלָדוּן עֲלֵיהֶן בֵּין רָצוּ בֵּין לֹא רָצוּ שֶׁנֶּאֱמַר (בראשית מט י) \"לֹא יָסוּר שֵׁבֶט מִיהוּדָה\" אֵלּוּ רָאשֵׁי גָּלֻיּוֹת שֶׁבְּבָבֶל:","וְכָל דַּיָּן הָרָאוּי לָדוּן שֶׁנָּתַן לוֹ רֹאשׁ גָּלוּת רְשׁוּת לָדוּן יֵשׁ לוֹ רְשׁוּת לָדוּן בְּכָל הָעוֹלָם אַף עַל פִּי שֶׁלֹּא רָצוּ בַּעֲלֵי דִּינִין בֵּין בָּאָרֶץ בֵּין בְּחוּצָה לָאָרֶץ אַף עַל פִּי שֶׁאֵינוֹ דָּן דִּינֵי קְנָסוֹת. וְכָל דַּיָּן הָרָאוּי לָדוּן שֶׁנָּתְנוּ לוֹ בֵּית דִּין שֶׁבְּאֶרֶץ יִשְׂרָאֵל רְשׁוּת לָדוּן יֵשׁ לוֹ רְשׁוּת לָדוּן בְּכָל אֶרֶץ יִשְׂרָאֵל וּבַעֲיָרוֹת הָעוֹמְדוֹת עַל הַגְּבוּלִים אַף עַל פִּי שֶׁלֹּא רָצוּ בַּעֲלֵי דִּינִין. אֲבָל בְּחוּצָה לָאָרֶץ אֵין רְשׁוּתָן מוֹעֶלֶת לוֹ לָכוֹף אֶת בַּעֲלֵי דִּינִין. אַף עַל פִּי שֶׁיֵּשׁ לוֹ לָדוּן דִּינֵי קְנָסוֹת בְּחוּצָה לָאָרֶץ אֵינוֹ דָּן אֶלָּא לְמִי שֶׁרוֹצֶה לָדוּן אֶצְלוֹ. אֲבָל לָכוֹף אֶת בַּעֲלֵי דִּינִין וְלָדוּן לָהֶם אֵין לוֹ רְשׁוּת עַד שֶׁיִּטּל רְשׁוּת מֵרֹאשׁ גָּלוּת:","מִי שֶׁאֵינוֹ רָאוּי לָדוּן מִפְּנֵי שֶׁאֵינוֹ יוֹדֵעַ אוֹ מִפְּנֵי שֶׁאֵינוֹ הָגוּן שֶׁעָבַר רֹאשׁ גָּלוּת וְנָתַן לוֹ רְשׁוּת אוֹ שֶׁטָּעוּ בֵּית דִּין וְנָתְנוּ לוֹ רְשׁוּת אֵין הָרְשׁוּת מוֹעֶלֶת לוֹ כְּלוּם עַד שֶׁיְּהֵא רָאוּי. שֶׁהַמַּקְדִּישׁ בַּעַל מוּם לַמִּזְבֵּחַ אֵין הַקְּדֻשָּׁה חָלָה עָלָיו:"],"Mishneh Torah, Theft 7":["הַשּׁוֹקֵל לַחֲבֵרוֹ מִמִּשְׁקָלוֹת חֲסֵרוֹת מִן הַמִּשְׁקָל שֶׁהִסְכִּימוּ עָלָיו בְּנֵי אוֹתָהּ הַמְּדִינָה. אוֹ הַמּוֹדֵד בְּמִדָּה חֲסֵרָה מִן הַמִּדָּה שֶׁהִסְכִּימוּ עָלֶיהָ. הֲרֵי זֶה עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (ויקרא יט לה) \"לֹא תַעֲשׂוּ עָוֶל בַּמִּשְׁפָּט בַּמִּדָּה בַּמִּשְׁקָל וּבַמְּשׂוּרָה\":","אַף עַל פִּי שֶׁהַמּוֹדֵד אוֹ הַשּׁוֹקֵל חָסֵר גּוֹנֵב אֵינוֹ מְשַׁלֵּם לוֹ תַּשְׁלוּמֵי כֶּפֶל אֶלָּא מְשַׁלֵּם לוֹ הַמִּדָּה אוֹ הַמִּשְׁקָל. וְאֵין לוֹקִין עַל לָאו זֶה מִפְּנֵי שֶׁהוּא חַיָּב בְּתַשְׁלוּמִין:","כָּל מִי שֶׁמַּשְׁהֶה בְּבֵיתוֹ אוֹ בַּחֲנוּתוֹ מִדָּה חֲסֵרָה אוֹ מִשְׁקַל חָסֵר עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (דברים כה יג) \"לֹא יִהְיֶה לְךָ בְּכִיסְךָ\" וְגוֹ'. וַאֲפִלּוּ לַעֲשׂוֹת הַמִּדָּה עָבִיט שֶׁל מֵימֵי רַגְלַיִם אָסוּר. שֶׁאַף עַל פִּי שֶׁאֵין זֶה לוֹקֵחַ וּמוֹכֵר בָּהּ שֶׁמָּא יָבוֹא מִי שֶׁאֵינוֹ יוֹדֵעַ שֶׁהִיא חֲסֵרָה וְיִמְדֹּד בָּהּ. וְאֵין לוֹקִין עַל לָאו זֶה שֶׁהֲרֵי אֵין בּוֹ מַעֲשֶׂה:","הָיוּ הַמִּדּוֹת וְהַמִּשְׁקָלוֹת שֶׁל בְּנֵי הָעִיר חֲתוּמוֹת בְּחוֹתָם יָדוּעַ וְזוֹ הַמִּדָּה אוֹ הַמִּשְׁקָל הַחֲסֵרִים בְּלֹא חוֹתָם. הֲרֵי זֶה מֻתָּר לַשְׁהוֹתָם לִשְׁאָר תַּשְׁמִישֵׁי הַבַּיִת. כַּיּוֹצֵא בָּזֶה סֶלַע שֶׁנִּפְגְּמָה מִן הַצַּד לֹא יַעֲשֶׂנָּה מִשְׁקָל בֵּין מִשְׁקְלוֹתָיו וְלֹא יִזְרְקֶנָּה בֵּין גְּרוּטוֹתָיו וְלֹא יִקָּבֶנָּה וְיִתְלֶנָּה בְּצַוַּאר בְּנוֹ שֶׁמָּא יָבוֹא אַחֵר וְיַעֲשֶׂנָּה מִשְׁקָל. אֶלָּא אוֹ יִשְׁחֹק אוֹ יַחְתֹּךְ אוֹ יָקֹץ אוֹ יַשְׁלִיךְ לְיָם הַמֶּלַח:","חָסְרָה וְעָמְדָה עַל מֶחֱצָה יְקַיֵּם. עָמְדָה עַל פָּחוֹת מִמֶּחֱצָה אוֹ עַל יֶתֶר מִמֶּחֱצָה יָקֹץ עַד שֶׁיַּעֲמִידֶנָּה עַל מֶחֱצָה. וְאִם לֹא חָסְרָה אֶלָּא פָּחוֹת מִשְּׁתוּת יְקַיֵּם לָשֵׂאת וְלָתֵת בָּהּ אֲבָל לֹא לְמִשְׁקָל. שֶׁכָּל פָּחוֹת מִשְּׁתוּת רֹב בְּנֵי אָדָם מוֹחֲלִין בּוֹ בְּמַשָּׂא וּבְמַתָּן:","סֶלַע שֶׁנִּפְגְּמָה בָּאֶמְצַע אָסוּר לְמָכְרָהּ לְהַרָג אוֹ לְחַרָם מִפְּנֵי שֶׁמְּרַמִּין בָּהּ אֶת אֲחֵרִים. אֲבָל נוֹקְבָהּ וְתוֹלֶה אוֹתָהּ בְּצַוַּאר הַקָּטָן:","עוֹשֶׂה אָדָם מִדּוֹתָיו סְאָה וַחֲצִי סְאָה וְרֹבַע סְאָה. וְקַב וַחֲצִי קַב וְרֹבַע הַקַּב וַחֲצִי הָרֹבַע וּשְׁמִינִית הָרֹבַע. אֲבָל לֹא יַעֲשֶׂה קַבַּיִם שֶׁלֹּא תִּתְחַלֵּף בְּרֹבַע הַסְּאָה שֶׁהוּא קַב וּמֶחֱצָה. וְכֵן בְּמִדּוֹת הַלַּח עוֹשֶׂה הִין וַחֲצִי הִין וּשְׁלִישִׁית הַהִין וּרְבִיעִית הַהִין. וְלוֹג וַחֲצִי לוֹג וּרְבִיעִית וּשְׁמִינִית וְאֶחָד מִשְּׁמוֹנָה בַּשְּׁמִינִית. וְלֹא אָסְרוּ לַעֲשׂוֹת שְׁלִישִׁית הִין וּרְבִיעִית הִין אַף עַל פִּי שֶׁמִּתְחַלְּפִין זֶה בָּזֶה הוֹאִיל וְהָיוּ בַּמִּקְדָּשׁ מִימוֹת משֶׁה רַבֵּנוּ:","אֶחָד הַנּוֹשֵׂא וְהַנּוֹתֵן עִם יִשְׂרָאֵל אוֹ עִם עַכּוּ\"ם אִם מָדַד אוֹ שָׁקַל בְּחָסֵר עוֹבֵר עַל לֹא תַּעֲשֶׂה וְחַיָּב לְהַחְזִיר. וְכֵן אָסוּר לְהַטְעוֹת אֶת הָעַכּוּ\"ם בְּחֶשְׁבּוֹן אֶלָּא יְדַקְדֵּק עִמּוֹ שֶׁנֶּאֱמַר (ויקרא כה נ) \"וְחִשַּׁב עִם קֹנֵהוּ\" אַף עַל פִּי שֶׁהוּא כָּבוּשׁ תַּחַת יָדֶיךָ. קַל וָחֹמֶר לְעַכּוּ\"ם שֶׁאֵינוֹ כָּבוּשׁ תַּחַת יָדֶיךָ. וַהֲרֵי הוּא בִּכְלַל (דברים כה טז) \"כִּי תוֹעֲבַת ה' אֱלֹהֶיךָ כָּל עשֵֹׁה אֵלֶּה כּל עשֵֹׁה עָוֶל\" מִכָּל מָקוֹם:","וְכֵן בְּמִדַּת הַקַּרְקַע אִם הִטְעָה אֶת חֲבֵרוֹ בִּמְשִׁיחַת הַקַּרְקַע עוֹבֵר בְּלֹא תַּעֲשֶׂה שֶׁנֶּאֱמַר (ויקרא יט לה) \"לֹא תַעֲשׂוּ עָוֶל בַּמִּשְׁפָּט בַּמִּדָּה\". בַּמִּדָּה זוֹ מִדַּת הַקַּרְקַע. וְכֵן הוּא עִנְיַן פָּסוּק זֶה לֹא תַעֲשׂוּ עָוֶל בַּמִּשְׁפָּט לֹא בְּמִשְׁפַּט הַמִּשְׁקָל וְלֹא בְּמִשְׁפַּט הַמִּדָּה אֲפִלּוּ מִדָּה קְטַנָּה כִּמְשׂוּרָה:","בְּנֵי חֲבוּרָה הַמַּקְפִּידִים זֶה עַל זֶה שֶׁהֶחְלִיפוּ חֵלֶק בְּחֵלֶק אוֹ לָוָה מִמֶּנּוּ מַאֲכָל וְהֶחְזִיר לוֹ. עוֹבְרִין מִשּׁוּם מִדָּה וּמִשּׁוּם מִשְׁקָל וּמִשּׁוּם מִנְיָן וּמִשּׁוּם לוֹוִין וּפוֹרְעִין בְּיוֹם טוֹב:","הַמַּסִּיג גְּבוּל רֵעֵהוּ וְהִכְנִיס מִתְּחוּם חֲבֵרוֹ בְּתוֹךְ תְּחוּמוֹ אֲפִלּוּ מְלוֹא אֶצְבַּע. אִם בְּחָזְקָה עָשָׂה הֲרֵי זֶה גַּזְלָן. וְאִם הִסִּיג בַּסֵּתֶר הֲרֵי זֶה גַּנָּב. וְאִם בְּאֶרֶץ יִשְׂרָאֵל הִסִּיג הַגְּבוּל הֲרֵי זֶה עוֹבֵר בִּשְׁנֵי לָאוִין בְּלָאו גְּנֵבָה אוֹ בְּלָאו גְּזֵלָה וּבְלָאו (דברים יט יד) \"לֹא תַסִּיג\". וְאֵין חַיָּב בְּלָאו זֶה אֶלָּא בְּאֶרֶץ יִשְׂרָאֵל שֶׁנֶּאֱמַר (דברים יט יד) \"בְּנַחֲלָתְךָ אֲשֶׁר תִּנְחַל\":","קָשֶׁה עָנְשָׁן שֶׁל מִדּוֹת יֶתֶר מֵעָנְשָׁן שֶׁל עֲרָיוֹת שֶׁזֶּה בֵּינוֹ לְבֵין הַמָּקוֹם וְזֶה בֵּינוֹ לְבֵין חֲבֵרוֹ. וְכָל הַכֹּפֶר בְּמִצְוַת מִדּוֹת כְּכוֹפֵר בִּיצִיאַת מִצְרַיִם שֶׁהִיא תְּחִלַּת הַצִּוּוּי. וְכָל הַמְקַבֵּל עָלָיו מִצְוַת מִדּוֹת הֲרֵי זֶה מוֹדֶה בִּיצִיאַת מִצְרַיִם שֶׁהִיא גָּרְמָה לְכָל הַצִּוּוּיִין:"],"Mishneh Torah, Those Who Defile Bed or Seat 11":["כְּבָר בֵּאַרְנוּ שֶׁעַמֵּי הָאָרֶץ נֶאֱמָנִים הֵן עַל טָהֳרַת פָּרַת הַחַטָּאת מִפְּנֵי חֻמְרָתָהּ אֵין מְזַלְזְלִין בָּהּ. וְכֵן נֶאֱמָנִים הֵן עַל טָהֳרַת יַיִן וְשֶׁמֶן שֶׁל נְסָכִים אִם אָמַר טָהוֹר הוּא הֲרֵי זֶה בְּחֶזְקַת טָהֳרָה מִפְּנֵי חֻמְרָתוֹ נִזְהָרִין בּוֹ. וְכֵן נֶאֱמָנִים הֵן עַל הַתְּרוּמָה בִּשְׁעַת הַגִּתּוֹת וְהַבַּדִּים מִפְּנֵי שֶׁכָּל הָעָם מְטַהֲרִין עַצְמָן וּכְלֵיהֶן כְּדֵי לַעֲשׂוֹת יֵינָם וְשַׁמְנָם בְּטָהֳרָה. עָבְרוּ הַגִּתּוֹת וְהַבַּדִּים אֵינָן נֶאֱמָנִים:","כֹּהֵן שֶׁהֵבִיא לוֹ עַם הָאָרֶץ חָבִית יַיִן אוֹ שֶׁמֶן שֶׁל תְּרוּמָה לֹא יְקַבְּלֶנָּה מִמֶּנּוּ מִפְּנֵי שֶׁהִיא בְּחֶזְקַת טֻמְאָה. הִנִּיחָהּ עַם הָאָרֶץ אֶצְלוֹ עַד גַּת הַבָּאָה וֶהֱבִיאָהּ לוֹ יְקַבְּלֶנָּה מִמֶּנּוּ אַף עַל פִּי שֶׁהוּא יוֹדֵעַ שֶׁהִיא שֶׁל אֶשְׁתָּקַד שֶׁלֹּא גָּזְרוּ עֲלֵיהֶם טֻמְאָה בִּשְׁעַת הַגִּתּוֹת וְהַבַּדִּים:","עַם הָאָרֶץ שֶׁנָּעַל בֵּית בַּדּוֹ אוֹ גִּתּוֹ בְּשָׁעָה שֶׁגָּמְרוּ הָעָם לִדְרֹךְ וְהוֹלִיךְ אֶת הַמַּפְתֵּחַ מִיָּד לְכֹהֵן אַף עַל פִּי שֶׁשָּׁהָה כַּמָּה יָמִים אַחַר שֶׁעָבְרוּ הַגִּתּוֹת הֲרֵי הַכֹּהֵן בָּא וּפוֹתֵחַ בְּפָנָיו וּמַטְבִּילוֹ וְדוֹרֵךְ וְנוֹטֵל תְּרוּמָה בְּטָהֳרָה. וְאִם לֹא עָשָׂה כֵן לֹא יִטּל תְּרוּמָה מֵעַם הָאָרֶץ אֶלָּא זֵיתִים וַעֲנָבִים שֶׁאֵינָן מֻכְשָׁרִין שֶׁאֵינָן מְקַבְּלִין טֻמְאָה:","הֵבִיא לוֹ עַם הָאָרֶץ חָבִית שֶׁל תְּרוּמָה בִּשְׁאָר יְמוֹת הַשָּׁנָה וְאָמַר הִפְרַשְׁתִּי בְּתוֹכָהּ קֹדֶשׁ אֲפִלּוּ רְבִיעִית מִתּוֹךְ שֶׁנֶּאֱמָן עַל טָהֳרַת הַקֹּדֶשׁ נֶאֱמָן עַל הַכּל אֲפִלּוּ בִּשְׁעַת הַגִּתּוֹת וְהַבַּדִּים שֶׁעַמֵּי הָאָרֶץ נֶאֱמָנִין עַל הַתְּרוּמָה אֵינָן נֶאֱמָנִין עַל הַכְּלִי הָרֵיקָם לוֹמַר שֶׁהוּא טָהוֹר לִתְרוּמָה. וְכֵן אֵין נֶאֱמָנִין לְעוֹלָם עַל כְּלִי רֵיקָם לוֹמַר שֶׁהוּא טָהוֹר לְקֹדֶשׁ:","כְּלִי שֶׁהָיָה בְּתוֹכוֹ יַיִן אוֹ שֶׁמֶן וְרָאִינוּ עַם הָאָרֶץ יוֹשֵׁב וּמְשַׁמְּרוֹ כְּדֵי לְהוֹצִיא מִמֶּנּוּ נְסָכִים הֲרֵי הוּא נֶאֱמָן עַל טָהֳרַת הַכְּלִי וַאֲפִלּוּ קֹדֶם לַגִּתּוֹת וְלַבַּדִּים בְּשִׁבְעִים יוֹם. אֲבָל קֹדֶם לְשִׁבְעִים אֵינָן נֶאֱמָנִים. בַּמֶּה דְּבָרִים אֲמוּרִים בִּשְׁאָר אֶרֶץ יִשְׂרָאֵל. אֲבָל בִּירוּשָׁלַיִם נֶאֱמָנִים עַל כְּלִי חֶרֶס הָרֵיקָם לוֹמַר שֶׁהוּא טָהוֹר לְקֹדֶשׁ לְעוֹלָם בֵּין כֵּלִים דַּקִּים בֵּין כֵּלִים גַּסִּים בֵּין מְלֵאִין בֵּין רֵיקָנִים הֲרֵי הוּא נֶאֱמָן עַל הַכְּלִי אַף עַל פִּי שֶׁהַמַּשְׁקִין שֶׁבְּתוֹכוֹ טְמֵאִין. אֲפִלּוּ הָיָה בִּגְדוֹ שֶׁהוּא מִדְרָס בְּתוֹךְ הַכְּלִי הֲרֵי הַכְּלִי בְּחֶזְקַת טָהֳרָה לְקֹדֶשׁ. וּמִפְּנֵי מָה הֵקֵלּוּ בָּהֶם מִפְּנֵי שֶׁאֵין עוֹשִׂין כִּבְשׁוֹנוֹת בִּירוּשָׁלַיִם:","מִן הַמּוֹדִיעִית וּלְפָנִים נֶאֱמָנִים עַל כְּלִי חֶרֶס מִן הַמּוֹדִיעִית וְלַחוּץ אֵינָן נֶאֱמָנִין וְהַמּוֹדִיעִית עַצְמָהּ פְּעָמִים כְּלַחוּץ וּפְעָמִים כִּלְפָנִים. כֵּיצַד. הָיָה חָבֵר נִכְנָס וְעַם הָאָרֶץ יוֹצֵא וּכְלִי חֶרֶס בְּיָדוֹ הֲרֵי זֶה נֶאֱמָן בַּמּוֹדִיעִית לוֹמַר שֶׁהוּא טָהוֹר לְקֹדֶשׁ. הָיוּ שְׁנֵיהֶן נִכְנָסִין אוֹ שְׁנֵיהֶן יוֹצְאִין אֵינוֹ נֶאֱמָן עַד שֶׁיְּהֵא לְפָנִים מִן הַמּוֹדִיעִית:","קַדָּר שֶׁהֵבִיא קְדֵרוֹת וְהִנִּיחָן לְפָנִים מִן הַמּוֹדִיעִית וּבָאוּ הַלּוֹקְחִין וְהוּא אוֹמֵר לָהֶן שֶׁטְּהוֹרוֹת הֵן. לָקַח קְדֵרָה וְנִכְנַס בָּהּ הֲרֵי הִיא טְהוֹרָה לְקֹדֶשׁ אֲבָל לֹא לִתְרוּמָה כְּמוֹ שֶׁבֵּאַרְנוּ. לָקַח קְדֵרָה וְיָצָא בָּהּ חוּץ לַמּוֹדִיעִית הֲרֵי זוֹ טְמֵאָה בֵּין לְקֹדֶשׁ בֵּין לִתְרוּמָה אַף עַל פִּי שֶׁהֵן הֵן הַקְּדֵרוֹת. וְהוּא הַקַּדָּר עַצְמוֹ אֵינוֹ נֶאֱמָן אֶלָּא לְפָנִים מִן הַמּוֹדִיעִית:","הַלּוֹקֵחַ כְּלֵי חֶרֶס מִן הַכִּבְשָׁן בְּכָל מָקוֹם הֲרֵי אֵלּוּ טְהוֹרִין בֵּין לְקֹדֶשׁ בֵּין לִתְרוּמָה וְאֵין אוֹמְרִים שֶׁמָּא נָגַע בָּהֶן עַם הָאָרֶץ. וַאֲפִלּוּ לָקַח מִן הַסֵּדֶר הָרִאשׁוֹן. וְאַף עַל פִּי שֶׁהַכִּבְשָׁן פָּתוּחַ וּכְבָר נִלְקַח חֶצְיוֹ שֶׁלֹּא גָּזְרוּ טֻמְאָה עַל כֵּלִים שֶׁבַּכִּבְשָׁן:","טֻמְאַת עַם הָאָרֶץ בָּרֶגֶל כִּטְהוֹרָה הִיא חֲשׁוּבָה שֶׁכָּל יִשְׂרָאֵל חֲבֵרִים הֵן בָּרְגָלִים וּכְלֵיהֶם כֻּלָּם וְאוֹכְלֵיהֶם וּמַשְׁקֵיהֶן טְהוֹרִים בָּרֶגֶל מִפְּנֵי שֶׁהַכּל מְטַהֲרִין עַצְמָן וְעוֹלִים לָרֶגֶל. לְפִיכָךְ הֵן נֶאֱמָנִים כָּל יְמוֹת הָרֶגֶל בֵּין עַל הַקֹּדֶשׁ בֵּין עַל הַתְּרוּמָה. מִשֶּׁעָבַר הָרֶגֶל חוֹזְרִין לְטֻמְאָתָן:","הַפּוֹתֵחַ חָבִיתוֹ בָּרֶגֶל וְהַמַּתְחִיל בְּעִסָּתוֹ וְעָבַר הָרֶגֶל הֲרֵי שְׁאָר הֶחָבִית וּשְׁאָר הָעִסָּה בְּחֶזְקַת טֻמְאָה שֶׁהֲרֵי נָגְעוּ בּוֹ עַמֵּי הָאָרֶץ. וְאַף עַל פִּי שֶׁלֹּא נָגַע בָּהּ אֶלָּא בִּזְמַן שֶׁהוּא כְּחָבֵר אֵינָהּ טְהוֹרָה אֶלָּא בִּימֵי הָרֶגֶל בִּלְבַד:","אַחַר הָרֶגֶל בְּמוֹצָאֵי יוֹם טוֹב הָיוּ מַטְבִּילִין כָּל הַכֵּלִים שֶׁהָיוּ בַּמִּקְדָּשׁ מִפְּנֵי שֶׁנָּגְעוּ בָּהֶן עַמֵּי הָאָרֶץ בָּרֶגֶל בִּשְׁעַת הֶחָג. וּלְפִיכָךְ הָיוּ אוֹמְרִים לָהֶן אַל תִּגְּעוּ בַּשֻּׁלְחָן בְּשָׁעָה שֶׁמַּרְאִין אוֹתוֹ לְעוֹלֵי רְגָלִים כְּדֵי שֶׁלֹּא יִהְיֶה טָמֵא בְּמַגָּעוֹ אַחַר הָרֶגֶל וְנִמְצָא צָרִיךְ טְבִילָה וְהַעֲרֵב שֶׁמֶשׁ וְנֶאֱמַר בְּלֶחֶם הַפָּנִים (שמות כה ל) \"לְפָנַי תָּמִיד\". וְכָל הַכֵּלִים הָיוּ טְעוּנִים טְבִילָה וְהַעֲרֵב שֶׁמֶשׁ חוּץ מִמִּזְבַּח הַזָּהָב וּמִזְבַּח הַנְּחשֶׁת מִפְּנֵי שֶׁצִּפּוּיֵיהֶן כִּבְטֵלִין לְגַבֵּיהֶן:","עַם הָאָרֶץ שֶׁאָמַר טָהוֹר אֲנִי מִטֻּמְאַת מֵת אוֹ שֶׁאָמַר כְּלִי זֶה טָהוֹר מִטֻּמְאַת מֵת נֶאֱמָן וּמַטְבִּילִין אוֹתוֹ מִשּׁוּם טֻמְאַת עַם הָאָרֶץ בִּלְבַד וְצָרִיךְ הַעֲרֵב שֶׁמֶשׁ וְאֵינוֹ צָרִיךְ הַזָּאָה. בַּמֶּה דְּבָרִים אֲמוּרִים בְּשֶׁשָּׁאֲלוּ וְאָמַר טָהוֹר הוּא. אֲבָל הַלּוֹקֵחַ כְּלִי סְתָם מֵרְשׁוּת עַם הָאָרֶץ חוֹשְׁשִׁין לוֹ שֶׁמָּא טְמֵא מֵת הוּא וּמַזִּין עָלָיו שְׁלִישִׁי וּשְׁבִיעִי כְּכָל הַכֵּלִים הַנִּמְצָאִים בְּכָל מָקוֹם חוּץ לִירוּשָׁלַיִם שֶׁלֹּא גָּזְרוּ טֻמְאָה עַל הַכֵּלִים הַנִּמְצָאִים בִּירוּשָׁלַיִם כְּמוֹ שֶׁיִּתְבָּאֵר בְּטֻמְאַת הַסְּפֵקוֹת:"],"Mishneh Torah, Tithes 10":["הַמְקַבֵּל עָלָיו לִהְיוֹת נֶאֱמָן עַל הַמַּעַשְׂרוֹת וְלֹא יִהְיוּ פֵּרוֹתָיו דְּמַאי צָרִיךְ לִהְיוֹת מְעַשֵּׂר אֶת שֶׁהוּא אוֹכֵל וְאֶת שֶׁהוּא מוֹכֵר וְאֶת שֶׁהוּא לוֹקֵחַ. וְאֵינוֹ מִתְאָרֵחַ אֵצֶל עַם הָאָרֶץ. וְצָרִיךְ שֶׁיְּקַבֵּל עָלָיו דְּבָרִים אֵלּוּ בָּרַבִּים. וּכְשֶׁיָּבוֹאוּ עֵדִים נֶאֱמָנִין שֶׁקִּבֵּל דְּבָרִים אֵלּוּ בָּרַבִּים וְשֶׁהוּא רָגִיל בָּהֶם תָּמִיד הֲרֵי זֶה נֶאֱמָן עַל פֵּרוֹתָיו לוֹמַר מְעֵשָּׂרִין הֵן:","כָּל תַּלְמִיד חָכָם לְעוֹלָם נֶאֱמָן וְאֵינוֹ צָרִיךְ בְּדִיקָה אַחֲרָיו. וּבָנָיו וּבְנֵי בֵּיתוֹ וַעֲבָדָיו [וְאִשְׁתּוֹ] הֲרֵי הֵם כָּמוֹהוּ. תַּלְמִיד חָכָם שֶׁמֵּת וְהִנִּיחַ פֵּרוֹת אֲפִלּוּ כְּנָסָם בְּאוֹתוֹ הַיּוֹם הֲרֵי הֵן בְּחֶזְקַת מְתֻקָּנִין:","בַּת עַם הָאָרֶץ אוֹ אִשְׁתּוֹ שֶׁנִּסֵּת לְחָבֵר וְעַבְדּוֹ שֶׁנִּמְכָּר לְחָבֵר צְרִיכִין לְקַבֵּל עֲלֵיהֶם בַּתְּחִלָּה. וּבַת חָבֵר אוֹ אִשְׁתּוֹ שֶׁנִּסֵּת לְעַם הָאָרֶץ וְעַבְדּוֹ שֶׁנִּמְכָּר לְעַם הָאָרֶץ הֲרֵי הֵן בְּחֶזְקָתָן עַד שֶׁיֵּחָשְׁדוּ. בְּנוֹ אוֹ עַבְדּוֹ שֶׁל חָבֵר שֶׁהָיוּ לְמוּדִין אֵצֶל עַם הָאָרֶץ צְרִיכִין לְקַבֵּל. בְּנוֹ אוֹ עַבְדּוֹ שֶׁל עַם הָאָרֶץ שֶׁהָיוּ לְמוּדִים אֵצֶל חָבֵר כָּל זְמַן שֶׁהֵן אֶצְלוֹ הֲרֵי הֵן כְּחָבֵר. יָצְאוּ הֲרֵי הֵן כְּעַם הָאָרֶץ:","מִי שֶׁאֵינוֹ נֶאֱמָן וְהָיָה אֶחָד מִבָּנָיו אוֹ מֵעֲבָדָיו נֶאֱמָן אוֹ אֶחָד מִמִּשְׁפַּחְתּוֹ לוֹקְחִין מִמֶּנּוּ וְאוֹכְלִין עַל פִּיהֶן וְאֵינָן חוֹשְׁשִׁין לְדָבָר:","הָיָה הוּא נֶאֱמָן וְאִשְׁתּוֹ אֵינָהּ נֶאֱמֶנֶת לוֹקְחִים מִמֶּנּוּ וְאֵין מִתְאָרְחִין אֶצְלוֹ. [הָיְתָה אִשְׁתּוֹ נֶאֱמֶנֶת וְהוּא אֵינוֹ נֶאֱמָן מִתְאָרְחִין אֶצְלוֹ וְאֵין לוֹקְחִין מִמֶּנּוּ. וְתָבוֹא מְאֵרָה לְמִי שֶׁאִשְׁתּוֹ נֶאֱמֶנֶת וְהוּא אֵינוֹ נֶאֱמָן]:","לֹא יְשַׁמֵּשׁ חָבֵר לֹא בְּמִשְׁתֵּה עַם הָאָרֶץ וְלֹא בִּסְעֻדָּתוֹ אֶלָּא אִם כֵּן הָיָה הַכּל מְעֻשָּׂר וּמְתֻקָּן מִתַּחַת יָדוֹ. לְפִיכָךְ הָרוֹאֶה חָבֵר מְשַׁמֵּשׁ בְּמִשְׁתֵּה עַם הָאָרֶץ אוֹ בִּסְעֻדָּתוֹ הֲרֵי הַכּל בְּחֶזְקַת מְתֻקָּן וּמְעֻשָּׂר. רָאוּהוּ מֵסֵב עִם עַמֵּי הָאָרֶץ אֵין הַסְּעֻדָּה בְּחֶזְקַת מְעֻשֶּׂרֶת. שֶׁמָּא הֶחָבֵר עַל הַתְּנָאִים שֶׁבְּלִבּוֹ הוּא סוֹמֵךְ:","כְּשֵׁם שֶׁאָדָם סוֹעֵד אֵצֶל עַם הָאָרֶץ וְסוֹמֵךְ עַל תְּנָאוֹ כָּךְ הוּא צָרִיךְ לִהְיוֹת מַתְנֶה עַל בְּנוֹ וַאֲפִלּוּ הָיָה בְּנוֹ בְּמָקוֹם אַחֵר. אֲבָל אֵינוֹ צָרִיךְ לִהְיוֹת מַתְנֶה עַל אַחֵר חוּץ מִבְּנוֹ וַאֲפִלּוּ הָיָה עִמּוֹ בְּמִשְׁתֶּה. לְפִיכָךְ בֶּן חָבֵר שֶׁהָיָה מֵסֵב בְּמִשְׁתֶּה עַם הָאָרֶץ אֵין הַסְּעֻדָּה בְּחֶזְקַת מְעֻשֶּׂרֶת שֶׁמָּא אָבִיו הִתְנָה עָלָיו:","עַם הָאָרֶץ שֶׁנָּתַן מָעָה לְחָבֵר וְאָמַר לוֹ קַח לִי אֲגֻדַּת יָרָק אַחַת אוֹ גְּלֻסְקָא אַחַת לוֹקֵחַ לוֹ סְתָם וּפָטוּר מִלְּעַשֵּׂר. וְאִם הֶחֱלִיף אֶת הַמָּעָה חַיָּב לְעַשֵּׂר וְאַחַר כָּךְ יָבִיא לוֹ. וְאִם פֵּרֵשׁ הֶחָבֵר וְלֹא לְקָחָן סְתָם אֶלָּא אָמַר לַחֶנְוָנִי אֲגֻדָּה זוֹ שֶׁאֲנִי לוֹקֵחַ מִמְּךָ לַחֲבֵרִי אֲנִי קוֹנֶה אוֹתָהּ וְזוֹ לְעַצְמִי אֲנִי קוֹנֶה אוֹתָהּ. זוֹ שֶׁלָּקַח לְעַצְמוֹ חַיָּב לְעַשְּׂרָהּ. וְזוֹ שֶׁלָּקַח לַחֲבֵרוֹ אֵינוֹ צָרִיךְ לְעַשְּׂרָהּ. וְאִם נִתְעָרְבוּ אֲפִלּוּ נִתְעָרְבָה אַחַת שֶׁלּוֹ בְּמֵאָה שֶׁל חֲבֵרוֹ מְתַקֵּן הַכּל דְּמַאי. וְאַחַר כָּךְ יִתֵּן לַחֲבֵרוֹ שֶׁשְּׁלָחוֹ לִקַּח לוֹ:","חֲמִשָּׁה שֶׁאָמְרוּ לְאֶחָד צֵא וְהָבֵא לָנוּ חָמֵשׁ אֲגֻדּוֹת שֶׁל יָרָק. וְהֵבִיא לְכָל אֶחָד וְאֶחָד בִּפְנֵי עַצְמוֹ. חֲבֵרִים שֶׁבָּהֶן אֵין צְרִיכִין לְעַשֵּׂר אֶלָּא עַל חֶלְקָן בִּלְבַד. הֵבִיא לָהֶן בְּעִרְבּוּב חֲבֵרִים שֶׁבָּהֶם צְרִיכִין לְעַשֵּׂר הַכּל:","עַם הָאָרֶץ שֶׁאָמַר לְחָבֵר צֵא וְלַקֵּט לִי תְּאֵנִים מִתְּאֵנָתִי אוֹכֵל מֵהֶן הֶחָבֵר עַרְאַי וּמְעַשְּׂרָן [דְּמַאי]. וְאִם אָמַר הֶחָבֵר לְעַם הָאָרֶץ לִלְקֹט לוֹ וְשָׁמַע חָבֵר אַחֵר זֶה הָאַחֵר אוֹכֵל וְאֵינוֹ צָרִיךְ לְעַשֵּׂר שֶׁאֵין הֶחָבֵר מוֹצִיא דָּבָר שֶׁאֵינוֹ מְתֻקָּן מִתַּחַת יָדוֹ וְחֶזְקָתוֹ שֶׁהִפְרִישׁ עָלֶיהָ מִמָּקוֹם אַחֵר. אַף עַל פִּי שֶׁלֹּא נֶחְשְׁדוּ חֲבֵרִים לִתְרֹם שֶׁלֹּא מִן הַמֻּקָּף, כְּדֵי לְסַלֵּק הַמִּכְשׁוֹל מִלִּפְנֵי עַם הָאָרֶץ תּוֹרְמִין:","מֻתָּר לְהַאֲכִיל אֶת הָעֲנִיִּים וְאֶת הָאוֹרְחִים דְּמַאי וְצָרִיךְ לְהוֹדִיעָן. וְהֶעָנִי עַצְמוֹ וְהָאוֹרֵחַ אִם רָצוּ לְתַקֵּן מְתַקְּנִין:","גַּבָּאֵי צְדָקָה גּוֹבִין סְתָם מִכָּל אָדָם וּמְחַלְּקִים סְתָם וְהָרוֹצֶה לְתַקֵּן יְתַקֵּן:","רוֹפֵא חָבֵר שֶׁהָיָה מַאֲכִיל לְחוֹלֵה עַם הָאָרֶץ מִפֵּרוֹת עַם הָאָרֶץ נוֹתֵן לְתוֹךְ יָדוֹ אֲבָל לֹא לְתוֹךְ פִּיו. וְאִם הָיָה הַדְּמַאי שֶׁל רוֹפֵא אֲפִלּוּ לְתוֹךְ יָדוֹ לֹא יִתֵּן. וְכֵן אִם יָדַע שֶׁהוּא טֶבֶל וַדַּאי אֲפִלּוּ לְתוֹךְ יָדוֹ אָסוּר:"],"Mishneh Torah, Tithes 9":["בִּימֵי יוֹחָנָן כֹּהֵן גָּדוֹל שֶׁהָיָה אַחַר שִׁמְעוֹן הַצַּדִּיק שָׁלְחוּ בֵּית דִּין הַגָּדוֹל וּבָדְקוּ בְּכָל גְּבוּל יִשְׂרָאֵל וּמָצְאוּ שֶׁהַכּל זְהִירִים בִּתְרוּמָה גְּדוֹלָה וּמַפְרִישִׁין אוֹתָהּ. אֲבָל מַעֲשֵׂר רִאשׁוֹן וּמַעֲשֵׂר שֵׁנִי וּמַעֲשַׂר עָנִי הָיוּ עַמֵּי הָאָרֶץ מִיִּשְׂרָאֵל מְקִלִּין עַל עַצְמָן וְלֹא הָיוּ מַפְרִישִׁין אוֹתָן. לְפִיכָךְ גָּזְרוּ שֶׁלֹּא יְהֵא נֶאֱמָן עַל הַמַּעַשְׂרוֹת אֶלָּא אֲנָשִׁים נֶאֱמָנִים. אֲבָל עַמֵּי הָאָרֶץ פֵּרוֹתֵיהֶן סָפֵק וְאֵין נֶאֱמָנִין לוֹמַר מְעֵשָּׂרִין הֵן. וְזֶהוּ הַנִּקְרָא דְּמַאי:","וְהִתְקִינוּ שֶׁלֹּא יְהֵא אָדָם מַפְרִישׁ מִן הַדְּמַאי אֶלָּא תְּרוּמַת מַעֲשֵׂר מִפְּנֵי שֶׁהוּא עֲוֹן מִיתָה. וּמַעֲשֵׂר שֵׁנִי שֶׁאֵין בָּזֶה הֶפְסֵד שֶׁהֲרֵי בְּעָלָיו אוֹכְלִין אוֹתוֹ. אֲבָל מַעֲשֵׂר רִאשׁוֹן וּמַעֲשַׂר עָנִי אֵין מַפְרִישׁ מִן הַדְּמַאי מִפְּנֵי שֶׁהוּא סָפֵק וְהַמּוֹצִיא מֵחֲבֵרוֹ עָלָיו הָרְאָיָה. לְפִיכָךְ אוֹמֵר לַלֵּוִי אוֹ לֶעָנִי הָבֵא רְאָיָה שֶׁאֵינוֹ מְעֵשָּׂר וְטֹל מַעַשְׂרוֹת:","אַף עַל פִּי שֶׁאֵין מַפְרִישִׁין מַעֲשַׂר עָנִי מִן הַדְּמַאי צָרִיךְ לִקְרוֹת לוֹ שֵׁם וְאֵינוֹ מַפְרִישׁ וְאוֹמֵר עִשּׂוּר מַה שֶּׁיֵּשׁ כָּאן מַעֲשַׂר עָנִי כְּדֵי לִקְבֹּעַ מַעֲשֵׂר שֵׁנִי שֶׁמַּעֲשַׂר עָנִי בִּשְׁלִישִׁית וְשִׁשִּׁית בִּמְקוֹם מַעֲשֵׂר שֵׁנִי שֶׁל שְׁאָר שְׁנֵי הַשָּׁבוּעַ:","כְּשֶׁמַּפְרִישִׁין מִן הַדְּמַאי תְּרוּמַת מַעֲשֵׂר וּמַעֲשֵׂר שֵׁנִי אֵין מְבָרְכִין עֲלֵיהֶן לְפִי שֶׁהוּא סָפֵק. לְפִיכָךְ מֻתָּר לְהַפְרִישׁ כְּשֶׁהוּא עֵרוֹם:","כֵּיצַד מְעַשְּׂרִין אֶת הַדְּמַאי. מַפְרִישׁ כְּדֵי תְּרוּמַת מַעֲשֵׂר שֶׁהוּא אֶחָד מִמֵּאָה מִן הַכּל וּמַנִּיחָהּ בְּצַד הַפֵּרוֹת וְאוֹמֵר זֶה מַעֲשֵׂר וּשְׁאָר מַעֲשֵׂר סָמוּךְ לוֹ. וְאַחַר כָּךְ אוֹמֵר זֶה שֶׁאָמַרְתִּי עָלָיו שֶׁהוּא מַעֲשֵׂר הֲרֵי הוּא תְּרוּמַת מַעֲשֵׂר עַל שְׁאָר הַמַּעֲשֵׂר הַסָּמוּךְ לוֹ. וְנוֹטֵל אוֹתָהּ וְנוֹתְנָהּ לַכֹּהֵן שֶׁאֵינוֹ רַשַּׁאי לְהַפְרִישׁ תְּרוּמַת מַעֲשֵׂר קֹדֶם הַמַּעֲשֵׂר לְכַתְּחִלָּה. וְאַחַר כָּךְ מַפְרִישׁ מַעֲשֵׂר שֵׁנִי:","וּמֻתָּר לְהַפְרִישׁ מַעֲשֵׂר שֵׁנִי קֹדֶם הָרִאשׁוֹן בִּדְמַאי. וְאִם רָצָה אוֹמֵר מַעֲשֵׂר שֵׁנִי שֶׁל פֵּרוֹת אֵלּוּ בִּצְפוֹנָם אוֹ בִּדְרוֹמָם וַהֲרֵי הוּא מְחֻלָּל עַל הַמָּעוֹת. וְכֵן הַלּוֹקֵחַ כִּכָּר מִן הַנַּחְתּוֹם מַפְרִישׁ מִמֶּנָּה כְּדֵי תְּרוּמַת מַעֲשֵׂר וְחַלָּה וְאוֹמֵר אֶחָד מִמֵּאָה מִמַּה שֶּׁיֵּשׁ כָּאן הֲרֵי הוּא מַעֲשֵׂר וּשְׁאָר מַעֲשֵׂר סָמוּךְ לוֹ וְזֶה שֶׁעָשִׂיתִי מַעֲשֵׂר עָשׂוּי תְּרוּמַת מַעֲשֵׂר עַל הַשְּׁאָר הַסָּמוּךְ לוֹ וְהַיֶּתֶר עַל אֶחָד מִמֵּאָה שֶׁיֵּשׁ בָּזֶה שֶׁהִפְרַשְׁתִּי הֲרֵי הוּא חַלָּה וּמַעֲשֵׂר שֵׁנִי בִּצְפוֹנָהּ אוֹ בִּדְרוֹמָהּ וַהֲרֵי הוּא מְחֻלָּל עַל הַמָּעוֹת וְאוֹכֵל:","וְכֵן הַמַּזְמִין אֶת חֲבֵרוֹ שֶׁיֹּאכַל אֶצְלוֹ וְהוּא אֵינוֹ מַאֲמִינוֹ עַל הַמַּעַשְׂרוֹת אוֹמֵר מֵעֶרֶב שַׁבָּת מַה שֶּׁאֲנִי עָתִיד לְהַפְרִישׁ לְמָחָר הֲרֵי הוּא מַעֲשֵׂר וּשְׁאָר מַעֲשֵׂר סָמוּךְ לוֹ. וְזֶה שֶׁעָשִׂיתִי מַעֲשֵׂר עָשׂוּי תְּרוּמַת מַעֲשֵׂר עַל שְׁאָר הַסָּמוּךְ לוֹ וּמַעֲשֵׂר שֵׁנִי בִּצְפוֹנוֹ אוֹ בִּדְרוֹמוֹ וַהֲרֵי הוּא מְחֻלָּל עַל הַמָּעוֹת. מִפְּנֵי שֶׁמֻּתָּר לְאָדָם לְהַתְנוֹת תְּנָאִים אֵלּוּ עַל הַדְּמַאי אַף עַל פִּי שֶׁאֵינוֹ בִּרְשׁוּתוֹ. אֲבָל בְּוַדַּאי אֵינוֹ מַתְנֶה אֶלָּא עַל דָּבָר שֶׁבִּרְשׁוּתוֹ:","כֵּיצַד. הָיוּ לוֹ מֵאָה תְּאֵנִים שֶׁל טֶבֶל בְּבֵיתוֹ וְהוּא בְּבֵית הַמִּדְרָשׁ אוֹ בַּשָּׂדֶה וּמִתְיָרֵא שֶׁמָּא תֶּחְשַׁךְ וְאֵינוֹ יָכוֹל לְעַשֵּׂר בְּשַׁבָּת אוֹמֵר שְׁנֵי תְּאֵנִים שֶׁאֲנִי עָתִיד לְהַפְרִישׁ הֲרֵי הֵן תְּרוּמָה. וְעֶשֶׂר שֶׁאֲנִי מַפְרִישׁ אַחֲרֵיהֶן מַעֲשֵׂר רִאשׁוֹן. תֵּשַׁע שֶׁאֲנִי מַפְרִישׁ אַחֲרֵיהֶן מַעֲשֵׂר שֵׁנִי. וּלְמָחָר מַפְרִישׁ וְאוֹכֵל:","וְצָרִיךְ לִרְחשׁ בִּשְׂפָתָיו בְּשָׁעָה שֶׁמַּפְרִישׁ זוֹ אַחַר זוֹ וְאֵינוֹ כִּמְתַקֵּן בְּשַׁבָּת שֶׁהֲרֵי הִקְדִּים תְּנָאוֹ. וְטֶבֶל שֶׁיֵּשׁ עָלָיו תְּנַאי זֶה מֻתָּר לְטַלְטְלוֹ בְּשַׁבָּת קֹדֶם שֶׁיַּפְרִישׁ. וְנוֹתֵן עֵינָיו בְּצַד זֶה וְאוֹכֵל אֶת הַשְּׁאָר:","נָתַן לוֹ עַם הָאָרֶץ כּוֹס לִשְׁתּוֹתוֹ אוֹמֵר מַה שֶּׁאֲנִי עָתִיד לְשַׁיֵּר בְּשׁוּלֵי הַכּוֹס הֲרֵי הוּא מַעֲשֵׂר וּשְׁאָר מַעֲשֵׂר סָמוּךְ לוֹ וְזֶה שֶׁעָשִׂיתִי מַעֲשֵׂר עָשׂוּי תְּרוּמַת מַעֲשֵׂר עַל הַשְּׁאָר הַסָּמוּךְ לוֹ וּמַעֲשֵׂר שֵׁנִי בְּפִי הַכּוֹס וַהֲרֵי הוּא מְחֻלָּל עַל הַמָּעוֹת וְשׁוֹתֶה וּמַנִּיחַ כְּדֵי תְּרוּמַת מַעֲשֵׂר בְּשׁוּלֵי הַכּוֹס:","וְכֵן אִם זִמְּנוֹ חֲבֵרוֹ לִשְׁתּוֹת בְּשַׁבָּת מַתְנֶה כִּתְנַאי זֶה מֵעֶרֶב שַׁבָּת עַל כָּל מַה שֶּׁיִּרְצֶה שֶׁיִּסְעֹד אֶצְלוֹ. וְכֵן פּוֹעֵל שֶׁאֵינוֹ מַאֲמִין לְבַעַל הַבַּיִת נוֹטֵל גְּרוֹגֶרֶת אַחַת וְאוֹמֵר זוֹ וְתֵשַׁע הַבָּאוֹת אַחֲרֶיהָ עֲשׂוּיוֹת מַעֲשֵׂר עַל הַמֵּאָה שֶׁאֲנִי עָתִיד לֶאֱכל וְזוֹ הָאַחַת תְּרוּמַת מַעֲשֵׂר עַל הָעֶשֶׂר הַבָּאוֹת אַחֲרֶיהָ וּמַעֲשֵׂר שֵׁנִי הוּא הָעֶשֶׂר הָאַחֲרוֹנוֹת וַהֲרֵי הוּא מְחֻלָּל עַל הַמָּעוֹת וְנוֹתֵן הַגְּרוֹגֶרֶת שֶׁהִפְרִישׁ לַכֹּהֵן. וְהַפּוֹעֵל מַפְרִישׁ לְעַצְמוֹ דְּמֵי מַעֲשֵׂר שֵׁנִי. שֶׁתְּנַאי בֵּית דִּין הוּא שֶׁתִּהְיֶה תְּרוּמַת מַעֲשֵׂר מִשֶּׁל בַּעַל הַבַּיִת וּמַעֲשֵׂר שֵׁנִי מִשֶּׁל פּוֹעֵל:","הַנַּחְתּוֹמִים לֹא חִיְּבוּם חֲכָמִים לְהַפְרִישׁ מַעֲשֵׂר שֵׁנִי מִן הַדְּמַאי אֶלָּא תְּרוּמַת מַעֲשֵׂר בִּלְבַד כְּדֵי שֶׁיַּפְרִישֶׁנָּה בְּטָהֳרָה עִם הַחַלָּה. וְהַלּוֹקֵחַ מַפְרִישׁ מַעֲשֵׂר שֵׁנִי. בַּמֶּה דְּבָרִים אֲמוּרִים בְּמוֹכֵר בַּחֲנוּתוֹ אוֹ עַל פֶּתַח חֲנוּתוֹ. אֲבָל הַמּוֹכֵר לְפַלְטֵר אוֹ בַּחֲנוּת הַסְּמוּכָה לְפַלְטֵר חַיָּב לְהַפְרִישׁ אַף מַעֲשֵׂר שֵׁנִי:","שְׁנַיִם שֶׁבָּצְרוּ כַּרְמֵיהֶן בְּתוֹךְ גַּת אַחַת וְהָאֶחָד מֵהֶם אֵינוֹ נֶאֱמָן עַל הַמַּעַשְׂרוֹת. אַף עַל פִּי שֶׁעִשֵּׂר זֶה הַנֶּאֱמָן עַל חֶלְקוֹ כְּשֶׁהוּא נוֹטֵל חֶלְקוֹ מִן הַיַּיִן חַיָּב לְהַפְרִישׁ מִמֶּנּוּ מַעֲשֵׂר דְּמַאי עַל חֵלֶק עַם הָאָרֶץ. כֵּיצַד. הָיוּ מֶחֱצָה לְמֶחֱצָה וְנוֹטֵל בְּחֶצְיוֹ מָאתַיִם לוֹג יַיִן הֲרֵי זֶה מַפְרִישׁ מִמֶּנּוּ לוֹג אֶחָד תְּרוּמַת מַעֲשֵׂר וְעֶשֶׂר מַעֲשֵׂר שֵׁנִי כְּנֶגֶד הַמֵּאָה לוֹג שֶׁהֲרֵי הִפְרִישׁ הַמַּעֲשֵׂר שֶׁל וַדַּאי תְּחִלָּה עַל חֲצִי כָּל שֶׁדְּרָכוֹ בַּגַּת. וְכֵן אִם הָיָה שְׁלִישׁ אוֹ רְבִיעַ מַפְרִישׁ לְפִי חֶשְׁבּוֹן:"],"Mishneh Torah, Transmission of the Oral Law 13":["וְכֵן כָּל אֶחָד וְאֶחָד כּוֹתֵב לְעַצְמוֹ כְּפִי כּוֹחוֹ, מִבֵּאוּר הַתּוֹרָה וּמֵהִלְכּוֹתֶיהָ כְּמוֹ שֶׁשָּׁמַע, וּמִדְּבָרִים שֶׁנִּתְחַדְּשׁוּ בְּכָל דּוֹר וָדוֹר, בְּדִינִים שֶׁלֹּא לְמָדוּם מִפִּי הַשְּׁמוּעָה אֵלָא בְּמִדָּה מִשְּׁלוֹשׁ עֶשְׂרֵה מִדּוֹת וְהִסְכִּימוּ עֲלֵיהֶן בֵּית דִּין הַגָּדוֹל. וְכֵן הָיָה הַדָּבָר תָּמִיד, עַד רַבֵּנוּ הַקָּדוֹשׁ."],"Mishneh Torah, Transmission of the Oral Law 24":["וְעִנְיַן שְׁנֵי הַתַּלְמוּדִין – הוּא פֵּרוּשׁ דִּבְרֵי הַמִּשְׁנָה וּבֵאוּר עֲמוּקוֹתֶיהָ, וּדְבָרִים שֶׁנִּתְחַדְּשׁוּ בְּכָל בֵּית דִּין וּבֵית דִּין מִיְּמוֹת רַבֵּנוּ הַקָּדוֹשׁ וְעַד חִבּוּר הַתַּלְמוּד. וּמִשְּׁנֵי הַתַּלְמוּדִין, וּמִן הַתּוֹסֶפְתָּא, וּמִסִּפְרָא וּמִסִּפְרֵי, וּמִן הַתּוֹסֶפְתּוֹת – מִכֻּלָּם יִתְבָּאַר הָאָסוּר וְהַמֻּתָּר, וְהַטָּמֵא וְהַטָּהוֹר, וְהַחַיָּב וְהַפָּטוּר, וְהַכָּשֵׁר וְהַפָּסוּל, כְּמוֹ שֶׁהִעְתִּיקוּ אִישׁ מִפִּי אִישׁ מִפִּי מֹשֶׁה מִסִּינַי."],"Mishneh Torah, Transmission of the Oral Law 35":["הוֹאִיל וְכָל אוֹתָן הַדְּבָרִים שֶׁבַּתַּלְמוּד הִסְכִּימוּ עֲלֵיהֶם כָּל יִשְׂרָאֵל, וְאוֹתָן הַחֲכָמִים שֶׁהִתְקִינוּ אוֹ שֶׁגָּזְרוּ אוֹ שֶׁהִנְהִיגוּ אוֹ שֶׁדָּנוּ דִּין וְלִמְּדוּ שֶׁהַמִּשְׁפָּט כָּךְ הוּא הֶם כָּל חַכְמֵי יִשְׂרָאֵל אוֹ רֻבָּן, וְהֶם שֶׁשָּׁמְעוּ הַקַּבָּלָה בְּעִיקְרֵי הַתּוֹרָה כֻּלָּהּ, אִישׁ מִפִּי אִישׁ עַד מֹשֶׁה רַבֵּנוּ."],"Mishneh Torah, Transmission of the Oral Law 5":["וּזְקֵנִים רַבִּים קִבְּלוּ מִיְּהוֹשׁוּעַ, וְקִבַּל עֵלִי מִן הַזְּקֵנִים וּמִפִּינְחָס; וּשְׁמוּאֵל קִבַּל מֵעֵלִי וּבֵית דִּינוֹ, וְדָוִיד קִבַּל מִשְּׁמוּאֵל וּבֵית דִּינוֹ. וַאֲחִיָּה הַשִּׁילוֹנִי, מִיּוֹצְאֵי מִצְרַיִם הָיָה וְלֵוִי הָיָה, וְשָׁמַע מִמֹּשֶׁה, וְהָיָה קָטָן בִּימֵי מֹשֶׁה; וְהוּא קִבַּל מִדָּוִיד וּבֵית דִּינוֹ."],"Mishneh Torah, Trespass 8":["הַפּוֹעֲלִים שֶׁהֵן עוֹשִׂין בְּהֶקְדֵּשׁ אַף עַל פִּי שֶׁפָּסְקוּ עִמָּהֶן מְזוֹנוֹת לֹא יֹאכְלוּ מִגְּרוֹגָרוֹת שֶׁל הֶקְדֵּשׁ וְאִם אָכְלוּ מָעֲלוּ. אֶלָּא הַהֶקְדֵּשׁ נוֹתֵן לָהֶם דְּמֵי מְזוֹנוֹת:","הַדָּשׁ כַּרְשִׁינֵי הֶקְדֵּשׁ הֲרֵי זֶה חוֹסֵם אֶת הַפָּרָה. שֶׁנֶּאֱמַר (דברים כה ד) \"לֹא תַחְסֹם שׁוֹר בְּדִישׁוֹ\" דַּיִשׁ הָרָאוּי לוֹ:","אֵין מְחַלְּלִין אֶת הַהֶקְדֵּשׁ עַל הַמְּלָאכָה אֶלָּא עַל הַמָּעוֹת. כֵּיצַד. אֻמָּן שֶׁעָשָׂה מְלָאכָה בְּהֶקְדֵּשׁ בְּמָנֶה אֵין נוֹתְנִין לוֹ בֶּהֱמַת הֶקְדֵּשׁ אוֹ טַלִּית הֶקְדֵּשׁ בִּשְׂכָרוֹ עַד שֶׁמְּחַלְּלִין אוֹתָן עַל הַמָּעוֹת. וְאַחַר שֶׁיֵּעָשׂוּ חֻלִּין נוֹתְנִין אוֹתָן לָאֻמָּן בִּשְׂכָרוֹ אִם רָצוּ. וְחוֹזְרִין וְלוֹקְחִין מִמֶּנּוּ בְּהֵמָה מִתְּרוּמַת הַלִּשְׁכָּה:","כְּשֶׁבּוֹנִין בַּמִּקְדָּשׁ אֵין לוֹקְחִין עֵצִים וַאֲבָנִים מִן הַהֶקְדֵּשׁ וְלֹא בּוֹנִין אֶת הַבִּנְיָן עַל דַּעַת שֶׁהוּא קֹדֶשׁ אֶלָּא בּוֹנִין הַכּל מִן הַחל. גְּזֵרָה שֶׁמָּא יֵהָנֶה בְּצֵל הַבִּנְיָן אוֹ יִשָּׁעֵן עַל אֶבֶן אוֹ קוֹרָה בִּשְׁעַת מְלָאכָה. וְאַחַר שֶׁיֻּשְׁלַם הַבִּנְיָן מְחַלְּלִין מְעוֹת הַהֶקְדֵּשׁ עַל הַבִּנְיָן. וְאִם צָרְכוּ הַגִּזְבָּרִין לְעֵצִים לַקֹּדֶשׁ לְאוֹתוֹ הַיּוֹם בִּלְבַד לוֹקְחִין אוֹתָן מִמְּעוֹת הַהֶקְדֵּשׁ שֶׁהֲרֵי אֵינָן מִתְאַחֲרִין יָמִים כְּדֵי שֶׁנָּחוּשׁ לָהֶן שֶׁמָּא יִשָּׁעֵן אָדָם עֲלֵיהֶן וְיִמְעל:","כְּשֶׁפּוֹסְקִין עִם הָאֻמָּנִין לִבְנוֹת בַּמִּקְדָּשׁ וּבָעֲזָרוֹת. פּוֹסְקִין עִמָּהֶן כָּךְ וְכָךְ אַמָּה בְּכָךְ וְכָךְ סֶלַע בְּאַמָּה בַּת עֶשְׂרִים אֶצְבַּע. וּכְשֶׁמּוֹשְׁחִין לָהֶן מַה שֶּׁבָּנוּ מוֹשְׁחִין וּמְחַשְּׁבִין לָהֶן בְּאַמָּה גְּדוֹלָה בַּת עֶשְׂרִים וְאַרְבַּע אֶצְבָּעוֹת כְּדֵי שֶׁלֹּא יָבוֹאוּ לִידֵי מְעִילָה מִפְּנֵי שֶׁאֵין מְדַקְדְּקִין בִּמְשִׁיחָה:","תְּנַאי בֵּית דִּין שֶׁיִּהְיוּ הַכֹּהֲנִים נֵאוֹתִין בַּמֶּלַח וּבָעֵצִים בַּאֲכִילַת קָרְבָּנוֹת שֶׁאוֹכְלִין בְּחֶלְקָן. אֲבָל לֹא יִתְּנוּ מֶלַח הַמִּקְדָּשׁ בְּחֻלִּין שֶׁלָּהֶן:","מֶלַח שֶׁעַל גַּבֵּי הָאֵיבָר מוֹעֲלִין בּוֹ. שֶׁעַל גַּבֵּי הַכֶּבֶשׁ וְשֶׁעַל רֹאשׁ הַמִּזְבֵּחַ אֵין מוֹעֲלִין בּוֹ:","רָאוּי לָאָדָם לְהִתְבּוֹנֵן בְּמִשְׁפְּטֵי הַתּוֹרָה הַקְּדוֹשָׁה וְלֵידַע סוֹף עִנְיָנָם כְּפִי כֹּחוֹ. וְדָבָר שֶׁלֹּא יִמְצָא לוֹ טַעַם וְלֹא יֵדַע לוֹ עִלָּה אַל יְהִי קַל בְּעֵינָיו וְלֹא יַהֲרֹס לַעֲלוֹת אֶל ה' פֶּן יִפְרֹץ בּוֹ. וְלֹא תְּהֵא מַחֲשַׁבְתּוֹ בּוֹ כְּמַחְשַׁבְתּוֹ בִּשְׁאָר דִּבְרֵי הַחל. בּוֹא וּרְאֵה כַּמָּה הֶחְמִירָה תּוֹרָה בִּמְעִילָה. וּמָה אִם עֵצִים וַאֲבָנִים וְעָפָר וָאֵפֶר כֵּיוָן שֶׁנִּקְרָא שֵׁם אֲדוֹן הָעוֹלָם עֲלֵיהֶם בִּדְבָרִים בִּלְבַד נִתְקַדְּשׁוּ וְכָל הַנּוֹהֵג בָּהֶן מִנְהַג חֹל מָעַל בָּהּ וַאֲפִלּוּ הָיָה שׁוֹגֵג צָרִיךְ כַּפָּרָה. קַל וָחֹמֶר לְמִצְוֹת שֶׁחָקַק לָנוּ הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא יִבְעַט הָאָדָם בָּהֶן מִפְּנֵי שֶׁלֹּא יֵדַע טַעְמָן. וְלֹא יְחַפֶּה דְּבָרִים אֲשֶׁר לֹא כֵּן עַל הַשֵּׁם וְלֹא יַחְשֹׁב בָּהֶן מַחְשַׁבְתּוֹ כְּדִבְרֵי הַחל. הֲרֵי נֶאֱמַר בַּתּוֹרָה (ויקרא יט לז) (ויקרא כ כב) \"וּשְׁמַרְתֶּם אֶת כָּל חֻקֹּתַי וְאֶת כָּל מִשְׁפָּטַי וַעֲשִׂיתֶם אֹתָם\". אָמְרוּ חֲכָמִים לִתֵּן שְׁמִירָה וַעֲשִׂיָּה לַחֻקִּים כַּמִּשְׁפָּטִים. וְהָעֲשִׂיָּה יְדוּעָה וְהִיא שֶׁיַּעֲשֶׂה הַחֻקִּים. וְהַשְּׁמִירָה שֶׁיִּזָּהֵר בָּהֶן וְלֹא יְדַמֶּה שֶׁהֵן פְּחוּתִין מִן הַמִּשְׁפָּטִים. וְהַמִּשְׁפָּטִים הֵן הַמִּצְוֹת שֶׁטַּעְמָן גָּלוּי וְטוֹבַת עֲשִׂיָּתָן בָּעוֹלָם הַזֶּה יְדוּעָה כְּגוֹן אִסּוּר גֵּזֶל וּשְׁפִיכוּת דָּמִים וְכִבּוּד אָב וָאֵם. וְהַחֻקִּים הֵן הַמִּצְוֹת שֶׁאֵין טַעְמָן יָדוּעַ. אָמְרוּ חֲכָמִים חֻקִּים חַקֹּתִי לְךָ וְאֵין לְךָ רְשׁוּת לְהַרְהֵר בָּהֶן. וְיִצְרוֹ שֶׁל אָדָם נוֹקְפוֹ בָּהֶן וְאֻמּוֹת הָעוֹלָם מְשִׁיבִין עֲלֵיהֶן כְּגוֹן אִסּוּר בְּשַׂר חֲזִיר וּבָשָׂר בְּחָלָב וְעֶגְלָה עֲרוּפָה וּפָרָה אֲדֻמָּה וְשָׂעִיר הַמִּשְׁתַּלֵּחַ. וְכַמָּה הָיָה דָּוִד הַמֶּלֶךְ מִצְטַעֵר מִן הַמִּינִים וּמִן הָעַכּוּ\"ם שֶׁהָיוּ מְשִׁיבִין עַל הַחֻקִּים. וְכָל זְמַן שֶׁהָיוּ רוֹדְפִין אוֹתוֹ בִּתְשׁוּבוֹת הַשֶּׁקֶר שֶׁעוֹרְכִין לְפִי קֹצֶר דַּעַת הָאָדָם הָיָה מוֹסִיף דְּבֵקוּת בַּתּוֹרָה. שֶׁנֶּאֱמַר (תהילים קיט סט) \"טָפְלוּ עָלַי שֶׁקֶר זֵדִים אֲנִי בְּכָל לֵב אֶצֹּר פִּקּוּדֶיךָ\". וְנֶאֱמַר שָׁם בָּעִנְיָן (תהילים קיט פו) \"כָּל מִצְוֹתֶיךָ אֱמוּנָה שֶׁקֶר רְדָפוּנִי עָזְרֵנִי\". וְכָל הַקָּרְבָּנוֹת כֻּלָּן מִכְּלַל הַחֻקִּים הֵן. אָמְרוּ חֲכָמִים שֶׁבִּשְׁבִיל עֲבוֹדַת הַקָּרְבָּנוֹת הָעוֹלָם עוֹמֵד. שֶׁבַּעֲשִׂיַּת הַחֻקִּים וְהַמִּשְׁפָּטִים זוֹכִין הַיְשָׁרִים לְחַיֵּי הָעוֹלָם הַבָּא. וְהִקְדִּימָה תּוֹרָה צִוּוּי עַל הַחֻקִּים. שֶׁנֶּאֱמַר (ויקרא יח ה) \"וּשְׁמַרְתֶּם אֶת חֻקֹּתַי וְאֶת מִשְׁפָּטַי אֲשֶׁר יַעֲשֶׂה אֹתָם הָאָדָם וָחַי בָּהֶם\"."],"Mishneh Torah, Vessels 2":["הָעוֹשֶׂה כְּלִי קִבּוּל מִכָּל מָקוֹם הֲרֵי זֶה מְקַבֵּל טֻמְאָה בְּכָל שֶׁהוּא מִן הַתּוֹרָה. וְאֵין לִכְלִי קִבּוּל שִׁעוּר. וְהוּא שֶׁיַּעֲשֶׂה דָּבָר שֶׁל קַיָּמָא שֶׁאֶפְשָׁר שֶׁיַּעֲמֹד. כֵּיצַד. הָעוֹשֶׂה כְּלִי מִן הָעוֹר הַמַּצָּה שֶׁלֹּא נִתְעַבֵּד כְּלָל. אוֹ מִן הַנְּיָר אַף עַל פִּי שֶׁאֵין הַנְּיָר מְקַבֵּל טֻמְאָה. אוֹ מִקְּלִפַּת הָרִמּוֹן וְהָאֱגוֹז וְהָאַלּוֹן אֲפִלּוּ חֲקָקוּם הַתִּינוֹקוֹת לָמֹד בָּהֶן אֶת הֶעָפָר. אוֹ שֶׁהִתְקִינוּם לְכַף מֹאזְנַיִם. הֲרֵי אֵלּוּ מְקַבְּלִין טֻמְאָה. שֶׁתִּינוֹק חֵרֵשׁ שׁוֹטֶה וְקָטָן יֵשׁ לָהֶן מַעֲשֶׂה אַף עַל פִּי שֶׁאֵין לָהֶן מַחֲשָׁבָה. אֲבָל הָעוֹשֶׂה כֵּלִים מִן הַלֶּפֶת וְהָאֶתְרוֹג וְהַדְּלַעַת הַיְבֵשִׁים שֶׁחֲקָקָן לָמֹד בָּהֶן וְכָל כַּיּוֹצֵא בָּהֶן. הֲרֵי הֵן טְהוֹרִין לְפִי שֶׁאִי אֶפְשָׁר שֶׁיַּעַמְדוּ אֶלָּא זְמַן מוּעָט:","קְנֵה מֹאזְנַיִם וְהַמַּחַק שֶׁיֵּשׁ בָּהֶן בֵּית קִבּוּל מַתֶּכֶת. וְהָאֵסֶל שֶׁיֵּשׁ בּוֹ בֵּית קִבּוּל מָעוֹת. וְקָנֶה שֶׁל עֵץ שֶׁיֵּשׁ בּוֹ בֵּית קִבּוּל מַיִם. וּמַקֵּל שֶׁיֵּשׁ בּוֹ בֵּית קִבּוּל מְזוּזָה אוֹ מְקוֹם מַרְגָּלִית. וּמַשְׁחֶזֶת שֶׁל עֵץ שֶׁיֵּשׁ בּוֹ בֵּית קִבּוּל שֶׁמֶן. וְלוּחַ פִּנְקָס שֶׁיֵּשׁ בּוֹ בֵּית קִבּוּל שַׁעֲוָה. כָּל אֵלּוּ וְכַיּוֹצֵא בָּהֶן אַף עַל פִּי שֶׁהֵן פְּשׁוּטֵי כְּלֵי עֵץ הוֹאִיל וְיֵשׁ בָּהֶן בֵּית קִבּוּל כָּל שֶׁהוּא מְקַבְּלִין טֻמְאָה דִּין תּוֹרָה. וְאֵין טָמֵא מִן הַתּוֹרָה אֶלָּא בֵּית קִבּוּל לְבַדּוֹ שֶׁיֵּשׁ בָּהֶן וְהַמְשַׁמֵּשׁ אֶת בֵּית הַקִּבּוּל מִשְּׁאָר הַכְּלִי שֶׁבֵּית הַקִּבּוּל צָרִיךְ לוֹ. אֲבָל הַיָּתֵר עַל הַצֹּרֶךְ מִשְּׁאָר הַכְּלִי הַפָּשׁוּט טָהוֹר מִן הַתּוֹרָה וְטָמֵא מִדִּבְרֵיהֶן כְּמוֹ שֶׁבֵּאַרְנוּ:","בֵּית קִבּוּל הֶעָשׂוּי לְמַלְּאוֹתוֹ אֵינוֹ בֵּית קִבּוּל. כֵּיצַד. בְּקַעַת שֶׁל עֵץ שֶׁחוֹקְקִין בָּהּ בֵּית קִבּוּל וְתוֹקְעִין בּוֹ הַסַּדָּן שֶׁל בַּרְזֶל. אִם שֶׁל נַפָּחִים הִיא אֵינָהּ מְקַבֶּלֶת טֻמְאָה שֶׁאַף עַל פִּי שֶׁיֵּשׁ בָּהּ בֵּית קִבּוּל לֹא נַעֲשָׂה אֶלָּא לְמַלְּאוֹתוֹ. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְאִם הָיְתָה שֶׁל צוֹרְפִין הֲרֵי זוֹ מְקַבֶּלֶת טֻמְאָה מִפְּנֵי שֶׁהֵן מַגְבִּיהִין אֶת הַבַּרְזֶל בְּכָל עֵת שֶׁיִּרְצֶה וּמְקַבְּצִין אֶת שְׂפוֹת הַזָּהָב וְהַכֶּסֶף הַמִּתְקַבֶּצֶת שָׁם תַּחַת הַסַּדָּן וַהֲרֵי נַעֲשָׂה לְקַבָּלָה. וְכֵן כָּל כַּיּוֹצֵא בּוֹ:","הַכַּף הֶחָקוּק שֶׁתַּחַת רַגְלֵי הַמִּטּוֹת וְהַמִּגְדָּלוֹת וְכַיּוֹצֵא בָּהֶן אַף עַל פִּי שֶׁהוּא מְקַבֵּל טָהוֹר וְאֵין בּוֹ מִשּׁוּם כְּלִי קִבּוּל לְפִי שֶׁאֵינוֹ עָשׂוּי לְקִבּוּל אֶלָּא לִסְמֹךְ בּוֹ בִּלְבַד. שְׁפוֹפֶרֶת הַקַּשׁ מְקַבֶּלֶת טֻמְאָה כְּכָל כְּלֵי הָעֵץ שֶׁמְּקַבְּלִין טֻמְאָה אֲפִלּוּ אֵינָהּ יְכוֹלָה לְקַבֵּל אֶלָּא טִפָּה אַחַת. וּשְׁפוֹפֶרֶת הַקָּנֶה שֶׁחֲתָכָהּ לְקַבָּלָה אֵינָהּ מְקַבֶּלֶת טֻמְאָה עַד שֶׁיּוֹצִיא אֶת כָּל הַלָּבָן שֶׁבְּתוֹכָהּ. וְאִם לֹא נֶחְתְכָה לְקַבָּלָה הֲרֵי הִיא כִּפְשׁוּטֵי כְּלֵי עֵץ. אֲבָל שְׁפוֹפֶרֶת שֶׁל פָּקוּעוֹת וְכַיּוֹצֵא בָּהֶן אֵינָן כֵּלִים אֶלָּא כָּאֳכָלִין הֵן חֲשׁוּבִין:","שְׁפוֹפֶרֶת שֶׁחֲתָכָהּ וְנָתַן בָּהּ אֶת הַמְּזוּזָה וְאַחַר כָּךְ נְתָנָהּ בְּכֹתֶל אֲפִלּוּ נָתְנָה שֶׁלֹּא כְּדֶרֶךְ קַבָּלָתָהּ מְקַבֶּלֶת טֻמְאָה. קְבָעָהּ בַּכֹּתֶל אִם קְבָעָהּ כְּדֶרֶךְ קַבָּלָתָהּ הֲרֵי זוֹ מְקַבֶּלֶת טֻמְאָה. שֶׁלֹּא כְּדֶרֶךְ קַבָּלָתָהּ טְהוֹרָה. נָתַן הַשְּׁפוֹפֶרֶת בַּכֹּתֶל וְאַחַר כָּךְ נָתַן בָּהּ הַמְּזוּזָה אִם הָיְתָה כְּדֶרֶךְ קַבָּלָתָהּ הֲרֵי זוֹ מְקַבֶּלֶת טֻמְאָה. שֶׁלֹּא כְּדֶרֶךְ קַבָּלָתָהּ טְהוֹרָה. קְבָעָהּ בַּכֹּתֶל אֲפִלּוּ כְּדֶרֶךְ קַבָּלָתָהּ טְהוֹרָה:","כְּלִי שֶׁאוֹרְגִין אוֹתוֹ מִן הַנְּסָרִים אוֹ מִן הַשַּׁעַם כְּדֵי שֶׁיִּשְׁטְחוּ עָלָיו הַבְּגָדִים וְהַמֻּגְמָר מִלְּמַטָּה כְּדֵי שֶׁיִּתְבַּסְּמוּ אִם הָיָה עָשׂוּי כְּכַוֶּרֶת שֶׁאֵין לוֹ קַרְקַע טָהוֹר וְאִם הָיָה בּוֹ בֵּית קַבָּלַת כְּסוּת הֲרֵי זֶה מְקַבֵּל טֻמְאָה:","סַנְדָּל שֶׁל בְּהֵמָה שֶׁל מַתֶּכֶת טָמֵא וְשֶׁל שַׁעַם טָהוֹר שֶׁאֵין זֶה חָשׁוּב מִכְּלֵי הַקַּבָּלָה:","הַצּוֹרֵר מַרְגָּלִית בָּעוֹר וְהוֹצִיאָהּ וְנִשְׁאַר מְקוֹמָהּ עָמֹק הֲרֵי זֶה מְקַבֵּל טֻמְאָה עַד שֶׁיִּפְשֹׁט. שֶׁכָּל כְּלֵי קִבּוּל מְקַבְּלִין בְּכָל שֶׁהֵן וַהֲרֵי מְקוֹמָן כְּמוֹ כִּיס קָטָן. אֲבָל צְרוֹר הַמָּעוֹת אֵינוֹ מְקַבֵּל טֻמְאָה שֶׁאֵין עָלָיו צוּרַת כְּלִי:"],"Mishneh Torah, Vessels 5":["כָּל הַכֵּלִים אֵין מְקַבְּלִין טֻמְאָה עַד שֶׁתִּגָּמֵר מְלַאכְתָּן. וּכְלֵי עֵץ מֵאֵימָתַי מְקַבְּלִין טֻמְאָה. הַמִּטָּה וְהָעֲרִיסָה מִשֶּׁיְּשׁוּפֵם בְּעוֹר הַדָּג. גָּמַר שֶׁלֹּא לָשׁוּף מְקַבְּלִין טֻמְאָה. הַסַּלִּים שֶׁל עֵץ מִשֶּׁיַּחְסֹם שִׂפְתוֹתֵיהֶן וְיִכְרֹת עֵקְצֵי הַשָּׂרִיגִים וְהָעֵצִים הַקְּטַנִּים הַיּוֹצְאִים עַל גַּבֵּי הַסַּל. הָיוּ הַסַּלִּים שֶׁל תְּמָרָה אַף עַל פִּי שֶׁלֹּא כָּרַת הַהוּצִין מִבִּפְנִים מְקַבְּלִין טֻמְאָה שֶׁכָּךְ מְקַיְּמִין אוֹתָן. הַכַּלְכָּלָה מִשֶּׁיַּחְסֹם פִּיהָ וְיִכְרֹת הַהוּצִים וְיִגְמֹר אֶת הַתְּלוּיוֹת. בֵּית הַכּוֹסוֹת וְהַלָּגִינִין אַף עַל פִּי שֶׁלֹּא כָּרַת מִבִּפְנִים מְקַבְּלִין טֻמְאָה שֶׁכָּךְ מְקַיְּמִין אוֹתָם. הַקְּנוֹנִים הַקְּטַנִּים וְהַקְּלָתוֹת מִשֶּׁיַּחְסֹם שִׂפְתוֹתֵיהֶן וְיִכְרֹת הַהוּצִין הַיּוֹצְאִים. הַקְּנוֹנִים הַגְּדוֹלִים וְהַסְּיוֹגִים הַגְּדוֹלִים מִשֶּׁיַּעֲשֶׂה שְׁנֵי דּוֹרִים לָרֹחַב שֶׁלָּהֶן. הַנָּפָה וְהַכְּבָרָה וְכַף מֹאזְנַיִם מִשֶּׁיַּעֲשֶׂה דּוֹר אֶחָד לָרֹחַב שֶׁלָּהֶן. הַקֻפָּה מִשֶּׁיַּעֲשֶׂה שְׁתֵּי צְפִירוֹת לָרֹחַב שֶׁלָּהּ. וְהָעֲרָק מִשֶּׁיַּעֲשֶׂה בּוֹ צְפִירָה אַחַת אַף עַל פִּי שֶׁלֹּא גָּמַר גַּבֵּיהֶן מְקַבְּלִין טֻמְאָה שֶׁהֲרֵי נִרְאוּ לְמַה שֶּׁנַּעֲשׂוּ וְצוּרַת הַכְּלִי עֲלֵיהֶן. הָא לְמָה זֶה דּוֹמֶה לְבֶגֶד שֶׁנֶּאֱרַג מִקְצָתוֹ. הַמַּחְצֶלֶת מִשֶּׁיִּכְרֹת הַהוּצִין וְזֶהוּ גְּמַר מְלָאכָה. וְכָל כְּלֵי הַנְּסָרִים אֵינָן מְקַבְּלִין טֻמְאָה עַד שֶׁיִּתְחַסְּמוּ שִׂפְתוֹתֵיהֶן. גָּלְמֵי כְּלֵי עֵץ מְקַבְּלִין טֻמְאָה מִשֶּׁנַּעֲשָׂה הַכְּלִי בְּצוּרָתוֹ. אַף עַל פִּי שֶׁעָתִיד לְתָאֲרוֹ בִּשְׂרַד אוֹ לְהַשְׁווֹתוֹ בִּמְחוֹגָה אוֹ לְיַפּוֹתוֹ בַּמַּעֲצָד וְכַיּוֹצֵא בְּמַעֲשִׂים אֵלּוּ וַעֲדַיִן הוּא גּלֶם הוֹאִיל וְאֵינוֹ מְחֻסַּר חֲקִיקָה וַהֲרֵי הִשְׁלִים חֲפִירָתוֹ הֲרֵי זֶה מְקַבֵּל טֻמְאָה. וְכָל גָּלְמֵי כְּלֵי עֵץ מְקַבְּלִין טֻמְאָה חוּץ מִשֶּׁל אֶשְׁכְּרוֹעַ שֶׁאֵין הַכְּלִי מִמֶּנּוּ חָשׁוּב כְּלִי עַד שֶׁיִּתְיַפֶּה. וְקָרוֹב בְּעֵינַי שֶׁכְּלֵי עֶצֶם כִּכְלֵי אֶשְׁכְּרוֹעַ וְאֵין גָּלְמֵיהֶן מְקַבְּלִין טֻמְאָה. כְּלִי עֵץ שֶׁאֵין עָלָיו צוּרַת כְּלִי אַף עַל פִּי שֶׁמִּשְׁתַּמְּשִׁין בּוֹ אֵינוֹ מְקַבֵּל טֻמְאָה. אֲרֻבּוֹת שֶׁל נַחְתּוֹמִין שֶׁסּוֹדְרִים עֲלֵיהֶן הַחַלּוֹת כְּשֶׁהֵן בָּצֵק מִתְטַמְּאוֹת שֶׁהֲרֵי צוּרַת הַכְּלִי עֲלֵיהֶן. וְשֶׁל בַּעֲלֵי בָּתִּים אֵינָן מְקַבְּלִין טֻמְאָה. וְאִם צְבָעָן בְּסִקְרָא אוֹ בְּכַרְכּוֹם וְכַיּוֹצֵא בָּהֶן מִתְטַמְּאוֹת שֶׁהֲרֵי נַעֲשֵׂית לָהֶן צוּרַת כְּלִי. סְרוֹד שֶׁל נַחְתּוֹמִין שֶׁנּוֹתְנִין בּוֹ הַמַּיִם שֶׁמְּקַטְּפִין בּוֹ טָמֵא וְשֶׁל בַּעֲלֵי בָּתִּים טָהוֹר. וְאִם גִּפְּפוֹ מֵאַרְבַּע רוּחוֹתָיו מִתְטַמֵּא. נִפְרָץ מֵרוּחַ אַחַת טָהוֹר. וְהַלּוּחַ שֶׁעוֹרְכִין עָלָיו מִתְטַמֵּא. כְּלִי עֵץ שֶׁהַסַּלָּתִים מְרַקְּדִין עָלָיו אֶת הַסּלֶת מִתְטַמֵּא. וְשֶׁל בַּעֲלֵי בָּתִּים טָהוֹר. רַחַת הַגָּרוֹסוֹת מִתְטַמְּאָה. שֶׁל אוֹצָרוֹת טְהוֹרָה שֶׁל גִּתּוֹת מִתְטַמְּאָה וְשֶׁל גֳּרָנוֹת טְהוֹרָה. זֶה הַכְּלָל הֶעָשׂוּי לְקַבָּלָה מְקַבֵּל טֻמְאָה וְהֶעָשׂוּי לְכַנֵּס בּוֹ טָהוֹר:","כָּל הַתְּלוֹיִין טְהוֹרִין חוּץ מִתְּלוֹיֵי נָפָה שֶׁל סַלָּתִין וּתְלוֹי כְּבָרָהּ שֶׁל גֳּרָנוֹת וּתְלוֹי מַגַּל יָד וּתְלוֹי מַקֵּל הַבַּלָּשִׁין מִפְּנֵי שֶׁהֵן מְסַיְּעִין בִּשְׁעַת מְלָאכָה. זֶה הַכְּלָל הֶעָשׂוּי לְסַיְּעוֹ בִּשְׁעַת מְלָאכָה מִתְטַמֵּא לִתְלוֹת בּוֹ הַכְּלִי בִּלְבַד טָהוֹר:","נִבְלֵי הַמְשׁוֹרְרִים מִתְטַמְּאִין. נִבְלֵי בְּנֵי לֵוִי שֶׁמְּזַמְּרִין בָּהֶן בַּמִּקְדָּשׁ טְהוֹרִין. הַבִּטְנוֹן וְהַנִּקְטְמוֹן וְהָאִירוּס מִתְטַמְּאִין:","מְצוּדַת הַחֻלְדָּה מִתְטַמֵּא וְשֶׁל עַכְבָּרִים טְהוֹרָה לְפִי שֶׁאֵין לָהּ בֵּית קִבּוּל וְאֵין עָלֶיהָ צוּרַת כְּלִי:","קוֹצִין שֶׁאוֹרְגִין בָּהֶן כְּמוֹ כְּפִיפָה שֶׁמַּנִּיחִין בָּהּ הַתְּאֵנִים וְכַיּוֹצֵא בָּהֶן מִתְטַמְּאִין. וְשֶׁאוֹרְגִין בָּהֶן כְּתַבְנִית מְנוֹרָה גְּדוֹלָה שֶׁאוֹצְרִין בָּהֶן הַחִטִּין טְהוֹרָה שֶׁאֵין תּוֹרַת כְּלִי עָלֶיהָ:","עָלִין שֶׁמְּסָרְגִין אוֹתָן כְּמִין סְיָג סָבִיב לַפֵּרוֹת טָהוֹר. וְאִם עָשׂוּ סְיָג שֶׁל נְסָרִין מִתְטַמְּאִין:","חֹתֶל שֶׁל הוּצִין שֶׁמַּנִּיחִין בּוֹ הָרֹטֶב וְכַיּוֹצֵא בּוֹ אִם הוּא נוֹתֵן לְתוֹכוֹ וְנוֹטֵל מִתּוֹכוֹ מִתְטַמֵּא וְאִם אֵינוֹ יָכוֹל לִטּל מַה שֶּׁבְּתוֹכוֹ עַד שֶׁיִּקְרָעֶנּוּ אוֹ יַתִּירֶנּוּ אוֹ שֶׁחָשַׁב לֶאֱכל מַה שֶּׁבְּתוֹכוֹ וּלְזָרְקוֹ טָהוֹר. וְכֵן הַקֶּרֶן שֶׁהוּא מִשְׁתַּמֵּשׁ בָּהּ וּמַשְׁלִיכָהּ אֵינָהּ מְקַבֶּלֶת טֻמְאָה. וְאִם חָשַׁב עָלֶיהָ מְקַבֶּלֶת טֻמְאָה:","הַשּׁוֹפָר אֵינוֹ מְקַבֵּל טֻמְאָה. חֲתָכוֹ לִהְיוֹת קֶרֶן תַּשְׁמִישׁ מְקַבֵּל טֻמְאָה:","קְעָרָה שֶׁקְּבָעָהּ בְּשִׁדָּה תֵּבָה וּמִגְדָּל אִם הִיא כְּדֶרֶךְ קַבָּלָתָהּ מְקַבֶּלֶת טֻמְאָה. וְאִם קְבָעָהּ בַּדֹּפֶן שֶׁהֲרֵי אֵינָהּ מְקַבֶּלֶת עַד שֶׁמַּטִּים שִׁדָּה עַל צִדָּה הֲרֵי זוֹ מִכְּלַל הַשִּׁדָּה וּטְהוֹרָה:","הָאַקּוֹן וְהָרָטוֹב וְהַכְּלוּב שֶׁל עֵץ טְהוֹרִין:","הַמַּדָּף וְהַפַּלְצוּר וּמְצוּדַת סְכָרִים מִתְטַמְּאִין שֶׁהֲרֵי צוּרַת כְּלִי עֲלֵיהֶם:","הַסַּפְסָלִין שֶׁבַּפֻּנְדְּקָאוֹת וְשֶׁל מְלַמְּדֵי תִּינוֹקוֹת אַף עַל פִּי שֶׁהֵן נְקוּבִין וּמַכְנִיסִין בָּהֶן אֶת הָרַגְלַיִם טְהוֹרִים. קָבְעוּ בָּהֶן רַגְלַיִם בְּמַסְמֵר מְקַבְּלִין טֻמְאָה. זֶה הַכְּלָל כָּל שֶׁנִּטָּל וְאֵין רַגְלָיו נִטָּלוֹת עִמּוֹ טָהוֹר. וְכָל שֶׁנִּטַּל וְרַגְלָיו נִטָּלוֹת עִמּוֹ טָמֵא. וְאִם הָיוּ כֻּלָּן שֶׁל עֵץ אוֹ עֶצֶם מְקַבֵּל טֻמְאָה. הָיְתָה אַחַת מֵרַגְלָיו שֶׁל אֶבֶן אֵינוֹ מְקַבֵּל טֻמְאָה:"],"Mishneh Torah, Vessels of the Sanctuary and Those Who Serve Therein 7":["חֲמִשָׁה עָשָׂר מְמֻנִּין הָיוּ בַּמִּקְדָּשׁ וְכֵן מְמַנִּים לְעוֹלָם עַל כָּל דָּבָר מֵחֲמִשָּׁה עָשָׂר דְּבָרִים אֵלּוּ מְמֻנֶּה אֶחָד. וְאֵלּוּ הֵן (א) עַל הַזְּמַנִּים (ב) עַל נְעִילַת שְׁעָרִים (ג) עַל הַשּׁוֹמְרִים (ד) עַל הַמְשׁוֹרְרִים (ה) עַל הַצִּלְצָל עִם שְׁאָר כְּלֵי שִׁיר (ו) עַל הַפְּיָסוֹת (ז) עַל הַקָּנִים (ח) עַל הַחוֹתָמוֹת (ט) עַל הַנְּסָכִים (י) עַל הַחוֹלִין (יא) עַל הַמַּיִם (יב) עַל מַעֲשֵׂה לֶחֶם הַפָּנִים (יג) עַל מַעֲשֵׂה הַקְּטֹרֶת (יד) עַל מַעֲשֵׂה הַפָּרֹכֶת (טו) עַל מַעֲשֵׂה בִּגְדֵי כְּהֻנָּה:","כָּל אֶחָד וְאֶחָד מִמְּמֻנִּים אֵלּוּ תַּחַת יָדוֹ אֲנָשִׁים הַרְבֵּה כְּדֵי לְהָכִין הַמְּלָאכָה שֶׁהוּא מְמֻנֶּה עָלֶיהָ. זֶה שֶׁעַל הַזְּמַנִּים הוּא וַאֲנָשָׁיו מְשַׁמְּרִים אֶת הַזְּמַנִּים. כֵּיוָן שֶׁיַּגִּיעַ עֵת הַקָּרְבָּן מַכְרִיז הוּא אוֹ אֶחָד מֵאֲנָשָׁיו בִּרְשׁוּתוֹ וְאוֹמֵר עִמְדוּ כֹּהֲנִים לָעֲבוֹדָה וּלְוִיִּם לַדּוּכָן וְיִשְׂרָאֵל לַמַּעֲמָד וְכֵיוָן שֶׁיִּשְׁמַע קוֹלוֹ יָבוֹא כָּל אֶחָד לִמְלַאכְתּוֹ:","זֶה שֶׁעַל נְעִילַת שְׁעָרִים עַל פִּיו נוֹעֲלִין וְעַל פִּיו פּוֹתְחִין וְאֵין הַתּוֹקְעִין תּוֹקְעִין בְּכָל יוֹם לִפְתִיחַת הַשְּׁעָרִים אֶלָּא בִּרְשׁוּתוֹ. וּבְכָל יוֹם תּוֹקְעִין בַּמִּקְדָּשׁ שָׁלֹשׁ תְּקִיעוֹת לִפְתִיחַת הַשְּׁעָרִים תְּקִיעָה תְּרוּעָה וּתְקִיעָה:","זֶה שֶׁעַל הַשּׁוֹמְרִים הוּא אִישׁ הַר הַבַּיִת שֶׁמְּסַבֵּב עַל הַלְוִיִּם בְּכָל לַיְלָה וְכָל מִי שֶׁיָּשֵׁן עַל מִשְׁמָרוֹ מַלְקֶה אוֹתוֹ בְּמַקְלוֹ וְשׂוֹרֵף אֶת כְּסוּתוֹ:","זֶה שֶׁעַל הַמְשׁוֹרְרִים הוּא בּוֹרֵר בְּכָל יוֹם הַמְשׁוֹרְרִים שֶׁעוֹמְדִים עַל הַדּוּכָן לוֹמַר שִׁירָה בַּפֶּה. וְעַל פִּיו תּוֹקְעִין עַל הַקָּרְבָּנוֹת. אֵין פּוֹחֲתִין בַּמִּקְדָּשׁ מֵאַחַת וְעֶשְׂרִים תְּקִיעָה בְּכָל יוֹם. שָׁלֹשׁ לִפְתִיחַת שְׁעָרִים. וְתֵשַׁע לְתָמִיד שֶׁל שַׁחַר. וְתֵשַׁע לְתָמִיד שֶׁל בֵּין הָעַרְבַּיִם. וְיוֹם שֶׁיֵּשׁ בּוֹ קָרְבַּן מוּסָף מוֹסִיפִין תֵּשַׁע עַל קָרְבַּן מוּסָף. וְאִם חָל רֹאשׁ חֹדֶשׁ אוֹ יוֹם טוֹב לִהְיוֹת בְּשַׁבָּת אוֹ שֶׁחָל רֹאשׁ הַשָּׁנָה לִהְיוֹת בְּשַׁבָּת שֶׁיֵּשׁ שָׁם שְׁלֹשָׁה מוּסָפִין אֵין תּוֹקְעִין לְכָל מוּסָף וּמוּסָף בִּפְנֵי עַצְמוֹ אֶלָּא תּוֹקְעִין תֵּשַׁע בִּלְבַד לְכָל הַמּוּסָפִין:","בְּעֶרֶב שַׁבָּת מוֹסִיפִין שֵׁשׁ. שָׁלֹשׁ לְהַבְטִיל אֶת הָעָם מִן הַמְּלָאכָה וְשָׁלֹשׁ לְהַבְדִּיל בֵּין קֹדֶשׁ לְחל. וּבָרֶגֶל מוֹסִיפִין שָׁלֹשׁ לִפְתִיחַת שַׁעַר הַתַּחְתּוֹן וְהוּא שַׁעַר עֶזְרַת נָשִׁים וְשָׁלֹשׁ לִפְתִיחַת שַׁעַר הָעֶלְיוֹן הוּא שַׁעַר נִקָּנוֹר וְלָמָּה נִקְרָא שַׁעַר עֶלְיוֹן לְפִי שֶׁהוּא לְמַעְלָה מֵעֶזְרַת נָשִׁים. וְכֵן תּוֹקְעִין שָׁלֹשׁ לְמִלּוּי הַמַּיִם שֶׁמְּנַסְּכִין בֶּחָג וְאֵין תּוֹקְעִים לְמִלּוּי הַמַּיִם בְּשַׁבָּת. וְתוֹקְעִין שָׁלֹשׁ עַל גַּבֵּי הַמִּזְבֵּחַ בְּשָׁעָה שֶׁמְּנַסְּכִין הַמַּיִם. וְכָל הַתּוֹקְעִים שֶׁתּוֹקְעִים עַל הַקָּרְבָּנוֹת מִתַּחַת יַד זֶה שֶׁעַל הַמְשׁוֹרְרִים וּבִרְשׁוּתוֹ. וְכָל אֵלּוּ הַתְּקִיעוֹת בַּחֲצוֹצְרוֹת הֵן:","זֶה שֶׁעַל הַצִּלְצָל הוּא הַמַּעֲמִיד כָּל הַמְשׁוֹרְרִים עַל פִּי כְּלֵי שִׁיר שֶׁסּוֹעֲדִין עִם הַלְוִיִּם כְּמוֹ שֶׁבֵּאַרְנוּ:","זֶה שֶׁעַל הַפְּיָסוֹת הוּא מֵפִיס בֵּין הַכֹּהֲנִים בְּכָל יוֹם עַד שֶׁיִּהְיֶה כָּל אִישׁ וְאִישׁ עוֹשֶׂה מְלַאכְתּוֹ שֶׁזָּכָה בָּהּ בַּפַּיִס. וְאַרְבַּע פְּעָמִים הָיוּ מְפִיסִין בְּכָל יוֹם וּבְהִלְכוֹת תְּמִידִין אֲבָאֵר כֵּיצַד הָיוּ מְפִיסִין:","הַמְמֻנֶּה שֶׁעַל הַקִּנִּים הוּא שֶׁפּוֹסְקִין עִמּוֹ שֶׁיִּמְכֹּר הַקִּנִּים לַקָּרְבָּנוֹת כָּךְ וְכָךְ בַּסֶּלַע וְכָל מִי שֶׁהוּא חַיָּב תּוֹרִים אוֹ שְׁנֵי בְּנֵי יוֹנָה יָבִיא דְּמֵיהֶם לַמִּקְדָּשׁ. וְזֶה הַמְמֻנֶּה נוֹתֵן הַקִּנִּים לְבַעֲלֵי הַקָּרְבָּנוֹת וְעוֹשֶׂה חֶשְׁבּוֹן עִם הַגִּזְבָּרִין וְנוֹתְנִין לוֹ. מִשְּׁלֹשִׁים יוֹם לִשְׁלֹשִׁים יוֹם פּוֹסְקִין עִמּוֹ הַשַּׁעַר. וְאִם הוּזְלוּ הַקִּנִּים מַסְפִּיק כְּשַׁעַר הַזּוֹל וְאִם הוּקְרוּ מַסְפִּיק כְּמוֹ שֶׁפָּסְקוּ עִמּוֹ שֶׁיַּד הֶקְדֵּשׁ עַל הָעֶלְיוֹנָה. וְכֵן קֵן שֶׁנִּמְצָא פָּסוּל אוֹ שֶׁנִּפְסַל קֹדֶם שֶׁיִּקָּרֵב נוֹתֵן אַחֵר תַּחְתָּיו:","זֶה שֶׁעַל הַחוֹתָמוֹת הוּא שֶׁמְּקַבֵּל דְּמֵי הַנְּסָכִים מִמְּחֻיְּבֵי נְסָכִים וְנוֹתֵן לָהֶן חוֹתָמוֹת. וְזֶה שֶׁעַל הַנְּסָכִים הוּא שֶׁמּוֹכֵר הַנְּסָכִים:","כֵּיצַד. אַרְבַּע חוֹתָמוֹת הָיוּ בַּמִּקְדָּשׁ. הָאֶחָד כָּתוּב עָלָיו עֵגֶל. וְהַשֵּׁנִי כָּתוּב עָלָיו זָכָר. וְהַשְּׁלִישִׁי כָּתוּב עָלָיו גְּדִי. וְהָרְבִיעִי כָּתוּב עָלָיו חוֹטֵא:","כָּל מִי שֶׁיָּבִיא קָרְבְּנוֹתָיו לַמִּקְדָּשׁ נוֹתֵן דְּמֵי הַנְּסָכִים לְזֶה הַמְמֻנֶּה עַל הַחוֹתָמוֹת וְנוֹתֵן לוֹ חוֹתָמוֹת כְּמִנְיַן הַקָּרְבָּנוֹת שֶׁלּוֹ. וְאִם הָיָה מְצֹרָע עָשִׁיר נוֹתֵן לוֹ חוֹתָם אֶחָד שֶׁכָּתוּב עָלָיו חוֹטֵא וְהַלָּה הוֹלֵךְ בַּחוֹתָמוֹת שֶׁבְּיָדוֹ לְזֶה הַמְמֻנֶּה עַל הַנְּסָכִים וְנוֹתֵן לוֹ נְסָכִים כְּמִנְיַן הַחוֹתָמוֹת וּכְמוֹ שֶׁכָּתוּב בָּהֶן וְלָעֶרֶב בָּאִים זֶה אֵצֶל זֶה מוֹצִיא אֶת הַחוֹתָמוֹת וּמְקַבֵּל כְּנֶגְדָּן מָעוֹת אִם הוֹתִירוּ הַמָּעוֹת הוֹתִירוּ לַהֶקְדֵּשׁ וְאִם פָּחֲתוּ הַמָּעוֹת יְשַׁלֵּם זֶה שֶׁעַל הַחוֹתָמוֹת מִבֵּיתוֹ. מִי שֶׁאָבַד חוֹתָמוֹ מַמְתִּינִין לוֹ עַד הָעֶרֶב אִם מָצְאוּ בַּמָּעוֹת יֶתֶר כְּדֵי חוֹתָם שֶׁטּוֹעֵן נוֹתְנִין לוֹ וְאִם לָאו אֵין נוֹתְנִין לוֹ. וְשֵׁם כָּל הַיּוֹם כָּתוּב עַל הַחוֹתָם מִפְּנֵי הָרַמָּאִים שֶׁלֹּא יַשְׁהֶא הַחוֹתָם אֶצְלוֹ עַד שֶׁיּוּקְרוּ הַנְּסָכִים:","מִשְּׁלֹשִׁים יוֹם לִשְׁלֹשִׁים יוֹם פּוֹסְקִין שַׁעַר הַיַּיִן וְהַסּלֶת עִם הַמְמֻנֶּה עַל הַנְּסָכִים. אִם הוּקְרוּ נְסָכִים מְסַפֵּק לָהֶן כְּמוֹ שֶׁפָּסְקוּ עִמּוֹ. וְאִם הוּזְלוּ מְסַפֵּק לָהֶן כְּשַׁעַר הַזּוֹל. וְהַשָּׂכָר שֶׁמִּשְׂתַּכֵּר הַהֶקְדֵּשׁ בִּשְׁעָרִים אֵלּוּ הוּא הַנִּקְרָא מוֹתַר נְסָכִים וְלוֹקְחִין בּוֹ עוֹלוֹת לְקַיִץ הַמִּזְבֵּחַ. וְאֵין מְקַיְּצִין אֶת הַמִּזְבֵּחַ בְּעוֹלוֹת עוֹף שֶׁאֵין בְּקָרְבְּנוֹת הַצִּבּוּר עוֹף:","הַכֹּהֲנִים מִפְּנֵי שֶׁהֵן עוֹמְדִין עַל הָרִצְפָּה תָּמִיד וְאוֹכְלִין בָּשָׂר הַרְבֵּה וְאֵין עֲלֵיהֶן בְּגָדִים בִּשְׁעַת הָעֲבוֹדָה אֶלָּא חָלוּק אֶחָד הֵם חוֹלִין בִּמְעֵיהֶן. לְפִיכָךְ מַעֲמִידִין מְמֻנֶּה אֶחָד שֶׁיִּהְיֶה מְבַקֵּר אוֹתָן וּמְרַפֵּא כָּל תַּחְלוּאֵיהֶן וְעוֹסֵק בָּהֶן תָּמִיד הוּא וַאֲנָשָׁיו שֶׁתַּחַת יָדוֹ:","וְכֵן מְמַנִּין אַחֵר לִהְיוֹת חוֹפֵר בּוֹרוֹת וְשִׁיחִין וּמְתַקֵּן הַבּוֹרוֹת שֶׁל רַבִּים כְּדֵי שֶׁיִּהְיוּ הַמַּיִם מְצוּיִין בִּירוּשָׁלָיִם לְכָל אֶחָד מִיּוֹשְׁבֶיהָ וּלְכָל עוֹלֵי הָרְגָלִים. וְאֶחָד מְמֻנֶּה עַל כָּל אֻמָּנֵי לֶחֶם הַפָּנִים וְהוּא מְתַקֵּן כָּל מְלַאכְתּוֹ. וְאֶחָד מְמֻנֶּה עַל כָּל אֻמָּנֵי הַקְּטֹרֶת וְהוּא מְתַקֵּן מְלַאכְתָּהּ:","זֶה שֶׁעַל הַפָּרֹכֶת מְמֻנֶּה עַל כָּל אוֹרְגֵי הַפָּרֹכוֹת וְהַרוֹקְמִין בָּהֶן שֶׁיִּהְיוּ מוּכָנוֹת לַהֵיכָל וְלַשְּׁעָרִים. וּשְׁתֵּי פָּרֹכוֹת הָיוּ עוֹשִׂין בְּכָל שָׁנָה לְהַבְדִּיל בֵּין הַקֹּדֶשׁ לְקֹדֶשׁ הַקֳדָשִׁים. וְחוּטֵי הַפָּרֹכֶת כְּפוּלִין שִׁשָּׁה שִׁשָּׁה. וְאַרְבָּעָה מִינִין הָיוּ בָּהּ שֵׁשׁ וּתְכֵלֶת וְאַרְגָּמָן וְתוֹלַעַת שָׁנִי. וְכָל אֶחָד מֵהֶן כָּפוּל שִׁשָּׁה הֲרֵי אַרְבָּעָה וְעֶשְׂרִים חוּטִין. וְטֶפַח הָיָה עָבְיָהּ וְעַל שְׁנַיִם וְשִׁבְעִים נִירִין הָיְתָה נֶאֱרֶגֶת אָרְכָּהּ אַרְבָּעִים אַמָּה וְרָחְבָּהּ עֶשְׂרִים אַמָּה:","וּשְׁלֹשׁ עֶשְׂרֵה פָּרֹכוֹת הָיוּ בְּמִקְדַּשׁ שֵׁנִי שֶׁבַע עַל שִׁבְעָה שַׁעֲרֵי הָעֲזָרָה וְאַחַת עַל פֶּתַח הָאוּלָם וְאַחַת עַל פֶּתַח הַהֵיכָל וּשְׁתַּיִם לַדְּבִיר בֵּינוֹ וּבֵין הַקֹּדֶשׁ וּשְׁתַּיִם כְּנֶגְדָּן בַּעֲלִיָּה:","פָּרֹכֶת שֶׁנִּטְמֵאת בִּוְלַד הַטֻמְאָה מַטְבִּילִין אוֹתָהּ בִּפְנִים וּמַכְנִיסִין אוֹתָהּ מִיָּד לְפִי שֶׁאֵינָהּ צְרִיכָה הַעֲרֵב שֶׁמֶשׁ. וְשֶׁנִּטְמֵאת בְּאַב הַטֻמְאָה מַטְבִּילִין אוֹתָהּ מִבַּחוּץ וְשׁוֹטְחִין אוֹתָהּ בַּחֵיל מִפְּנֵי שֶׁהִיא צְרִיכָה הַעֲרֵב שֶׁמֶשׁ. וְאִם הָיְתָה חֲדָשָׁה שׁוֹטְחִין אוֹתָהּ עַל גַּב הָאִצְטַבָּא כְּדֵי שֶׁיִּרְאֶה הָעָם אֶת מְלַאכְתָּהּ שֶׁהִיא נָאָה:","וְכָל הַכֵּלִים שֶׁהָיוּ בַּמִּקְדָּשׁ הָיוּ לָהֶם שְׁנִיִּים וּשְׁלִישִׁים שֶׁאִם יִטַּמְּאוּ הָרִאשׁוֹנִים יָבִיאוּ הַשְּׁנִיִּים תַּחְתֵּיהֶם:","זֶה הַמְּמֻנֶּה עַל מַעֲשֶׂה בִּגְדֵי כְּהֻנָּה עוֹסֵק בַּהֲכָנַת בִּגְדֵי כֹּהֲנִים הֶדְיוֹטִים וּבִגְדֵי כֹּהֵן גָּדוֹל וּבַאֲרִיגָתָן וּמִתַּחַת יָדוֹ נַעֲשָׂה הַכּל. וְלִשְׁכָּה הָיְתָה לוֹ בַּמִּקְדָּשׁ:"],"Mishneh Torah, Vows 3":["אַרְבָּעָה דְּבָרִים יֵשׁ בֵּין נְדָרִים לִשְׁבוּעַת בִּטּוּי. שֶׁבִּשְׁבוּעַת בִּטּוּי אֵין שְׁבוּעָה חָלָה עַל שְׁבוּעָה. וּבִנְדָרִים יָחוּל נֵדֶר עַל נֵדֶר. הַמַּתְפִּיס בִּשְׁבוּעָה פָּטוּר וּבִנְדָרִים חַיָּב. אֵין שְׁבוּעַת בִּטּוּי חָלָה אֶלָּא עַל דִּבְרֵי הָרְשׁוּת. וּנְדָרִים חָלוֹת עַל דִּבְרֵי מִצְוָה כְּדִבְרֵי הָרְשׁוּת. שְׁבוּעַת בִּטּוּי חָלָה עַל דָּבָר שֶׁיֵּשׁ בּוֹ מַמָּשׁ וְעַל דָּבָר שֶׁאֵין בּוֹ מַמָּשׁ. וּנְדָרִים אֵינָן חָלִין אֶלָּא עַל דָּבָר שֶׁיֵּשׁ בּוֹ מַמָּשׁ:","כֵּיצַד יָחוּל נֵדֶר עַל נֵדֶר. הָאוֹמֵר הֲרֵי עָלַי קָרְבָּן אִם אָכַלְתִּי כִּכָּר זוֹ. הֲרֵי עָלַי קָרְבָּן אִם אֹכָלֶנָּה וַאֲכָלָהּ חַיָּב עַל כָּל אַחַת וְאַחַת. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","כֵּיצַד הַמַּתְפִּיס בִּנְדָרִים חַיָּב. שָׁמַע חֲבֵרוֹ שֶׁנָּדַר וְאָמַר וַאֲנִי כְּמוֹתְךָ בְּתוֹךְ כְּדֵי דִּבּוּר הֲרֵי זֶה אָסוּר בְּמַה שֶּׁנֶּאֱסַר בּוֹ חֲבֵרוֹ. שָׁמַע הַשְּׁלִישִׁי זֶה שֶׁאָמַר וַאֲנִי וְאָמַר וַאֲנִי אֲפִלּוּ הָיוּ מֵאָה וְכָל אֶחָד מֵהֶן אוֹמֵר וַאֲנִי בְּתוֹךְ כְּדֵי דִּבּוּרוֹ שֶׁל חֲבֵרוֹ הֲרֵי כֻּלָּן אֲסוּרִין:","וְכֵן הָאוֹמֵר הַבָּשָׂר הַזֶּה עָלַי אָסוּר וְחָזַר וְאָמַר אֲפִלּוּ אַחַר כַּמָּה יָמִים וְהַפַּת הַזֹּאת כַּבָּשָׂר הַזֶּה הֲרֵי הַפַּת נִתְפְּשָׂה וְנֶאֶסְרָה. חָזַר וְאָמַר וּדְבַשׁ זֶה כַּפַּת הַזֹּאת וְיַיִן זֶה כִּדְבַשׁ זֶה אֲפִלּוּ הֵן מֵאָה כֻּלָּן אֲסוּרִין:","הֲרֵי שֶׁמֵּת אָבִיו אוֹ רַבּוֹ הַיּוֹם וְנָדַר שֶׁיָּצוּם אוֹתוֹ הַיּוֹם וְצָם. וּלְאַחַר שָׁנִים אָמַר הֲרֵי יוֹם זֶה עָלָיו כְּיוֹם שֶׁמֵּת בּוֹ אָבִיו אוֹ רַבּוֹ הֲרֵי זֶה אָסוּר לֶאֱכל בּוֹ כְּלוּם שֶׁהֲרֵי הִתְפִּיס יוֹם זֶה וַאֲסָרוֹ כַּיּוֹם הָאָסוּר לוֹ. וְכֵן כָּל כַּיּוֹצֵא בְּאֵלּוּ:","כֵּיצַד חָלִים הַנְּדָרִים עַל דִּבְרֵי מִצְוָה כְּדִבְרֵי הָרְשׁוּת. הָאוֹמֵר הֲרֵי הַמַּצָּה בְּלֵילֵי הַפֶּסַח אֲסוּרָה עָלָיו. הֲרֵי יְשִׁיבַת הַסֻּכָּה בֶּחָג הַסֻּכּוֹת אֲסוּרָה עָלָיו וַהֲרֵי הַתְּפִלִּין אֲסוּרוֹת בִּנְטִילָה עָלָיו הֲרֵי אֵלּוּ אֲסוּרִין עָלָיו. וְאִם אָכַל אוֹ יָשַׁב אוֹ נָטַל לוֹקֶה. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה. וְאֵין צָרִיךְ לוֹמַר בְּמִי שֶׁאָמַר הֲרֵי עָלַי קָרְבָּן אִם אֹכַל מַצָּה בְּלֵילֵי הַפֶּסַח שֶׁהוּא חַיָּב בְּקָרְבָּן. וְכֵן כָּל כַּיּוֹצֵא בָּזֶה:","וּמִפְּנֵי מָה נְדָרִים חָלִים עַל דִּבְרֵי מִצְוָה וּשְׁבוּעוֹת אֵין חָלוֹת עַל דִּבְרֵי מִצְוָה. שֶׁהַנִּשְׁבָּע אוֹסֵר עַצְמוֹ עַל דָּבָר שֶׁנִּשְׁבַּע עָלָיו. וְהַנּוֹדֵר אוֹסֵר הַדָּבָר הַנָּדוּר עַל עַצְמוֹ. נִמְצָא הַנִּשְׁבָּע לְבַטֵּל מִצְוָה אוֹסֵר עַצְמוֹ וּכְבָר עַצְמוֹ מֻשְׁבָּע מֵהַר סִינַי וְאֵין שְׁבוּעָה חָלָה עַל שְׁבוּעָה. וְהָאוֹסֵר דָּבָר זֶה בְּנֵדֶר זֶה הַדָּבָר הוּא שֶׁנֶּאֱסַר וְאוֹתוֹ הַדָּבָר אֵינוֹ מֻשְׁבָּע מֵהַר סִינַי:","כְּשֶׁאַתָּה מִתְבּוֹנֵן בַּכָּתוּב תִּמְצָא שֶׁהַדְּבָרִים מַרְאִין כֵּן כְּמוֹ שֶׁקִּבְּלוּ חֲכָמִים מִפִּי הַשְּׁמוּעָה. שֶׁהֲרֵי אוֹמֵר בִּשְׁבוּעַת בִּטּוּי (ויקרא ה ד) \"לְהָרַע אוֹ לְהֵיטִיב\" בְּדִבְרֵי הָרְשׁוּת כְּמוֹ שֶׁבֵּאַרְנוּ. שֶׁיֹּאכַל וְיִשְׁתֶּה הַיּוֹם אוֹ שֶׁיָּצוּם וְכַיּוֹצֵא בָּהֶן. וּבִנְדָרִים הוּא אוֹמֵר (במדבר ל ג) \"כְּכָל הַיֹּצֵא מִפִּיו יַעֲשֶׂה\" וְלֹא חִלֵּק בֵּין דִּבְרֵי מִצְוָה לְדִבְרֵי הָרְשׁוּת:","הַנּוֹדֵר שֶׁיָּצוּם בְּשַׁבָּת אוֹ בְּיוֹם טוֹב חַיָּב לָצוּם. שֶׁהַנְּדָרִים חָלִים עַל דִּבְרֵי מִצְוָה כְּמוֹ שֶׁבֵּאַרְנוּ. וְכֵן הַנּוֹדֵר שֶׁיָּצוּם יוֹם רִאשׁוֹן אוֹ יוֹם שְׁלִישִׁי כָּל יָמָיו וּפָגַע בּוֹ יוֹם זֶה וַהֲרֵי הוּא יוֹם טוֹב אוֹ עֶרֶב יוֹם הַכִּפּוּרִים הֲרֵי זֶה חַיָּב לָצוּם וְאֵין צָרִיךְ לוֹמַר רֹאשׁ חֹדֶשׁ. פָּגַע בּוֹ חֲנֻכָּה וּפוּרִים יִדָּחֶה נִדְרוֹ מִפְּנֵי הַיָּמִים הָאֵלּוּ הוֹאִיל וְאִסּוּר הַצּוֹם בָּהֶם מִדִּבְרֵי סוֹפְרִים הֲרֵי הֵן צְרִיכִין חִזּוּק וְיִדָּחֶה נִדְרוֹ מִפְּנֵי גְּזֵרַת חֲכָמִים:","כֵּיצַד אֵין הַנְּדָרִים חָלִים אֶלָּא עַל דָּבָר שֶׁיֵּשׁ בּוֹ מַמָּשׁ. הָאוֹמֵר דִּבּוּרִי עָלֶיךָ קָרְבָּן אֵינוֹ אָסוּר מִלְּדַבֵּר עִמּוֹ שֶׁהַדִּבּוּר אֵין בּוֹ מַמָּשׁ. וְכֵן אִם אָמַר לוֹ דִּבּוּרִי אָסוּר עָלֶיךָ אֵין זֶה כְּאוֹמֵר פֵּרוֹתַי אֲסוּרִין עָלֶיךָ אוֹ פֵּרוֹתַי קָרְבָּן עָלֶיךָ שֶׁהֵן אֲסוּרִין עָלָיו. לְפִיכָךְ הָאוֹמֵר לַחֲבֵרוֹ קָרְבָּן שֶׁאֵינִי מְדַבֵּר עִמְּךָ אוֹ שֶׁאֵינִי עוֹשֶׂה עִמְּךָ אוֹ שֶׁאֵינִי מְהַלֵּךְ עִמְּךָ. אוֹ שֶׁאָמַר קָרְבָּן שֶׁאֵינִי יָשֵׁן שֶׁאֵינִי מְדַבֵּר שֶׁאֵינִי מְהַלֵּךְ. אוֹ שֶׁאָמַר לְאִשְׁתּוֹ קָרְבָּן שֶׁאֵינִי מְשַׁמְּשֵׁךְ אֵין הַנֵּדֶר חָל בְּכָל אֵלּוּ. וַהֲרֵי זֶה כְּאוֹמֵר דִּבּוּרִי וְהִלּוּכִי וַעֲשִׂיָּתִי וְשִׁמּוּשִׁי קָרְבָּן שֶׁהֵן דְּבָרִים שֶׁאֵין בָּהֶן מַמָּשׁ:","אֲבָל הָאוֹמֵר יֵאָסֵר פִּי לְדִבּוּרוֹ וְיָדַי לְמַעֲשֵׂיהֶן וְרַגְלַי לְהִלּוּכָן וְעֵינַי לִשְׁנָתָן הֲרֵי הַנֵּדֶר חָל עֲלֵיהֶן. לְפִיכָךְ הָאוֹמֵר לַחֲבֵרוֹ קָרְבָּן פִּי מִלְּדַבֵּר עִמְּךָ וְיָדַי מִלַּעֲשׂוֹת עִמְּךָ וְרַגְלַי מִלְּהַלֵּךְ עִמְּךָ הֲרֵי זֶה אָסוּר. וְכֵן הָאוֹמֵר הֲרֵי עָלַי קָרְבָּן אִם אֲדַבֵּר עִם פְּלוֹנִי אוֹ אִם לֹא אֲדַבֵּר עִמּוֹ וְעָבַר עַל דְּבָרוֹ חַיָּב בְּקָרְבָּן. וְכֵן אִם נָדַר דִּבַּרְתִּי וְלֹא דִּבַּרְתִּי וְכַיּוֹצֵא בָּהֶן שֶׁאֵין אֵלּוּ נִדְרֵי אִסָּר שֶׁאָנוּ מְבָאֲרִין מִשְׁפְּטֵיהֶם אֶלָּא נִדְרֵי הֶקְדֵּשׁ:","הַנּוֹדֵר בִּדְבָרִים שֶׁאֵין בָּהֶם מַמָּשׁ וַאֲסָרָן אַף עַל פִּי שֶׁאֵין הַנֵּדֶר חָל עֲלֵיהֶם אֵין מוֹרִים לוֹ שֶׁיִּנְהֹג בָּהֶן הֶתֵּר הוֹאִיל וְאָסַר עַצְמוֹ בָּהֶן וּבְדַעְתּוֹ שֶׁהַנֵּדֶר חָל עֲלֵיהֶן. אֶלָּא פּוֹתְחִין לוֹ פֶּתַח מִמָּקוֹם אַחֵר וּמַתִּירִין לוֹ נִדְרוֹ אַף עַל פִּי שֶׁלֹּא נֶאֱסַר כְּדֵי שֶׁלֹּא יִנְהֲגוּ קַלּוּת רֹאשׁ בִּנְדָרִים:"]} as Record<string, string[]>;
